window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["经济法"] = {"gerenxinxibaohufa":[{"i":1,"n":"第一条","txt":"为了保护个人信息权益，规范个人信息处理活动，促进个人信息合理利用，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"自然人的个人信息受法律保护，任何组织、个人不得侵害自然人的个人信息权益。"},{"i":3,"n":"第三条","txt":"在中华人民共和国境内处理自然人个人信息的活动，适用本法。"},{"i":4,"n":"第四条","txt":"个人信息是以电子或者其他方式记录的与已识别或者可识别的自然人有关的各种信息，不包括匿名化处理后的信息。"},{"i":5,"n":"第五条","txt":"处理个人信息应当遵循合法、正当、必要和诚信原则，不得通过误导、欺诈、胁迫等方式处理个人信息。"},{"i":6,"n":"第六条","txt":"处理个人信息应当具有明确、合理的目的，并应当与处理目的直接相关，采取对个人权益影响最小的方式。"},{"i":7,"n":"第七条","txt":"处理个人信息应当遵循公开、透明原则，公开个人信息处理规则，明示处理的目的、方式和范围。"},{"i":8,"n":"第八条","txt":"处理个人信息应当保证个人信息的质量，避免因个人信息不准确、不完整对个人权益造成不利影响。"},{"i":9,"n":"第九条","txt":"个人信息处理者应当对其个人信息处理活动负责，并采取必要措施保障所处理的个人信息的安全。"},{"i":10,"n":"第十条","txt":"任何组织、个人不得非法收集、使用、加工、传输他人个人信息，不得非法买卖、提供或者公开他人个人信息；不得从事危害国家安全、公共利益的个人信息处理活动。"},{"i":11,"n":"第十一条","txt":"国家建立健全个人信息保护制度，预防和惩治侵害个人信息权益的行为，加强个人信息保护宣传教育，推动形成政府、企业、相关社会组织、公众共同参与个人信息保护的良好环境。"},{"i":12,"n":"第十二条","txt":"国家积极参与个人信息保护国际规则的制定，促进个人信息保护方面的国际交流与合作，推动与其他国家、地区、国际组织之间的个人信息保护规则、标准等互认。"},{"i":13,"n":"第十三条","txt":"符合下列情形之一的，个人信息处理者方可处理个人信息："},{"i":14,"n":"第十四条","txt":"基于个人同意处理个人信息的，该同意应当由个人在充分知情的前提下自愿、明确作出。法律、行政法规规定处理个人信息应当取得个人单独同意或者书面同意的，从其规定。"},{"i":15,"n":"第十五条","txt":"基于个人同意处理个人信息的，个人有权撤回其同意。个人信息处理者应当提供便捷的撤回同意的方式。"},{"i":16,"n":"第十六条","txt":"个人信息处理者不得以个人不同意处理其个人信息或者撤回同意为由，拒绝提供产品或者服务；处理个人信息属于提供产品或者服务所必需的除外。"},{"i":17,"n":"第十七条","txt":"个人信息处理者在处理个人信息前，应当以显著方式、清晰易懂的语言真实、准确、完整地向个人告知下列事项："},{"i":18,"n":"第十八条","txt":"个人信息处理者处理个人信息，有法律、行政法规规定应当保密或者不需要告知的情形的，可以不向个人告知前条第一款规定的事项。"},{"i":19,"n":"第十九条","txt":"除法律、行政法规另有规定外，个人信息的保存期限应当为实现处理目的所必要的最短时间。"},{"i":20,"n":"第二十条","txt":"两个以上的个人信息处理者共同决定个人信息的处理目的和处理方式的，应当约定各自的权利和义务。但是，该约定不影响个人向其中任何一个个人信息处理者要求行使本法规定的权利。"},{"i":21,"n":"第二十一条","txt":"个人信息处理者委托处理个人信息的，应当与受托人约定委托处理的目的、期限、处理方式、个人信息的种类、保护措施以及双方的权利和义务等，并对受托人的个人信息处理活动进行监督。"},{"i":22,"n":"第二十二条","txt":"个人信息处理者因合并、分立、解散、被宣告破产等原因需要转移个人信息的，应当向个人告知接收方的名称或者姓名和联系方式。接收方应当继续履行个人信息处理者的义务。接收方变更原先的处理目的、处理方式的，应当依照本法规定重新取得个人同意。"},{"i":23,"n":"第二十三条","txt":"个人信息处理者向其他个人信息处理者提供其处理的个人信息的，应当向个人告知接收方的名称或者姓名、联系方式、处理目的、处理方式和个人信息的种类，并取得个人的单独同意。接收方应当在上述处理目的、处理方式和个人信息的种类等范围内处理个人信息。接收方变更原先的处理目的、处理方式的，应当依照本法规定重新取得个人同意。"},{"i":24,"n":"第二十四条","txt":"个人信息处理者利用个人信息进行自动化决策，应当保证决策的透明度和结果公平、公正，不得对个人在交易价格等交易条件上实行不合理的差别待遇。"},{"i":25,"n":"第二十五条","txt":"个人信息处理者不得公开其处理的个人信息，取得个人单独同意的除外。"},{"i":26,"n":"第二十六条","txt":"在公共场所安装图像采集、个人身份识别设备，应当为维护公共安全所必需，遵守国家有关规定，并设置显著的提示标识。所收集的个人图像、身份识别信息只能用于维护公共安全的目的，不得用于其他目的；取得个人单独同意的除外。"},{"i":27,"n":"第二十七条","txt":"个人信息处理者可以在合理的范围内处理个人自行公开或者其他已经合法公开的个人信息；个人明确拒绝的除外。个人信息处理者处理已公开的个人信息，对个人权益有重大影响的，应当依照本法规定取得个人同意。"},{"i":28,"n":"第二十八条","txt":"敏感个人信息是一旦泄露或者非法使用，容易导致自然人的人格尊严受到侵害或者人身、财产安全受到危害的个人信息，包括生物识别、宗教信仰、特定身份、医疗健康、金融账户、行踪轨迹等信息，以及不满十四周岁未成年人的个人信息。"},{"i":29,"n":"第二十九条","txt":"处理敏感个人信息应当取得个人的单独同意；法律、行政法规规定处理敏感个人信息应当取得书面同意的，从其规定。"},{"i":30,"n":"第三十条","txt":"个人信息处理者处理敏感个人信息的，除本法第十七条第一款规定的事项外，还应当向个人告知处理敏感个人信息的必要性以及对个人权益的影响；依照本法规定可以不向个人告知的除外。"},{"i":31,"n":"第三十一条","txt":"个人信息处理者处理不满十四周岁未成年人个人信息的，应当取得未成年人的父母或者其他监护人的同意。"},{"i":32,"n":"第三十二条","txt":"法律、行政法规对处理敏感个人信息规定应当取得相关行政许可或者作出其他限制的，从其规定。"},{"i":33,"n":"第三十三条","txt":"国家机关处理个人信息的活动，适用本法；本节有特别规定的，适用本节规定。"},{"i":34,"n":"第三十四条","txt":"国家机关为履行法定职责处理个人信息，应当依照法律、行政法规规定的权限、程序进行，不得超出履行法定职责所必需的范围和限度。"},{"i":35,"n":"第三十五条","txt":"国家机关为履行法定职责处理个人信息，应当依照本法规定履行告知义务；有本法第十八条第一款规定的情形，或者告知将妨碍国家机关履行法定职责的除外。"},{"i":36,"n":"第三十六条","txt":"国家机关处理的个人信息应当在中华人民共和国境内存储；确需向境外提供的，应当进行安全评估。安全评估可以要求有关部门提供支持与协助。"},{"i":37,"n":"第三十七条","txt":"法律、法规授权的具有管理公共事务职能的组织为履行法定职责处理个人信息，适用本法关于国家机关处理个人信息的规定。"},{"i":38,"n":"第三十八条","txt":"个人信息处理者因业务等需要，确需向中华人民共和国境外提供个人信息的，应当具备下列条件之一："},{"i":39,"n":"第三十九条","txt":"个人信息处理者向中华人民共和国境外提供个人信息的，应当向个人告知境外接收方的名称或者姓名、联系方式、处理目的、处理方式、个人信息的种类以及个人向境外接收方行使本法规定权利的方式和程序等事项，并取得个人的单独同意。"},{"i":40,"n":"第四十条","txt":"关键信息基础设施运营者和处理个人信息达到国家网信部门规定数量的个人信息处理者，应当将在中华人民共和国境内收集和产生的个人信息存储在境内。确需向境外提供的，应当通过国家网信部门组织的安全评估；法律、行政法规和国家网信部门规定可以不进行安全评估的，从其规定。"},{"i":41,"n":"第四十一条","txt":"中华人民共和国主管机关根据有关法律和中华人民共和国缔结或者参加的国际条约、协定，或者按照平等互惠原则，处理外国司法或者执法机构关于提供存储于境内个人信息的请求。非经中华人民共和国主管机关批准，个人信息处理者不得向外国司法或者执法机构提供存储于中华人民共和国境内的个人信息。"},{"i":42,"n":"第四十二条","txt":"境外的组织、个人从事侵害中华人民共和国公民的个人信息权益，或者危害中华人民共和国国家安全、公共利益的个人信息处理活动的，国家网信部门可以将其列入限制或者禁止个人信息提供清单，予以公告，并采取限制或者禁止向其提供个人信息等措施。"},{"i":43,"n":"第四十三条","txt":"任何国家或者地区在个人信息保护方面对中华人民共和国采取歧视性的禁止、限制或者其他类似措施的，中华人民共和国可以根据实际情况对该国家或者地区对等采取措施。"},{"i":44,"n":"第四十四条","txt":"个人对其个人信息的处理享有知情权、决定权，有权限制或者拒绝他人对其个人信息进行处理；法律、行政法规另有规定的除外。"},{"i":45,"n":"第四十五条","txt":"个人有权向个人信息处理者查阅、复制其个人信息；有本法第十八条第一款、第三十五条规定情形的除外。"},{"i":46,"n":"第四十六条","txt":"个人发现其个人信息不准确或者不完整的，有权请求个人信息处理者更正、补充。"},{"i":47,"n":"第四十七条","txt":"有下列情形之一的，个人信息处理者应当主动删除个人信息；个人信息处理者未删除的，个人有权请求删除："},{"i":48,"n":"第四十八条","txt":"个人有权要求个人信息处理者对其个人信息处理规则进行解释说明。"},{"i":49,"n":"第四十九条","txt":"自然人死亡的，其近亲属为了自身的合法、正当利益，可以对死者的相关个人信息行使本章规定的查阅、复制、更正、删除等权利；死者生前另有安排的除外。"},{"i":50,"n":"第五十条","txt":"个人信息处理者应当建立便捷的个人行使权利的申请受理和处理机制。拒绝个人行使权利的请求的，应当说明理由。"},{"i":51,"n":"第五十一条","txt":"个人信息处理者应当根据个人信息的处理目的、处理方式、个人信息的种类以及对个人权益的影响、可能存在的安全风险等，采取下列措施确保个人信息处理活动符合法律、行政法规的规定，并防止未经授权的访问以及个人信息泄露、篡改、丢失："},{"i":52,"n":"第五十二条","txt":"处理个人信息达到国家网信部门规定数量的个人信息处理者应当指定个人信息保护负责人，负责对个人信息处理活动以及采取的保护措施等进行监督。"},{"i":53,"n":"第五十三条","txt":"本法第三条第二款规定的中华人民共和国境外的个人信息处理者，应当在中华人民共和国境内设立专门机构或者指定代表，负责处理个人信息保护相关事务，并将有关机构的名称或者代表的姓名、联系方式等报送履行个人信息保护职责的部门。"},{"i":54,"n":"第五十四条","txt":"个人信息处理者应当定期对其处理个人信息遵守法律、行政法规的情况进行合规审计。"},{"i":55,"n":"第五十五条","txt":"有下列情形之一的，个人信息处理者应当事前进行个人信息保护影响评估，并对处理情况进行记录："},{"i":56,"n":"第五十六条","txt":"个人信息保护影响评估应当包括下列内容："},{"i":57,"n":"第五十七条","txt":"发生或者可能发生个人信息泄露、篡改、丢失的，个人信息处理者应当立即采取补救措施，并通知履行个人信息保护职责的部门和个人。通知应当包括下列事项："},{"i":58,"n":"第五十八条","txt":"提供重要互联网平台服务、用户数量巨大、业务类型复杂的个人信息处理者，应当履行下列义务："},{"i":59,"n":"第五十九条","txt":"接受委托处理个人信息的受托人，应当依照本法和有关法律、行政法规的规定，采取必要措施保障所处理的个人信息的安全，并协助个人信息处理者履行本法规定的义务。"},{"i":60,"n":"第六十条","txt":"国家网信部门负责统筹协调个人信息保护工作和相关监督管理工作。国务院有关部门依照本法和有关法律、行政法规的规定，在各自职责范围内负责个人信息保护和监督管理工作。"},{"i":61,"n":"第六十一条","txt":"履行个人信息保护职责的部门履行下列个人信息保护职责："},{"i":62,"n":"第六十二条","txt":"国家网信部门统筹协调有关部门依据本法推进下列个人信息保护工作："},{"i":63,"n":"第六十三条","txt":"履行个人信息保护职责的部门履行个人信息保护职责，可以采取下列措施："},{"i":64,"n":"第六十四条","txt":"履行个人信息保护职责的部门在履行职责中，发现个人信息处理活动存在较大风险或者发生个人信息安全事件的，可以按照规定的权限和程序对该个人信息处理者的法定代表人或者主要负责人进行约谈，或者要求个人信息处理者委托专业机构对其个人信息处理活动进行合规审计。个人信息处理者应当按照要求采取措施，进行整改，消除隐患。"},{"i":65,"n":"第六十五条","txt":"任何组织、个人有权对违法个人信息处理活动向履行个人信息保护职责的部门进行投诉、举报。收到投诉、举报的部门应当依法及时处理，并将处理结果告知投诉、举报人。"},{"i":66,"n":"第六十六条","txt":"违反本法规定处理个人信息，或者处理个人信息未履行本法规定的个人信息保护义务的，由履行个人信息保护职责的部门责令改正，给予警告，没收违法所得，对违法处理个人信息的应用程序，责令暂停或者终止提供服务；拒不改正的，并处一百万元以下罚款；对直接负责的主管人员和其他直接责任人员处一万元以上十万元以下罚款。"},{"i":67,"n":"第六十七条","txt":"有本法规定的违法行为的，依照有关法律、行政法规的规定记入信用档案，并予以公示。"},{"i":68,"n":"第六十八条","txt":"国家机关不履行本法规定的个人信息保护义务的，由其上级机关或者履行个人信息保护职责的部门责令改正；对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":69,"n":"第六十九条","txt":"处理个人信息侵害个人信息权益造成损害，个人信息处理者不能证明自己没有过错的，应当承担损害赔偿等侵权责任。"},{"i":70,"n":"第七十条","txt":"个人信息处理者违反本法规定处理个人信息，侵害众多个人的权益的，人民检察院、法律规定的消费者组织和由国家网信部门确定的组织可以依法向人民法院提起诉讼。"},{"i":71,"n":"第七十一条","txt":"违反本法规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":72,"n":"第七十二条","txt":"自然人因个人或者家庭事务处理个人信息的，不适用本法。"},{"i":73,"n":"第七十三条","txt":"本法下列用语的含义："},{"i":74,"n":"第七十四条","txt":"本法自2021年11月1日起施行。"}],"gerensuodeshuifa":[{"i":1,"n":"第一条","txt":"在中国境内有住所，或者无住所而一个纳税年度内在中国境内居住累计满一百八十三天的个人，为居民个人。居民个人从中国境内和境外取得的所得，依照本法规定缴纳个人所得税。"},{"i":2,"n":"第二条","txt":"下列各项个人所得，应当缴纳个人所得税："},{"i":3,"n":"第三条","txt":"个人所得税的税率："},{"i":4,"n":"第四条","txt":"下列各项个人所得，免征个人所得税："},{"i":5,"n":"第五条","txt":"有下列情形之一的，可以减征个人所得税，具体幅度和期限，由省、自治区、直辖市人民政府规定，并报同级人民代表大会常务委员会备案："},{"i":6,"n":"第六条","txt":"应纳税所得额的计算："},{"i":7,"n":"第七条","txt":"居民个人从中国境外取得的所得，可以从其应纳税额中抵免已在境外缴纳的个人所得税税额，但抵免额不得超过该纳税人境外所得依照本法规定计算的应纳税额。"},{"i":8,"n":"第八条","txt":"有下列情形之一的，税务机关有权按照合理方法进行纳税调整："},{"i":9,"n":"第九条","txt":"个人所得税以所得人为纳税人，以支付所得的单位或者个人为扣缴义务人。"},{"i":10,"n":"第十条","txt":"有下列情形之一的，纳税人应当依法办理纳税申报："},{"i":11,"n":"第十一条","txt":"居民个人取得综合所得，按年计算个人所得税；有扣缴义务人的，由扣缴义务人按月或者按次预扣预缴税款；需要办理汇算清缴的，应当在取得所得的次年三月一日至六月三十日内办理汇算清缴。预扣预缴办法由国务院税务主管部门制定。"},{"i":12,"n":"第十二条","txt":"纳税人取得经营所得，按年计算个人所得税，由纳税人在月度或者季度终了后十五日内向税务机关报送纳税申报表，并预缴税款；在取得所得的次年三月三十一日前办理汇算清缴。"},{"i":13,"n":"第十三条","txt":"纳税人取得应税所得没有扣缴义务人的，应当在取得所得的次月十五日内向税务机关报送纳税申报表，并缴纳税款。"},{"i":14,"n":"第十四条","txt":"扣缴义务人每月或者每次预扣、代扣的税款，应当在次月十五日内缴入国库，并向税务机关报送扣缴个人所得税申报表。"},{"i":15,"n":"第十五条","txt":"公安、人民银行、金融监督管理等相关部门应当协助税务机关确认纳税人的身份、金融账户信息。教育、卫生、医疗保障、民政、人力资源社会保障、住房城乡建设、公安、人民银行、金融监督管理等相关部门应当向税务机关提供纳税人子女教育、继续教育、大病医疗、住房贷款利息、住房租金、赡养老人等专项附加扣除信息。"},{"i":16,"n":"第十六条","txt":"各项所得的计算，以人民币为单位。所得为人民币以外的货币的，按照人民币汇率中间价折合成人民币缴纳税款。"},{"i":17,"n":"第十七条","txt":"对扣缴义务人按照所扣缴的税款，付给百分之二的手续费。"},{"i":18,"n":"第十八条","txt":"对储蓄存款利息所得开征、减征、停征个人所得税及其具体办法，由国务院规定，并报全国人民代表大会常务委员会备案。"},{"i":19,"n":"第十九条","txt":"纳税人、扣缴义务人和税务机关及其工作人员违反本法规定的，依照《中华人民共和国税收征收管理法》和有关法律法规的规定追究法律责任。"},{"i":20,"n":"第二十条","txt":"个人所得税的征收管理，依照本法和《中华人民共和国税收征收管理法》的规定执行。"},{"i":21,"n":"第二十一条","txt":"国务院根据本法制定实施条例。"},{"i":22,"n":"第二十二条","txt":"本法自公布之日起施行。"}],"zhongguorenminyinhangfa":[{"i":1,"n":"第一条","txt":"为了确立中国人民银行的地位，明确其职责，保证国家货币政策的正确制定和执行，建立和完善中央银行宏观调控体系，维护金融稳定，制定本法。"},{"i":2,"n":"第二条","txt":"中国人民银行是中华人民共和国的中央银行。"},{"i":3,"n":"第三条","txt":"货币政策目标是保持货币币值的稳定，并以此促进经济增长。"},{"i":4,"n":"第四条","txt":"中国人民银行履行下列职责："},{"i":5,"n":"第五条","txt":"中国人民银行就年度货币供应量、利率、汇率和国务院规定的其他重要事项作出的决定，报国务院批准后执行。"},{"i":6,"n":"第六条","txt":"中国人民银行应当向全国人民代表大会常务委员会提出有关货币政策情况和金融业运行情况的工作报告。"},{"i":7,"n":"第七条","txt":"中国人民银行在国务院领导下依法独立执行货币政策，履行职责，开展业务，不受地方政府、各级政府部门、社会团体和个人的干涉。"},{"i":8,"n":"第八条","txt":"中国人民银行的全部资本由国家出资，属于国家所有。"},{"i":9,"n":"第九条","txt":"国务院建立金融监督管理协调机制，具体办法由国务院规定。"},{"i":10,"n":"第十条","txt":"中国人民银行设行长一人，副行长若干人。"},{"i":11,"n":"第十一条","txt":"中国人民银行实行行长负责制。行长领导中国人民银行的工作，副行长协助行长工作。"},{"i":12,"n":"第十二条","txt":"中国人民银行设立货币政策委员会。货币政策委员会的职责、组成和工作程序，由国务院规定，报全国人民代表大会常务委员会备案。"},{"i":13,"n":"第十三条","txt":"中国人民银行根据履行职责的需要设立分支机构，作为中国人民银行的派出机构。中国人民银行对分支机构实行统一领导和管理。"},{"i":14,"n":"第十四条","txt":"中国人民银行的行长、副行长及其他工作人员应当恪尽职守，不得滥用职权、徇私舞弊，不得在任何金融机构、企业、基金会兼职。"},{"i":15,"n":"第十五条","txt":"中国人民银行的行长、副行长及其他工作人员，应当依法保守国家秘密，并有责任为与履行其职责有关的金融机构及当事人保守秘密。"},{"i":16,"n":"第十六条","txt":"中华人民共和国的法定货币是人民币。以人民币支付中华人民共和国境内的一切公共的和私人的债务，任何单位和个人不得拒收。"},{"i":17,"n":"第十七条","txt":"人民币的单位为元，人民币辅币单位为角、分。"},{"i":18,"n":"第十八条","txt":"人民币由中国人民银行统一印制、发行。"},{"i":19,"n":"第十九条","txt":"禁止伪造、变造人民币。禁止出售、购买伪造、变造的人民币。禁止运输、持有、使用伪造、变造的人民币。禁止故意毁损人民币。禁止在宣传品、出版物或者其他商品上非法使用人民币图样。"},{"i":20,"n":"第二十条","txt":"任何单位和个人不得印制、发售代币票券，以代替人民币在市场上流通。"},{"i":21,"n":"第二十一条","txt":"残缺、污损的人民币，按照中国人民银行的规定兑换，并由中国人民银行负责收回、销毁。"},{"i":22,"n":"第二十二条","txt":"中国人民银行设立人民币发行库，在其分支机构设立分支库。分支库调拨人民币发行基金，应当按照上级库的调拨命令办理。任何单位和个人不得违反规定，动用发行基金。"},{"i":23,"n":"第二十三条","txt":"中国人民银行为执行货币政策，可以运用下列货币政策工具："},{"i":24,"n":"第二十四条","txt":"中国人民银行依照法律、行政法规的规定经理国库。"},{"i":25,"n":"第二十五条","txt":"中国人民银行可以代理国务院财政部门向各金融机构组织发行、兑付国债和其他政府债券。"},{"i":26,"n":"第二十六条","txt":"中国人民银行可以根据需要，为银行业金融机构开立账户，但不得对银行业金融机构的账户透支。"},{"i":27,"n":"第二十七条","txt":"中国人民银行应当组织或者协助组织银行业金融机构相互之间的清算系统，协调银行业金融机构相互之间的清算事项，提供清算服务。具体办法由中国人民银行制定。"},{"i":28,"n":"第二十八条","txt":"中国人民银行根据执行货币政策的需要，可以决定对商业银行贷款的数额、期限、利率和方式，但贷款的期限不得超过一年。"},{"i":29,"n":"第二十九条","txt":"中国人民银行不得对政府财政透支，不得直接认购、包销国债和其他政府债券。"},{"i":30,"n":"第三十条","txt":"中国人民银行不得向地方政府、各级政府部门提供贷款，不得向非银行金融机构以及其他单位和个人提供贷款，但国务院决定中国人民银行可以向特定的非银行金融机构提供贷款的除外。"},{"i":31,"n":"第三十一条","txt":"中国人民银行依法监测金融市场的运行情况，对金融市场实施宏观调控，促进其协调发展。"},{"i":32,"n":"第三十二条","txt":"中国人民银行有权对金融机构以及其他单位和个人的下列行为进行检查监督："},{"i":33,"n":"第三十三条","txt":"中国人民银行根据执行货币政策和维护金融稳定的需要，可以建议国务院银行业监督管理机构对银行业金融机构进行检查监督。国务院银行业监督管理机构应当自收到建议之日起三十日内予以回复。"},{"i":34,"n":"第三十四条","txt":"当银行业金融机构出现支付困难，可能引发金融风险时，为了维护金融稳定，中国人民银行经国务院批准，有权对银行业金融机构进行检查监督。"},{"i":35,"n":"第三十五条","txt":"中国人民银行根据履行职责的需要，有权要求银行业金融机构报送必要的资产负债表、利润表以及其他财务会计、统计报表和资料。"},{"i":36,"n":"第三十六条","txt":"中国人民银行负责统一编制全国金融统计数据、报表，并按照国家有关规定予以公布。"},{"i":37,"n":"第三十七条","txt":"中国人民银行应当建立、健全本系统的稽核、检查制度，加强内部的监督管理。"},{"i":38,"n":"第三十八条","txt":"中国人民银行实行独立的财务预算管理制度。"},{"i":39,"n":"第三十九条","txt":"中国人民银行每一会计年度的收入减除该年度支出，并按照国务院财政部门核定的比例提取总准备金后的净利润，全部上缴中央财政。"},{"i":40,"n":"第四十条","txt":"中国人民银行的财务收支和会计事务，应当执行法律、行政法规和国家统一的财务、会计制度，接受国务院审计机关和财政部门依法分别进行的审计和监督。"},{"i":41,"n":"第四十一条","txt":"中国人民银行应当于每一会计年度结束后的三个月内，编制资产负债表、损益表和相关的财务会计报表，并编制年度报告，按照国家有关规定予以公布。"},{"i":42,"n":"第四十二条","txt":"伪造、变造人民币，出售伪造、变造的人民币，或者明知是伪造、变造的人民币而运输，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，由公安机关处十五日以下拘留、一万元以下罚款。"},{"i":43,"n":"第四十三条","txt":"购买伪造、变造的人民币或者明知是伪造、变造的人民币而持有、使用，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，由公安机关处十五日以下拘留、一万元以下罚款。"},{"i":44,"n":"第四十四条","txt":"在宣传品、出版物或者其他商品上非法使用人民币图样的，中国人民银行应当责令改正，并销毁非法使用的人民币图样，没收违法所得，并处五万元以下罚款。"},{"i":45,"n":"第四十五条","txt":"印制、发售代币票券，以代替人民币在市场上流通的，中国人民银行应当责令停止违法行为，并处二十万元以下罚款。"},{"i":46,"n":"第四十六条","txt":"本法第三十二条所列行为违反有关规定，有关法律、行政法规有处罚规定的，依照其规定给予处罚；有关法律、行政法规未作处罚规定的，由中国人民银行区别不同情形给予警告，没收违法所得，违法所得五十万元以上的，并处违法所得一倍以上五倍以下罚款；没有违法所得或者违法所得不足五十万元的，处五十万元以上二百万元以下罚款；对负有直接责任的董事、高级管理人员和其他直接责任人员给予警告，处五万元以上五十万元以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":47,"n":"第四十七条","txt":"当事人对行政处罚不服的，可以依照《中华人民共和国行政诉讼法》的规定提起行政诉讼。"},{"i":48,"n":"第四十八条","txt":"中国人民银行有下列行为之一的，对负有直接责任的主管人员和其他直接责任人员，依法给予行政处分；构成犯罪的，依法追究刑事责任："},{"i":49,"n":"第四十九条","txt":"地方政府、各级政府部门、社会团体和个人强令中国人民银行及其工作人员违反本法第三十条的规定提供贷款或者担保的，对负有直接责任的主管人员和其他直接责任人员，依法给予行政处分；构成犯罪的，依法追究刑事责任；造成损失的，应当承担部分或者全部赔偿责任。"},{"i":50,"n":"第五十条","txt":"中国人民银行的工作人员泄露国家秘密或者所知悉的商业秘密，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":51,"n":"第五十一条","txt":"中国人民银行的工作人员贪污受贿、徇私舞弊、滥用职权、玩忽职守，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":52,"n":"第五十二条","txt":"本法所称银行业金融机构，是指在中华人民共和国境内设立的商业银行、城市信用合作社、农村信用合作社等吸收公众存款的金融机构以及政策性银行。"},{"i":53,"n":"第五十三条","txt":"本法自公布之日起施行。"}],"zhongxiaoqiyecujinfa":[{"i":1,"n":"第一条","txt":"为了改善中小企业经营环境，保障中小企业公平参与市场竞争，维护中小企业合法权益，支持中小企业创业创新，促进中小企业健康发展，扩大城乡就业，发挥中小企业在国民经济和社会发展中的重要作用，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称中小企业，是指在中华人民共和国境内依法设立的，人员规模、经营规模相对较小的企业，包括中型企业、小型企业和微型企业。"},{"i":3,"n":"第三条","txt":"国家将促进中小企业发展作为长期发展战略，坚持各类企业权利平等、机会平等、规则平等，对中小企业特别是其中的小型微型企业实行积极扶持、加强引导、完善服务、依法规范、保障权益的方针，为中小企业创立和发展创造有利的环境。"},{"i":4,"n":"第四条","txt":"中小企业应当依法经营，遵守国家劳动用工、安全生产、职业卫生、社会保障、资源环境、质量标准、知识产权、财政税收等方面的法律、法规，遵循诚信原则，规范内部管理，提高经营管理水平；不得损害劳动者合法权益，不得损害社会公共利益。"},{"i":5,"n":"第五条","txt":"国务院制定促进中小企业发展政策，建立中小企业促进工作协调机制，统筹全国中小企业促进工作。"},{"i":6,"n":"第六条","txt":"国家建立中小企业统计监测制度。统计部门应当加强对中小企业的统计调查和监测分析，定期发布有关信息。"},{"i":7,"n":"第七条","txt":"国家推进中小企业信用制度建设，建立社会化的信用信息征集与评价体系，实现中小企业信用信息查询、交流和共享的社会化。"},{"i":8,"n":"第八条","txt":"中央财政应当在本级预算中设立中小企业科目，安排中小企业发展专项资金。"},{"i":9,"n":"第九条","txt":"中小企业发展专项资金通过资助、购买服务、奖励等方式，重点用于支持中小企业公共服务体系和融资服务体系建设。"},{"i":10,"n":"第十条","txt":"国家设立中小企业发展基金。国家中小企业发展基金应当遵循政策性导向和市场化运作原则，主要用于引导和带动社会资金支持初创期中小企业，促进创业创新。"},{"i":11,"n":"第十一条","txt":"国家实行有利于小型微型企业发展的税收政策，对符合条件的小型微型企业按照规定实行缓征、减征、免征企业所得税、增值税等措施，简化税收征管程序，减轻小型微型企业税收负担。"},{"i":12,"n":"第十二条","txt":"国家对小型微型企业行政事业性收费实行减免等优惠政策，减轻小型微型企业负担。"},{"i":13,"n":"第十三条","txt":"金融机构应当发挥服务实体经济的功能，高效、公平地服务中小企业。"},{"i":14,"n":"第十四条","txt":"中国人民银行应当综合运用货币政策工具，鼓励和引导金融机构加大对小型微型企业的信贷支持，改善小型微型企业融资环境。"},{"i":15,"n":"第十五条","txt":"国务院银行业监督管理机构对金融机构开展小型微型企业金融服务应当制定差异化监管政策，采取合理提高小型微型企业不良贷款容忍度等措施，引导金融机构增加小型微型企业融资规模和比重，提高金融服务水平。"},{"i":16,"n":"第十六条","txt":"国家鼓励各类金融机构开发和提供适合中小企业特点的金融产品和服务。"},{"i":17,"n":"第十七条","txt":"国家推进和支持普惠金融体系建设，推动中小银行、非存款类放贷机构和互联网金融有序健康发展，引导银行业金融机构向县域和乡镇等小型微型企业金融服务薄弱地区延伸网点和业务。"},{"i":18,"n":"第十八条","txt":"国家健全多层次资本市场体系，多渠道推动股权融资，发展并规范债券市场，促进中小企业利用多种方式直接融资。"},{"i":19,"n":"第十九条","txt":"国家完善担保融资制度，支持金融机构为中小企业提供以应收账款、知识产权、存货、机器设备等为担保品的担保融资。"},{"i":20,"n":"第二十条","txt":"中小企业以应收账款申请担保融资时，其应收账款的付款方，应当及时确认债权债务关系，支持中小企业融资。"},{"i":21,"n":"第二十一条","txt":"县级以上人民政府应当建立中小企业政策性信用担保体系，鼓励各类担保机构为中小企业融资提供信用担保。"},{"i":22,"n":"第二十二条","txt":"国家推动保险机构开展中小企业贷款保证保险和信用保险业务，开发适应中小企业分散风险、补偿损失需求的保险产品。"},{"i":23,"n":"第二十三条","txt":"国家支持征信机构发展针对中小企业融资的征信产品和服务，依法向政府有关部门、公用事业单位和商业机构采集信息。"},{"i":24,"n":"第二十四条","txt":"县级以上人民政府及其有关部门应当通过政府网站、宣传资料等形式，为创业人员免费提供工商、财税、金融、环境保护、安全生产、劳动用工、社会保障等方面的法律政策咨询和公共信息服务。"},{"i":25,"n":"第二十五条","txt":"高等学校毕业生、退役军人和失业人员、残疾人员等创办小型微型企业，按照国家规定享受税收优惠和收费减免。"},{"i":26,"n":"第二十六条","txt":"国家采取措施支持社会资金参与投资中小企业。创业投资企业和个人投资者投资初创期科技创新企业的，按照国家规定享受税收优惠。"},{"i":27,"n":"第二十七条","txt":"国家改善企业创业环境，优化审批流程，实现中小企业行政许可便捷，降低中小企业设立成本。"},{"i":28,"n":"第二十八条","txt":"国家鼓励建设和创办小型微型企业创业基地、孵化基地，为小型微型企业提供生产经营场地和服务。"},{"i":29,"n":"第二十九条","txt":"地方各级人民政府应当根据中小企业发展的需要，在城乡规划中安排必要的用地和设施，为中小企业获得生产经营场所提供便利。"},{"i":30,"n":"第三十条","txt":"国家鼓励互联网平台向中小企业开放技术、开发、营销、推广等资源，加强资源共享与合作，为中小企业创业提供服务。"},{"i":31,"n":"第三十一条","txt":"国家简化中小企业注销登记程序，实现中小企业市场退出便利化。"},{"i":32,"n":"第三十二条","txt":"国家鼓励中小企业按照市场需求，推进技术、产品、管理模式、商业模式等创新。"},{"i":33,"n":"第三十三条","txt":"国家支持中小企业在研发设计、生产制造、运营管理等环节应用互联网、云计算、大数据、人工智能等现代技术手段，创新生产方式，提高生产经营效率。"},{"i":34,"n":"第三十四条","txt":"国家鼓励中小企业参与产业关键共性技术研究开发和利用财政资金设立的科研项目实施。"},{"i":35,"n":"第三十五条","txt":"国家鼓励中小企业研究开发拥有自主知识产权的技术和产品，规范内部知识产权管理，提升保护和运用知识产权的能力；鼓励中小企业投保知识产权保险；减轻中小企业申请和维持知识产权的费用等负担。"},{"i":36,"n":"第三十六条","txt":"县级以上人民政府有关部门应当在规划、用地、财政等方面提供支持，推动建立和发展各类创新服务机构。"},{"i":37,"n":"第三十七条","txt":"县级以上人民政府有关部门应当拓宽渠道，采取补贴、培训等措施，引导高等学校毕业生到中小企业就业，帮助中小企业引进创新人才。"},{"i":38,"n":"第三十八条","txt":"国家完善市场体系，实行统一的市场准入和市场监管制度，反对垄断和不正当竞争，营造中小企业公平参与竞争的市场环境。"},{"i":39,"n":"第三十九条","txt":"国家支持大型企业与中小企业建立以市场配置资源为基础的、稳定的原材料供应、生产、销售、服务外包、技术开发和技术改造等方面的协作关系，带动和促进中小企业发展。"},{"i":40,"n":"第四十条","txt":"国务院有关部门应当制定中小企业政府采购的相关优惠政策，通过制定采购需求标准、预留采购份额、价格评审优惠、优先采购等措施，提高中小企业在政府采购中的份额。"},{"i":41,"n":"第四十一条","txt":"县级以上人民政府有关部门应当在法律咨询、知识产权保护、技术性贸易措施、产品认证等方面为中小企业产品和服务出口提供指导和帮助，推动对外经济技术合作与交流。"},{"i":42,"n":"第四十二条","txt":"县级以上人民政府有关部门应当为中小企业提供用汇、人员出入境等方面的便利，支持中小企业到境外投资，开拓国际市场。"},{"i":43,"n":"第四十三条","txt":"国家建立健全社会化的中小企业公共服务体系，为中小企业提供服务。"},{"i":44,"n":"第四十四条","txt":"县级以上地方各级人民政府应当根据实际需要建立和完善中小企业公共服务机构，为中小企业提供公益性服务。"},{"i":45,"n":"第四十五条","txt":"县级以上人民政府负责中小企业促进工作综合管理的部门应当建立跨部门的政策信息互联网发布平台，及时汇集涉及中小企业的法律法规、创业、创新、金融、市场、权益保护等各类政府服务信息，为中小企业提供便捷无偿服务。"},{"i":46,"n":"第四十六条","txt":"国家鼓励各类服务机构为中小企业提供创业培训与辅导、知识产权保护、管理咨询、信息咨询、信用服务、市场营销、项目开发、投资融资、财会税务、产权交易、技术支持、人才引进、对外合作、展览展销、法律咨询等服务。"},{"i":47,"n":"第四十七条","txt":"县级以上人民政府负责中小企业促进工作综合管理的部门应当安排资金，有计划地组织实施中小企业经营管理人员培训。"},{"i":48,"n":"第四十八条","txt":"国家支持有关机构、高等学校开展针对中小企业经营管理及生产技术等方面的人员培训，提高企业营销、管理和技术水平。"},{"i":49,"n":"第四十九条","txt":"中小企业的有关行业组织应当依法维护会员的合法权益，反映会员诉求，加强自律管理，为中小企业创业创新、开拓市场等提供服务。"},{"i":50,"n":"第五十条","txt":"国家保护中小企业及其出资人的财产权和其他合法权益。任何单位和个人不得侵犯中小企业财产及其合法收益。"},{"i":51,"n":"第五十一条","txt":"县级以上人民政府负责中小企业促进工作综合管理的部门应当建立专门渠道，听取中小企业对政府相关管理工作的意见和建议，并及时向有关部门反馈，督促改进。"},{"i":52,"n":"第五十二条","txt":"地方各级人民政府应当依法实施行政许可，依法开展管理工作，不得实施没有法律、法规依据的检查，不得强制或者变相强制中小企业参加考核、评比、表彰、培训等活动。"},{"i":53,"n":"第五十三条","txt":"国家机关、事业单位和大型企业不得违约拖欠中小企业的货物、工程、服务款项。"},{"i":54,"n":"第五十四条","txt":"任何单位不得违反法律、法规向中小企业收取费用，不得实施没有法律、法规依据的罚款，不得向中小企业摊派财物。中小企业对违反上述规定的行为有权拒绝和举报、控告。"},{"i":55,"n":"第五十五条","txt":"国家建立和实施涉企行政事业性收费目录清单制度，收费目录清单及其实施情况向社会公开，接受社会监督。"},{"i":56,"n":"第五十六条","txt":"县级以上地方各级人民政府有关部门对中小企业实施监督检查应当依法进行，建立随机抽查机制。同一部门对中小企业实施的多项监督检查能够合并进行的，应当合并进行；不同部门对中小企业实施的多项监督检查能够合并完成的，由本级人民政府组织有关部门实施合并或者联合检查。"},{"i":57,"n":"第五十七条","txt":"县级以上人民政府定期组织对中小企业促进工作情况的监督检查；对违反本法的行为及时予以纠正，并对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":58,"n":"第五十八条","txt":"国务院负责中小企业促进工作综合管理的部门应当委托第三方机构定期开展中小企业发展环境评估，并向社会公布。"},{"i":59,"n":"第五十九条","txt":"县级以上人民政府应当定期组织开展对中小企业发展专项资金、中小企业发展基金使用效果的企业评价、社会评价和资金使用动态评估，并将评价和评估情况及时向社会公布，接受社会监督。"},{"i":60,"n":"第六十条","txt":"县级以上地方各级人民政府有关部门在各自职责范围内，对强制或者变相强制中小企业参加考核、评比、表彰、培训等活动的行为，违法向中小企业收费、罚款、摊派财物的行为，以及其他侵犯中小企业合法权益的行为进行查处，并对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":61,"n":"第六十一条","txt":"本法自2018年1月1日起施行。"}],"xiangcunzhenxingcujinfa":[{"i":1,"n":"第一条","txt":"为了全面实施乡村振兴战略，促进农业全面升级、农村全面进步、农民全面发展，加快农业农村现代化，全面建设社会主义现代化国家，制定本法。"},{"i":2,"n":"第二条","txt":"全面实施乡村振兴战略，开展促进乡村产业振兴、人才振兴、文化振兴、生态振兴、组织振兴，推进城乡融合发展等活动，适用本法。"},{"i":3,"n":"第三条","txt":"促进乡村振兴应当按照产业兴旺、生态宜居、乡风文明、治理有效、生活富裕的总要求，统筹推进农村经济建设、政治建设、文化建设、社会建设、生态文明建设和党的建设，充分发挥乡村在保障农产品供给和粮食安全、保护生态环境、传承发展中华民族优秀传统文化等方面的特有功能。"},{"i":4,"n":"第四条","txt":"全面实施乡村振兴战略，应当坚持中国共产党的领导，贯彻创新、协调、绿色、开放、共享的新发展理念，走中国特色社会主义乡村振兴道路，促进共同富裕，遵循以下原则："},{"i":5,"n":"第五条","txt":"国家巩固和完善以家庭承包经营为基础、统分结合的双层经营体制，发展壮大农村集体所有制经济。"},{"i":6,"n":"第六条","txt":"国家建立健全城乡融合发展的体制机制和政策体系，推动城乡要素有序流动、平等交换和公共资源均衡配置，坚持以工补农、以城带乡，推动形成工农互促、城乡互补、协调发展、共同繁荣的新型工农城乡关系。"},{"i":7,"n":"第七条","txt":"国家坚持以社会主义核心价值观为引领，大力弘扬民族精神和时代精神，加强乡村优秀传统文化保护和公共文化服务体系建设，繁荣发展乡村文化。"},{"i":8,"n":"第八条","txt":"国家实施以我为主、立足国内、确保产能、适度进口、科技支撑的粮食安全战略，坚持藏粮于地、藏粮于技，采取措施不断提高粮食综合生产能力，建设国家粮食安全产业带，完善粮食加工、流通、储备体系，确保谷物基本自给、口粮绝对安全，保障国家粮食安全。"},{"i":9,"n":"第九条","txt":"国家建立健全中央统筹、省负总责、市县乡抓落实的乡村振兴工作机制。"},{"i":10,"n":"第十条","txt":"国务院农业农村主管部门负责全国乡村振兴促进工作的统筹协调、宏观指导和监督检查；国务院其他有关部门在各自职责范围内负责有关的乡村振兴促进工作。"},{"i":11,"n":"第十一条","txt":"各级人民政府及其有关部门应当采取多种形式，广泛宣传乡村振兴促进相关法律法规和政策，鼓励、支持人民团体、社会组织、企事业单位等社会各方面参与乡村振兴促进相关活动。"},{"i":12,"n":"第十二条","txt":"国家完善农村集体产权制度，增强农村集体所有制经济发展活力，促进集体资产保值增值，确保农民受益。"},{"i":13,"n":"第十三条","txt":"国家采取措施优化农业生产力布局，推进农业结构调整，发展优势特色产业，保障粮食和重要农产品有效供给和质量安全，推动品种培优、品质提升、品牌打造和标准化生产，推动农业对外开放，提高农业质量、效益和竞争力。"},{"i":14,"n":"第十四条","txt":"国家建立农用地分类管理制度，严格保护耕地，严格控制农用地转为建设用地，严格控制耕地转为林地、园地等其他类型农用地。省、自治区、直辖市人民政府应当采取措施确保耕地总量不减少、质量有提高。"},{"i":15,"n":"第十五条","txt":"国家加强农业种质资源保护利用和种质资源库建设，支持育种基础性、前沿性和应用技术研究，实施农作物和畜禽等良种培育、育种关键技术攻关，鼓励种业科技成果转化和优良品种推广，建立并实施种业国家安全审查机制，促进种业高质量发展。"},{"i":16,"n":"第十六条","txt":"国家采取措施加强农业科技创新，培育创新主体，构建以企业为主体、产学研协同的创新机制，强化高等学校、科研机构、农业企业创新能力，建立创新平台，加强新品种、新技术、新装备、新产品研发，加强农业知识产权保护，推进生物种业、智慧农业、设施农业、农产品加工、绿色农业投入品等领域创新，建设现代农业产业技术体系，推动农业农村创新驱动发展。"},{"i":17,"n":"第十七条","txt":"国家加强农业技术推广体系建设，促进建立有利于农业科技成果转化推广的激励机制和利益分享机制，鼓励企业、高等学校、职业学校、科研机构、科学技术社会团体、农民专业合作社、农业专业化社会化服务组织、农业科技人员等创新推广方式，开展农业技术推广服务。"},{"i":18,"n":"第十八条","txt":"国家鼓励农业机械生产研发和推广应用，推进主要农作物生产全程机械化，提高设施农业、林草业、畜牧业、渔业和农产品初加工的装备水平，推动农机农艺融合、机械化信息化融合，促进机械化生产与农田建设相适应、服务模式与农业适度规模经营相适应。"},{"i":19,"n":"第十九条","txt":"各级人民政府应当发挥农村资源和生态优势，支持特色农业、休闲农业、现代农产品加工业、乡村手工业、绿色建材、红色旅游、乡村旅游、康养和乡村物流、电子商务等乡村产业的发展；引导新型经营主体通过特色化、专业化经营，合理配置生产要素，促进乡村产业深度融合；支持特色农产品优势区、现代农业产业园、农业科技园、农村创业园、休闲农业和乡村旅游重点村镇等的建设；统筹农产品生产地、集散地、销售地市场建设，加强农产品流通骨干网络和冷链物流体系建设；鼓励企业获得国际通行的农产品认证，增强乡村产业竞争力。"},{"i":20,"n":"第二十条","txt":"各级人民政府应当完善扶持政策，加强指导服务，支持农民、返乡入乡人员在乡村创业创新，促进乡村产业发展和农民就业。"},{"i":21,"n":"第二十一条","txt":"各级人民政府应当建立健全有利于农民收入稳定增长的机制，鼓励支持农民拓宽增收渠道，促进农民增加收入。"},{"i":22,"n":"第二十二条","txt":"各级人民政府应当加强国有农（林、牧、渔）场规划建设，推进国有农（林、牧、渔）场现代农业发展，鼓励国有农（林、牧、渔）场在农业农村现代化建设中发挥示范引领作用。"},{"i":23,"n":"第二十三条","txt":"各级人民政府应当深化供销合作社综合改革，鼓励供销合作社加强与农民利益联结，完善市场运作机制，强化为农服务功能，发挥其为农服务综合性合作经济组织的作用。"},{"i":24,"n":"第二十四条","txt":"国家健全乡村人才工作体制机制，采取措施鼓励和支持社会各方面提供教育培训、技术支持、创业指导等服务，培养本土人才，引导城市人才下乡，推动专业人才服务乡村，促进农业农村人才队伍建设。"},{"i":25,"n":"第二十五条","txt":"各级人民政府应当加强农村教育工作统筹，持续改善农村学校办学条件，支持开展网络远程教育，提高农村基础教育质量，加大乡村教师培养力度，采取公费师范教育等方式吸引高等学校毕业生到乡村任教，对长期在乡村任教的教师在职称评定等方面给予优待，保障和改善乡村教师待遇，提高乡村教师学历水平、整体素质和乡村教育现代化水平。"},{"i":26,"n":"第二十六条","txt":"各级人民政府应当采取措施，加强职业教育和继续教育，组织开展农业技能培训、返乡创业就业培训和职业技能培训，培养有文化、懂技术、善经营、会管理的高素质农民和农村实用人才、创新创业带头人。"},{"i":27,"n":"第二十七条","txt":"县级以上人民政府及其教育行政部门应当指导、支持高等学校、职业学校设置涉农相关专业，加大农村专业人才培养力度，鼓励高等学校、职业学校毕业生到农村就业创业。"},{"i":28,"n":"第二十八条","txt":"国家鼓励城市人才向乡村流动，建立健全城乡、区域、校地之间人才培养合作与交流机制。"},{"i":29,"n":"第二十九条","txt":"各级人民政府应当组织开展新时代文明实践活动，加强农村精神文明建设，不断提高乡村社会文明程度。"},{"i":30,"n":"第三十条","txt":"各级人民政府应当采取措施丰富农民文化体育生活，倡导科学健康的生产生活方式，发挥村规民约积极作用，普及科学知识，推进移风易俗，破除大操大办、铺张浪费等陈规陋习，提倡孝老爱亲、勤俭节约、诚实守信，促进男女平等，创建文明村镇、文明家庭，培育文明乡风、良好家风、淳朴民风，建设文明乡村。"},{"i":31,"n":"第三十一条","txt":"各级人民政府应当健全完善乡村公共文化体育设施网络和服务运行机制，鼓励开展形式多样的农民群众性文化体育、节日民俗等活动，充分利用广播电视、视听网络和书籍报刊，拓展乡村文化服务渠道，提供便利可及的公共文化服务。"},{"i":32,"n":"第三十二条","txt":"各级人民政府应当采取措施保护农业文化遗产和非物质文化遗产，挖掘优秀农业文化深厚内涵，弘扬红色文化，传承和发展优秀传统文化。"},{"i":33,"n":"第三十三条","txt":"县级以上地方人民政府应当坚持规划引导、典型示范，有计划地建设特色鲜明、优势突出的农业文化展示区、文化产业特色村落，发展乡村特色文化体育产业，推动乡村地区传统工艺振兴，积极推动智慧广电乡村建设，活跃繁荣农村文化市场。"},{"i":34,"n":"第三十四条","txt":"国家健全重要生态系统保护制度和生态保护补偿机制，实施重要生态系统保护和修复工程，加强乡村生态保护和环境治理，绿化美化乡村环境，建设美丽乡村。"},{"i":35,"n":"第三十五条","txt":"国家鼓励和支持农业生产者采用节水、节肥、节药、节能等先进的种植养殖技术，推动种养结合、农业资源综合开发，优先发展生态循环农业。"},{"i":36,"n":"第三十六条","txt":"各级人民政府应当实施国土综合整治和生态修复，加强森林、草原、湿地等保护修复，开展荒漠化、石漠化、水土流失综合治理，改善乡村生态环境。"},{"i":37,"n":"第三十七条","txt":"各级人民政府应当建立政府、村级组织、企业、农民等各方面参与的共建共管共享机制，综合整治农村水系，因地制宜推广卫生厕所和简便易行的垃圾分类，治理农村垃圾和污水，加强乡村无障碍设施建设，鼓励和支持使用清洁能源、可再生能源，持续改善农村人居环境。"},{"i":38,"n":"第三十八条","txt":"国家建立健全农村住房建设质量安全管理制度和相关技术标准体系，建立农村低收入群体安全住房保障机制。建设农村住房应当避让灾害易发区域，符合抗震、防洪等基本安全要求。"},{"i":39,"n":"第三十九条","txt":"国家对农业投入品实行严格管理，对剧毒、高毒、高残留的农药、兽药采取禁用限用措施。农产品生产经营者不得使用国家禁用的农药、兽药或者其他有毒有害物质，不得违反农产品质量安全标准和国家有关规定超剂量、超范围使用农药、兽药、肥料、饲料添加剂等农业投入品。"},{"i":40,"n":"第四十条","txt":"国家实行耕地养护、修复、休耕和草原森林河流湖泊休养生息制度。县级以上人民政府及其有关部门依法划定江河湖海限捕、禁捕的时间和区域，并可以根据地下水超采情况，划定禁止、限制开采地下水区域。"},{"i":41,"n":"第四十一条","txt":"建立健全党委领导、政府负责、民主协商、社会协同、公众参与、法治保障、科技支撑的现代乡村社会治理体制和自治、法治、德治相结合的乡村社会治理体系，建设充满活力、和谐有序的善治乡村。"},{"i":42,"n":"第四十二条","txt":"中国共产党农村基层组织，按照中国共产党章程和有关规定发挥全面领导作用。村民委员会、农村集体经济组织等应当在乡镇党委和村党组织的领导下，实行村民自治，发展集体所有制经济，维护农民合法权益，并应当接受村民监督。"},{"i":43,"n":"第四十三条","txt":"国家建立健全农业农村工作干部队伍的培养、配备、使用、管理机制，选拔优秀干部充实到农业农村工作干部队伍，采取措施提高农业农村工作干部队伍的能力和水平，落实农村基层干部相关待遇保障，建设懂农业、爱农村、爱农民的农业农村工作干部队伍。"},{"i":44,"n":"第四十四条","txt":"地方各级人民政府应当构建简约高效的基层管理体制，科学设置乡镇机构，加强乡村干部培训，健全农村基层服务体系，夯实乡村治理基础。"},{"i":45,"n":"第四十五条","txt":"乡镇人民政府应当指导和支持农村基层群众性自治组织规范化、制度化建设，健全村民委员会民主决策机制和村务公开制度，增强村民自我管理、自我教育、自我服务、自我监督能力。"},{"i":46,"n":"第四十六条","txt":"各级人民政府应当引导和支持农村集体经济组织发挥依法管理集体资产、合理开发集体资源、服务集体成员等方面的作用，保障农村集体经济组织的独立运营。"},{"i":47,"n":"第四十七条","txt":"县级以上地方人民政府应当采取措施加强基层群团组织建设，支持、规范和引导农村社会组织发展，发挥基层群团组织、农村社会组织团结群众、联系群众、服务群众等方面的作用。"},{"i":48,"n":"第四十八条","txt":"地方各级人民政府应当加强基层执法队伍建设，鼓励乡镇人民政府根据需要设立法律顾问和公职律师，鼓励有条件的地方在村民委员会建立公共法律服务工作室，深入开展法治宣传教育和人民调解工作，健全乡村矛盾纠纷调处化解机制，推进法治乡村建设。"},{"i":49,"n":"第四十九条","txt":"地方各级人民政府应当健全农村社会治安防控体系，加强农村警务工作，推动平安乡村建设；健全农村公共安全体系，强化农村公共卫生、安全生产、防灾减灾救灾、应急救援、应急广播、食品、药品、交通、消防等安全管理责任。"},{"i":50,"n":"第五十条","txt":"各级人民政府应当协同推进乡村振兴战略和新型城镇化战略的实施，整体筹划城镇和乡村发展，科学有序统筹安排生态、农业、城镇等功能空间，优化城乡产业发展、基础设施、公共服务设施等布局，逐步健全全民覆盖、普惠共享、城乡一体的基本公共服务体系，加快县域城乡融合发展，促进农业高质高效、乡村宜居宜业、农民富裕富足。"},{"i":51,"n":"第五十一条","txt":"县级人民政府和乡镇人民政府应当优化本行政区域内乡村发展布局，按照尊重农民意愿、方便群众生产生活、保持乡村功能和特色的原则，因地制宜安排村庄布局，依法编制村庄规划，分类有序推进村庄建设，严格规范村庄撤并，严禁违背农民意愿、违反法定程序撤并村庄。"},{"i":52,"n":"第五十二条","txt":"县级以上地方人民政府应当统筹规划、建设、管护城乡道路以及垃圾污水处理、供水供电供气、物流、客运、信息通信、广播电视、消防、防灾减灾等公共基础设施和新型基础设施，推动城乡基础设施互联互通，保障乡村发展能源需求，保障农村饮用水安全，满足农民生产生活需要。"},{"i":53,"n":"第五十三条","txt":"国家发展农村社会事业，促进公共教育、医疗卫生、社会保障等资源向农村倾斜，提升乡村基本公共服务水平，推进城乡基本公共服务均等化。"},{"i":54,"n":"第五十四条","txt":"国家完善城乡统筹的社会保障制度，建立健全保障机制，支持乡村提高社会保障管理服务水平；建立健全城乡居民基本养老保险待遇确定和基础养老金标准正常调整机制，确保城乡居民基本养老保险待遇随经济社会发展逐步提高。"},{"i":55,"n":"第五十五条","txt":"国家推动形成平等竞争、规范有序、城乡统一的人力资源市场，健全城乡均等的公共就业创业服务制度。"},{"i":56,"n":"第五十六条","txt":"县级以上人民政府应当采取措施促进城乡产业协同发展，在保障农民主体地位的基础上健全联农带农激励机制，实现乡村经济多元化和农业全产业链发展。"},{"i":57,"n":"第五十七条","txt":"各级人民政府及其有关部门应当采取措施鼓励农民进城务工，全面落实城乡劳动者平等就业、同工同酬，依法保障农民工工资支付和社会保障权益。"},{"i":58,"n":"第五十八条","txt":"国家建立健全农业支持保护体系和实施乡村振兴战略财政投入保障制度。县级以上人民政府应当优先保障用于乡村振兴的财政投入，确保投入力度不断增强、总量持续增加、与乡村振兴目标任务相适应。"},{"i":59,"n":"第五十九条","txt":"各级人民政府应当采取措施增强脱贫地区内生发展能力，建立农村低收入人口、欠发达地区帮扶长效机制，持续推进脱贫地区发展；建立健全易返贫致贫人口动态监测预警和帮扶机制，实现巩固拓展脱贫攻坚成果同乡村振兴有效衔接。"},{"i":60,"n":"第六十条","txt":"国家按照增加总量、优化存量、提高效能的原则，构建以高质量绿色发展为导向的新型农业补贴政策体系。"},{"i":61,"n":"第六十一条","txt":"各级人民政府应当坚持取之于农、主要用之于农的原则，按照国家有关规定调整完善土地使用权出让收入使用范围，提高农业农村投入比例，重点用于高标准农田建设、农田水利建设、现代种业提升、农村供水保障、农村人居环境整治、农村土地综合整治、耕地及永久基本农田保护、村庄公共设施建设和管护、农村教育、农村文化和精神文明建设支出，以及与农业农村直接相关的山水林田湖草沙生态保护修复、以工代赈工程建设等。"},{"i":62,"n":"第六十二条","txt":"县级以上人民政府设立的相关专项资金、基金应当按照规定加强对乡村振兴的支持。"},{"i":63,"n":"第六十三条","txt":"国家综合运用财政、金融等政策措施，完善政府性融资担保机制，依法完善乡村资产抵押担保权能，改进、加强乡村振兴的金融支持和服务。"},{"i":64,"n":"第六十四条","txt":"国家健全多层次资本市场，多渠道推动涉农企业股权融资，发展并规范债券市场，促进涉农企业利用多种方式融资；丰富农产品期货品种，发挥期货市场价格发现和风险分散功能。"},{"i":65,"n":"第六十五条","txt":"国家建立健全多层次、广覆盖、可持续的农村金融服务体系，完善金融支持乡村振兴考核评估机制，促进农村普惠金融发展，鼓励金融机构依法将更多资源配置到乡村发展的重点领域和薄弱环节。"},{"i":66,"n":"第六十六条","txt":"国家建立健全多层次农业保险体系，完善政策性农业保险制度，鼓励商业性保险公司开展农业保险业务，支持农民和农业经营主体依法开展互助合作保险。"},{"i":67,"n":"第六十七条","txt":"县级以上地方人民政府应当推进节约集约用地，提高土地使用效率，依法采取措施盘活农村存量建设用地，激活农村土地资源，完善农村新增建设用地保障机制，满足乡村产业、公共服务设施和农民住宅用地合理需求。"},{"i":68,"n":"第六十八条","txt":"国家实行乡村振兴战略实施目标责任制和考核评价制度。上级人民政府应当对下级人民政府实施乡村振兴战略的目标完成情况等进行考核，考核结果作为地方人民政府及其负责人综合考核评价的重要内容。"},{"i":69,"n":"第六十九条","txt":"国务院和省、自治区、直辖市人民政府有关部门建立客观反映乡村振兴进展的指标和统计体系。县级以上地方人民政府应当对本行政区域内乡村振兴战略实施情况进行评估。"},{"i":70,"n":"第七十条","txt":"县级以上各级人民政府应当向本级人民代表大会或者其常务委员会报告乡村振兴促进工作情况。乡镇人民政府应当向本级人民代表大会报告乡村振兴促进工作情况。"},{"i":71,"n":"第七十一条","txt":"地方各级人民政府应当每年向上一级人民政府报告乡村振兴促进工作情况。"},{"i":72,"n":"第七十二条","txt":"县级以上人民政府发展改革、财政、农业农村、审计等部门按照各自职责对农业农村投入优先保障机制落实情况、乡村振兴资金使用情况和绩效等实施监督。"},{"i":73,"n":"第七十三条","txt":"各级人民政府及其有关部门在乡村振兴促进工作中不履行或者不正确履行职责的，依照法律法规和国家有关规定追究责任，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":74,"n":"第七十四条","txt":"本法自2021年6月1日起施行。"}],"chanpinzhiliangfa":[{"i":1,"n":"第一条","txt":"为了加强对产品质量的监督管理，提高产品质量水平，明确产品质量责任，保护消费者的合法权益，维护社会经济秩序，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事产品生产、销售活动，必须遵守本法。"},{"i":3,"n":"第三条","txt":"生产者、销售者应当建立健全内部产品质量管理制度，严格实施岗位质量规范、质量责任以及相应的考核办法。"},{"i":4,"n":"第四条","txt":"生产者、销售者依照本法规定承担产品质量责任。"},{"i":5,"n":"第五条","txt":"禁止伪造或者冒用认证标志等质量标志；禁止伪造产品的产地，伪造或者冒用他人的厂名、厂址；禁止在生产、销售的产品中掺杂、掺假，以假充真，以次充好。"},{"i":6,"n":"第六条","txt":"国家鼓励推行科学的质量管理方法，采用先进的科学技术，鼓励企业产品质量达到并且超过行业标准、国家标准和国际标准。"},{"i":7,"n":"第七条","txt":"各级人民政府应当把提高产品质量纳入国民经济和社会发展规划，加强对产品质量工作的统筹规划和组织领导，引导、督促生产者、销售者加强产品质量管理，提高产品质量，组织各有关部门依法采取措施，制止产品生产、销售中违反本法规定的行为，保障本法的施行。"},{"i":8,"n":"第八条","txt":"国务院市场监督管理部门主管全国产品质量监督工作。国务院有关部门在各自的职责范围内负责产品质量监督工作。"},{"i":9,"n":"第九条","txt":"各级人民政府工作人员和其他国家机关工作人员不得滥用职权、玩忽职守或者徇私舞弊，包庇、放纵本地区、本系统发生的产品生产、销售中违反本法规定的行为，或者阻挠、干预依法对产品生产、销售中违反本法规定的行为进行查处。"},{"i":10,"n":"第十条","txt":"任何单位和个人有权对违反本法规定的行为，向市场监督管理部门或者其他有关部门检举。"},{"i":11,"n":"第十一条","txt":"任何单位和个人不得排斥非本地区或者非本系统企业生产的质量合格产品进入本地区、本系统。"},{"i":12,"n":"第十二条","txt":"产品质量应当检验合格，不得以不合格产品冒充合格产品。"},{"i":13,"n":"第十三条","txt":"可能危及人体健康和人身、财产安全的工业产品，必须符合保障人体健康和人身、财产安全的国家标准、行业标准；未制定国家标准、行业标准的，必须符合保障人体健康和人身、财产安全的要求。"},{"i":14,"n":"第十四条","txt":"国家根据国际通用的质量管理标准，推行企业质量体系认证制度。企业根据自愿原则可以向国务院市场监督管理部门认可的或者国务院市场监督管理部门授权的部门认可的认证机构申请企业质量体系认证。经认证合格的，由认证机构颁发企业质量体系认证证书。"},{"i":15,"n":"第十五条","txt":"国家对产品质量实行以抽查为主要方式的监督检查制度，对可能危及人体健康和人身、财产安全的产品，影响国计民生的重要工业产品以及消费者、有关组织反映有质量问题的产品进行抽查。抽查的样品应当在市场上或者企业成品仓库内的待销产品中随机抽取。监督抽查工作由国务院市场监督管理部门规划和组织。县级以上地方市场监督管理部门在本行政区域内也可以组织监督抽查。法律对产品质量的监督检查另有规定的，依照有关法律的规定执行。"},{"i":16,"n":"第十六条","txt":"对依法进行的产品质量监督检查，生产者、销售者不得拒绝。"},{"i":17,"n":"第十七条","txt":"依照本法规定进行监督抽查的产品质量不合格的，由实施监督抽查的市场监督管理部门责令其生产者、销售者限期改正。逾期不改正的，由省级以上人民政府市场监督管理部门予以公告；公告后经复查仍不合格的，责令停业，限期整顿；整顿期满后经复查产品质量仍不合格的，吊销营业执照。"},{"i":18,"n":"第十八条","txt":"县级以上市场监督管理部门根据已经取得的违法嫌疑证据或者举报，对涉嫌违反本法规定的行为进行查处时，可以行使下列职权："},{"i":19,"n":"第十九条","txt":"产品质量检验机构必须具备相应的检测条件和能力，经省级以上人民政府市场监督管理部门或者其授权的部门考核合格后，方可承担产品质量检验工作。法律、行政法规对产品质量检验机构另有规定的，依照有关法律、行政法规的规定执行。"},{"i":20,"n":"第二十条","txt":"从事产品质量检验、认证的社会中介机构必须依法设立，不得与行政机关和其他国家机关存在隶属关系或者其他利益关系。"},{"i":21,"n":"第二十一条","txt":"产品质量检验机构、认证机构必须依法按照有关标准，客观、公正地出具检验结果或者认证证明。"},{"i":22,"n":"第二十二条","txt":"消费者有权就产品质量问题，向产品的生产者、销售者查询；向市场监督管理部门及有关部门申诉，接受申诉的部门应当负责处理。"},{"i":23,"n":"第二十三条","txt":"保护消费者权益的社会组织可以就消费者反映的产品质量问题建议有关部门负责处理，支持消费者对因产品质量造成的损害向人民法院起诉。"},{"i":24,"n":"第二十四条","txt":"国务院和省、自治区、直辖市人民政府的市场监督管理部门应当定期发布其监督抽查的产品的质量状况公告。"},{"i":25,"n":"第二十五条","txt":"市场监督管理部门或者其他国家机关以及产品质量检验机构不得向社会推荐生产者的产品；不得以对产品进行监制、监销等方式参与产品经营活动。"},{"i":26,"n":"第二十六条","txt":"生产者应当对其生产的产品质量负责。"},{"i":27,"n":"第二十七条","txt":"产品或者其包装上的标识必须真实，并符合下列要求："},{"i":28,"n":"第二十八条","txt":"易碎、易燃、易爆、有毒、有腐蚀性、有放射性等危险物品以及储运中不能倒置和其他有特殊要求的产品，其包装质量必须符合相应要求，依照国家有关规定作出警示标志或者中文警示说明，标明储运注意事项。"},{"i":29,"n":"第二十九条","txt":"生产者不得生产国家明令淘汰的产品。"},{"i":30,"n":"第三十条","txt":"生产者不得伪造产地，不得伪造或者冒用他人的厂名、厂址。"},{"i":31,"n":"第三十一条","txt":"生产者不得伪造或者冒用认证标志等质量标志。"},{"i":32,"n":"第三十二条","txt":"生产者生产产品，不得掺杂、掺假，不得以假充真、以次充好，不得以不合格产品冒充合格产品。"},{"i":33,"n":"第三十三条","txt":"销售者应当建立并执行进货检查验收制度，验明产品合格证明和其他标识。"},{"i":34,"n":"第三十四条","txt":"销售者应当采取措施，保持销售产品的质量。"},{"i":35,"n":"第三十五条","txt":"销售者不得销售国家明令淘汰并停止销售的产品和失效、变质的产品。"},{"i":36,"n":"第三十六条","txt":"销售者销售的产品的标识应当符合本法第二十七条的规定。"},{"i":37,"n":"第三十七条","txt":"销售者不得伪造产地，不得伪造或者冒用他人的厂名、厂址。"},{"i":38,"n":"第三十八条","txt":"销售者不得伪造或者冒用认证标志等质量标志。"},{"i":39,"n":"第三十九条","txt":"销售者销售产品，不得掺杂、掺假，不得以假充真、以次充好，不得以不合格产品冒充合格产品。"},{"i":40,"n":"第四十条","txt":"售出的产品有下列情形之一的，销售者应当负责修理、更换、退货；给购买产品的消费者造成损失的，销售者应当赔偿损失："},{"i":41,"n":"第四十一条","txt":"因产品存在缺陷造成人身、缺陷产品以外的其他财产（以下简称他人财产）损害的，生产者应当承担赔偿责任。"},{"i":42,"n":"第四十二条","txt":"由于销售者的过错使产品存在缺陷，造成人身、他人财产损害的，销售者应当承担赔偿责任。"},{"i":43,"n":"第四十三条","txt":"因产品存在缺陷造成人身、他人财产损害的，受害人可以向产品的生产者要求赔偿，也可以向产品的销售者要求赔偿。属于产品的生产者的责任，产品的销售者赔偿的，产品的销售者有权向产品的生产者追偿。属于产品的销售者的责任，产品的生产者赔偿的，产品的生产者有权向产品的销售者追偿。"},{"i":44,"n":"第四十四条","txt":"因产品存在缺陷造成受害人人身伤害的，侵害人应当赔偿医疗费、治疗期间的护理费、因误工减少的收入等费用；造成残疾的，还应当支付残疾者生活自助具费、生活补助费、残疾赔偿金以及由其扶养的人所必需的生活费等费用；造成受害人死亡的，并应当支付丧葬费、死亡赔偿金以及由死者生前扶养的人所必需的生活费等费用。"},{"i":45,"n":"第四十五条","txt":"因产品存在缺陷造成损害要求赔偿的诉讼时效期间为二年，自当事人知道或者应当知道其权益受到损害时起计算。"},{"i":46,"n":"第四十六条","txt":"本法所称缺陷，是指产品存在危及人身、他人财产安全的不合理的危险；产品有保障人体健康和人身、财产安全的国家标准、行业标准的，是指不符合该标准。"},{"i":47,"n":"第四十七条","txt":"因产品质量发生民事纠纷时，当事人可以通过协商或者调解解决。当事人不愿通过协商、调解解决或者协商、调解不成的，可以根据当事人各方的协议向仲裁机构申请仲裁；当事人各方没有达成仲裁协议或者仲裁协议无效的，可以直接向人民法院起诉。"},{"i":48,"n":"第四十八条","txt":"仲裁机构或者人民法院可以委托本法第十九条规定的产品质量检验机构，对有关产品质量进行检验。"},{"i":49,"n":"第四十九条","txt":"生产、销售不符合保障人体健康和人身、财产安全的国家标准、行业标准的产品的，责令停止生产、销售，没收违法生产、销售的产品，并处违法生产、销售产品（包括已售出和未售出的产品，下同）货值金额等值以上三倍以下的罚款；有违法所得的，并处没收违法所得；情节严重的，吊销营业执照；构成犯罪的，依法追究刑事责任。"},{"i":50,"n":"第五十条","txt":"在产品中掺杂、掺假，以假充真，以次充好，或者以不合格产品冒充合格产品的，责令停止生产、销售，没收违法生产、销售的产品，并处违法生产、销售产品货值金额百分之五十以上三倍以下的罚款；有违法所得的，并处没收违法所得；情节严重的，吊销营业执照；构成犯罪的，依法追究刑事责任。"},{"i":51,"n":"第五十一条","txt":"生产国家明令淘汰的产品的，销售国家明令淘汰并停止销售的产品的，责令停止生产、销售，没收违法生产、销售的产品，并处违法生产、销售产品货值金额等值以下的罚款；有违法所得的，并处没收违法所得；情节严重的，吊销营业执照。"},{"i":52,"n":"第五十二条","txt":"销售失效、变质的产品的，责令停止销售，没收违法销售的产品，并处违法销售产品货值金额二倍以下的罚款；有违法所得的，并处没收违法所得；情节严重的，吊销营业执照；构成犯罪的，依法追究刑事责任。"},{"i":53,"n":"第五十三条","txt":"伪造产品产地的，伪造或者冒用他人厂名、厂址的，伪造或者冒用认证标志等质量标志的，责令改正，没收违法生产、销售的产品，并处违法生产、销售产品货值金额等值以下的罚款；有违法所得的，并处没收违法所得；情节严重的，吊销营业执照。"},{"i":54,"n":"第五十四条","txt":"产品标识不符合本法第二十七条规定的，责令改正；有包装的产品标识不符合本法第二十七条第（四）项、第（五）项规定，情节严重的，责令停止生产、销售，并处违法生产、销售产品货值金额百分之三十以下的罚款；有违法所得的，并处没收违法所得。"},{"i":55,"n":"第五十五条","txt":"销售者销售本法第四十九条至第五十三条规定禁止销售的产品，有充分证据证明其不知道该产品为禁止销售的产品并如实说明其进货来源的，可以从轻或者减轻处罚。"},{"i":56,"n":"第五十六条","txt":"拒绝接受依法进行的产品质量监督检查的，给予警告，责令改正；拒不改正的，责令停业整顿；情节特别严重的，吊销营业执照。"},{"i":57,"n":"第五十七条","txt":"产品质量检验机构、认证机构伪造检验结果或者出具虚假证明的，责令改正，对单位处五万元以上十万元以下的罚款，对直接负责的主管人员和其他直接责任人员处一万元以上五万元以下的罚款；有违法所得的，并处没收违法所得；情节严重的，取消其检验资格、认证资格；构成犯罪的，依法追究刑事责任。"},{"i":58,"n":"第五十八条","txt":"社会团体、社会中介机构对产品质量作出承诺、保证，而该产品又不符合其承诺、保证的质量要求，给消费者造成损失的，与产品的生产者、销售者承担连带责任。"},{"i":59,"n":"第五十九条","txt":"在广告中对产品质量作虚假宣传，欺骗和误导消费者的，依照《中华人民共和国广告法》的规定追究法律责任。"},{"i":60,"n":"第六十条","txt":"对生产者专门用于生产本法第四十九条、第五十一条所列的产品或者以假充真的产品的原辅材料、包装物、生产工具，应当予以没收。"},{"i":61,"n":"第六十一条","txt":"知道或者应当知道属于本法规定禁止生产、销售的产品而为其提供运输、保管、仓储等便利条件的，或者为以假充真的产品提供制假生产技术的，没收全部运输、保管、仓储或者提供制假生产技术的收入，并处违法收入百分之五十以上三倍以下的罚款；构成犯罪的，依法追究刑事责任。"},{"i":62,"n":"第六十二条","txt":"服务业的经营者将本法第四十九条至第五十二条规定禁止销售的产品用于经营性服务的，责令停止使用；对知道或者应当知道所使用的产品属于本法规定禁止销售的产品的，按照违法使用的产品（包括已使用和尚未使用的产品）的货值金额，依照本法对销售者的处罚规定处罚。"},{"i":63,"n":"第六十三条","txt":"隐匿、转移、变卖、损毁被市场监督管理部门查封、扣押的物品的，处被隐匿、转移、变卖、损毁物品货值金额等值以上三倍以下的罚款；有违法所得的，并处没收违法所得。"},{"i":64,"n":"第六十四条","txt":"违反本法规定，应当承担民事赔偿责任和缴纳罚款、罚金，其财产不足以同时支付时，先承担民事赔偿责任。"},{"i":65,"n":"第六十五条","txt":"各级人民政府工作人员和其他国家机关工作人员有下列情形之一的，依法给予行政处分；构成犯罪的，依法追究刑事责任："},{"i":66,"n":"第六十六条","txt":"市场监督管理部门在产品质量监督抽查中超过规定的数量索取样品或者向被检查人收取检验费用的，由上级市场监督管理部门或者监察机关责令退还；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予行政处分。"},{"i":67,"n":"第六十七条","txt":"市场监督管理部门或者其他国家机关违反本法第二十五条的规定，向社会推荐生产者的产品或者以监制、监销等方式参与产品经营活动的，由其上级机关或者监察机关责令改正，消除影响，有违法收入的予以没收；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予行政处分。"},{"i":68,"n":"第六十八条","txt":"市场监督管理部门的工作人员滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":69,"n":"第六十九条","txt":"以暴力、威胁方法阻碍市场监督管理部门的工作人员依法执行职务的，依法追究刑事责任；拒绝、阻碍未使用暴力、威胁方法的，由公安机关依照治安管理处罚法的规定处罚。"},{"i":70,"n":"第七十条","txt":"本法第四十九条至第五十七条、第六十条至第六十三条规定的行政处罚由市场监督管理部门决定。法律、行政法规对行使行政处罚权的机关另有规定的，依照有关法律、行政法规的规定执行。"},{"i":71,"n":"第七十一条","txt":"对依照本法规定没收的产品，依照国家有关规定进行销毁或者采取其他方式处理。"},{"i":72,"n":"第七十二条","txt":"本法第四十九条至第五十四条、第六十二条、第六十三条所规定的货值金额以违法生产、销售产品的标价计算；没有标价的，按照同类产品的市场价格计算。"},{"i":73,"n":"第七十三条","txt":"军工产品质量监督管理办法，由国务院、中央军事委员会另行制定。"},{"i":74,"n":"第七十四条","txt":"本法自1993年9月1日起施行。"}],"jiagefa":[{"i":1,"n":"第一条","txt":"为了规范价格行为，发挥价格合理配置资源的作用，稳定市场价格总水平，保护消费者和经营者的合法权益，促进社会主义市场经济健康发展，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内发生的价格行为，适用本法。"},{"i":3,"n":"第三条","txt":"国家实行并逐步完善宏观经济调控下主要由市场形成价格的机制。价格的制定应当符合价值规律，大多数商品和服务价格实行市场调节价，极少数商品和服务价格实行政府指导价或者政府定价。"},{"i":4,"n":"第四条","txt":"国家支持和促进公平、公开、合法的市场竞争，维护正常的价格秩序，对价格活动实行管理、监督和必要的调控。"},{"i":5,"n":"第五条","txt":"国务院价格主管部门统一负责全国的价格工作。国务院其他有关部门在各自的职责范围内，负责有关的价格工作。"},{"i":6,"n":"第六条","txt":"商品价格和服务价格，除依照本法第十八条规定适用政府指导价或者政府定价外，实行市场调节价，由经营者依照本法自主制定。"},{"i":7,"n":"第七条","txt":"经营者定价，应当遵循公平、合法和诚实信用的原则。"},{"i":8,"n":"第八条","txt":"经营者定价的基本依据是生产经营成本和市场供求状况。"},{"i":9,"n":"第九条","txt":"经营者应当努力改进生产经营管理，降低生产经营成本，为消费者提供价格合理的商品和服务，并在市场竞争中获取合法利润。"},{"i":10,"n":"第十条","txt":"经营者应当根据其经营条件建立、健全内部价格管理制度，准确记录与核定商品和服务的生产经营成本，不得弄虚作假。"},{"i":11,"n":"第十一条","txt":"经营者进行价格活动，享有下列权利："},{"i":12,"n":"第十二条","txt":"经营者进行价格活动，应当遵守法律、法规，执行依法制定的政府指导价、政府定价和法定的价格干预措施、紧急措施。"},{"i":13,"n":"第十三条","txt":"经营者销售、收购商品和提供服务，应当按照政府价格主管部门的规定明码标价，注明商品的品名、产地、规格、等级、计价单位、价格或者服务的项目、收费标准等有关情况。"},{"i":14,"n":"第十四条","txt":"经营者不得有下列不正当价格行为："},{"i":15,"n":"第十五条","txt":"各类中介机构提供有偿服务收取费用，应当遵守本法的规定。法律另有规定的，按照有关规定执行。"},{"i":16,"n":"第十六条","txt":"经营者销售进口商品、收购出口商品，应当遵守本章的有关规定，维护国内市场秩序。"},{"i":17,"n":"第十七条","txt":"行业组织应当遵守价格法律、法规，加强价格自律，接受政府价格主管部门的工作指导。"},{"i":18,"n":"第十八条","txt":"下列商品和服务价格，政府在必要时可以实行政府指导价或者政府定价："},{"i":19,"n":"第十九条","txt":"政府指导价、政府定价的定价权限和具体适用范围，以中央的和地方的定价目录为依据。"},{"i":20,"n":"第二十条","txt":"国务院价格主管部门和其他有关部门，按照中央定价目录规定的定价权限和具体适用范围制定政府指导价、政府定价；其中重要的商品和服务价格的政府指导价、政府定价，应当按照规定经国务院批准。"},{"i":21,"n":"第二十一条","txt":"制定政府指导价、政府定价，应当依据有关商品或者服务的社会平均成本和市场供求状况、国民经济与社会发展要求以及社会承受能力，实行合理的购销差价、批零差价、地区差价和季节差价。"},{"i":22,"n":"第二十二条","txt":"政府价格主管部门和其他有关部门制定政府指导价、政府定价，应当开展价格、成本调查，听取消费者、经营者和有关方面的意见。"},{"i":23,"n":"第二十三条","txt":"制定关系群众切身利益的公用事业价格、公益性服务价格、自然垄断经营的商品价格等政府指导价、政府定价，应当建立听证会制度，由政府价格主管部门主持，征求消费者、经营者和有关方面的意见，论证其必要性、可行性。"},{"i":24,"n":"第二十四条","txt":"政府指导价、政府定价制定后，由制定价格的部门向消费者、经营者公布。"},{"i":25,"n":"第二十五条","txt":"政府指导价、政府定价的具体适用范围、价格水平，应当根据经济运行情况，按照规定的定价权限和程序适时调整。"},{"i":26,"n":"第二十六条","txt":"稳定市场价格总水平是国家重要的宏观经济政策目标。国家根据国民经济发展的需要和社会承受能力，确定市场价格总水平调控目标，列入国民经济和社会发展计划，并综合运用货币、财政、投资、进出口等方面的政策和措施，予以实现。"},{"i":27,"n":"第二十七条","txt":"政府可以建立重要商品储备制度，设立价格调节基金，调控价格，稳定市场。"},{"i":28,"n":"第二十八条","txt":"为适应价格调控和管理的需要，政府价格主管部门应当建立价格监测制度，对重要商品、服务价格的变动进行监测。"},{"i":29,"n":"第二十九条","txt":"政府在粮食等重要农产品的市场购买价格过低时，可以在收购中实行保护价格，并采取相应的经济措施保证其实现。"},{"i":30,"n":"第三十条","txt":"当重要商品和服务价格显著上涨或者有可能显著上涨，国务院和省、自治区、直辖市人民政府可以对部分价格采取限定差价率或者利润率、规定限价、实行提价申报制度和调价备案制度等干预措施。"},{"i":31,"n":"第三十一条","txt":"当市场价格总水平出现剧烈波动等异常状态时，国务院可以在全国范围内或者部分区域内采取临时集中定价权限、部分或者全面冻结价格的紧急措施。"},{"i":32,"n":"第三十二条","txt":"依照本法第三十条、第三十一条的规定实行干预措施、紧急措施的情形消除后，应当及时解除干预措施、紧急措施。"},{"i":33,"n":"第三十三条","txt":"县级以上各级人民政府价格主管部门，依法对价格活动进行监督检查，并依照本法的规定对价格违法行为实施行政处罚。"},{"i":34,"n":"第三十四条","txt":"政府价格主管部门进行价格监督检查时，可以行使下列职权；"},{"i":35,"n":"第三十五条","txt":"经营者接受政府价格主管部门的监督检查时，应当如实提供价格监督检查所必需的帐簿、单据、凭证、文件以及其他资料。"},{"i":36,"n":"第三十六条","txt":"政府部门价格工作人员不得将依法取得的资料或者了解的情况用于依法进行价格管理以外的任何其他目的，不得泄露当事人的商业秘密。"},{"i":37,"n":"第三十七条","txt":"消费者组织、职工价格监督组织、居民委员会、村民委员会等组织以及消费者，有权对价格行为进行社会监督。政府价格主管部门应当充分发挥群众的价格监督作用。"},{"i":38,"n":"第三十八条","txt":"政府价格主管部门应当建立对价格违法行为的举报制度。"},{"i":39,"n":"第三十九条","txt":"经营者不执行政府指导价、政府定价以及法定的价格干预措施、紧急措施的，责令改正，没收违法所得，可以并处违法所得五倍以下的罚款；没有违法所得的，可以处以罚款；情节严重的，责令停业整顿。"},{"i":40,"n":"第四十条","txt":"经营者有本法第十四条所列行为之一的，责令改正，没收违法所得，可以并处违法所得五倍以下的罚款；没有违法所得的，予以警告，可以并处罚款；情节严重的，责令停业整顿，或者由工商行政管理机关吊销营业执照。有关法律对本法第十四条所列行为的处罚及处罚机关另有规定的，可以依照有关法律的规定执行。"},{"i":41,"n":"第四十一条","txt":"经营者因价格违法行为致使消费者或者其他经营者多付价款的，应当退还多付部分；造成损害的，应当依法承担赔偿责任。"},{"i":42,"n":"第四十二条","txt":"经营者违反明码标价规定的，责令改正，没收违法所得，可以并处五千元以下的罚款。"},{"i":43,"n":"第四十三条","txt":"经营者被责令暂停相关营业而不停止的，或者转移、隐匿、销毁依法登记保存的财物的，处相关营业所得或者转移、隐匿、销毁的财物价值一倍以上三倍以下的罚款。"},{"i":44,"n":"第四十四条","txt":"拒绝按照规定提供监督检查所需资料或者提供虚假资料的，责令改正，予以警告；逾期不改正的，可以处以罚款。"},{"i":45,"n":"第四十五条","txt":"地方各级人民政府或者各级人民政府有关部门违反本法规定，超越定价权限和范围擅自制定、调整价格或者不执行法定的价格干预措施、紧急措施的，责令改正，并可以通报批评；对直接负责的主管人员和其他直接责任人员，依法给予行政处分。"},{"i":46,"n":"第四十六条","txt":"价格工作人员泄露国家秘密、商业秘密以及滥用职权、徇私舞弊、玩忽职守、索贿受贿，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。"},{"i":47,"n":"第四十七条","txt":"国家行政机关的收费，应当依法进行，严格控制收费项目，限定收费范围、标准。收费的具体管理办法由国务院另行制定。"},{"i":48,"n":"第四十八条","txt":"本法自1998年5月1日起施行。"}],"qiyeguoyouzichanfa":[{"i":1,"n":"第一条","txt":"为了维护国家基本经济制度，巩固和发展国有经济，加强对国有资产的保护，发挥国有经济在国民经济中的主导作用，促进社会主义市场经济发展，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称企业国有资产（以下称国有资产），是指国家对企业各种形式的出资所形成的权益。"},{"i":3,"n":"第三条","txt":"国有资产属于国家所有即全民所有。国务院代表国家行使国有资产所有权。"},{"i":4,"n":"第四条","txt":"国务院和地方人民政府依照法律、行政法规的规定，分别代表国家对国家出资企业履行出资人职责，享有出资人权益。"},{"i":5,"n":"第五条","txt":"本法所称国家出资企业，是指国家出资的国有独资企业、国有独资公司，以及国有资本控股公司、国有资本参股公司。"},{"i":6,"n":"第六条","txt":"国务院和地方人民政府应当按照政企分开、社会公共管理职能与国有资产出资人职能分开、不干预企业依法自主经营的原则，依法履行出资人职责。"},{"i":7,"n":"第七条","txt":"国家采取措施，推动国有资本向关系国民经济命脉和国家安全的重要行业和关键领域集中，优化国有经济布局和结构，推进国有企业的改革和发展，提高国有经济的整体素质，增强国有经济的控制力、影响力。"},{"i":8,"n":"第八条","txt":"国家建立健全与社会主义市场经济发展要求相适应的国有资产管理与监督体制，建立健全国有资产保值增值考核和责任追究制度，落实国有资产保值增值责任。"},{"i":9,"n":"第九条","txt":"国家建立健全国有资产基础管理制度。具体办法按照国务院的规定制定。"},{"i":10,"n":"第十条","txt":"国有资产受法律保护，任何单位和个人不得侵害。"},{"i":11,"n":"第十一条","txt":"国务院国有资产监督管理机构和地方人民政府按照国务院的规定设立的国有资产监督管理机构，根据本级人民政府的授权，代表本级人民政府对国家出资企业履行出资人职责。"},{"i":12,"n":"第十二条","txt":"履行出资人职责的机构代表本级人民政府对国家出资企业依法享有资产收益、参与重大决策和选择管理者等出资人权利。"},{"i":13,"n":"第十三条","txt":"履行出资人职责的机构委派的股东代表参加国有资本控股公司、国有资本参股公司召开的股东会会议、股东大会会议，应当按照委派机构的指示提出提案、发表意见、行使表决权，并将其履行职责的情况和结果及时报告委派机构。"},{"i":14,"n":"第十四条","txt":"履行出资人职责的机构应当依照法律、行政法规以及企业章程履行出资人职责，保障出资人权益，防止国有资产损失。"},{"i":15,"n":"第十五条","txt":"履行出资人职责的机构对本级人民政府负责，向本级人民政府报告履行出资人职责的情况，接受本级人民政府的监督和考核，对国有资产的保值增值负责。"},{"i":16,"n":"第十六条","txt":"国家出资企业对其动产、不动产和其他财产依照法律、行政法规以及企业章程享有占有、使用、收益和处分的权利。"},{"i":17,"n":"第十七条","txt":"国家出资企业从事经营活动，应当遵守法律、行政法规，加强经营管理，提高经济效益，接受人民政府及其有关部门、机构依法实施的管理和监督，接受社会公众的监督，承担社会责任，对出资人负责。"},{"i":18,"n":"第十八条","txt":"国家出资企业应当依照法律、行政法规和国务院财政部门的规定，建立健全财务、会计制度，设置会计账簿，进行会计核算，依照法律、行政法规以及企业章程的规定向出资人提供真实、完整的财务、会计信息。"},{"i":19,"n":"第十九条","txt":"国有独资公司、国有资本控股公司和国有资本参股公司依照《中华人民共和国公司法》的规定设立监事会。国有独资企业由履行出资人职责的机构按照国务院的规定委派监事组成监事会。"},{"i":20,"n":"第二十条","txt":"国家出资企业依照法律规定，通过职工代表大会或者其他形式，实行民主管理。"},{"i":21,"n":"第二十一条","txt":"国家出资企业对其所出资企业依法享有资产收益、参与重大决策和选择管理者等出资人权利。"},{"i":22,"n":"第二十二条","txt":"履行出资人职责的机构依照法律、行政法规以及企业章程的规定，任免或者建议任免国家出资企业的下列人员："},{"i":23,"n":"第二十三条","txt":"履行出资人职责的机构任命或者建议任命的董事、监事、高级管理人员，应当具备下列条件："},{"i":24,"n":"第二十四条","txt":"履行出资人职责的机构对拟任命或者建议任命的董事、监事、高级管理人员的人选，应当按照规定的条件和程序进行考察。考察合格的，按照规定的权限和程序任命或者建议任命。"},{"i":25,"n":"第二十五条","txt":"未经履行出资人职责的机构同意，国有独资企业、国有独资公司的董事、高级管理人员不得在其他企业兼职。未经股东会、股东大会同意，国有资本控股公司、国有资本参股公司的董事、高级管理人员不得在经营同类业务的其他企业兼职。"},{"i":26,"n":"第二十六条","txt":"国家出资企业的董事、监事、高级管理人员，应当遵守法律、行政法规以及企业章程，对企业负有忠实义务和勤勉义务，不得利用职权收受贿赂或者取得其他非法收入和不当利益，不得侵占、挪用企业资产，不得超越职权或者违反程序决定企业重大事项，不得有其他侵害国有资产出资人权益的行为。"},{"i":27,"n":"第二十七条","txt":"国家建立国家出资企业管理者经营业绩考核制度。履行出资人职责的机构应当对其任命的企业管理者进行年度和任期考核，并依据考核结果决定对企业管理者的奖惩。"},{"i":28,"n":"第二十八条","txt":"国有独资企业、国有独资公司和国有资本控股公司的主要负责人，应当接受依法进行的任期经济责任审计。"},{"i":29,"n":"第二十九条","txt":"本法第二十二条第一款第一项、第二项规定的企业管理者，国务院和地方人民政府规定由本级人民政府任免的，依照其规定。履行出资人职责的机构依照本章规定对上述企业管理者进行考核、奖惩并确定其薪酬标准。"},{"i":30,"n":"第三十条","txt":"国家出资企业合并、分立、改制、上市，增加或者减少注册资本，发行债券，进行重大投资，为他人提供大额担保，转让重大财产，进行大额捐赠，分配利润，以及解散、申请破产等重大事项，应当遵守法律、行政法规以及企业章程的规定，不得损害出资人和债权人的权益。"},{"i":31,"n":"第三十一条","txt":"国有独资企业、国有独资公司合并、分立，增加或者减少注册资本，发行债券，分配利润，以及解散、申请破产，由履行出资人职责的机构决定。"},{"i":32,"n":"第三十二条","txt":"国有独资企业、国有独资公司有本法第三十条所列事项的，除依照本法第三十一条和有关法律、行政法规以及企业章程的规定，由履行出资人职责的机构决定的以外，国有独资企业由企业负责人集体讨论决定，国有独资公司由董事会决定。"},{"i":33,"n":"第三十三条","txt":"国有资本控股公司、国有资本参股公司有本法第三十条所列事项的，依照法律、行政法规以及公司章程的规定，由公司股东会、股东大会或者董事会决定。由股东会、股东大会决定的，履行出资人职责的机构委派的股东代表应当依照本法第十三条的规定行使权利。"},{"i":34,"n":"第三十四条","txt":"重要的国有独资企业、国有独资公司、国有资本控股公司的合并、分立、解散、申请破产以及法律、行政法规和本级人民政府规定应当由履行出资人职责的机构报经本级人民政府批准的重大事项，履行出资人职责的机构在作出决定或者向其委派参加国有资本控股公司股东会会议、股东大会会议的股东代表作出指示前，应当报请本级人民政府批准。"},{"i":35,"n":"第三十五条","txt":"国家出资企业发行债券、投资等事项，有关法律、行政法规规定应当报经人民政府或者人民政府有关部门、机构批准、核准或者备案的，依照其规定。"},{"i":36,"n":"第三十六条","txt":"国家出资企业投资应当符合国家产业政策，并按照国家规定进行可行性研究；与他人交易应当公平、有偿，取得合理对价。"},{"i":37,"n":"第三十七条","txt":"国家出资企业的合并、分立、改制、解散、申请破产等重大事项，应当听取企业工会的意见，并通过职工代表大会或者其他形式听取职工的意见和建议。"},{"i":38,"n":"第三十八条","txt":"国有独资企业、国有独资公司、国有资本控股公司对其所出资企业的重大事项参照本章规定履行出资人职责。具体办法由国务院规定。"},{"i":39,"n":"第三十九条","txt":"本法所称企业改制是指："},{"i":40,"n":"第四十条","txt":"企业改制应当依照法定程序，由履行出资人职责的机构决定或者由公司股东会、股东大会决定。"},{"i":41,"n":"第四十一条","txt":"企业改制应当制定改制方案，载明改制后的企业组织形式、企业资产和债权债务处理方案、股权变动方案、改制的操作程序、资产评估和财务审计等中介机构的选聘等事项。"},{"i":42,"n":"第四十二条","txt":"企业改制应当按照规定进行清产核资、财务审计、资产评估，准确界定和核实资产，客观、公正地确定资产的价值。"},{"i":43,"n":"第四十三条","txt":"国家出资企业的关联方不得利用与国家出资企业之间的交易，谋取不当利益，损害国家出资企业利益。"},{"i":44,"n":"第四十四条","txt":"国有独资企业、国有独资公司、国有资本控股公司不得无偿向关联方提供资金、商品、服务或者其他资产，不得以不公平的价格与关联方进行交易。"},{"i":45,"n":"第四十五条","txt":"未经履行出资人职责的机构同意，国有独资企业、国有独资公司不得有下列行为："},{"i":46,"n":"第四十六条","txt":"国有资本控股公司、国有资本参股公司与关联方的交易，依照《中华人民共和国公司法》和有关行政法规以及公司章程的规定，由公司股东会、股东大会或者董事会决定。由公司股东会、股东大会决定的，履行出资人职责的机构委派的股东代表，应当依照本法第十三条的规定行使权利。"},{"i":47,"n":"第四十七条","txt":"国有独资企业、国有独资公司和国有资本控股公司合并、分立、改制，转让重大财产，以非货币财产对外投资，清算或者有法律、行政法规以及企业章程规定应当进行资产评估的其他情形的，应当按照规定对有关资产进行评估。"},{"i":48,"n":"第四十八条","txt":"国有独资企业、国有独资公司和国有资本控股公司应当委托依法设立的符合条件的资产评估机构进行资产评估；涉及应当报经履行出资人职责的机构决定的事项的，应当将委托资产评估机构的情况向履行出资人职责的机构报告。"},{"i":49,"n":"第四十九条","txt":"国有独资企业、国有独资公司、国有资本控股公司及其董事、监事、高级管理人员应当向资产评估机构如实提供有关情况和资料，不得与资产评估机构串通评估作价。"},{"i":50,"n":"第五十条","txt":"资产评估机构及其工作人员受托评估有关资产，应当遵守法律、行政法规以及评估执业准则，独立、客观、公正地对受托评估的资产进行评估。资产评估机构应当对其出具的评估报告负责。"},{"i":51,"n":"第五十一条","txt":"本法所称国有资产转让，是指依法将国家对企业的出资所形成的权益转移给其他单位或者个人的行为；按照国家规定无偿划转国有资产的除外。"},{"i":52,"n":"第五十二条","txt":"国有资产转让应当有利于国有经济布局和结构的战略性调整，防止国有资产损失，不得损害交易各方的合法权益。"},{"i":53,"n":"第五十三条","txt":"国有资产转让由履行出资人职责的机构决定。履行出资人职责的机构决定转让全部国有资产的，或者转让部分国有资产致使国家对该企业不再具有控股地位的，应当报请本级人民政府批准。"},{"i":54,"n":"第五十四条","txt":"国有资产转让应当遵循等价有偿和公开、公平、公正的原则。"},{"i":55,"n":"第五十五条","txt":"国有资产转让应当以依法评估的、经履行出资人职责的机构认可或者由履行出资人职责的机构报经本级人民政府核准的价格为依据，合理确定最低转让价格。"},{"i":56,"n":"第五十六条","txt":"法律、行政法规或者国务院国有资产监督管理机构规定可以向本企业的董事、监事、高级管理人员或者其近亲属，或者这些人员所有或者实际控制的企业转让的国有资产，在转让时，上述人员或者企业参与受让的，应当与其他受让参与者平等竞买；转让方应当按照国家有关规定，如实披露有关信息；相关的董事、监事和高级管理人员不得参与转让方案的制定和组织实施的各项工作。"},{"i":57,"n":"第五十七条","txt":"国有资产向境外投资者转让的，应当遵守国家有关规定，不得危害国家安全和社会公共利益。"},{"i":58,"n":"第五十八条","txt":"国家建立健全国有资本经营预算制度，对取得的国有资本收入及其支出实行预算管理。"},{"i":59,"n":"第五十九条","txt":"国家取得的下列国有资本收入，以及下列收入的支出，应当编制国有资本经营预算："},{"i":60,"n":"第六十条","txt":"国有资本经营预算按年度单独编制，纳入本级人民政府预算，报本级人民代表大会批准。"},{"i":61,"n":"第六十一条","txt":"国务院和有关地方人民政府财政部门负责国有资本经营预算草案的编制工作，履行出资人职责的机构向财政部门提出由其履行出资人职责的国有资本经营预算建议草案。"},{"i":62,"n":"第六十二条","txt":"国有资本经营预算管理的具体办法和实施步骤，由国务院规定，报全国人民代表大会常务委员会备案。"},{"i":63,"n":"第六十三条","txt":"各级人民代表大会常务委员会通过听取和审议本级人民政府履行出资人职责的情况和国有资产监督管理情况的专项工作报告，组织对本法实施情况的执法检查等，依法行使监督职权。"},{"i":64,"n":"第六十四条","txt":"国务院和地方人民政府应当对其授权履行出资人职责的机构履行职责的情况进行监督。"},{"i":65,"n":"第六十五条","txt":"国务院和地方人民政府审计机关依照《中华人民共和国审计法》的规定，对国有资本经营预算的执行情况和属于审计监督对象的国家出资企业进行审计监督。"},{"i":66,"n":"第六十六条","txt":"国务院和地方人民政府应当依法向社会公布国有资产状况和国有资产监督管理工作情况，接受社会公众的监督。"},{"i":67,"n":"第六十七条","txt":"履行出资人职责的机构根据需要，可以委托会计师事务所对国有独资企业、国有独资公司的年度财务会计报告进行审计，或者通过国有资本控股公司的股东会、股东大会决议，由国有资本控股公司聘请会计师事务所对公司的年度财务会计报告进行审计，维护出资人权益。"},{"i":68,"n":"第六十八条","txt":"履行出资人职责的机构有下列行为之一的，对其直接负责的主管人员和其他直接责任人员依法给予处分："},{"i":69,"n":"第六十九条","txt":"履行出资人职责的机构的工作人员玩忽职守、滥用职权、徇私舞弊，尚不构成犯罪的，依法给予处分。"},{"i":70,"n":"第七十条","txt":"履行出资人职责的机构委派的股东代表未按照委派机构的指示履行职责，造成国有资产损失的，依法承担赔偿责任；属于国家工作人员的，并依法给予处分。"},{"i":71,"n":"第七十一条","txt":"国家出资企业的董事、监事、高级管理人员有下列行为之一，造成国有资产损失的，依法承担赔偿责任；属于国家工作人员的，并依法给予处分："},{"i":72,"n":"第七十二条","txt":"在涉及关联方交易、国有资产转让等交易活动中，当事人恶意串通，损害国有资产权益的，该交易行为无效。"},{"i":73,"n":"第七十三条","txt":"国有独资企业、国有独资公司、国有资本控股公司的董事、监事、高级管理人员违反本法规定，造成国有资产重大损失，被免职的，自免职之日起五年内不得担任国有独资企业、国有独资公司、国有资本控股公司的董事、监事、高级管理人员；造成国有资产特别重大损失，或者因贪污、贿赂、侵占财产、挪用财产或者破坏社会主义市场经济秩序被判处刑罚的，终身不得担任国有独资企业、国有独资公司、国有资本控股公司的董事、监事、高级管理人员。"},{"i":74,"n":"第七十四条","txt":"接受委托对国家出资企业进行资产评估、财务审计的资产评估机构、会计师事务所违反法律、行政法规的规定和执业准则，出具虚假的资产评估报告或者审计报告的，依照有关法律、行政法规的规定追究法律责任。"},{"i":75,"n":"第七十五条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":76,"n":"第七十六条","txt":"金融企业国有资产的管理与监督，法律、行政法规另有规定的，依照其规定。"},{"i":77,"n":"第七十七条","txt":"本法自2009年5月1日起施行。"}],"qiyesuodeshuifa":[{"i":1,"n":"第一条","txt":"在中华人民共和国境内，企业和其他取得收入的组织（以下统称企业）为企业所得税的纳税人，依照本法的规定缴纳企业所得税。"},{"i":2,"n":"第二条","txt":"企业分为居民企业和非居民企业。"},{"i":3,"n":"第三条","txt":"居民企业应当就其来源于中国境内、境外的所得缴纳企业所得税。"},{"i":4,"n":"第四条","txt":"企业所得税的税率为25％。"},{"i":5,"n":"第五条","txt":"企业每一纳税年度的收入总额，减除不征税收入、免税收入、各项扣除以及允许弥补的以前年度亏损后的余额，为应纳税所得额。"},{"i":6,"n":"第六条","txt":"企业以货币形式和非货币形式从各种来源取得的收入，为收入总额。包括："},{"i":7,"n":"第七条","txt":"收入总额中的下列收入为不征税收入："},{"i":8,"n":"第八条","txt":"企业实际发生的与取得收入有关的、合理的支出，包括成本、费用、税金、损失和其他支出，准予在计算应纳税所得额时扣除。"},{"i":9,"n":"第九条","txt":"企业发生的公益性捐赠支出，在年度利润总额12％以内的部分，准予在计算应纳税所得额时扣除；超过年度利润总额12％的部分，准予结转以后三年内在计算应纳税所得额时扣除。"},{"i":10,"n":"第十条","txt":"在计算应纳税所得额时，下列支出不得扣除："},{"i":11,"n":"第十一条","txt":"在计算应纳税所得额时，企业按照规定计算的固定资产折旧，准予扣除。"},{"i":12,"n":"第十二条","txt":"在计算应纳税所得额时，企业按照规定计算的无形资产摊销费用，准予扣除。"},{"i":13,"n":"第十三条","txt":"在计算应纳税所得额时，企业发生的下列支出作为长期待摊费用，按照规定摊销的，准予扣除："},{"i":14,"n":"第十四条","txt":"企业对外投资期间，投资资产的成本在计算应纳税所得额时不得扣除。"},{"i":15,"n":"第十五条","txt":"企业使用或者销售存货，按照规定计算的存货成本，准予在计算应纳税所得额时扣除。"},{"i":16,"n":"第十六条","txt":"企业转让资产，该项资产的净值，准予在计算应纳税所得额时扣除。"},{"i":17,"n":"第十七条","txt":"企业在汇总计算缴纳企业所得税时，其境外营业机构的亏损不得抵减境内营业机构的盈利。"},{"i":18,"n":"第十八条","txt":"企业纳税年度发生的亏损，准予向以后年度结转，用以后年度的所得弥补，但结转年限最长不得超过五年。"},{"i":19,"n":"第十九条","txt":"非居民企业取得本法第三条第三款规定的所得，按照下列方法计算其应纳税所得额："},{"i":20,"n":"第二十条","txt":"本章规定的收入、扣除的具体范围、标准和资产的税务处理的具体办法，由国务院财政、税务主管部门规定。"},{"i":21,"n":"第二十一条","txt":"在计算应纳税所得额时，企业财务、会计处理办法与税收法律、行政法规的规定不一致的，应当依照税收法律、行政法规的规定计算。"},{"i":22,"n":"第二十二条","txt":"企业的应纳税所得额乘以适用税率，减除依照本法关于税收优惠的规定减免和抵免的税额后的余额，为应纳税额。"},{"i":23,"n":"第二十三条","txt":"企业取得的下列所得已在境外缴纳的所得税税额，可以从其当期应纳税额中抵免，抵免限额为该项所得依照本法规定计算的应纳税额；超过抵免限额的部分，可以在以后五个年度内，用每年度抵免限额抵免当年应抵税额后的余额进行抵补："},{"i":24,"n":"第二十四条","txt":"居民企业从其直接或者间接控制的外国企业分得的来源于中国境外的股息、红利等权益性投资收益，外国企业在境外实际缴纳的所得税税额中属于该项所得负担的部分，可以作为该居民企业的可抵免境外所得税税额，在本法第二十三条规定的抵免限额内抵免。"},{"i":25,"n":"第二十五条","txt":"国家对重点扶持和鼓励发展的产业和项目，给予企业所得税优惠。"},{"i":26,"n":"第二十六条","txt":"企业的下列收入为免税收入："},{"i":27,"n":"第二十七条","txt":"企业的下列所得，可以免征、减征企业所得税："},{"i":28,"n":"第二十八条","txt":"符合条件的小型微利企业，减按20％的税率征收企业所得税。"},{"i":29,"n":"第二十九条","txt":"民族自治地方的自治机关对本民族自治地方的企业应缴纳的企业所得税中属于地方分享的部分，可以决定减征或者免征。自治州、自治县决定减征或者免征的，须报省、自治区、直辖市人民政府批准。"},{"i":30,"n":"第三十条","txt":"企业的下列支出，可以在计算应纳税所得额时加计扣除："},{"i":31,"n":"第三十一条","txt":"创业投资企业从事国家需要重点扶持和鼓励的创业投资，可以按投资额的一定比例抵扣应纳税所得额。"},{"i":32,"n":"第三十二条","txt":"企业的固定资产由于技术进步等原因，确需加速折旧的，可以缩短折旧年限或者采取加速折旧的方法。"},{"i":33,"n":"第三十三条","txt":"企业综合利用资源，生产符合国家产业政策规定的产品所取得的收入，可以在计算应纳税所得额时减计收入。"},{"i":34,"n":"第三十四条","txt":"企业购置用于环境保护、节能节水、安全生产等专用设备的投资额，可以按一定比例实行税额抵免。"},{"i":35,"n":"第三十五条","txt":"本法规定的税收优惠的具体办法，由国务院规定。"},{"i":36,"n":"第三十六条","txt":"根据国民经济和社会发展的需要，或者由于突发事件等原因对企业经营活动产生重大影响的，国务院可以制定企业所得税专项优惠政策，报全国人民代表大会常务委员会备案。"},{"i":37,"n":"第三十七条","txt":"对非居民企业取得本法第三条第三款规定的所得应缴纳的所得税，实行源泉扣缴，以支付人为扣缴义务人。税款由扣缴义务人在每次支付或者到期应支付时，从支付或者到期应支付的款项中扣缴。"},{"i":38,"n":"第三十八条","txt":"对非居民企业在中国境内取得工程作业和劳务所得应缴纳的所得税，税务机关可以指定工程价款或者劳务费的支付人为扣缴义务人。"},{"i":39,"n":"第三十九条","txt":"依照本法第三十七条、第三十八条规定应当扣缴的所得税，扣缴义务人未依法扣缴或者无法履行扣缴义务的，由纳税人在所得发生地缴纳。纳税人未依法缴纳的，税务机关可以从该纳税人在中国境内其他收入项目的支付人应付的款项中，追缴该纳税人的应纳税款。"},{"i":40,"n":"第四十条","txt":"扣缴义务人每次代扣的税款，应当自代扣之日起七日内缴入国库，并向所在地的税务机关报送扣缴企业所得税报告表。"},{"i":41,"n":"第四十一条","txt":"企业与其关联方之间的业务往来，不符合独立交易原则而减少企业或者其关联方应纳税收入或者所得额的，税务机关有权按照合理方法调整。"},{"i":42,"n":"第四十二条","txt":"企业可以向税务机关提出与其关联方之间业务往来的定价原则和计算方法，税务机关与企业协商、确认后，达成预约定价安排。"},{"i":43,"n":"第四十三条","txt":"企业向税务机关报送年度企业所得税纳税申报表时，应当就其与关联方之间的业务往来，附送年度关联业务往来报告表。"},{"i":44,"n":"第四十四条","txt":"企业不提供与其关联方之间业务往来资料，或者提供虚假、不完整资料，未能真实反映其关联业务往来情况的，税务机关有权依法核定其应纳税所得额。"},{"i":45,"n":"第四十五条","txt":"由居民企业，或者由居民企业和中国居民控制的设立在实际税负明显低于本法第四条第一款规定税率水平的国家（地区）的企业，并非由于合理的经营需要而对利润不作分配或者减少分配的，上述利润中应归属于该居民企业的部分，应当计入该居民企业的当期收入。"},{"i":46,"n":"第四十六条","txt":"企业从其关联方接受的债权性投资与权益性投资的比例超过规定标准而发生的利息支出，不得在计算应纳税所得额时扣除。"},{"i":47,"n":"第四十七条","txt":"企业实施其他不具有合理商业目的的安排而减少其应纳税收入或者所得额的，税务机关有权按照合理方法调整。"},{"i":48,"n":"第四十八条","txt":"税务机关依照本章规定作出纳税调整，需要补征税款的，应当补征税款，并按照国务院规定加收利息。"},{"i":49,"n":"第四十九条","txt":"企业所得税的征收管理除本法规定外，依照《中华人民共和国税收征收管理法》的规定执行。"},{"i":50,"n":"第五十条","txt":"除税收法律、行政法规另有规定外，居民企业以企业登记注册地为纳税地点；但登记注册地在境外的，以实际管理机构所在地为纳税地点。"},{"i":51,"n":"第五十一条","txt":"非居民企业取得本法第三条第二款规定的所得，以机构、场所所在地为纳税地点。非居民企业在中国境内设立两个或者两个以上机构、场所，符合国务院税务主管部门规定条件的，可以选择由其主要机构、场所汇总缴纳企业所得税。"},{"i":52,"n":"第五十二条","txt":"除国务院另有规定外，企业之间不得合并缴纳企业所得税。"},{"i":53,"n":"第五十三条","txt":"企业所得税按纳税年度计算。纳税年度自公历1月1日起至12月31日止。"},{"i":54,"n":"第五十四条","txt":"企业所得税分月或者分季预缴。"},{"i":55,"n":"第五十五条","txt":"企业在年度中间终止经营活动的，应当自实际经营终止之日起六十日内，向税务机关办理当期企业所得税汇算清缴。"},{"i":56,"n":"第五十六条","txt":"依照本法缴纳的企业所得税，以人民币计算。所得以人民币以外的货币计算的，应当折合成人民币计算并缴纳税款。"},{"i":57,"n":"第五十七条","txt":"本法公布前已经批准设立的企业，依照当时的税收法律、行政法规规定，享受低税率优惠的，按照国务院规定，可以在本法施行后五年内，逐步过渡到本法规定的税率；享受定期减免税优惠的，按照国务院规定，可以在本法施行后继续享受到期满为止，但因未获利而尚未享受优惠的，优惠期限从本法施行年度起计算。"},{"i":58,"n":"第五十八条","txt":"中华人民共和国政府同外国政府订立的有关税收的协定与本法有不同规定的，依照协定的规定办理。"},{"i":59,"n":"第五十九条","txt":"国务院根据本法制定实施条例。"},{"i":60,"n":"第六十条","txt":"本法自2008年1月1日起施行。1991年4月9日第七届全国人民代表大会第四次会议通过的《中华人民共和国外商投资企业和外国企业所得税法》和1993年12月13日国务院发布的《中华人民共和国企业所得税暂行条例》同时废止。"}],"kuaijifa":[{"i":1,"n":"第一条","txt":"为了规范会计行为，保证会计资料真实、完整，加强经济管理和财务管理，提高经济效益，维护社会主义市场经济秩序，制定本法。"},{"i":2,"n":"第二条","txt":"会计工作应当贯彻落实党和国家路线方针政策、决策部署，维护社会公共利益，为国民经济和社会发展服务。"},{"i":3,"n":"第三条","txt":"各单位必须依法设置会计账簿，并保证其真实、完整。"},{"i":4,"n":"第四条","txt":"单位负责人对本单位的会计工作和会计资料的真实性、完整性负责。"},{"i":5,"n":"第五条","txt":"会计机构、会计人员依照本法规定进行会计核算，实行会计监督。"},{"i":6,"n":"第六条","txt":"对认真执行本法，忠于职守，坚持原则，做出显著成绩的会计人员，给予精神的或者物质的奖励。"},{"i":7,"n":"第七条","txt":"国务院财政部门主管全国的会计工作。"},{"i":8,"n":"第八条","txt":"国家实行统一的会计制度。国家统一的会计制度由国务院财政部门根据本法制定并公布。"},{"i":9,"n":"第九条","txt":"各单位必须根据实际发生的经济业务事项进行会计核算，填制会计凭证，登记会计账簿，编制财务会计报告。"},{"i":10,"n":"第十条","txt":"各单位应当对下列经济业务事项办理会计手续，进行会计核算："},{"i":11,"n":"第十一条","txt":"会计年度自公历1月1日起至12月31日止。"},{"i":12,"n":"第十二条","txt":"会计核算以人民币为记账本位币。"},{"i":13,"n":"第十三条","txt":"会计凭证、会计账簿、财务会计报告和其他会计资料，必须符合国家统一的会计制度的规定。"},{"i":14,"n":"第十四条","txt":"会计凭证包括原始凭证和记账凭证。"},{"i":15,"n":"第十五条","txt":"会计账簿登记，必须以经过审核的会计凭证为依据，并符合有关法律、行政法规和国家统一的会计制度的规定。会计账簿包括总账、明细账、日记账和其他辅助性账簿。"},{"i":16,"n":"第十六条","txt":"各单位发生的各项经济业务事项应当在依法设置的会计账簿上统一登记、核算，不得违反本法和国家统一的会计制度的规定私设会计账簿登记、核算。"},{"i":17,"n":"第十七条","txt":"各单位应当定期将会计账簿记录与实物、款项及有关资料相互核对，保证会计账簿记录与实物及款项的实有数额相符、会计账簿记录与会计凭证的有关内容相符、会计账簿之间相对应的记录相符、会计账簿记录与会计报表的有关内容相符。"},{"i":18,"n":"第十八条","txt":"各单位采用的会计处理方法，前后各期应当一致，不得随意变更；确有必要变更的，应当按照国家统一的会计制度的规定变更，并将变更的原因、情况及影响在财务会计报告中说明。"},{"i":19,"n":"第十九条","txt":"单位提供的担保、未决诉讼等或有事项，应当按照国家统一的会计制度的规定，在财务会计报告中予以说明。"},{"i":20,"n":"第二十条","txt":"财务会计报告应当根据经过审核的会计账簿记录和有关资料编制，并符合本法和国家统一的会计制度关于财务会计报告的编制要求、提供对象和提供期限的规定；其他法律、行政法规另有规定的，从其规定。"},{"i":21,"n":"第二十一条","txt":"财务会计报告应当由单位负责人和主管会计工作的负责人、会计机构负责人（会计主管人员）签名并盖章；设置总会计师的单位，还须由总会计师签名并盖章。"},{"i":22,"n":"第二十二条","txt":"会计记录的文字应当使用中文。在民族自治地方，会计记录可以同时使用当地通用的一种民族文字。在中华人民共和国境内的外商投资企业、外国企业和其他外国组织的会计记录可以同时使用一种外国文字。"},{"i":23,"n":"第二十三条","txt":"各单位对会计凭证、会计账簿、财务会计报告和其他会计资料应当建立档案，妥善保管。会计档案的保管期限、销毁、安全保护等具体管理办法，由国务院财政部门会同有关部门制定。"},{"i":24,"n":"第二十四条","txt":"各单位进行会计核算不得有下列行为："},{"i":25,"n":"第二十五条","txt":"各单位应当建立、健全本单位内部会计监督制度，并将其纳入本单位内部控制制度。单位内部会计监督制度应当符合下列要求："},{"i":26,"n":"第二十六条","txt":"单位负责人应当保证会计机构、会计人员依法履行职责，不得授意、指使、强令会计机构、会计人员违法办理会计事项。"},{"i":27,"n":"第二十七条","txt":"会计机构、会计人员发现会计账簿记录与实物、款项及有关资料不相符的，按照国家统一的会计制度的规定有权自行处理的，应当及时处理；无权处理的，应当立即向单位负责人报告，请求查明原因，作出处理。"},{"i":28,"n":"第二十八条","txt":"任何单位和个人对违反本法和国家统一的会计制度规定的行为，有权检举。收到检举的部门有权处理的，应当依法按照职责分工及时处理；无权处理的，应当及时移送有权处理的部门处理。收到检举的部门、负责处理的部门应当为检举人保密，不得将检举人姓名和检举材料转给被检举单位和被检举人个人。"},{"i":29,"n":"第二十九条","txt":"有关法律、行政法规规定，须经注册会计师进行审计的单位，应当向受委托的会计师事务所如实提供会计凭证、会计账簿、财务会计报告和其他会计资料以及有关情况。"},{"i":30,"n":"第三十条","txt":"财政部门对各单位的下列情况实施监督："},{"i":31,"n":"第三十一条","txt":"财政、审计、税务、金融管理等部门应当依照有关法律、行政法规规定的职责，对有关单位的会计资料实施监督检查，并出具检查结论。"},{"i":32,"n":"第三十二条","txt":"依法对有关单位的会计资料实施监督检查的部门及其工作人员对在监督检查中知悉的国家秘密、工作秘密、商业秘密、个人隐私、个人信息负有保密义务。"},{"i":33,"n":"第三十三条","txt":"各单位必须依照有关法律、行政法规的规定，接受有关监督检查部门依法实施的监督检查，如实提供会计凭证、会计账簿、财务会计报告和其他会计资料以及有关情况，不得拒绝、隐匿、谎报。"},{"i":34,"n":"第三十四条","txt":"各单位应当根据会计业务的需要，依法采取下列一种方式组织本单位的会计工作："},{"i":35,"n":"第三十五条","txt":"会计机构内部应当建立稽核制度。"},{"i":36,"n":"第三十六条","txt":"会计人员应当具备从事会计工作所需要的专业能力。"},{"i":37,"n":"第三十七条","txt":"会计人员应当遵守职业道德，提高业务素质，严格遵守国家有关保密规定。对会计人员的教育和培训工作应当加强。"},{"i":38,"n":"第三十八条","txt":"因有提供虚假财务会计报告，做假账，隐匿或者故意销毁会计凭证、会计账簿、财务会计报告，贪污，挪用公款，职务侵占等与会计职务有关的违法行为被依法追究刑事责任的人员，不得再从事会计工作。"},{"i":39,"n":"第三十九条","txt":"会计人员调动工作或者离职，必须与接管人员办清交接手续。"},{"i":40,"n":"第四十条","txt":"违反本法规定，有下列行为之一的，由县级以上人民政府财政部门责令限期改正，给予警告、通报批评，对单位可以并处二十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员可以处五万元以下的罚款；情节严重的，对单位可以并处二十万元以上一百万元以下的罚款，对其直接负责的主管人员和其他直接责任人员可以处五万元以上五十万元以下的罚款；属于公职人员的，还应当依法给予处分："},{"i":41,"n":"第四十一条","txt":"伪造、变造会计凭证、会计账簿，编制虚假财务会计报告，隐匿或者故意销毁依法应当保存的会计凭证、会计账簿、财务会计报告的，由县级以上人民政府财政部门责令限期改正，给予警告、通报批评，没收违法所得，违法所得二十万元以上的，对单位可以并处违法所得一倍以上十倍以下的罚款，没有违法所得或者违法所得不足二十万元的，可以并处二十万元以上二百万元以下的罚款；对其直接负责的主管人员和其他直接责任人员可以处十万元以上五十万元以下的罚款，情节严重的，可以处五十万元以上二百万元以下的罚款；属于公职人员的，还应当依法给予处分；其中的会计人员，五年内不得从事会计工作；构成犯罪的，依法追究刑事责任。"},{"i":42,"n":"第四十二条","txt":"授意、指使、强令会计机构、会计人员及其他人员伪造、变造会计凭证、会计账簿，编制虚假财务会计报告或者隐匿、故意销毁依法应当保存的会计凭证、会计账簿、财务会计报告的，由县级以上人民政府财政部门给予警告、通报批评，可以并处二十万元以上一百万元以下的罚款；情节严重的，可以并处一百万元以上五百万元以下的罚款；属于公职人员的，还应当依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":43,"n":"第四十三条","txt":"单位负责人对依法履行职责、抵制违反本法规定行为的会计人员以降级、撤职、调离工作岗位、解聘或者开除等方式实行打击报复的，依法给予处分；构成犯罪的，依法追究刑事责任。对受打击报复的会计人员，应当恢复其名誉和原有职务、级别。"},{"i":44,"n":"第四十四条","txt":"财政部门及有关行政部门的工作人员在实施监督管理中滥用职权、玩忽职守、徇私舞弊或者泄露国家秘密、工作秘密、商业秘密、个人隐私、个人信息的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":45,"n":"第四十五条","txt":"违反本法规定，将检举人姓名和检举材料转给被检举单位和被检举人个人的，依法给予处分。"},{"i":46,"n":"第四十六条","txt":"违反本法规定，但具有《中华人民共和国行政处罚法》规定的从轻、减轻或者不予处罚情形的，依照其规定从轻、减轻或者不予处罚。"},{"i":47,"n":"第四十七条","txt":"因违反本法规定受到处罚的，按照国家有关规定记入信用记录。"},{"i":48,"n":"第四十八条","txt":"本法下列用语的含义："},{"i":49,"n":"第四十九条","txt":"中央军事委员会有关部门可以依照本法和国家统一的会计制度制定军队实施国家统一的会计制度的具体办法，抄送国务院财政部门。"},{"i":50,"n":"第五十条","txt":"个体工商户会计管理的具体办法，由国务院财政部门根据本法的原则另行规定。"},{"i":51,"n":"第五十一条","txt":"本法自2000年7月1日起施行。"}],"gonglufa":[{"i":1,"n":"第一条","txt":"为了加强公路的建设和管理，促进公路事业的发展，适应社会主义现代化建设和人民生活的需要，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事公路的规划、建设、养护、经营、使用和管理，适用本法。"},{"i":3,"n":"第三条","txt":"公路的发展应当遵循全面规划、合理布局、确保质量、保障畅通、保护环境、建设改造与养护并重的原则。"},{"i":4,"n":"第四条","txt":"各级人民政府应当采取有力措施，扶持、促进公路建设。公路建设应当纳入国民经济和社会发展计划。"},{"i":5,"n":"第五条","txt":"国家帮助和扶持少数民族地区、边远地区和贫困地区发展公路建设。"},{"i":6,"n":"第六条","txt":"公路按其在公路路网中的地位分为国道、省道、县道和乡道，并按技术等级分为高速公路、一级公路、二级公路、三级公路和四级公路。具体划分标准由国务院交通主管部门规定。"},{"i":7,"n":"第七条","txt":"公路受国家保护，任何单位和个人不得破坏、损坏或者非法占用公路、公路用地及公路附属设施。"},{"i":8,"n":"第八条","txt":"国务院交通主管部门主管全国公路工作。"},{"i":9,"n":"第九条","txt":"禁止任何单位和个人在公路上非法设卡、收费、罚款和拦截车辆。"},{"i":10,"n":"第十条","txt":"国家鼓励公路工作方面的科学技术研究，对在公路科学技术研究和应用方面作出显著成绩的单位和个人给予奖励。"},{"i":11,"n":"第十一条","txt":"本法对专用公路有规定的，适用于专用公路。"},{"i":12,"n":"第十二条","txt":"公路规划应当根据国民经济和社会发展以及国防建设的需要编制，与城市建设发展规划和其他方式的交通运输发展规划相协调。"},{"i":13,"n":"第十三条","txt":"公路建设用地规划应当符合土地利用总体规划，当年建设用地应当纳入年度建设用地计划。"},{"i":14,"n":"第十四条","txt":"国道规划由国务院交通主管部门会同国务院有关部门并商国道沿线省、自治区、直辖市人民政府编制，报国务院批准。"},{"i":15,"n":"第十五条","txt":"专用公路规划由专用公路的主管单位编制，经其上级主管部门审定后，报县级以上人民政府交通主管部门审核。"},{"i":16,"n":"第十六条","txt":"国道规划的局部调整由原编制机关决定。国道规划需要作重大修改的，由原编制机关提出修改方案，报国务院批准。"},{"i":17,"n":"第十七条","txt":"国道的命名和编号，由国务院交通主管部门确定；省道、县道、乡道的命名和编号，由省、自治区、直辖市人民政府交通主管部门按照国务院交通主管部门的有关规定确定。"},{"i":18,"n":"第十八条","txt":"规划和新建村镇、开发区，应当与公路保持规定的距离并避免在公路两侧对应进行，防止造成公路街道化，影响公路的运行安全与畅通。"},{"i":19,"n":"第十九条","txt":"国家鼓励专用公路用于社会公共运输。专用公路主要用于社会公共运输时，由专用公路的主管单位申请，或者由有关方面申请，专用公路的主管单位同意，并经省、自治区、直辖市人民政府交通主管部门批准，可以改划为省道、县道或者乡道。"},{"i":20,"n":"第二十条","txt":"县级以上人民政府交通主管部门应当依据职责维护公路建设秩序，加强对公路建设的监督管理。"},{"i":21,"n":"第二十一条","txt":"筹集公路建设资金，除各级人民政府的财政拨款，包括依法征税筹集的公路建设专项资金转为的财政拨款外，可以依法向国内外金融机构或者外国政府贷款。"},{"i":22,"n":"第二十二条","txt":"公路建设应当按照国家规定的基本建设程序和有关规定进行。"},{"i":23,"n":"第二十三条","txt":"公路建设项目应当按照国家有关规定实行法人负责制度、招标投标制度和工程监理制度。"},{"i":24,"n":"第二十四条","txt":"公路建设单位应当根据公路建设工程的特点和技术要求，选择具有相应资格的勘查设计单位、施工单位和工程监理单位，并依照有关法律、法规、规章的规定和公路工程技术标准的要求，分别签订合同，明确双方的权利义务。"},{"i":25,"n":"第二十五条","txt":"公路建设项目的施工，须按国务院交通主管部门的规定报请县级以上地方人民政府交通主管部门批准。"},{"i":26,"n":"第二十六条","txt":"公路建设必须符合公路工程技术标准。"},{"i":27,"n":"第二十七条","txt":"公路建设使用土地依照有关法律、行政法规的规定办理。"},{"i":28,"n":"第二十八条","txt":"公路建设需要使用国有荒山、荒地或者需要在国有荒山、荒地、河滩、滩涂上挖砂、采石、取土的，依照有关法律、行政法规的规定办理后，任何单位和个人不得阻挠或者非法收取费用。"},{"i":29,"n":"第二十九条","txt":"地方各级人民政府对公路建设依法使用土地和搬迁居民，应当给予支持和协助。"},{"i":30,"n":"第三十条","txt":"公路建设项目的设计和施工，应当符合依法保护环境、保护文物古迹和防止水土流失的要求。"},{"i":31,"n":"第三十一条","txt":"因建设公路影响铁路、水利、电力、邮电设施和其他设施正常使用时，公路建设单位应当事先征得有关部门的同意；因公路建设对有关设施造成损坏的，公路建设单位应当按照不低于该设施原有的技术标准予以修复，或者给予相应的经济补偿。"},{"i":32,"n":"第三十二条","txt":"改建公路时，施工单位应当在施工路段两端设置明显的施工标志、安全标志。需要车辆绕行的，应当在绕行路口设置标志；不能绕行的，必须修建临时道路，保证车辆和行人通行。"},{"i":33,"n":"第三十三条","txt":"公路建设项目和公路修复项目竣工后，应当按照国家有关规定进行验收；未经验收或者验收不合格的，不得交付使用。"},{"i":34,"n":"第三十四条","txt":"县级以上地方人民政府应当确定公路两侧边沟（截水沟、坡脚护坡道，下同）外缘起不少于一米的公路用地。"},{"i":35,"n":"第三十五条","txt":"公路管理机构应当按照国务院交通主管部门规定的技术规范和操作规程对公路进行养护，保证公路经常处于良好的技术状态。"},{"i":36,"n":"第三十六条","txt":"国家采用依法征税的办法筹集公路养护资金，具体实施办法和步骤由国务院规定。"},{"i":37,"n":"第三十七条","txt":"县、乡级人民政府对公路养护需要的挖砂、采石、取土以及取水，应当给予支持和协助。"},{"i":38,"n":"第三十八条","txt":"县、乡级人民政府应当在农村义务工的范围内，按照国家有关规定组织公路两侧的农村居民履行为公路建设和养护提供劳务的义务。"},{"i":39,"n":"第三十九条","txt":"为保障公路养护人员的人身安全，公路养护人员进行养护作业时，应当穿着统一的安全标志服；利用车辆进行养护作业时，应当在公路作业车辆上设置明显的作业标志。"},{"i":40,"n":"第四十条","txt":"因严重自然灾害致使国道、省道交通中断，公路管理机构应当及时修复；公路管理机构难以及时修复时，县级以上地方人民政府应当及时组织当地机关、团体、企业事业单位、城乡居民进行抢修，并可以请求当地驻军支援，尽快恢复交通。"},{"i":41,"n":"第四十一条","txt":"公路用地范围内的山坡、荒地，由公路管理机构负责水土保持。"},{"i":42,"n":"第四十二条","txt":"公路绿化工作，由公路管理机构按照公路工程技术标准组织实施。"},{"i":43,"n":"第四十三条","txt":"各级地方人民政府应当采取措施，加强对公路的保护。"},{"i":44,"n":"第四十四条","txt":"任何单位和个人不得擅自占用、挖掘公路。"},{"i":45,"n":"第四十五条","txt":"跨越、穿越公路修建桥梁、渡槽或者架设、埋设管线等设施的，以及在公路用地范围内架设、埋设管线、电缆等设施的，应当事先经有关交通主管部门同意，影响交通安全的，还须征得有关公安机关的同意；所修建、架设或者埋设的设施应当符合公路工程技术标准的要求。对公路造成损坏的，应当按照损坏程度给予补偿。"},{"i":46,"n":"第四十六条","txt":"任何单位和个人不得在公路上及公路用地范围内摆摊设点、堆放物品、倾倒垃圾、设置障碍、挖沟引水、利用公路边沟排放污物或者进行其他损坏、污染公路和影响公路畅通的活动。"},{"i":47,"n":"第四十七条","txt":"在大中型公路桥梁和渡口周围二百米、公路隧道上方和洞口外一百米范围内，以及在公路两侧一定距离内，不得挖砂、采石、取土、倾倒废弃物，不得进行爆破作业及其他危及公路、公路桥梁、公路隧道、公路渡口安全的活动。"},{"i":48,"n":"第四十八条","txt":"铁轮车、履带车和其他可能损害公路路面的机具，不得在公路上行驶。"},{"i":49,"n":"第四十九条","txt":"在公路上行驶的车辆的轴载质量应当符合公路工程技术标准要求。"},{"i":50,"n":"第五十条","txt":"超过公路、公路桥梁、公路隧道或者汽车渡船的限载、限高、限宽、限长标准的车辆，不得在有限定标准的公路、公路桥梁上或者公路隧道内行驶，不得使用汽车渡船。超过公路或者公路桥梁限载标准确需行驶的，必须经县级以上地方人民政府交通主管部门批准，并按要求采取有效的防护措施；运载不可解体的超限物品的，应当按照指定的时间、路线、时速行驶，并悬挂明显标志。"},{"i":51,"n":"第五十一条","txt":"机动车制造厂和其他单位不得将公路作为检验机动车制动性能的试车场地。"},{"i":52,"n":"第五十二条","txt":"任何单位和个人不得损坏、擅自移动、涂改公路附属设施。"},{"i":53,"n":"第五十三条","txt":"造成公路损坏的，责任者应当及时报告公路管理机构，并接受公路管理机构的现场调查。"},{"i":54,"n":"第五十四条","txt":"任何单位和个人未经县级以上地方人民政府交通主管部门批准，不得在公路用地范围内设置公路标志以外的其他标志。"},{"i":55,"n":"第五十五条","txt":"在公路上增设平面交叉道口，必须按照国家有关规定经过批准，并按照国家规定的技术标准建设。"},{"i":56,"n":"第五十六条","txt":"除公路防护、养护需要的以外，禁止在公路两侧的建筑控制区内修建建筑物和地面构筑物；需要在建筑控制区内埋设管线、电缆等设施的，应当事先经县级以上地方人民政府交通主管部门批准。"},{"i":57,"n":"第五十七条","txt":"除本法第四十七条第二款的规定外，本章规定由交通主管部门行使的路政管理职责，可以依照本法第八条第四款的规定，由公路管理机构行使。"},{"i":58,"n":"第五十八条","txt":"国家允许依法设立收费公路，同时对收费公路的数量进行控制。"},{"i":59,"n":"第五十九条","txt":"符合国务院交通主管部门规定的技术等级和规模的下列公路，可以依法收取车辆通行费："},{"i":60,"n":"第六十条","txt":"县级以上地方人民政府交通主管部门利用贷款或者集资建成的收费公路的收费期限，按照收费偿还贷款、集资款的原则，由省、自治区、直辖市人民政府依照国务院交通主管部门的规定确定。"},{"i":61,"n":"第六十一条","txt":"本法第五十九条第一款第一项规定的公路中的国道收费权的转让，应当在转让协议签订之日起三十个工作日内报国务院交通主管部门备案；国道以外的其他公路收费权的转让，应当在转让协议签订之日起三十个工作日内报省、自治区、直辖市人民政府备案。"},{"i":62,"n":"第六十二条","txt":"受让公路收费权和投资建设公路的国内外经济组织应当依法成立开发、经营公路的企业（以下简称公路经营企业）。"},{"i":63,"n":"第六十三条","txt":"收费公路车辆通行费的收费标准，由公路收费单位提出方案，报省、自治区、直辖市人民政府交通主管部门会同同级物价行政主管部门审查批准。"},{"i":64,"n":"第六十四条","txt":"收费公路设置车辆通行费的收费站，应当报经省、自治区、直辖市人民政府审查批准。跨省、自治区、直辖市的收费公路设置车辆通行费的收费站，由有关省、自治区、直辖市人民政府协商确定；协商不成的，由国务院交通主管部门决定。同一收费公路由不同的交通主管部门组织建设或者由不同的公路经营企业经营的，应当按照“统一收费、按比例分成”的原则，统筹规划，合理设置收费站。"},{"i":65,"n":"第六十五条","txt":"有偿转让公路收费权的公路，转让收费权合同约定的期限届满，收费权由出让方收回。"},{"i":66,"n":"第六十六条","txt":"依照本法第五十九条规定受让收费权或者由国内外经济组织投资建成经营的公路的养护工作，由各该公路经营企业负责。各该公路经营企业在经营期间应当按照国务院交通主管部门规定的技术规范和操作规程做好对公路的养护工作。在受让收费权的期限届满，或者经营期限届满时，公路应当处于良好的技术状态。"},{"i":67,"n":"第六十七条","txt":"在收费公路上从事本法第四十四条第二款、第四十五条、第四十八条、第五十条所列活动的，除依照各该条的规定办理外，给公路经营企业造成损失的，应当给予相应的补偿。"},{"i":68,"n":"第六十八条","txt":"收费公路的具体管理办法，由国务院依照本法制定。"},{"i":69,"n":"第六十九条","txt":"交通主管部门、公路管理机构依法对有关公路的法律、法规执行情况进行监督检查。"},{"i":70,"n":"第七十条","txt":"交通主管部门、公路管理机构负有管理和保护公路的责任，有权检查、制止各种侵占、损坏公路、公路用地、公路附属设施及其他违反本法规定的行为。"},{"i":71,"n":"第七十一条","txt":"公路监督检查人员依法在公路、建筑控制区、车辆停放场所、车辆所属单位等进行监督检查时，任何单位和个人不得阻挠。"},{"i":72,"n":"第七十二条","txt":"交通主管部门、公路管理机构应当加强对所属公路监督检查人员的管理和教育，要求公路监督检查人员熟悉国家有关法律和规定，公正廉洁，热情服务，秉公执法，对公路监督检查人员的执法行为应当加强监督检查，对其违法行为应当及时纠正，依法处理。"},{"i":73,"n":"第七十三条","txt":"用于公路监督检查的专用车辆，应当设置统一的标志和示警灯。"},{"i":74,"n":"第七十四条","txt":"违反法律或者国务院有关规定，擅自在公路上设卡、收费的，由交通主管部门责令停止违法行为，没收违法所得，可以处违法所得三倍以下的罚款，没有违法所得的，可以处二万元以下的罚款；对负有直接责任的主管人员和其他直接责任人员，依法给予行政处分。"},{"i":75,"n":"第七十五条","txt":"违反本法第二十五条规定，未经有关交通主管部门批准擅自施工的，交通主管部门可以责令停止施工，并可以处五万元以下的罚款。"},{"i":76,"n":"第七十六条","txt":"有下列违法行为之一的，由交通主管部门责令停止违法行为，可以处三万元以下的罚款："},{"i":77,"n":"第七十七条","txt":"违反本法第四十六条的规定，造成公路路面损坏、污染或者影响公路畅通的，或者违反本法第五十一条规定，将公路作为试车场地的，由交通主管部门责令停止违法行为，可以处五千元以下的罚款。"},{"i":78,"n":"第七十八条","txt":"违反本法第五十三条规定，造成公路损坏，未报告的，由交通主管部门处一千元以下的罚款。"},{"i":79,"n":"第七十九条","txt":"违反本法第五十四条规定，在公路用地范围内设置公路标志以外的其他标志的，由交通主管部门责令限期拆除，可以处二万元以下的罚款；逾期不拆除的，由交通主管部门拆除，有关费用由设置者负担。"},{"i":80,"n":"第八十条","txt":"违反本法第五十五条规定，未经批准在公路上增设平面交叉道口的，由交通主管部门责令恢复原状，处五万元以下的罚款。"},{"i":81,"n":"第八十一条","txt":"违反本法第五十六条规定，在公路建筑控制区内修建建筑物、地面构筑物或者擅自埋设管线、电缆等设施的，由交通主管部门责令限期拆除，并可以处五万元以下的罚款。逾期不拆除的，由交通主管部门拆除，有关费用由建筑者、构筑者承担。"},{"i":82,"n":"第八十二条","txt":"除本法第七十四条、第七十五条的规定外，本章规定由交通主管部门行使的行政处罚权和行政措施，可以依照本法第八条第四款的规定由公路管理机构行使。"},{"i":83,"n":"第八十三条","txt":"阻碍公路建设或者公路抢修，致使公路建设或者抢修不能正常进行，尚未造成严重损失的，依照《中华人民共和国治安管理处罚法》的规定处罚。"},{"i":84,"n":"第八十四条","txt":"违反本法有关规定，构成犯罪的，依法追究刑事责任。"},{"i":85,"n":"第八十五条","txt":"违反本法有关规定，对公路造成损害的，应当依法承担民事责任。"},{"i":86,"n":"第八十六条","txt":"交通主管部门、公路管理机构的工作人员玩忽职守、徇私舞弊、滥用职权，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":87,"n":"第八十七条","txt":"本法自1998年1月1日起施行。"}],"guanshuifa":[{"i":1,"n":"第一条","txt":"为了规范关税的征收和缴纳，维护进出口秩序，促进对外贸易，推进高水平对外开放，推动高质量发展，维护国家主权和利益，保护纳税人合法权益，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"中华人民共和国准许进出口的货物、进境物品，由海关依照本法和有关法律、行政法规的规定征收关税。"},{"i":3,"n":"第三条","txt":"进口货物的收货人、出口货物的发货人、进境物品的携带人或者收件人，是关税的纳税人。"},{"i":4,"n":"第四条","txt":"进出口货物的关税税目、税率以及税目、税率的适用规则等，依照本法所附《中华人民共和国进出口税则》（以下简称《税则》）执行。"},{"i":5,"n":"第五条","txt":"个人合理自用的进境物品，按照简易征收办法征收关税。超过个人合理自用数量的进境物品，按照进口货物征收关税。"},{"i":6,"n":"第六条","txt":"关税工作坚持中国共产党的领导，贯彻落实党和国家路线方针政策、决策部署，为国民经济和社会发展服务。"},{"i":7,"n":"第七条","txt":"国务院设立关税税则委员会，履行下列职责："},{"i":8,"n":"第八条","txt":"海关及其工作人员对在履行职责中知悉的纳税人、扣缴义务人的商业秘密、个人隐私、个人信息，应当依法予以保密，不得泄露或者非法向他人提供。"},{"i":9,"n":"第九条","txt":"关税税目由税则号列和目录条文等组成。"},{"i":10,"n":"第十条","txt":"进口关税设置最惠国税率、协定税率、特惠税率、普通税率。"},{"i":11,"n":"第十一条","txt":"关税税率的适用应当符合相应的原产地规则。"},{"i":12,"n":"第十二条","txt":"原产于共同适用最惠国待遇条款的世界贸易组织成员的进口货物，原产于与中华人民共和国缔结或者共同参加含有相互给予最惠国待遇条款的国际条约、协定的国家或者地区的进口货物，以及原产于中华人民共和国境内的进口货物，适用最惠国税率。"},{"i":13,"n":"第十三条","txt":"适用最惠国税率的进口货物有暂定税率的，适用暂定税率。"},{"i":14,"n":"第十四条","txt":"实行关税配额管理的进出口货物，关税配额内的适用关税配额税率，有暂定税率的适用暂定税率；关税配额外的，其税率的适用按照本法第十二条、第十三条的规定执行。"},{"i":15,"n":"第十五条","txt":"关税税率的调整，按照下列规定执行："},{"i":16,"n":"第十六条","txt":"依法对进口货物征收反倾销税、反补贴税、保障措施关税的，其税率的适用按照有关反倾销、反补贴和保障措施的法律、行政法规的规定执行。"},{"i":17,"n":"第十七条","txt":"任何国家或者地区不履行与中华人民共和国缔结或者共同参加的国际条约、协定中的最惠国待遇条款或者关税优惠条款，国务院关税税则委员会可以提出按照对等原则采取相应措施的建议，报国务院批准后执行。"},{"i":18,"n":"第十八条","txt":"任何国家或者地区违反与中华人民共和国缔结或者共同参加的国际条约、协定，对中华人民共和国在贸易方面采取禁止、限制、加征关税或者其他影响正常贸易的措施的，对原产于该国家或者地区的进口货物可以采取征收报复性关税等措施。"},{"i":19,"n":"第十九条","txt":"涉及本法第十六条、第十七条、第十八条规定措施的进口货物，纳税人未提供证明材料，或者提供了证明材料但经海关审核仍无法排除该货物原产于被采取规定措施的国家或者地区的，对该货物适用下列两项税率中较高者："},{"i":20,"n":"第二十条","txt":"进出口货物、进境物品，应当适用纳税人、扣缴义务人完成申报之日实施的税率。"},{"i":21,"n":"第二十一条","txt":"有下列情形之一的，应当适用纳税人、扣缴义务人办理纳税手续之日实施的税率："},{"i":22,"n":"第二十二条","txt":"补征或者退还关税税款，应当按照本法第二十条或者第二十一条的规定确定适用的税率。"},{"i":23,"n":"第二十三条","txt":"关税实行从价计征、从量计征、复合计征的方式征收。"},{"i":24,"n":"第二十四条","txt":"进口货物的计税价格以成交价格以及该货物运抵中华人民共和国境内输入地点起卸前的运输及其相关费用、保险费为基础确定。"},{"i":25,"n":"第二十五条","txt":"进口货物的下列费用应当计入计税价格："},{"i":26,"n":"第二十六条","txt":"进口时在货物的价款中列明的下列费用、税收，不计入该货物的计税价格："},{"i":27,"n":"第二十七条","txt":"进口货物的成交价格不符合本法第二十四条第三款规定条件，或者成交价格不能确定的，海关经了解有关情况，并与纳税人进行价格磋商后，依次以下列价格估定该货物的计税价格："},{"i":28,"n":"第二十八条","txt":"按照本法第二十七条第一款第三项规定估定计税价格，应当扣除下列项目："},{"i":29,"n":"第二十九条","txt":"出口货物的计税价格以该货物的成交价格以及该货物运至中华人民共和国境内输出地点装载前的运输及其相关费用、保险费为基础确定。"},{"i":30,"n":"第三十条","txt":"出口货物的成交价格不能确定的，海关经了解有关情况，并与纳税人进行价格磋商后，依次以下列价格估定该货物的计税价格："},{"i":31,"n":"第三十一条","txt":"海关可以依申请或者依职权，对进出口货物、进境物品的计税价格、商品归类和原产地依法进行确定。"},{"i":32,"n":"第三十二条","txt":"下列进出口货物、进境物品，免征关税："},{"i":33,"n":"第三十三条","txt":"下列进出口货物、进境物品，减征关税："},{"i":34,"n":"第三十四条","txt":"根据维护国家利益、促进对外交往、经济社会发展、科技创新需要或者由于突发事件等原因，国务院可以制定关税专项优惠政策，报全国人民代表大会常务委员会备案。"},{"i":35,"n":"第三十五条","txt":"减免税货物应当依法办理手续。需由海关监管使用的减免税货物应当接受海关监管，在监管年限内转让、移作他用或者进行其他处置，按照国家有关规定需要补税的，应当补缴关税。"},{"i":36,"n":"第三十六条","txt":"保税货物复运出境的，免征关税；不复运出境转为内销的，按照规定征收关税。加工贸易保税进口料件或者其制成品内销的，除按照规定征收关税外，还应当征收缓税利息。"},{"i":37,"n":"第三十七条","txt":"暂时进境或者暂时出境的下列货物、物品，可以依法暂不缴纳关税，但该货物、物品应当自进境或者出境之日起六个月内复运出境或者复运进境；需要延长复运出境或者复运进境期限的，应当根据海关总署的规定向海关办理延期手续："},{"i":38,"n":"第三十八条","txt":"本法第三十七条规定以外的其他暂时进境的货物、物品，应当根据该货物、物品的计税价格和其在境内滞留时间与折旧时间的比例计算缴纳进口关税；该货物、物品在规定期限届满后未复运出境的，应当补足依法应缴纳的关税。"},{"i":39,"n":"第三十九条","txt":"因品质、规格原因或者不可抗力，出口货物自出口之日起一年内原状复运进境的，不征收进口关税。因品质、规格原因或者不可抗力，进口货物自进口之日起一年内原状复运出境的，不征收出口关税。"},{"i":40,"n":"第四十条","txt":"因残损、短少、品质不良或者规格不符原因，进出口货物的发货人、承运人或者保险公司免费补偿或者更换的相同货物，进出口时不征收关税。被免费更换的原进口货物不退运出境或者原出口货物不退运进境的，海关应当对原进出口货物重新按照规定征收关税。"},{"i":41,"n":"第四十一条","txt":"关税征收管理可以实施货物放行与税额确定相分离的模式。"},{"i":42,"n":"第四十二条","txt":"进出口货物的纳税人、扣缴义务人可以按照规定选择海关办理申报纳税。"},{"i":43,"n":"第四十三条","txt":"进出口货物的纳税人、扣缴义务人应当自完成申报之日起十五日内缴纳税款；符合海关规定条件并提供担保的，可以于次月第五个工作日结束前汇总缴纳税款。因不可抗力或者国家税收政策调整，不能按期缴纳的，经向海关申请并提供担保，可以延期缴纳，但最长不得超过六个月。"},{"i":44,"n":"第四十四条","txt":"进出口货物的纳税人在规定的纳税期限内有转移、藏匿其应税货物以及其他财产的明显迹象，或者存在其他可能导致无法缴纳税款风险的，海关可以责令其提供担保；纳税人不提供担保的，经直属海关关长或者其授权的隶属海关关长批准，海关可以实施下列强制措施："},{"i":45,"n":"第四十五条","txt":"自纳税人、扣缴义务人缴纳税款或者货物放行之日起三年内，海关有权对纳税人、扣缴义务人的应纳税额进行确认。"},{"i":46,"n":"第四十六条","txt":"因纳税人、扣缴义务人违反规定造成少征或者漏征税款的，海关可以自缴纳税款或者货物放行之日起三年内追征税款，并自缴纳税款或者货物放行之日起，按日加收少征或者漏征税款万分之五的滞纳金。"},{"i":47,"n":"第四十七条","txt":"对走私行为，海关追征税款、滞纳金的，不受前条规定期限的限制，并有权核定应纳税额。"},{"i":48,"n":"第四十八条","txt":"海关发现海关监管货物因纳税人、扣缴义务人违反规定造成少征或者漏征税款的，应当自纳税人、扣缴义务人应缴纳税款之日起三年内追征税款，并自应缴纳税款之日起按日加收少征或者漏征税款万分之五的滞纳金。"},{"i":49,"n":"第四十九条","txt":"海关可以对纳税人、扣缴义务人欠缴税款的情况予以公告。"},{"i":50,"n":"第五十条","txt":"纳税人、扣缴义务人未按照规定的期限缴纳或者解缴税款的，由海关责令其限期缴纳；逾期仍未缴纳且无正当理由的，经直属海关关长或者其授权的隶属海关关长批准，海关可以实施下列强制执行措施："},{"i":51,"n":"第五十一条","txt":"海关发现多征税款的，应当及时通知纳税人办理退还手续。"},{"i":52,"n":"第五十二条","txt":"有下列情形之一的，纳税人自缴纳税款之日起一年内，可以向海关申请退还关税："},{"i":53,"n":"第五十三条","txt":"按照规定退还关税的，应当加算银行同期活期存款利息。"},{"i":54,"n":"第五十四条","txt":"对规避本法第二章、第三章有关规定，不具有合理商业目的而减少应纳税额的行为，国家可以采取调整关税等反规避措施。"},{"i":55,"n":"第五十五条","txt":"报关企业接受纳税人的委托，以纳税人的名义办理报关纳税手续，因报关企业违反规定造成海关少征、漏征税款的，报关企业对少征或者漏征的税款及其滞纳金与纳税人承担纳税的连带责任。"},{"i":56,"n":"第五十六条","txt":"除不可抗力外，在保管海关监管货物期间，海关监管货物损毁或者灭失的，对海关监管货物负有保管义务的单位或者个人应当承担相应的纳税责任。"},{"i":57,"n":"第五十七条","txt":"未履行纳税义务的纳税人有合并、分立情形的，在合并、分立前，应当向海关报告，依法缴清税款、滞纳金或者提供担保。纳税人合并时未缴清税款、滞纳金或者未提供担保的，由合并后的法人或者非法人组织继续履行未履行的纳税义务；纳税人分立时未缴清税款、滞纳金或者未提供担保的，分立后的法人或者非法人组织对未履行的纳税义务承担连带责任。"},{"i":58,"n":"第五十八条","txt":"海关征收的税款优先于无担保债权，法律另有规定的除外。纳税人欠缴税款发生在纳税人以其财产设定抵押、质押之前的，税款应当先于抵押权、质权执行。"},{"i":59,"n":"第五十九条","txt":"税款、滞纳金应当按照国家有关规定及时缴入国库。"},{"i":60,"n":"第六十条","txt":"税款、滞纳金、利息等应当以人民币计算。"},{"i":61,"n":"第六十一条","txt":"海关因关税征收的需要，可以依法向有关政府部门和机构查询纳税人的身份、账户、资金往来等涉及关税的信息，有关政府部门和机构应当在职责范围内予以协助和配合。海关获取的涉及关税的信息只能用于关税征收目的。"},{"i":62,"n":"第六十二条","txt":"有下列情形之一的，由海关给予警告；情节严重的，处三万元以下的罚款："},{"i":63,"n":"第六十三条","txt":"纳税人欠缴应纳税款，采取转移或者藏匿财产等手段，妨碍海关依法追征欠缴的税款的，除由海关追征欠缴的税款、滞纳金外，处欠缴税款百分之五十以上五倍以下的罚款。"},{"i":64,"n":"第六十四条","txt":"扣缴义务人应扣未扣、应收未收税款的，由海关向纳税人追征税款，对扣缴义务人处应扣未扣、应收未收税款百分之五十以上三倍以下的罚款。"},{"i":65,"n":"第六十五条","txt":"对本法第六十二条、第六十三条、第六十四条规定以外其他违反本法规定的行为，由海关依照《中华人民共和国海关法》等法律、行政法规的规定处罚。"},{"i":66,"n":"第六十六条","txt":"纳税人、扣缴义务人、担保人对海关确定纳税人、商品归类、货物原产地、纳税地点、计征方式、计税价格、适用税率或者汇率，决定减征或者免征税款，确认应纳税额、补缴税款、退还税款以及加收滞纳金等征税事项有异议的，应当依法先向上一级海关申请行政复议；对行政复议决定不服的，可以依法向人民法院提起行政诉讼。"},{"i":67,"n":"第六十七条","txt":"违反本法规定，滥用职权、玩忽职守、徇私舞弊或者泄露、非法向他人提供在履行职责中知悉的商业秘密、个人隐私、个人信息的，依法给予处分。"},{"i":68,"n":"第六十八条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":69,"n":"第六十九条","txt":"《中华人民共和国海南自由贸易港法》对海南自由贸易港的关税事宜另有规定的，依照其规定。"},{"i":70,"n":"第七十条","txt":"进口环节海关代征税的征收管理，适用关税征收管理的规定。"},{"i":71,"n":"第七十一条","txt":"从事免税商品零售业务应当经过批准，具体办法由国务院规定。"},{"i":72,"n":"第七十二条","txt":"本法自2024年12月1日起施行。《中华人民共和国进出口关税条例》同时废止。"}],"nongyejishutuiguangfa":[{"i":1,"n":"第一条","txt":"为了加强农业技术推广工作，促使农业科研成果和实用技术尽快应用于农业生产，增强科技支撑保障能力，促进农业和农村经济可持续发展，实现农业现代化，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称农业技术，是指应用于种植业、林业、畜牧业、渔业的科研成果和实用技术，包括："},{"i":3,"n":"第三条","txt":"国家扶持农业技术推广事业，加快农业技术的普及应用，发展高产、优质、高效、生态、安全农业。"},{"i":4,"n":"第四条","txt":"农业技术推广应当遵循下列原则："},{"i":5,"n":"第五条","txt":"国家鼓励和支持科技人员开发、推广应用先进的农业技术，鼓励和支持农业劳动者和农业生产经营组织应用先进的农业技术。"},{"i":6,"n":"第六条","txt":"国家鼓励和支持引进国外先进的农业技术，促进农业技术推广的国际合作与交流。"},{"i":7,"n":"第七条","txt":"各级人民政府应当加强对农业技术推广工作的领导，组织有关部门和单位采取措施，提高农业技术推广服务水平，促进农业技术推广事业的发展。"},{"i":8,"n":"第八条","txt":"对在农业技术推广工作中做出贡献的单位和个人，给予奖励。"},{"i":9,"n":"第九条","txt":"国务院农业农村、林业草原、水利等部门（以下统称农业技术推广部门）按照各自的职责，负责全国范围内有关的农业技术推广工作。县级以上地方各级人民政府农业技术推广部门在同级人民政府的领导下，按照各自的职责，负责本行政区域内有关的农业技术推广工作。同级人民政府其他有关部门按照各自的职责，负责农业技术推广的有关工作。"},{"i":10,"n":"第十条","txt":"农业技术推广，实行国家农业技术推广机构与农业科研单位、有关学校、农民专业合作社、涉农企业、群众性科技组织、农民技术人员等相结合的推广体系。"},{"i":11,"n":"第十一条","txt":"各级国家农业技术推广机构属于公共服务机构，履行下列公益性职责："},{"i":12,"n":"第十二条","txt":"根据科学合理、集中力量的原则以及县域农业特色、森林资源、水系和水利设施分布等情况，因地制宜设置县、乡镇或者区域国家农业技术推广机构。"},{"i":13,"n":"第十三条","txt":"国家农业技术推广机构的人员编制应当根据所服务区域的种养规模、服务范围和工作任务等合理确定，保证公益性职责的履行。"},{"i":14,"n":"第十四条","txt":"国家农业技术推广机构的专业技术人员应当具有相应的专业技术水平，符合岗位职责要求。"},{"i":15,"n":"第十五条","txt":"国家鼓励和支持村农业技术服务站点和农民技术人员开展农业技术推广。对农民技术人员协助开展公益性农业技术推广活动，按照规定给予补助。"},{"i":16,"n":"第十六条","txt":"农业科研单位和有关学校应当适应农村经济建设发展的需要，开展农业技术开发和推广工作，加快先进技术在农业生产中的普及应用。"},{"i":17,"n":"第十七条","txt":"国家鼓励农场、林场、牧场、渔场、水利工程管理单位面向社会开展农业技术推广服务。"},{"i":18,"n":"第十八条","txt":"国家鼓励和支持发展农村专业技术协会等群众性科技组织，发挥其在农业技术推广中的作用。"},{"i":19,"n":"第十九条","txt":"重大农业技术的推广应当列入国家和地方相关发展规划、计划，由农业技术推广部门会同相关部门按照各自的职责，相互配合，组织实施。"},{"i":20,"n":"第二十条","txt":"农业科研单位和有关学校应当把农业生产中需要解决的技术问题列为研究课题，其科研成果可以通过有关农业技术推广单位进行推广或者直接向农业劳动者和农业生产经营组织推广。"},{"i":21,"n":"第二十一条","txt":"向农业劳动者和农业生产经营组织推广的农业技术，必须在推广地区经过试验证明具有先进性、适用性和安全性。"},{"i":22,"n":"第二十二条","txt":"国家鼓励和支持农业劳动者和农业生产经营组织参与农业技术推广。"},{"i":23,"n":"第二十三条","txt":"县、乡镇国家农业技术推广机构应当组织农业劳动者学习农业科学技术知识，提高其应用农业技术的能力。"},{"i":24,"n":"第二十四条","txt":"各级国家农业技术推广机构应当认真履行本法第十一条规定的公益性职责，向农业劳动者和农业生产经营组织推广农业技术，实行无偿服务。"},{"i":25,"n":"第二十五条","txt":"国家鼓励和支持农民专业合作社、涉农企业，采取多种形式，为农民应用先进农业技术提供有关的技术服务。"},{"i":26,"n":"第二十六条","txt":"国家鼓励和支持以大宗农产品和优势特色农产品生产为重点的农业示范区建设，发挥示范区对农业技术推广的引领作用，促进农业产业化发展和现代农业建设。"},{"i":27,"n":"第二十七条","txt":"各级人民政府可以采取购买服务等方式，引导社会力量参与公益性农业技术推广服务。"},{"i":28,"n":"第二十八条","txt":"国家逐步提高对农业技术推广的投入。各级人民政府在财政预算内应当保障用于农业技术推广的资金，并按规定使该资金逐年增长。"},{"i":29,"n":"第二十九条","txt":"各级人民政府应当采取措施，保障和改善县、乡镇国家农业技术推广机构的专业技术人员的工作条件、生活条件和待遇，并按照国家规定给予补贴，保持国家农业技术推广队伍的稳定。"},{"i":30,"n":"第三十条","txt":"各级人民政府应当采取措施，保障国家农业技术推广机构获得必需的试验示范场所、办公场所、推广和培训设施设备等工作条件。"},{"i":31,"n":"第三十一条","txt":"农业技术推广部门和县级以上国家农业技术推广机构，应当有计划地对农业技术推广人员进行技术培训，组织专业进修，使其不断更新知识、提高业务水平。"},{"i":32,"n":"第三十二条","txt":"县级以上农业技术推广部门、乡镇人民政府应当对其管理的国家农业技术推广机构履行公益性职责的情况进行监督、考评。"},{"i":33,"n":"第三十三条","txt":"从事农业技术推广服务的，可以享受国家规定的税收、信贷等方面的优惠。"},{"i":34,"n":"第三十四条","txt":"各级人民政府有关部门及其工作人员未依照本法规定履行职责的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":35,"n":"第三十五条","txt":"国家农业技术推广机构及其工作人员未依照本法规定履行职责的，由主管机关责令限期改正，通报批评；对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":36,"n":"第三十六条","txt":"违反本法规定，向农业劳动者、农业生产经营组织推广未经试验证明具有先进性、适用性或者安全性的农业技术，造成损失的，应当承担赔偿责任。"},{"i":37,"n":"第三十七条","txt":"违反本法规定，强迫农业劳动者、农业生产经营组织应用农业技术，造成损失的，依法承担赔偿责任。"},{"i":38,"n":"第三十八条","txt":"违反本法规定，截留或者挪用用于农业技术推广的资金的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":39,"n":"第三十九条","txt":"本法自公布之日起施行。"}],"nongyejixiehuacujinfa":[{"i":1,"n":"第一条","txt":"为了鼓励、扶持农民和农业生产经营组织使用先进适用的农业机械，促进农业机械化，建设现代农业，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称农业机械化，是指运用先进适用的农业机械装备农业，改善农业生产经营条件，不断提高农业的生产技术水平和经济效益、生态效益的过程。"},{"i":3,"n":"第三条","txt":"县级以上人民政府应当把推进农业机械化纳入国民经济和社会发展计划，采取财政支持和实施国家规定的税收优惠政策以及金融扶持等措施，逐步提高对农业机械化的资金投入，充分发挥市场机制的作用，按照因地制宜、经济有效、保障安全、保护环境的原则，促进农业机械化的发展。"},{"i":4,"n":"第四条","txt":"国家引导、支持农民和农业生产经营组织自主选择先进适用的农业机械。任何单位和个人不得强迫农民和农业生产经营组织购买其指定的农业机械产品。"},{"i":5,"n":"第五条","txt":"国家采取措施，开展农业机械化科技知识的宣传和教育，培养农业机械化专业人才，推进农业机械化信息服务，提高农业机械化水平。"},{"i":6,"n":"第六条","txt":"国务院农业行政主管部门和其他负责农业机械化有关工作的部门，按照各自的职责分工，密切配合，共同做好农业机械化促进工作。"},{"i":7,"n":"第七条","txt":"省级以上人民政府及其有关部门应当组织有关单位采取技术攻关、试验、示范等措施，促进基础性、关键性、公益性农业机械科学研究和先进适用的农业机械的推广应用。"},{"i":8,"n":"第八条","txt":"国家支持有关科研机构和院校加强农业机械化科学技术研究，根据不同的农业生产条件和农民需求，研究开发先进适用的农业机械；支持农业机械科研、教学与生产、推广相结合，促进农业机械与农业生产技术的发展要求相适应。"},{"i":9,"n":"第九条","txt":"国家支持农业机械生产者开发先进适用的农业机械，采用先进技术、先进工艺和先进材料，提高农业机械产品的质量和技术水平，降低生产成本，提供系列化、标准化、多功能和质量优良、节约能源、价格合理的农业机械产品。"},{"i":10,"n":"第十条","txt":"国家支持引进、利用先进的农业机械、关键零配件和技术，鼓励引进外资从事农业机械的研究、开发、生产和经营。"},{"i":11,"n":"第十一条","txt":"国家加强农业机械化标准体系建设，制定和完善农业机械产品质量、维修质量和作业质量等标准。对农业机械产品涉及人身安全、农产品质量安全和环境保护的技术要求，应当按照有关法律、行政法规的规定制定强制执行的技术规范。"},{"i":12,"n":"第十二条","txt":"市场监督管理部门应当依法组织对农业机械产品质量的监督抽查，加强对农业机械产品市场的监督管理工作。"},{"i":13,"n":"第十三条","txt":"农业机械生产者、销售者应当对其生产、销售的农业机械产品质量负责，并按照国家有关规定承担零配件供应和培训等售后服务责任。"},{"i":14,"n":"第十四条","txt":"农业机械产品不符合质量要求的，农业机械生产者、销售者应当负责修理、更换、退货；给农业机械使用者造成农业生产损失或者其他损失的，应当依法赔偿损失。农业机械使用者有权要求农业机械销售者先予赔偿。农业机械销售者赔偿后，属于农业机械生产者的责任的，农业机械销售者有权向农业机械生产者追偿。"},{"i":15,"n":"第十五条","txt":"列入依法必须经过认证的产品目录的农业机械产品，未经认证并标注认证标志，禁止出厂、销售和进口。"},{"i":16,"n":"第十六条","txt":"国家支持向农民和农业生产经营组织推广先进适用的农业机械产品。推广农业机械产品，应当适应当地农业发展的需要，并依照农业技术推广法的规定，在推广地区经过试验证明具有先进性和适用性。"},{"i":17,"n":"第十七条","txt":"县级以上人民政府可以根据实际情况，在不同的农业区域建立农业机械化示范基地，并鼓励农业机械生产者、经营者等建立农业机械示范点，引导农民和农业生产经营组织使用先进适用的农业机械。"},{"i":18,"n":"第十八条","txt":"国务院农业行政主管部门会同国务院财政部门、经济综合宏观调控部门，根据促进农业结构调整、保护自然资源与生态环境、推广农业新技术与加快农机具更新的原则，确定、公布国家支持推广的先进适用的农业机械产品目录，并定期调整。省级人民政府主管农业机械化工作的部门会同同级财政部门、经济综合宏观调控部门根据上述原则，确定、公布省级人民政府支持推广的先进适用的农业机械产品目录，并定期调整。"},{"i":19,"n":"第十九条","txt":"国家鼓励和支持农民合作使用农业机械，提高农业机械利用率和作业效率，降低作业成本。"},{"i":20,"n":"第二十条","txt":"国务院农业行政主管部门和县级以上地方人民政府主管农业机械化工作的部门，应当按照安全生产、预防为主的方针，加强对农业机械安全使用的宣传、教育和管理。"},{"i":21,"n":"第二十一条","txt":"农民、农业机械作业组织可以按照双方自愿、平等协商的原则，为本地或者外地的农民和农业生产经营组织提供各项有偿农业机械作业服务。有偿农业机械作业应当符合国家或者地方规定的农业机械作业质量标准。"},{"i":22,"n":"第二十二条","txt":"各级人民政府应当采取措施，鼓励和扶持发展多种形式的农业机械服务组织，推进农业机械化信息网络建设，完善农业机械化服务体系。农业机械服务组织应当根据农民、农业生产经营组织的需求，提供农业机械示范推广、实用技术培训、维修、信息、中介等社会化服务。"},{"i":23,"n":"第二十三条","txt":"国家设立的基层农业机械技术推广机构应当以试验示范基地为依托，为农民和农业生产经营组织无偿提供公益性农业机械技术的推广、培训等服务。"},{"i":24,"n":"第二十四条","txt":"从事农业机械维修，应当具备与维修业务相适应的仪器、设备和具有农业机械维修职业技能的技术人员，保证维修质量。维修质量不合格的，维修者应当免费重新修理；造成人身伤害或者财产损失的，维修者应当依法承担赔偿责任。"},{"i":25,"n":"第二十五条","txt":"农业机械生产者、经营者、维修者可以依照法律、行政法规的规定，自愿成立行业协会，实行行业自律，为会员提供服务，维护会员的合法权益。"},{"i":26,"n":"第二十六条","txt":"国家采取措施，鼓励和支持农业机械生产者增加新产品、新技术、新工艺的研究开发投入，并对农业机械的科研开发和制造实施税收优惠政策。"},{"i":27,"n":"第二十七条","txt":"中央财政、省级财政应当分别安排专项资金，对农民和农业生产经营组织购买国家支持推广的先进适用的农业机械给予补贴。补贴资金的使用应当遵循公开、公正、及时、有效的原则，可以向农民和农业生产经营组织发放，也可以采用贴息方式支持金融机构向农民和农业生产经营组织购买先进适用的农业机械提供贷款。具体办法由国务院规定。"},{"i":28,"n":"第二十八条","txt":"从事农业机械生产作业服务的收入，按照国家规定给予税收优惠。"},{"i":29,"n":"第二十九条","txt":"地方各级人民政府应当采取措施加强农村机耕道路等农业机械化基础设施的建设和维护，为农业机械化创造条件。"},{"i":30,"n":"第三十条","txt":"违反本法第十五条规定的，依照产品质量法的有关规定予以处罚；构成犯罪的，依法追究刑事责任。"},{"i":31,"n":"第三十一条","txt":"农业机械驾驶、操作人员违反国家规定的安全操作规程，违章作业的，责令改正，依照有关法律、行政法规的规定予以处罚；构成犯罪的，依法追究刑事责任。"},{"i":32,"n":"第三十二条","txt":"农业机械试验鉴定机构在鉴定工作中不按照规定为农业机械生产者、销售者进行鉴定，或者伪造鉴定结果、出具虚假证明，给农业机械使用者造成损失的，依法承担赔偿责任。"},{"i":33,"n":"第三十三条","txt":"国务院农业行政主管部门和县级以上地方人民政府主管农业机械化工作的部门违反本法规定，强制或者变相强制农业机械生产者、销售者对其生产、销售的农业机械产品进行鉴定的，由上级主管机关或者监察机关责令限期改正，并对直接负责的主管人员和其他直接责任人员给予行政处分。"},{"i":34,"n":"第三十四条","txt":"违反本法第二十七条、第二十八条规定，截留、挪用有关补贴资金的，由上级主管机关责令限期归还被截留、挪用的资金，没收非法所得，并由上级主管机关、监察机关或者所在单位对直接负责的主管人员和其他直接责任人员给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":35,"n":"第三十五条","txt":"本法自2004年11月1日起施行。"}],"nongyefa-2":[{"i":1,"n":"第一条","txt":"为了巩固和加强农业在国民经济中的基础地位，深化农村改革，保护农业资源，发展农业生产力，推进农业现代化，维护农民和农业生产经营组织的合法权益，增加农民收入，提高农民科学文化素质，促进农业和农村经济的持续、稳定、健康发展，推进乡村全面振兴，加快建设农业强国，全面建设社会主义现代化国家，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称农业，是指种植业、林草业、畜牧业和渔业等产业，以及与其直接相关的产前、产中、产后服务。"},{"i":3,"n":"第三条","txt":"农业和农村工作应当坚持中国共产党的领导，贯彻创新、协调、绿色、开放、共享的新发展理念，推动高质量发展，统筹发展和安全。"},{"i":4,"n":"第四条","txt":"国家坚持和完善公有制为主体、多种所有制经济共同发展，按劳分配为主体、多种分配方式并存，社会主义市场经济体制等社会主义基本经济制度，振兴农村经济。"},{"i":5,"n":"第五条","txt":"国家坚持大农业观、大食物观，坚持农林牧渔并举，保障粮食安全，构建多元化食物供给体系。"},{"i":6,"n":"第六条","txt":"国家采取措施拓展农业多种功能，保障农业更好地发挥在提供食物、工业原料和其他农产品，维护和改善生态环境，传承弘扬中华优秀农耕文化，促进农村经济社会发展等多方面的作用。"},{"i":7,"n":"第七条","txt":"国家坚持科教兴农和农业可持续发展的方针，因地制宜发展农业新质生产力，推进科技创新和产业创新深度融合。"},{"i":8,"n":"第八条","txt":"国家把增加农民收入作为农业农村工作的中心任务。各级人民政府及其有关部门应当采取措施增加农民收入，切实减轻农民负担，缩小城乡居民收入差距，扎实推进共同富裕。"},{"i":9,"n":"第九条","txt":"全社会应当高度重视农业和农村，支持农业农村发展。"},{"i":10,"n":"第十条","txt":"各级人民政府对农业和农村经济发展工作统一负责，组织各有关部门和全社会做好发展农业和为发展农业服务的各项工作。"},{"i":11,"n":"第十一条","txt":"国家坚持平等互利、合作共赢的方针，支持开展农业领域的国际交流与合作，积极参与农业可持续发展与粮食安全国际治理。"},{"i":12,"n":"第十二条","txt":"国家实行农村土地承包经营制度，依法保障农村土地承包关系稳定并长久不变，保护农民对承包土地的土地承包经营权。国家保护承包方依法、自愿、有偿流转土地经营权，保护土地经营权人的合法权益。"},{"i":13,"n":"第十三条","txt":"国家鼓励在家庭承包经营的基础上依法自愿发展农民专业合作社。"},{"i":14,"n":"第十四条","txt":"农民和农业生产经营组织可以自愿按照民主管理、按劳分配和按股分红相结合的原则，以资金、技术、实物等入股，依法兴办各类企业。"},{"i":15,"n":"第十五条","txt":"国家鼓励和支持以家庭为基本经营单元、实行适度规模经营的家庭农场发展，引导其与现代农业相适应，提高集约化水平和经营效率。农村集体经济组织可以通过提供技术、信息服务等形式，支持家庭农场发展。"},{"i":16,"n":"第十六条","txt":"国家加强国有农场、林场、牧场、渔场规划建设，更好发挥其在发展现代农业中的示范引领作用。"},{"i":17,"n":"第十七条","txt":"国家鼓励供销合作社、农村集体经济组织、农民专业合作社、农业企业、其他组织和个人发展多层次、多类型的专业化服务，提升农业产前、产中、产后社会化服务水平。"},{"i":18,"n":"第十八条","txt":"国家采取措施发展多种形式的农业产业化经营，鼓励和支持农民和农业生产经营组织发展生产、加工、销售一体化经营。"},{"i":19,"n":"第十九条","txt":"农民和农业生产经营组织可以按照法律、行政法规成立农产品行业协会等组织，为成员提供生产、营销、信息、技术、培训等服务，发挥协调和自律作用，提出农产品贸易救济措施的申请，维护成员和行业的利益。"},{"i":20,"n":"第二十条","txt":"国务院和省级人民政府根据国民经济和社会发展规划、农业和农村经济发展的基本目标和农业资源区划，制定农业发展规划。"},{"i":21,"n":"第二十一条","txt":"国家引导和支持农民和农业生产经营组织结合本地实际，按照市场需求和生态环境承载能力，调整优化农业生产结构和区域布局，协调发展种植业、林草业、畜牧业和渔业，发展优质、高产、高效益的农业，提高农产品国际竞争力。"},{"i":22,"n":"第二十二条","txt":"各级人民政府应当采取措施，加强农业综合开发和农田水利、农业生态环境保护、乡村道路、农村能源和电网、农产品仓储和流通、渔港、草原围栏、动植物原种良种基地、农业防灾减灾、农业农村信息化等农业和农村基础设施建设，改善农业生产条件，保护和提高农业综合生产能力。"},{"i":23,"n":"第二十三条","txt":"国家扶持动植物品种的选育、生产、更新和良种的推广使用，鼓励品种选育和生产、经营相结合，实施现代种业提升工程，推进动植物良种培育、育种关键技术攻关，维护种业安全，提升种业现代化水平。国务院和省级人民政府设立专项资金，用于扶持动植物良种的选育和推广工作。"},{"i":24,"n":"第二十四条","txt":"各级人民政府和农业生产经营组织应当加强农田水利设施建设和管护，节约用水，因地制宜推动农业节水增效、发展高效节水农业，保障农业用水需求，严格依法控制非农业建设占用灌溉水源，禁止任何单位和个人非法占用或者毁损农田水利设施。"},{"i":25,"n":"第二十五条","txt":"国家鼓励和支持农民和农业生产经营组织使用先进适用的农业机械，加强农业机械安全管理，提高农业机械化水平。"},{"i":26,"n":"第二十六条","txt":"各级人民政府应当支持为农业服务的气象事业发展，加强农业气象综合监测网络建设，提高气象灾害监测和预报预警水平。"},{"i":27,"n":"第二十七条","txt":"国家采取措施提高农产品的质量，建立健全农产品质量安全标准、检验检测和监管体系，按照有关技术规范、操作规程和标准，引导和组织农产品的生产经营，推进农产品质量安全追溯管理，保障农产品质量安全。"},{"i":28,"n":"第二十八条","txt":"国家鼓励和扶持发展优质农产品生产，支持依法建立健全优质农产品认证和标志制度。符合国家规定标准的优质农产品可以依照法律、行政法规的规定申请使用有关的标志。符合规定产地及生产规范要求的农产品可以依照有关法律、行政法规的规定申请使用地理标志。"},{"i":29,"n":"第二十九条","txt":"国家实行动植物防疫、检疫制度，健全动植物防疫、检疫体系，完善动植物疫情监测预警网络，加强对动物疫病和植物病、虫、杂草、鼠害及其他有害生物的监测、预警、防治，建立重大动植物疫情快速扑灭机制，建设无规定动物疫病区，实施动植物保护能力提升工程。"},{"i":30,"n":"第三十条","txt":"农药、兽药、饲料和饲料添加剂、肥料、种子、农业机械、兽医器械等可能危害人畜安全的农业生产资料的生产经营，依照相关法律、行政法规的规定实行备案、登记或者许可制度。"},{"i":31,"n":"第三十一条","txt":"农产品的购销实行市场调节。国家健全农产品市场监测预警机制，对关系国计民生的粮食等重要农产品的购销活动实行必要的宏观调控，建立中央和地方分级储备调节制度，完善仓储运输体系，做到保证供应，稳定市场。"},{"i":32,"n":"第三十二条","txt":"国家逐步建立统一、开放、竞争、有序的农产品市场体系。对农村集体经济组织和农民专业合作社建立农产品批发市场和农产品集贸市场，国家给予扶持。"},{"i":33,"n":"第三十三条","txt":"国家鼓励和支持发展多种形式的农产品流通活动。支持农民和农民专业合作社按照国家有关规定从事农产品收购、批发、储存、运输、零售和中介活动。鼓励供销合作社和其他从事农产品购销的农业生产经营组织提供市场信息，开拓农产品流通渠道，为农产品销售服务。"},{"i":34,"n":"第三十四条","txt":"县级以上地方人民政府应当支持粮食烘干、产品分级、农产品产地冷藏保鲜、冷链物流等设施建设，支持完善县乡村物流配送体系，提高农产品储存、运输技术水平，增强保障供应能力。"},{"i":35,"n":"第三十五条","txt":"国家支持发展农产品加工业和食品工业，推动农产品加工业优化升级，增加农产品的附加值。县级以上人民政府应当引导农产品加工业形成合理的区域布局和规模结构，扶持农产品加工和综合开发利用。"},{"i":36,"n":"第三十六条","txt":"国家鼓励发展农产品进出口贸易和农业服务贸易。"},{"i":37,"n":"第三十七条","txt":"国家实施以我为主、立足国内、确保产能、适度进口、科技支撑的国家粮食安全战略，坚持藏粮于地、藏粮于技，确保谷物基本自给、口粮绝对安全。"},{"i":38,"n":"第三十八条","txt":"国家采取措施保护和提高粮食综合生产能力，稳步提高粮食生产水平，保障粮食安全。"},{"i":39,"n":"第三十九条","txt":"国家在政策、资金、技术等方面对粮食主产区给予重点扶持，建设稳定的商品粮生产基地，改善粮食收储及加工设施，提高粮食主产区的粮食生产、加工、储存、运输水平和经济效益。"},{"i":40,"n":"第四十条","txt":"国家健全粮食生产者收益保障机制，完善价格、补贴、保险等政策体系，完善农业生产资料保供稳价应对机制，保护粮食生产者的种粮积极性。"},{"i":41,"n":"第四十一条","txt":"国家加强对粮食市场的调控。"},{"i":42,"n":"第四十二条","txt":"国家建立粮食安全监测预警制度，建立政府粮食储备体系，完善粮食应急管理体制，采取措施保障粮食供给。国务院应当制定粮食安全保障目标与粮食储备数量指标，并根据需要组织有关主管部门进行耕地、粮食库存情况的核查。"},{"i":43,"n":"第四十三条","txt":"国家建立粮食风险基金，用于支持粮食储备、稳定粮食市场等。"},{"i":44,"n":"第四十四条","txt":"国家提倡珍惜和节约粮食，采取措施减少粮食生产、储存、流通、加工、消费等环节的损失损耗，防止浪费。"},{"i":45,"n":"第四十五条","txt":"国家推动加快形成财政优先保障、金融重点支持、社会多元参与的农业农村投入格局。国家提高强农惠农富农政策效能。"},{"i":46,"n":"第四十六条","txt":"国家逐步提高农业投入的总体水平，坚持将农业作为财政优先保障领域，建立健全农业投入稳定增长保障机制。中央和县级以上地方财政每年对农业总投入的增长幅度应当高于其财政经常性收入的增长幅度。"},{"i":47,"n":"第四十七条","txt":"县级以上人民政府每年财政预算内安排的各项用于农业的资金应当及时足额拨付。各级人民政府应当加强对国家各项农业资金分配、使用过程的监督管理，保证资金安全，提高资金的使用效益。"},{"i":48,"n":"第四十八条","txt":"国家运用税收、价格、信贷、奖补等手段，鼓励和引导农民和农业生产经营组织增加农业生产经营性投入和小型农田水利等基本建设投入。"},{"i":49,"n":"第四十九条","txt":"国家鼓励、引导社会资金投向农业，鼓励企业事业单位、社会组织和个人捐资设立支持农业建设和农业科技、教育等基金。"},{"i":50,"n":"第五十条","txt":"各级人民政府应当鼓励和支持企业事业单位及其他各类经济组织开展农业信息服务。"},{"i":51,"n":"第五十一条","txt":"国家鼓励和扶持农用工业的发展。"},{"i":52,"n":"第五十二条","txt":"县级以上人民政府及其各有关部门应当采取措施对农业社会化服务事业给予支持。"},{"i":53,"n":"第五十三条","txt":"国家建立健全多层次、广覆盖、可持续的农村金融体系，促进金融服务便利化，加强农村信用体系建设和农村金融监管，提升农村金融服务水平。"},{"i":54,"n":"第五十四条","txt":"国家完善农业保险制度，发展多层次的农业保险，丰富保险品种，提高保障水平和服务质量，发挥稳定农业生产、减少灾害损失和保障收入作用。"},{"i":55,"n":"第五十五条","txt":"国家鼓励符合规定的金融机构和涉农企业发行债券用于农业。按照国家规定发行的政府债券，应当加大对现代农业发展的支持力度。"},{"i":56,"n":"第五十六条","txt":"各级人民政府应当采取措施，提高农业防御自然灾害的能力，做好防灾减灾救灾工作，帮助受灾人员恢复生产，组织生产自救，开展社会互助互济；对没有基本生活保障的受灾人员给予救助和扶持。"},{"i":57,"n":"第五十七条","txt":"国务院和省级人民政府应当通过制定实施相关规划等措施，推进农业科技、教育、人才发展。"},{"i":58,"n":"第五十八条","txt":"国家采取措施加强农业科技创新，打造国家农业科技战略力量，发挥企业在科技创新中的主体作用，加强农业原始创新和关键核心技术攻关，提高农业劳动生产率和科技进步贡献率，加快实现高水平农业科技自立自强。"},{"i":59,"n":"第五十九条","txt":"国家保护植物新品种、地理标志等知识产权，鼓励、支持和引导高等学校、科研机构、企业加强农业科学技术的基础研究和应用研究，传播和普及农业科学技术知识，加速科技成果转化与产业化，促进农业科学技术进步。"},{"i":60,"n":"第六十条","txt":"国家扶持农业技术推广事业，建立政府扶持和市场引导相结合、有偿与无偿服务相结合、国家农业技术推广机构和社会力量相结合的农业技术推广体系，促使先进的农业技术、装备尽快推广应用。"},{"i":61,"n":"第六十一条","txt":"国家农业技术推广机构应当以农业技术试验示范基地为依托，承担公共所需的关键性技术的推广和示范等公益性职责，为农民和农业生产经营组织提供无偿农业技术服务。"},{"i":62,"n":"第六十二条","txt":"科研机构、有关学校、农民专业合作社、涉农企业、群众性科技组织及有关科技人员，根据农民和农业生产经营组织的需要，可以提供无偿服务，也可以通过技术转让、技术服务、技术承包、技术咨询、技术许可和技术入股等形式，提供有偿服务，取得合法收益。科研机构、有关学校、农民专业合作社、涉农企业、群众性科技组织及有关科技人员应当提高服务水平，保证服务质量。"},{"i":63,"n":"第六十三条","txt":"国家建立农业专业技术人员继续教育制度。县级以上人民政府农业农村主管部门会同教育、人力资源社会保障等有关部门制定农业专业技术人员继续教育计划，并组织实施。"},{"i":64,"n":"第六十四条","txt":"国家在农村依法实施义务教育，建立健全城乡统一的义务教育经费保障机制，保障义务教育经费。国家在农村举办的普通中小学校教职工工资由县级人民政府按照国家规定统一发放，校舍等教学设施的建设和维护经费由县级人民政府按照国家规定统一安排。"},{"i":65,"n":"第六十五条","txt":"国家发展农业高等教育、职业教育，加强涉农学科、专业建设，支持培养涉农急需紧缺专业人才。"},{"i":66,"n":"第六十六条","txt":"国家组织开展农业实用技术技能培训和其他就业培训，培养乡村本土人才，采取措施鼓励农民采用先进的农业技术，支持农民举办各种科技组织，发挥农业广播电视学校作用，提高农民文化技术素质和生产经营技能。"},{"i":67,"n":"第六十七条","txt":"发展农业和农村经济必须合理利用和保护土地、水、森林、草原、野生动植物等自然资源，合理开发和利用水能、风能、太阳能、生物质能、海洋能等可再生能源和清洁能源，发展生态农业，保护和改善生态环境。"},{"i":68,"n":"第六十八条","txt":"国家实行最严格的耕地保护制度，对永久基本农田依法实行特殊保护，确保国土空间规划确定的耕地和永久基本农田总量不减少、质量有提升、生态功能稳定。"},{"i":69,"n":"第六十九条","txt":"县级以上人民政府农业农村主管部门应当采取措施，支持农民和农业生产经营组织加强耕地质量建设，参与高标准农田建设与管护。"},{"i":70,"n":"第七十条","txt":"国家坚持山水林田湖草沙一体化保护和系统治理，实施重要生态系统保护和修复工程，加强生态的保护与修复。"},{"i":71,"n":"第七十一条","txt":"各级人民政府应当采取措施，组织群众造林绿化，保护林地和林木，预防森林火灾，防治林业有害生物，制止滥伐、盗伐林木，提高森林覆盖率、森林蓄积量。国家实行全民义务植树制度。"},{"i":72,"n":"第七十二条","txt":"有关地方人民政府应当加强草原保护、建设和管理，促进草牧业发展，指导、组织农（牧）民和农（牧）业生产经营组织建设人工草地、饲草饲料基地和改良天然草原，实行以草定畜、草畜平衡，合理控制载畜量，落实休牧和禁牧制度，推行划区轮牧，保护草原植被，加强草原火灾和病虫害防控工作，防止草原退化、沙化、盐碱化、石漠化和水土流失。"},{"i":73,"n":"第七十三条","txt":"禁止毁林毁草开垦、烧山开垦以及开垦国家禁止开垦的陡坡地。禁止围湖造田以及开（围）垦自然湿地。"},{"i":74,"n":"第七十四条","txt":"各级人民政府应当采取措施，依法执行捕捞许可证、捕捞限额和禁渔、休渔制度，增殖渔业资源，保护渔业水域生态环境。"},{"i":75,"n":"第七十五条","txt":"国家建立与农业生产有关的生物物种资源保护制度，保护生物多样性，对稀有、濒危、珍贵生物资源及其原生地实行重点保护。国家加强种质资源普查、收集、保护和开发利用，建设国家种质资源库。"},{"i":76,"n":"第七十六条","txt":"国家推进农业发展全面绿色转型，鼓励、支持农民和农业生产经营组织采用节约集约的种植养殖技术，加强农业面源污染防治。"},{"i":77,"n":"第七十七条","txt":"国家优先发展生态循环农业，推进农业废弃物回收、无害化处理和综合利用，鼓励发展种养循环农业。"},{"i":78,"n":"第七十八条","txt":"县级以上人民政府应当采取措施，督促有关单位进行治理，防治废水、废气、固体废物或者其他有毒有害物质对农业生态环境的污染。排放或者倾倒废水、废气、固体废物或者其他有毒有害物质造成农业生态环境污染事故的，由生态环境主管部门或者农业农村主管部门依法调查处理；给农民和农业生产经营组织造成损失的，有关责任者应当依法赔偿。"},{"i":79,"n":"第七十九条","txt":"国家鼓励和支持保护农业资源、发展生态农业，依法实施生态保护补偿，逐步完善农业生态产品价值实现机制。"},{"i":80,"n":"第八十条","txt":"国家采取措施，积极应对气候变化对农业产生的影响。"},{"i":81,"n":"第八十一条","txt":"任何机关或者单位向农民或者农业生产经营组织收取行政、事业性费用必须依据法律、法规的规定。收费的依据、项目、范围和标准应当公布。没有法律、法规依据的收费，农民和农业生产经营组织有权拒绝。"},{"i":82,"n":"第八十二条","txt":"农民和农业生产经营组织依照法律、行政法规的规定承担纳税义务，享受法律、行政法规规定的税收减免。"},{"i":83,"n":"第八十三条","txt":"各级人民政府及其有关部门和所属单位不得以任何方式向农民或者农业生产经营组织集资。"},{"i":84,"n":"第八十四条","txt":"农村义务教育除按国家规定收取的费用外，不得向农民和学生收取其他费用。禁止任何机关或者单位通过农村中小学校向农民收费。"},{"i":85,"n":"第八十五条","txt":"国家为了公共利益的需要依法征收农民集体所有土地的，应当保护农民和农村集体经济组织的合法权益，依法给予征地补偿并安排社会保障费用，任何单位和个人不得截留、挪用。征收农村村民住宅的，应当依法保障其居住的权利和合法的住房财产权益。"},{"i":86,"n":"第八十六条","txt":"各级人民政府、农村集体经济组织或者村民委员会在农业和农村经济结构调整、农业产业化经营和土地经营权流转等过程中，应当充分尊重农民和农业生产经营组织意愿，不得侵害土地承包经营权、土地经营权，不得干涉农民和农业生产经营组织依法自主安排的生产经营项目，不得强行毁坏作物青苗或者盛果期果树，不得强迫农民和农业生产经营组织购买指定的生产资料或者按指定的渠道销售农产品。"},{"i":87,"n":"第八十七条","txt":"农村集体经济组织或者村民委员会为发展生产或者兴办公益事业，需要向其成员（村民）筹资筹劳的，应当依法经成员（村民）会议或者成员（村民）代表会议通过后方可进行。"},{"i":88,"n":"第八十八条","txt":"任何单位和个人向农民或者农业生产经营组织提供生产、技术、信息、文化、保险等有偿服务，必须坚持自愿原则，不得强迫农民和农业生产经营组织接受服务。"},{"i":89,"n":"第八十九条","txt":"农产品收购单位在收购农产品时，不得压级压价，不得在支付的价款中扣缴任何费用。"},{"i":90,"n":"第九十条","txt":"农业生产资料使用者因生产资料质量问题遭受损失的，出售该生产资料的经营者应当予以赔偿，赔偿额包括购货价款、有关费用和可得利益损失。"},{"i":91,"n":"第九十一条","txt":"农民或者农业生产经营组织为维护自身的合法权益，有向各级人民政府及其有关部门反映情况和提出合法要求的权利，人民政府及其有关部门对农民或者农业生产经营组织提出的合理要求，应当按照国家规定及时给予答复。"},{"i":92,"n":"第九十二条","txt":"违反法律规定，侵害农民权益的，农民或者农业生产经营组织可以依法申请行政复议或者向人民法院提起诉讼，有关行政复议机关或者人民法院应当依法受理。"},{"i":93,"n":"第九十三条","txt":"国家加强乡村治理，推进平安乡村建设，构建和谐有序的乡村社会，不断增强广大农民的获得感、幸福感、安全感。"},{"i":94,"n":"第九十四条","txt":"国家坚持城乡融合发展，提高城乡规划、建设、治理融合水平，促进城乡要素平等交换、双向流动，推进公共资源均衡配置，促进城乡共同繁荣。"},{"i":95,"n":"第九十五条","txt":"国土空间规划应当统筹考虑城乡生产、生活、生态用地等需求，合理安排乡村产业、居住、公共服务和基础设施等各类用地。建设用地指标应当保障乡村发展合理需要。"},{"i":96,"n":"第九十六条","txt":"国家促进农村市场经济发展，保障各类经营主体的平等法律地位和发展权利。"},{"i":97,"n":"第九十七条","txt":"县级以上地方人民政府应当根据当地的经济发展水平、区位优势和资源条件，按照合理布局、科学规划、节约用地的原则，有重点地推进农村小城镇建设。"},{"i":98,"n":"第九十八条","txt":"国家统筹城乡就业政策体系，采取措施推动形成平等竞争、规范有序、城乡统一的人力资源市场，健全城乡均等的公共就业创业服务制度，引导劳动力在城乡、地区间合理有序流动。地方各级人民政府依法保护进入城镇就业的农村劳动者的合法权益，不得设置不合理限制，已经设置的应当取消。"},{"i":99,"n":"第九十九条","txt":"国家健全社会保险制度，依法保障农民参加社会保险和享受社会保险待遇的合法权益。"},{"i":100,"n":"第一百条","txt":"国家扶持欠发达地区改善经济发展条件，帮助进行经济开发，统筹建立常态化防止返贫致贫机制，持续巩固拓展脱贫攻坚成果。"},{"i":101,"n":"第一百零一条","txt":"国务院和省级人民政府应当把常态化帮扶投入列入年度财政预算，加大对欠发达地区的财政转移支付和建设资金投入，提高资金使用绩效。"},{"i":102,"n":"第一百零二条","txt":"县级以上人民政府应当采取措施逐步完善适应社会主义市场经济发展要求的农业农村行政管理体制。"},{"i":103,"n":"第一百零三条","txt":"县级以上人民政府农业农村主管部门履行执法监督检查职责时，有权采取下列措施："},{"i":104,"n":"第一百零四条","txt":"农业农村主管部门与农业生产、经营单位必须在机构、人员、财务上彻底分离。农业农村主管部门及其工作人员不得参与和从事农业生产经营活动。"},{"i":105,"n":"第一百零五条","txt":"违反本法规定，侵害农民和农业生产经营组织的土地承包经营权、土地经营权等财产权或者其他合法权益的，应当停止侵害，恢复原状；造成损失、损害的，依法承担赔偿责任。"},{"i":106,"n":"第一百零六条","txt":"违反本法第二十四条、第三十条、第七十三条、第七十五条、第八十五条有关规定的，依照相关法律、行政法规的规定予以处罚。"},{"i":107,"n":"第一百零七条","txt":"有下列行为之一的，由上级主管机关责令限期归还被截留、挪用的资金，没收非法所得，并依法给予直接负责的主管人员和其他直接责任人员处分："},{"i":108,"n":"第一百零八条","txt":"违反本法第八十一条规定，向农民或者农业生产经营组织违法收费、罚款、摊派的，上级主管机关应当予以制止，并予公告；已经收取钱款或者已经使用人力、物力的，由上级主管机关责令限期归还已经收取的钱款或者折价偿还已经使用的人力、物力，并依法给予直接负责的主管人员和其他直接责任人员处分。"},{"i":109,"n":"第一百零九条","txt":"有下列行为之一的，由上级主管机关责令停止违法行为，并依法给予直接负责的主管人员和其他直接责任人员处分，责令退还违法收取的集资款或者费用："},{"i":110,"n":"第一百一十条","txt":"违反本法第八十七条第二款规定，强迫农民以资代劳的，由乡镇人民政府责令改正，并退还违法收取的资金。"},{"i":111,"n":"第一百一十一条","txt":"违反本法第八十八条规定，强迫农民和农业生产经营组织接受有偿服务的，由有关人民政府责令改正，并返还其违法收取的费用；情节严重的，依法给予直接负责的主管人员和其他直接责任人员处分；造成农民和农业生产经营组织损失的，依法承担赔偿责任。"},{"i":112,"n":"第一百一十二条","txt":"县级以上人民政府农业农村主管部门的工作人员违反本法规定参与和从事农业生产经营活动的，依法给予处分。"},{"i":113,"n":"第一百一十三条","txt":"违反本法规定，侵害农民和农业生产经营组织合法权益，构成犯罪的，依法追究刑事责任。"},{"i":114,"n":"第一百一十四条","txt":"国有农场、林场、牧场、渔场等企业事业单位实行承包经营的职工，参照适用本法有关农民的规定。"},{"i":115,"n":"第一百一十五条","txt":"本法自2027年1月1日起施行。"}],"nongyefa":[{"i":1,"n":"第一条","txt":"为了巩固和加强农业在国民经济中的基础地位，深化农村改革，发展农业生产力，推进农业现代化，维护农民和农业生产经营组织的合法权益，增加农民收入，提高农民科学文化素质，促进农业和农村经济的持续、稳定、健康发展，实现全面建设小康社会的目标，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称农业，是指种植业、林业、畜牧业和渔业等产业，包括与其直接相关的产前、产中、产后服务。"},{"i":3,"n":"第三条","txt":"国家把农业放在发展国民经济的首位。"},{"i":4,"n":"第四条","txt":"国家采取措施，保障农业更好地发挥在提供食物、工业原料和其他农产品，维护和改善生态环境，促进农村经济社会发展等多方面的作用。"},{"i":5,"n":"第五条","txt":"国家坚持和完善公有制为主体、多种所有制经济共同发展的基本经济制度，振兴农村经济。"},{"i":6,"n":"第六条","txt":"国家坚持科教兴农和农业可持续发展的方针。"},{"i":7,"n":"第七条","txt":"国家保护农民和农业生产经营组织的财产及其他合法权益不受侵犯。"},{"i":8,"n":"第八条","txt":"全社会应当高度重视农业，支持农业发展。"},{"i":9,"n":"第九条","txt":"各级人民政府对农业和农村经济发展工作统一负责，组织各有关部门和全社会做好发展农业和为发展农业服务的各项工作。"},{"i":10,"n":"第十条","txt":"国家实行农村土地承包经营制度，依法保障农村土地承包关系的长期稳定，保护农民对承包土地的使用权。"},{"i":11,"n":"第十一条","txt":"国家鼓励农民在家庭承包经营的基础上自愿组成各类专业合作经济组织。"},{"i":12,"n":"第十二条","txt":"农民和农业生产经营组织可以自愿按照民主管理、按劳分配和按股分红相结合的原则，以资金、技术、实物等入股，依法兴办各类企业。"},{"i":13,"n":"第十三条","txt":"国家采取措施发展多种形式的农业产业化经营，鼓励和支持农民和农业生产经营组织发展生产、加工、销售一体化经营。"},{"i":14,"n":"第十四条","txt":"农民和农业生产经营组织可以按照法律、行政法规成立各种农产品行业协会，为成员提供生产、营销、信息、技术、培训等服务，发挥协调和自律作用，提出农产品贸易救济措施的申请，维护成员和行业的利益。"},{"i":15,"n":"第十五条","txt":"县级以上人民政府根据国民经济和社会发展的中长期规划、农业和农村经济发展的基本目标和农业资源区划，制定农业发展规划。"},{"i":16,"n":"第十六条","txt":"国家引导和支持农民和农业生产经营组织结合本地实际按照市场需求，调整和优化农业生产结构，协调发展种植业、林业、畜牧业和渔业，发展优质、高产、高效益的农业，提高农产品国际竞争力。"},{"i":17,"n":"第十七条","txt":"各级人民政府应当采取措施，加强农业综合开发和农田水利、农业生态环境保护、乡村道路、农村能源和电网、农产品仓储和流通、渔港、草原围栏、动植物原种良种基地等农业和农村基础设施建设，改善农业生产条件，保护和提高农业综合生产能力。"},{"i":18,"n":"第十八条","txt":"国家扶持动植物品种的选育、生产、更新和良种的推广使用，鼓励品种选育和生产、经营相结合，实施种子工程和畜禽良种工程。国务院和省、自治区、直辖市人民政府设立专项资金，用于扶持动植物良种的选育和推广工作。"},{"i":19,"n":"第十九条","txt":"各级人民政府和农业生产经营组织应当加强农田水利设施建设，建立健全农田水利设施的管理制度，节约用水，发展节水型农业，严格依法控制非农业建设占用灌溉水源，禁止任何组织和个人非法占用或者毁损农田水利设施。"},{"i":20,"n":"第二十条","txt":"国家鼓励和支持农民和农业生产经营组织使用先进、适用的农业机械，加强农业机械安全管理，提高农业机械化水平。"},{"i":21,"n":"第二十一条","txt":"各级人民政府应当支持为农业服务的气象事业的发展，提高对气象灾害的监测和预报水平。"},{"i":22,"n":"第二十二条","txt":"国家采取措施提高农产品的质量，建立健全农产品质量标准体系和质量检验检测监督体系，按照有关技术规范、操作规程和质量卫生安全标准，组织农产品的生产经营，保障农产品质量安全。"},{"i":23,"n":"第二十三条","txt":"国家支持依法建立健全优质农产品认证和标志制度。"},{"i":24,"n":"第二十四条","txt":"国家实行动植物防疫、检疫制度，健全动植物防疫、检疫体系，加强对动物疫病和植物病、虫、杂草、鼠害的监测、预警、防治，建立重大动物疫情和植物病虫害的快速扑灭机制，建设动物无规定疫病区，实施植物保护工程。"},{"i":25,"n":"第二十五条","txt":"农药、兽药、饲料和饲料添加剂、肥料、种子、农业机械等可能危害人畜安全的农业生产资料的生产经营，依照相关法律、行政法规的规定实行登记或者许可制度。"},{"i":26,"n":"第二十六条","txt":"农产品的购销实行市场调节。国家对关系国计民生的重要农产品的购销活动实行必要的宏观调控，建立中央和地方分级储备调节制度，完善仓储运输体系，做到保证供应，稳定市场。"},{"i":27,"n":"第二十七条","txt":"国家逐步建立统一、开放、竞争、有序的农产品市场体系，制定农产品批发市场发展规划。对农村集体经济组织和农民专业合作经济组织建立农产品批发市场和农产品集贸市场，国家给予扶持。"},{"i":28,"n":"第二十八条","txt":"国家鼓励和支持发展多种形式的农产品流通活动。支持农民和农民专业合作经济组织按照国家有关规定从事农产品收购、批发、贮藏、运输、零售和中介活动。鼓励供销合作社和其他从事农产品购销的农业生产经营组织提供市场信息，开拓农产品流通渠道，为农产品销售服务。"},{"i":29,"n":"第二十九条","txt":"国家支持发展农产品加工业和食品工业，增加农产品的附加值。县级以上人民政府应当制定农产品加工业和食品工业发展规划，引导农产品加工企业形成合理的区域布局和规模结构，扶持农民专业合作经济组织和乡镇企业从事农产品加工和综合开发利用。"},{"i":30,"n":"第三十条","txt":"国家鼓励发展农产品进出口贸易。"},{"i":31,"n":"第三十一条","txt":"国家采取措施保护和提高粮食综合生产能力，稳步提高粮食生产水平，保障粮食安全。"},{"i":32,"n":"第三十二条","txt":"国家在政策、资金、技术等方面对粮食主产区给予重点扶持，建设稳定的商品粮生产基地，改善粮食收贮及加工设施，提高粮食主产区的粮食生产、加工水平和经济效益。"},{"i":33,"n":"第三十三条","txt":"在粮食的市场价格过低时，国务院可以决定对部分粮食品种实行保护价制度。保护价应当根据有利于保护农民利益、稳定粮食生产的原则确定。"},{"i":34,"n":"第三十四条","txt":"国家建立粮食安全预警制度，采取措施保障粮食供给。国务院应当制定粮食安全保障目标与粮食储备数量指标，并根据需要组织有关主管部门进行耕地、粮食库存情况的核查。"},{"i":35,"n":"第三十五条","txt":"国家建立粮食风险基金，用于支持粮食储备、稳定粮食市场和保护农民利益。"},{"i":36,"n":"第三十六条","txt":"国家提倡珍惜和节约粮食，并采取措施改善人民的食物营养结构。"},{"i":37,"n":"第三十七条","txt":"国家建立和完善农业支持保护体系，采取财政投入、税收优惠、金融支持等措施，从资金投入、科研与技术推广、教育培训、农业生产资料供应、市场信息、质量标准、检验检疫、社会化服务以及灾害救助等方面扶持农民和农业生产经营组织发展农业生产，提高农民的收入水平。"},{"i":38,"n":"第三十八条","txt":"国家逐步提高农业投入的总体水平。中央和县级以上地方财政每年对农业总投入的增长幅度应当高于其财政经常性收入的增长幅度。"},{"i":39,"n":"第三十九条","txt":"县级以上人民政府每年财政预算内安排的各项用于农业的资金应当及时足额拨付。各级人民政府应当加强对国家各项农业资金分配、使用过程的监督管理，保证资金安全，提高资金的使用效率。"},{"i":40,"n":"第四十条","txt":"国家运用税收、价格、信贷等手段，鼓励和引导农民和农业生产经营组织增加农业生产经营性投入和小型农田水利等基本建设投入。"},{"i":41,"n":"第四十一条","txt":"国家鼓励社会资金投向农业，鼓励企业事业单位、社会团体和个人捐资设立各种农业建设和农业科技、教育基金。"},{"i":42,"n":"第四十二条","txt":"各级人民政府应当鼓励和支持企业事业单位及其他各类经济组织开展农业信息服务。"},{"i":43,"n":"第四十三条","txt":"国家鼓励和扶持农用工业的发展。"},{"i":44,"n":"第四十四条","txt":"国家鼓励供销合作社、农村集体经济组织、农民专业合作经济组织、其他组织和个人发展多种形式的农业生产产前、产中、产后的社会化服务事业。县级以上人民政府及其各有关部门应当采取措施对农业社会化服务事业给予支持。"},{"i":45,"n":"第四十五条","txt":"国家建立健全农村金融体系，加强农村信用制度建设，加强农村金融监管。"},{"i":46,"n":"第四十六条","txt":"国家建立和完善农业保险制度。"},{"i":47,"n":"第四十七条","txt":"各级人民政府应当采取措施，提高农业防御自然灾害的能力，做好防灾、抗灾和救灾工作，帮助灾民恢复生产，组织生产自救，开展社会互助互济；对没有基本生活保障的灾民给予救济和扶持。"},{"i":48,"n":"第四十八条","txt":"国务院和省级人民政府应当制定农业科技、农业教育发展规划，发展农业科技、教育事业。"},{"i":49,"n":"第四十九条","txt":"国家保护植物新品种、农产品地理标志等知识产权，鼓励和引导农业科研、教育单位加强农业科学技术的基础研究和应用研究，传播和普及农业科学技术知识，加速科技成果转化与产业化，促进农业科学技术进步。"},{"i":50,"n":"第五十条","txt":"国家扶持农业技术推广事业，建立政府扶持和市场引导相结合，有偿与无偿服务相结合，国家农业技术推广机构和社会力量相结合的农业技术推广体系，促使先进的农业技术尽快应用于农业生产。"},{"i":51,"n":"第五十一条","txt":"国家设立的农业技术推广机构应当以农业技术试验示范基地为依托，承担公共所需的关键性技术的推广和示范等公益性职责，为农民和农业生产经营组织提供无偿农业技术服务。"},{"i":52,"n":"第五十二条","txt":"农业科研单位、有关学校、农民专业合作社、涉农企业、群众性科技组织及有关科技人员，根据农民和农业生产经营组织的需要，可以提供无偿服务，也可以通过技术转让、技术服务、技术承包、技术咨询和技术入股等形式，提供有偿服务，取得合法收益。农业科研单位、有关学校、农民专业合作社、涉农企业、群众性科技组织及有关科技人员应当提高服务水平，保证服务质量。"},{"i":53,"n":"第五十三条","txt":"国家建立农业专业技术人员继续教育制度。县级以上人民政府农业行政主管部门会同教育、人事等有关部门制定农业专业技术人员继续教育计划，并组织实施。"},{"i":54,"n":"第五十四条","txt":"国家在农村依法实施义务教育，并保障义务教育经费。国家在农村举办的普通中小学校教职工工资由县级人民政府按照国家规定统一发放，校舍等教学设施的建设和维护经费由县级人民政府按照国家规定统一安排。"},{"i":55,"n":"第五十五条","txt":"国家发展农业职业教育。国务院有关部门按照国家职业资格证书制度的统一规定，开展农业行业的职业分类、职业技能鉴定工作，管理农业行业的职业资格证书。"},{"i":56,"n":"第五十六条","txt":"国家采取措施鼓励农民采用先进的农业技术，支持农民举办各种科技组织，开展农业实用技术培训、农民绿色证书培训和其他就业培训，提高农民的文化技术素质。"},{"i":57,"n":"第五十七条","txt":"发展农业和农村经济必须合理利用和保护土地、水、森林、草原、野生动植物等自然资源，合理开发和利用水能、沼气、太阳能、风能等可再生能源和清洁能源，发展生态农业，保护和改善生态环境。"},{"i":58,"n":"第五十八条","txt":"农民和农业生产经营组织应当保养耕地，合理使用化肥、农药、农用薄膜，增加使用有机肥料，采用先进技术，保护和提高地力，防止农用地的污染、破坏和地力衰退。"},{"i":59,"n":"第五十九条","txt":"各级人民政府应当采取措施，加强小流域综合治理，预防和治理水土流失。从事可能引起水土流失的生产建设活动的单位和个人，必须采取预防措施，并负责治理因生产建设活动造成的水土流失。"},{"i":60,"n":"第六十条","txt":"国家实行全民义务植树制度。各级人民政府应当采取措施，组织群众植树造林，保护林地和林木，预防森林火灾，防治森林病虫害，制止滥伐、盗伐林木，提高森林覆盖率。"},{"i":61,"n":"第六十一条","txt":"有关地方人民政府，应当加强草原的保护、建设和管理，指导、组织农（牧）民和农（牧）业生产经营组织建设人工草场、饲草饲料基地和改良天然草原，实行以草定畜，控制载畜量，推行划区轮牧、休牧和禁牧制度，保护草原植被，防止草原退化沙化和盐渍化。"},{"i":62,"n":"第六十二条","txt":"禁止毁林毁草开垦、烧山开垦以及开垦国家禁止开垦的陡坡地，已经开垦的应当逐步退耕还林、还草。"},{"i":63,"n":"第六十三条","txt":"各级人民政府应当采取措施，依法执行捕捞限额和禁渔、休渔制度，增殖渔业资源，保护渔业水域生态环境。"},{"i":64,"n":"第六十四条","txt":"国家建立与农业生产有关的生物物种资源保护制度，保护生物多样性，对稀有、濒危、珍贵生物资源及其原生地实行重点保护。从境外引进生物物种资源应当依法进行登记或者审批，并采取相应安全控制措施。"},{"i":65,"n":"第六十五条","txt":"各级农业行政主管部门应当引导农民和农业生产经营组织采取生物措施或者使用高效低毒低残留农药、兽药，防治动植物病、虫、杂草、鼠害。"},{"i":66,"n":"第六十六条","txt":"县级以上人民政府应当采取措施，督促有关单位进行治理，防治废水、废气和固体废弃物对农业生态环境的污染。排放废水、废气和固体废弃物造成农业生态环境污染事故的，由环境保护行政主管部门或者农业行政主管部门依法调查处理；给农民和农业生产经营组织造成损失的，有关责任者应当依法赔偿。"},{"i":67,"n":"第六十七条","txt":"任何机关或者单位向农民或者农业生产经营组织收取行政、事业性费用必须依据法律、法规的规定。收费的项目、范围和标准应当公布。没有法律、法规依据的收费，农民和农业生产经营组织有权拒绝。"},{"i":68,"n":"第六十八条","txt":"各级人民政府及其有关部门和所属单位不得以任何方式向农民或者农业生产经营组织集资。"},{"i":69,"n":"第六十九条","txt":"农民和农业生产经营组织依照法律、行政法规的规定承担纳税义务。税务机关及代扣、代收税款的单位应当依法征税，不得违法摊派税款及以其他违法方法征税。"},{"i":70,"n":"第七十条","txt":"农村义务教育除按国务院规定收取的费用外，不得向农民和学生收取其他费用。禁止任何机关或者单位通过农村中小学校向农民收费。"},{"i":71,"n":"第七十一条","txt":"国家依法征收农民集体所有的土地，应当保护农民和农村集体经济组织的合法权益，依法给予农民和农村集体经济组织征地补偿，任何单位和个人不得截留、挪用征地补偿费用。"},{"i":72,"n":"第七十二条","txt":"各级人民政府、农村集体经济组织或者村民委员会在农业和农村经济结构调整、农业产业化经营和土地承包经营权流转等过程中，不得侵犯农民的土地承包经营权，不得干涉农民自主安排的生产经营项目，不得强迫农民购买指定的生产资料或者按指定的渠道销售农产品。"},{"i":73,"n":"第七十三条","txt":"农村集体经济组织或者村民委员会为发展生产或者兴办公益事业，需要向其成员（村民）筹资筹劳的，应当经成员（村民）会议或者成员（村民）代表会议过半数通过后，方可进行。"},{"i":74,"n":"第七十四条","txt":"任何单位和个人向农民或者农业生产经营组织提供生产、技术、信息、文化、保险等有偿服务，必须坚持自愿原则，不得强迫农民和农业生产经营组织接受服务。"},{"i":75,"n":"第七十五条","txt":"农产品收购单位在收购农产品时，不得压级压价，不得在支付的价款中扣缴任何费用。法律、行政法规规定代扣、代收税款的，依照法律、行政法规的规定办理。"},{"i":76,"n":"第七十六条","txt":"农业生产资料使用者因生产资料质量问题遭受损失的，出售该生产资料的经营者应当予以赔偿，赔偿额包括购货价款、有关费用和可得利益损失。"},{"i":77,"n":"第七十七条","txt":"农民或者农业生产经营组织为维护自身的合法权益，有向各级人民政府及其有关部门反映情况和提出合法要求的权利，人民政府及其有关部门对农民或者农业生产经营组织提出的合理要求，应当按照国家规定及时给予答复。"},{"i":78,"n":"第七十八条","txt":"违反法律规定，侵犯农民权益的，农民或者农业生产经营组织可以依法申请行政复议或者向人民法院提起诉讼，有关人民政府及其有关部门或者人民法院应当依法受理。"},{"i":79,"n":"第七十九条","txt":"国家坚持城乡协调发展的方针，扶持农村第二、第三产业发展，调整和优化农村经济结构，增加农民收入，促进农村经济全面发展，逐步缩小城乡差别。"},{"i":80,"n":"第八十条","txt":"各级人民政府应当采取措施，发展乡镇企业，支持农业的发展，转移富余的农业劳动力。"},{"i":81,"n":"第八十一条","txt":"县级以上地方人民政府应当根据当地的经济发展水平、区位优势和资源条件，按照合理布局、科学规划、节约用地的原则，有重点地推进农村小城镇建设。"},{"i":82,"n":"第八十二条","txt":"国家采取措施引导农村富余劳动力在城乡、地区间合理有序流动。地方各级人民政府依法保护进入城镇就业的农村劳动力的合法权益，不得设置不合理限制，已经设置的应当取消。"},{"i":83,"n":"第八十三条","txt":"国家逐步完善农村社会救济制度，保障农村五保户、贫困残疾农民、贫困老年农民和其他丧失劳动能力的农民的基本生活。"},{"i":84,"n":"第八十四条","txt":"国家鼓励、支持农民巩固和发展农村合作医疗和其他医疗保障形式，提高农民健康水平。"},{"i":85,"n":"第八十五条","txt":"国家扶持贫困地区改善经济发展条件，帮助进行经济开发。省级人民政府根据国家关于扶持贫困地区的总体目标和要求，制定扶贫开发规划，并组织实施。"},{"i":86,"n":"第八十六条","txt":"中央和省级财政应当把扶贫开发投入列入年度财政预算，并逐年增加，加大对贫困地区的财政转移支付和建设资金投入。"},{"i":87,"n":"第八十七条","txt":"县级以上人民政府应当采取措施逐步完善适应社会主义市场经济发展要求的农业行政管理体制。"},{"i":88,"n":"第八十八条","txt":"县级以上人民政府农业行政主管部门及其执法人员履行执法监督检查职责时，有权采取下列措施："},{"i":89,"n":"第八十九条","txt":"农业行政主管部门与农业生产、经营单位必须在机构、人员、财务上彻底分离。农业行政主管部门及其工作人员不得参与和从事农业生产经营活动。"},{"i":90,"n":"第九十条","txt":"违反本法规定，侵害农民和农业生产经营组织的土地承包经营权等财产权或者其他合法权益的，应当停止侵害，恢复原状；造成损失、损害的，依法承担赔偿责任。"},{"i":91,"n":"第九十一条","txt":"违反本法第十九条、第二十五条、第六十二条、第七十一条规定的，依照相关法律或者行政法规的规定予以处罚。"},{"i":92,"n":"第九十二条","txt":"有下列行为之一的，由上级主管机关责令限期归还被截留、挪用的资金，没收非法所得，并由上级主管机关或者所在单位给予直接负责的主管人员和其他直接责任人员行政处分；构成犯罪的，依法追究刑事责任："},{"i":93,"n":"第九十三条","txt":"违反本法第六十七条规定，向农民或者农业生产经营组织违法收费、罚款、摊派的，上级主管机关应当予以制止，并予公告；已经收取钱款或者已经使用人力、物力的，由上级主管机关责令限期归还已经收取的钱款或者折价偿还已经使用的人力、物力，并由上级主管机关或者所在单位给予直接负责的主管人员和其他直接责任人员行政处分；情节严重，构成犯罪的，依法追究刑事责任。"},{"i":94,"n":"第九十四条","txt":"有下列行为之一的，由上级主管机关责令停止违法行为，并给予直接负责的主管人员和其他直接责任人员行政处分，责令退还违法收取的集资款、税款或者费用："},{"i":95,"n":"第九十五条","txt":"违反本法第七十三条第二款规定，强迫农民以资代劳的，由乡（镇）人民政府责令改正，并退还违法收取的资金。"},{"i":96,"n":"第九十六条","txt":"违反本法第七十四条规定，强迫农民和农业生产经营组织接受有偿服务的，由有关人民政府责令改正，并返还其违法收取的费用；情节严重的，给予直接负责的主管人员和其他直接责任人员行政处分；造成农民和农业生产经营组织损失的，依法承担赔偿责任。"},{"i":97,"n":"第九十七条","txt":"县级以上人民政府农业行政主管部门的工作人员违反本法规定参与和从事农业生产经营活动的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":98,"n":"第九十八条","txt":"本法有关农民的规定，适用于国有农场、牧场、林场、渔场等企业事业单位实行承包经营的职工。"},{"i":99,"n":"第九十九条","txt":"本法自2003年3月1日起施行。"}],"nongchanpinzhilianganquanfa":[{"i":1,"n":"第一条","txt":"为了保障农产品质量安全，维护公众健康，促进农业和农村经济发展，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称农产品，是指来源于种植业、林业、畜牧业和渔业等的初级产品，即在农业活动中获得的植物、动物、微生物及其产品。"},{"i":3,"n":"第三条","txt":"与农产品质量安全有关的农产品生产经营及其监督管理活动，适用本法。"},{"i":4,"n":"第四条","txt":"国家加强农产品质量安全工作，实行源头治理、风险管理、全程控制，建立科学、严格的监督管理制度，构建协同、高效的社会共治体系。"},{"i":5,"n":"第五条","txt":"国务院农业农村主管部门、市场监督管理部门依照本法和规定的职责，对农产品质量安全实施监督管理。"},{"i":6,"n":"第六条","txt":"县级以上地方人民政府对本行政区域的农产品质量安全工作负责，统一领导、组织、协调本行政区域的农产品质量安全工作，建立健全农产品质量安全工作机制，提高农产品质量安全水平。"},{"i":7,"n":"第七条","txt":"农产品生产经营者应当对其生产经营的农产品质量安全负责。"},{"i":8,"n":"第八条","txt":"县级以上人民政府应当将农产品质量安全管理工作纳入本级国民经济和社会发展规划，所需经费列入本级预算，加强农产品质量安全监督管理能力建设。"},{"i":9,"n":"第九条","txt":"国家引导、推广农产品标准化生产，鼓励和支持生产绿色优质农产品，禁止生产、销售不符合国家规定的农产品质量安全标准的农产品。"},{"i":10,"n":"第十条","txt":"国家支持农产品质量安全科学技术研究，推行科学的质量安全管理方法，推广先进安全的生产技术。国家加强农产品质量安全科学技术国际交流与合作。"},{"i":11,"n":"第十一条","txt":"各级人民政府及有关部门应当加强农产品质量安全知识的宣传，发挥基层群众性自治组织、农村集体经济组织的优势和作用，指导农产品生产经营者加强质量安全管理，保障农产品消费安全。"},{"i":12,"n":"第十二条","txt":"农民专业合作社和农产品行业协会等应当及时为其成员提供生产技术服务，建立农产品质量安全管理制度，健全农产品质量安全控制体系，加强自律管理。"},{"i":13,"n":"第十三条","txt":"国家建立农产品质量安全风险监测制度。"},{"i":14,"n":"第十四条","txt":"国家建立农产品质量安全风险评估制度。"},{"i":15,"n":"第十五条","txt":"国务院农业农村主管部门应当根据农产品质量安全风险监测、风险评估结果采取相应的管理措施，并将农产品质量安全风险监测、风险评估结果及时通报国务院市场监督管理、卫生健康等部门和有关省、自治区、直辖市人民政府农业农村主管部门。"},{"i":16,"n":"第十六条","txt":"国家建立健全农产品质量安全标准体系，确保严格实施。农产品质量安全标准是强制执行的标准，包括以下与农产品质量安全有关的要求："},{"i":17,"n":"第十七条","txt":"农产品质量安全标准的制定和发布，依照法律、行政法规的规定执行。"},{"i":18,"n":"第十八条","txt":"农产品质量安全标准应当根据科学技术发展水平以及农产品质量安全的需要，及时修订。"},{"i":19,"n":"第十九条","txt":"农产品质量安全标准由农业农村主管部门商有关部门推进实施。"},{"i":20,"n":"第二十条","txt":"国家建立健全农产品产地监测制度。"},{"i":21,"n":"第二十一条","txt":"县级以上地方人民政府农业农村主管部门应当会同同级生态环境、自然资源等部门按照保障农产品质量安全的要求，根据农产品品种特性和产地安全调查、监测、评价结果，依照土壤污染防治等法律、法规的规定提出划定特定农产品禁止生产区域的建议，报本级人民政府批准后实施。"},{"i":22,"n":"第二十二条","txt":"任何单位和个人不得违反有关环境保护法律、法规的规定向农产品产地排放或者倾倒废水、废气、固体废物或者其他有毒有害物质。"},{"i":23,"n":"第二十三条","txt":"农产品生产者应当科学合理使用农药、兽药、肥料、农用薄膜等农业投入品，防止对农产品产地造成污染。"},{"i":24,"n":"第二十四条","txt":"县级以上人民政府应当采取措施，加强农产品基地建设，推进农业标准化示范建设，改善农产品的生产条件。"},{"i":25,"n":"第二十五条","txt":"县级以上地方人民政府农业农村主管部门应当根据本地区的实际情况，制定保障农产品质量安全的生产技术要求和操作规程，并加强对农产品生产经营者的培训和指导。"},{"i":26,"n":"第二十六条","txt":"农产品生产企业、农民专业合作社、农业社会化服务组织应当加强农产品质量安全管理。"},{"i":27,"n":"第二十七条","txt":"农产品生产企业、农民专业合作社、农业社会化服务组织应当建立农产品生产记录，如实记载下列事项："},{"i":28,"n":"第二十八条","txt":"对可能影响农产品质量安全的农药、兽药、饲料和饲料添加剂、肥料、兽医器械，依照有关法律、行政法规的规定实行许可制度。"},{"i":29,"n":"第二十九条","txt":"农产品生产经营者应当依照有关法律、行政法规和国家有关强制性标准、国务院农业农村主管部门的规定，科学合理使用农药、兽药、饲料和饲料添加剂、肥料等农业投入品，严格执行农业投入品使用安全间隔期或者休药期的规定；不得超范围、超剂量使用农业投入品危及农产品质量安全。"},{"i":30,"n":"第三十条","txt":"农产品生产场所以及生产活动中使用的设施、设备、消毒剂、洗涤剂等应当符合国家有关质量安全规定，防止污染农产品。"},{"i":31,"n":"第三十一条","txt":"县级以上人民政府农业农村主管部门应当加强对农业投入品使用的监督管理和指导，建立健全农业投入品的安全使用制度，推广农业投入品科学使用技术，普及安全、环保农业投入品的使用。"},{"i":32,"n":"第三十二条","txt":"国家鼓励和支持农产品生产经营者选用优质特色农产品品种，采用绿色生产技术和全程质量控制技术，生产绿色优质农产品，实施分等分级，提高农产品品质，打造农产品品牌。"},{"i":33,"n":"第三十三条","txt":"国家支持农产品产地冷链物流基础设施建设，健全有关农产品冷链物流标准、服务规范和监管保障机制，保障冷链物流农产品畅通高效、安全便捷，扩大高品质市场供给。"},{"i":34,"n":"第三十四条","txt":"销售的农产品应当符合农产品质量安全标准。"},{"i":35,"n":"第三十五条","txt":"农产品在包装、保鲜、储存、运输中所使用的保鲜剂、防腐剂、添加剂、包装材料等，应当符合国家有关强制性标准以及其他农产品质量安全规定。"},{"i":36,"n":"第三十六条","txt":"有下列情形之一的农产品，不得销售："},{"i":37,"n":"第三十七条","txt":"农产品批发市场应当按照规定设立或者委托检测机构，对进场销售的农产品质量安全状况进行抽查检测；发现不符合农产品质量安全标准的，应当要求销售者立即停止销售，并向所在地市场监督管理、农业农村等部门报告。"},{"i":38,"n":"第三十八条","txt":"农产品生产企业、农民专业合作社以及从事农产品收购的单位或者个人销售的农产品，按照规定应当包装或者附加承诺达标合格证等标识的，须经包装或者附加标识后方可销售。包装物或者标识上应当按照规定标明产品的品名、产地、生产者、生产日期、保质期、产品质量等级等内容；使用添加剂的，还应当按照规定标明添加剂的名称。具体办法由国务院农业农村主管部门制定。"},{"i":39,"n":"第三十九条","txt":"农产品生产企业、农民专业合作社应当执行法律、法规的规定和国家有关强制性标准，保证其销售的农产品符合农产品质量安全标准，并根据质量安全控制、检测结果等开具承诺达标合格证，承诺不使用禁用的农药、兽药及其他化合物且使用的常规农药、兽药残留不超标等。鼓励和支持农户销售农产品时开具承诺达标合格证。法律、行政法规对畜禽产品的质量安全合格证明有特别规定的，应当遵守其规定。"},{"i":40,"n":"第四十条","txt":"农产品生产经营者通过网络平台销售农产品的，应当依照本法和《中华人民共和国电子商务法》、《中华人民共和国食品安全法》等法律、法规的规定，严格落实质量安全责任，保证其销售的农产品符合质量安全标准。网络平台经营者应当依法加强对农产品生产经营者的管理。"},{"i":41,"n":"第四十一条","txt":"国家对列入农产品质量安全追溯目录的农产品实施追溯管理。国务院农业农村主管部门应当会同国务院市场监督管理等部门建立农产品质量安全追溯协作机制。农产品质量安全追溯管理办法和追溯目录由国务院农业农村主管部门会同国务院市场监督管理等部门制定。"},{"i":42,"n":"第四十二条","txt":"农产品质量符合国家规定的有关优质农产品标准的，农产品生产经营者可以申请使用农产品质量标志。禁止冒用农产品质量标志。"},{"i":43,"n":"第四十三条","txt":"属于农业转基因生物的农产品，应当按照农业转基因生物安全管理的有关规定进行标识。"},{"i":44,"n":"第四十四条","txt":"依法需要实施检疫的动植物及其产品，应当附具检疫标志、检疫证明。"},{"i":45,"n":"第四十五条","txt":"县级以上人民政府农业农村主管部门和市场监督管理等部门应当建立健全农产品质量安全全程监督管理协作机制，确保农产品从生产到消费各环节的质量安全。"},{"i":46,"n":"第四十六条","txt":"县级以上人民政府农业农村主管部门应当根据农产品质量安全风险监测、风险评估结果和农产品质量安全状况等，制定监督抽查计划，确定农产品质量安全监督抽查的重点、方式和频次，并实施农产品质量安全风险分级管理。"},{"i":47,"n":"第四十七条","txt":"县级以上人民政府农业农村主管部门应当建立健全随机抽查机制，按照监督抽查计划，组织开展农产品质量安全监督抽查。"},{"i":48,"n":"第四十八条","txt":"农产品质量安全检测应当充分利用现有的符合条件的检测机构。"},{"i":49,"n":"第四十九条","txt":"从事农产品质量安全检测工作的人员，应当具备相应的专业知识和实际操作技能，遵纪守法，恪守职业道德。"},{"i":50,"n":"第五十条","txt":"县级以上地方人民政府农业农村主管部门可以采用国务院农业农村主管部门会同国务院市场监督管理等部门认定的快速检测方法，开展农产品质量安全监督抽查检测。抽查检测结果确定有关农产品不符合农产品质量安全标准的，可以作为行政处罚的证据。"},{"i":51,"n":"第五十一条","txt":"农产品生产经营者对监督抽查检测结果有异议的，可以自收到检测结果之日起五个工作日内，向实施农产品质量安全监督抽查的农业农村主管部门或者其上一级农业农村主管部门申请复检。复检机构与初检机构不得为同一机构。"},{"i":52,"n":"第五十二条","txt":"县级以上地方人民政府农业农村主管部门应当加强对农产品生产的监督管理，开展日常检查，重点检查农产品产地环境、农业投入品购买和使用、农产品生产记录、承诺达标合格证开具等情况。"},{"i":53,"n":"第五十三条","txt":"开展农产品质量安全监督检查，有权采取下列措施："},{"i":54,"n":"第五十四条","txt":"县级以上人民政府农业农村等部门应当加强农产品质量安全信用体系建设，建立农产品生产经营者信用记录，记载行政处罚等信息，推进农产品质量安全信用信息的应用和管理。"},{"i":55,"n":"第五十五条","txt":"农产品生产经营过程中存在质量安全隐患，未及时采取措施消除的，县级以上地方人民政府农业农村主管部门可以对农产品生产经营者的法定代表人或者主要负责人进行责任约谈。农产品生产经营者应当立即采取措施，进行整改，消除隐患。"},{"i":56,"n":"第五十六条","txt":"国家鼓励消费者协会和其他单位或者个人对农产品质量安全进行社会监督，对农产品质量安全监督管理工作提出意见和建议。任何单位和个人有权对违反本法的行为进行检举控告、投诉举报。"},{"i":57,"n":"第五十七条","txt":"县级以上地方人民政府农业农村主管部门应当加强对农产品质量安全执法人员的专业技术培训并组织考核。不具备相应知识和能力的，不得从事农产品质量安全执法工作。"},{"i":58,"n":"第五十八条","txt":"上级人民政府应当督促下级人民政府履行农产品质量安全职责。对农产品质量安全责任落实不力、问题突出的地方人民政府，上级人民政府可以对其主要负责人进行责任约谈。被约谈的地方人民政府应当立即采取整改措施。"},{"i":59,"n":"第五十九条","txt":"国务院农业农村主管部门应当会同国务院有关部门制定国家农产品质量安全突发事件应急预案，并与国家食品安全事故应急预案相衔接。"},{"i":60,"n":"第六十条","txt":"县级以上地方人民政府市场监督管理部门依照本法和《中华人民共和国食品安全法》等法律、法规的规定，对农产品进入批发、零售市场或者生产加工企业后的生产经营活动进行监督检查。"},{"i":61,"n":"第六十一条","txt":"县级以上人民政府农业农村、市场监督管理等部门发现农产品质量安全违法行为涉嫌犯罪的，应当及时将案件移送公安机关。对移送的案件，公安机关应当及时审查；认为有犯罪事实需要追究刑事责任的，应当立案侦查。"},{"i":62,"n":"第六十二条","txt":"违反本法规定，地方各级人民政府有下列情形之一的，对直接负责的主管人员和其他直接责任人员给予警告、记过、记大过处分；造成严重后果的，给予降级或者撤职处分："},{"i":63,"n":"第六十三条","txt":"违反本法规定，县级以上人民政府农业农村等部门有下列行为之一的，对直接负责的主管人员和其他直接责任人员给予记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分；造成严重后果的，其主要负责人还应当引咎辞职："},{"i":64,"n":"第六十四条","txt":"县级以上地方人民政府农业农村、市场监督管理等部门在履行农产品质量安全监督管理职责过程中，违法实施检查、强制等执法措施，给农产品生产经营者造成损失的，应当依法予以赔偿，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":65,"n":"第六十五条","txt":"农产品质量安全检测机构、检测人员出具虚假检测报告的，由县级以上人民政府农业农村主管部门没收所收取的检测费用，检测费用不足一万元的，并处五万元以上十万元以下罚款，检测费用一万元以上的，并处检测费用五倍以上十倍以下罚款；对直接负责的主管人员和其他直接责任人员处一万元以上五万元以下罚款；使消费者的合法权益受到损害的，农产品质量安全检测机构应当与农产品生产经营者承担连带责任。"},{"i":66,"n":"第六十六条","txt":"违反本法规定，在特定农产品禁止生产区域种植、养殖、捕捞、采集特定农产品或者建立特定农产品生产基地的，由县级以上地方人民政府农业农村主管部门责令停止违法行为，没收农产品和违法所得，并处违法所得一倍以上三倍以下罚款。"},{"i":67,"n":"第六十七条","txt":"农药、肥料、农用薄膜等农业投入品的生产者、经营者、使用者未按照规定回收并妥善处置包装物或者废弃物的，由县级以上地方人民政府农业农村主管部门依照有关法律、法规的规定处理、处罚。"},{"i":68,"n":"第六十八条","txt":"违反本法规定，农产品生产企业有下列情形之一的，由县级以上地方人民政府农业农村主管部门责令限期改正；逾期不改正的，处五千元以上五万元以下罚款："},{"i":69,"n":"第六十九条","txt":"农产品生产企业、农民专业合作社、农业社会化服务组织未依照本法规定建立、保存农产品生产记录，或者伪造、变造农产品生产记录的，由县级以上地方人民政府农业农村主管部门责令限期改正；逾期不改正的，处二千元以上二万元以下罚款。"},{"i":70,"n":"第七十条","txt":"违反本法规定，农产品生产经营者有下列行为之一，尚不构成犯罪的，由县级以上地方人民政府农业农村主管部门责令停止生产经营、追回已经销售的农产品，对违法生产经营的农产品进行无害化处理或者予以监督销毁，没收违法所得，并可以没收用于违法生产经营的工具、设备、原料等物品；违法生产经营的农产品货值金额不足一万元的，并处十万元以上十五万元以下罚款，货值金额一万元以上的，并处货值金额十五倍以上三十倍以下罚款；对农户，并处一千元以上一万元以下罚款；情节严重的，有许可证的吊销许可证，并可以由公安机关对其直接负责的主管人员和其他直接责任人员处五日以上十五日以下拘留："},{"i":71,"n":"第七十一条","txt":"违反本法规定，农产品生产经营者有下列行为之一，尚不构成犯罪的，由县级以上地方人民政府农业农村主管部门责令停止生产经营、追回已经销售的农产品，对违法生产经营的农产品进行无害化处理或者予以监督销毁，没收违法所得，并可以没收用于违法生产经营的工具、设备、原料等物品；违法生产经营的农产品货值金额不足一万元的，并处五万元以上十万元以下罚款，货值金额一万元以上的，并处货值金额十倍以上二十倍以下罚款；对农户，并处五百元以上五千元以下罚款："},{"i":72,"n":"第七十二条","txt":"违反本法规定，农产品生产经营者有下列行为之一的，由县级以上地方人民政府农业农村主管部门责令停止生产经营、追回已经销售的农产品，对违法生产经营的农产品进行无害化处理或者予以监督销毁，没收违法所得，并可以没收用于违法生产经营的工具、设备、原料等物品；违法生产经营的农产品货值金额不足一万元的，并处五千元以上五万元以下罚款，货值金额一万元以上的，并处货值金额五倍以上十倍以下罚款；对农户，并处三百元以上三千元以下罚款："},{"i":73,"n":"第七十三条","txt":"违反本法规定，有下列行为之一的，由县级以上地方人民政府农业农村主管部门按照职责给予批评教育，责令限期改正；逾期不改正的，处一百元以上一千元以下罚款："},{"i":74,"n":"第七十四条","txt":"农产品生产经营者冒用农产品质量标志，或者销售冒用农产品质量标志的农产品的，由县级以上地方人民政府农业农村主管部门按照职责责令改正，没收违法所得；违法生产经营的农产品货值金额不足五千元的，并处五千元以上五万元以下罚款，货值金额五千元以上的，并处货值金额十倍以上二十倍以下罚款。"},{"i":75,"n":"第七十五条","txt":"违反本法关于农产品质量安全追溯规定的，由县级以上地方人民政府农业农村主管部门按照职责责令限期改正；逾期不改正的，可以处一万元以下罚款。"},{"i":76,"n":"第七十六条","txt":"违反本法规定，拒绝、阻挠依法开展的农产品质量安全监督检查、事故调查处理、抽样检测和风险评估的，由有关主管部门按照职责责令停产停业，并处二千元以上五万元以下罚款；构成违反治安管理行为的，由公安机关依法给予治安管理处罚。"},{"i":77,"n":"第七十七条","txt":"《中华人民共和国食品安全法》对食用农产品进入批发、零售市场或者生产加工企业后的违法行为和法律责任有规定的，由县级以上地方人民政府市场监督管理部门依照其规定进行处罚。"},{"i":78,"n":"第七十八条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":79,"n":"第七十九条","txt":"违反本法规定，给消费者造成人身、财产或者其他损害的，依法承担民事赔偿责任。生产经营者财产不足以同时承担民事赔偿责任和缴纳罚款、罚金时，先承担民事赔偿责任。"},{"i":80,"n":"第八十条","txt":"粮食收购、储存、运输环节的质量安全管理，依照有关粮食管理的法律、行政法规执行。"},{"i":81,"n":"第八十一条","txt":"本法自2023年1月1日起施行。"}],"chukouguanzhifa":[{"i":1,"n":"第一条","txt":"为了维护国家安全和利益，履行防扩散等国际义务，加强和规范出口管制，制定本法。"},{"i":2,"n":"第二条","txt":"国家对两用物项、军品、核以及其他与维护国家安全和利益、履行防扩散等国际义务相关的货物、技术、服务等物项（以下统称管制物项）的出口管制，适用本法。"},{"i":3,"n":"第三条","txt":"出口管制工作应当坚持总体国家安全观，维护国际和平，统筹安全和发展，完善出口管制管理和服务。"},{"i":4,"n":"第四条","txt":"国家实行统一的出口管制制度，通过制定管制清单、名录或者目录（以下统称管制清单）、实施出口许可等方式进行管理。"},{"i":5,"n":"第五条","txt":"国务院、中央军事委员会承担出口管制职能的部门（以下统称国家出口管制管理部门）按照职责分工负责出口管制工作。国务院、中央军事委员会其他有关部门按照职责分工负责出口管制有关工作。"},{"i":6,"n":"第六条","txt":"国家加强出口管制国际合作，参与出口管制有关国际规则的制定。"},{"i":7,"n":"第七条","txt":"出口经营者可以依法成立和参加有关的商会、协会等行业自律组织。"},{"i":8,"n":"第八条","txt":"国家出口管制管理部门会同有关部门制定出口管制政策，其中重大政策应当报国务院批准，或者报国务院、中央军事委员会批准。"},{"i":9,"n":"第九条","txt":"国家出口管制管理部门依据本法和有关法律、行政法规的规定，根据出口管制政策，按照规定程序会同有关部门制定、调整管制物项出口管制清单，并及时公布。"},{"i":10,"n":"第十条","txt":"根据维护国家安全和利益、履行防扩散等国际义务的需要，经国务院批准，或者经国务院、中央军事委员会批准，国家出口管制管理部门会同有关部门可以禁止相关管制物项的出口，或者禁止相关管制物项向特定目的国家和地区、特定组织和个人出口。"},{"i":11,"n":"第十一条","txt":"出口经营者从事管制物项出口，应当遵守本法和有关法律、行政法规的规定；依法需要取得相关管制物项出口经营资格的，应当取得相应的资格。"},{"i":12,"n":"第十二条","txt":"国家对管制物项的出口实行许可制度。"},{"i":13,"n":"第十三条","txt":"国家出口管制管理部门综合考虑下列因素，对出口经营者出口管制物项的申请进行审查，作出准予或者不予许可的决定："},{"i":14,"n":"第十四条","txt":"出口经营者建立出口管制内部合规制度，且运行情况良好的，国家出口管制管理部门可以对其出口有关管制物项给予通用许可等便利措施。具体办法由国家出口管制管理部门规定。"},{"i":15,"n":"第十五条","txt":"出口经营者应当向国家出口管制管理部门提交管制物项的最终用户和最终用途证明文件，有关证明文件由最终用户或者最终用户所在国家和地区政府机构出具。"},{"i":16,"n":"第十六条","txt":"管制物项的最终用户应当承诺，未经国家出口管制管理部门允许，不得擅自改变相关管制物项的最终用途或者向任何第三方转让。"},{"i":17,"n":"第十七条","txt":"国家出口管制管理部门建立管制物项最终用户和最终用途风险管理制度，对管制物项的最终用户和最终用途进行评估、核查，加强最终用户和最终用途管理。"},{"i":18,"n":"第十八条","txt":"国家出口管制管理部门对有下列情形之一的进口商和最终用户，建立管控名单："},{"i":19,"n":"第十九条","txt":"出口货物的发货人或者代理报关企业出口管制货物时，应当向海关交验由国家出口管制管理部门颁发的许可证件，并按照国家有关规定办理报关手续。"},{"i":20,"n":"第二十条","txt":"任何组织和个人不得为出口经营者从事出口管制违法行为提供代理、货运、寄递、报关、第三方电子商务交易平台和金融等服务。"},{"i":21,"n":"第二十一条","txt":"出口经营者向国家两用物项出口管制管理部门申请出口两用物项时，应当依照法律、行政法规的规定如实提交相关材料。"},{"i":22,"n":"第二十二条","txt":"国家两用物项出口管制管理部门受理两用物项出口申请，单独或者会同有关部门依照本法和有关法律、行政法规的规定对两用物项出口申请进行审查，并在法定期限内作出准予或者不予许可的决定。作出准予许可决定的，由发证机关统一颁发出口许可证。"},{"i":23,"n":"第二十三条","txt":"国家实行军品出口专营制度。从事军品出口的经营者，应当获得军品出口专营资格并在核定的经营范围内从事军品出口经营活动。"},{"i":24,"n":"第二十四条","txt":"军品出口经营者应当根据管制政策和产品属性，向国家军品出口管制管理部门申请办理军品出口立项、军品出口项目、军品出口合同审查批准手续。"},{"i":25,"n":"第二十五条","txt":"军品出口经营者在出口军品前，应当向国家军品出口管制管理部门申请领取军品出口许可证。"},{"i":26,"n":"第二十六条","txt":"军品出口经营者应当委托经批准的军品出口运输企业办理军品出口运输及相关业务。具体办法由国家军品出口管制管理部门会同有关部门规定。"},{"i":27,"n":"第二十七条","txt":"军品出口经营者或者科研生产单位参加国际性军品展览，应当按照程序向国家军品出口管制管理部门办理审批手续。"},{"i":28,"n":"第二十八条","txt":"国家出口管制管理部门依法对管制物项出口活动进行监督检查。"},{"i":29,"n":"第二十九条","txt":"国家出口管制管理部门依法履行职责，国务院有关部门、地方人民政府及其有关部门应当予以协助。"},{"i":30,"n":"第三十条","txt":"为加强管制物项出口管理，防范管制物项出口违法风险，国家出口管制管理部门可以采取监管谈话、出具警示函等措施。"},{"i":31,"n":"第三十一条","txt":"对涉嫌违反本法规定的行为，任何组织和个人有权向国家出口管制管理部门举报，国家出口管制管理部门接到举报后应当依法及时处理，并为举报人保密。"},{"i":32,"n":"第三十二条","txt":"国家出口管制管理部门根据缔结或者参加的国际条约，或者按照平等互惠原则，与其他国家或者地区、国际组织等开展出口管制合作与交流。"},{"i":33,"n":"第三十三条","txt":"出口经营者未取得相关管制物项的出口经营资格从事有关管制物项出口的，给予警告，责令停止违法行为，没收违法所得，违法经营额五十万元以上的，并处违法经营额五倍以上十倍以下罚款；没有违法经营额或者违法经营额不足五十万元的，并处五十万元以上五百万元以下罚款。"},{"i":34,"n":"第三十四条","txt":"出口经营者有下列行为之一的，责令停止违法行为，没收违法所得，违法经营额五十万元以上的，并处违法经营额五倍以上十倍以下罚款；没有违法经营额或者违法经营额不足五十万元的，并处五十万元以上五百万元以下罚款；情节严重的，责令停业整顿，直至吊销相关管制物项出口经营资格："},{"i":35,"n":"第三十五条","txt":"以欺骗、贿赂等不正当手段获取管制物项出口许可证件，或者非法转让管制物项出口许可证件的，撤销许可，收缴出口许可证，没收违法所得，违法经营额二十万元以上的，并处违法经营额五倍以上十倍以下罚款；没有违法经营额或者违法经营额不足二十万元的，并处二十万元以上二百万元以下罚款。"},{"i":36,"n":"第三十六条","txt":"明知出口经营者从事出口管制违法行为仍为其提供代理、货运、寄递、报关、第三方电子商务交易平台和金融等服务的，给予警告，责令停止违法行为，没收违法所得，违法经营额十万元以上的，并处违法经营额三倍以上五倍以下罚款；没有违法经营额或者违法经营额不足十万元的，并处十万元以上五十万元以下罚款。"},{"i":37,"n":"第三十七条","txt":"出口经营者违反本法规定与列入管控名单的进口商、最终用户进行交易的，给予警告，责令停止违法行为，没收违法所得，违法经营额五十万元以上的，并处违法经营额十倍以上二十倍以下罚款；没有违法经营额或者违法经营额不足五十万元的，并处五十万元以上五百万元以下罚款；情节严重的，责令停业整顿，直至吊销相关管制物项出口经营资格。"},{"i":38,"n":"第三十八条","txt":"出口经营者拒绝、阻碍监督检查的，给予警告，并处十万元以上三十万元以下罚款；情节严重的，责令停业整顿，直至吊销相关管制物项出口经营资格。"},{"i":39,"n":"第三十九条","txt":"违反本法规定受到处罚的出口经营者，自处罚决定生效之日起，国家出口管制管理部门可以在五年内不受理其提出的出口许可申请；对其直接负责的主管人员和其他直接责任人员，可以禁止其在五年内从事有关出口经营活动，因出口管制违法行为受到刑事处罚的，终身不得从事有关出口经营活动。"},{"i":40,"n":"第四十条","txt":"本法规定的出口管制违法行为，由国家出口管制管理部门进行处罚；法律、行政法规规定由海关处罚的，由其依照本法进行处罚。"},{"i":41,"n":"第四十一条","txt":"有关组织或者个人对国家出口管制管理部门的不予许可决定不服的，可以依法申请行政复议。行政复议决定为最终裁决。"},{"i":42,"n":"第四十二条","txt":"从事出口管制管理的国家工作人员玩忽职守、徇私舞弊、滥用职权的，依法给予处分。"},{"i":43,"n":"第四十三条","txt":"违反本法有关出口管制管理规定，危害国家安全和利益的，除依照本法规定处罚外，还应当依照有关法律、行政法规的规定进行处理和处罚。"},{"i":44,"n":"第四十四条","txt":"中华人民共和国境外的组织和个人，违反本法有关出口管制管理规定，危害中华人民共和国国家安全和利益，妨碍履行防扩散等国际义务的，依法处理并追究其法律责任。"},{"i":45,"n":"第四十五条","txt":"管制物项的过境、转运、通运、再出口或者从保税区、出口加工区等海关特殊监管区域和出口监管仓库、保税物流中心等保税监管场所向境外出口，依照本法的有关规定执行。"},{"i":46,"n":"第四十六条","txt":"核以及其他管制物项的出口，本法未作规定的，依照有关法律、行政法规的规定执行。"},{"i":47,"n":"第四十七条","txt":"用于武装力量海外运用、对外军事交流、军事援助等的军品出口，依照有关法律法规的规定执行。"},{"i":48,"n":"第四十八条","txt":"任何国家或者地区滥用出口管制措施危害中华人民共和国国家安全和利益的，中华人民共和国可以根据实际情况对该国家或者地区对等采取措施。"},{"i":49,"n":"第四十九条","txt":"本法自2020年12月1日起施行。"}],"dongwufangyifa":[{"i":1,"n":"第一条","txt":"为了加强对动物防疫活动的管理，预防、控制、净化、消灭动物疫病，促进养殖业发展，防控人畜共患传染病，保障公共卫生安全和人体健康，制定本法。"},{"i":2,"n":"第二条","txt":"本法适用于在中华人民共和国领域内的动物防疫及其监督管理活动。"},{"i":3,"n":"第三条","txt":"本法所称动物，是指家畜家禽和人工饲养、捕获的其他动物。"},{"i":4,"n":"第四条","txt":"根据动物疫病对养殖业生产和人体健康的危害程度，本法规定的动物疫病分为下列三类："},{"i":5,"n":"第五条","txt":"动物防疫实行预防为主，预防与控制、净化、消灭相结合的方针。"},{"i":6,"n":"第六条","txt":"国家鼓励社会力量参与动物防疫工作。各级人民政府采取措施，支持单位和个人参与动物防疫的宣传教育、疫情报告、志愿服务和捐赠等活动。"},{"i":7,"n":"第七条","txt":"从事动物饲养、屠宰、经营、隔离、运输以及动物产品生产、经营、加工、贮藏等活动的单位和个人，依照本法和国务院农业农村主管部门的规定，做好免疫、消毒、检测、隔离、净化、消灭、无害化处理等动物防疫工作，承担动物防疫相关责任。"},{"i":8,"n":"第八条","txt":"县级以上人民政府对动物防疫工作实行统一领导，采取有效措施稳定基层机构队伍，加强动物防疫队伍建设，建立健全动物防疫体系，制定并组织实施动物疫病防治规划。"},{"i":9,"n":"第九条","txt":"国务院农业农村主管部门主管全国的动物防疫工作。"},{"i":10,"n":"第十条","txt":"县级以上人民政府卫生健康主管部门和本级人民政府农业农村、野生动物保护等主管部门应当建立人畜共患传染病防治的协作机制。"},{"i":11,"n":"第十一条","txt":"县级以上地方人民政府的动物卫生监督机构依照本法规定，负责动物、动物产品的检疫工作。"},{"i":12,"n":"第十二条","txt":"县级以上人民政府按照国务院的规定，根据统筹规划、合理布局、综合设置的原则建立动物疫病预防控制机构。"},{"i":13,"n":"第十三条","txt":"国家鼓励和支持开展动物疫病的科学研究以及国际合作与交流，推广先进适用的科学研究成果，提高动物疫病防治的科学技术水平。"},{"i":14,"n":"第十四条","txt":"对在动物防疫工作、相关科学研究、动物疫情扑灭中做出贡献的单位和个人，各级人民政府和有关部门按照国家有关规定给予表彰、奖励。"},{"i":15,"n":"第十五条","txt":"国家建立动物疫病风险评估制度。"},{"i":16,"n":"第十六条","txt":"国家对严重危害养殖业生产和人体健康的动物疫病实施强制免疫。"},{"i":17,"n":"第十七条","txt":"饲养动物的单位和个人应当履行动物疫病强制免疫义务，按照强制免疫计划和技术规范，对动物实施免疫接种，并按照国家有关规定建立免疫档案、加施畜禽标识，保证可追溯。"},{"i":18,"n":"第十八条","txt":"县级以上地方人民政府农业农村主管部门负责组织实施动物疫病强制免疫计划，并对饲养动物的单位和个人履行强制免疫义务的情况进行监督检查。"},{"i":19,"n":"第十九条","txt":"国家实行动物疫病监测和疫情预警制度。"},{"i":20,"n":"第二十条","txt":"陆路边境省、自治区人民政府根据动物疫病防控需要，合理设置动物疫病监测站点，健全监测工作机制，防范境外动物疫病传入。"},{"i":21,"n":"第二十一条","txt":"国家支持地方建立无规定动物疫病区，鼓励动物饲养场建设无规定动物疫病生物安全隔离区。对符合国务院农业农村主管部门规定标准的无规定动物疫病区和无规定动物疫病生物安全隔离区，国务院农业农村主管部门验收合格予以公布，并对其维持情况进行监督检查。"},{"i":22,"n":"第二十二条","txt":"国务院农业农村主管部门制定并组织实施动物疫病净化、消灭规划。"},{"i":23,"n":"第二十三条","txt":"种用、乳用动物应当符合国务院农业农村主管部门规定的健康标准。"},{"i":24,"n":"第二十四条","txt":"动物饲养场和隔离场所、动物屠宰加工场所以及动物和动物产品无害化处理场所，应当符合下列动物防疫条件："},{"i":25,"n":"第二十五条","txt":"国家实行动物防疫条件审查制度。"},{"i":26,"n":"第二十六条","txt":"经营动物、动物产品的集贸市场应当具备国务院农业农村主管部门规定的动物防疫条件，并接受农业农村主管部门的监督检查。具体办法由国务院农业农村主管部门制定。"},{"i":27,"n":"第二十七条","txt":"动物、动物产品的运载工具、垫料、包装物、容器等应当符合国务院农业农村主管部门规定的动物防疫要求。"},{"i":28,"n":"第二十八条","txt":"采集、保存、运输动物病料或者病原微生物以及从事病原微生物研究、教学、检测、诊断等活动，应当遵守国家有关病原微生物实验室管理的规定。"},{"i":29,"n":"第二十九条","txt":"禁止屠宰、经营、运输下列动物和生产、经营、加工、贮藏、运输下列动物产品："},{"i":30,"n":"第三十条","txt":"单位和个人饲养犬只，应当按照规定定期免疫接种狂犬病疫苗，凭动物诊疗机构出具的免疫证明向所在地养犬登记机关申请登记。"},{"i":31,"n":"第三十一条","txt":"从事动物疫病监测、检测、检验检疫、研究、诊疗以及动物饲养、屠宰、经营、隔离、运输等活动的单位和个人，发现动物染疫或者疑似染疫的，应当立即向所在地农业农村主管部门或者动物疫病预防控制机构报告，并迅速采取隔离等控制措施，防止动物疫情扩散。其他单位和个人发现动物染疫或者疑似染疫的，应当及时报告。"},{"i":32,"n":"第三十二条","txt":"动物疫情由县级以上人民政府农业农村主管部门认定；其中重大动物疫情由省、自治区、直辖市人民政府农业农村主管部门认定，必要时报国务院农业农村主管部门认定。"},{"i":33,"n":"第三十三条","txt":"国家实行动物疫情通报制度。"},{"i":34,"n":"第三十四条","txt":"发生人畜共患传染病疫情时，县级以上人民政府农业农村主管部门与本级人民政府卫生健康、野生动物保护等主管部门应当及时相互通报。"},{"i":35,"n":"第三十五条","txt":"患有人畜共患传染病的人员不得直接从事动物疫病监测、检测、检验检疫、诊疗以及易感染动物的饲养、屠宰、经营、隔离、运输等活动。"},{"i":36,"n":"第三十六条","txt":"国务院农业农村主管部门向社会及时公布全国动物疫情，也可以根据需要授权省、自治区、直辖市人民政府农业农村主管部门公布本行政区域的动物疫情。其他单位和个人不得发布动物疫情。"},{"i":37,"n":"第三十七条","txt":"任何单位和个人不得瞒报、谎报、迟报、漏报动物疫情，不得授意他人瞒报、谎报、迟报动物疫情，不得阻碍他人报告动物疫情。"},{"i":38,"n":"第三十八条","txt":"发生一类动物疫病时，应当采取下列控制措施："},{"i":39,"n":"第三十九条","txt":"发生二类动物疫病时，应当采取下列控制措施："},{"i":40,"n":"第四十条","txt":"疫点、疫区、受威胁区的撤销和疫区封锁的解除，按照国务院农业农村主管部门规定的标准和程序评估后，由原决定机关决定并宣布。"},{"i":41,"n":"第四十一条","txt":"发生三类动物疫病时，所在地县级、乡级人民政府应当按照国务院农业农村主管部门的规定组织防治。"},{"i":42,"n":"第四十二条","txt":"二、三类动物疫病呈暴发性流行时，按照一类动物疫病处理。"},{"i":43,"n":"第四十三条","txt":"疫区内有关单位和个人，应当遵守县级以上人民政府及其农业农村主管部门依法作出的有关控制动物疫病的规定。"},{"i":44,"n":"第四十四条","txt":"发生动物疫情时，航空、铁路、道路、水路运输企业应当优先组织运送防疫人员和物资。"},{"i":45,"n":"第四十五条","txt":"国务院农业农村主管部门根据动物疫病的性质、特点和可能造成的社会危害，制定国家重大动物疫情应急预案报国务院批准，并按照不同动物疫病病种、流行特点和危害程度，分别制定实施方案。"},{"i":46,"n":"第四十六条","txt":"发生重大动物疫情时，国务院农业农村主管部门负责划定动物疫病风险区，禁止或者限制特定动物、动物产品由高风险区向低风险区调运。"},{"i":47,"n":"第四十七条","txt":"发生重大动物疫情时，依照法律和国务院的规定以及应急预案采取应急处置措施。"},{"i":48,"n":"第四十八条","txt":"动物卫生监督机构依照本法和国务院农业农村主管部门的规定对动物、动物产品实施检疫。"},{"i":49,"n":"第四十九条","txt":"屠宰、出售或者运输动物以及出售或者运输动物产品前，货主应当按照国务院农业农村主管部门的规定向所在地动物卫生监督机构申报检疫。"},{"i":50,"n":"第五十条","txt":"因科研、药用、展示等特殊情形需要非食用性利用的野生动物，应当按照国家有关规定报动物卫生监督机构检疫，检疫合格的，方可利用。"},{"i":51,"n":"第五十一条","txt":"屠宰、经营、运输的动物，以及用于科研、展示、演出和比赛等非食用性利用的动物，应当附有检疫证明；经营和运输的动物产品，应当附有检疫证明、检疫标志。"},{"i":52,"n":"第五十二条","txt":"经航空、铁路、道路、水路运输动物和动物产品的，托运人托运时应当提供检疫证明；没有检疫证明的，承运人不得承运。"},{"i":53,"n":"第五十三条","txt":"省、自治区、直辖市人民政府确定并公布道路运输的动物进入本行政区域的指定通道，设置引导标志。跨省、自治区、直辖市通过道路运输动物的，应当经省、自治区、直辖市人民政府设立的指定通道入省境或者过省境。"},{"i":54,"n":"第五十四条","txt":"输入到无规定动物疫病区的动物、动物产品，货主应当按照国务院农业农村主管部门的规定向无规定动物疫病区所在地动物卫生监督机构申报检疫，经检疫合格的，方可进入。"},{"i":55,"n":"第五十五条","txt":"跨省、自治区、直辖市引进的种用、乳用动物到达输入地后，货主应当按照国务院农业农村主管部门的规定对引进的种用、乳用动物进行隔离观察。"},{"i":56,"n":"第五十六条","txt":"经检疫不合格的动物、动物产品，货主应当在农业农村主管部门的监督下按照国家有关规定处理，处理费用由货主承担。"},{"i":57,"n":"第五十七条","txt":"从事动物饲养、屠宰、经营、隔离以及动物产品生产、经营、加工、贮藏等活动的单位和个人，应当按照国家有关规定做好病死动物、病害动物产品的无害化处理，或者委托动物和动物产品无害化处理场所处理。"},{"i":58,"n":"第五十八条","txt":"在江河、湖泊、水库等水域发现的死亡畜禽，由所在地县级人民政府组织收集、处理并溯源。"},{"i":59,"n":"第五十九条","txt":"省、自治区、直辖市人民政府制定动物和动物产品集中无害化处理场所建设规划，建立政府主导、市场运作的无害化处理机制。"},{"i":60,"n":"第六十条","txt":"各级财政对病死动物无害化处理提供补助。具体补助标准和办法由县级以上人民政府财政部门会同本级人民政府农业农村、野生动物保护等有关部门制定。"},{"i":61,"n":"第六十一条","txt":"从事动物诊疗活动的机构，应当具备下列条件："},{"i":62,"n":"第六十二条","txt":"从事动物诊疗活动的机构，应当向县级以上地方人民政府农业农村主管部门申请动物诊疗许可证。受理申请的农业农村主管部门应当依照本法和《中华人民共和国行政许可法》的规定进行审查。经审查合格的，发给动物诊疗许可证；不合格的，应当通知申请人并说明理由。"},{"i":63,"n":"第六十三条","txt":"动物诊疗许可证应当载明诊疗机构名称、诊疗活动范围、从业地点和法定代表人（负责人）等事项。"},{"i":64,"n":"第六十四条","txt":"动物诊疗机构应当按照国务院农业农村主管部门的规定，做好诊疗活动中的卫生安全防护、消毒、隔离和诊疗废弃物处置等工作。"},{"i":65,"n":"第六十五条","txt":"从事动物诊疗活动，应当遵守有关动物诊疗的操作技术规范，使用符合规定的兽药和兽医器械。"},{"i":66,"n":"第六十六条","txt":"国家实行官方兽医任命制度。"},{"i":67,"n":"第六十七条","txt":"官方兽医依法履行动物、动物产品检疫职责，任何单位和个人不得拒绝或者阻碍。"},{"i":68,"n":"第六十八条","txt":"县级以上人民政府农业农村主管部门制定官方兽医培训计划，提供培训条件，定期对官方兽医进行培训和考核。"},{"i":69,"n":"第六十九条","txt":"国家实行执业兽医资格考试制度。具有兽医相关专业大学专科以上学历的人员或者符合条件的乡村兽医，通过执业兽医资格考试的，由省、自治区、直辖市人民政府农业农村主管部门颁发执业兽医资格证书；从事动物诊疗等经营活动的，还应当向所在地县级人民政府农业农村主管部门备案。"},{"i":70,"n":"第七十条","txt":"执业兽医开具兽医处方应当亲自诊断，并对诊断结论负责。"},{"i":71,"n":"第七十一条","txt":"乡村兽医可以在乡村从事动物诊疗活动。具体管理办法由国务院农业农村主管部门制定。"},{"i":72,"n":"第七十二条","txt":"执业兽医、乡村兽医应当按照所在地人民政府和农业农村主管部门的要求，参加动物疫病预防、控制和动物疫情扑灭等活动。"},{"i":73,"n":"第七十三条","txt":"兽医行业协会提供兽医信息、技术、培训等服务，维护成员合法权益，按照章程建立健全行业规范和奖惩机制，加强行业自律，推动行业诚信建设，宣传动物防疫和兽医知识。"},{"i":74,"n":"第七十四条","txt":"县级以上地方人民政府农业农村主管部门依照本法规定，对动物饲养、屠宰、经营、隔离、运输以及动物产品生产、经营、加工、贮藏、运输等活动中的动物防疫实施监督管理。"},{"i":75,"n":"第七十五条","txt":"为控制动物疫病，县级人民政府农业农村主管部门应当派人在所在地依法设立的现有检查站执行监督检查任务；必要时，经省、自治区、直辖市人民政府批准，可以设立临时性的动物防疫检查站，执行监督检查任务。"},{"i":76,"n":"第七十六条","txt":"县级以上地方人民政府农业农村主管部门执行监督检查任务，可以采取下列措施，有关单位和个人不得拒绝或者阻碍："},{"i":77,"n":"第七十七条","txt":"执法人员执行动物防疫监督检查任务，应当出示行政执法证件，佩带统一标志。"},{"i":78,"n":"第七十八条","txt":"禁止转让、伪造或者变造检疫证明、检疫标志或者畜禽标识。"},{"i":79,"n":"第七十九条","txt":"县级以上人民政府应当将动物防疫工作纳入本级国民经济和社会发展规划及年度计划。"},{"i":80,"n":"第八十条","txt":"国家鼓励和支持动物防疫领域新技术、新设备、新产品等科学技术研究开发。"},{"i":81,"n":"第八十一条","txt":"县级人民政府应当为动物卫生监督机构配备与动物、动物产品检疫工作相适应的官方兽医，保障检疫工作条件。"},{"i":82,"n":"第八十二条","txt":"国家鼓励和支持执业兽医、乡村兽医和动物诊疗机构开展动物防疫和疫病诊疗活动；鼓励养殖企业、兽药及饲料生产企业组建动物防疫服务团队，提供防疫服务。地方人民政府组织村级防疫员参加动物疫病防治工作的，应当保障村级防疫员合理劳务报酬。"},{"i":83,"n":"第八十三条","txt":"县级以上人民政府按照本级政府职责，将动物疫病的监测、预防、控制、净化、消灭，动物、动物产品的检疫和病死动物的无害化处理，以及监督管理所需经费纳入本级预算。"},{"i":84,"n":"第八十四条","txt":"县级以上人民政府应当储备动物疫情应急处置所需的防疫物资。"},{"i":85,"n":"第八十五条","txt":"对在动物疫病预防、控制、净化、消灭过程中强制扑杀的动物、销毁的动物产品和相关物品，县级以上人民政府给予补偿。具体补偿标准和办法由国务院财政部门会同有关部门制定。"},{"i":86,"n":"第八十六条","txt":"对从事动物疫病预防、检疫、监督检查、现场处理疫情以及在工作中接触动物疫病病原体的人员，有关单位按照国家规定，采取有效的卫生防护、医疗保健措施，给予畜牧兽医医疗卫生津贴等相关待遇。"},{"i":87,"n":"第八十七条","txt":"地方各级人民政府及其工作人员未依照本法规定履行职责的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":88,"n":"第八十八条","txt":"县级以上人民政府农业农村主管部门及其工作人员违反本法规定，有下列行为之一的，由本级人民政府责令改正，通报批评；对直接负责的主管人员和其他直接责任人员依法给予处分："},{"i":89,"n":"第八十九条","txt":"动物卫生监督机构及其工作人员违反本法规定，有下列行为之一的，由本级人民政府或者农业农村主管部门责令改正，通报批评；对直接负责的主管人员和其他直接责任人员依法给予处分："},{"i":90,"n":"第九十条","txt":"动物疫病预防控制机构及其工作人员违反本法规定，有下列行为之一的，由本级人民政府或者农业农村主管部门责令改正，通报批评；对直接负责的主管人员和其他直接责任人员依法给予处分："},{"i":91,"n":"第九十一条","txt":"地方各级人民政府、有关部门及其工作人员瞒报、谎报、迟报、漏报或者授意他人瞒报、谎报、迟报动物疫情，或者阻碍他人报告动物疫情的，由上级人民政府或者有关部门责令改正，通报批评；对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":92,"n":"第九十二条","txt":"违反本法规定，有下列行为之一的，由县级以上地方人民政府农业农村主管部门责令限期改正，可以处一千元以下罚款；逾期不改正的，处一千元以上五千元以下罚款，由县级以上地方人民政府农业农村主管部门委托动物诊疗机构、无害化处理场所等代为处理，所需费用由违法行为人承担："},{"i":93,"n":"第九十三条","txt":"违反本法规定，对经强制免疫的动物未按照规定建立免疫档案，或者未按照规定加施畜禽标识的，依照《中华人民共和国畜牧法》的有关规定处罚。"},{"i":94,"n":"第九十四条","txt":"违反本法规定，动物、动物产品的运载工具、垫料、包装物、容器等不符合国务院农业农村主管部门规定的动物防疫要求的，由县级以上地方人民政府农业农村主管部门责令改正，可以处五千元以下罚款；情节严重的，处五千元以上五万元以下罚款。"},{"i":95,"n":"第九十五条","txt":"违反本法规定，对染疫动物及其排泄物、染疫动物产品或者被染疫动物、动物产品污染的运载工具、垫料、包装物、容器等未按照规定处置的，由县级以上地方人民政府农业农村主管部门责令限期处理；逾期不处理的，由县级以上地方人民政府农业农村主管部门委托有关单位代为处理，所需费用由违法行为人承担，处五千元以上五万元以下罚款。"},{"i":96,"n":"第九十六条","txt":"违反本法规定，患有人畜共患传染病的人员，直接从事动物疫病监测、检测、检验检疫，动物诊疗以及易感染动物的饲养、屠宰、经营、隔离、运输等活动的，由县级以上地方人民政府农业农村或者野生动物保护主管部门责令改正；拒不改正的，处一千元以上一万元以下罚款；情节严重的，处一万元以上五万元以下罚款。"},{"i":97,"n":"第九十七条","txt":"违反本法第二十九条规定，屠宰、经营、运输动物或者生产、经营、加工、贮藏、运输动物产品的，由县级以上地方人民政府农业农村主管部门责令改正、采取补救措施，没收违法所得、动物和动物产品，并处同类检疫合格动物、动物产品货值金额十五倍以上三十倍以下罚款；同类检疫合格动物、动物产品货值金额不足一万元的，并处五万元以上十五万元以下罚款；其中依法应当检疫而未检疫的，依照本法第一百条的规定处罚。"},{"i":98,"n":"第九十八条","txt":"违反本法规定，有下列行为之一的，由县级以上地方人民政府农业农村主管部门责令改正，处三千元以上三万元以下罚款；情节严重的，责令停业整顿，并处三万元以上十万元以下罚款："},{"i":99,"n":"第九十九条","txt":"动物饲养场和隔离场所、动物屠宰加工场所以及动物和动物产品无害化处理场所，生产经营条件发生变化，不再符合本法第二十四条规定的动物防疫条件继续从事相关活动的，由县级以上地方人民政府农业农村主管部门给予警告，责令限期改正；逾期仍达不到规定条件的，吊销动物防疫条件合格证，并通报市场监督管理部门依法处理。"},{"i":100,"n":"第一百条","txt":"违反本法规定，屠宰、经营、运输的动物未附有检疫证明，经营和运输的动物产品未附有检疫证明、检疫标志的，由县级以上地方人民政府农业农村主管部门责令改正，处同类检疫合格动物、动物产品货值金额一倍以下罚款；对货主以外的承运人处运输费用三倍以上五倍以下罚款，情节严重的，处五倍以上十倍以下罚款。"},{"i":101,"n":"第一百零一条","txt":"违反本法规定，将禁止或者限制调运的特定动物、动物产品由动物疫病高风险区调入低风险区的，由县级以上地方人民政府农业农村主管部门没收运输费用、违法运输的动物和动物产品，并处运输费用一倍以上五倍以下罚款。"},{"i":102,"n":"第一百零二条","txt":"违反本法规定，通过道路跨省、自治区、直辖市运输动物，未经省、自治区、直辖市人民政府设立的指定通道入省境或者过省境的，由县级以上地方人民政府农业农村主管部门对运输人处五千元以上一万元以下罚款；情节严重的，处一万元以上五万元以下罚款。"},{"i":103,"n":"第一百零三条","txt":"违反本法规定，转让、伪造或者变造检疫证明、检疫标志或者畜禽标识的，由县级以上地方人民政府农业农村主管部门没收违法所得和检疫证明、检疫标志、畜禽标识，并处五千元以上五万元以下罚款。"},{"i":104,"n":"第一百零四条","txt":"违反本法规定，有下列行为之一的，由县级以上地方人民政府农业农村主管部门责令改正，处三千元以上三万元以下罚款："},{"i":105,"n":"第一百零五条","txt":"违反本法规定，未取得动物诊疗许可证从事动物诊疗活动的，由县级以上地方人民政府农业农村主管部门责令停止诊疗活动，没收违法所得，并处违法所得一倍以上三倍以下罚款；违法所得不足三万元的，并处三千元以上三万元以下罚款。"},{"i":106,"n":"第一百零六条","txt":"违反本法规定，未经执业兽医备案从事经营性动物诊疗活动的，由县级以上地方人民政府农业农村主管部门责令停止动物诊疗活动，没收违法所得，并处三千元以上三万元以下罚款；对其所在的动物诊疗机构处一万元以上五万元以下罚款。"},{"i":107,"n":"第一百零七条","txt":"违反本法规定，生产经营兽医器械，产品质量不符合要求的，由县级以上地方人民政府农业农村主管部门责令限期整改；情节严重的，责令停业整顿，并处二万元以上十万元以下罚款。"},{"i":108,"n":"第一百零八条","txt":"违反本法规定，从事动物疫病研究、诊疗和动物饲养、屠宰、经营、隔离、运输，以及动物产品生产、经营、加工、贮藏、无害化处理等活动的单位和个人，有下列行为之一的，由县级以上地方人民政府农业农村主管部门责令改正，可以处一万元以下罚款；拒不改正的，处一万元以上五万元以下罚款，并可以责令停业整顿："},{"i":109,"n":"第一百零九条","txt":"违反本法规定，造成人畜共患传染病传播、流行的，依法从重给予处分、处罚。"},{"i":110,"n":"第一百一十条","txt":"本法下列用语的含义："},{"i":111,"n":"第一百一十一条","txt":"境外无规定动物疫病区和无规定动物疫病生物安全隔离区的无疫等效性评估，参照本法有关规定执行。"},{"i":112,"n":"第一百一十二条","txt":"实验动物防疫有特殊要求的，按照实验动物管理的有关规定执行。"},{"i":113,"n":"第一百一十三条","txt":"本法自2021年5月1日起施行。"}],"yinhuashuifa":[{"i":1,"n":"第一条","txt":"在中华人民共和国境内书立应税凭证、进行证券交易的单位和个人，为印花税的纳税人，应当依照本法规定缴纳印花税。"},{"i":2,"n":"第二条","txt":"本法所称应税凭证，是指本法所附《印花税税目税率表》列明的合同、产权转移书据和营业账簿。"},{"i":3,"n":"第三条","txt":"本法所称证券交易，是指转让在依法设立的证券交易所、国务院批准的其他全国性证券交易场所交易的股票和以股票为基础的存托凭证。"},{"i":4,"n":"第四条","txt":"印花税的税目、税率，依照本法所附《印花税税目税率表》执行。"},{"i":5,"n":"第五条","txt":"印花税的计税依据如下："},{"i":6,"n":"第六条","txt":"应税合同、产权转移书据未列明金额的，印花税的计税依据按照实际结算的金额确定。"},{"i":7,"n":"第七条","txt":"证券交易无转让价格的，按照办理过户登记手续时该证券前一个交易日收盘价计算确定计税依据；无收盘价的，按照证券面值计算确定计税依据。"},{"i":8,"n":"第八条","txt":"印花税的应纳税额按照计税依据乘以适用税率计算。"},{"i":9,"n":"第九条","txt":"同一应税凭证载有两个以上税目事项并分别列明金额的，按照各自适用的税目税率分别计算应纳税额；未分别列明金额的，从高适用税率。"},{"i":10,"n":"第十条","txt":"同一应税凭证由两方以上当事人书立的，按照各自涉及的金额分别计算应纳税额。"},{"i":11,"n":"第十一条","txt":"已缴纳印花税的营业账簿，以后年度记载的实收资本（股本）、资本公积合计金额比已缴纳印花税的实收资本（股本）、资本公积合计金额增加的，按照增加部分计算应纳税额。"},{"i":12,"n":"第十二条","txt":"下列凭证免征印花税："},{"i":13,"n":"第十三条","txt":"纳税人为单位的，应当向其机构所在地的主管税务机关申报缴纳印花税；纳税人为个人的，应当向应税凭证书立地或者纳税人居住地的主管税务机关申报缴纳印花税。"},{"i":14,"n":"第十四条","txt":"纳税人为境外单位或者个人，在境内有代理人的，以其境内代理人为扣缴义务人；在境内没有代理人的，由纳税人自行申报缴纳印花税，具体办法由国务院税务主管部门规定。"},{"i":15,"n":"第十五条","txt":"印花税的纳税义务发生时间为纳税人书立应税凭证或者完成证券交易的当日。"},{"i":16,"n":"第十六条","txt":"印花税按季、按年或者按次计征。实行按季、按年计征的，纳税人应当自季度、年度终了之日起十五日内申报缴纳税款；实行按次计征的，纳税人应当自纳税义务发生之日起十五日内申报缴纳税款。"},{"i":17,"n":"第十七条","txt":"印花税可以采用粘贴印花税票或者由税务机关依法开具其他完税凭证的方式缴纳。"},{"i":18,"n":"第十八条","txt":"印花税由税务机关依照本法和《中华人民共和国税收征收管理法》的规定征收管理。"},{"i":19,"n":"第十九条","txt":"纳税人、扣缴义务人和税务机关及其工作人员违反本法规定的，依照《中华人民共和国税收征收管理法》和有关法律、行政法规的规定追究法律责任。"},{"i":20,"n":"第二十条","txt":"本法自2022年7月1日起施行。1988年8月6日国务院发布的《中华人民共和国印花税暂行条例》同时废止。"}],"fanbuzhengdangjingzhengfa":[{"i":1,"n":"第一条","txt":"为了促进社会主义市场经济健康发展，鼓励和保护公平竞争，预防和制止不正当竞争行为，保护经营者和消费者的合法权益，制定本法。"},{"i":2,"n":"第二条","txt":"经营者在生产经营活动中，应当遵循自愿、平等、公平、诚信的原则，遵守法律和商业道德，公平参与市场竞争。"},{"i":3,"n":"第三条","txt":"反不正当竞争工作坚持中国共产党的领导。"},{"i":4,"n":"第四条","txt":"各级人民政府应当采取措施，预防和制止不正当竞争行为，为公平竞争创造良好的环境和条件。"},{"i":5,"n":"第五条","txt":"县级以上人民政府履行市场监督管理职责的部门对不正当竞争行为进行监督检查；法律、行政法规规定由其他部门监督检查的，依照其规定。"},{"i":6,"n":"第六条","txt":"国家鼓励、支持和保护一切组织和个人对不正当竞争行为进行社会监督。"},{"i":7,"n":"第七条","txt":"经营者不得实施下列混淆行为，引人误认为是他人商品或者与他人存在特定联系："},{"i":8,"n":"第八条","txt":"经营者不得采用给予财物或者其他手段贿赂下列单位或者个人，以谋取交易机会或者竞争优势："},{"i":9,"n":"第九条","txt":"经营者不得对其商品的性能、功能、质量、销售状况、用户评价、曾获荣誉等作虚假或者引人误解的商业宣传，欺骗、误导消费者和其他经营者。"},{"i":10,"n":"第十条","txt":"经营者不得实施下列侵犯商业秘密的行为："},{"i":11,"n":"第十一条","txt":"经营者进行有奖销售不得存在下列情形："},{"i":12,"n":"第十二条","txt":"经营者不得编造、传播或者指使他人编造、传播虚假信息或者误导性信息，损害其他经营者的商业信誉、商品声誉。"},{"i":13,"n":"第十三条","txt":"经营者利用网络从事生产经营活动，应当遵守本法的各项规定。"},{"i":14,"n":"第十四条","txt":"平台经营者不得强制或者变相强制平台内经营者按照其定价规则，以低于成本的价格销售商品，扰乱市场竞争秩序。"},{"i":15,"n":"第十五条","txt":"大型企业等经营者不得滥用自身资金、技术、交易渠道、行业影响力等方面的优势地位，要求中小企业接受明显不合理的付款期限、方式、条件和违约责任等交易条件，拖欠中小企业的货物、工程、服务等账款。"},{"i":16,"n":"第十六条","txt":"监督检查部门调查涉嫌不正当竞争行为，可以采取下列措施："},{"i":17,"n":"第十七条","txt":"监督检查部门调查涉嫌不正当竞争行为，被调查的经营者、利害关系人及其他有关单位、个人应当如实提供有关资料或者情况。"},{"i":18,"n":"第十八条","txt":"经营者涉嫌违反本法规定的，监督检查部门可以对其有关负责人进行约谈，要求其说明情况、提出改进措施。"},{"i":19,"n":"第十九条","txt":"监督检查部门及其工作人员对调查过程中知悉的商业秘密、个人隐私和个人信息依法负有保密义务。"},{"i":20,"n":"第二十条","txt":"对涉嫌不正当竞争行为，任何单位和个人有权向监督检查部门举报，监督检查部门接到举报后应当依法及时处理。"},{"i":21,"n":"第二十一条","txt":"平台经营者应当在平台服务协议和交易规则中明确平台内公平竞争规则，建立不正当竞争举报投诉和纠纷处置机制，引导、规范平台内经营者依法公平竞争；发现平台内经营者实施不正当竞争行为的，应当及时依法采取必要的处置措施，保存有关记录，并按规定向平台经营者住所地县级以上人民政府监督检查部门报告。"},{"i":22,"n":"第二十二条","txt":"经营者违反本法规定，给他人造成损害的，应当依法承担民事责任。"},{"i":23,"n":"第二十三条","txt":"经营者违反本法第七条规定实施混淆行为或者帮助他人实施混淆行为的，由监督检查部门责令停止违法行为，没收违法商品。违法经营额五万元以上的，可以并处违法经营额五倍以下的罚款；没有违法经营额或者违法经营额不足五万元的，可以并处二十五万元以下的罚款；情节严重的，并处吊销营业执照。"},{"i":24,"n":"第二十四条","txt":"有关单位违反本法第八条规定贿赂他人或者收受贿赂的，由监督检查部门没收违法所得，处十万元以上一百万元以下的罚款；情节严重的，处一百万元以上五百万元以下的罚款，可以并处吊销营业执照。"},{"i":25,"n":"第二十五条","txt":"经营者违反本法第九条规定对其商品作虚假或者引人误解的商业宣传，或者通过组织虚假交易、虚假评价等方式帮助其他经营者进行虚假或者引人误解的商业宣传的，由监督检查部门责令停止违法行为，处一百万元以下的罚款；情节严重的，处一百万元以上二百万元以下的罚款，可以并处吊销营业执照。"},{"i":26,"n":"第二十六条","txt":"经营者以及其他自然人、法人和非法人组织违反本法第十条规定侵犯商业秘密的，由监督检查部门责令停止违法行为，没收违法所得，处十万元以上一百万元以下的罚款；情节严重的，处一百万元以上五百万元以下的罚款。"},{"i":27,"n":"第二十七条","txt":"经营者违反本法第十一条规定进行有奖销售的，由监督检查部门责令停止违法行为，处五万元以上五十万元以下的罚款。"},{"i":28,"n":"第二十八条","txt":"经营者违反本法第十二条规定损害其他经营者商业信誉、商品声誉的，由监督检查部门责令停止违法行为、消除影响，处十万元以上一百万元以下的罚款；情节严重的，处一百万元以上五百万元以下的罚款。"},{"i":29,"n":"第二十九条","txt":"经营者违反本法第十三条第二款、第三款、第四款规定利用网络从事不正当竞争的，由监督检查部门责令停止违法行为，处十万元以上一百万元以下的罚款；情节严重的，处一百万元以上五百万元以下的罚款。"},{"i":30,"n":"第三十条","txt":"平台经营者违反本法第十四条规定强制或者变相强制平台内经营者以低于成本的价格销售商品的，由监督检查部门责令停止违法行为，处五万元以上五十万元以下的罚款；情节严重的，处五十万元以上二百万元以下的罚款。"},{"i":31,"n":"第三十一条","txt":"经营者违反本法第十五条规定滥用自身优势地位的，由省级以上人民政府监督检查部门责令限期改正，逾期不改正的，处一百万元以下的罚款；情节严重的，处一百万元以上五百万元以下的罚款。"},{"i":32,"n":"第三十二条","txt":"经营者违反本法规定从事不正当竞争，有主动消除或者减轻违法行为危害后果等法定情形的，依法从轻或者减轻行政处罚；违法行为轻微并及时纠正，没有造成危害后果的，不予行政处罚。"},{"i":33,"n":"第三十三条","txt":"经营者违反本法规定从事不正当竞争，受到行政处罚的，由监督检查部门记入信用记录，并依照有关法律、行政法规的规定予以公示。"},{"i":34,"n":"第三十四条","txt":"经营者违反本法规定，应当承担民事责任、行政责任和刑事责任，其财产不足以支付的，优先用于承担民事责任。"},{"i":35,"n":"第三十五条","txt":"妨害监督检查部门依照本法履行职责，拒绝、阻碍调查的，由监督检查部门责令改正，对个人可以处一万元以下的罚款，对单位可以处十万元以下的罚款。"},{"i":36,"n":"第三十六条","txt":"当事人对监督检查部门作出的决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":37,"n":"第三十七条","txt":"监督检查部门的工作人员滥用职权、玩忽职守、徇私舞弊或者泄露调查过程中知悉的商业秘密、个人隐私或者个人信息的，依法给予处分。"},{"i":38,"n":"第三十八条","txt":"违反本法规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":39,"n":"第三十九条","txt":"在侵犯商业秘密的民事审判程序中，商业秘密权利人提供初步证据，证明其已经对所主张的商业秘密采取保密措施，且合理表明商业秘密被侵犯，涉嫌侵权人应当证明权利人所主张的商业秘密不属于本法规定的商业秘密。"},{"i":40,"n":"第四十条","txt":"在中华人民共和国境外实施本法规定的不正当竞争行为，扰乱境内市场竞争秩序，损害境内经营者或者消费者的合法权益的，依照本法以及有关法律的规定处理。"},{"i":41,"n":"第四十一条","txt":"本法自2025年10月15日起施行。"}],"fanlongduanfa":[{"i":1,"n":"第一条","txt":"为了预防和制止垄断行为，保护市场公平竞争，鼓励创新，提高经济运行效率，维护消费者利益和社会公共利益，促进社会主义市场经济健康发展，制定本法。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内经济活动中的垄断行为，适用本法；中华人民共和国境外的垄断行为，对境内市场竞争产生排除、限制影响的，适用本法。"},{"i":3,"n":"第三条","txt":"本法规定的垄断行为包括："},{"i":4,"n":"第四条","txt":"反垄断工作坚持中国共产党的领导。"},{"i":5,"n":"第五条","txt":"国家建立健全公平竞争审查制度。"},{"i":6,"n":"第六条","txt":"经营者可以通过公平竞争、自愿联合，依法实施集中，扩大经营规模，提高市场竞争能力。"},{"i":7,"n":"第七条","txt":"具有市场支配地位的经营者，不得滥用市场支配地位，排除、限制竞争。"},{"i":8,"n":"第八条","txt":"国有经济占控制地位的关系国民经济命脉和国家安全的行业以及依法实行专营专卖的行业，国家对其经营者的合法经营活动予以保护，并对经营者的经营行为及其商品和服务的价格依法实施监管和调控，维护消费者利益，促进技术进步。"},{"i":9,"n":"第九条","txt":"经营者不得利用数据和算法、技术、资本优势以及平台规则等从事本法禁止的垄断行为。"},{"i":10,"n":"第十条","txt":"行政机关和法律、法规授权的具有管理公共事务职能的组织不得滥用行政权力，排除、限制竞争。"},{"i":11,"n":"第十一条","txt":"国家健全完善反垄断规则制度，强化反垄断监管力量，提高监管能力和监管体系现代化水平，加强反垄断执法司法，依法公正高效审理垄断案件，健全行政执法和司法衔接机制，维护公平竞争秩序。"},{"i":12,"n":"第十二条","txt":"国务院设立反垄断委员会，负责组织、协调、指导反垄断工作，履行下列职责："},{"i":13,"n":"第十三条","txt":"国务院反垄断执法机构负责反垄断统一执法工作。"},{"i":14,"n":"第十四条","txt":"行业协会应当加强行业自律，引导本行业的经营者依法竞争，合规经营，维护市场竞争秩序。"},{"i":15,"n":"第十五条","txt":"本法所称经营者，是指从事商品生产、经营或者提供服务的自然人、法人和非法人组织。"},{"i":16,"n":"第十六条","txt":"本法所称垄断协议，是指排除、限制竞争的协议、决定或者其他协同行为。"},{"i":17,"n":"第十七条","txt":"禁止具有竞争关系的经营者达成下列垄断协议："},{"i":18,"n":"第十八条","txt":"禁止经营者与交易相对人达成下列垄断协议："},{"i":19,"n":"第十九条","txt":"经营者不得组织其他经营者达成垄断协议或者为其他经营者达成垄断协议提供实质性帮助。"},{"i":20,"n":"第二十条","txt":"经营者能够证明所达成的协议属于下列情形之一的，不适用本法第十七条、第十八条第一款、第十九条的规定："},{"i":21,"n":"第二十一条","txt":"行业协会不得组织本行业的经营者从事本章禁止的垄断行为。"},{"i":22,"n":"第二十二条","txt":"禁止具有市场支配地位的经营者从事下列滥用市场支配地位的行为："},{"i":23,"n":"第二十三条","txt":"认定经营者具有市场支配地位，应当依据下列因素："},{"i":24,"n":"第二十四条","txt":"有下列情形之一的，可以推定经营者具有市场支配地位："},{"i":25,"n":"第二十五条","txt":"经营者集中是指下列情形："},{"i":26,"n":"第二十六条","txt":"经营者集中达到国务院规定的申报标准的，经营者应当事先向国务院反垄断执法机构申报，未申报的不得实施集中。"},{"i":27,"n":"第二十七条","txt":"经营者集中有下列情形之一的，可以不向国务院反垄断执法机构申报："},{"i":28,"n":"第二十八条","txt":"经营者向国务院反垄断执法机构申报集中，应当提交下列文件、资料："},{"i":29,"n":"第二十九条","txt":"经营者提交的文件、资料不完备的，应当在国务院反垄断执法机构规定的期限内补交文件、资料。经营者逾期未补交文件、资料的，视为未申报。"},{"i":30,"n":"第三十条","txt":"国务院反垄断执法机构应当自收到经营者提交的符合本法第二十八条规定的文件、资料之日起三十日内，对申报的经营者集中进行初步审查，作出是否实施进一步审查的决定，并书面通知经营者。国务院反垄断执法机构作出决定前，经营者不得实施集中。"},{"i":31,"n":"第三十一条","txt":"国务院反垄断执法机构决定实施进一步审查的，应当自决定之日起九十日内审查完毕，作出是否禁止经营者集中的决定，并书面通知经营者。作出禁止经营者集中的决定，应当说明理由。审查期间，经营者不得实施集中。"},{"i":32,"n":"第三十二条","txt":"有下列情形之一的，国务院反垄断执法机构可以决定中止计算经营者集中的审查期限，并书面通知经营者："},{"i":33,"n":"第三十三条","txt":"审查经营者集中，应当考虑下列因素："},{"i":34,"n":"第三十四条","txt":"经营者集中具有或者可能具有排除、限制竞争效果的，国务院反垄断执法机构应当作出禁止经营者集中的决定。但是，经营者能够证明该集中对竞争产生的有利影响明显大于不利影响，或者符合社会公共利益的，国务院反垄断执法机构可以作出对经营者集中不予禁止的决定。"},{"i":35,"n":"第三十五条","txt":"对不予禁止的经营者集中，国务院反垄断执法机构可以决定附加减少集中对竞争产生不利影响的限制性条件。"},{"i":36,"n":"第三十六条","txt":"国务院反垄断执法机构应当将禁止经营者集中的决定或者对经营者集中附加限制性条件的决定，及时向社会公布。"},{"i":37,"n":"第三十七条","txt":"国务院反垄断执法机构应当健全经营者集中分类分级审查制度，依法加强对涉及国计民生等重要领域的经营者集中的审查，提高审查质量和效率。"},{"i":38,"n":"第三十八条","txt":"对外资并购境内企业或者以其他方式参与经营者集中，涉及国家安全的，除依照本法规定进行经营者集中审查外，还应当按照国家有关规定进行国家安全审查。"},{"i":39,"n":"第三十九条","txt":"行政机关和法律、法规授权的具有管理公共事务职能的组织不得滥用行政权力，限定或者变相限定单位或者个人经营、购买、使用其指定的经营者提供的商品。"},{"i":40,"n":"第四十条","txt":"行政机关和法律、法规授权的具有管理公共事务职能的组织不得滥用行政权力，通过与经营者签订合作协议、备忘录等方式，妨碍其他经营者进入相关市场或者对其他经营者实行不平等待遇，排除、限制竞争。"},{"i":41,"n":"第四十一条","txt":"行政机关和法律、法规授权的具有管理公共事务职能的组织不得滥用行政权力，实施下列行为，妨碍商品在地区之间的自由流通："},{"i":42,"n":"第四十二条","txt":"行政机关和法律、法规授权的具有管理公共事务职能的组织不得滥用行政权力，以设定歧视性资质要求、评审标准或者不依法发布信息等方式，排斥或者限制经营者参加招标投标以及其他经营活动。"},{"i":43,"n":"第四十三条","txt":"行政机关和法律、法规授权的具有管理公共事务职能的组织不得滥用行政权力，采取与本地经营者不平等待遇等方式，排斥、限制、强制或者变相强制外地经营者在本地投资或者设立分支机构。"},{"i":44,"n":"第四十四条","txt":"行政机关和法律、法规授权的具有管理公共事务职能的组织不得滥用行政权力，强制或者变相强制经营者从事本法规定的垄断行为。"},{"i":45,"n":"第四十五条","txt":"行政机关和法律、法规授权的具有管理公共事务职能的组织不得滥用行政权力，制定含有排除、限制竞争内容的规定。"},{"i":46,"n":"第四十六条","txt":"反垄断执法机构依法对涉嫌垄断行为进行调查。"},{"i":47,"n":"第四十七条","txt":"反垄断执法机构调查涉嫌垄断行为，可以采取下列措施："},{"i":48,"n":"第四十八条","txt":"反垄断执法机构调查涉嫌垄断行为，执法人员不得少于二人，并应当出示执法证件。"},{"i":49,"n":"第四十九条","txt":"反垄断执法机构及其工作人员对执法过程中知悉的商业秘密、个人隐私和个人信息依法负有保密义务。"},{"i":50,"n":"第五十条","txt":"被调查的经营者、利害关系人或者其他有关单位或者个人应当配合反垄断执法机构依法履行职责，不得拒绝、阻碍反垄断执法机构的调查。"},{"i":51,"n":"第五十一条","txt":"被调查的经营者、利害关系人有权陈述意见。反垄断执法机构应当对被调查的经营者、利害关系人提出的事实、理由和证据进行核实。"},{"i":52,"n":"第五十二条","txt":"反垄断执法机构对涉嫌垄断行为调查核实后，认为构成垄断行为的，应当依法作出处理决定，并可以向社会公布。"},{"i":53,"n":"第五十三条","txt":"对反垄断执法机构调查的涉嫌垄断行为，被调查的经营者承诺在反垄断执法机构认可的期限内采取具体措施消除该行为后果的，反垄断执法机构可以决定中止调查。中止调查的决定应当载明被调查的经营者承诺的具体内容。"},{"i":54,"n":"第五十四条","txt":"反垄断执法机构依法对涉嫌滥用行政权力排除、限制竞争的行为进行调查，有关单位或者个人应当配合。"},{"i":55,"n":"第五十五条","txt":"经营者、行政机关和法律、法规授权的具有管理公共事务职能的组织，涉嫌违反本法规定的，反垄断执法机构可以对其法定代表人或者负责人进行约谈，要求其提出改进措施。"},{"i":56,"n":"第五十六条","txt":"经营者违反本法规定，达成并实施垄断协议的，由反垄断执法机构责令停止违法行为，没收违法所得，并处上一年度销售额百分之一以上百分之十以下的罚款，上一年度没有销售额的，处五百万元以下的罚款；尚未实施所达成的垄断协议的，可以处三百万元以下的罚款。经营者的法定代表人、主要负责人和直接责任人员对达成垄断协议负有个人责任的，可以处一百万元以下的罚款。"},{"i":57,"n":"第五十七条","txt":"经营者违反本法规定，滥用市场支配地位的，由反垄断执法机构责令停止违法行为，没收违法所得，并处上一年度销售额百分之一以上百分之十以下的罚款。"},{"i":58,"n":"第五十八条","txt":"经营者违反本法规定实施集中，且具有或者可能具有排除、限制竞争效果的，由国务院反垄断执法机构责令停止实施集中、限期处分股份或者资产、限期转让营业以及采取其他必要措施恢复到集中前的状态，处上一年度销售额百分之十以下的罚款；不具有排除、限制竞争效果的，处五百万元以下的罚款。"},{"i":59,"n":"第五十九条","txt":"对本法第五十六条、第五十七条、第五十八条规定的罚款，反垄断执法机构确定具体罚款数额时，应当考虑违法行为的性质、程度、持续时间和消除违法行为后果的情况等因素。"},{"i":60,"n":"第六十条","txt":"经营者实施垄断行为，给他人造成损失的，依法承担民事责任。"},{"i":61,"n":"第六十一条","txt":"行政机关和法律、法规授权的具有管理公共事务职能的组织滥用行政权力，实施排除、限制竞争行为的，由上级机关责令改正；对直接负责的主管人员和其他直接责任人员依法给予处分。反垄断执法机构可以向有关上级机关提出依法处理的建议。行政机关和法律、法规授权的具有管理公共事务职能的组织应当将有关改正情况书面报告上级机关和反垄断执法机构。"},{"i":62,"n":"第六十二条","txt":"对反垄断执法机构依法实施的审查和调查，拒绝提供有关材料、信息，或者提供虚假材料、信息，或者隐匿、销毁、转移证据，或者有其他拒绝、阻碍调查行为的，由反垄断执法机构责令改正，对单位处上一年度销售额百分之一以下的罚款，上一年度没有销售额或者销售额难以计算的，处五百万元以下的罚款；对个人处五十万元以下的罚款。"},{"i":63,"n":"第六十三条","txt":"违反本法规定，情节特别严重、影响特别恶劣、造成特别严重后果的，国务院反垄断执法机构可以在本法第五十六条、第五十七条、第五十八条、第六十二条规定的罚款数额的二倍以上五倍以下确定具体罚款数额。"},{"i":64,"n":"第六十四条","txt":"经营者因违反本法规定受到行政处罚的，按照国家有关规定记入信用记录，并向社会公示。"},{"i":65,"n":"第六十五条","txt":"对反垄断执法机构依据本法第三十四条、第三十五条作出的决定不服的，可以先依法申请行政复议；对行政复议决定不服的，可以依法提起行政诉讼。"},{"i":66,"n":"第六十六条","txt":"反垄断执法机构工作人员滥用职权、玩忽职守、徇私舞弊或者泄露执法过程中知悉的商业秘密、个人隐私和个人信息的，依法给予处分。"},{"i":67,"n":"第六十七条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":68,"n":"第六十八条","txt":"经营者依照有关知识产权的法律、行政法规规定行使知识产权的行为，不适用本法；但是，经营者滥用知识产权，排除、限制竞争的行为，适用本法。"},{"i":69,"n":"第六十九条","txt":"农业生产者及农村经济组织在农产品生产、加工、销售、运输、储存等经营活动中实施的联合或者协同行为，不适用本法。"},{"i":70,"n":"第七十条","txt":"本法自2008年8月1日起施行。"}],"fanxiqianfa":[{"i":1,"n":"第一条","txt":"为了预防洗钱活动，遏制洗钱以及相关犯罪，加强和规范反洗钱工作，维护金融秩序、社会公共利益和国家安全，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称反洗钱，是指为了预防通过各种方式掩饰、隐瞒毒品犯罪、黑社会性质的组织犯罪、恐怖活动犯罪、走私犯罪、贪污贿赂犯罪、破坏金融管理秩序犯罪、金融诈骗犯罪和其他犯罪所得及其收益的来源、性质的洗钱活动，依照本法规定采取相关措施的行为。"},{"i":3,"n":"第三条","txt":"反洗钱工作应当贯彻落实党和国家路线方针政策、决策部署，坚持总体国家安全观，完善监督管理体制机制，健全风险防控体系。"},{"i":4,"n":"第四条","txt":"反洗钱工作应当依法进行，确保反洗钱措施与洗钱风险相适应，保障正常金融服务和资金流转顺利进行，维护单位和个人的合法权益。"},{"i":5,"n":"第五条","txt":"国务院反洗钱行政主管部门负责全国的反洗钱监督管理工作。国务院有关部门在各自的职责范围内履行反洗钱监督管理职责。"},{"i":6,"n":"第六条","txt":"在中华人民共和国境内（以下简称境内）设立的金融机构和依照本法规定应当履行反洗钱义务的特定非金融机构，应当依法采取预防、监控措施，建立健全反洗钱内部控制制度，履行客户尽职调查、客户身份资料和交易记录保存、大额交易和可疑交易报告、反洗钱特别预防措施等反洗钱义务。"},{"i":7,"n":"第七条","txt":"对依法履行反洗钱职责或者义务获得的客户身份资料和交易信息、反洗钱调查信息等反洗钱信息，应当予以保密；非依法律规定，不得向任何单位和个人提供。"},{"i":8,"n":"第八条","txt":"履行反洗钱义务的机构及其工作人员依法开展提交大额交易和可疑交易报告等工作，受法律保护。"},{"i":9,"n":"第九条","txt":"反洗钱行政主管部门会同国家有关机关通过多种形式开展反洗钱宣传教育活动，向社会公众宣传洗钱活动的违法性、危害性及其表现形式等，增强社会公众对洗钱活动的防范意识和识别能力。"},{"i":10,"n":"第十条","txt":"任何单位和个人不得从事洗钱活动或者为洗钱活动提供便利，并应当配合金融机构和特定非金融机构依法开展的客户尽职调查。"},{"i":11,"n":"第十一条","txt":"任何单位和个人发现洗钱活动，有权向反洗钱行政主管部门、公安机关或者其他有关国家机关举报。接受举报的机关应当对举报人和举报内容保密。"},{"i":12,"n":"第十二条","txt":"在中华人民共和国境外（以下简称境外）的洗钱和恐怖主义融资活动，危害中华人民共和国主权和安全，侵犯中华人民共和国公民、法人和其他组织合法权益，或者扰乱境内金融秩序的，依照本法以及相关法律规定处理并追究法律责任。"},{"i":13,"n":"第十三条","txt":"国务院反洗钱行政主管部门组织、协调全国的反洗钱工作，负责反洗钱的资金监测，制定或者会同国务院有关金融管理部门制定金融机构反洗钱管理规定，监督检查金融机构履行反洗钱义务的情况，在职责范围内调查可疑交易活动，履行法律和国务院规定的有关反洗钱的其他职责。"},{"i":14,"n":"第十四条","txt":"国务院有关金融管理部门参与制定所监督管理的金融机构反洗钱管理规定，履行法律和国务院规定的有关反洗钱的其他职责。"},{"i":15,"n":"第十五条","txt":"国务院有关特定非金融机构主管部门制定或者国务院反洗钱行政主管部门会同其制定特定非金融机构反洗钱管理规定。"},{"i":16,"n":"第十六条","txt":"国务院反洗钱行政主管部门设立反洗钱监测分析机构。反洗钱监测分析机构开展反洗钱资金监测，负责接收、分析大额交易和可疑交易报告，移送分析结果，并按照规定向国务院反洗钱行政主管部门报告工作情况，履行国务院反洗钱行政主管部门规定的其他职责。"},{"i":17,"n":"第十七条","txt":"国务院反洗钱行政主管部门为履行反洗钱职责，可以从国家有关机关获取所必需的信息，国家有关机关应当依法提供。"},{"i":18,"n":"第十八条","txt":"出入境人员携带的现金、无记名支付凭证等超过规定金额的，应当按照规定向海关申报。海关发现个人出入境携带的现金、无记名支付凭证等超过规定金额的，应当及时向反洗钱行政主管部门通报。"},{"i":19,"n":"第十九条","txt":"国务院反洗钱行政主管部门会同国务院有关部门建立法人、非法人组织受益所有人信息管理制度。"},{"i":20,"n":"第二十条","txt":"反洗钱行政主管部门和其他依法负有反洗钱监督管理职责的部门发现涉嫌洗钱以及相关违法犯罪的交易活动，应当将线索和相关证据材料移送有管辖权的机关处理。接受移送的机关应当按照有关规定反馈处理结果。"},{"i":21,"n":"第二十一条","txt":"反洗钱行政主管部门为依法履行监督管理职责，可以要求金融机构报送履行反洗钱义务情况，对金融机构实施风险监测、评估，并就金融机构执行本法以及相关管理规定的情况进行评价。必要时可以按照规定约谈金融机构的董事、监事、高级管理人员以及反洗钱工作直接负责人，要求其就有关事项说明情况；对金融机构履行反洗钱义务存在的问题进行提示。"},{"i":22,"n":"第二十二条","txt":"反洗钱行政主管部门进行监督检查时，可以采取下列措施："},{"i":23,"n":"第二十三条","txt":"国务院反洗钱行政主管部门会同国家有关机关评估国家、行业面临的洗钱风险，发布洗钱风险指引，加强对履行反洗钱义务的机构指导，支持和鼓励反洗钱领域技术创新，及时监测与新领域、新业态相关的新型洗钱风险，根据洗钱风险状况优化资源配置，完善监督管理措施。"},{"i":24,"n":"第二十四条","txt":"对存在严重洗钱风险的国家或者地区，国务院反洗钱行政主管部门可以在征求国家有关机关意见的基础上，经国务院批准，将其列为洗钱高风险国家或者地区，并采取相应措施。"},{"i":25,"n":"第二十五条","txt":"履行反洗钱义务的机构可以依法成立反洗钱自律组织。反洗钱自律组织与相关行业自律组织协同开展反洗钱领域的自律管理。"},{"i":26,"n":"第二十六条","txt":"提供反洗钱咨询、技术、专业能力评价等服务的机构及其工作人员，应当勤勉尽责、恪尽职守地提供服务；对于因提供服务获得的数据、信息，应当依法妥善处理，确保数据、信息安全。"},{"i":27,"n":"第二十七条","txt":"金融机构应当依照本法规定建立健全反洗钱内部控制制度，设立专门机构或者指定内设机构牵头负责反洗钱工作，根据经营规模和洗钱风险状况配备相应的人员，按照要求开展反洗钱培训和宣传。"},{"i":28,"n":"第二十八条","txt":"金融机构应当按照规定建立客户尽职调查制度。"},{"i":29,"n":"第二十九条","txt":"有下列情形之一的，金融机构应当开展客户尽职调查："},{"i":30,"n":"第三十条","txt":"在业务关系存续期间，金融机构应当持续关注并评估客户整体状况及交易情况，了解客户的洗钱风险。发现客户进行的交易与金融机构所掌握的客户身份、风险状况等不符的，应当进一步核实客户及其交易有关情况；对存在洗钱高风险情形的，必要时可以采取限制交易方式、金额或者频次，限制业务类型，拒绝办理业务，终止业务关系等洗钱风险管理措施。"},{"i":31,"n":"第三十一条","txt":"客户由他人代理办理业务的，金融机构应当按照规定核实代理关系，识别并核实代理人的身份。"},{"i":32,"n":"第三十二条","txt":"金融机构依托第三方开展客户尽职调查的，应当评估第三方的风险状况及其履行反洗钱义务的能力。第三方具有较高风险情形或者不具备履行反洗钱义务能力的，金融机构不得依托其开展客户尽职调查。"},{"i":33,"n":"第三十三条","txt":"金融机构进行客户尽职调查，可以通过反洗钱行政主管部门以及公安、市场监督管理、民政、税务、移民管理、电信管理等部门依法核实客户身份等有关信息，相关部门应当依法予以支持。"},{"i":34,"n":"第三十四条","txt":"金融机构应当按照规定建立客户身份资料和交易记录保存制度。"},{"i":35,"n":"第三十五条","txt":"金融机构应当按照规定执行大额交易报告制度，客户单笔交易或者在一定期限内的累计交易超过规定金额的，应当及时向反洗钱监测分析机构报告。"},{"i":36,"n":"第三十六条","txt":"金融机构应当在反洗钱行政主管部门的指导下，关注、评估运用新技术、新产品、新业务等带来的洗钱风险，根据情形采取相应措施，降低洗钱风险。"},{"i":37,"n":"第三十七条","txt":"在境内外设有分支机构或者控股其他金融机构的金融机构，以及金融控股公司，应当在总部或者集团层面统筹安排反洗钱工作。为履行反洗钱义务在公司内部、集团成员之间共享必要的反洗钱信息的，应当明确信息共享机制和程序。共享反洗钱信息，应当符合有关信息保护的法律规定，并确保相关信息不被用于反洗钱和反恐怖主义融资以外的用途。"},{"i":38,"n":"第三十八条","txt":"与金融机构存在业务关系的单位和个人应当配合金融机构的客户尽职调查，提供真实有效的身份证件或者其他身份证明文件，准确、完整填报身份信息，如实提供与交易和资金相关的资料。"},{"i":39,"n":"第三十九条","txt":"单位和个人对金融机构采取洗钱风险管理措施有异议的，可以向金融机构提出。金融机构应当在十五日内进行处理，并将结果答复当事人；涉及客户基本的、必需的金融服务的，应当及时处理并答复当事人。相关单位和个人逾期未收到答复，或者对处理结果不满意的，可以向反洗钱行政主管部门投诉。"},{"i":40,"n":"第四十条","txt":"任何单位和个人应当按照国家有关机关要求对下列名单所列对象采取反洗钱特别预防措施："},{"i":41,"n":"第四十一条","txt":"金融机构应当识别、评估相关风险并制定相应的制度，及时获取本法第四十条第一款规定的名单，对客户及其交易对象进行核查，采取相应措施，并向反洗钱行政主管部门报告。"},{"i":42,"n":"第四十二条","txt":"特定非金融机构在从事规定的特定业务时，参照本章关于金融机构履行反洗钱义务的相关规定，根据行业特点、经营规模、洗钱风险状况履行反洗钱义务。"},{"i":43,"n":"第四十三条","txt":"国务院反洗钱行政主管部门或者其设区的市级以上派出机构发现涉嫌洗钱的可疑交易活动或者违反本法规定的其他行为，需要调查核实的，经国务院反洗钱行政主管部门或者其设区的市级以上派出机构负责人批准，可以向金融机构、特定非金融机构发出调查通知书，开展反洗钱调查。"},{"i":44,"n":"第四十四条","txt":"国务院反洗钱行政主管部门或者其设区的市级以上派出机构开展反洗钱调查，可以采取下列措施："},{"i":45,"n":"第四十五条","txt":"经调查仍不能排除洗钱嫌疑或者发现其他违法犯罪线索的，应当及时向有管辖权的机关移送。接受移送的机关应当按照有关规定反馈处理结果。"},{"i":46,"n":"第四十六条","txt":"中华人民共和国根据缔结或者参加的国际条约，或者按照平等互惠原则，开展反洗钱国际合作。"},{"i":47,"n":"第四十七条","txt":"国务院反洗钱行政主管部门根据国务院授权，负责组织、协调反洗钱国际合作，代表中国政府参与有关国际组织活动，依法与境外相关机构开展反洗钱合作，交换反洗钱信息。"},{"i":48,"n":"第四十八条","txt":"涉及追究洗钱犯罪的司法协助，依照《中华人民共和国国际刑事司法协助法》以及有关法律的规定办理。"},{"i":49,"n":"第四十九条","txt":"国家有关机关在依法调查洗钱和恐怖主义融资活动过程中，按照对等原则或者经与有关国家协商一致，可以要求在境内开立代理行账户或者与我国存在其他密切金融联系的境外金融机构予以配合。"},{"i":50,"n":"第五十条","txt":"外国国家、组织违反对等、协商一致原则直接要求境内金融机构提交客户身份资料、交易信息，扣押、冻结、划转境内资金、资产，或者作出其他行动的，金融机构不得擅自执行，并应当及时向国务院有关金融管理部门报告。"},{"i":51,"n":"第五十一条","txt":"反洗钱行政主管部门和其他依法负有反洗钱监督管理职责的部门从事反洗钱工作的人员有下列行为之一的，依法给予处分："},{"i":52,"n":"第五十二条","txt":"金融机构有下列情形之一的，由国务院反洗钱行政主管部门或者其设区的市级以上派出机构责令限期改正；情节较重的，给予警告或者处二十万元以下罚款；情节严重或者逾期未改正的，处二十万元以上二百万元以下罚款，可以根据情形在职责范围内或者建议有关金融管理部门限制或者禁止其开展相关业务："},{"i":53,"n":"第五十三条","txt":"金融机构有下列行为之一的，由国务院反洗钱行政主管部门或者其设区的市级以上派出机构责令限期改正，可以给予警告或者处二十万元以下罚款；情节严重或者逾期未改正的，处二十万元以上二百万元以下罚款："},{"i":54,"n":"第五十四条","txt":"金融机构有下列行为之一的，由国务院反洗钱行政主管部门或者其设区的市级以上派出机构责令限期改正，处五十万元以下罚款；情节严重的，处五十万元以上五百万元以下罚款，可以根据情形在职责范围内或者建议有关金融管理部门限制或者禁止其开展相关业务："},{"i":55,"n":"第五十五条","txt":"金融机构有本法第五十三条、第五十四条规定的行为，致使犯罪所得及其收益通过本机构得以掩饰、隐瞒的，或者致使恐怖主义融资后果发生的，由国务院反洗钱行政主管部门或者其设区的市级以上派出机构责令限期改正，涉及金额不足一千万元的，处五十万元以上一千万元以下罚款；涉及金额一千万元以上的，处涉及金额百分之二十以上二倍以下罚款；情节严重的，可以根据情形在职责范围内实施或者建议有关金融管理部门实施限制、禁止其开展相关业务，或者责令停业整顿、吊销经营许可证等处罚。"},{"i":56,"n":"第五十六条","txt":"国务院反洗钱行政主管部门或者其设区的市级以上派出机构依照本法第五十二条至第五十四条规定对金融机构进行处罚的，还可以根据情形对负有责任的董事、监事、高级管理人员或者其他直接责任人员，给予警告或者处二十万元以下罚款；情节严重的，可以根据情形在职责范围内实施或者建议有关金融管理部门实施取消其任职资格、禁止其从事有关金融行业工作等处罚。"},{"i":57,"n":"第五十七条","txt":"金融机构违反本法第五十条规定擅自采取行动的，由国务院有关金融管理部门处五十万元以下罚款；情节严重的，处五十万元以上五百万元以下罚款；造成损失的，并处所造成直接经济损失一倍以上五倍以下罚款。对负有责任的董事、监事、高级管理人员或者其他直接责任人员，可以由国务院有关金融管理部门给予警告或者处五十万元以下罚款。"},{"i":58,"n":"第五十八条","txt":"特定非金融机构违反本法规定的，由有关特定非金融机构主管部门责令限期改正；情节较重的，给予警告或者处五万元以下罚款；情节严重或者逾期未改正的，处五万元以上五十万元以下罚款；对有关负责人，可以给予警告或者处五万元以下罚款。"},{"i":59,"n":"第五十九条","txt":"金融机构、特定非金融机构以外的单位和个人未依照本法第四十条规定履行反洗钱特别预防措施义务的，由国务院反洗钱行政主管部门或者其设区的市级以上派出机构责令限期改正；情节严重的，对单位给予警告或者处二十万元以下罚款，对个人给予警告或者处五万元以下罚款。"},{"i":60,"n":"第六十条","txt":"法人、非法人组织未按照规定向登记机关提交受益所有人信息的，由登记机关责令限期改正；拒不改正的，处五万元以下罚款。向登记机关提交虚假或者不实的受益所有人信息，或者未按照规定及时更新受益所有人信息的，由国务院反洗钱行政主管部门或者其设区的市级以上派出机构责令限期改正；拒不改正的，处五万元以下罚款。"},{"i":61,"n":"第六十一条","txt":"国务院反洗钱行政主管部门应当综合考虑金融机构的经营规模、内部控制制度执行情况、勤勉尽责程度、违法行为持续时间、危害程度以及整改情况等因素，制定本法相关行政处罚裁量基准。"},{"i":62,"n":"第六十二条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":63,"n":"第六十三条","txt":"在境内设立的下列机构，履行本法规定的金融机构反洗钱义务："},{"i":64,"n":"第六十四条","txt":"在境内设立的下列机构，履行本法规定的特定非金融机构反洗钱义务："},{"i":65,"n":"第六十五条","txt":"本法自2025年1月1日起施行。"}],"taiwantongbaotouzibaohufa":[{"i":1,"n":"第一条","txt":"为了保护和鼓励台湾同胞投资，促进海峡两岸的经济发展，制定本法。"},{"i":2,"n":"第二条","txt":"台湾同胞投资适用本法；本法未规定的，国家其他有关法律、行政法规对台湾同胞投资有规定的，依照该规定执行。"},{"i":3,"n":"第三条","txt":"国家依法保护台湾同胞投资者的投资、投资收益和其他合法权益。"},{"i":4,"n":"第四条","txt":"国家对台湾同胞投资者的投资不实行国有化和征收；在特殊情况下，根据社会公共利益的需要，对台湾同胞投资者的投资可以依照法律程序实行征收，并给予相应的补偿。"},{"i":5,"n":"第五条","txt":"台湾同胞投资者投资的财产、工业产权、投资收益和其他合法权益，可以依法转让和继承。"},{"i":6,"n":"第六条","txt":"台湾同胞投资者可以用可自由兑换货币、机器设备或者其他实物、工业产权、非专利技术等作为投资。"},{"i":7,"n":"第七条","txt":"台湾同胞投资，可以举办全部或者部分由台湾同胞投资者投资的企业（以下简称台湾同胞投资企业），也可以采用法律、行政法规或者国务院规定的其他投资形式。"},{"i":8,"n":"第八条","txt":"台湾同胞投资企业依法进行经营管理活动，其经营管理的自主权不受干涉。"},{"i":9,"n":"第九条","txt":"在台湾同胞投资企业集中的地区，可以依法成立台湾同胞投资企业协会，其合法权益受法律保护。"},{"i":10,"n":"第十条","txt":"台湾同胞投资者依法获得的投资收益、其他合法收入和清算后的资金，可以依法汇回台湾或者汇往境外。"},{"i":11,"n":"第十一条","txt":"台湾同胞投资者可以委托亲友作为其投资的代理人。"},{"i":12,"n":"第十二条","txt":"台湾同胞投资企业依照国务院关于鼓励台湾同胞投资的有关规定，享受优惠待遇。"},{"i":13,"n":"第十三条","txt":"台湾同胞投资者与其他省、自治区和直辖市的公司、企业、其他经济组织或者个人之间发生的与投资有关的争议，当事人可以通过协商或者调解解决。"},{"i":14,"n":"第十四条","txt":"本法自公布之日起施行。"}],"chengshiweihujiansheshuifa":[{"i":1,"n":"第一条","txt":"在中华人民共和国境内缴纳增值税、消费税的单位和个人，为城市维护建设税的纳税人，应当依照本法规定缴纳城市维护建设税。"},{"i":2,"n":"第二条","txt":"城市维护建设税以纳税人依法实际缴纳的增值税、消费税税额为计税依据。"},{"i":3,"n":"第三条","txt":"对进口货物或者境外单位和个人向境内销售劳务、服务、无形资产缴纳的增值税、消费税税额，不征收城市维护建设税。"},{"i":4,"n":"第四条","txt":"城市维护建设税税率如下："},{"i":5,"n":"第五条","txt":"城市维护建设税的应纳税额按照计税依据乘以具体适用税率计算。"},{"i":6,"n":"第六条","txt":"根据国民经济和社会发展的需要，国务院对重大公共基础设施建设、特殊产业和群体以及重大突发事件应对等情形可以规定减征或者免征城市维护建设税，报全国人民代表大会常务委员会备案。"},{"i":7,"n":"第七条","txt":"城市维护建设税的纳税义务发生时间与增值税、消费税的纳税义务发生时间一致，分别与增值税、消费税同时缴纳。"},{"i":8,"n":"第八条","txt":"城市维护建设税的扣缴义务人为负有增值税、消费税扣缴义务的单位和个人，在扣缴增值税、消费税的同时扣缴城市维护建设税。"},{"i":9,"n":"第九条","txt":"城市维护建设税由税务机关依照本法和《中华人民共和国税收征收管理法》的规定征收管理。"},{"i":10,"n":"第十条","txt":"纳税人、税务机关及其工作人员违反本法规定的，依照《中华人民共和国税收征收管理法》和有关法律法规的规定追究法律责任。"},{"i":11,"n":"第十一条","txt":"本法自2021年9月1日起施行。1985年2月8日国务院发布的《中华人民共和国城市维护建设税暂行条例》同时废止。"}],"zengzhishuifa":[{"i":1,"n":"第一条","txt":"为了健全有利于高质量发展的增值税制度，规范增值税的征收和缴纳，保护纳税人的合法权益，制定本法。"},{"i":2,"n":"第二条","txt":"增值税税收工作应当贯彻落实党和国家路线方针政策、决策部署，为国民经济和社会发展服务。"},{"i":3,"n":"第三条","txt":"在中华人民共和国境内（以下简称境内）销售货物、服务、无形资产、不动产（以下称应税交易），以及进口货物的单位和个人（包括个体工商户），为增值税的纳税人，应当依照本法规定缴纳增值税。"},{"i":4,"n":"第四条","txt":"在境内发生应税交易，是指下列情形："},{"i":5,"n":"第五条","txt":"有下列情形之一的，视同应税交易，应当依照本法规定缴纳增值税："},{"i":6,"n":"第六条","txt":"有下列情形之一的，不属于应税交易，不征收增值税："},{"i":7,"n":"第七条","txt":"增值税为价外税，应税交易的销售额不包括增值税税额。增值税税额，应当按照国务院的规定在交易凭证上单独列明。"},{"i":8,"n":"第八条","txt":"纳税人发生应税交易，应当按照一般计税方法，通过销项税额抵扣进项税额计算应纳税额的方式，计算缴纳增值税；本法另有规定的除外。"},{"i":9,"n":"第九条","txt":"本法所称小规模纳税人，是指年应征增值税销售额未超过五百万元的纳税人。"},{"i":10,"n":"第十条","txt":"增值税税率："},{"i":11,"n":"第十一条","txt":"适用简易计税方法计算缴纳增值税的征收率为百分之三。"},{"i":12,"n":"第十二条","txt":"纳税人发生两项以上应税交易涉及不同税率、征收率的，应当分别核算适用不同税率、征收率的销售额；未分别核算的，从高适用税率。"},{"i":13,"n":"第十三条","txt":"纳税人发生一项应税交易涉及两个以上税率、征收率的，按照应税交易的主要业务适用税率、征收率。"},{"i":14,"n":"第十四条","txt":"按照一般计税方法计算缴纳增值税的，应纳税额为当期销项税额抵扣当期进项税额后的余额。"},{"i":15,"n":"第十五条","txt":"境外单位和个人在境内发生应税交易，以购买方为扣缴义务人；按照国务院的规定委托境内代理人申报缴纳税款的除外。"},{"i":16,"n":"第十六条","txt":"销项税额，是指纳税人发生应税交易，按照销售额乘以本法规定的税率计算的增值税税额。"},{"i":17,"n":"第十七条","txt":"销售额，是指纳税人发生应税交易取得的与之相关的价款，包括货币和非货币形式的经济利益对应的全部价款，不包括按照一般计税方法计算的销项税额和按照简易计税方法计算的应纳税额。"},{"i":18,"n":"第十八条","txt":"销售额以人民币计算。纳税人以人民币以外的货币结算销售额的，应当折合成人民币计算。"},{"i":19,"n":"第十九条","txt":"发生本法第五条规定的视同应税交易以及销售额为非货币形式的，纳税人应当按照市场价格确定销售额。"},{"i":20,"n":"第二十条","txt":"销售额明显偏低或者偏高且无正当理由的，税务机关可以依照《中华人民共和国税收征收管理法》和有关行政法规的规定核定销售额。"},{"i":21,"n":"第二十一条","txt":"当期进项税额大于当期销项税额的部分，纳税人可以按照国务院的规定选择结转下期继续抵扣或者申请退还。"},{"i":22,"n":"第二十二条","txt":"纳税人的下列进项税额不得从其销项税额中抵扣："},{"i":23,"n":"第二十三条","txt":"小规模纳税人发生应税交易，销售额未达到起征点的，免征增值税；达到起征点的，依照本法规定全额计算缴纳增值税。"},{"i":24,"n":"第二十四条","txt":"下列项目免征增值税："},{"i":25,"n":"第二十五条","txt":"根据国民经济和社会发展的需要，国务院对支持小微企业发展、扶持重点产业、鼓励创新创业就业、公益事业捐赠等情形可以制定增值税专项优惠政策，报全国人民代表大会常务委员会备案。"},{"i":26,"n":"第二十六条","txt":"纳税人兼营增值税优惠项目的，应当单独核算增值税优惠项目的销售额；未单独核算的项目，不得享受税收优惠。"},{"i":27,"n":"第二十七条","txt":"纳税人可以放弃增值税优惠；放弃优惠的，在三十六个月内不得享受该项税收优惠，小规模纳税人除外。"},{"i":28,"n":"第二十八条","txt":"增值税纳税义务发生时间，按照下列规定确定："},{"i":29,"n":"第二十九条","txt":"增值税纳税地点，按照下列规定确定："},{"i":30,"n":"第三十条","txt":"增值税的计税期间分别为十日、十五日、一个月或者一个季度。纳税人的具体计税期间，由主管税务机关根据纳税人应纳税额的大小分别核定。不经常发生应税交易的纳税人，可以按次纳税。"},{"i":31,"n":"第三十一条","txt":"纳税人以十日或者十五日为一个计税期间的，应当自期满之日起五日内预缴税款。"},{"i":32,"n":"第三十二条","txt":"增值税由税务机关征收，进口货物的增值税由海关代征。"},{"i":33,"n":"第三十三条","txt":"纳税人出口货物或者跨境销售服务、无形资产，适用零税率的，应当向主管税务机关申报办理退（免）税。出口退（免）税的具体办法，由国务院制定。"},{"i":34,"n":"第三十四条","txt":"纳税人应当依法开具和使用增值税发票。增值税发票包括纸质发票和电子发票。电子发票与纸质发票具有同等法律效力。"},{"i":35,"n":"第三十五条","txt":"税务机关与工业和信息化、公安、海关、市场监督管理、人民银行、金融监督管理等部门建立增值税涉税信息共享机制和工作配合机制。"},{"i":36,"n":"第三十六条","txt":"增值税的征收管理依照本法和《中华人民共和国税收征收管理法》的规定执行。"},{"i":37,"n":"第三十七条","txt":"纳税人、扣缴义务人、税务机关及其工作人员违反本法规定的，依照《中华人民共和国税收征收管理法》和有关法律、行政法规的规定追究法律责任。"},{"i":38,"n":"第三十八条","txt":"本法自2026年1月1日起施行。《中华人民共和国增值税暂行条例》同时废止。"}],"waishangtouzifa":[{"i":1,"n":"第一条","txt":"为了进一步扩大对外开放，积极促进外商投资，保护外商投资合法权益，规范外商投资管理，推动形成全面开放新格局，促进社会主义市场经济健康发展，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内（以下简称中国境内）的外商投资，适用本法。"},{"i":3,"n":"第三条","txt":"国家坚持对外开放的基本国策，鼓励外国投资者依法在中国境内投资。"},{"i":4,"n":"第四条","txt":"国家对外商投资实行准入前国民待遇加负面清单管理制度。"},{"i":5,"n":"第五条","txt":"国家依法保护外国投资者在中国境内的投资、收益和其他合法权益。"},{"i":6,"n":"第六条","txt":"在中国境内进行投资活动的外国投资者、外商投资企业，应当遵守中国法律法规，不得危害中国国家安全、损害社会公共利益。"},{"i":7,"n":"第七条","txt":"国务院商务主管部门、投资主管部门按照职责分工，开展外商投资促进、保护和管理工作；国务院其他有关部门在各自职责范围内，负责外商投资促进、保护和管理的相关工作。"},{"i":8,"n":"第八条","txt":"外商投资企业职工依法建立工会组织，开展工会活动，维护职工的合法权益。外商投资企业应当为本企业工会提供必要的活动条件。"},{"i":9,"n":"第九条","txt":"外商投资企业依法平等适用国家支持企业发展的各项政策。"},{"i":10,"n":"第十条","txt":"制定与外商投资有关的法律、法规、规章，应当采取适当方式征求外商投资企业的意见和建议。"},{"i":11,"n":"第十一条","txt":"国家建立健全外商投资服务体系，为外国投资者和外商投资企业提供法律法规、政策措施、投资项目信息等方面的咨询和服务。"},{"i":12,"n":"第十二条","txt":"国家与其他国家和地区、国际组织建立多边、双边投资促进合作机制，加强投资领域的国际交流与合作。"},{"i":13,"n":"第十三条","txt":"国家根据需要，设立特殊经济区域，或者在部分地区实行外商投资试验性政策措施，促进外商投资，扩大对外开放。"},{"i":14,"n":"第十四条","txt":"国家根据国民经济和社会发展需要，鼓励和引导外国投资者在特定行业、领域、地区投资。外国投资者、外商投资企业可以依照法律、行政法规或者国务院的规定享受优惠待遇。"},{"i":15,"n":"第十五条","txt":"国家保障外商投资企业依法平等参与标准制定工作，强化标准制定的信息公开和社会监督。"},{"i":16,"n":"第十六条","txt":"国家保障外商投资企业依法通过公平竞争参与政府采购活动。政府采购依法对外商投资企业在中国境内生产的产品、提供的服务平等对待。"},{"i":17,"n":"第十七条","txt":"外商投资企业可以依法通过公开发行股票、公司债券等证券和其他方式进行融资。"},{"i":18,"n":"第十八条","txt":"县级以上地方人民政府可以根据法律、行政法规、地方性法规的规定，在法定权限内制定外商投资促进和便利化政策措施。"},{"i":19,"n":"第十九条","txt":"各级人民政府及其有关部门应当按照便利、高效、透明的原则，简化办事程序，提高办事效率，优化政务服务，进一步提高外商投资服务水平。"},{"i":20,"n":"第二十条","txt":"国家对外国投资者的投资不实行征收。"},{"i":21,"n":"第二十一条","txt":"外国投资者在中国境内的出资、利润、资本收益、资产处置所得、知识产权许可使用费、依法获得的补偿或者赔偿、清算所得等，可以依法以人民币或者外汇自由汇入、汇出。"},{"i":22,"n":"第二十二条","txt":"国家保护外国投资者和外商投资企业的知识产权，保护知识产权权利人和相关权利人的合法权益；对知识产权侵权行为，严格依法追究法律责任。"},{"i":23,"n":"第二十三条","txt":"行政机关及其工作人员对于履行职责过程中知悉的外国投资者、外商投资企业的商业秘密，应当依法予以保密，不得泄露或者非法向他人提供。"},{"i":24,"n":"第二十四条","txt":"各级人民政府及其有关部门制定涉及外商投资的规范性文件，应当符合法律法规的规定；没有法律、行政法规依据的，不得减损外商投资企业的合法权益或者增加其义务，不得设置市场准入和退出条件，不得干预外商投资企业的正常生产经营活动。"},{"i":25,"n":"第二十五条","txt":"地方各级人民政府及其有关部门应当履行向外国投资者、外商投资企业依法作出的政策承诺以及依法订立的各类合同。"},{"i":26,"n":"第二十六条","txt":"国家建立外商投资企业投诉工作机制，及时处理外商投资企业或者其投资者反映的问题，协调完善相关政策措施。"},{"i":27,"n":"第二十七条","txt":"外商投资企业可以依法成立和自愿参加商会、协会。商会、协会依照法律法规和章程的规定开展相关活动，维护会员的合法权益。"},{"i":28,"n":"第二十八条","txt":"外商投资准入负面清单规定禁止投资的领域，外国投资者不得投资。"},{"i":29,"n":"第二十九条","txt":"外商投资需要办理投资项目核准、备案的，按照国家有关规定执行。"},{"i":30,"n":"第三十条","txt":"外国投资者在依法需要取得许可的行业、领域进行投资的，应当依法办理相关许可手续。"},{"i":31,"n":"第三十一条","txt":"外商投资企业的组织形式、组织机构及其活动准则，适用《中华人民共和国公司法》、《中华人民共和国合伙企业法》等法律的规定。"},{"i":32,"n":"第三十二条","txt":"外商投资企业开展生产经营活动，应当遵守法律、行政法规有关劳动保护、社会保险的规定，依照法律、行政法规和国家有关规定办理税收、会计、外汇等事宜，并接受相关主管部门依法实施的监督检查。"},{"i":33,"n":"第三十三条","txt":"外国投资者并购中国境内企业或者以其他方式参与经营者集中的，应当依照《中华人民共和国反垄断法》的规定接受经营者集中审查。"},{"i":34,"n":"第三十四条","txt":"国家建立外商投资信息报告制度。外国投资者或者外商投资企业应当通过企业登记系统以及企业信用信息公示系统向商务主管部门报送投资信息。"},{"i":35,"n":"第三十五条","txt":"国家建立外商投资安全审查制度，对影响或者可能影响国家安全的外商投资进行安全审查。"},{"i":36,"n":"第三十六条","txt":"外国投资者投资外商投资准入负面清单规定禁止投资的领域的，由有关主管部门责令停止投资活动，限期处分股份、资产或者采取其他必要措施，恢复到实施投资前的状态；有违法所得的，没收违法所得。"},{"i":37,"n":"第三十七条","txt":"外国投资者、外商投资企业违反本法规定，未按照外商投资信息报告制度的要求报送投资信息的，由商务主管部门责令限期改正；逾期不改正的，处十万元以上五十万元以下的罚款。"},{"i":38,"n":"第三十八条","txt":"对外国投资者、外商投资企业违反法律、法规的行为，由有关部门依法查处，并按照国家有关规定纳入信用信息系统。"},{"i":39,"n":"第三十九条","txt":"行政机关工作人员在外商投资促进、保护和管理工作中滥用职权、玩忽职守、徇私舞弊的，或者泄露、非法向他人提供履行职责过程中知悉的商业秘密的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":40,"n":"第四十条","txt":"任何国家或者地区在投资方面对中华人民共和国采取歧视性的禁止、限制或者其他类似措施的，中华人民共和国可以根据实际情况对该国家或者该地区采取相应的措施。"},{"i":41,"n":"第四十一条","txt":"对外国投资者在中国境内投资银行业、证券业、保险业等金融行业，或者在证券市场、外汇市场等金融市场进行投资的管理，国家另有规定的，依照其规定。"},{"i":42,"n":"第四十二条","txt":"本法自2020年1月1日起施行。《中华人民共和国中外合资经营企业法》、《中华人民共和国外资企业法》、《中华人民共和国中外合作经营企业法》同时废止。"}],"qishuifa":[{"i":1,"n":"第一条","txt":"在中华人民共和国境内转移土地、房屋权属，承受的单位和个人为契税的纳税人，应当依照本法规定缴纳契税。"},{"i":2,"n":"第二条","txt":"本法所称转移土地、房屋权属，是指下列行为："},{"i":3,"n":"第三条","txt":"契税税率为百分之三至百分之五。"},{"i":4,"n":"第四条","txt":"契税的计税依据："},{"i":5,"n":"第五条","txt":"契税的应纳税额按照计税依据乘以具体适用税率计算。"},{"i":6,"n":"第六条","txt":"有下列情形之一的，免征契税："},{"i":7,"n":"第七条","txt":"省、自治区、直辖市可以决定对下列情形免征或者减征契税："},{"i":8,"n":"第八条","txt":"纳税人改变有关土地、房屋的用途，或者有其他不再属于本法第六条规定的免征、减征契税情形的，应当缴纳已经免征、减征的税款。"},{"i":9,"n":"第九条","txt":"契税的纳税义务发生时间，为纳税人签订土地、房屋权属转移合同的当日，或者纳税人取得其他具有土地、房屋权属转移合同性质凭证的当日。"},{"i":10,"n":"第十条","txt":"纳税人应当在依法办理土地、房屋权属登记手续前申报缴纳契税。"},{"i":11,"n":"第十一条","txt":"纳税人办理纳税事宜后，税务机关应当开具契税完税凭证。纳税人办理土地、房屋权属登记，不动产登记机构应当查验契税完税、减免税凭证或者有关信息。未按照规定缴纳契税的，不动产登记机构不予办理土地、房屋权属登记。"},{"i":12,"n":"第十二条","txt":"在依法办理土地、房屋权属登记前，权属转移合同、权属转移合同性质凭证不生效、无效、被撤销或者被解除的，纳税人可以向税务机关申请退还已缴纳的税款，税务机关应当依法办理。"},{"i":13,"n":"第十三条","txt":"税务机关应当与相关部门建立契税涉税信息共享和工作配合机制。自然资源、住房城乡建设、民政、公安等相关部门应当及时向税务机关提供与转移土地、房屋权属有关的信息，协助税务机关加强契税征收管理。"},{"i":14,"n":"第十四条","txt":"契税由土地、房屋所在地的税务机关依照本法和《中华人民共和国税收征收管理法》的规定征收管理。"},{"i":15,"n":"第十五条","txt":"纳税人、税务机关及其工作人员违反本法规定的，依照《中华人民共和国税收征收管理法》和有关法律法规的规定追究法律责任。"},{"i":16,"n":"第十六条","txt":"本法自2021年9月1日起施行。1997年7月7日国务院发布的《中华人民共和国契税暂行条例》同时废止。"}],"shenjifa":[{"i":1,"n":"第一条","txt":"为了加强国家的审计监督，维护国家财政经济秩序，提高财政资金使用效益，促进廉政建设，保障国民经济和社会健康发展，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"国家实行审计监督制度。坚持中国共产党对审计工作的领导，构建集中统一、全面覆盖、权威高效的审计监督体系。"},{"i":3,"n":"第三条","txt":"审计机关依照法律规定的职权和程序，进行审计监督。"},{"i":4,"n":"第四条","txt":"国务院和县级以上地方人民政府应当每年向本级人民代表大会常务委员会提出审计工作报告。审计工作报告应当报告审计机关对预算执行、决算草案以及其他财政收支的审计情况，重点报告对预算执行及其绩效的审计情况，按照有关法律、行政法规的规定报告对国有资源、国有资产的审计情况。必要时，人民代表大会常务委员会可以对审计工作报告作出决议。"},{"i":5,"n":"第五条","txt":"审计机关依照法律规定独立行使审计监督权，不受其他行政机关、社会团体和个人的干涉。"},{"i":6,"n":"第六条","txt":"审计机关和审计人员办理审计事项，应当客观公正，实事求是，廉洁奉公，保守秘密。"},{"i":7,"n":"第七条","txt":"国务院设立审计署，在国务院总理领导下，主管全国的审计工作。审计长是审计署的行政首长。"},{"i":8,"n":"第八条","txt":"省、自治区、直辖市、设区的市、自治州、县、自治县、不设区的市、市辖区的人民政府的审计机关，分别在省长、自治区主席、市长、州长、县长、区长和上一级审计机关的领导下，负责本行政区域内的审计工作。"},{"i":9,"n":"第九条","txt":"地方各级审计机关对本级人民政府和上一级审计机关负责并报告工作，审计业务以上级审计机关领导为主。"},{"i":10,"n":"第十条","txt":"审计机关根据工作需要，经本级人民政府批准，可以在其审计管辖范围内设立派出机构。"},{"i":11,"n":"第十一条","txt":"审计机关履行职责所必需的经费，应当列入预算予以保证。"},{"i":12,"n":"第十二条","txt":"审计机关应当建设信念坚定、为民服务、业务精通、作风务实、敢于担当、清正廉洁的高素质专业化审计队伍。"},{"i":13,"n":"第十三条","txt":"审计人员应当具备与其从事的审计工作相适应的专业知识和业务能力。"},{"i":14,"n":"第十四条","txt":"审计机关和审计人员不得参加可能影响其依法独立履行审计监督职责的活动，不得干预、插手被审计单位及其相关单位的正常生产经营和管理活动。"},{"i":15,"n":"第十五条","txt":"审计人员办理审计事项，与被审计单位或者审计事项有利害关系的，应当回避。"},{"i":16,"n":"第十六条","txt":"审计机关和审计人员对在执行职务中知悉的国家秘密、工作秘密、商业秘密、个人隐私和个人信息，应当予以保密，不得泄露或者向他人非法提供。"},{"i":17,"n":"第十七条","txt":"审计人员依法执行职务，受法律保护。"},{"i":18,"n":"第十八条","txt":"审计机关对本级各部门（含直属单位）和下级政府预算的执行情况和决算以及其他财政收支情况，进行审计监督。"},{"i":19,"n":"第十九条","txt":"审计署在国务院总理领导下，对中央预算执行情况、决算草案以及其他财政收支情况进行审计监督，向国务院总理提出审计结果报告。"},{"i":20,"n":"第二十条","txt":"审计署对中央银行的财务收支，进行审计监督。"},{"i":21,"n":"第二十一条","txt":"审计机关对国家的事业组织和使用财政资金的其他事业组织的财务收支，进行审计监督。"},{"i":22,"n":"第二十二条","txt":"审计机关对国有企业、国有金融机构和国有资本占控股地位或者主导地位的企业、金融机构的资产、负债、损益以及其他财务收支情况，进行审计监督。"},{"i":23,"n":"第二十三条","txt":"审计机关对政府投资和以政府投资为主的建设项目的预算执行情况和决算，对其他关系国家利益和公共利益的重大公共工程项目的资金管理使用和建设运营情况，进行审计监督。"},{"i":24,"n":"第二十四条","txt":"审计机关对国有资源、国有资产，进行审计监督。"},{"i":25,"n":"第二十五条","txt":"审计机关对国际组织和外国政府援助、贷款项目的财务收支，进行审计监督。"},{"i":26,"n":"第二十六条","txt":"根据经批准的审计项目计划安排，审计机关可以对被审计单位贯彻落实国家重大经济社会政策措施情况进行审计监督。"},{"i":27,"n":"第二十七条","txt":"除本法规定的审计事项外，审计机关对其他法律、行政法规规定应当由审计机关进行审计的事项，依照本法和有关法律、行政法规的规定进行审计监督。"},{"i":28,"n":"第二十八条","txt":"审计机关可以对被审计单位依法应当接受审计的事项进行全面审计，也可以对其中的特定事项进行专项审计。"},{"i":29,"n":"第二十九条","txt":"审计机关有权对与国家财政收支有关的特定事项，向有关地方、部门、单位进行专项审计调查，并向本级人民政府和上一级审计机关报告审计调查结果。"},{"i":30,"n":"第三十条","txt":"审计机关履行审计监督职责，发现经济社会运行中存在风险隐患的，应当及时向本级人民政府报告或者向有关主管机关、单位通报。"},{"i":31,"n":"第三十一条","txt":"审计机关根据被审计单位的财政、财务隶属关系或者国有资源、国有资产监督管理关系，确定审计管辖范围。"},{"i":32,"n":"第三十二条","txt":"被审计单位应当加强对内部审计工作的领导，按照国家有关规定建立健全内部审计制度。"},{"i":33,"n":"第三十三条","txt":"社会审计机构审计的单位依法属于被审计单位的，审计机关按照国务院的规定，有权对该社会审计机构出具的相关审计报告进行核查。"},{"i":34,"n":"第三十四条","txt":"审计机关有权要求被审计单位按照审计机关的规定提供财务、会计资料以及与财政收支、财务收支有关的业务、管理等资料，包括电子数据和有关文档。被审计单位不得拒绝、拖延、谎报。"},{"i":35,"n":"第三十五条","txt":"国家政务信息系统和数据共享平台应当按照规定向审计机关开放。"},{"i":36,"n":"第三十六条","txt":"审计机关进行审计时，有权检查被审计单位的财务、会计资料以及与财政收支、财务收支有关的业务、管理等资料和资产，有权检查被审计单位信息系统的安全性、可靠性、经济性，被审计单位不得拒绝。"},{"i":37,"n":"第三十七条","txt":"审计机关进行审计时，有权就审计事项的有关问题向有关单位和个人进行调查，并取得有关证明材料。有关单位和个人应当支持、协助审计机关工作，如实向审计机关反映情况，提供有关证明材料。"},{"i":38,"n":"第三十八条","txt":"审计机关进行审计时，被审计单位不得转移、隐匿、篡改、毁弃财务、会计资料以及与财政收支、财务收支有关的业务、管理等资料，不得转移、隐匿、故意毁损所持有的违反国家规定取得的资产。"},{"i":39,"n":"第三十九条","txt":"审计机关认为被审计单位所执行的上级主管机关、单位有关财政收支、财务收支的规定与法律、行政法规相抵触的，应当建议有关主管机关、单位纠正；有关主管机关、单位不予纠正的，审计机关应当提请有权处理的机关、单位依法处理。"},{"i":40,"n":"第四十条","txt":"审计机关可以向政府有关部门通报或者向社会公布审计结果。"},{"i":41,"n":"第四十一条","txt":"审计机关履行审计监督职责，可以提请公安、财政、自然资源、生态环境、海关、税务、市场监督管理等机关予以协助。有关机关应当依法予以配合。"},{"i":42,"n":"第四十二条","txt":"审计机关根据经批准的审计项目计划确定的审计事项组成审计组，并应当在实施审计三日前，向被审计单位送达审计通知书；遇有特殊情况，经县级以上人民政府审计机关负责人批准，可以直接持审计通知书实施审计。"},{"i":43,"n":"第四十三条","txt":"审计人员通过审查财务、会计资料，查阅与审计事项有关的文件、资料，检查现金、实物、有价证券和信息系统，向有关单位和个人调查等方式进行审计，并取得证明材料。"},{"i":44,"n":"第四十四条","txt":"审计组对审计事项实施审计后，应当向审计机关提出审计组的审计报告。审计组的审计报告报送审计机关前，应当征求被审计单位的意见。被审计单位应当自接到审计组的审计报告之日起十日内，将其书面意见送交审计组。审计组应当将被审计单位的书面意见一并报送审计机关。"},{"i":45,"n":"第四十五条","txt":"审计机关按照审计署规定的程序对审计组的审计报告进行审议，并对被审计单位对审计组的审计报告提出的意见一并研究后，出具审计机关的审计报告。对违反国家规定的财政收支、财务收支行为，依法应当给予处理、处罚的，审计机关在法定职权范围内作出审计决定；需要移送有关主管机关、单位处理、处罚的，审计机关应当依法移送。"},{"i":46,"n":"第四十六条","txt":"上级审计机关认为下级审计机关作出的审计决定违反国家有关规定的，可以责成下级审计机关予以变更或者撤销，必要时也可以直接作出变更或者撤销的决定。"},{"i":47,"n":"第四十七条","txt":"被审计单位违反本法规定，拒绝、拖延提供与审计事项有关的资料的，或者提供的资料不真实、不完整的，或者拒绝、阻碍检查、调查、核实有关情况的，由审计机关责令改正，可以通报批评，给予警告；拒不改正的，依法追究法律责任。"},{"i":48,"n":"第四十八条","txt":"被审计单位违反本法规定，转移、隐匿、篡改、毁弃财务、会计资料以及与财政收支、财务收支有关的业务、管理等资料，或者转移、隐匿、故意毁损所持有的违反国家规定取得的资产，审计机关认为对直接负责的主管人员和其他直接责任人员依法应当给予处分的，应当向被审计单位提出处理建议，或者移送监察机关和有关主管机关、单位处理，有关机关、单位应当将处理结果书面告知审计机关；构成犯罪的，依法追究刑事责任。"},{"i":49,"n":"第四十九条","txt":"对本级各部门（含直属单位）和下级政府违反预算的行为或者其他违反国家规定的财政收支行为，审计机关、人民政府或者有关主管机关、单位在法定职权范围内，依照法律、行政法规的规定，区别情况采取下列处理措施："},{"i":50,"n":"第五十条","txt":"对被审计单位违反国家规定的财务收支行为，审计机关、人民政府或者有关主管机关、单位在法定职权范围内，依照法律、行政法规的规定，区别情况采取前条规定的处理措施，并可以依法给予处罚。"},{"i":51,"n":"第五十一条","txt":"审计机关在法定职权范围内作出的审计决定，被审计单位应当执行。"},{"i":52,"n":"第五十二条","txt":"被审计单位应当按照规定时间整改审计查出的问题，将整改情况报告审计机关，同时向本级人民政府或者有关主管机关、单位报告，并按照规定向社会公布。"},{"i":53,"n":"第五十三条","txt":"被审计单位对审计机关作出的有关财务收支的审计决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":54,"n":"第五十四条","txt":"被审计单位的财政收支、财务收支违反国家规定，审计机关认为对直接负责的主管人员和其他直接责任人员依法应当给予处分的，应当向被审计单位提出处理建议，或者移送监察机关和有关主管机关、单位处理，有关机关、单位应当将处理结果书面告知审计机关。"},{"i":55,"n":"第五十五条","txt":"被审计单位的财政收支、财务收支违反法律、行政法规的规定，构成犯罪的，依法追究刑事责任。"},{"i":56,"n":"第五十六条","txt":"报复陷害审计人员的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":57,"n":"第五十七条","txt":"审计人员滥用职权、徇私舞弊、玩忽职守或者泄露、向他人非法提供所知悉的国家秘密、工作秘密、商业秘密、个人隐私和个人信息的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":58,"n":"第五十八条","txt":"领导干部经济责任审计和自然资源资产离任审计，依照本法和国家有关规定执行。"},{"i":59,"n":"第五十九条","txt":"中国人民解放军和中国人民武装警察部队审计工作的规定，由中央军事委员会根据本法制定。"},{"i":60,"n":"第六十条","txt":"本法自1995年1月1日起施行。1988年11月30日国务院发布的《中华人民共和国审计条例》同时废止。"}],"duiwaimaoyifa":[{"i":1,"n":"第一条","txt":"为了推进高水平对外开放，推动对外贸易高质量发展，维护对外贸易秩序，保护对外贸易经营者合法权益，促进社会主义市场经济健康发展，维护国家主权、安全、发展利益，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法适用于对外贸易以及与对外贸易有关的知识产权保护。"},{"i":3,"n":"第三条","txt":"对外贸易工作应当坚持服务国家经济社会发展，推进贸易强国建设。"},{"i":4,"n":"第四条","txt":"国务院对外贸易主管部门依照本法主管全国对外贸易工作。"},{"i":5,"n":"第五条","txt":"国家实行统一的对外贸易制度，鼓励发展对外贸易，维护公平、自由的对外贸易秩序。"},{"i":6,"n":"第六条","txt":"国家主动对接国际高标准经济贸易规则，积极参与国际经济贸易规则制定，维护多边贸易体制和公平公正的国际经济贸易秩序，扩大高标准自由贸易区网络，优化开放合作环境，推动建设开放型世界经济。"},{"i":7,"n":"第七条","txt":"国家建立同国际通行规则衔接的贸易政策合规机制。"},{"i":8,"n":"第八条","txt":"中华人民共和国根据平等互利的原则，促进和发展同其他国家和地区的贸易关系，缔结或者参加关税同盟协定、自由贸易区协定等区域经济贸易协定，参加区域经济组织。"},{"i":9,"n":"第九条","txt":"中华人民共和国在对外贸易方面根据所缔结或者参加的国际条约、协定，给予其他缔约方、参加方最惠国待遇、国民待遇等待遇，或者根据互惠、对等原则给予对方最惠国待遇、国民待遇等待遇。"},{"i":10,"n":"第十条","txt":"任何国家或者地区在贸易方面对中华人民共和国采取歧视性的禁止、限制或者其他类似措施的，中华人民共和国可以根据实际情况对该国家或者该地区采取相应的措施。"},{"i":11,"n":"第十一条","txt":"本法所称对外贸易经营者，是指依法办理经营主体登记或者其他执业手续，依照本法和其他有关法律、行政法规的规定从事对外贸易活动的个人、组织。"},{"i":12,"n":"第十二条","txt":"从事对外劳务合作，应当依法取得对外劳务合作经营资格。具体办法由国务院规定。"},{"i":13,"n":"第十三条","txt":"国家可以对部分货物的进出口实行国营贸易管理。实行国营贸易管理货物的进出口业务只能由经授权的企业经营；但是，国家允许部分数量的国营贸易管理货物的进出口业务由非授权企业经营的除外。"},{"i":14,"n":"第十四条","txt":"对外贸易经营者可以接受他人的委托，在经营范围内代为办理对外贸易业务。"},{"i":15,"n":"第十五条","txt":"对外贸易经营者应当按照国务院对外贸易主管部门或者国务院其他有关部门依法作出的规定，向有关部门提交与其对外贸易经营活动有关的文件及资料。有关部门应当为提供者保守商业秘密。"},{"i":16,"n":"第十六条","txt":"国家准许货物与技术的自由进出口。但是，法律、行政法规另有规定的除外。"},{"i":17,"n":"第十七条","txt":"国务院对外贸易主管部门基于监测进出口情况的需要，可以对部分自由进出口的货物实行进出口自动许可并发布其目录。"},{"i":18,"n":"第十八条","txt":"国家基于下列原因，可以禁止或者限制有关货物、技术进出口，或者采取其他必要的措施："},{"i":19,"n":"第十九条","txt":"国家对与裂变、聚变物质或者衍生此类物质的物质有关的货物、技术进出口，以及与武器、弹药或者其他军用物资有关的进出口，可以采取任何必要的措施维护国家安全。"},{"i":20,"n":"第二十条","txt":"国务院对外贸易主管部门会同国务院其他有关部门，依照本法第十八条和第十九条的规定，制定、调整并发布禁止或者限制进出口的货物、技术目录。"},{"i":21,"n":"第二十一条","txt":"国家对限制进出口的货物，实行配额、许可证等方式管理；对限制进出口的技术，实行许可证管理。"},{"i":22,"n":"第二十二条","txt":"进出口货物配额、关税配额，由国务院对外贸易主管部门或者国务院其他有关部门在各自的职责范围内，按照公开、公平、公正和效益的原则进行分配。具体办法由国务院规定。"},{"i":23,"n":"第二十三条","txt":"对外贸易经营者可以依法开展加工贸易，进口全部或者部分料件，经加工、装配或者维修后将制成品复出口。"},{"i":24,"n":"第二十四条","txt":"国家实行统一的商品合格评定制度，进出口商品的认证、检验、检疫依照有关法律、行政法规的规定进行。"},{"i":25,"n":"第二十五条","txt":"国家对进出口货物进行原产地管理。进出口货物原产地的具体确定，依照有关法律和国务院及其有关部门的规定执行。"},{"i":26,"n":"第二十六条","txt":"对文物和野生动物、植物及其制品等，其他法律、行政法规有禁止或者限制进出口规定的，依照有关法律、行政法规的规定执行。"},{"i":27,"n":"第二十七条","txt":"国家鼓励以跨境交付、境外消费、商业存在、自然人移动等各种模式开展国际服务贸易。"},{"i":28,"n":"第二十八条","txt":"国务院对外贸易主管部门和国务院其他有关部门，依照本法和其他有关法律、行政法规的规定，对国际服务贸易进行管理。"},{"i":29,"n":"第二十九条","txt":"国家基于下列原因，可以禁止或者限制有关的国际服务贸易，或者采取其他必要的措施："},{"i":30,"n":"第三十条","txt":"国家对与军事有关的国际服务贸易，以及与裂变、聚变物质或者衍生此类物质的物质有关的国际服务贸易，可以采取任何必要的措施维护国家安全。"},{"i":31,"n":"第三十一条","txt":"国家对境外服务提供者以跨境交付、境外消费、自然人移动模式开展国际服务贸易（以下统称跨境服务贸易）实行跨境服务贸易负面清单管理制度。"},{"i":32,"n":"第三十二条","txt":"国家加强与对外贸易有关的知识产权保护，依照有关知识产权的法律、行政法规，保护与对外贸易有关的知识产权。"},{"i":33,"n":"第三十三条","txt":"国家开展与对外贸易有关的知识产权国际交流合作，积极推进与对外贸易有关的知识产权对外谈判，建立健全海外知识产权预警和维权援助信息平台，提升对外贸易经营者知识产权合规水平和风险应对能力。"},{"i":34,"n":"第三十四条","txt":"知识产权权利人有阻止被许可人对许可合同中的知识产权的有效性提出质疑、进行强制性一揽子许可、在许可合同中规定排他性返授条件等行为，并危害对外贸易公平竞争秩序的，国务院对外贸易主管部门可以采取必要的措施消除危害。"},{"i":35,"n":"第三十五条","txt":"其他国家或者地区在知识产权保护方面未给予中华人民共和国的个人、组织国民待遇，或者不能对来源于中华人民共和国的货物、技术或者服务提供充分有效的知识产权保护的，国务院对外贸易主管部门可以依照本法和其他有关法律、行政法规的规定，并根据中华人民共和国缔结或者参加的国际条约、协定，对与该国家或者该地区的对外贸易采取必要的措施。"},{"i":36,"n":"第三十六条","txt":"在对外贸易活动中，不得违反有关反垄断、反不正当竞争法律、行政法规的规定实施垄断或者不正当竞争行为。"},{"i":37,"n":"第三十七条","txt":"在对外贸易活动中，不得有下列行为："},{"i":38,"n":"第三十八条","txt":"对外贸易经营者在对外贸易活动中，应当遵守海关监督管理、外汇管理、数据安全保护等有关规定。"},{"i":39,"n":"第三十九条","txt":"违反本法规定，危害对外贸易秩序的，国务院对外贸易主管部门可以向社会公告，并采取必要的措施消除危害。"},{"i":40,"n":"第四十条","txt":"国务院对外贸易主管部门可以对有下列情形之一的境外个人、组织，采取禁止或者限制其与中华人民共和国有关的货物、技术进出口以及国际服务贸易等措施："},{"i":41,"n":"第四十一条","txt":"为了维护对外贸易秩序，国务院对外贸易主管部门可以自行或者会同国务院其他有关部门，依照法律、行政法规的规定对下列事项进行调查："},{"i":42,"n":"第四十二条","txt":"启动对外贸易调查，由国务院对外贸易主管部门发布公告。"},{"i":43,"n":"第四十三条","txt":"有关个人、组织应当对对外贸易调查给予配合、协助。"},{"i":44,"n":"第四十四条","txt":"国家根据对外贸易调查结果，可以采取适当的对外贸易救济措施。"},{"i":45,"n":"第四十五条","txt":"其他国家或者地区的产品以低于正常价值的倾销方式进入我国市场，对已建立的国内产业造成实质损害或者产生实质损害威胁，或者对建立国内产业造成实质阻碍的，国家可以采取反倾销措施，消除或者减轻这种损害或者损害的威胁或者阻碍。"},{"i":46,"n":"第四十六条","txt":"其他国家或者地区的产品以低于正常价值出口至第三国市场，对我国已建立的国内产业造成实质损害或者产生实质损害威胁，或者对我国建立国内产业造成实质阻碍的，应国内产业的申请，国务院对外贸易主管部门可以与该第三国政府进行磋商，要求其采取适当的措施。"},{"i":47,"n":"第四十七条","txt":"进口的产品直接或者间接地接受出口国家或者地区给予的任何形式的专向性补贴，对已建立的国内产业造成实质损害或者产生实质损害威胁，或者对建立国内产业造成实质阻碍的，国家可以采取反补贴措施，消除或者减轻这种损害或者损害的威胁或者阻碍。"},{"i":48,"n":"第四十八条","txt":"因进口产品数量大量增加，对生产同类产品或者与其直接竞争的产品的国内产业造成严重损害或者严重损害威胁的，国家可以采取必要的保障措施，消除或者减轻这种损害或者损害的威胁，并可以对该产业提供必要的支持。"},{"i":49,"n":"第四十九条","txt":"因其他国家或者地区的服务提供者向我国提供的服务增加，对提供同类服务或者与其直接竞争的服务的国内产业造成损害或者产生损害威胁的，国家可以采取必要的救济措施，消除或者减轻这种损害或者损害的威胁。"},{"i":50,"n":"第五十条","txt":"因第三国限制进口而导致某种产品进入我国市场的数量大量增加，对已建立的国内产业造成损害或者产生损害威胁，或者对建立国内产业造成阻碍的，国家可以采取必要的救济措施，限制该产品进口。"},{"i":51,"n":"第五十一条","txt":"与中华人民共和国缔结或者共同参加经济贸易条约、协定的国家或者地区，违反条约、协定的规定，使中华人民共和国根据该条约、协定享有的利益丧失或者受损，或者阻碍条约、协定目标实现的，中华人民共和国政府有权要求有关国家或者地区政府终止上述行为、采取适当的补救措施，并可以根据有关条约、协定中止或者终止履行相关义务。"},{"i":52,"n":"第五十二条","txt":"国务院对外贸易主管部门依照本法和其他有关法律的规定，进行对外贸易的双边或者多边磋商、谈判和争端的解决工作。"},{"i":53,"n":"第五十三条","txt":"国务院对外贸易主管部门和国务院其他有关部门应当建立健全货物进出口、技术进出口和国际服务贸易的预警应急机制，应对对外贸易中的突发和异常情况，维护国家经济安全。"},{"i":54,"n":"第五十四条","txt":"国家对规避本法规定的对外贸易救济措施的行为，可以采取调整本法第四十五条至第五十一条规定的对外贸易救济措施等必要的反规避措施。"},{"i":55,"n":"第五十五条","txt":"为应对贸易风险和贸易环境变化的影响，有关人民政府可以根据需要建立符合世界贸易组织规则等的贸易调整援助制度，积极开展贸易调整援助工作，稳定产业链、供应链。"},{"i":56,"n":"第五十六条","txt":"国家制定对外贸易发展战略，推动对外贸易平衡发展，建立和完善对外贸易促进机制，强化贸易政策与财税、金融、产业等政策协同一致。"},{"i":57,"n":"第五十七条","txt":"国家根据对外贸易发展的需要，建立和完善为对外贸易服务的金融机构，完善保险保障措施，促进跨境金融服务体系建设。"},{"i":58,"n":"第五十八条","txt":"国家通过进出口信贷、出口信用保险、出口退税以及其他促进对外贸易的方式，发展对外贸易。"},{"i":59,"n":"第五十九条","txt":"国家支持和促进跨境电子商务、对外贸易综合服务等对外贸易业态和模式创新发展。国务院对外贸易主管部门应当会同国务院其他有关部门建立健全适应对外贸易新业态、新模式发展需要的政策措施和管理制度。"},{"i":60,"n":"第六十条","txt":"国家支持对外贸易数字化发展，推动和加强信息技术手段在对外贸易活动中的应用，支持电子提单、电子发票等的使用，推动数字证书、电子签名等国际互认，提升对外贸易数字化、便利化水平。"},{"i":61,"n":"第六十一条","txt":"国家加快建立绿色贸易体系，鼓励绿色低碳产品进出口，推动与绿色贸易有关的产品标准、认证、标识体系建设，加强绿色贸易国际合作。"},{"i":62,"n":"第六十二条","txt":"国家建立对外贸易公共信息服务体系，向对外贸易经营者和其他社会公众提供信息服务。"},{"i":63,"n":"第六十三条","txt":"国家鼓励对外贸易经营者开拓国际市场，指导和帮助对外贸易经营者防范和应对风险，采取对外投资、对外劳务合作和对外承包工程等多种形式，发展对外贸易。"},{"i":64,"n":"第六十四条","txt":"国家支持贸易促进平台提升功能和服务水平，以境内外展会、线上贸易平台等方式帮助对外贸易经营者开展对外贸易。"},{"i":65,"n":"第六十五条","txt":"对外贸易经营者可以依法成立和参加有关协会、商会。"},{"i":66,"n":"第六十六条","txt":"国家建立健全对外贸易纠纷多元化解决机制，为对外贸易经营者通过调解、仲裁、诉讼等方式解决纠纷提供公正、高效、便捷的途径。"},{"i":67,"n":"第六十七条","txt":"中国国际贸易促进组织按照章程开展对外联系，举办展览，提供信息、咨询服务和其他对外贸易促进活动。"},{"i":68,"n":"第六十八条","txt":"国家扶持和促进中小微企业开展对外贸易，在监管、融资、外汇结算等方面提供便利。"},{"i":69,"n":"第六十九条","txt":"国家扶持和促进民族自治地方和经济欠发达地区发展对外贸易。"},{"i":70,"n":"第七十条","txt":"国家支持和促进对外贸易人才队伍建设，培养适应对外贸易发展需要的各类人才，为对外贸易高质量发展提供人才支撑。"},{"i":71,"n":"第七十一条","txt":"违反本法第十三条规定，未经授权擅自进出口实行国营贸易管理的货物的，国务院对外贸易主管部门或者国务院其他有关部门可以处五十万元以下罚款；情节严重的，可以自行政处罚决定生效之日起三年内，不受理违法行为人从事国营贸易管理货物进出口业务的申请，或者撤销已给予其从事其他国营贸易管理货物进出口的授权。"},{"i":72,"n":"第七十二条","txt":"违反本法第十七条第三款规定，进出口属于自由进出口的技术未办理合同备案登记的，由国务院对外贸易主管部门责令改正，给予警告；拒不改正的，处五万元以下罚款。"},{"i":73,"n":"第七十三条","txt":"进出口属于禁止进出口的货物的，或者未经许可擅自进出口属于限制进出口的货物的，由海关依照有关法律、行政法规的规定处理、处罚；构成犯罪的，依法追究刑事责任。"},{"i":74,"n":"第七十四条","txt":"从事属于禁止的国际服务贸易的，或者未经许可擅自从事属于限制的国际服务贸易的，或者未执行本法第二十九条、第三十条规定的必要措施的，依照有关法律、行政法规的规定处理、处罚；法律、行政法规没有规定的，由国务院对外贸易主管部门责令改正，没收违法所得，违法所得五十万元以上的，处违法所得一倍以上五倍以下罚款，没有违法所得或者违法所得不足五十万元的，处五十万元以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":75,"n":"第七十五条","txt":"违反本法第三十七条规定，依照有关法律、行政法规的规定处罚；构成犯罪的，依法追究刑事责任。"},{"i":76,"n":"第七十六条","txt":"违反本法第四十条规定，与相关境外个人、组织进行对外贸易活动或者提供代理、货运、寄递、报关、仓储、第三方交易平台服务等支持、协助、便利的，依照有关法律、行政法规、部门规章的规定处理、处罚；法律、行政法规、部门规章没有规定的，由国务院对外贸易主管部门责令改正，没收违法所得，违法所得五十万元以上的，处违法所得一倍以上五倍以下罚款，没有违法所得或者违法所得不足五十万元的，处五十万元以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":77,"n":"第七十七条","txt":"依照本法第四十条第一款、第七十三条至第七十六条规定被禁止从事有关对外贸易活动的，在禁止期限内，海关根据有关禁止决定不予办理有关进出口货物报关验放手续，中国人民银行、外汇管理部门、金融机构根据有关禁止决定不予办理有关结汇、售汇手续和收汇、付汇、跨境人民币结算等资金收付手续。"},{"i":78,"n":"第七十八条","txt":"依照本法负责对外贸易管理工作的部门的工作人员滥用职权、玩忽职守、徇私舞弊或者泄露、非法向他人提供所知悉的国家秘密、工作秘密、商业秘密、个人隐私和个人信息的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":79,"n":"第七十九条","txt":"对外贸易活动当事人对依照本法负责对外贸易管理工作的部门作出的行政行为不服的，可以依法申请行政复议或者向人民法院提起行政诉讼。"},{"i":80,"n":"第八十条","txt":"与两用物项、军品、裂变和聚变物质或者衍生此类物质的物质以及其他与维护国家安全和利益、履行防扩散等国际义务相关的货物、技术、服务等物项有关的对外贸易管理，以及文化产品的进出口管理，法律、行政法规另有规定的，依照其规定。"},{"i":81,"n":"第八十一条","txt":"国家对边境地区与接壤国家边境地区之间的贸易以及边民互市贸易，采取灵活措施，给予优惠和便利。具体办法由国务院或者国务院授权的有关部门规定。"},{"i":82,"n":"第八十二条","txt":"中华人民共和国的单独关税区不适用本法。"},{"i":83,"n":"第八十三条","txt":"本法自2026年3月1日起施行。"}],"guanggaofa":[{"i":1,"n":"第一条","txt":"为了规范广告活动，保护消费者的合法权益，促进广告业的健康发展，维护社会经济秩序，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内，商品经营者或者服务提供者通过一定媒介和形式直接或者间接地介绍自己所推销的商品或者服务的商业广告活动，适用本法。"},{"i":3,"n":"第三条","txt":"广告应当真实、合法，以健康的表现形式表达广告内容，符合社会主义精神文明建设和弘扬中华民族优秀传统文化的要求。"},{"i":4,"n":"第四条","txt":"广告不得含有虚假或者引人误解的内容，不得欺骗、误导消费者。"},{"i":5,"n":"第五条","txt":"广告主、广告经营者、广告发布者从事广告活动，应当遵守法律、法规，诚实信用，公平竞争。"},{"i":6,"n":"第六条","txt":"国务院市场监督管理部门主管全国的广告监督管理工作，国务院有关部门在各自的职责范围内负责广告管理相关工作。"},{"i":7,"n":"第七条","txt":"广告行业组织依照法律、法规和章程的规定，制定行业规范，加强行业自律，促进行业发展，引导会员依法从事广告活动，推动广告行业诚信建设。"},{"i":8,"n":"第八条","txt":"广告中对商品的性能、功能、产地、用途、质量、成分、价格、生产者、有效期限、允诺等或者对服务的内容、提供者、形式、质量、价格、允诺等有表示的，应当准确、清楚、明白。"},{"i":9,"n":"第九条","txt":"广告不得有下列情形："},{"i":10,"n":"第十条","txt":"广告不得损害未成年人和残疾人的身心健康。"},{"i":11,"n":"第十一条","txt":"广告内容涉及的事项需要取得行政许可的，应当与许可的内容相符合。"},{"i":12,"n":"第十二条","txt":"广告中涉及专利产品或者专利方法的，应当标明专利号和专利种类。"},{"i":13,"n":"第十三条","txt":"广告不得贬低其他生产经营者的商品或者服务。"},{"i":14,"n":"第十四条","txt":"广告应当具有可识别性，能够使消费者辨明其为广告。"},{"i":15,"n":"第十五条","txt":"麻醉药品、精神药品、医疗用毒性药品、放射性药品等特殊药品，药品类易制毒化学品，以及戒毒治疗的药品、医疗器械和治疗方法，不得作广告。"},{"i":16,"n":"第十六条","txt":"医疗、药品、医疗器械广告不得含有下列内容："},{"i":17,"n":"第十七条","txt":"除医疗、药品、医疗器械广告外，禁止其他任何广告涉及疾病治疗功能，并不得使用医疗用语或者易使推销的商品与药品、医疗器械相混淆的用语。"},{"i":18,"n":"第十八条","txt":"保健食品广告不得含有下列内容："},{"i":19,"n":"第十九条","txt":"广播电台、电视台、报刊音像出版单位、互联网信息服务提供者不得以介绍健康、养生知识等形式变相发布医疗、药品、医疗器械、保健食品广告。"},{"i":20,"n":"第二十条","txt":"禁止在大众传播媒介或者公共场所发布声称全部或者部分替代母乳的婴儿乳制品、饮料和其他食品广告。"},{"i":21,"n":"第二十一条","txt":"农药、兽药、饲料和饲料添加剂广告不得含有下列内容："},{"i":22,"n":"第二十二条","txt":"禁止在大众传播媒介或者公共场所、公共交通工具、户外发布烟草广告。禁止向未成年人发送任何形式的烟草广告。"},{"i":23,"n":"第二十三条","txt":"酒类广告不得含有下列内容："},{"i":24,"n":"第二十四条","txt":"教育、培训广告不得含有下列内容："},{"i":25,"n":"第二十五条","txt":"招商等有投资回报预期的商品或者服务广告，应当对可能存在的风险以及风险责任承担有合理提示或者警示，并不得含有下列内容："},{"i":26,"n":"第二十六条","txt":"房地产广告，房源信息应当真实，面积应当表明为建筑面积或者套内建筑面积，并不得含有下列内容："},{"i":27,"n":"第二十七条","txt":"农作物种子、林木种子、草种子、种畜禽、水产苗种和种养殖广告关于品种名称、生产性能、生长量或者产量、品质、抗性、特殊使用价值、经济价值、适宜种植或者养殖的范围和条件等方面的表述应当真实、清楚、明白，并不得含有下列内容："},{"i":28,"n":"第二十八条","txt":"广告以虚假或者引人误解的内容欺骗、误导消费者的，构成虚假广告。"},{"i":29,"n":"第二十九条","txt":"广播电台、电视台、报刊出版单位从事广告发布业务的，应当设有专门从事广告业务的机构，配备必要的人员，具有与发布广告相适应的场所、设备。"},{"i":30,"n":"第三十条","txt":"广告主、广告经营者、广告发布者之间在广告活动中应当依法订立书面合同。"},{"i":31,"n":"第三十一条","txt":"广告主、广告经营者、广告发布者不得在广告活动中进行任何形式的不正当竞争。"},{"i":32,"n":"第三十二条","txt":"广告主委托设计、制作、发布广告，应当委托具有合法经营资格的广告经营者、广告发布者。"},{"i":33,"n":"第三十三条","txt":"广告主或者广告经营者在广告中使用他人名义或者形象的，应当事先取得其书面同意；使用无民事行为能力人、限制民事行为能力人的名义或者形象的，应当事先取得其监护人的书面同意。"},{"i":34,"n":"第三十四条","txt":"广告经营者、广告发布者应当按照国家有关规定，建立、健全广告业务的承接登记、审核、档案管理制度。"},{"i":35,"n":"第三十五条","txt":"广告经营者、广告发布者应当公布其收费标准和收费办法。"},{"i":36,"n":"第三十六条","txt":"广告发布者向广告主、广告经营者提供的覆盖率、收视率、点击率、发行量等资料应当真实。"},{"i":37,"n":"第三十七条","txt":"法律、行政法规规定禁止生产、销售的产品或者提供的服务，以及禁止发布广告的商品或者服务，任何单位或者个人不得设计、制作、代理、发布广告。"},{"i":38,"n":"第三十八条","txt":"广告代言人在广告中对商品、服务作推荐、证明，应当依据事实，符合本法和有关法律、行政法规规定，并不得为其未使用过的商品或者未接受过的服务作推荐、证明。"},{"i":39,"n":"第三十九条","txt":"不得在中小学校、幼儿园内开展广告活动，不得利用中小学生和幼儿的教材、教辅材料、练习册、文具、教具、校服、校车等发布或者变相发布广告，但公益广告除外。"},{"i":40,"n":"第四十条","txt":"在针对未成年人的大众传播媒介上不得发布医疗、药品、保健食品、医疗器械、化妆品、酒类、美容广告，以及不利于未成年人身心健康的网络游戏广告。"},{"i":41,"n":"第四十一条","txt":"县级以上地方人民政府应当组织有关部门加强对利用户外场所、空间、设施等发布户外广告的监督管理，制定户外广告设置规划和安全要求。"},{"i":42,"n":"第四十二条","txt":"有下列情形之一的，不得设置户外广告："},{"i":43,"n":"第四十三条","txt":"任何单位或者个人未经当事人同意或者请求，不得向其住宅、交通工具等发送广告，也不得以电子信息方式向其发送广告。"},{"i":44,"n":"第四十四条","txt":"利用互联网从事广告活动，适用本法的各项规定。"},{"i":45,"n":"第四十五条","txt":"公共场所的管理者或者电信业务经营者、互联网信息服务提供者对其明知或者应知的利用其场所或者信息传输、发布平台发送、发布违法广告的，应当予以制止。"},{"i":46,"n":"第四十六条","txt":"发布医疗、药品、医疗器械、农药、兽药和保健食品广告，以及法律、行政法规规定应当进行审查的其他广告，应当在发布前由有关部门（以下称广告审查机关）对广告内容进行审查；未经审查，不得发布。"},{"i":47,"n":"第四十七条","txt":"广告主申请广告审查，应当依照法律、行政法规向广告审查机关提交有关证明文件。"},{"i":48,"n":"第四十八条","txt":"任何单位或者个人不得伪造、变造或者转让广告审查批准文件。"},{"i":49,"n":"第四十九条","txt":"市场监督管理部门履行广告监督管理职责，可以行使下列职权："},{"i":50,"n":"第五十条","txt":"国务院市场监督管理部门会同国务院有关部门，制定大众传播媒介广告发布行为规范。"},{"i":51,"n":"第五十一条","txt":"市场监督管理部门依照本法规定行使职权，当事人应当协助、配合，不得拒绝、阻挠。"},{"i":52,"n":"第五十二条","txt":"市场监督管理部门和有关部门及其工作人员对其在广告监督管理活动中知悉的商业秘密负有保密义务。"},{"i":53,"n":"第五十三条","txt":"任何单位或者个人有权向市场监督管理部门和有关部门投诉、举报违反本法的行为。市场监督管理部门和有关部门应当向社会公开受理投诉、举报的电话、信箱或者电子邮件地址，接到投诉、举报的部门应当自收到投诉之日起七个工作日内，予以处理并告知投诉、举报人。"},{"i":54,"n":"第五十四条","txt":"消费者协会和其他消费者组织对违反本法规定，发布虚假广告侵害消费者合法权益，以及其他损害社会公共利益的行为，依法进行社会监督。"},{"i":55,"n":"第五十五条","txt":"违反本法规定，发布虚假广告的，由市场监督管理部门责令停止发布广告，责令广告主在相应范围内消除影响，处广告费用三倍以上五倍以下的罚款，广告费用无法计算或者明显偏低的，处二十万元以上一百万元以下的罚款；两年内有三次以上违法行为或者有其他严重情节的，处广告费用五倍以上十倍以下的罚款，广告费用无法计算或者明显偏低的，处一百万元以上二百万元以下的罚款，可以吊销营业执照，并由广告审查机关撤销广告审查批准文件、一年内不受理其广告审查申请。"},{"i":56,"n":"第五十六条","txt":"违反本法规定，发布虚假广告，欺骗、误导消费者，使购买商品或者接受服务的消费者的合法权益受到损害的，由广告主依法承担民事责任。广告经营者、广告发布者不能提供广告主的真实名称、地址和有效联系方式的，消费者可以要求广告经营者、广告发布者先行赔偿。"},{"i":57,"n":"第五十七条","txt":"有下列行为之一的，由市场监督管理部门责令停止发布广告，对广告主处二十万元以上一百万元以下的罚款，情节严重的，并可以吊销营业执照，由广告审查机关撤销广告审查批准文件、一年内不受理其广告审查申请；对广告经营者、广告发布者，由市场监督管理部门没收广告费用，处二十万元以上一百万元以下的罚款，情节严重的，并可以吊销营业执照："},{"i":58,"n":"第五十八条","txt":"有下列行为之一的，由市场监督管理部门责令停止发布广告，责令广告主在相应范围内消除影响，处广告费用一倍以上三倍以下的罚款，广告费用无法计算或者明显偏低的，处十万元以上二十万元以下的罚款；情节严重的，处广告费用三倍以上五倍以下的罚款，广告费用无法计算或者明显偏低的，处二十万元以上一百万元以下的罚款，可以吊销营业执照，并由广告审查机关撤销广告审查批准文件、一年内不受理其广告审查申请："},{"i":59,"n":"第五十九条","txt":"有下列行为之一的，由市场监督管理部门责令停止发布广告，对广告主处十万元以下的罚款："},{"i":60,"n":"第六十条","txt":"违反本法第三十四条规定，广告经营者、广告发布者未按照国家有关规定建立、健全广告业务管理制度的，或者未对广告内容进行核对的，由市场监督管理部门责令改正，可以处五万元以下的罚款。"},{"i":61,"n":"第六十一条","txt":"广告代言人有下列情形之一的，由市场监督管理部门没收违法所得，并处违法所得一倍以上二倍以下的罚款："},{"i":62,"n":"第六十二条","txt":"违反本法第四十三条规定发送广告的，由有关部门责令停止违法行为，对广告主处五千元以上三万元以下的罚款。"},{"i":63,"n":"第六十三条","txt":"违反本法第四十五条规定，公共场所的管理者和电信业务经营者、互联网信息服务提供者，明知或者应知广告活动违法不予制止的，由市场监督管理部门没收违法所得，违法所得五万元以上的，并处违法所得一倍以上三倍以下的罚款，违法所得不足五万元的，并处一万元以上五万元以下的罚款；情节严重的，由有关部门依法停止相关业务。"},{"i":64,"n":"第六十四条","txt":"违反本法规定，隐瞒真实情况或者提供虚假材料申请广告审查的，广告审查机关不予受理或者不予批准，予以警告，一年内不受理该申请人的广告审查申请；以欺骗、贿赂等不正当手段取得广告审查批准的，广告审查机关予以撤销，处十万元以上二十万元以下的罚款，三年内不受理该申请人的广告审查申请。"},{"i":65,"n":"第六十五条","txt":"违反本法规定，伪造、变造或者转让广告审查批准文件的，由市场监督管理部门没收违法所得，并处一万元以上十万元以下的罚款。"},{"i":66,"n":"第六十六条","txt":"有本法规定的违法行为的，由市场监督管理部门记入信用档案，并依照有关法律、行政法规规定予以公示。"},{"i":67,"n":"第六十七条","txt":"广播电台、电视台、报刊音像出版单位发布违法广告，或者以新闻报道形式变相发布广告，或者以介绍健康、养生知识等形式变相发布医疗、药品、医疗器械、保健食品广告，市场监督管理部门依照本法给予处罚的，应当通报新闻出版、广播电视主管部门以及其他有关部门。新闻出版、广播电视主管部门以及其他有关部门应当依法对负有责任的主管人员和直接责任人员给予处分；情节严重的，并可以暂停媒体的广告发布业务。"},{"i":68,"n":"第六十八条","txt":"广告主、广告经营者、广告发布者违反本法规定，有下列侵权行为之一的，依法承担民事责任："},{"i":69,"n":"第六十九条","txt":"因发布虚假广告，或者有其他本法规定的违法行为，被吊销营业执照的公司、企业的法定代表人，对违法行为负有个人责任的，自该公司、企业被吊销营业执照之日起三年内不得担任公司、企业的董事、监事、高级管理人员。"},{"i":70,"n":"第七十条","txt":"违反本法规定，拒绝、阻挠市场监督管理部门监督检查，或者有其他构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":71,"n":"第七十一条","txt":"广告审查机关对违法的广告内容作出审查批准决定的，对负有责任的主管人员和直接责任人员，由任免机关或者监察机关依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":72,"n":"第七十二条","txt":"市场监督管理部门对在履行广告监测职责中发现的违法广告行为或者对经投诉、举报的违法广告行为，不依法予以查处的，对负有责任的主管人员和直接责任人员，依法给予处分。"},{"i":73,"n":"第七十三条","txt":"国家鼓励、支持开展公益广告宣传活动，传播社会主义核心价值观，倡导文明风尚。"},{"i":74,"n":"第七十四条","txt":"本法自2015年9月1日起施行。"}],"jianzhufa":[{"i":1,"n":"第一条","txt":"为了加强对建筑活动的监督管理，维护建筑市场秩序，保证建筑工程的质量和安全，促进建筑业健康发展，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事建筑活动，实施对建筑活动的监督管理，应当遵守本法。"},{"i":3,"n":"第三条","txt":"建筑活动应当确保建筑工程质量和安全，符合国家的建筑工程安全标准。"},{"i":4,"n":"第四条","txt":"国家扶持建筑业的发展，支持建筑科学技术研究，提高房屋建筑设计水平，鼓励节约能源和保护环境，提倡采用先进技术、先进设备、先进工艺、新型建筑材料和现代管理方式。"},{"i":5,"n":"第五条","txt":"从事建筑活动应当遵守法律、法规，不得损害社会公共利益和他人的合法权益。"},{"i":6,"n":"第六条","txt":"国务院建设行政主管部门对全国的建筑活动实施统一监督管理。"},{"i":7,"n":"第七条","txt":"建筑工程开工前，建设单位应当按照国家有关规定向工程所在地县级以上人民政府建设行政主管部门申请领取施工许可证；但是，国务院建设行政主管部门确定的限额以下的小型工程除外。"},{"i":8,"n":"第八条","txt":"申请领取施工许可证，应当具备下列条件："},{"i":9,"n":"第九条","txt":"建设单位应当自领取施工许可证之日起三个月内开工。因故不能按期开工的，应当向发证机关申请延期；延期以两次为限，每次不超过三个月。既不开工又不申请延期或者超过延期时限的，施工许可证自行废止。"},{"i":10,"n":"第十条","txt":"在建的建筑工程因故中止施工的，建设单位应当自中止施工之日起一个月内，向发证机关报告，并按照规定做好建筑工程的维护管理工作。"},{"i":11,"n":"第十一条","txt":"按照国务院有关规定批准开工报告的建筑工程，因故不能按期开工或者中止施工的，应当及时向批准机关报告情况。因故不能按期开工超过六个月的，应当重新办理开工报告的批准手续。"},{"i":12,"n":"第十二条","txt":"从事建筑活动的建筑施工企业、勘察单位、设计单位和工程监理单位，应当具备下列条件："},{"i":13,"n":"第十三条","txt":"从事建筑活动的建筑施工企业、勘察单位、设计单位和工程监理单位，按照其拥有的注册资本、专业技术人员、技术装备和已完成的建筑工程业绩等资质条件，划分为不同的资质等级，经资质审查合格，取得相应等级的资质证书后，方可在其资质等级许可的范围内从事建筑活动。"},{"i":14,"n":"第十四条","txt":"从事建筑活动的专业技术人员，应当依法取得相应的执业资格证书，并在执业资格证书许可的范围内从事建筑活动。"},{"i":15,"n":"第十五条","txt":"建筑工程的发包单位与承包单位应当依法订立书面合同，明确双方的权利和义务。"},{"i":16,"n":"第十六条","txt":"建筑工程发包与承包的招标投标活动，应当遵循公开、公正、平等竞争的原则，择优选择承包单位。"},{"i":17,"n":"第十七条","txt":"发包单位及其工作人员在建筑工程发包中不得收受贿赂、回扣或者索取其他好处。"},{"i":18,"n":"第十八条","txt":"建筑工程造价应当按照国家有关规定，由发包单位与承包单位在合同中约定。公开招标发包的，其造价的约定，须遵守招标投标法律的规定。"},{"i":19,"n":"第十九条","txt":"建筑工程依法实行招标发包，对不适于招标发包的可以直接发包。"},{"i":20,"n":"第二十条","txt":"建筑工程实行公开招标的，发包单位应当依照法定程序和方式，发布招标公告，提供载有招标工程的主要技术要求、主要的合同条款、评标的标准和方法以及开标、评标、定标的程序等内容的招标文件。"},{"i":21,"n":"第二十一条","txt":"建筑工程招标的开标、评标、定标由建设单位依法组织实施，并接受有关行政主管部门的监督。"},{"i":22,"n":"第二十二条","txt":"建筑工程实行招标发包的，发包单位应当将建筑工程发包给依法中标的承包单位。建筑工程实行直接发包的，发包单位应当将建筑工程发包给具有相应资质条件的承包单位。"},{"i":23,"n":"第二十三条","txt":"政府及其所属部门不得滥用行政权力，限定发包单位将招标发包的建筑工程发包给指定的承包单位。"},{"i":24,"n":"第二十四条","txt":"提倡对建筑工程实行总承包，禁止将建筑工程肢解发包。"},{"i":25,"n":"第二十五条","txt":"按照合同约定，建筑材料、建筑构配件和设备由工程承包单位采购的，发包单位不得指定承包单位购入用于工程的建筑材料、建筑构配件和设备或者指定生产厂、供应商。"},{"i":26,"n":"第二十六条","txt":"承包建筑工程的单位应当持有依法取得的资质证书，并在其资质等级许可的业务范围内承揽工程。"},{"i":27,"n":"第二十七条","txt":"大型建筑工程或者结构复杂的建筑工程，可以由两个以上的承包单位联合共同承包。共同承包的各方对承包合同的履行承担连带责任。"},{"i":28,"n":"第二十八条","txt":"禁止承包单位将其承包的全部建筑工程转包给他人，禁止承包单位将其承包的全部建筑工程肢解以后以分包的名义分别转包给他人。"},{"i":29,"n":"第二十九条","txt":"建筑工程总承包单位可以将承包工程中的部分工程发包给具有相应资质条件的分包单位；但是，除总承包合同中约定的分包外，必须经建设单位认可。施工总承包的，建筑工程主体结构的施工必须由总承包单位自行完成。"},{"i":30,"n":"第三十条","txt":"国家推行建筑工程监理制度。"},{"i":31,"n":"第三十一条","txt":"实行监理的建筑工程，由建设单位委托具有相应资质条件的工程监理单位监理。建设单位与其委托的工程监理单位应当订立书面委托监理合同。"},{"i":32,"n":"第三十二条","txt":"建筑工程监理应当依照法律、行政法规及有关的技术标准、设计文件和建筑工程承包合同，对承包单位在施工质量、建设工期和建设资金使用等方面，代表建设单位实施监督。"},{"i":33,"n":"第三十三条","txt":"实施建筑工程监理前，建设单位应当将委托的工程监理单位、监理的内容及监理权限，书面通知被监理的建筑施工企业。"},{"i":34,"n":"第三十四条","txt":"工程监理单位应当在其资质等级许可的监理范围内，承担工程监理业务。"},{"i":35,"n":"第三十五条","txt":"工程监理单位不按照委托监理合同的约定履行监理义务，对应当监督检查的项目不检查或者不按照规定检查，给建设单位造成损失的，应当承担相应的赔偿责任。"},{"i":36,"n":"第三十六条","txt":"建筑工程安全生产管理必须坚持安全第一、预防为主的方针，建立健全安全生产的责任制度和群防群治制度。"},{"i":37,"n":"第三十七条","txt":"建筑工程设计应当符合按照国家规定制定的建筑安全规程和技术规范，保证工程的安全性能。"},{"i":38,"n":"第三十八条","txt":"建筑施工企业在编制施工组织设计时，应当根据建筑工程的特点制定相应的安全技术措施；对专业性较强的工程项目，应当编制专项安全施工组织设计，并采取安全技术措施。"},{"i":39,"n":"第三十九条","txt":"建筑施工企业应当在施工现场采取维护安全、防范危险、预防火灾等措施；有条件的，应当对施工现场实行封闭管理。"},{"i":40,"n":"第四十条","txt":"建设单位应当向建筑施工企业提供与施工现场相关的地下管线资料，建筑施工企业应当采取措施加以保护。"},{"i":41,"n":"第四十一条","txt":"建筑施工企业应当遵守有关环境保护和安全生产的法律、法规的规定，采取控制和处理施工现场的各种粉尘、废气、废水、固体废物以及噪声、振动对环境的污染和危害的措施。"},{"i":42,"n":"第四十二条","txt":"有下列情形之一的，建设单位应当按照国家有关规定办理申请批准手续："},{"i":43,"n":"第四十三条","txt":"建设行政主管部门负责建筑安全生产的管理，并依法接受劳动行政主管部门对建筑安全生产的指导和监督。"},{"i":44,"n":"第四十四条","txt":"建筑施工企业必须依法加强对建筑安全生产的管理，执行安全生产责任制度，采取有效措施，防止伤亡和其他安全生产事故的发生。"},{"i":45,"n":"第四十五条","txt":"施工现场安全由建筑施工企业负责。实行施工总承包的，由总承包单位负责。分包单位向总承包单位负责，服从总承包单位对施工现场的安全生产管理。"},{"i":46,"n":"第四十六条","txt":"建筑施工企业应当建立健全劳动安全生产教育培训制度，加强对职工安全生产的教育培训；未经安全生产教育培训的人员，不得上岗作业。"},{"i":47,"n":"第四十七条","txt":"建筑施工企业和作业人员在施工过程中，应当遵守有关安全生产的法律、法规和建筑行业安全规章、规程，不得违章指挥或者违章作业。作业人员有权对影响人身健康的作业程序和作业条件提出改进意见，有权获得安全生产所需的防护用品。作业人员对危及生命安全和人身健康的行为有权提出批评、检举和控告。"},{"i":48,"n":"第四十八条","txt":"建筑施工企业应当依法为职工参加工伤保险缴纳工伤保险费。鼓励企业为从事危险作业的职工办理意外伤害保险，支付保险费。"},{"i":49,"n":"第四十九条","txt":"涉及建筑主体和承重结构变动的装修工程，建设单位应当在施工前委托原设计单位或者具有相应资质条件的设计单位提出设计方案；没有设计方案的，不得施工。"},{"i":50,"n":"第五十条","txt":"房屋拆除应当由具备保证安全条件的建筑施工单位承担，由建筑施工单位负责人对安全负责。"},{"i":51,"n":"第五十一条","txt":"施工中发生事故时，建筑施工企业应当采取紧急措施减少人员伤亡和事故损失，并按照国家有关规定及时向有关部门报告。"},{"i":52,"n":"第五十二条","txt":"建筑工程勘察、设计、施工的质量必须符合国家有关建筑工程安全标准的要求，具体管理办法由国务院规定。"},{"i":53,"n":"第五十三条","txt":"国家对从事建筑活动的单位推行质量体系认证制度。从事建筑活动的单位根据自愿原则可以向国务院产品质量监督管理部门或者国务院产品质量监督管理部门授权的部门认可的认证机构申请质量体系认证。经认证合格的，由认证机构颁发质量体系认证证书。"},{"i":54,"n":"第五十四条","txt":"建设单位不得以任何理由，要求建筑设计单位或者建筑施工企业在工程设计或者施工作业中，违反法律、行政法规和建筑工程质量、安全标准，降低工程质量。"},{"i":55,"n":"第五十五条","txt":"建筑工程实行总承包的，工程质量由工程总承包单位负责，总承包单位将建筑工程分包给其他单位的，应当对分包工程的质量与分包单位承担连带责任。分包单位应当接受总承包单位的质量管理。"},{"i":56,"n":"第五十六条","txt":"建筑工程的勘察、设计单位必须对其勘察、设计的质量负责。勘察、设计文件应当符合有关法律、行政法规的规定和建筑工程质量、安全标准、建筑工程勘察、设计技术规范以及合同的约定。设计文件选用的建筑材料、建筑构配件和设备，应当注明其规格、型号、性能等技术指标，其质量要求必须符合国家规定的标准。"},{"i":57,"n":"第五十七条","txt":"建筑设计单位对设计文件选用的建筑材料、建筑构配件和设备，不得指定生产厂、供应商。"},{"i":58,"n":"第五十八条","txt":"建筑施工企业对工程的施工质量负责。"},{"i":59,"n":"第五十九条","txt":"建筑施工企业必须按照工程设计要求、施工技术标准和合同的约定，对建筑材料、建筑构配件和设备进行检验，不合格的不得使用。"},{"i":60,"n":"第六十条","txt":"建筑物在合理使用寿命内，必须确保地基基础工程和主体结构的质量。"},{"i":61,"n":"第六十一条","txt":"交付竣工验收的建筑工程，必须符合规定的建筑工程质量标准，有完整的工程技术经济资料和经签署的工程保修书，并具备国家规定的其他竣工条件。"},{"i":62,"n":"第六十二条","txt":"建筑工程实行质量保修制度。"},{"i":63,"n":"第六十三条","txt":"任何单位和个人对建筑工程的质量事故、质量缺陷都有权向建设行政主管部门或者其他有关部门进行检举、控告、投诉。"},{"i":64,"n":"第六十四条","txt":"违反本法规定，未取得施工许可证或者开工报告未经批准擅自施工的，责令改正，对不符合开工条件的责令停止施工，可以处以罚款。"},{"i":65,"n":"第六十五条","txt":"发包单位将工程发包给不具有相应资质条件的承包单位的，或者违反本法规定将建筑工程肢解发包的，责令改正，处以罚款。"},{"i":66,"n":"第六十六条","txt":"建筑施工企业转让、出借资质证书或者以其他方式允许他人以本企业的名义承揽工程的，责令改正，没收违法所得，并处罚款，可以责令停业整顿，降低资质等级；情节严重的，吊销资质证书。对因该项承揽工程不符合规定的质量标准造成的损失，建筑施工企业与使用本企业名义的单位或者个人承担连带赔偿责任。"},{"i":67,"n":"第六十七条","txt":"承包单位将承包的工程转包的，或者违反本法规定进行分包的，责令改正，没收违法所得，并处罚款，可以责令停业整顿，降低资质等级；情节严重的，吊销资质证书。"},{"i":68,"n":"第六十八条","txt":"在工程发包与承包中索贿、受贿、行贿，构成犯罪的，依法追究刑事责任；不构成犯罪的，分别处以罚款，没收贿赂的财物，对直接负责的主管人员和其他直接责任人员给予处分。"},{"i":69,"n":"第六十九条","txt":"工程监理单位与建设单位或者建筑施工企业串通，弄虚作假、降低工程质量的，责令改正，处以罚款，降低资质等级或者吊销资质证书；有违法所得的，予以没收；造成损失的，承担连带赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":70,"n":"第七十条","txt":"违反本法规定，涉及建筑主体或者承重结构变动的装修工程擅自施工的，责令改正，处以罚款；造成损失的，承担赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":71,"n":"第七十一条","txt":"建筑施工企业违反本法规定，对建筑安全事故隐患不采取措施予以消除的，责令改正，可以处以罚款；情节严重的，责令停业整顿，降低资质等级或者吊销资质证书；构成犯罪的，依法追究刑事责任。"},{"i":72,"n":"第七十二条","txt":"建设单位违反本法规定，要求建筑设计单位或者建筑施工企业违反建筑工程质量、安全标准，降低工程质量的，责令改正，可以处以罚款；构成犯罪的，依法追究刑事责任。"},{"i":73,"n":"第七十三条","txt":"建筑设计单位不按照建筑工程质量、安全标准进行设计的，责令改正，处以罚款；造成工程质量事故的，责令停业整顿，降低资质等级或者吊销资质证书，没收违法所得，并处罚款；造成损失的，承担赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":74,"n":"第七十四条","txt":"建筑施工企业在施工中偷工减料的，使用不合格的建筑材料、建筑构配件和设备的，或者有其他不按照工程设计图纸或者施工技术标准施工的行为的，责令改正，处以罚款；情节严重的，责令停业整顿，降低资质等级或者吊销资质证书；造成建筑工程质量不符合规定的质量标准的，负责返工、修理，并赔偿因此造成的损失；构成犯罪的，依法追究刑事责任。"},{"i":75,"n":"第七十五条","txt":"建筑施工企业违反本法规定，不履行保修义务或者拖延履行保修义务的，责令改正，可以处以罚款，并对在保修期内因屋顶、墙面渗漏、开裂等质量缺陷造成的损失，承担赔偿责任。"},{"i":76,"n":"第七十六条","txt":"本法规定的责令停业整顿、降低资质等级和吊销资质证书的行政处罚，由颁发资质证书的机关决定；其他行政处罚，由建设行政主管部门或者有关部门依照法律和国务院规定的职权范围决定。"},{"i":77,"n":"第七十七条","txt":"违反本法规定，对不具备相应资质等级条件的单位颁发该等级资质证书的，由其上级机关责令收回所发的资质证书，对直接负责的主管人员和其他直接责任人员给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":78,"n":"第七十八条","txt":"政府及其所属部门的工作人员违反本法规定，限定发包单位将招标发包的工程发包给指定的承包单位的，由上级机关责令改正；构成犯罪的，依法追究刑事责任。"},{"i":79,"n":"第七十九条","txt":"负责颁发建筑工程施工许可证的部门及其工作人员对不符合施工条件的建筑工程颁发施工许可证的，负责工程质量监督检查或者竣工验收的部门及其工作人员对不合格的建筑工程出具质量合格文件或者按合格工程验收的，由上级机关责令改正，对责任人员给予行政处分；构成犯罪的，依法追究刑事责任；造成损失的，由该部门承担相应的赔偿责任。"},{"i":80,"n":"第八十条","txt":"在建筑物的合理使用寿命内，因建筑工程质量不合格受到损害的，有权向责任者要求赔偿。"},{"i":81,"n":"第八十一条","txt":"本法关于施工许可、建筑施工企业资质审查和建筑工程发包、承包、禁止转包，以及建筑工程监理、建筑工程安全和质量管理的规定，适用于其他专业建筑工程的建筑活动，具体办法由国务院规定。"},{"i":82,"n":"第八十二条","txt":"建设行政主管部门和其他有关部门在对建筑活动实施监督管理中，除按照国务院有关规定收取费用外，不得收取其他费用。"},{"i":83,"n":"第八十三条","txt":"省、自治区、直辖市人民政府确定的小型房屋建筑工程的建筑活动，参照本法执行。"},{"i":84,"n":"第八十四条","txt":"军用房屋建筑工程建筑活动的具体管理办法，由国务院、中央军事委员会依据本法制定。"},{"i":85,"n":"第八十五条","txt":"本法自1998年3月1日起施行。"}],"zhengfucaigoufa":[{"i":1,"n":"第一条","txt":"为了规范政府采购行为，提高政府采购资金的使用效益，维护国家利益和社会公共利益，保护政府采购当事人的合法权益，促进廉政建设，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内进行的政府采购适用本法。"},{"i":3,"n":"第三条","txt":"政府采购应当遵循公开透明原则、公平竞争原则、公正原则和诚实信用原则。"},{"i":4,"n":"第四条","txt":"政府采购工程进行招标投标的，适用招标投标法。"},{"i":5,"n":"第五条","txt":"任何单位和个人不得采用任何方式，阻挠和限制供应商自由进入本地区和本行业的政府采购市场。"},{"i":6,"n":"第六条","txt":"政府采购应当严格按照批准的预算执行。"},{"i":7,"n":"第七条","txt":"政府采购实行集中采购和分散采购相结合。集中采购的范围由省级以上人民政府公布的集中采购目录确定。"},{"i":8,"n":"第八条","txt":"政府采购限额标准，属于中央预算的政府采购项目，由国务院确定并公布；属于地方预算的政府采购项目，由省、自治区、直辖市人民政府或者其授权的机构确定并公布。"},{"i":9,"n":"第九条","txt":"政府采购应当有助于实现国家的经济和社会发展政策目标，包括保护环境，扶持不发达地区和少数民族地区，促进中小企业发展等。"},{"i":10,"n":"第十条","txt":"政府采购应当采购本国货物、工程和服务。但有下列情形之一的除外："},{"i":11,"n":"第十一条","txt":"政府采购的信息应当在政府采购监督管理部门指定的媒体上及时向社会公开发布，但涉及商业秘密的除外。"},{"i":12,"n":"第十二条","txt":"在政府采购活动中，采购人员及相关人员与供应商有利害关系的，必须回避。供应商认为采购人员及相关人员与其他供应商有利害关系的，可以申请其回避。"},{"i":13,"n":"第十三条","txt":"各级人民政府财政部门是负责政府采购监督管理的部门，依法履行对政府采购活动的监督管理职责。"},{"i":14,"n":"第十四条","txt":"政府采购当事人是指在政府采购活动中享有权利和承担义务的各类主体，包括采购人、供应商和采购代理机构等。"},{"i":15,"n":"第十五条","txt":"采购人是指依法进行政府采购的国家机关、事业单位、团体组织。"},{"i":16,"n":"第十六条","txt":"集中采购机构为采购代理机构。设区的市、自治州以上人民政府根据本级政府采购项目组织集中采购的需要设立集中采购机构。"},{"i":17,"n":"第十七条","txt":"集中采购机构进行政府采购活动，应当符合采购价格低于市场平均价格、采购效率更高、采购质量优良和服务良好的要求。"},{"i":18,"n":"第十八条","txt":"采购人采购纳入集中采购目录的政府采购项目，必须委托集中采购机构代理采购；采购未纳入集中采购目录的政府采购项目，可以自行采购，也可以委托集中采购机构在委托的范围内代理采购。"},{"i":19,"n":"第十九条","txt":"采购人可以委托集中采购机构以外的采购代理机构，在委托的范围内办理政府采购事宜。"},{"i":20,"n":"第二十条","txt":"采购人依法委托采购代理机构办理采购事宜的，应当由采购人与采购代理机构签订委托代理协议，依法确定委托代理的事项，约定双方的权利义务。"},{"i":21,"n":"第二十一条","txt":"供应商是指向采购人提供货物、工程或者服务的法人、其他组织或者自然人。"},{"i":22,"n":"第二十二条","txt":"供应商参加政府采购活动应当具备下列条件："},{"i":23,"n":"第二十三条","txt":"采购人可以要求参加政府采购的供应商提供有关资质证明文件和业绩情况，并根据本法规定的供应商条件和采购项目对供应商的特定要求，对供应商的资格进行审查。"},{"i":24,"n":"第二十四条","txt":"两个以上的自然人、法人或者其他组织可以组成一个联合体，以一个供应商的身份共同参加政府采购。"},{"i":25,"n":"第二十五条","txt":"政府采购当事人不得相互串通损害国家利益、社会公共利益和其他当事人的合法权益；不得以任何手段排斥其他供应商参与竞争。"},{"i":26,"n":"第二十六条","txt":"政府采购采用以下方式："},{"i":27,"n":"第二十七条","txt":"采购人采购货物或者服务应当采用公开招标方式的，其具体数额标准，属于中央预算的政府采购项目，由国务院规定；属于地方预算的政府采购项目，由省、自治区、直辖市人民政府规定；因特殊情况需要采用公开招标以外的采购方式的，应当在采购活动开始前获得设区的市、自治州以上人民政府采购监督管理部门的批准。"},{"i":28,"n":"第二十八条","txt":"采购人不得将应当以公开招标方式采购的货物或者服务化整为零或者以其他任何方式规避公开招标采购。"},{"i":29,"n":"第二十九条","txt":"符合下列情形之一的货物或者服务，可以依照本法采用邀请招标方式采购："},{"i":30,"n":"第三十条","txt":"符合下列情形之一的货物或者服务，可以依照本法采用竞争性谈判方式采购："},{"i":31,"n":"第三十一条","txt":"符合下列情形之一的货物或者服务，可以依照本法采用单一来源方式采购："},{"i":32,"n":"第三十二条","txt":"采购的货物规格、标准统一、现货货源充足且价格变化幅度小的政府采购项目，可以依照本法采用询价方式采购。"},{"i":33,"n":"第三十三条","txt":"负有编制部门预算职责的部门在编制下一财政年度部门预算时，应当将该财政年度政府采购的项目及资金预算列出，报本级财政部门汇总。部门预算的审批，按预算管理权限和程序进行。"},{"i":34,"n":"第三十四条","txt":"货物或者服务项目采取邀请招标方式采购的，采购人应当从符合相应资格条件的供应商中，通过随机方式选择三家以上的供应商，并向其发出投标邀请书。"},{"i":35,"n":"第三十五条","txt":"货物和服务项目实行招标方式采购的，自招标文件开始发出之日起至投标人提交投标文件截止之日止，不得少于二十日。"},{"i":36,"n":"第三十六条","txt":"在招标采购中，出现下列情形之一的，应予废标："},{"i":37,"n":"第三十七条","txt":"废标后，除采购任务取消情形外，应当重新组织招标；需要采取其他方式采购的，应当在采购活动开始前获得设区的市、自治州以上人民政府采购监督管理部门或者政府有关部门批准。"},{"i":38,"n":"第三十八条","txt":"采用竞争性谈判方式采购的，应当遵循下列程序："},{"i":39,"n":"第三十九条","txt":"采取单一来源方式采购的，采购人与供应商应当遵循本法规定的原则，在保证采购项目质量和双方商定合理价格的基础上进行采购。"},{"i":40,"n":"第四十条","txt":"采取询价方式采购的，应当遵循下列程序："},{"i":41,"n":"第四十一条","txt":"采购人或者其委托的采购代理机构应当组织对供应商履约的验收。大型或者复杂的政府采购项目，应当邀请国家认可的质量检测机构参加验收工作。验收方成员应当在验收书上签字，并承担相应的法律责任。"},{"i":42,"n":"第四十二条","txt":"采购人、采购代理机构对政府采购项目每项采购活动的采购文件应当妥善保存，不得伪造、变造、隐匿或者销毁。采购文件的保存期限为从采购结束之日起至少保存十五年。"},{"i":43,"n":"第四十三条","txt":"政府采购合同适用合同法。采购人和供应商之间的权利和义务，应当按照平等、自愿的原则以合同方式约定。"},{"i":44,"n":"第四十四条","txt":"政府采购合同应当采用书面形式。"},{"i":45,"n":"第四十五条","txt":"国务院政府采购监督管理部门应当会同国务院有关部门，规定政府采购合同必须具备的条款。"},{"i":46,"n":"第四十六条","txt":"采购人与中标、成交供应商应当在中标、成交通知书发出之日起三十日内，按照采购文件确定的事项签订政府采购合同。"},{"i":47,"n":"第四十七条","txt":"政府采购项目的采购合同自签订之日起七个工作日内，采购人应当将合同副本报同级政府采购监督管理部门和有关部门备案。"},{"i":48,"n":"第四十八条","txt":"经采购人同意，中标、成交供应商可以依法采取分包方式履行合同。"},{"i":49,"n":"第四十九条","txt":"政府采购合同履行中，采购人需追加与合同标的相同的货物、工程或者服务的，在不改变合同其他条款的前提下，可以与供应商协商签订补充合同，但所有补充合同的采购金额不得超过原合同采购金额的百分之十。"},{"i":50,"n":"第五十条","txt":"政府采购合同的双方当事人不得擅自变更、中止或者终止合同。"},{"i":51,"n":"第五十一条","txt":"供应商对政府采购活动事项有疑问的，可以向采购人提出询问，采购人应当及时作出答复，但答复的内容不得涉及商业秘密。"},{"i":52,"n":"第五十二条","txt":"供应商认为采购文件、采购过程和中标、成交结果使自己的权益受到损害的，可以在知道或者应知其权益受到损害之日起七个工作日内，以书面形式向采购人提出质疑。"},{"i":53,"n":"第五十三条","txt":"采购人应当在收到供应商的书面质疑后七个工作日内作出答复，并以书面形式通知质疑供应商和其他有关供应商，但答复的内容不得涉及商业秘密。"},{"i":54,"n":"第五十四条","txt":"采购人委托采购代理机构采购的，供应商可以向采购代理机构提出询问或者质疑，采购代理机构应当依照本法第五十一条、第五十三条的规定就采购人委托授权范围内的事项作出答复。"},{"i":55,"n":"第五十五条","txt":"质疑供应商对采购人、采购代理机构的答复不满意或者采购人、采购代理机构未在规定的时间内作出答复的，可以在答复期满后十五个工作日内向同级政府采购监督管理部门投诉。"},{"i":56,"n":"第五十六条","txt":"政府采购监督管理部门应当在收到投诉后三十个工作日内，对投诉事项作出处理决定，并以书面形式通知投诉人和与投诉事项有关的当事人。"},{"i":57,"n":"第五十七条","txt":"政府采购监督管理部门在处理投诉事项期间，可以视具体情况书面通知采购人暂停采购活动，但暂停时间最长不得超过三十日。"},{"i":58,"n":"第五十八条","txt":"投诉人对政府采购监督管理部门的投诉处理决定不服或者政府采购监督管理部门逾期未作处理的，可以依法申请行政复议或者向人民法院提起行政诉讼。"},{"i":59,"n":"第五十九条","txt":"政府采购监督管理部门应当加强对政府采购活动及集中采购机构的监督检查。"},{"i":60,"n":"第六十条","txt":"政府采购监督管理部门不得设置集中采购机构，不得参与政府采购项目的采购活动。"},{"i":61,"n":"第六十一条","txt":"集中采购机构应当建立健全内部监督管理制度。采购活动的决策和执行程序应当明确，并相互监督、相互制约。经办采购的人员与负责采购合同审核、验收人员的职责权限应当明确，并相互分离。"},{"i":62,"n":"第六十二条","txt":"集中采购机构的采购人员应当具有相关职业素质和专业技能，符合政府采购监督管理部门规定的专业岗位任职要求。"},{"i":63,"n":"第六十三条","txt":"政府采购项目的采购标准应当公开。"},{"i":64,"n":"第六十四条","txt":"采购人必须按照本法规定的采购方式和采购程序进行采购。"},{"i":65,"n":"第六十五条","txt":"政府采购监督管理部门应当对政府采购项目的采购活动进行检查，政府采购当事人应当如实反映情况，提供有关材料。"},{"i":66,"n":"第六十六条","txt":"政府采购监督管理部门应当对集中采购机构的采购价格、节约资金效果、服务质量、信誉状况、有无违法行为等事项进行考核，并定期如实公布考核结果。"},{"i":67,"n":"第六十七条","txt":"依照法律、行政法规的规定对政府采购负有行政监督职责的政府有关部门，应当按照其职责分工，加强对政府采购活动的监督。"},{"i":68,"n":"第六十八条","txt":"审计机关应当对政府采购进行审计监督。政府采购监督管理部门、政府采购各当事人有关政府采购活动，应当接受审计机关的审计监督。"},{"i":69,"n":"第六十九条","txt":"监察机关应当加强对参与政府采购活动的国家机关、国家公务员和国家行政机关任命的其他人员实施监察。"},{"i":70,"n":"第七十条","txt":"任何单位和个人对政府采购活动中的违法行为，有权控告和检举，有关部门、机关应当依照各自职责及时处理。"},{"i":71,"n":"第七十一条","txt":"采购人、采购代理机构有下列情形之一的，责令限期改正，给予警告，可以并处罚款，对直接负责的主管人员和其他直接责任人员，由其行政主管部门或者有关机关给予处分，并予通报："},{"i":72,"n":"第七十二条","txt":"采购人、采购代理机构及其工作人员有下列情形之一，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，处以罚款，有违法所得的，并处没收违法所得，属于国家机关工作人员的，依法给予行政处分："},{"i":73,"n":"第七十三条","txt":"有前两条违法行为之一影响中标、成交结果或者可能影响中标、成交结果的，按下列情况分别处理："},{"i":74,"n":"第七十四条","txt":"采购人对应当实行集中采购的政府采购项目，不委托集中采购机构实行集中采购的，由政府采购监督管理部门责令改正；拒不改正的，停止按预算向其支付资金，由其上级行政主管部门或者有关机关依法给予其直接负责的主管人员和其他直接责任人员处分。"},{"i":75,"n":"第七十五条","txt":"采购人未依法公布政府采购项目的采购标准和采购结果的，责令改正，对直接负责的主管人员依法给予处分。"},{"i":76,"n":"第七十六条","txt":"采购人、采购代理机构违反本法规定隐匿、销毁应当保存的采购文件或者伪造、变造采购文件的，由政府采购监督管理部门处以二万元以上十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":77,"n":"第七十七条","txt":"供应商有下列情形之一的，处以采购金额千分之五以上千分之十以下的罚款，列入不良行为记录名单，在一至三年内禁止参加政府采购活动，有违法所得的，并处没收违法所得，情节严重的，由工商行政管理机关吊销营业执照；构成犯罪的，依法追究刑事责任："},{"i":78,"n":"第七十八条","txt":"采购代理机构在代理政府采购业务中有违法行为的，按照有关法律规定处以罚款，可以在一至三年内禁止其代理政府采购业务，构成犯罪的，依法追究刑事责任。"},{"i":79,"n":"第七十九条","txt":"政府采购当事人有本法第七十一条、第七十二条、第七十七条违法行为之一，给他人造成损失的，并应依照有关民事法律规定承担民事责任。"},{"i":80,"n":"第八十条","txt":"政府采购监督管理部门的工作人员在实施监督检查中违反本法规定滥用职权，玩忽职守，徇私舞弊的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":81,"n":"第八十一条","txt":"政府采购监督管理部门对供应商的投诉逾期未作处理的，给予直接负责的主管人员和其他直接责任人员行政处分。"},{"i":82,"n":"第八十二条","txt":"政府采购监督管理部门对集中采购机构业绩的考核，有虚假陈述，隐瞒真实情况的，或者不作定期考核和公布考核结果的，应当及时纠正，由其上级机关或者监察机关对其负责人进行通报，并对直接负责的人员依法给予行政处分。"},{"i":83,"n":"第八十三条","txt":"任何单位或者个人阻挠和限制供应商进入本地区或者本行业政府采购市场的，责令限期改正；拒不改正的，由该单位、个人的上级行政主管部门或者有关机关给予单位责任人或者个人处分。"},{"i":84,"n":"第八十四条","txt":"使用国际组织和外国政府贷款进行的政府采购，贷款方、资金提供方与中方达成的协议对采购的具体条件另有规定的，可以适用其规定，但不得损害国家利益和社会公共利益。"},{"i":85,"n":"第八十五条","txt":"对因严重自然灾害和其他不可抗力事件所实施的紧急采购和涉及国家安全和秘密的采购，不适用本法。"},{"i":86,"n":"第八十六条","txt":"军事采购法规由中央军事委员会另行制定。"},{"i":87,"n":"第八十七条","txt":"本法实施的具体步骤和办法由国务院规定。"},{"i":88,"n":"第八十八条","txt":"本法自2003年1月1日起施行。"}],"shujuanquanfa":[{"i":1,"n":"第一条","txt":"为了规范数据处理活动，保障数据安全，促进数据开发利用，保护个人、组织的合法权益，维护国家主权、安全和发展利益，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内开展数据处理活动及其安全监管，适用本法。"},{"i":3,"n":"第三条","txt":"本法所称数据，是指任何以电子或者其他方式对信息的记录。"},{"i":4,"n":"第四条","txt":"维护数据安全，应当坚持总体国家安全观，建立健全数据安全治理体系，提高数据安全保障能力。"},{"i":5,"n":"第五条","txt":"中央国家安全领导机构负责国家数据安全工作的决策和议事协调，研究制定、指导实施国家数据安全战略和有关重大方针政策，统筹协调国家数据安全的重大事项和重要工作，建立国家数据安全工作协调机制。"},{"i":6,"n":"第六条","txt":"各地区、各部门对本地区、本部门工作中收集和产生的数据及数据安全负责。"},{"i":7,"n":"第七条","txt":"国家保护个人、组织与数据有关的权益，鼓励数据依法合理有效利用，保障数据依法有序自由流动，促进以数据为关键要素的数字经济发展。"},{"i":8,"n":"第八条","txt":"开展数据处理活动，应当遵守法律、法规，尊重社会公德和伦理，遵守商业道德和职业道德，诚实守信，履行数据安全保护义务，承担社会责任，不得危害国家安全、公共利益，不得损害个人、组织的合法权益。"},{"i":9,"n":"第九条","txt":"国家支持开展数据安全知识宣传普及，提高全社会的数据安全保护意识和水平，推动有关部门、行业组织、科研机构、企业、个人等共同参与数据安全保护工作，形成全社会共同维护数据安全和促进发展的良好环境。"},{"i":10,"n":"第十条","txt":"相关行业组织按照章程，依法制定数据安全行为规范和团体标准，加强行业自律，指导会员加强数据安全保护，提高数据安全保护水平，促进行业健康发展。"},{"i":11,"n":"第十一条","txt":"国家积极开展数据安全治理、数据开发利用等领域的国际交流与合作，参与数据安全相关国际规则和标准的制定，促进数据跨境安全、自由流动。"},{"i":12,"n":"第十二条","txt":"任何个人、组织都有权对违反本法规定的行为向有关主管部门投诉、举报。收到投诉、举报的部门应当及时依法处理。"},{"i":13,"n":"第十三条","txt":"国家统筹发展和安全，坚持以数据开发利用和产业发展促进数据安全，以数据安全保障数据开发利用和产业发展。"},{"i":14,"n":"第十四条","txt":"国家实施大数据战略，推进数据基础设施建设，鼓励和支持数据在各行业、各领域的创新应用。"},{"i":15,"n":"第十五条","txt":"国家支持开发利用数据提升公共服务的智能化水平。提供智能化公共服务，应当充分考虑老年人、残疾人的需求，避免对老年人、残疾人的日常生活造成障碍。"},{"i":16,"n":"第十六条","txt":"国家支持数据开发利用和数据安全技术研究，鼓励数据开发利用和数据安全等领域的技术推广和商业创新，培育、发展数据开发利用和数据安全产品、产业体系。"},{"i":17,"n":"第十七条","txt":"国家推进数据开发利用技术和数据安全标准体系建设。国务院标准化行政主管部门和国务院有关部门根据各自的职责，组织制定并适时修订有关数据开发利用技术、产品和数据安全相关标准。国家支持企业、社会团体和教育、科研机构等参与标准制定。"},{"i":18,"n":"第十八条","txt":"国家促进数据安全检测评估、认证等服务的发展，支持数据安全检测评估、认证等专业机构依法开展服务活动。"},{"i":19,"n":"第十九条","txt":"国家建立健全数据交易管理制度，规范数据交易行为，培育数据交易市场。"},{"i":20,"n":"第二十条","txt":"国家支持教育、科研机构和企业等开展数据开发利用技术和数据安全相关教育和培训，采取多种方式培养数据开发利用技术和数据安全专业人才，促进人才交流。"},{"i":21,"n":"第二十一条","txt":"国家建立数据分类分级保护制度，根据数据在经济社会发展中的重要程度，以及一旦遭到篡改、破坏、泄露或者非法获取、非法利用，对国家安全、公共利益或者个人、组织合法权益造成的危害程度，对数据实行分类分级保护。国家数据安全工作协调机制统筹协调有关部门制定重要数据目录，加强对重要数据的保护。"},{"i":22,"n":"第二十二条","txt":"国家建立集中统一、高效权威的数据安全风险评估、报告、信息共享、监测预警机制。国家数据安全工作协调机制统筹协调有关部门加强数据安全风险信息的获取、分析、研判、预警工作。"},{"i":23,"n":"第二十三条","txt":"国家建立数据安全应急处置机制。发生数据安全事件，有关主管部门应当依法启动应急预案，采取相应的应急处置措施，防止危害扩大，消除安全隐患，并及时向社会发布与公众有关的警示信息。"},{"i":24,"n":"第二十四条","txt":"国家建立数据安全审查制度，对影响或者可能影响国家安全的数据处理活动进行国家安全审查。"},{"i":25,"n":"第二十五条","txt":"国家对与维护国家安全和利益、履行国际义务相关的属于管制物项的数据依法实施出口管制。"},{"i":26,"n":"第二十六条","txt":"任何国家或者地区在与数据和数据开发利用技术等有关的投资、贸易等方面对中华人民共和国采取歧视性的禁止、限制或者其他类似措施的，中华人民共和国可以根据实际情况对该国家或者地区对等采取措施。"},{"i":27,"n":"第二十七条","txt":"开展数据处理活动应当依照法律、法规的规定，建立健全全流程数据安全管理制度，组织开展数据安全教育培训，采取相应的技术措施和其他必要措施，保障数据安全。利用互联网等信息网络开展数据处理活动，应当在网络安全等级保护制度的基础上，履行上述数据安全保护义务。"},{"i":28,"n":"第二十八条","txt":"开展数据处理活动以及研究开发数据新技术，应当有利于促进经济社会发展，增进人民福祉，符合社会公德和伦理。"},{"i":29,"n":"第二十九条","txt":"开展数据处理活动应当加强风险监测，发现数据安全缺陷、漏洞等风险时，应当立即采取补救措施；发生数据安全事件时，应当立即采取处置措施，按照规定及时告知用户并向有关主管部门报告。"},{"i":30,"n":"第三十条","txt":"重要数据的处理者应当按照规定对其数据处理活动定期开展风险评估，并向有关主管部门报送风险评估报告。"},{"i":31,"n":"第三十一条","txt":"关键信息基础设施的运营者在中华人民共和国境内运营中收集和产生的重要数据的出境安全管理，适用《中华人民共和国网络安全法》的规定；其他数据处理者在中华人民共和国境内运营中收集和产生的重要数据的出境安全管理办法，由国家网信部门会同国务院有关部门制定。"},{"i":32,"n":"第三十二条","txt":"任何组织、个人收集数据，应当采取合法、正当的方式，不得窃取或者以其他非法方式获取数据。"},{"i":33,"n":"第三十三条","txt":"从事数据交易中介服务的机构提供服务，应当要求数据提供方说明数据来源，审核交易双方的身份，并留存审核、交易记录。"},{"i":34,"n":"第三十四条","txt":"法律、行政法规规定提供数据处理相关服务应当取得行政许可的，服务提供者应当依法取得许可。"},{"i":35,"n":"第三十五条","txt":"公安机关、国家安全机关因依法维护国家安全或者侦查犯罪的需要调取数据，应当按照国家有关规定，经过严格的批准手续，依法进行，有关组织、个人应当予以配合。"},{"i":36,"n":"第三十六条","txt":"中华人民共和国主管机关根据有关法律和中华人民共和国缔结或者参加的国际条约、协定，或者按照平等互惠原则，处理外国司法或者执法机构关于提供数据的请求。非经中华人民共和国主管机关批准，境内的组织、个人不得向外国司法或者执法机构提供存储于中华人民共和国境内的数据。"},{"i":37,"n":"第三十七条","txt":"国家大力推进电子政务建设，提高政务数据的科学性、准确性、时效性，提升运用数据服务经济社会发展的能力。"},{"i":38,"n":"第三十八条","txt":"国家机关为履行法定职责的需要收集、使用数据，应当在其履行法定职责的范围内依照法律、行政法规规定的条件和程序进行；对在履行职责中知悉的个人隐私、个人信息、商业秘密、保密商务信息等数据应当依法予以保密，不得泄露或者非法向他人提供。"},{"i":39,"n":"第三十九条","txt":"国家机关应当依照法律、行政法规的规定，建立健全数据安全管理制度，落实数据安全保护责任，保障政务数据安全。"},{"i":40,"n":"第四十条","txt":"国家机关委托他人建设、维护电子政务系统，存储、加工政务数据，应当经过严格的批准程序，并应当监督受托方履行相应的数据安全保护义务。受托方应当依照法律、法规的规定和合同约定履行数据安全保护义务，不得擅自留存、使用、泄露或者向他人提供政务数据。"},{"i":41,"n":"第四十一条","txt":"国家机关应当遵循公正、公平、便民的原则，按照规定及时、准确地公开政务数据。依法不予公开的除外。"},{"i":42,"n":"第四十二条","txt":"国家制定政务数据开放目录，构建统一规范、互联互通、安全可控的政务数据开放平台，推动政务数据开放利用。"},{"i":43,"n":"第四十三条","txt":"法律、法规授权的具有管理公共事务职能的组织为履行法定职责开展数据处理活动，适用本章规定。"},{"i":44,"n":"第四十四条","txt":"有关主管部门在履行数据安全监管职责中，发现数据处理活动存在较大安全风险的，可以按照规定的权限和程序对有关组织、个人进行约谈，并要求有关组织、个人采取措施进行整改，消除隐患。"},{"i":45,"n":"第四十五条","txt":"开展数据处理活动的组织、个人不履行本法第二十七条、第二十九条、第三十条规定的数据安全保护义务的，由有关主管部门责令改正，给予警告，可以并处五万元以上五十万元以下罚款，对直接负责的主管人员和其他直接责任人员可以处一万元以上十万元以下罚款；拒不改正或者造成大量数据泄露等严重后果的，处五十万元以上二百万元以下罚款，并可以责令暂停相关业务、停业整顿、吊销相关业务许可证或者吊销营业执照，对直接负责的主管人员和其他直接责任人员处五万元以上二十万元以下罚款。"},{"i":46,"n":"第四十六条","txt":"违反本法第三十一条规定，向境外提供重要数据的，由有关主管部门责令改正，给予警告，可以并处十万元以上一百万元以下罚款，对直接负责的主管人员和其他直接责任人员可以处一万元以上十万元以下罚款；情节严重的，处一百万元以上一千万元以下罚款，并可以责令暂停相关业务、停业整顿、吊销相关业务许可证或者吊销营业执照，对直接负责的主管人员和其他直接责任人员处十万元以上一百万元以下罚款。"},{"i":47,"n":"第四十七条","txt":"从事数据交易中介服务的机构未履行本法第三十三条规定的义务的，由有关主管部门责令改正，没收违法所得，处违法所得一倍以上十倍以下罚款，没有违法所得或者违法所得不足十万元的，处十万元以上一百万元以下罚款，并可以责令暂停相关业务、停业整顿、吊销相关业务许可证或者吊销营业执照；对直接负责的主管人员和其他直接责任人员处一万元以上十万元以下罚款。"},{"i":48,"n":"第四十八条","txt":"违反本法第三十五条规定，拒不配合数据调取的，由有关主管部门责令改正，给予警告，并处五万元以上五十万元以下罚款，对直接负责的主管人员和其他直接责任人员处一万元以上十万元以下罚款。"},{"i":49,"n":"第四十九条","txt":"国家机关不履行本法规定的数据安全保护义务的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":50,"n":"第五十条","txt":"履行数据安全监管职责的国家工作人员玩忽职守、滥用职权、徇私舞弊的，依法给予处分。"},{"i":51,"n":"第五十一条","txt":"窃取或者以其他非法方式获取数据，开展数据处理活动排除、限制竞争，或者损害个人、组织合法权益的，依照有关法律、行政法规的规定处罚。"},{"i":52,"n":"第五十二条","txt":"违反本法规定，给他人造成损害的，依法承担民事责任。"},{"i":53,"n":"第五十三条","txt":"开展涉及国家秘密的数据处理活动，适用《中华人民共和国保守国家秘密法》等法律、行政法规的规定。"},{"i":54,"n":"第五十四条","txt":"军事数据安全保护的办法，由中央军事委员会依据本法另行制定。"},{"i":55,"n":"第五十五条","txt":"本法自2021年9月1日起施行。"}],"lvyoufa":[{"i":1,"n":"第一条","txt":"为保障旅游者和旅游经营者的合法权益，规范旅游市场秩序，保护和合理利用旅游资源，促进旅游业持续健康发展，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内的和在中华人民共和国境内组织到境外的游览、度假、休闲等形式的旅游活动以及为旅游活动提供相关服务的经营活动，适用本法。"},{"i":3,"n":"第三条","txt":"国家发展旅游事业，完善旅游公共服务，依法保护旅游者在旅游活动中的权利。"},{"i":4,"n":"第四条","txt":"旅游业发展应当遵循社会效益、经济效益和生态效益相统一的原则。国家鼓励各类市场主体在有效保护旅游资源的前提下，依法合理利用旅游资源。利用公共资源建设的游览场所应当体现公益性质。"},{"i":5,"n":"第五条","txt":"国家倡导健康、文明、环保的旅游方式，支持和鼓励各类社会机构开展旅游公益宣传，对促进旅游业发展做出突出贡献的单位和个人给予奖励。"},{"i":6,"n":"第六条","txt":"国家建立健全旅游服务标准和市场规则，禁止行业垄断和地区垄断。旅游经营者应当诚信经营，公平竞争，承担社会责任，为旅游者提供安全、健康、卫生、方便的旅游服务。"},{"i":7,"n":"第七条","txt":"国务院建立健全旅游综合协调机制，对旅游业发展进行综合协调。"},{"i":8,"n":"第八条","txt":"依法成立的旅游行业组织，实行自律管理。"},{"i":9,"n":"第九条","txt":"旅游者有权自主选择旅游产品和服务，有权拒绝旅游经营者的强制交易行为。"},{"i":10,"n":"第十条","txt":"旅游者的人格尊严、民族风俗习惯和宗教信仰应当得到尊重。"},{"i":11,"n":"第十一条","txt":"残疾人、老年人、未成年人等旅游者在旅游活动中依照法律、法规和有关规定享受便利和优惠。"},{"i":12,"n":"第十二条","txt":"旅游者在人身、财产安全遇有危险时，有请求救助和保护的权利。"},{"i":13,"n":"第十三条","txt":"旅游者在旅游活动中应当遵守社会公共秩序和社会公德，尊重当地的风俗习惯、文化传统和宗教信仰，爱护旅游资源，保护生态环境，遵守旅游文明行为规范。"},{"i":14,"n":"第十四条","txt":"旅游者在旅游活动中或者在解决纠纷时，不得损害当地居民的合法权益，不得干扰他人的旅游活动，不得损害旅游经营者和旅游从业人员的合法权益。"},{"i":15,"n":"第十五条","txt":"旅游者购买、接受旅游服务时，应当向旅游经营者如实告知与旅游活动相关的个人健康信息，遵守旅游活动中的安全警示规定。"},{"i":16,"n":"第十六条","txt":"出境旅游者不得在境外非法滞留，随团出境的旅游者不得擅自分团、脱团。"},{"i":17,"n":"第十七条","txt":"国务院和县级以上地方人民政府应当将旅游业发展纳入国民经济和社会发展规划。"},{"i":18,"n":"第十八条","txt":"旅游发展规划应当包括旅游业发展的总体要求和发展目标，旅游资源保护和利用的要求和措施，以及旅游产品开发、旅游服务质量提升、旅游文化建设、旅游形象推广、旅游基础设施和公共服务设施建设的要求和促进措施等内容。"},{"i":19,"n":"第十九条","txt":"旅游发展规划应当与土地利用总体规划、城乡规划、环境保护规划以及其他自然资源和文物等人文资源的保护和利用规划相衔接。"},{"i":20,"n":"第二十条","txt":"各级人民政府编制土地利用总体规划、城乡规划，应当充分考虑相关旅游项目、设施的空间布局和建设用地要求。规划和建设交通、通信、供水、供电、环保等基础设施和公共服务设施，应当兼顾旅游业发展的需要。"},{"i":21,"n":"第二十一条","txt":"对自然资源和文物等人文资源进行旅游利用，必须严格遵守有关法律、法规的规定，符合资源、生态保护和文物安全的要求，尊重和维护当地传统文化和习俗，维护资源的区域整体性、文化代表性和地域特殊性，并考虑军事设施保护的需要。有关主管部门应当加强对资源保护和旅游利用状况的监督检查。"},{"i":22,"n":"第二十二条","txt":"各级人民政府应当组织对本级政府编制的旅游发展规划的执行情况进行评估，并向社会公布。"},{"i":23,"n":"第二十三条","txt":"国务院和县级以上地方人民政府应当制定并组织实施有利于旅游业持续健康发展的产业政策，推进旅游休闲体系建设，采取措施推动区域旅游合作，鼓励跨区域旅游线路和产品开发，促进旅游与工业、农业、商业、文化、卫生、体育、科教等领域的融合，扶持少数民族地区、革命老区、边远地区和贫困地区旅游业发展。"},{"i":24,"n":"第二十四条","txt":"国务院和县级以上地方人民政府应当根据实际情况安排资金，加强旅游基础设施建设、旅游公共服务和旅游形象推广。"},{"i":25,"n":"第二十五条","txt":"国家制定并实施旅游形象推广战略。国务院旅游主管部门统筹组织国家旅游形象的境外推广工作，建立旅游形象推广机构和网络，开展旅游国际合作与交流。"},{"i":26,"n":"第二十六条","txt":"国务院旅游主管部门和县级以上地方人民政府应当根据需要建立旅游公共信息和咨询平台，无偿向旅游者提供旅游景区、线路、交通、气象、住宿、安全、医疗急救等必要信息和咨询服务。设区的市和县级人民政府有关部门应当根据需要在交通枢纽、商业中心和旅游者集中场所设置旅游咨询中心，在景区和通往主要景区的道路设置旅游指示标识。"},{"i":27,"n":"第二十七条","txt":"国家鼓励和支持发展旅游职业教育和培训，提高旅游从业人员素质。"},{"i":28,"n":"第二十八条","txt":"设立旅行社，招徕、组织、接待旅游者，为其提供旅游服务，应当具备下列条件，取得旅游主管部门的许可，依法办理工商登记："},{"i":29,"n":"第二十九条","txt":"旅行社可以经营下列业务："},{"i":30,"n":"第三十条","txt":"旅行社不得出租、出借旅行社业务经营许可证，或者以其他形式非法转让旅行社业务经营许可。"},{"i":31,"n":"第三十一条","txt":"旅行社应当按照规定交纳旅游服务质量保证金，用于旅游者权益损害赔偿和垫付旅游者人身安全遇有危险时紧急救助的费用。"},{"i":32,"n":"第三十二条","txt":"旅行社为招徕、组织旅游者发布信息，必须真实、准确，不得进行虚假宣传，误导旅游者。"},{"i":33,"n":"第三十三条","txt":"旅行社及其从业人员组织、接待旅游者，不得安排参观或者参与违反我国法律、法规和社会公德的项目或者活动。"},{"i":34,"n":"第三十四条","txt":"旅行社组织旅游活动应当向合格的供应商订购产品和服务。"},{"i":35,"n":"第三十五条","txt":"旅行社不得以不合理的低价组织旅游活动，诱骗旅游者，并通过安排购物或者另行付费旅游项目获取回扣等不正当利益。"},{"i":36,"n":"第三十六条","txt":"旅行社组织团队出境旅游或者组织、接待团队入境旅游，应当按照规定安排领队或者导游全程陪同。"},{"i":37,"n":"第三十七条","txt":"参加导游资格考试成绩合格，与旅行社订立劳动合同或者在相关旅游行业组织注册的人员，可以申请取得导游证。"},{"i":38,"n":"第三十八条","txt":"旅行社应当与其聘用的导游依法订立劳动合同，支付劳动报酬，缴纳社会保险费用。"},{"i":39,"n":"第三十九条","txt":"从事领队业务，应当取得导游证，具有相应的学历、语言能力和旅游从业经历，并与委派其从事领队业务的取得出境旅游业务经营许可的旅行社订立劳动合同。"},{"i":40,"n":"第四十条","txt":"导游和领队为旅游者提供服务必须接受旅行社委派，不得私自承揽导游和领队业务。"},{"i":41,"n":"第四十一条","txt":"导游和领队从事业务活动，应当佩戴导游证，遵守职业道德，尊重旅游者的风俗习惯和宗教信仰，应当向旅游者告知和解释旅游文明行为规范，引导旅游者健康、文明旅游，劝阻旅游者违反社会公德的行为。"},{"i":42,"n":"第四十二条","txt":"景区开放应当具备下列条件，并听取旅游主管部门的意见："},{"i":43,"n":"第四十三条","txt":"利用公共资源建设的景区的门票以及景区内的游览场所、交通工具等另行收费项目，实行政府定价或者政府指导价，严格控制价格上涨。拟收费或者提高价格的，应当举行听证会，征求旅游者、经营者和有关方面的意见，论证其必要性、可行性。"},{"i":44,"n":"第四十四条","txt":"景区应当在醒目位置公示门票价格、另行收费项目的价格及团体收费价格。景区提高门票价格应当提前六个月公布。"},{"i":45,"n":"第四十五条","txt":"景区接待旅游者不得超过景区主管部门核定的最大承载量。景区应当公布景区主管部门核定的最大承载量，制定和实施旅游者流量控制方案，并可以采取门票预约等方式，对景区接待旅游者的数量进行控制。"},{"i":46,"n":"第四十六条","txt":"城镇和乡村居民利用自有住宅或者其他条件依法从事旅游经营，其管理办法由省、自治区、直辖市制定。"},{"i":47,"n":"第四十七条","txt":"经营高空、高速、水上、潜水、探险等高风险旅游项目，应当按照国家有关规定取得经营许可。"},{"i":48,"n":"第四十八条","txt":"通过网络经营旅行社业务的，应当依法取得旅行社业务经营许可，并在其网站主页的显著位置标明其业务经营许可证信息。"},{"i":49,"n":"第四十九条","txt":"为旅游者提供交通、住宿、餐饮、娱乐等服务的经营者，应当符合法律、法规规定的要求，按照合同约定履行义务。"},{"i":50,"n":"第五十条","txt":"旅游经营者应当保证其提供的商品和服务符合保障人身、财产安全的要求。"},{"i":51,"n":"第五十一条","txt":"旅游经营者销售、购买商品或者服务，不得给予或者收受贿赂。"},{"i":52,"n":"第五十二条","txt":"旅游经营者对其在经营活动中知悉的旅游者个人信息，应当予以保密。"},{"i":53,"n":"第五十三条","txt":"从事道路旅游客运的经营者应当遵守道路客运安全管理的各项制度，并在车辆显著位置明示道路旅游客运专用标识，在车厢内显著位置公示经营者和驾驶人信息、道路运输管理机构监督电话等事项。"},{"i":54,"n":"第五十四条","txt":"景区、住宿经营者将其部分经营项目或者场地交由他人从事住宿、餐饮、购物、游览、娱乐、旅游交通等经营的，应当对实际经营者的经营行为给旅游者造成的损害承担连带责任。"},{"i":55,"n":"第五十五条","txt":"旅游经营者组织、接待出入境旅游，发现旅游者从事违法活动或者有违反本法第十六条规定情形的，应当及时向公安机关、旅游主管部门或者我国驻外机构报告。"},{"i":56,"n":"第五十六条","txt":"国家根据旅游活动的风险程度，对旅行社、住宿、旅游交通以及本法第四十七条规定的高风险旅游项目等经营者实施责任保险制度。"},{"i":57,"n":"第五十七条","txt":"旅行社组织和安排旅游活动，应当与旅游者订立合同。"},{"i":58,"n":"第五十八条","txt":"包价旅游合同应当采用书面形式，包括下列内容："},{"i":59,"n":"第五十九条","txt":"旅行社应当在旅游行程开始前向旅游者提供旅游行程单。旅游行程单是包价旅游合同的组成部分。"},{"i":60,"n":"第六十条","txt":"旅行社委托其他旅行社代理销售包价旅游产品并与旅游者订立包价旅游合同的，应当在包价旅游合同中载明委托社和代理社的基本信息。"},{"i":61,"n":"第六十一条","txt":"旅行社应当提示参加团队旅游的旅游者按照规定投保人身意外伤害保险。"},{"i":62,"n":"第六十二条","txt":"订立包价旅游合同时，旅行社应当向旅游者告知下列事项："},{"i":63,"n":"第六十三条","txt":"旅行社招徕旅游者组团旅游，因未达到约定人数不能出团的，组团社可以解除合同。但是，境内旅游应当至少提前七日通知旅游者，出境旅游应当至少提前三十日通知旅游者。"},{"i":64,"n":"第六十四条","txt":"旅游行程开始前，旅游者可以将包价旅游合同中自身的权利义务转让给第三人，旅行社没有正当理由的不得拒绝，因此增加的费用由旅游者和第三人承担。"},{"i":65,"n":"第六十五条","txt":"旅游行程结束前，旅游者解除合同的，组团社应当在扣除必要的费用后，将余款退还旅游者。"},{"i":66,"n":"第六十六条","txt":"旅游者有下列情形之一的，旅行社可以解除合同："},{"i":67,"n":"第六十七条","txt":"因不可抗力或者旅行社、履行辅助人已尽合理注意义务仍不能避免的事件，影响旅游行程的，按照下列情形处理："},{"i":68,"n":"第六十八条","txt":"旅游行程中解除合同的，旅行社应当协助旅游者返回出发地或者旅游者指定的合理地点。由于旅行社或者履行辅助人的原因导致合同解除的，返程费用由旅行社承担。"},{"i":69,"n":"第六十九条","txt":"旅行社应当按照包价旅游合同的约定履行义务，不得擅自变更旅游行程安排。"},{"i":70,"n":"第七十条","txt":"旅行社不履行包价旅游合同义务或者履行合同义务不符合约定的，应当依法承担继续履行、采取补救措施或者赔偿损失等违约责任；造成旅游者人身损害、财产损失的，应当依法承担赔偿责任。旅行社具备履行条件，经旅游者要求仍拒绝履行合同，造成旅游者人身损害、滞留等严重后果的，旅游者还可以要求旅行社支付旅游费用一倍以上三倍以下的赔偿金。"},{"i":71,"n":"第七十一条","txt":"由于地接社、履行辅助人的原因导致违约的，由组团社承担责任；组团社承担责任后可以向地接社、履行辅助人追偿。"},{"i":72,"n":"第七十二条","txt":"旅游者在旅游活动中或者在解决纠纷时，损害旅行社、履行辅助人、旅游从业人员或者其他旅游者的合法权益的，依法承担赔偿责任。"},{"i":73,"n":"第七十三条","txt":"旅行社根据旅游者的具体要求安排旅游行程，与旅游者订立包价旅游合同的，旅游者请求变更旅游行程安排，因此增加的费用由旅游者承担，减少的费用退还旅游者。"},{"i":74,"n":"第七十四条","txt":"旅行社接受旅游者的委托，为其代订交通、住宿、餐饮、游览、娱乐等旅游服务，收取代办费用的，应当亲自处理委托事务。因旅行社的过错给旅游者造成损失的，旅行社应当承担赔偿责任。"},{"i":75,"n":"第七十五条","txt":"住宿经营者应当按照旅游服务合同的约定为团队旅游者提供住宿服务。住宿经营者未能按照旅游服务合同提供服务的，应当为旅游者提供不低于原定标准的住宿服务，因此增加的费用由住宿经营者承担；但由于不可抗力、政府因公共利益需要采取措施造成不能提供服务的，住宿经营者应当协助安排旅游者住宿。"},{"i":76,"n":"第七十六条","txt":"县级以上人民政府统一负责旅游安全工作。县级以上人民政府有关部门依照法律、法规履行旅游安全监管职责。"},{"i":77,"n":"第七十七条","txt":"国家建立旅游目的地安全风险提示制度。旅游目的地安全风险提示的级别划分和实施程序，由国务院旅游主管部门会同有关部门制定。"},{"i":78,"n":"第七十八条","txt":"县级以上人民政府应当依法将旅游应急管理纳入政府应急管理体系，制定应急预案，建立旅游突发事件应对机制。"},{"i":79,"n":"第七十九条","txt":"旅游经营者应当严格执行安全生产管理和消防安全管理的法律、法规和国家标准、行业标准，具备相应的安全生产条件，制定旅游者安全保护制度和应急预案。"},{"i":80,"n":"第八十条","txt":"旅游经营者应当就旅游活动中的下列事项，以明示的方式事先向旅游者作出说明或者警示："},{"i":81,"n":"第八十一条","txt":"突发事件或者旅游安全事故发生后，旅游经营者应当立即采取必要的救助和处置措施，依法履行报告义务，并对旅游者作出妥善安排。"},{"i":82,"n":"第八十二条","txt":"旅游者在人身、财产安全遇有危险时，有权请求旅游经营者、当地政府和相关机构进行及时救助。"},{"i":83,"n":"第八十三条","txt":"县级以上人民政府旅游主管部门和有关部门依照本法和有关法律、法规的规定，在各自职责范围内对旅游市场实施监督管理。"},{"i":84,"n":"第八十四条","txt":"旅游主管部门履行监督管理职责，不得违反法律、行政法规的规定向监督管理对象收取费用。"},{"i":85,"n":"第八十五条","txt":"县级以上人民政府旅游主管部门有权对下列事项实施监督检查："},{"i":86,"n":"第八十六条","txt":"旅游主管部门和有关部门依法实施监督检查，其监督检查人员不得少于二人，并应当出示合法证件。监督检查人员少于二人或者未出示合法证件的，被检查单位和个人有权拒绝。"},{"i":87,"n":"第八十七条","txt":"对依法实施的监督检查，有关单位和个人应当配合，如实说明情况并提供文件、资料，不得拒绝、阻碍和隐瞒。"},{"i":88,"n":"第八十八条","txt":"县级以上人民政府旅游主管部门和有关部门，在履行监督检查职责中或者在处理举报、投诉时，发现违反本法规定行为的，应当依法及时作出处理；对不属于本部门职责范围的事项，应当及时书面通知并移交有关部门查处。"},{"i":89,"n":"第八十九条","txt":"县级以上地方人民政府建立旅游违法行为查处信息的共享机制，对需要跨部门、跨地区联合查处的违法行为，应当进行督办。"},{"i":90,"n":"第九十条","txt":"依法成立的旅游行业组织依照法律、行政法规和章程的规定，制定行业经营规范和服务标准，对其会员的经营行为和服务质量进行自律管理，组织开展职业道德教育和业务培训，提高从业人员素质。"},{"i":91,"n":"第九十一条","txt":"县级以上人民政府应当指定或者设立统一的旅游投诉受理机构。受理机构接到投诉，应当及时进行处理或者移交有关部门处理，并告知投诉者。"},{"i":92,"n":"第九十二条","txt":"旅游者与旅游经营者发生纠纷，可以通过下列途径解决："},{"i":93,"n":"第九十三条","txt":"消费者协会、旅游投诉受理机构和有关调解组织在双方自愿的基础上，依法对旅游者与旅游经营者之间的纠纷进行调解。"},{"i":94,"n":"第九十四条","txt":"旅游者与旅游经营者发生纠纷，旅游者一方人数众多并有共同请求的，可以推选代表人参加协商、调解、仲裁、诉讼活动。"},{"i":95,"n":"第九十五条","txt":"违反本法规定，未经许可经营旅行社业务的，由旅游主管部门或者市场监督管理部门责令改正，没收违法所得，并处一万元以上十万元以下罚款；违法所得十万元以上的，并处违法所得一倍以上五倍以下罚款；对有关责任人员，处二千元以上二万元以下罚款。"},{"i":96,"n":"第九十六条","txt":"旅行社违反本法规定，有下列行为之一的，由旅游主管部门责令改正，没收违法所得，并处五千元以上五万元以下罚款；情节严重的，责令停业整顿或者吊销旅行社业务经营许可证；对直接负责的主管人员和其他直接责任人员，处二千元以上二万元以下罚款："},{"i":97,"n":"第九十七条","txt":"旅行社违反本法规定，有下列行为之一的，由旅游主管部门或者有关部门责令改正，没收违法所得，并处五千元以上五万元以下罚款；违法所得五万元以上的，并处违法所得一倍以上五倍以下罚款；情节严重的，责令停业整顿或者吊销旅行社业务经营许可证；对直接负责的主管人员和其他直接责任人员，处二千元以上二万元以下罚款："},{"i":98,"n":"第九十八条","txt":"旅行社违反本法第三十五条规定的，由旅游主管部门责令改正，没收违法所得，责令停业整顿，并处三万元以上三十万元以下罚款；违法所得三十万元以上的，并处违法所得一倍以上五倍以下罚款；情节严重的，吊销旅行社业务经营许可证；对直接负责的主管人员和其他直接责任人员，没收违法所得，处二千元以上二万以下罚款，并暂扣或者吊销导游证。"},{"i":99,"n":"第九十九条","txt":"旅行社未履行本法第五十五条规定的报告义务的，由旅游主管部门处五千元以上五万元以下罚款；情节严重的，责令停业整顿或者吊销旅行社业务经营许可证；对直接负责的主管人员和其他直接责任人员，处二千元以上二万元以下罚款，并暂扣或者吊销导游证。"},{"i":100,"n":"第一百条","txt":"旅行社违反本法规定，有下列行为之一的，由旅游主管部门责令改正，处三万元以上三十万元以下罚款，并责令停业整顿；造成旅游者滞留等严重后果的，吊销旅行社业务经营许可证；对直接负责的主管人员和其他直接责任人员，处二千元以上二万元以下罚款，并暂扣或者吊销导游证："},{"i":101,"n":"第一百零一条","txt":"旅行社违反本法规定，安排旅游者参观或者参与违反我国法律、法规和社会公德的项目或者活动的，由旅游主管部门责令改正，没收违法所得，责令停业整顿，并处二万元以上二十万元以下罚款；情节严重的，吊销旅行社业务经营许可证；对直接负责的主管人员和其他直接责任人员，处二千元以上二万元以下罚款，并暂扣或者吊销导游证。"},{"i":102,"n":"第一百零二条","txt":"违反本法规定，未取得导游证或者不具备领队条件而从事导游、领队活动的，由旅游主管部门责令改正，没收违法所得，并处一千元以上一万元以下罚款，予以公告。"},{"i":103,"n":"第一百零三条","txt":"违反本法规定被吊销导游证的导游、领队和受到吊销旅行社业务经营许可证处罚的旅行社的有关管理人员，自处罚之日起未逾三年的，不得重新申请导游证或者从事旅行社业务。"},{"i":104,"n":"第一百零四条","txt":"旅游经营者违反本法规定，给予或者收受贿赂的，由市场监督管理部门依照有关法律、法规的规定处罚；情节严重的，并由旅游主管部门吊销旅行社业务经营许可证。"},{"i":105,"n":"第一百零五条","txt":"景区不符合本法规定的开放条件而接待旅游者的，由景区主管部门责令停业整顿直至符合开放条件，并处二万元以上二十万元以下罚款。"},{"i":106,"n":"第一百零六条","txt":"景区违反本法规定，擅自提高门票或者另行收费项目的价格，或者有其他价格违法行为的，由有关主管部门依照有关法律、法规的规定处罚。"},{"i":107,"n":"第一百零七条","txt":"旅游经营者违反有关安全生产管理和消防安全管理的法律、法规或者国家标准、行业标准的，由有关主管部门依照有关法律、法规的规定处罚。"},{"i":108,"n":"第一百零八条","txt":"对违反本法规定的旅游经营者及其从业人员，旅游主管部门和有关部门应当记入信用档案，向社会公布。"},{"i":109,"n":"第一百零九条","txt":"旅游主管部门和有关部门的工作人员在履行监督管理职责中，滥用职权、玩忽职守、徇私舞弊，尚不构成犯罪的，依法给予处分。"},{"i":110,"n":"第一百一十条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":111,"n":"第一百一十一条","txt":"本法下列用语的含义："},{"i":112,"n":"第一百一十二条","txt":"本法自2013年10月1日起施行。"}],"biaozhunhuafa":[{"i":1,"n":"第一条","txt":"为了加强标准化工作，提升产品和服务质量，促进科学技术进步，保障人身健康和生命财产安全，维护国家安全、生态环境安全，提高经济社会发展水平，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称标准（含标准样品），是指农业、工业、服务业以及社会事业等领域需要统一的技术要求。"},{"i":3,"n":"第三条","txt":"标准化工作的任务是制定标准、组织实施标准以及对标准的制定、实施进行监督。"},{"i":4,"n":"第四条","txt":"制定标准应当在科学技术研究成果和社会实践经验的基础上，深入调查论证，广泛征求意见，保证标准的科学性、规范性、时效性，提高标准质量。"},{"i":5,"n":"第五条","txt":"国务院标准化行政主管部门统一管理全国标准化工作。国务院有关行政主管部门分工管理本部门、本行业的标准化工作。"},{"i":6,"n":"第六条","txt":"国务院建立标准化协调机制，统筹推进标准化重大改革，研究标准化重大政策，对跨部门跨领域、存在重大争议标准的制定和实施进行协调。"},{"i":7,"n":"第七条","txt":"国家鼓励企业、社会团体和教育、科研机构等开展或者参与标准化工作。"},{"i":8,"n":"第八条","txt":"国家积极推动参与国际标准化活动，开展标准化对外合作与交流，参与制定国际标准，结合国情采用国际标准，推进中国标准与国外标准之间的转化运用。"},{"i":9,"n":"第九条","txt":"对在标准化工作中做出显著成绩的单位和个人，按照国家有关规定给予表彰和奖励。"},{"i":10,"n":"第十条","txt":"对保障人身健康和生命财产安全、国家安全、生态环境安全以及满足经济社会管理基本需要的技术要求，应当制定强制性国家标准。"},{"i":11,"n":"第十一条","txt":"对满足基础通用、与强制性国家标准配套、对各有关行业起引领作用等需要的技术要求，可以制定推荐性国家标准。"},{"i":12,"n":"第十二条","txt":"对没有推荐性国家标准、需要在全国某个行业范围内统一的技术要求，可以制定行业标准。"},{"i":13,"n":"第十三条","txt":"为满足地方自然条件、风俗习惯等特殊技术要求，可以制定地方标准。"},{"i":14,"n":"第十四条","txt":"对保障人身健康和生命财产安全、国家安全、生态环境安全以及经济社会发展所急需的标准项目，制定标准的行政主管部门应当优先立项并及时完成。"},{"i":15,"n":"第十五条","txt":"制定强制性标准、推荐性标准，应当在立项时对有关行政主管部门、企业、社会团体、消费者和教育、科研机构等方面的实际需求进行调查，对制定标准的必要性、可行性进行论证评估；在制定过程中，应当按照便捷有效的原则采取多种方式征求意见，组织对标准相关事项进行调查分析、实验、论证，并做到有关标准之间的协调配套。"},{"i":16,"n":"第十六条","txt":"制定推荐性标准，应当组织由相关方组成的标准化技术委员会，承担标准的起草、技术审查工作。制定强制性标准，可以委托相关标准化技术委员会承担标准的起草、技术审查工作。未组成标准化技术委员会的，应当成立专家组承担相关标准的起草、技术审查工作。标准化技术委员会和专家组的组成应当具有广泛代表性。"},{"i":17,"n":"第十七条","txt":"强制性标准文本应当免费向社会公开。国家推动免费向社会公开推荐性标准文本。"},{"i":18,"n":"第十八条","txt":"国家鼓励学会、协会、商会、联合会、产业技术联盟等社会团体协调相关市场主体共同制定满足市场和创新需要的团体标准，由本团体成员约定采用或者按照本团体的规定供社会自愿采用。"},{"i":19,"n":"第十九条","txt":"企业可以根据需要自行制定企业标准，或者与其他企业联合制定企业标准。"},{"i":20,"n":"第二十条","txt":"国家支持在重要行业、战略性新兴产业、关键共性技术等领域利用自主创新技术制定团体标准、企业标准。"},{"i":21,"n":"第二十一条","txt":"推荐性国家标准、行业标准、地方标准、团体标准、企业标准的技术要求不得低于强制性国家标准的相关技术要求。"},{"i":22,"n":"第二十二条","txt":"制定标准应当有利于科学合理利用资源，推广科学技术成果，增强产品的安全性、通用性、可替换性，提高经济效益、社会效益、生态效益，做到技术上先进、经济上合理。"},{"i":23,"n":"第二十三条","txt":"国家推进标准化军民融合和资源共享，提升军民标准通用化水平，积极推动在国防和军队建设中采用先进适用的民用标准，并将先进适用的军用标准转化为民用标准。"},{"i":24,"n":"第二十四条","txt":"标准应当按照编号规则进行编号。标准的编号规则由国务院标准化行政主管部门制定并公布。"},{"i":25,"n":"第二十五条","txt":"不符合强制性标准的产品、服务，不得生产、销售、进口或者提供。"},{"i":26,"n":"第二十六条","txt":"出口产品、服务的技术要求，按照合同的约定执行。"},{"i":27,"n":"第二十七条","txt":"国家实行团体标准、企业标准自我声明公开和监督制度。企业应当公开其执行的强制性标准、推荐性标准、团体标准或者企业标准的编号和名称；企业执行自行制定的企业标准的，还应当公开产品、服务的功能指标和产品的性能指标。国家鼓励团体标准、企业标准通过标准信息公共服务平台向社会公开。"},{"i":28,"n":"第二十八条","txt":"企业研制新产品、改进产品，进行技术改造，应当符合本法规定的标准化要求。"},{"i":29,"n":"第二十九条","txt":"国家建立强制性标准实施情况统计分析报告制度。"},{"i":30,"n":"第三十条","txt":"国务院标准化行政主管部门根据标准实施信息反馈、评估、复审情况，对有关标准之间重复交叉或者不衔接配套的，应当会同国务院有关行政主管部门作出处理或者通过国务院标准化协调机制处理。"},{"i":31,"n":"第三十一条","txt":"县级以上人民政府应当支持开展标准化试点示范和宣传工作，传播标准化理念，推广标准化经验，推动全社会运用标准化方式组织生产、经营、管理和服务，发挥标准对促进转型升级、引领创新驱动的支撑作用。"},{"i":32,"n":"第三十二条","txt":"县级以上人民政府标准化行政主管部门、有关行政主管部门依据法定职责，对标准的制定进行指导和监督，对标准的实施进行监督检查。"},{"i":33,"n":"第三十三条","txt":"国务院有关行政主管部门在标准制定、实施过程中出现争议的，由国务院标准化行政主管部门组织协商；协商不成的，由国务院标准化协调机制解决。"},{"i":34,"n":"第三十四条","txt":"国务院有关行政主管部门、设区的市级以上地方人民政府标准化行政主管部门未依照本法规定对标准进行编号、复审或者备案的，国务院标准化行政主管部门应当要求其说明情况，并限期改正。"},{"i":35,"n":"第三十五条","txt":"任何单位或者个人有权向标准化行政主管部门、有关行政主管部门举报、投诉违反本法规定的行为。"},{"i":36,"n":"第三十六条","txt":"生产、销售、进口产品或者提供服务不符合强制性标准，或者企业生产的产品、提供的服务不符合其公开标准的技术要求的，依法承担民事责任。"},{"i":37,"n":"第三十七条","txt":"生产、销售、进口产品或者提供服务不符合强制性标准的，依照《中华人民共和国产品质量法》、《中华人民共和国进出口商品检验法》、《中华人民共和国消费者权益保护法》等法律、行政法规的规定查处，记入信用记录，并依照有关法律、行政法规的规定予以公示；构成犯罪的，依法追究刑事责任。"},{"i":38,"n":"第三十八条","txt":"企业未依照本法规定公开其执行的标准的，由标准化行政主管部门责令限期改正；逾期不改正的，在标准信息公共服务平台上公示。"},{"i":39,"n":"第三十九条","txt":"国务院有关行政主管部门、设区的市级以上地方人民政府标准化行政主管部门制定的标准不符合本法第二十一条第一款、第二十二条第一款规定的，应当及时改正；拒不改正的，由国务院标准化行政主管部门公告废止相关标准；对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":40,"n":"第四十条","txt":"国务院有关行政主管部门、设区的市级以上地方人民政府标准化行政主管部门未依照本法规定对标准进行编号或者备案，又未依照本法第三十四条的规定改正的，由国务院标准化行政主管部门撤销相关标准编号或者公告废止未备案标准；对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":41,"n":"第四十一条","txt":"国务院标准化行政主管部门未依照本法第十条第二款规定对制定强制性国家标准的项目予以立项，制定的标准不符合本法第二十一条第一款、第二十二条第一款规定，或者未依照本法规定对标准进行编号、复审或者予以备案的，应当及时改正；对负有责任的领导人员和直接责任人员可以依法给予处分。"},{"i":42,"n":"第四十二条","txt":"社会团体、企业未依照本法规定对团体标准或者企业标准进行编号的，由标准化行政主管部门责令限期改正；逾期不改正的，由省级以上人民政府标准化行政主管部门撤销相关标准编号，并在标准信息公共服务平台上公示。"},{"i":43,"n":"第四十三条","txt":"标准化工作的监督、管理人员滥用职权、玩忽职守、徇私舞弊的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":44,"n":"第四十四条","txt":"军用标准的制定、实施和监督办法，由国务院、中央军事委员会另行制定。"},{"i":45,"n":"第四十五条","txt":"本法自2018年1月1日起施行。"}],"minyonghangkongfa":[{"i":1,"n":"第一条","txt":"为了维护国家的领空主权和民用航空权利，保障民用航空活动安全、有序进行，保护民用航空活动当事人各方的合法权益，促进民用航空事业高质量发展，制定本法。"},{"i":2,"n":"第二条","txt":"中华人民共和国的领陆和领水之上的空域为中华人民共和国领空。中华人民共和国对领空享有完全的、排他的主权。"},{"i":3,"n":"第三条","txt":"民用航空事业坚持中国共产党的领导，坚持以人民为中心，坚持安全第一，统筹发展和安全，为全面建设社会主义现代化国家提供有力支撑。"},{"i":4,"n":"第四条","txt":"国务院民用航空主管部门对全国民用航空活动实施统一监督管理；根据法律、行政法规和国务院的决定、命令，在本部门的权限内，发布有关民用航空活动的规定、决定。"},{"i":5,"n":"第五条","txt":"国务院民用航空主管部门会同国务院有关部门依据国民经济和社会发展规划、综合交通运输规划，编制民用航空发展规划。"},{"i":6,"n":"第六条","txt":"投资公共航空运输、通用航空、民用机场、空中交通管理等领域，应当符合法律、行政法规和国务院民用航空主管部门有关规定。"},{"i":7,"n":"第七条","txt":"国家加强民用航空基础设施建设，鼓励和支持民用航空科学技术研究，发展民用航空教育事业，加大民用航空专业人才培养力度，提升民用航空安全保障水平和服务质量，推动民用航空事业高质量发展。"},{"i":8,"n":"第八条","txt":"从事民用航空活动应当遵守生态环境保护的法律、法规和国家有关规定，控制并减少污染物和温室气体排放。"},{"i":9,"n":"第九条","txt":"从事民用航空生产经营活动的单位应当落实安全生产主体责任，建立健全安全生产规章制度，保证安全投入，改善安全生产条件，构建实施民用航空安全风险分级管控和隐患排查治理双重预防机制，提高民用航空活动安全生产水平。"},{"i":10,"n":"第十条","txt":"对在民用航空事业发展、民用航空安全等工作中做出突出贡献的单位和个人，按照国家有关规定给予表彰、奖励。"},{"i":11,"n":"第十一条","txt":"本法所称民用航空器，是指除用于执行军事、海关、警务、消防救援飞行任务外的航空器。"},{"i":12,"n":"第十二条","txt":"经国务院民用航空主管部门依法进行国籍登记的民用航空器，具有中华人民共和国国籍，由国务院民用航空主管部门发给国籍登记证书。"},{"i":13,"n":"第十三条","txt":"民用航空器不得具有双重国籍。未注销外国国籍的民用航空器不得在中华人民共和国申请国籍登记。"},{"i":14,"n":"第十四条","txt":"中华人民共和国国家机构的民用航空器应当进行中华人民共和国国籍登记。"},{"i":15,"n":"第十五条","txt":"依法取得中华人民共和国国籍的民用航空器，应当标明规定的国籍标志和登记标志。"},{"i":16,"n":"第十六条","txt":"本法规定的对民用航空器的权利，包括对民用航空器构架、发动机、螺旋桨、无线电设备和其他一切为了在民用航空器上使用的，无论安装于其上或者暂时拆离的物品的权利。"},{"i":17,"n":"第十七条","txt":"民用航空器权利人可以就下列权利分别向国务院民用航空主管部门申请办理权利登记；未经登记，不得对抗善意第三人："},{"i":18,"n":"第十八条","txt":"国务院民用航空主管部门设立民用航空器权利登记簿。同一民用航空器的权利登记事项应当记载于同一权利登记簿中。"},{"i":19,"n":"第十九条","txt":"除民用航空器经依法强制拍卖外，在已经登记的民用航空器权利得到补偿或者民用航空器权利人同意之前，民用航空器的国籍登记或者权利登记不得转移至国外。"},{"i":20,"n":"第二十条","txt":"民用航空器优先权，是指债权人依照本法第二十一条规定，向民用航空器所有人、承租人提出请求，对产生该请求的民用航空器具有优先受偿的权利。"},{"i":21,"n":"第二十一条","txt":"下列各项债权具有民用航空器优先权："},{"i":22,"n":"第二十二条","txt":"民用航空器优先权应当通过人民法院扣押产生优先权的民用航空器行使。"},{"i":23,"n":"第二十三条","txt":"民用航空器优先权自援救或者保管维护工作终了之日起满三个月时终止；但是，债权人就其债权已经依照本法第二十一条规定登记，并具有下列情形之一的除外："},{"i":24,"n":"第二十四条","txt":"为了债权人的共同利益，在执行人民法院判决以及拍卖过程中产生的费用，应当从民用航空器拍卖所得价款中先行拨付。"},{"i":25,"n":"第二十五条","txt":"从事民用航空器及其发动机、螺旋桨（以下统称民用航空产品）和民用航空产品零部件设计、设计更改的机构，应当按照国务院民用航空主管部门的规定，建立相应的设计保证系统，并向国务院民用航空主管部门申请取得设计机构许可证书。"},{"i":26,"n":"第二十六条","txt":"设计民用航空产品，应当按照国务院民用航空主管部门的规定申请取得型号合格证书。"},{"i":27,"n":"第二十七条","txt":"对依照本法第二十六条第一款、第三款规定已取得相应证书的民用航空产品设计进行更改，应当由取得设计机构许可证书的机构进行，并按照国务院民用航空主管部门的规定申请取得补充型号合格证书或者改装设计批准证书；但是，相关更改属于设计小改的除外。"},{"i":28,"n":"第二十八条","txt":"从事民用航空产品和零部件生产的机构，应当按照国务院民用航空主管部门的规定建立生产质量系统，并申请取得生产机构许可证书。"},{"i":29,"n":"第二十九条","txt":"仅设计和生产装于已获得型号合格证书或者型号认可证书的民用航空产品后只构成设计小改的民用航空产品零部件，按照国务院民用航空主管部门的规定无需取得设计机构许可证书和生产机构许可证书的，应当向国务院民用航空主管部门申请取得零部件制造人许可证书。"},{"i":30,"n":"第三十条","txt":"从事民用航空产品和零部件维修的机构，应当按照国务院民用航空主管部门的规定申请取得维修机构许可证书。"},{"i":31,"n":"第三十一条","txt":"具有中华人民共和国国籍的民用航空器，应当按照国务院民用航空主管部门的规定申请取得适航证书，方可飞行。尚未取得适航证书，为生产试飞等目的需要进行飞行的，按照国务院民用航空主管部门的规定申请取得特许飞行证书后，可以在许可范围内从事飞行活动。"},{"i":32,"n":"第三十二条","txt":"从事民用航空化学产品设计、生产和民用航空油料供应、测试的单位，应当按照国务院民用航空主管部门的规定申请取得相关许可证书。"},{"i":33,"n":"第三十三条","txt":"民用航空器的所有人或者承租人应当按照适航证书规定的使用范围使用民用航空器，做好民用航空器的维修保养工作，保证民用航空器处于适航状态；民用航空产品和零部件需要维修的，应当按照国务院民用航空主管部门的规定由取得相关许可的机构或者人员实施。"},{"i":34,"n":"第三十四条","txt":"从事民用无人驾驶航空器的设计、生产、进口、维修和飞行活动，应当按照国家有关规定向国务院民用航空主管部门申请取得适航许可，按照规定无需取得适航许可的除外。"},{"i":35,"n":"第三十五条","txt":"国务院根据本法制定民用航空器适航管理规定。"},{"i":36,"n":"第三十六条","txt":"本法所称航空人员，是指下列从事民用航空活动的空勤人员和地面人员："},{"i":37,"n":"第三十七条","txt":"乘务员应当接受专门训练，取得公共航空运输企业颁发的训练合格证书，其他航空人员应当接受专门训练，经考核合格，取得国务院民用航空主管部门颁发的执照，方可履行相应的工作职责。"},{"i":38,"n":"第三十八条","txt":"从事飞行活动时，驾驶员、飞行机械员和航空安全员应当携带执照和体格检查合格证书，乘务员应当携带训练合格证书和体格检查合格证书，并接受国务院民用航空主管部门的查验。"},{"i":39,"n":"第三十九条","txt":"航空人员应当按照国务院民用航空主管部门的规定接受训练以及定期或者不定期的检查、考核，检查、考核合格后方可继续履行相应的工作职责。"},{"i":40,"n":"第四十条","txt":"为民用航空器驾驶员、维修人员、飞行签派员提供执照及资格训练的机构，应当按照国务院民用航空主管部门的规定申请取得相应许可证书，并在许可的范围内按照训练大纲实施训练。"},{"i":41,"n":"第四十一条","txt":"用于满足民用航空器驾驶员训练、考试或者检查要求的飞行模拟训练设备，应当通过国务院民用航空主管部门的鉴定，取得飞行模拟训练设备合格证书，方可投入使用。"},{"i":42,"n":"第四十二条","txt":"民用航空器机组由机长和其他空勤人员组成。机长应当由具有独立驾驶该型号民用航空器的技术和经验的驾驶员担任。"},{"i":43,"n":"第四十三条","txt":"民用航空器的操作由机长负责，机长应当严格履行职责，保护民用航空器及其所载人员和财产的安全。"},{"i":44,"n":"第四十四条","txt":"飞行前，机长应当对民用航空器实施必要的检查；未经检查，不得起飞。"},{"i":45,"n":"第四十五条","txt":"飞行中，对于任何破坏民用航空器、扰乱民用航空器内秩序、危害民用航空器所载人员或者财产安全以及其他危及飞行安全的行为，在保证安全的前提下，机长有权采取包括必要的管束措施在内的合理措施，必要时可以请求或者授权旅客提供协助。"},{"i":46,"n":"第四十六条","txt":"机长发现机组人员不适宜执行飞行任务的，为保证飞行安全，有权提出调整。"},{"i":47,"n":"第四十七条","txt":"民用航空器遇险时，机长有权采取一切必要措施，并指挥机组人员和民用航空器上其他人员采取抢救措施。在必须撤离遇险民用航空器的紧急情况下，机长应当采取措施，首先组织旅客安全离开民用航空器；未经机长允许，机组人员不得擅自离开民用航空器；机长应当最后离开民用航空器。"},{"i":48,"n":"第四十八条","txt":"民用航空器发生事故，机长应当直接或者通过空中交通管制单位，将事故情况及时、如实报告国务院民用航空主管部门。"},{"i":49,"n":"第四十九条","txt":"机长收到船舶或者其他航空器的遇险信号，或者发现遇险的船舶、航空器及其人员，应当将遇险情况及时报告就近的空中交通管制单位并给予可能的合理的援助。"},{"i":50,"n":"第五十条","txt":"飞行中，机长因故不能履行职务的，由仅次于机长职务的驾驶员代理机长；在下一个经停地起飞前，民用航空器所有人或者承租人应当指派新机长接任。"},{"i":51,"n":"第五十一条","txt":"只有一名驾驶员，不需配备其他空勤人员的民用航空器，本节对机长的规定，适用于该驾驶员。"},{"i":52,"n":"第五十二条","txt":"本法所称民用机场，是指供民用航空器起飞、降落、滑行、停放以及进行其他活动使用的划定区域，包括附属的建筑物、装置和设施。"},{"i":53,"n":"第五十三条","txt":"民用机场的规划、建设和运行应当统筹安排、合理布局，依法落实国防要求，提高安全水平和运行效率，促进民用航空发展与生态环境保护相协调。"},{"i":54,"n":"第五十四条","txt":"县级以上地方人民政府应当将本行政区域内民用机场场址和总体规划纳入本级国土空间规划统筹安排，并根据机场运行安全、国防要求以及生态环境保护的需要，依法对周边区域实行规划控制，依法划定噪声敏感建筑物禁止建设区域和限制建设区域。"},{"i":55,"n":"第五十五条","txt":"新建、扩建民用机场，应当由民用机场所在地县级以上地方人民政府发布项目建设公告。"},{"i":56,"n":"第五十六条","txt":"民用机场所在地有关地方人民政府应当会同地区民用航空管理机构，按照国家有关规定划定民用机场净空保护区域，并向社会公布。"},{"i":57,"n":"第五十七条","txt":"民用机场所在地地方无线电管理机构应当会同地区民用航空管理机构，按照国家无线电管理的有关规定和标准划定民用机场电磁环境保护区域，并向社会公布。"},{"i":58,"n":"第五十八条","txt":"民用机场项目建设公告发布前，在依法划定的民用机场范围内和民用机场净空保护区域、电磁环境保护区域内存在的可能影响飞行安全的建筑物、构筑物、树木、照明设施、无线电台（站）和其他障碍物体，应当在规定的期限内清除；当事人逾期未清除，经催告仍不清除的，由机场所在地县级以上地方人民政府依法予以清除。对由此造成的损失，应当依法给予补偿或者采取其他补救措施。"},{"i":59,"n":"第五十九条","txt":"民用机场项目建设公告发布后，任何单位或者个人违反本法和有关法规的规定，在依法划定的民用机场范围内和民用机场净空保护区域、电磁环境保护区域内修建、种植或者设置可能影响飞行安全的障碍物体的，由机场所在地县级以上地方人民政府作出要求当事人在规定期限内履行排除妨碍、恢复原状等义务的行政决定，当事人逾期不履行，经催告仍不履行的，由机场所在地县级以上地方人民政府依法代履行。障碍物体造成的损失以及代履行的费用，由修建、种植或者设置该障碍物体的单位或者个人承担。"},{"i":60,"n":"第六十条","txt":"民用机场运营人应当按照国务院民用航空主管部门的规定，设置必要设施、采取适当措施，维护民用机场运营秩序、保障民用机场运营安全。"},{"i":61,"n":"第六十一条","txt":"国家在民用机场以及周边一定范围的区域依法划定无人驾驶航空器管制空域，并向社会公布。"},{"i":62,"n":"第六十二条","txt":"民用航空器在民用机场运行的时刻应当按照公开、公平、公正的原则，在机场容量范围内协调配置。具体管理办法由国务院民用航空主管部门制定。"},{"i":63,"n":"第六十三条","txt":"民用航空器使用民用机场及其助航设施，应当缴纳使用费、服务费；使用费、服务费的收费标准，由国务院民用航空主管部门制定。"},{"i":64,"n":"第六十四条","txt":"民用机场废弃或者改作他用，应当按照国家有关规定办理报批手续。"},{"i":65,"n":"第六十五条","txt":"全国运输机场的布局和建设规划，由国务院发展改革部门会同国务院民用航空主管部门制定，并按照国家规定的程序，经批准后组织实施。"},{"i":66,"n":"第六十六条","txt":"新建、改建和扩建运输机场，应当符合依法制定的运输机场布局和建设规划以及相关技术标准，按照国家有关规定报经批准后实施。"},{"i":67,"n":"第六十七条","txt":"运输机场应当依法取得机场运营许可证，方可开放运营。"},{"i":68,"n":"第六十八条","txt":"设立国际机场，由机场所在地省、自治区、直辖市人民政府报请国务院批准。"},{"i":69,"n":"第六十九条","txt":"通用机场根据业务类型、建设规模和标准，实施分类分级管理，具体办法由国务院民用航空主管部门制定。"},{"i":70,"n":"第七十条","txt":"省、自治区、直辖市人民政府应当综合考虑本行政区域内人口、土地、空域资源、交通运输、产业基础等条件，因地制宜推进通用机场建设，合理确定通用机场建设规模和标准。"},{"i":71,"n":"第七十一条","txt":"省、自治区、直辖市人民政府发展改革部门组织编制本行政区域内通用机场布局规划，征得地区民用航空管理机构和其他相关单位同意后，报省、自治区、直辖市人民政府批准。"},{"i":72,"n":"第七十二条","txt":"国务院民用航空主管部门规定的对公众开放的通用机场应当依法取得机场运营许可证，方可开放运营。"},{"i":73,"n":"第七十三条","txt":"国家对空域实行统一管理。国家空中交通管理机构依照法律、行政法规和国家有关规定管理全国空域资源。"},{"i":74,"n":"第七十四条","txt":"划分空域，应当兼顾民用航空和国防安全、低空经济发展需要以及公众利益，使空域得到合理、安全、充分、有效利用。"},{"i":75,"n":"第七十五条","txt":"空域管理的具体办法，由国务院、中央军事委员会制定。"},{"i":76,"n":"第七十六条","txt":"在一个划定的管制空域内，由一个空中交通管制单位负责该空域内的航空器的空中交通管制。"},{"i":77,"n":"第七十七条","txt":"民用航空器在管制空域内进行飞行活动，应当按照有关规定取得空中交通管制单位的许可。"},{"i":78,"n":"第七十八条","txt":"从事飞行的民用航空器，应当携带下列文件："},{"i":79,"n":"第七十九条","txt":"民用航空器应当按照空中交通管制单位指定的航路和飞行高度飞行，因故确需偏离指定的航路或者改变飞行高度飞行的，应当取得空中交通管制单位的许可。"},{"i":80,"n":"第八十条","txt":"在中华人民共和国境内飞行的民用航空器，必须遵守统一的飞行规则。"},{"i":81,"n":"第八十一条","txt":"民用航空器机组人员的飞行时间、值勤时间、休息时间应当符合国务院民用航空主管部门的规定。"},{"i":82,"n":"第八十二条","txt":"民用航空器除按照国家有关规定经特别批准外，不得飞入空中禁区；除遵守规定的限制条件外，不得飞入空中限制区。"},{"i":83,"n":"第八十三条","txt":"民用航空器不得飞越城市上空；但是，有下列情形之一的除外："},{"i":84,"n":"第八十四条","txt":"飞行中，民用航空器不得投掷物品；但是，有下列情形之一的除外："},{"i":85,"n":"第八十五条","txt":"民用航空器未经批准不得飞入或者飞出中华人民共和国领空。"},{"i":86,"n":"第八十六条","txt":"空中交通管制单位应当按照分工为飞行中的航空器提供空中交通服务，包括空中交通管制服务、飞行情报服务和告警服务。"},{"i":87,"n":"第八十七条","txt":"空中交通管制单位发现民用航空器偏离指定航路、迷失航向时，应当迅速采取一切必要措施，使其回归航路。"},{"i":88,"n":"第八十八条","txt":"空中交通管制员值勤时间不得超过国务院民用航空主管部门规定的时限。"},{"i":89,"n":"第八十九条","txt":"空中交通管制单位、公共航空运输企业、从事定期运输的通用航空企业等单位应当采取有效措施，实时掌握民用航空器飞行动态，保障民用航空活动安全。"},{"i":90,"n":"第九十条","txt":"空域内应当设置必要的符合国家规定标准和技术规范的通信、导航、监视、气象设备。"},{"i":91,"n":"第九十一条","txt":"空域内影响飞行安全的自然障碍物体，应当在航图上标明；空域内影响飞行安全的人工障碍物体，应当设置航空障碍灯和标志，并使其保持正常状态。"},{"i":92,"n":"第九十二条","txt":"在距离航路边界三十公里以内的地带，禁止修建靶场和其他可能影响飞行安全的设施；但是，平射轻武器靶场除外。"},{"i":93,"n":"第九十三条","txt":"在依法划定的民用机场及其净空保护区域外，对可能影响飞行安全的高大建筑物或者设施，应当按照国家有关规定设置航空障碍灯和标志，并使其保持正常状态。"},{"i":94,"n":"第九十四条","txt":"任何可能影响飞行安全的活动，应当依法获得批准，并采取确保飞行安全的必要措施，方可进行。"},{"i":95,"n":"第九十五条","txt":"国务院民用航空主管部门应当依法对民用航空无线电台（站）和分配给民用航空系统使用的专用频率实施管理，并制定相关管理规定。"},{"i":96,"n":"第九十六条","txt":"信息通信企业应当对民用航空电信传输优先提供服务。"},{"i":97,"n":"第九十七条","txt":"民用航空器使用空中交通服务设施应当缴纳使用费、服务费；使用费、服务费的收费标准，由国务院民用航空主管部门制定。"},{"i":98,"n":"第九十八条","txt":"公共航空运输，是指以营利为目的，使用国务院民用航空主管部门规定的民用航空器运送旅客、行李、邮件或者货物的民用航空活动。"},{"i":99,"n":"第九十九条","txt":"本章适用于公共航空运输企业使用民用航空器经营的旅客、行李或者货物的运输，包括免费运输。"},{"i":100,"n":"第一百条","txt":"本法所称国内航空运输，是指根据当事人订立的航空运输合同，运输的出发地点、约定的经停地点和目的地点均在中华人民共和国境内的运输。"},{"i":101,"n":"第一百零一条","txt":"航空运输合同各方认为几个连续的航空运输承运人办理的运输是一项单一业务活动的，无论其形式是以一个合同订立或者数个合同订立，应当视为一项不可分割的运输。"},{"i":102,"n":"第一百零二条","txt":"企业从事公共航空运输，应当向国务院民用航空主管部门申请取得公共航空运输企业经营许可证和运行合格证。"},{"i":103,"n":"第一百零三条","txt":"取得公共航空运输企业经营许可证，应当具备下列条件："},{"i":104,"n":"第一百零四条","txt":"取得公共航空运输运行合格证，应当具备下列条件："},{"i":105,"n":"第一百零五条","txt":"国务院民用航空主管部门应当自受理公共航空运输企业经营许可证申请之日起六个月内、受理公共航空运输运行合格证申请之日起十二个月内作出批准或者不予批准的决定。决定批准的，颁发相应许可证件；不予批准的，书面告知申请人并说明理由。"},{"i":106,"n":"第一百零六条","txt":"公共航空运输企业申请经营定期航班运输（以下简称航班运输）的航线，暂停、终止经营的航线，应当报经国务院民用航空主管部门批准。"},{"i":107,"n":"第一百零七条","txt":"公共航空运输企业的营业收费项目，由国务院民用航空主管部门确定。"},{"i":108,"n":"第一百零八条","txt":"公共航空运输企业从事不定期运输，应当经国务院民用航空主管部门批准，并不得影响航班运输的正常经营。"},{"i":109,"n":"第一百零九条","txt":"公共航空运输企业不得运输法律、行政法规禁止运输的物品。"},{"i":110,"n":"第一百一十条","txt":"公共航空运输企业从事危险品运输，应当遵守国家有关规定，并取得危险品航空运输许可。"},{"i":111,"n":"第一百一十一条","txt":"公共航空运输企业不得运输拒绝接受安全检查的旅客，不得违反国家有关规定运输未经安全检查的行李。"},{"i":112,"n":"第一百一十二条","txt":"公共航空运输企业从事国际航空运输的民用航空器及其所载人员、行李、货物应当接受移民管理、海关等主管部门依法实施的检查、检疫；检查、检疫应当避免不必要的延误。"},{"i":113,"n":"第一百一十三条","txt":"公共航空运输企业应当依照有关法律、行政法规的规定优先运输邮件。"},{"i":114,"n":"第一百一十四条","txt":"公共航空运输企业应当就所从事的公共航空运输的旅客、行李、货物以及可能对第三人承担的赔偿责任依法投保责任保险或者取得相应的财务担保。"},{"i":115,"n":"第一百一十五条","txt":"承运人运送旅客，应当出具客票。"},{"i":116,"n":"第一百一十六条","txt":"客票是航空旅客运输合同订立和运输合同条件的初步证据。"},{"i":117,"n":"第一百一十七条","txt":"承运人应当就每一件托运行李向旅客出具行李票。"},{"i":118,"n":"第一百一十八条","txt":"货物运输应当出具航空货运单，并经双方签名、盖章后生效。"},{"i":119,"n":"第一百一十九条","txt":"托运人应当填写航空货运单，连同货物交给承运人。"},{"i":120,"n":"第一百二十条","txt":"航空货运单应当包括的内容由国务院民用航空主管部门规定，至少应当包括以下内容："},{"i":121,"n":"第一百二十一条","txt":"托运人应当对航空货运单上关于货物的说明和声明的正确性负责。"},{"i":122,"n":"第一百二十二条","txt":"航空货运单是航空货物运输合同订立和运输条件以及承运人接受货物的初步证据。"},{"i":123,"n":"第一百二十三条","txt":"托运人在履行航空货物运输合同规定的义务的条件下，有权在出发地机场或者目的地机场将货物提回，或者在途中经停时中止运输，或者在目的地点或者途中要求将货物交给非航空货运单上指定的收货人，或者要求将货物运回出发地机场；但是，托运人不得因行使此种权利而使承运人或者其他托运人遭受损失，并应当偿付由此产生的费用。"},{"i":124,"n":"第一百二十四条","txt":"除本法第一百二十三条所列情形外，收货人于货物到达目的地点，并在缴付应付款项和履行运输条件后，有权要求承运人交付货物。"},{"i":125,"n":"第一百二十五条","txt":"托运人和收货人在履行航空货物运输合同规定的义务的条件下，无论为本人或者他人的利益，可以以本人的名义分别行使本法第一百二十三条和第一百二十四条所赋予的权利。"},{"i":126,"n":"第一百二十六条","txt":"托运人应当提供必需的资料和文件，以便在货物交付收货人前完成法律、行政法规规定的有关手续；因没有此种资料、文件，或者此种资料、文件不充足或者不符合规定造成的损失，除由于承运人或者其受雇人、代理人的过错造成的外，托运人应当对承运人承担责任。"},{"i":127,"n":"第一百二十七条","txt":"客票、行李票、航空货运单等运输凭证应当为书面形式。"},{"i":128,"n":"第一百二十八条","txt":"因发生在民用航空器上或者在旅客上、下民用航空器过程中的事故，造成旅客人身伤亡的，承运人应当承担责任；但是，旅客的人身伤亡完全是由于旅客本人的健康状况造成的，承运人不承担责任。"},{"i":129,"n":"第一百二十九条","txt":"因发生在民用航空器上或者在旅客上、下民用航空器过程中的事件，造成旅客非托运行李（包括个人物件）毁灭、遗失或者损坏的，承运人应当对因其过错或者其受雇人、代理人过错造成的损失承担责任。"},{"i":130,"n":"第一百三十条","txt":"本法所称航空运输期间，是指在机场内、民用航空器上或者机场外降落的任何地点，托运行李、货物处于承运人掌管之下的全部期间。"},{"i":131,"n":"第一百三十一条","txt":"因发生在航空运输期间的事件，造成货物毁灭、遗失或者损坏的，承运人应当承担责任；但是，承运人证明货物的毁灭、遗失或者损坏完全是由于下列原因之一造成的，不承担责任："},{"i":132,"n":"第一百三十二条","txt":"旅客、行李或者货物在航空运输中因延误造成的损失，承运人应当承担责任；但是，承运人证明本人或者其受雇人、代理人为了避免损失的发生，已经采取一切合理措施或者不可能采取此种措施的，不承担责任。"},{"i":133,"n":"第一百三十三条","txt":"在旅客、行李运输中，经承运人证明，损失是由索赔人或者代行权利人的过错造成或者促成的，应当根据造成或者促成此种损失的过错的程度，相应免除或者减轻承运人的责任。旅客以外的其他人就旅客人身伤亡提出赔偿请求时，经承运人证明，人身伤亡是旅客本人的过错造成或者促成的，同样应当根据造成或者促成此种损失的过错的程度，相应免除或者减轻承运人的责任。"},{"i":134,"n":"第一百三十四条","txt":"对于依据本法第一百二十八条规定所产生的赔偿责任，按照造成损害的事故发生时我国参加的相关国际民用航空公约规定的赔偿责任限额确定。"},{"i":135,"n":"第一百三十五条","txt":"在航空运输中，行李、货物毁灭、遗失、损坏，或者旅客、行李和货物延误所造成的损失，承运人的赔偿责任，以造成损害的事件或者延误发生时我国参加的相关国际民用航空公约规定的赔偿责任限额为限。"},{"i":136,"n":"第一百三十六条","txt":"本法第一百三十四条第一款和第一百三十五条规定的赔偿责任限额，由国务院民用航空主管部门公布。"},{"i":137,"n":"第一百三十七条","txt":"旅客或者托运人在交运托运行李或者货物时，特别声明在目的地点交付时的利益，并在必要时支付附加费的，除承运人证明旅客或者托运人声明的金额高于托运行李或者货物在目的地点交付时的实际利益外，承运人应当在声明金额范围内承担责任。"},{"i":138,"n":"第一百三十八条","txt":"任何旨在免除本法规定的承运人责任或者降低本法规定的赔偿责任限额的条款，均属无效；但是，此种条款的无效，不影响整个航空运输合同的效力。"},{"i":139,"n":"第一百三十九条","txt":"就航空运输中的损失向承运人的受雇人、代理人提起诉讼时，该受雇人、代理人证明其是在受雇、代理范围内行事的，有权援用承运人依据本法可以援用的有关赔偿责任限制的规定。"},{"i":140,"n":"第一百四十条","txt":"经证明，航空运输中的损失是由于承运人或者其受雇人、代理人的故意或者明知可能造成损失而轻率地作为或者不作为造成的，承运人无权援用本法有关旅客延误以及行李运输赔偿责任限制的规定。"},{"i":141,"n":"第一百四十一条","txt":"有关航空运输中发生的损失的诉讼，不论其根据如何，只能依照本法规定的条件和赔偿责任限额提出，但是不妨碍谁有权提起诉讼以及他们各自的权利。"},{"i":142,"n":"第一百四十二条","txt":"旅客或者收货人收受托运行李或者货物而未提出异议，为托运行李或者货物已经完好交付并与运输凭证相符的初步证据。"},{"i":143,"n":"第一百四十三条","txt":"航空运输的诉讼时效期间为二年，自民用航空器到达目的地点、应当到达目的地点或者运输终止之日起计算。"},{"i":144,"n":"第一百四十四条","txt":"由几个航空承运人办理的连续运输，接受旅客、行李或者货物的每一个承运人应当受本法规定的约束，并就其根据合同办理的运输区段作为运输合同的订约一方。"},{"i":145,"n":"第一百四十五条","txt":"本法所称缔约承运人，是指以本人名义与旅客或者托运人，或者与旅客或者托运人的代理人，订立本章调整的航空运输合同的人。"},{"i":146,"n":"第一百四十六条","txt":"除本节另有规定外，缔约承运人和实际承运人都应当受本章规定的约束。缔约承运人应当对合同约定的全部运输负责。实际承运人应当对其履行的运输负责。"},{"i":147,"n":"第一百四十七条","txt":"实际承运人的作为和不作为，实际承运人的受雇人、代理人在受雇、代理范围内实施的与实际承运人履行运输义务有关的行为，视为缔约承运人的行为，相应法律后果由缔约承运人承担。"},{"i":148,"n":"第一百四十八条","txt":"依照本章规定提出的异议或者发出的指示，无论是向缔约承运人还是向实际承运人提出或者发出的，具有同等效力；但是，本法第一百二十三条规定的指示，仅在向缔约承运人发出时有效。"},{"i":149,"n":"第一百四十九条","txt":"实际承运人的受雇人、代理人或者缔约承运人的受雇人、代理人，证明其是在受雇、代理范围内行事的，就实际承运人履行的运输而言，有权援用本法第一百三十四条、第一百三十五条有关赔偿责任限制的规定，但是依照本法规定不得援用赔偿责任限制规定的除外。"},{"i":150,"n":"第一百五十条","txt":"对于实际承运人履行的运输，实际承运人、缔约承运人以及他们的在受雇、代理范围内行事的受雇人、代理人的赔偿总额，不得超过依照本法得以从缔约承运人或者实际承运人获得赔偿的最高数额；同时，其中任何人都不承担超过对其适用的赔偿责任限额。"},{"i":151,"n":"第一百五十一条","txt":"对实际承运人履行的运输提起的诉讼，可以分别对实际承运人或者缔约承运人提起，也可以同时对实际承运人和缔约承运人提起；被提起诉讼的承运人有权要求另一承运人参加诉讼。"},{"i":152,"n":"第一百五十二条","txt":"公共航空运输企业、运输机场运营人应当以保证飞行安全和航班正常，提供良好服务为准则，采取有效措施，提高运输服务质量。"},{"i":153,"n":"第一百五十三条","txt":"公共航空运输企业制定运输总条件等格式条款，应当遵循公平原则确定当事人之间的权利和义务，予以公布，并在售票等环节中明确告知旅客。"},{"i":154,"n":"第一百五十四条","txt":"公共航空运输企业、运输机场运营人应当合理安排运力、调配资源，加强对设施设备的检查和维护，减少因自身原因导致的航班延误或者取消。"},{"i":155,"n":"第一百五十五条","txt":"公共航空运输企业、航空销售代理人、航空销售网络平台经营者、航空信息企业等参与民用航空运输服务的单位应当按照个人信息保护有关法律、行政法规的规定，履行个人信息保护义务。"},{"i":156,"n":"第一百五十六条","txt":"公共航空运输企业、运输机场运营人、航空销售网络平台经营者应当以适当方式向社会公布投诉受理方式等信息，按照国务院民用航空主管部门的规定及时受理、处理投诉，并及时向投诉人反馈相关情况。"},{"i":157,"n":"第一百五十七条","txt":"通用航空，是指使用民用航空器从事公共航空运输以外的民用航空活动。"},{"i":158,"n":"第一百五十八条","txt":"从事经营性通用航空活动的，应当具备下列条件，并向国务院民用航空主管部门申请取得通用航空运营许可证："},{"i":159,"n":"第一百五十九条","txt":"通用航空企业从事经营性通用航空活动，应当与用户订立书面合同，但是紧急情况下的应急救援飞行除外。"},{"i":160,"n":"第一百六十条","txt":"组织实施通用航空飞行时，应当采取有效措施，保证飞行安全，保护环境和生态平衡，防止对环境、居民、作物或者牲畜等造成损害。"},{"i":161,"n":"第一百六十一条","txt":"从事通用航空活动的，应当投保第三人责任险。"},{"i":162,"n":"第一百六十二条","txt":"从事通用航空定期运输的，还应当遵守本法第六章关于公共航空运输的有关规定。"},{"i":163,"n":"第一百六十三条","txt":"国务院民用航空主管部门依照本法和有关法律、行政法规的规定负责民用航空安全保卫管理工作，国务院公安部门依照本法和有关法律、行政法规的规定负责民用航空安全保卫管理有关工作，其他有关部门和单位应当密切配合、协调联动，按照职责共同维护民用航空安全和秩序。"},{"i":164,"n":"第一百六十四条","txt":"有关公安机关应当依法维护民用机场内的安全和秩序，预防、制止和惩治危害民用航空运输活动的违法犯罪行为。"},{"i":165,"n":"第一百六十五条","txt":"旅客、行李和货物应当接受安全检查；但是，国务院规定免检的除外。"},{"i":166,"n":"第一百六十六条","txt":"民用航空安全检查应当使用经国务院民用航空主管部门许可的安全检查仪器设备。"},{"i":167,"n":"第一百六十七条","txt":"公共航空运输企业、运输机场运营人、民用航空空中交通管制单位等应当按照国家民用航空安全保卫方案，制定本单位的安全保卫方案并报国务院民用航空主管部门备案。"},{"i":168,"n":"第一百六十八条","txt":"民用机场运营人应当按照国务院民用航空主管部门的规定，采取措施保障机场内人员和财产的安全。"},{"i":169,"n":"第一百六十九条","txt":"航空人员、民用航空安全保卫人员以及其他需要进入民用机场控制区的相关人员应当依法接受安全背景审查。"},{"i":170,"n":"第一百七十条","txt":"机长和机组其他人员，应当严格履行安全保卫职责，维护民用航空器内秩序，保护民用航空器及其所载人员、财产的安全。"},{"i":171,"n":"第一百七十一条","txt":"禁止实施下列妨害民用航空运输安全和秩序的行为："},{"i":172,"n":"第一百七十二条","txt":"通用航空活动安全保卫工作应当根据通用航空活动类型，在安全保卫机构、方案、措施等方面实施分类分级管理。具体办法由国务院民用航空主管部门制定。"},{"i":173,"n":"第一百七十三条","txt":"国务院有关部门、空中交通管制单位、航空运输企业、民用机场运营人及其他有关单位应当依照法律、行政法规和国家有关规定，制定民用航空器事故应急预案，并定期开展应急演练。"},{"i":174,"n":"第一百七十四条","txt":"民用航空器遇到紧急情况时，应当发送信号，并向空中交通管制单位报告，提出援救请求；空中交通管制单位应当立即通知搜寻援救协调中心。民用航空器在海上遇到紧急情况时，还应当向船舶和国家海上搜寻援救组织发送信号。"},{"i":175,"n":"第一百七十五条","txt":"发现民用航空器遇到紧急情况或者收听到民用航空器遇到紧急情况的信号的单位或者个人，应当立即通知有关的搜寻援救协调中心、海上搜寻援救组织或者当地人民政府。"},{"i":176,"n":"第一百七十六条","txt":"收到通知的搜寻援救协调中心、海上搜寻援救组织和地方人民政府，应当立即组织搜寻援救。"},{"i":177,"n":"第一百七十七条","txt":"公共航空运输企业、运输机场，以及从事定期运输的通用航空企业、通用机场应当根据国务院民用航空主管部门的规定，制定民用航空器事故家属援助计划。"},{"i":178,"n":"第一百七十八条","txt":"执行搜寻援救任务的单位或者个人，应当尽力抢救民用航空器所载人员，按照规定对民用航空器采取抢救措施并保护现场，保存证据。"},{"i":179,"n":"第一百七十九条","txt":"民用航空器事故根据造成的损害后果分为特别重大事故、重大事故、较大事故和一般事故。事故等级划分的人身伤亡标准依照有关安全生产的法律、行政法规的规定确定；事故等级划分的直接经济损失标准，由国务院民用航空主管部门会同国务院有关部门根据民用航空器事故中的特殊情况确定，报国务院批准后公布施行。"},{"i":180,"n":"第一百八十条","txt":"特别重大民用航空器事故由国务院或者国务院授权的部门组织事故调查组进行调查。"},{"i":181,"n":"第一百八十一条","txt":"事故调查组可以根据调查需要，依法要求有关单位提供相关记录、设备、资料，询问当事人等有关人员，查阅、检验和留存证据。有关单位和人员应当如实提供现场情况和事故相关信息。"},{"i":182,"n":"第一百八十二条","txt":"为了查明民用航空器事故原因开展的技术调查工作应当与其他事故调查工作相互协调。开展民用航空器事故技术调查的具体办法由国务院民用航空主管部门制定。"},{"i":183,"n":"第一百八十三条","txt":"组织事故调查的单位应当自民用航空器事故发生之日起十二个月内依法公布事故调查报告。特殊情况下不能按期公布事故调查报告的，应当及时公布调查进展情况。"},{"i":184,"n":"第一百八十四条","txt":"我国参加或者组织的对境外发生的民用航空器事故的调查工作，按照我国缔结或者参加的国际条约的规定执行。"},{"i":185,"n":"第一百八十五条","txt":"因飞行中的民用航空器或者从飞行中的民用航空器上落下的人或者物，造成第三人人身伤亡或者财产损害的，受害人有权获得赔偿；但是，所受损害并非造成损害的事故的直接后果，或者所受损害仅是民用航空器依照国家有关空中交通规则在空中通过造成的，受害人无权要求赔偿。"},{"i":186,"n":"第一百八十六条","txt":"本法第一百八十五条规定的赔偿责任，由民用航空器运营人承担。"},{"i":187,"n":"第一百八十七条","txt":"民用航空器所有人、出租人或者保留民用航空器所有权或者持有其担保权益的融资人，或者其受雇人、代理人，不是本法第一百八十六条规定的民用航空器运营人的，不对第三人所受的损害承担赔偿责任，但是故意造成此种损害的人除外。"},{"i":188,"n":"第一百八十八条","txt":"未经对民用航空器有航行控制权的人同意而使用民用航空器，对第三人造成损害的，有航行控制权的人除证明本人已经适当注意防止此种使用外，应当与该非法使用人承担连带责任。"},{"i":189,"n":"第一百八十九条","txt":"对于武装冲突或者骚乱直接造成的损害，以及由核事件造成的核损害，依照本章规定应当承担责任的人不承担责任。"},{"i":190,"n":"第一百九十条","txt":"依照本章规定应当承担责任的人证明损害是完全由于受害人或者其受雇人、代理人的过错造成的，免除其赔偿责任；应当承担责任的人证明损害是部分由于受害人或者其受雇人、代理人的过错造成的，相应减轻其赔偿责任。但是，损害是由于受害人的受雇人、代理人的过错造成的，受害人证明其受雇人、代理人的行为超出其所授权的范围的，不免除或者不减轻应当承担责任的人的赔偿责任。"},{"i":191,"n":"第一百九十一条","txt":"造成损害的事件涉及两架或者两架以上民用航空器，有关民用航空器运营人应当对第三人所受的损害承担连带责任。"},{"i":192,"n":"第一百九十二条","txt":"本法第一百八十六条第四款和第一百八十八条规定的人，享有依照本章规定民用航空器运营人所能援用的抗辩权。"},{"i":193,"n":"第一百九十三条","txt":"本章不妨碍依照本章规定应当对损害承担责任的人向他人追偿的权利。"},{"i":194,"n":"第一百九十四条","txt":"在中华人民共和国境内起飞或者降落的民用航空器，其运营人应当投保第三人责任险或者取得相应的财务担保。"},{"i":195,"n":"第一百九十五条","txt":"保险人和担保人除享有与民用航空器运营人相同的抗辩权，以及对于伪造证件进行抗辩的权利外，对于依照本章规定提出的赔偿请求只能进行下列抗辩："},{"i":196,"n":"第一百九十六条","txt":"仅在下列情形下，受害人可以直接对保险人或者担保人提起诉讼："},{"i":197,"n":"第一百九十七条","txt":"依照本法第一百九十四条规定提供的保险或者担保，应当被专门指定优先支付本章规定的赔偿。"},{"i":198,"n":"第一百九十八条","txt":"保险人应当支付给民用航空器运营人的款项，在本章规定的第三人的赔偿请求未满足前，不受民用航空器运营人的债权人的扣留和处理。"},{"i":199,"n":"第一百九十九条","txt":"第三人损害赔偿的诉讼时效期间为二年，自损害发生之日起计算；但是，在任何情况下，时效期间不得超过自损害发生之日起三年。"},{"i":200,"n":"第二百条","txt":"本章所称第三人，是指除民用航空器运营人、旅客、货物的托运人及收货人以外的其他人。"},{"i":201,"n":"第二百零一条","txt":"外国民用航空器在中华人民共和国境内从事民用航空活动，适用本章规定；本章没有规定的，适用本法其他有关规定。"},{"i":202,"n":"第二百零二条","txt":"外国民用航空器根据其国籍登记国政府与中华人民共和国政府签订的协定、协议的规定，或者经国务院民用航空主管部门批准或者接受，方可飞入、飞出中华人民共和国领空和在中华人民共和国境内飞行、降落。"},{"i":203,"n":"第二百零三条","txt":"外国民用航空器飞入中华人民共和国领空，其运营人应当提供有关证明书，证明其已经投保第三人责任险或者已经取得相应的财务担保；其运营人未提供有关证明书的，国务院民用航空主管部门有权拒绝其飞入中华人民共和国领空。"},{"i":204,"n":"第二百零四条","txt":"中华人民共和国政府根据与外国政府签订的协定、协议开放航权，允许该外国的民用航空器运营人经营相关国际航班运输。"},{"i":205,"n":"第二百零五条","txt":"外国民用航空器运营人制定运输总条件等格式条款的，应当公布中文版本，并设立具备中文能力的专门机构或者指定专人负责受理投诉。"},{"i":206,"n":"第二百零六条","txt":"外国民用航空器运营人，不得经营中华人民共和国境内两点之间的航空运输。"},{"i":207,"n":"第二百零七条","txt":"外国民用航空器应当按照国务院民用航空主管部门批准的班期时刻或者飞行计划飞行；变更班期时刻或者飞行计划的，其运营人应当获得国务院民用航空主管部门的批准；因故变更或者取消飞行的，其运营人应当及时报告国务院民用航空主管部门。"},{"i":208,"n":"第二百零八条","txt":"外国民用航空器应当在国务院民用航空主管部门指定的国际机场起飞或者降落。"},{"i":209,"n":"第二百零九条","txt":"国务院民用航空主管部门和其他主管机关，有权在外国民用航空器降落或者起飞时查验本法第七十八条规定的文件。"},{"i":210,"n":"第二百一十条","txt":"外国民用航空器国籍登记国颁发或者核准的民用航空器适航证书、机组人员合格证书和执照，中华人民共和国政府承认其有效；但是，颁发或者核准此项证书或者执照的要求，应当等于或者高于国际民用航空组织制定的最低标准。"},{"i":211,"n":"第二百一十一条","txt":"外国民用航空器在中华人民共和国境内使用无线电设备，应当遵守中华人民共和国无线电管理有关规定。"},{"i":212,"n":"第二百一十二条","txt":"外国民用航空器在中华人民共和国搜寻援救区内遇险，其所有人或者国籍登记国参加搜寻援救工作，应当经国务院民用航空主管部门批准或者按照两国政府协议进行。"},{"i":213,"n":"第二百一十三条","txt":"外国民用航空器在中华人民共和国境内发生事故，其国籍登记国和其他有关国家可以按照我国缔结或者参加的国际条约的规定参加事故调查。事故调查报告和调查结果，由国务院民用航空主管部门告知该外国民用航空器的国籍登记国和其他有关国家。"},{"i":214,"n":"第二百一十四条","txt":"民用航空器所有权的取得、转让和消灭，适用民用航空器国籍登记国法律。"},{"i":215,"n":"第二百一十五条","txt":"民用航空器抵押权适用民用航空器国籍登记国法律。"},{"i":216,"n":"第二百一十六条","txt":"民用航空器优先权适用受理案件的法院所在地法律。"},{"i":217,"n":"第二百一十七条","txt":"民用航空运输合同当事人可以选择合同适用的法律，但是法律另有规定的除外；合同当事人没有选择的，适用与合同有最密切联系的国家的法律。"},{"i":218,"n":"第二百一十八条","txt":"民用航空器对第三人的损害赔偿，适用侵权行为地法律。"},{"i":219,"n":"第二百一十九条","txt":"依照本章规定适用外国法律或者国际惯例，不得危害中华人民共和国主权、安全、发展利益，不得违背中华人民共和国的社会公共利益。"},{"i":220,"n":"第二百二十条","txt":"国家完善以企业为主体、市场为导向、产学研相结合的民用航空制造业创新体系，支持关键核心技术研发，提高大型飞机和先进发动机等研发设计能力，推进科技创新成果产业化，促进民用航空制造业发展，为民用航空活动提供安全、先进、绿色、经济、适用的民用航空产品。"},{"i":221,"n":"第二百二十一条","txt":"国家完善民用航空器适航审定组织体系和标准规范，加强适航审定人才培养，建立健全基于风险的分类分级适航管理方式，提升适航审定能力和水平。"},{"i":222,"n":"第二百二十二条","txt":"民用机场是公共基础设施。各级人民政府应当采取必要措施，支持民用机场的建设、运营和维护。"},{"i":223,"n":"第二百二十三条","txt":"国家采取措施优化航线网络，提高资源配置效率，构建覆盖广泛、优质高效的民用航空服务体系。"},{"i":224,"n":"第二百二十四条","txt":"国家鼓励发展通用航空，加快构建通用航空基础设施网络，培育通用航空市场。"},{"i":225,"n":"第二百二十五条","txt":"国家采取措施优化低空空域资源配置，推动建设民用低空飞行和应用相关监管服务平台，建立健全适应低空经济发展要求的适航审定、飞行管理等制度和标准。"},{"i":226,"n":"第二百二十六条","txt":"国家坚持平等互利、合作共赢的方针，促进民用航空领域国际合作，积极参与国际民用航空标准制定，推进民用航空运输市场高水平开放，提升民用航空国际竞争力。"},{"i":227,"n":"第二百二十七条","txt":"国务院民用航空主管部门应当加强对民用航空活动的监督检查，按照分类分级监督管理的要求，根据民用航空活动类别、单位信用记录和民用航空管理需要等因素，合理确定检查频次和检查方式。"},{"i":228,"n":"第二百二十八条","txt":"国务院民用航空主管部门履行监督检查职责，可以采取下列措施："},{"i":229,"n":"第二百二十九条","txt":"遇有突发事件、特殊保障条件等情形，必须采取不同于国家有关民用航空器和民用机场运营相关规定的特别措施的，应当经国务院民用航空主管部门批准。"},{"i":230,"n":"第二百三十条","txt":"国务院民用航空主管部门应当运用大数据等现代信息技术手段，提高监督管理工作能力和水平，并依照有关法律、行政法规的规定做好数据安全保护工作。"},{"i":231,"n":"第二百三十一条","txt":"从事民用航空生产经营活动的单位应当建立民用航空安全信息收集、分析和发布制度，并按照国务院民用航空主管部门的规定报告和发布安全信息。"},{"i":232,"n":"第二百三十二条","txt":"国务院民用航空主管部门、地方各级人民政府及其有关部门，以及从事民用航空生产经营活动的单位应当加强对民用航空法律、法规和安全知识的宣传教育，提高全社会的民用航空安全意识。"},{"i":233,"n":"第二百三十三条","txt":"投资民用航空业违反国务院民用航空主管部门有关规定的，由国务院民用航空主管部门责令限期改正，没收违法所得，并处二万元以上二十万元以下的罚款；逾期未改正的，并处二十万元以上五十万元以下的罚款；情节特别严重的，可以吊销公共航空运输企业、通用航空企业、民用机场的相关许可证件。"},{"i":234,"n":"第二百三十四条","txt":"违反本法规定，未经许可从事民用航空产品和零部件设计、生产、维修活动，民用航空化学产品设计、生产或者民用航空油料供应、测试活动的，由国务院民用航空主管部门责令停止违法活动，没收违法所得，并处十万元以上五十万元以下的罚款；情节严重的，并处五十万元以上二百万元以下的罚款。"},{"i":235,"n":"第二百三十五条","txt":"取得本法规定的设计、生产、维修许可证书，民用航空化学产品设计、生产或者民用航空油料供应、测试相关许可证书的企业，因质量问题造成严重事故的，由国务院民用航空主管部门责令停业整顿；情节严重的，可以吊销相关许可证件。"},{"i":236,"n":"第二百三十六条","txt":"违反本法规定，未取得适航证书、特许飞行证书，或者超出证书有效期、规定范围进行飞行活动的，由国务院民用航空主管部门责令停止飞行，没收违法所得，并处二十万元以上二百万元以下的罚款；情节严重的，可以吊销相关许可证件。"},{"i":237,"n":"第二百三十七条","txt":"违反本法规定，未取得相关航空人员执照、证书，或者超出执照、证书载明事项范围从事民用航空活动的，由国务院民用航空主管部门责令停止民用航空活动，处一万元以上五万元以下的罚款；情节严重的，处五万元以上二十万元以下的罚款；对超出执照、证书载明事项范围从事民用航空活动的航空人员，可以吊销相关执照或者责令所属单位取消训练合格证书。"},{"i":238,"n":"第二百三十八条","txt":"违反本法规定，未经许可为民用航空器驾驶员、维修人员、飞行签派员提供执照和资格训练的，由国务院民用航空主管部门责令停止违法行为，没收违法所得，并处十万元以上一百万元以下的罚款。"},{"i":239,"n":"第二百三十九条","txt":"违反本法规定，在依法划定的民用机场范围内和民用机场净空保护区域、电磁环境保护区域内从事禁止性活动的，由机场所在地县级以上地方人民政府责令停止违法行为，给予通报批评；情节严重的，对生产经营单位处五万元以上五十万元以下的罚款，对个人处二千元以上二万元以下的罚款。"},{"i":240,"n":"第二百四十条","txt":"违反本法规定，运输机场或者对公众开放的通用机场未取得机场运营许可证开放运营的，由国务院民用航空主管部门责令停止开放运营，没收违法所得，并处十万元以上一百万元以下的罚款。"},{"i":241,"n":"第二百四十一条","txt":"违反本法规定，民用航空器未按照有关规定经空中交通管制单位许可进行飞行活动的，由国务院民用航空主管部门责令停止飞行，对该民用航空器所有人或者承租人处五万元以上五十万元以下的罚款，暂扣相关许可证件一个月至三个月，情节严重的，吊销相关许可证件；对机长给予警告，处一万元以上五万元以下的罚款，暂扣执照一个月至六个月，情节严重的，吊销执照。"},{"i":242,"n":"第二百四十二条","txt":"违反本法规定，有下列情形之一的，由国务院民用航空主管部门对民用航空器的机长给予警告，暂扣执照一个月至六个月；情节严重的，吊销执照："},{"i":243,"n":"第二百四十三条","txt":"违反本法规定，民用航空器的机长或者机组其他人员有下列情形之一的，由国务院民用航空主管部门给予警告，暂扣相关执照或者训练合格证书一个月至六个月；情节严重的，吊销相关执照或者责令所属单位取消训练合格证书："},{"i":244,"n":"第二百四十四条","txt":"违反本法规定，空中交通管制员值勤时间超过规定时限的，由国务院民用航空主管部门对民用航空空中交通管制单位处一万元以上十万元以下的罚款。"},{"i":245,"n":"第二百四十五条","txt":"违反本法规定，使用未经许可或者未经飞行校验验证合格的通信、导航、监视设备的，由国务院民用航空主管部门责令限期改正，处五万元以上二十万元以下的罚款。"},{"i":246,"n":"第二百四十六条","txt":"违反本法规定，运输法律、行政法规禁止运输的物品，或者未经许可从事危险品航空运输活动的，由国务院民用航空主管部门责令停止违法行为，没收违法所得，并处五十万元以上二百万元以下的罚款；情节严重的，可以吊销违法公共航空运输企业、通用航空企业的相关许可证件。"},{"i":247,"n":"第二百四十七条","txt":"违反本法规定，运输机场、公共航空运输企业不依法开展安全检查工作的，由国务院民用航空主管部门责令改正，处十万元以上五十万元以下的罚款，对直接负责的主管人员和其他直接责任人员，处一万元以上五万元以下的罚款；情节严重的，处五十万元以上二百万元以下的罚款，对直接负责的主管人员和其他直接责任人员，处五万元以上二十万元以下的罚款；情节特别严重的，可以吊销违法运输机场、公共航空运输企业的相关许可证件。"},{"i":248,"n":"第二百四十八条","txt":"违反本法规定，未经许可从事公共航空运输的，由国务院民用航空主管部门责令停止违法行为，没收违法所得，并处五十万元以上二百万元以下的罚款。"},{"i":249,"n":"第二百四十九条","txt":"公共航空运输企业、通用航空企业、民用机场航班运行效率较低、不符合航班正常管理要求或者安全运营保障能力不足的，国务院民用航空主管部门可以暂停受理其新增业务申请或者限缩其业务范围。"},{"i":250,"n":"第二百五十条","txt":"违反本法规定，未制定民用航空安全保卫方案并备案的，由国务院民用航空主管部门责令限期改正；逾期未改正的，处一万元以上十万元以下的罚款；情节严重的，处十万元以上二十万元以下的罚款。"},{"i":251,"n":"第二百五十一条","txt":"违反本法规定，公共航空运输企业和从事定期运输的通用航空企业有下列情形之一的，由国务院民用航空主管部门责令限期改正；逾期未改正的，处五万元以上二十万元以下的罚款；情节严重的，处二十万元以上一百万元以下的罚款；情节特别严重的，可以吊销相关许可证件："},{"i":252,"n":"第二百五十二条","txt":"违反本法规定，实施妨害民用航空运输安全和秩序的行为情节严重的，国务院民用航空主管部门可以在一定期限内限制其乘坐民用航空器。"},{"i":253,"n":"第二百五十三条","txt":"违反本法规定，从事民用航空生产经营活动的单位有下列情形之一的，由国务院民用航空主管部门责令限期改正；逾期未改正的，处五万元以上二十万元以下的罚款："},{"i":254,"n":"第二百五十四条","txt":"国务院民用航空主管部门和地区民用航空管理机构的工作人员玩忽职守、滥用职权、徇私舞弊的，依法给予处分。"},{"i":255,"n":"第二百五十五条","txt":"违反本法规定，实施危害民用航空安全或者扰乱民用航空秩序的行为，构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":256,"n":"第二百五十六条","txt":"航空人员因故意犯罪被判处刑罚的，由国务院民用航空主管部门吊销相关执照。"},{"i":257,"n":"第二百五十七条","txt":"国家根据民用航空事业发展需要设立政府性基金，具体执行期限由国务院规定。"},{"i":258,"n":"第二百五十八条","txt":"国务院、中央军事委员会对无人驾驶航空器的管理另有规定的，从其规定。"},{"i":259,"n":"第二百五十九条","txt":"取得中华人民共和国国籍的民用航空器，由在其他国家有主营业地或者永久居所的运营人根据租用、包用或者互换民用航空器的协议或者其他类似协议运营的，中华人民共和国政府可以按照与该外国政府签订的协定、协议，将本法规定的飞行管理、无线电台执照、适航证书以及机组人员执照的管理职责和义务转移至该外国，中华人民共和国对已转移的职责和义务的责任相应解除。"},{"i":260,"n":"第二百六十条","txt":"中华人民共和国缔结或者参加的国际条约同本法有不同规定的，适用国际条约的规定；但是，中华人民共和国声明保留的条款除外。"},{"i":261,"n":"第二百六十一条","txt":"任何国家或者地区在民用航空运输和民用航空器制造相关领域对中华人民共和国采取歧视性的禁止、限制或者其他类似措施的，中华人民共和国可以根据实际情况对有关国家或者地区采取相应的措施。"},{"i":262,"n":"第二百六十二条","txt":"本法自2026年7月1日起施行。"}],"minyingjingjicujinfa":[{"i":1,"n":"第一条","txt":"为优化民营经济发展环境，保证各类经济组织公平参与市场竞争，促进民营经济健康发展和民营经济人士健康成长，构建高水平社会主义市场经济体制，发挥民营经济在国民经济和社会发展中的重要作用，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"促进民营经济发展工作坚持中国共产党的领导，坚持以人民为中心，坚持中国特色社会主义制度，确保民营经济发展的正确政治方向。"},{"i":3,"n":"第三条","txt":"民营经济是社会主义市场经济的重要组成部分，是推进中国式现代化的生力军，是高质量发展的重要基础，是推动我国全面建成社会主义现代化强国、实现中华民族伟大复兴的重要力量。促进民营经济持续、健康、高质量发展，是国家长期坚持的重大方针政策。"},{"i":4,"n":"第四条","txt":"国务院和县级以上地方人民政府将促进民营经济发展工作纳入国民经济和社会发展规划，建立促进民营经济发展工作协调机制，制定完善政策措施，协调解决民营经济发展中的重大问题。"},{"i":5,"n":"第五条","txt":"民营经济组织及其经营者应当拥护中国共产党的领导，坚持中国特色社会主义制度，积极投身社会主义现代化强国建设。"},{"i":6,"n":"第六条","txt":"民营经济组织及其经营者从事生产经营活动，应当遵守法律法规，遵守社会公德、商业道德，诚实守信、公平竞争，履行社会责任，保障劳动者合法权益，维护国家利益和社会公共利益，接受政府和社会监督。"},{"i":7,"n":"第七条","txt":"工商业联合会发挥在促进民营经济健康发展和民营经济人士健康成长中的重要作用，加强民营经济组织经营者思想政治建设，引导民营经济组织依法经营，提高服务民营经济水平。"},{"i":8,"n":"第八条","txt":"加强对民营经济组织及其经营者创新创造等先进事迹的宣传报道，支持民营经济组织及其经营者参与评选表彰，引导形成尊重劳动、尊重创造、尊重企业家的社会环境，营造全社会关心、支持、促进民营经济发展的氛围。"},{"i":9,"n":"第九条","txt":"国家建立健全民营经济统计制度，对民营经济发展情况进行统计分析，定期发布有关信息。"},{"i":10,"n":"第十条","txt":"国家实行全国统一的市场准入负面清单制度。市场准入负面清单以外的领域，包括民营经济组织在内的各类经济组织可以依法平等进入。"},{"i":11,"n":"第十一条","txt":"各级人民政府及其有关部门落实公平竞争审查制度，制定涉及经营主体生产经营活动的政策措施应当经过公平竞争审查，并定期评估，及时清理、废除含有妨碍全国统一市场和公平竞争内容的政策措施，保障民营经济组织公平参与市场竞争。"},{"i":12,"n":"第十二条","txt":"国家保障民营经济组织依法平等使用资金、技术、人力资源、数据、土地及其他自然资源等各类生产要素和公共服务资源，依法平等适用国家支持发展的政策。"},{"i":13,"n":"第十三条","txt":"各级人民政府及其有关部门依照法定权限，在制定、实施政府资金安排、土地供应、排污指标、公共数据开放、资质许可、标准制定、项目申报、职称评定、评优评先、人力资源等方面的政策措施时，平等对待民营经济组织。"},{"i":14,"n":"第十四条","txt":"公共资源交易活动应当公开透明、公平公正，依法平等对待包括民营经济组织在内的各类经济组织。"},{"i":15,"n":"第十五条","txt":"反垄断和反不正当竞争执法机构按照职责权限，预防和制止市场经济活动中的垄断、不正当竞争行为，对滥用行政权力排除、限制竞争的行为依法处理，为民营经济组织提供良好的市场环境。"},{"i":16,"n":"第十六条","txt":"支持民营经济组织参与国家重大战略和重大工程。支持民营经济组织在战略性新兴产业、未来产业等领域投资和创业，鼓励开展传统产业技术改造和转型升级，参与现代化基础设施投资建设。"},{"i":17,"n":"第十七条","txt":"国务院有关部门根据国家重大发展战略、发展规划、产业政策等，统筹研究制定促进民营经济投资政策措施，发布鼓励民营经济投资重大项目信息，引导民营经济投资重点领域。"},{"i":18,"n":"第十八条","txt":"支持民营经济组织通过多种方式盘活存量资产，提高再投资能力，提升资产质量和效益。"},{"i":19,"n":"第十九条","txt":"各级人民政府及其有关部门在项目推介对接、前期工作和报建审批事项办理、要素获取和政府投资支持等方面，为民营经济组织投资提供规范高效便利的服务。"},{"i":20,"n":"第二十条","txt":"国务院有关部门依据职责发挥货币政策工具和宏观信贷政策的激励约束作用，按照市场化、法治化原则，对金融机构向小型微型民营经济组织提供金融服务实施差异化政策，督促引导金融机构合理设置不良贷款容忍度、建立健全尽职免责机制、提升专业服务能力，提高为民营经济组织提供金融服务的水平。"},{"i":21,"n":"第二十一条","txt":"银行业金融机构等依据法律法规，接受符合贷款业务需要的担保方式，并为民营经济组织提供应收账款、仓单、股权、知识产权等权利质押贷款。"},{"i":22,"n":"第二十二条","txt":"国家推动构建完善民营经济组织融资风险的市场化分担机制，支持银行业金融机构与融资担保机构有序扩大业务合作，共同服务民营经济组织。"},{"i":23,"n":"第二十三条","txt":"金融机构在依法合规前提下，按照市场化、可持续发展原则开发和提供适合民营经济特点的金融产品和服务，为资信良好的民营经济组织融资提供便利条件，增强信贷供给、贷款周期与民营经济组织融资需求、资金使用周期的适配性，提升金融服务可获得性和便利度。"},{"i":24,"n":"第二十四条","txt":"金融机构在授信、信贷管理、风控管理、服务收费等方面应当平等对待民营经济组织。"},{"i":25,"n":"第二十五条","txt":"健全多层次资本市场体系，支持符合条件的民营经济组织通过发行股票、债券等方式平等获得直接融资。"},{"i":26,"n":"第二十六条","txt":"建立健全信用信息归集共享机制，支持征信机构为民营经济组织融资提供征信服务，支持信用评级机构优化民营经济组织的评级方法，增加信用评级有效供给，为民营经济组织获得融资提供便利。"},{"i":27,"n":"第二十七条","txt":"国家鼓励、支持民营经济组织在推动科技创新、培育新质生产力、建设现代化产业体系中积极发挥作用。引导民营经济组织根据国家战略需要、行业发展趋势和世界科技前沿，加强基础性、前沿性研究，开发关键核心技术、共性基础技术和前沿交叉技术，推动科技创新和产业创新融合发展，催生新产业、新模式、新动能。"},{"i":28,"n":"第二十八条","txt":"支持民营经济组织参与国家科技攻关项目，支持有能力的民营经济组织牵头承担国家重大技术攻关任务，向民营经济组织开放国家重大科研基础设施，支持公共研究开发平台、共性技术平台开放共享，为民营经济组织技术创新平等提供服务，鼓励各类企业和高等学校、科研院所、职业学校与民营经济组织创新合作机制，开展技术交流和成果转移转化，推动产学研深度融合。"},{"i":29,"n":"第二十九条","txt":"支持民营经济组织依法参与数字化、智能化共性技术研发和数据要素市场建设，依法合理使用数据，对开放的公共数据资源依法进行开发利用，增强数据要素共享性、普惠性、安全性，充分发挥数据赋能作用。"},{"i":30,"n":"第三十条","txt":"国家保障民营经济组织依法参与标准制定工作，强化标准制定的信息公开和社会监督。"},{"i":31,"n":"第三十一条","txt":"支持民营经济组织加强新技术应用，开展新技术、新产品、新服务、新模式应用试验，发挥技术市场、中介服务机构作用，通过多种方式推动科技成果应用推广。"},{"i":32,"n":"第三十二条","txt":"鼓励民营经济组织积极培养使用知识型、技能型、创新型人才，在关键岗位、关键工序培养使用高技能人才，推动产业工人队伍建设。"},{"i":33,"n":"第三十三条","txt":"国家加强对民营经济组织及其经营者原始创新的保护。加大创新成果知识产权保护力度，实施知识产权侵权惩罚性赔偿制度，依法查处侵犯商标专用权、专利权、著作权和侵犯商业秘密、仿冒混淆等违法行为。"},{"i":34,"n":"第三十四条","txt":"民营经济组织中的中国共产党的组织和党员，按照中国共产党章程和有关党内法规开展党的活动，在促进民营经济组织健康发展中发挥党组织的政治引领作用和党员先锋模范作用。"},{"i":35,"n":"第三十五条","txt":"民营经济组织应当围绕国家工作大局，在发展经济、扩大就业、改善民生、科技创新等方面积极发挥作用，为满足人民日益增长的美好生活需要贡献力量。"},{"i":36,"n":"第三十六条","txt":"民营经济组织从事生产经营活动应当遵守劳动用工、安全生产、职业卫生、社会保障、生态环境、质量标准、知识产权、网络和数据安全、财政税收、金融等方面的法律法规；不得通过贿赂和欺诈等手段牟取不正当利益，不得妨害市场和金融秩序、破坏生态环境、损害劳动者合法权益和社会公共利益。"},{"i":37,"n":"第三十七条","txt":"支持民营资本服务经济社会发展，完善资本行为制度规则，依法规范和引导民营资本健康发展，维护社会主义市场经济秩序和社会公共利益。支持民营经济组织加强风险防范管理，鼓励民营经济组织做优主业、做强实业，提升核心竞争力。"},{"i":38,"n":"第三十八条","txt":"民营经济组织应当完善治理结构和管理制度、规范经营者行为、强化内部监督，实现规范治理；依法建立健全以职工代表大会为基本形式的民主管理制度。鼓励有条件的民营经济组织建立完善中国特色现代企业制度。"},{"i":39,"n":"第三十九条","txt":"国家推动构建民营经济组织源头防范和治理腐败的体制机制，支持引导民营经济组织建立健全内部审计制度，加强廉洁风险防控，推动民营经济组织提升依法合规经营管理水平，及时预防、发现、治理经营中违法违规等问题。"},{"i":40,"n":"第四十条","txt":"民营经济组织应当依照法律、行政法规和国家统一的会计制度，加强财务管理，规范会计核算，防止财务造假，并区分民营经济组织生产经营收支与民营经济组织经营者个人收支，实现民营经济组织财产与民营经济组织经营者个人财产分离。"},{"i":41,"n":"第四十一条","txt":"支持民营经济组织通过加强技能培训、扩大吸纳就业、完善工资分配制度等，促进员工共享发展成果。"},{"i":42,"n":"第四十二条","txt":"探索建立民营经济组织的社会责任评价体系和激励机制，鼓励、引导民营经济组织积极履行社会责任，自愿参与公益慈善事业、应急救灾等活动。"},{"i":43,"n":"第四十三条","txt":"民营经济组织及其经营者在海外投资经营应当遵守所在国家或者地区的法律，尊重当地习俗和文化传统，维护国家形象，不得从事损害国家安全和国家利益的活动。"},{"i":44,"n":"第四十四条","txt":"国家机关及其工作人员在促进民营经济发展工作中，应当依法履职尽责。国家机关工作人员与民营经济组织经营者在工作交往中，应当遵纪守法，保持清正廉洁。"},{"i":45,"n":"第四十五条","txt":"国家机关制定与经营主体生产经营活动密切相关的法律、法规、规章和其他规范性文件，最高人民法院、最高人民检察院作出属于审判、检察工作中具体应用法律的相关解释，或者作出有关重大决策，应当注重听取包括民营经济组织在内各类经济组织、行业协会商会的意见建议；在实施前应当根据实际情况留出必要的适应调整期。"},{"i":46,"n":"第四十六条","txt":"各级人民政府及其有关部门应当及时向社会公开涉及经营主体的优惠政策适用范围、标准、条件和申请程序等，为民营经济组织申请享受有关优惠政策提供便利。"},{"i":47,"n":"第四十七条","txt":"各级人民政府及其有关部门制定鼓励民营经济组织创业的政策，提供公共服务，鼓励创业带动就业。"},{"i":48,"n":"第四十八条","txt":"登记机关应当为包括民营经济组织在内的各类经济组织提供依法合规、规范统一、公开透明、便捷高效的设立、变更、注销等登记服务，降低市场进入和退出成本。"},{"i":49,"n":"第四十九条","txt":"鼓励、支持高等学校、科研院所、职业学校、公共实训基地和各类职业技能培训机构创新人才培养模式，加强职业教育和培训，培养符合民营经济高质量发展需求的专业人才和产业工人。"},{"i":50,"n":"第五十条","txt":"行政机关坚持依法行政。行政机关开展执法活动应当避免或者尽量减少对民营经济组织正常生产经营活动的影响，并对其合理、合法诉求及时响应、处置。"},{"i":51,"n":"第五十一条","txt":"对民营经济组织及其经营者违法行为的行政处罚应当按照与其他经济组织及其经营者同等原则实施。对违法行为依法需要实施行政处罚或者采取其他措施的，应当与违法行为的事实、性质、情节以及社会危害程度相当。违法行为具有《中华人民共和国行政处罚法》规定的从轻、减轻或者不予处罚情形的，依照其规定从轻、减轻或者不予处罚。"},{"i":52,"n":"第五十二条","txt":"各级人民政府及其有关部门推动监管信息共享互认，根据民营经济组织的信用状况实施分级分类监管，提升监管效能。"},{"i":53,"n":"第五十三条","txt":"各级人民政府及其有关部门建立健全行政执法违法行为投诉举报处理机制，及时受理并依法处理投诉举报，保护民营经济组织及其经营者合法权益。"},{"i":54,"n":"第五十四条","txt":"健全失信惩戒和信用修复制度。实施失信惩戒，应当依照法律、法规和有关规定，并根据失信行为的事实、性质、轻重程度等采取适度的惩戒措施。"},{"i":55,"n":"第五十五条","txt":"建立健全矛盾纠纷多元化解机制，为民营经济组织维护合法权益提供便利。"},{"i":56,"n":"第五十六条","txt":"有关行业协会商会依照法律、法规和章程，发挥协调和自律作用，及时反映行业诉求，为民营经济组织及其经营者提供信息咨询、宣传培训、市场拓展、权益保护、纠纷处理等方面的服务。"},{"i":57,"n":"第五十七条","txt":"国家坚持高水平对外开放，加快构建以国内大循环为主体、国内国际双循环相互促进的新发展格局；支持、引导民营经济组织拓展国际交流合作，在海外依法合规开展投资经营等活动；加强法律、金融、物流等海外综合服务，完善海外利益保障机制，维护民营经济组织及其经营者海外合法权益。"},{"i":58,"n":"第五十八条","txt":"民营经济组织及其经营者的人身权利、财产权利以及经营自主权等合法权益受法律保护，任何单位和个人不得侵犯。"},{"i":59,"n":"第五十九条","txt":"民营经济组织的名称权、名誉权、荣誉权和民营经济组织经营者的名誉权、荣誉权、隐私权、个人信息等人格权益受法律保护。"},{"i":60,"n":"第六十条","txt":"国家机关及其工作人员依法开展调查或者要求协助调查，应当避免或者尽量减少对正常生产经营活动产生影响。实施限制人身自由的强制措施，应当严格依照法定权限、条件和程序进行。"},{"i":61,"n":"第六十一条","txt":"征收、征用财产，应当严格依照法定权限、条件和程序进行。"},{"i":62,"n":"第六十二条","txt":"查封、扣押、冻结涉案财物，应当遵守法定权限、条件和程序，严格区分违法所得、其他涉案财物与合法财产，民营经济组织财产与民营经济组织经营者个人财产，涉案人财产与案外人财产，不得超权限、超范围、超数额、超时限查封、扣押、冻结财物。对查封、扣押的涉案财物，应当妥善保管。"},{"i":63,"n":"第六十三条","txt":"办理案件应当严格区分经济纠纷与经济犯罪，遵守法律关于追诉期限的规定；生产经营活动未违反刑法规定的，不以犯罪论处；事实不清、证据不足或者依法不追究刑事责任的，应当依法撤销案件、不起诉、终止审理或者宣告无罪。"},{"i":64,"n":"第六十四条","txt":"规范异地执法行为，建立健全异地执法协助制度。办理案件需要异地执法的，应当遵守法定权限、条件和程序。国家机关之间对案件管辖有争议的，可以进行协商，协商不成的，提请共同的上级机关决定，法律另有规定的从其规定。"},{"i":65,"n":"第六十五条","txt":"民营经济组织及其经营者对生产经营活动是否违法，以及国家机关实施的强制措施存在异议的，可以依法向有关机关反映情况、申诉，依法申请行政复议、提起诉讼。"},{"i":66,"n":"第六十六条","txt":"检察机关依法对涉及民营经济组织及其经营者的诉讼活动实施法律监督，及时受理并审查有关申诉、控告。发现存在违法情形的，应当依法提出抗诉、纠正意见、检察建议。"},{"i":67,"n":"第六十七条","txt":"国家机关、事业单位、国有企业应当依法或者依合同约定及时向民营经济组织支付账款，不得以人员变更、履行内部付款流程或者在合同未作约定情况下以等待竣工验收批复、决算审计等为由，拒绝或者拖延支付民营经济组织账款；除法律、行政法规另有规定外，不得强制要求以审计结果作为结算依据。"},{"i":68,"n":"第六十八条","txt":"大型企业向中小民营经济组织采购货物、工程、服务等，应当合理约定付款期限并及时支付账款，不得以收到第三方付款作为向中小民营经济组织支付账款的条件。"},{"i":69,"n":"第六十九条","txt":"县级以上地方人民政府应当加强账款支付保障工作，预防和清理拖欠民营经济组织账款；强化预算管理，政府采购项目应当严格按照批准的预算执行；加强对拖欠账款处置工作的统筹指导，对有争议的鼓励各方协商解决，对存在重大分歧的组织协商、调解。协商、调解应当发挥工商业联合会、律师协会等组织的作用。"},{"i":70,"n":"第七十条","txt":"地方各级人民政府及其有关部门应当履行依法向民营经济组织作出的政策承诺和与民营经济组织订立的合同，不得以行政区划调整、政府换届、机构或者职能调整以及相关人员更替等为由违约、毁约。"},{"i":71,"n":"第七十一条","txt":"违反本法规定，有下列情形之一的，由有权机关责令改正，造成不良后果或者影响的，对负有责任的领导人员和直接责任人员依法给予处分："},{"i":72,"n":"第七十二条","txt":"违反法律规定实施征收、征用或者查封、扣押、冻结等措施的，由有权机关责令改正，造成损失的，依法予以赔偿；造成不良后果或者影响的，对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":73,"n":"第七十三条","txt":"国家机关、事业单位、国有企业违反法律、行政法规规定或者合同约定，拒绝或者拖延支付民营经济组织账款，地方各级人民政府及其有关部门不履行向民营经济组织依法作出的政策承诺、依法订立的合同的，由有权机关予以纠正，造成损失的，依法予以赔偿；造成不良后果或者影响的，对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":74,"n":"第七十四条","txt":"违反本法规定，侵害民营经济组织及其经营者合法权益，其他法律、法规规定行政处罚的，从其规定；造成人身损害或者财产损失的，依法承担民事责任；构成犯罪的，依法追究刑事责任。"},{"i":75,"n":"第七十五条","txt":"民营经济组织及其经营者生产经营活动违反法律、法规规定，由有权机关责令改正，依法予以行政处罚；造成人身损害或者财产损失的，依法承担民事责任；构成犯罪的，依法追究刑事责任。"},{"i":76,"n":"第七十六条","txt":"民营经济组织及其经营者采取欺诈等不正当手段骗取表彰荣誉、优惠政策等的，应当撤销已获表彰荣誉、取消享受的政策待遇，依法予以处罚；构成犯罪的，依法追究刑事责任。"},{"i":77,"n":"第七十七条","txt":"本法所称民营经济组织，是指在中华人民共和国境内依法设立的由中国公民控股或者实际控制的营利法人、非法人组织和个体工商户，以及前述组织控股或者实际控制的营利法人、非法人组织。"},{"i":78,"n":"第七十八条","txt":"本法自2025年5月20日起施行。"}],"zhucekuaijishifa-2":[{"i":1,"n":"第一条","txt":"为了发挥注册会计师在社会经济活动中的鉴证和服务作用，加强对注册会计师的管理，维护社会公共利益和投资者的合法权益，促进社会主义市场经济的健康发展，制定本法。"},{"i":2,"n":"第二条","txt":"注册会计师行业坚持中国共产党的领导，贯彻落实党和国家路线方针政策、决策部署，为国民经济和社会发展服务。"},{"i":3,"n":"第三条","txt":"注册会计师是依法取得注册会计师证书并接受委托从事审计和会计咨询、会计服务业务的执业人员。"},{"i":4,"n":"第四条","txt":"会计师事务所是依法设立并承办注册会计师业务的机构。"},{"i":5,"n":"第五条","txt":"注册会计师协会是由注册会计师组成的社会团体。中国注册会计师协会是注册会计师的全国组织，省、自治区、直辖市注册会计师协会是注册会计师的地方组织。"},{"i":6,"n":"第六条","txt":"国务院财政部门和省、自治区、直辖市人民政府财政部门，依法对注册会计师、会计师事务所和注册会计师协会进行监督、指导。"},{"i":7,"n":"第七条","txt":"国家支持注册会计师行业加强诚信建设，提高审计质量，拓展服务网络，提升规范化、专业化水平，促进注册会计师行业健康发展。"},{"i":8,"n":"第八条","txt":"注册会计师和会计师事务所执行业务，必须遵守法律、行政法规，遵循执业准则，恪守职业道德，坚持诚信、客观、独立、公正。"},{"i":9,"n":"第九条","txt":"国家实行注册会计师全国统一考试制度。注册会计师全国统一考试办法，由国务院财政部门制定，由中国注册会计师协会组织实施。"},{"i":10,"n":"第十条","txt":"具有高等专科以上学校毕业的学历、或者具有会计或者相关专业中级以上技术职称的中国公民，可以申请参加注册会计师全国统一考试；具有会计或者相关专业高级技术职称的人员，可以免予部分科目的考试。"},{"i":11,"n":"第十一条","txt":"参加注册会计师全国统一考试成绩合格，并从事审计业务工作二年以上的，可以向省、自治区、直辖市注册会计师协会申请注册。"},{"i":12,"n":"第十二条","txt":"有下列情形之一的，受理申请的注册会计师协会不予注册："},{"i":13,"n":"第十三条","txt":"注册会计师协会应当将准予注册的人员名单报国务院财政部门备案。国务院财政部门发现注册会计师协会的注册不符合本法规定的，应当通知有关的注册会计师协会撤销注册。"},{"i":14,"n":"第十四条","txt":"准予注册的申请人，由注册会计师协会发给国务院财政部门统一制定的注册会计师证书。"},{"i":15,"n":"第十五条","txt":"已取得注册会计师证书的人员，注册后有下列情形之一的，由准予注册的注册会计师协会注销或者撤销注册，收回注册会计师证书："},{"i":16,"n":"第十六条","txt":"注册会计师承办下列审计业务："},{"i":17,"n":"第十七条","txt":"注册会计师可以承办会计咨询、会计服务业务。"},{"i":18,"n":"第十八条","txt":"注册会计师承办业务，由其所在的会计师事务所统一受理并与委托人签订委托合同。"},{"i":19,"n":"第十九条","txt":"注册会计师执行业务，可以根据需要查阅被审计单位以及相关单位和个人的有关会计资料和文件，查看被审计单位的业务现场和设施，要求委托人或者被审计单位提供其他必要的协助。"},{"i":20,"n":"第二十条","txt":"注册会计师与委托人或者被审计单位有利害关系的，应当回避；委托人或者被审计单位有权要求其回避。"},{"i":21,"n":"第二十一条","txt":"注册会计师对在执行业务中知悉的国家秘密、工作秘密、商业秘密、个人隐私、个人信息，负有保密义务，不得泄露或者非法向他人提供。"},{"i":22,"n":"第二十二条","txt":"注册会计师执行审计业务，遇有下列情形之一的，应当拒绝出具有关报告，或者出具非无保留意见的报告："},{"i":23,"n":"第二十三条","txt":"注册会计师执行审计业务，必须以国家统一的会计制度为依据，按照执业准则、规则确定的工作程序出具报告，不得出具虚假报告。"},{"i":24,"n":"第二十四条","txt":"注册会计师不得有下列行为："},{"i":25,"n":"第二十五条","txt":"会计师事务所可以由注册会计师合伙设立。合伙设立的会计师事务所应当采用普通合伙或者特殊的普通合伙形式。"},{"i":26,"n":"第二十六条","txt":"会计师事务所符合下列条件的，可以是负有限责任的法人："},{"i":27,"n":"第二十七条","txt":"设立会计师事务所，由省、自治区、直辖市人民政府财政部门批准。"},{"i":28,"n":"第二十八条","txt":"审批机关应当自收到申请文件之日起十五日内决定批准或者不批准。"},{"i":29,"n":"第二十九条","txt":"会计师事务所设立分支机构，须经分支机构所在地的省、自治区、直辖市人民政府财政部门批准。"},{"i":30,"n":"第三十条","txt":"会计师事务所依法纳税。"},{"i":31,"n":"第三十一条","txt":"会计师事务所受理业务，不受行政区域、行业的限制；但是，法律、行政法规另有规定的除外。"},{"i":32,"n":"第三十二条","txt":"国务院财政部门会同国务院有关部门依照有关法律规定，对会计师事务所从事上市公司审计等金融活动审计服务实施准入管理。"},{"i":33,"n":"第三十三条","txt":"委托人委托会计师事务所办理业务，任何单位和个人不得干预。"},{"i":34,"n":"第三十四条","txt":"本法第二十条至第二十三条的规定，适用于会计师事务所。"},{"i":35,"n":"第三十五条","txt":"会计师事务所不得有本法第二十四条第（一）项至第（四）项、第（六）项、第（七）项所列的行为。"},{"i":36,"n":"第三十六条","txt":"注册会计师应当加入注册会计师协会。"},{"i":37,"n":"第三十七条","txt":"中国注册会计师协会的章程由全国会员代表大会制定，并报国务院财政部门备案；省、自治区、直辖市注册会计师协会的章程由省、自治区、直辖市会员代表大会制定，并报省、自治区、直辖市人民政府财政部门备案。"},{"i":38,"n":"第三十八条","txt":"中国注册会计师协会依法拟订注册会计师执业准则、规则，报国务院财政部门批准后施行。"},{"i":39,"n":"第三十九条","txt":"注册会计师协会应当加强注册会计师行业有关发展规划和人才队伍建设工作，强化行业自律监督，为提升行业服务质量，拓展业务领域和创新技术应用提供支持。"},{"i":40,"n":"第四十条","txt":"注册会计师协会应当对注册会计师的任职资格和执业情况进行年度检查。"},{"i":41,"n":"第四十一条","txt":"注册会计师协会依法取得社会团体法人资格。"},{"i":42,"n":"第四十二条","txt":"国务院财政部门和省、自治区、直辖市人民政府财政部门依法对会计师事务所、注册会计师的执业情况进行监督检查。具体办法由国务院财政部门制定。"},{"i":43,"n":"第四十三条","txt":"国务院财政部门或者省、自治区、直辖市人民政府财政部门对会计师事务所、注册会计师依法实施监督检查时，会计师事务所、注册会计师应当如实提供有关审计资料和文件，不得拒绝、阻碍或者隐瞒。"},{"i":44,"n":"第四十四条","txt":"国务院财政部门或者省、自治区、直辖市人民政府财政部门在监督检查中发现会计师事务所、注册会计师有违规行为的，可以采取监管谈话、出具警示函、责令限期整改等措施。"},{"i":45,"n":"第四十五条","txt":"会计师事务所应当加强对审计工作底稿和审计档案的管理，保证其真实、完整。注册会计师执行审计业务形成的审计工作底稿和审计档案，应当存放在中国境内。除国家另有规定外，任何单位或者个人不得擅自携带、传递审计工作底稿或者审计档案出境。审计工作底稿和审计档案的具体管理办法由国务院财政部门会同有关部门制定。"},{"i":46,"n":"第四十六条","txt":"国务院财政部门和省、自治区、直辖市人民政府财政部门应当加强信息化建设，提升注册会计师行业的监管效率和水平。"},{"i":47,"n":"第四十七条","txt":"会计师事务所违反本法第二十二条、第二十三条规定的，由国务院财政部门或者省、自治区、直辖市人民政府财政部门责令限期改正，给予警告、通报批评，没收违法所得，违法所得五十万元以上的，可以并处违法所得一倍以上十倍以下的罚款，没有违法所得或者违法所得不足五十万元的，可以并处五百万元以下的罚款；情节严重的，暂停其部分或者全部经营业务一个月至十二个月或者吊销其执业许可。对直接负责的主管人员和其他直接责任人员，责令限期改正，给予警告、通报批评，没收违法所得，可以并处二百万元以下的罚款。"},{"i":48,"n":"第四十八条","txt":"会计师事务所违反本法第三十五条规定的，由国务院财政部门或者省、自治区、直辖市人民政府财政部门责令限期改正，给予警告、通报批评，没收违法所得，违法所得十万元以上的，可以并处违法所得一倍以上十倍以下的罚款，没有违法所得或者违法所得不足十万元的，可以并处一百万元以下的罚款；情节严重的，暂停其部分或者全部经营业务一个月至十二个月或者吊销其执业许可。对直接负责的主管人员和其他直接责任人员，责令限期改正，给予警告、通报批评，没收违法所得，可以并处五十万元以下的罚款。"},{"i":49,"n":"第四十九条","txt":"委托人或者被审计单位以及其他单位或者个人串通、唆使会计师事务所或者注册会计师违反本法第二十二条、第二十三条规定出具虚假报告的，由国务院财政部门或者省、自治区、直辖市人民政府财政部门，责令其限期改正，给予警告、通报批评，没收违法所得，可以并处五百万元以下的罚款。对直接负责的主管人员和其他直接责任人员，责令限期改正，给予警告、通报批评，没收违法所得，可以并处二百万元以下的罚款。"},{"i":50,"n":"第五十条","txt":"对未经批准承办本法第十六条规定的注册会计师业务的单位或者个人，由国务院财政部门或者省、自治区、直辖市人民政府财政部门责令其停止违法活动，没收违法所得，违法所得五十万元以上的，可以并处违法所得一倍以上十倍以下的罚款，没有违法所得或者违法所得不足五十万元的，可以并处五百万元以下的罚款。"},{"i":51,"n":"第五十一条","txt":"被审计单位以及相关单位和个人向注册会计师提供虚假的会计资料或者文件的，依照有关法律、行政法规的规定处罚。"},{"i":52,"n":"第五十二条","txt":"会计师事务所、注册会计师违反本法第四十三条规定的，由国务院财政部门或者省、自治区、直辖市人民政府财政部门责令限期改正，给予警告、通报批评，可以并处二十万元以下的罚款；情节严重的，处二十万元以上一百万元以下的罚款。"},{"i":53,"n":"第五十三条","txt":"任何单位或者个人违反本法第四十五条规定，擅自携带、传递审计工作底稿或者审计档案出境的，由国务院财政部门或者省、自治区、直辖市人民政府财政部门责令限期改正，给予警告、通报批评，没收违法所得，对单位可以并处二百万元以下的罚款，对直接负责的主管人员和其他直接责任人员可以并处五十万元以下的罚款，属于会计师事务所且情节严重的，暂停其部分或者全部经营业务一个月至十二个月或者吊销其执业许可；对个人可以并处五十万元以下的罚款，属于注册会计师且情节严重的，暂停其执行业务一个月至十二个月或者吊销其注册会计师证书。"},{"i":54,"n":"第五十四条","txt":"财政部门、注册会计师协会工作人员在注册会计师行业监督管理工作中滥用职权、玩忽职守、徇私舞弊或者泄露国家秘密、工作秘密、商业秘密、个人隐私、个人信息的，依法给予处分。"},{"i":55,"n":"第五十五条","txt":"当事人对行政处罚决定不服的，可以依法申请行政复议或者向人民法院提起行政诉讼。"},{"i":56,"n":"第五十六条","txt":"会计师事务所违反本法规定，给委托人、被审计单位以及其他利害关系人造成损失的，应当依法承担赔偿责任。"},{"i":57,"n":"第五十七条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":58,"n":"第五十八条","txt":"外国人申请参加中国注册会计师全国统一考试和注册，按照互惠原则办理。"},{"i":59,"n":"第五十九条","txt":"国务院可以根据本法制定实施条例。"},{"i":60,"n":"第六十条","txt":"本法自1994年1月1日起施行。1986年7月3日国务院发布的《中华人民共和国注册会计师条例》同时废止。"}],"zhucekuaijishifa":[{"i":1,"n":"第一条","txt":"为了发挥注册会计师在社会经济活动中的鉴证和服务作用，加强对注册会计师的管理，维护社会公共利益和投资者的合法权益，促进社会主义市场经济的健康发展，制定本法。"},{"i":2,"n":"第二条","txt":"注册会计师是依法取得注册会计师证书并接受委托从事审计和会计咨询、会计服务业务的执业人员。"},{"i":3,"n":"第三条","txt":"会计师事务所是依法设立并承办注册会计师业务的机构。"},{"i":4,"n":"第四条","txt":"注册会计师协会是由注册会计师组成的社会团体。中国注册会计师协会是注册会计师的全国组织，省、自治区、直辖市注册会计师协会是注册会计师的地方组织。"},{"i":5,"n":"第五条","txt":"国务院财政部门和省、自治区、直辖市人民政府财政部门，依法对注册会计师、会计师事务所和注册会计师协会进行监督、指导。"},{"i":6,"n":"第六条","txt":"注册会计师和会计师事务所执行业务，必须遵守法律、行政法规。"},{"i":7,"n":"第七条","txt":"国家实行注册会计师全国统一考试制度。注册会计师全国统一考试办法，由国务院财政部门制定，由中国注册会计师协会组织实施。"},{"i":8,"n":"第八条","txt":"具有高等专科以上学校毕业的学历、或者具有会计或者相关专业中级以上技术职称的中国公民，可以申请参加注册会计师全国统一考试；具有会计或者相关专业高级技术职称的人员，可以免予部分科目的考试。"},{"i":9,"n":"第九条","txt":"参加注册会计师全国统一考试成绩合格，并从事审计业务工作二年以上的，可以向省、自治区、直辖市注册会计师协会申请注册。"},{"i":10,"n":"第十条","txt":"有下列情形之一的，受理申请的注册会计师协会不予注册："},{"i":11,"n":"第十一条","txt":"注册会计师协会应当将准予注册的人员名单报国务院财政部门备案。国务院财政部门发现注册会计师协会的注册不符合本法规定的，应当通知有关的注册会计师协会撤销注册。"},{"i":12,"n":"第十二条","txt":"准予注册的申请人，由注册会计师协会发给国务院财政部门统一制定的注册会计师证书。"},{"i":13,"n":"第十三条","txt":"已取得注册会计师证书的人员，除本法第十一条第一款规定的情形外，注册后有下列情形之一的，由准予注册的注册会计师协会撤销注册，收回注册会计师证书："},{"i":14,"n":"第十四条","txt":"注册会计师承办下列审计业务："},{"i":15,"n":"第十五条","txt":"注册会计师可以承办会计咨询、会计服务业务。"},{"i":16,"n":"第十六条","txt":"注册会计师承办业务，由其所在的会计师事务所统一受理并与委托人签订委托合同。"},{"i":17,"n":"第十七条","txt":"注册会计师执行业务，可以根据需要查阅委托人的有关会计资料和文件，查看委托人的业务现场和设施，要求委托人提供其他必要的协助。"},{"i":18,"n":"第十八条","txt":"注册会计师与委托人有利害关系的，应当回避；委托人有权要求其回避。"},{"i":19,"n":"第十九条","txt":"注册会计师对在执行业务中知悉的商业秘密，负有保密义务。"},{"i":20,"n":"第二十条","txt":"注册会计师执行审计业务，遇有下列情形之一的，应当拒绝出具有关报告："},{"i":21,"n":"第二十一条","txt":"注册会计师执行审计业务，必须按照执业准则、规则确定的工作程序出具报告。"},{"i":22,"n":"第二十二条","txt":"注册会计师不得有下列行为："},{"i":23,"n":"第二十三条","txt":"会计师事务所可以由注册会计师合伙设立。"},{"i":24,"n":"第二十四条","txt":"会计师事务所符合下列条件的，可以是负有限责任的法人："},{"i":25,"n":"第二十五条","txt":"设立会计师事务所，由省、自治区、直辖市人民政府财政部门批准。"},{"i":26,"n":"第二十六条","txt":"审批机关应当自收到申请文件之日起三十日内决定批准或者不批准。"},{"i":27,"n":"第二十七条","txt":"会计师事务所设立分支机构，须经分支机构所在地的省、自治区、直辖市人民政府财政部门批准。"},{"i":28,"n":"第二十八条","txt":"会计师事务所依法纳税。"},{"i":29,"n":"第二十九条","txt":"会计师事务所受理业务，不受行政区域、行业的限制；但是，法律、行政法规另有规定的除外。"},{"i":30,"n":"第三十条","txt":"委托人委托会计师事务所办理业务，任何单位和个人不得干预。"},{"i":31,"n":"第三十一条","txt":"本法第十八条至第二十一条的规定，适用于会计师事务所。"},{"i":32,"n":"第三十二条","txt":"会计师事务所不得有本法第二十二条第（一）项至第（四）项、第（六）项、第（七）项所列的行为。"},{"i":33,"n":"第三十三条","txt":"注册会计师应当加入注册会计师协会。"},{"i":34,"n":"第三十四条","txt":"中国注册会计师协会的章程由全国会员代表大会制定，并报国务院财政部门备案；省、自治区、直辖市注册会计师协会的章程由省、自治区、直辖市会员代表大会制定，并报省、自治区、直辖市人民政府财政部门备案。"},{"i":35,"n":"第三十五条","txt":"中国注册会计师协会依法拟订注册会计师执业准则、规则，报国务院财政部门批准后施行。"},{"i":36,"n":"第三十六条","txt":"注册会计师协会应当支持注册会计师依法执行业务，维护其合法权益，向有关方面反映其意见和建议。"},{"i":37,"n":"第三十七条","txt":"注册会计师协会应当对注册会计师的任职资格和执业情况进行年度检查。"},{"i":38,"n":"第三十八条","txt":"注册会计师协会依法取得社会团体法人资格。"},{"i":39,"n":"第三十九条","txt":"会计师事务所违反本法第二十条、第二十一条规定的，由省级以上人民政府财政部门给予警告，没收违法所得，可以并处违法所得一倍以上五倍以下的罚款；情节严重的，并可以由省级以上人民政府财政部门暂停其经营业务或者予以撤销。"},{"i":40,"n":"第四十条","txt":"对未经批准承办本法第十四条规定的注册会计师业务的单位，由省级以上人民政府财政部门责令其停止违法活动，没收违法所得，可以并处违法所得一倍以上五倍以下的罚款。"},{"i":41,"n":"第四十一条","txt":"当事人对行政处罚决定不服的，可以在接到处罚通知之日起十五日内向作出处罚决定的机关的上一级机关申请复议；当事人也可以在接到处罚决定通知之日起十五日内直接向人民法院起诉。"},{"i":42,"n":"第四十二条","txt":"会计师事务所违反本法规定，给委托人、其他利害关系人造成损失的，应当依法承担赔偿责任。"},{"i":43,"n":"第四十三条","txt":"在审计事务所工作的注册审计师，经认定为具有注册会计师资格的，可以执行本法规定的业务，其资格认定和对其监督、指导、管理的办法由国务院另行规定。"},{"i":44,"n":"第四十四条","txt":"外国人申请参加中国注册会计师全国统一考试和注册，按照互惠原则办理。"},{"i":45,"n":"第四十五条","txt":"国务院可以根据本法制定实施条例。"},{"i":46,"n":"第四十六条","txt":"本法自1994年1月1日起施行。1986年7月3日国务院发布的《中华人民共和国注册会计师条例》同时废止。"}],"hainanziyoumaoyigangfa":[{"i":1,"n":"第一条","txt":"为了建设高水平的中国特色海南自由贸易港，推动形成更高层次改革开放新格局，建立开放型经济新体制，促进社会主义市场经济平稳健康可持续发展，制定本法。"},{"i":2,"n":"第二条","txt":"国家在海南岛全岛设立海南自由贸易港，分步骤、分阶段建立自由贸易港政策和制度体系，实现贸易、投资、跨境资金流动、人员进出、运输来往自由便利和数据安全有序流动。"},{"i":3,"n":"第三条","txt":"海南自由贸易港建设，应当体现中国特色，借鉴国际经验，围绕海南战略定位，发挥海南优势，推进改革创新，加强风险防范，贯彻创新、协调、绿色、开放、共享的新发展理念，坚持高质量发展，坚持总体国家安全观，坚持以人民为中心，实现经济繁荣、社会文明、生态宜居、人民幸福。"},{"i":4,"n":"第四条","txt":"海南自由贸易港建设，以贸易投资自由化便利化为重点，以各类生产要素跨境自由有序安全便捷流动和现代产业体系为支撑，以特殊的税收制度安排、高效的社会治理体系和完备的法治体系为保障，持续优化法治化、国际化、便利化的营商环境和公平统一高效的市场环境。"},{"i":5,"n":"第五条","txt":"海南自由贸易港实行最严格的生态环境保护制度，坚持生态优先、绿色发展，创新生态文明体制机制，建设国家生态文明试验区。"},{"i":6,"n":"第六条","txt":"国家建立海南自由贸易港建设领导机制，统筹协调海南自由贸易港建设重大政策和重大事项。国务院发展改革、财政、商务、金融管理、海关、税务等部门按照职责分工，指导推动海南自由贸易港建设相关工作。"},{"i":7,"n":"第七条","txt":"国家支持海南自由贸易港建设发展，支持海南省依照中央要求和法律规定行使改革自主权。国务院及其有关部门根据海南自由贸易港建设的实际需要，及时依法授权或者委托海南省人民政府及其有关部门行使相关管理职权。"},{"i":8,"n":"第八条","txt":"海南自由贸易港构建系统完备、科学规范、运行有效的海南自由贸易港治理体系，推动政府机构改革和职能转变，规范政府服务标准，加强预防和化解社会矛盾机制建设，提高社会治理智能化水平，完善共建共治共享的社会治理制度。"},{"i":9,"n":"第九条","txt":"国家支持海南自由贸易港主动适应国际经济贸易规则发展和全球经济治理体系改革新趋势，积极开展国际交流合作。"},{"i":10,"n":"第十条","txt":"海南省人民代表大会及其常务委员会可以根据本法，结合海南自由贸易港建设的具体情况和实际需要，遵循宪法规定和法律、行政法规的基本原则，就贸易、投资及相关管理活动制定法规（以下称海南自由贸易港法规），在海南自由贸易港范围内实施。"},{"i":11,"n":"第十一条","txt":"国家建立健全全岛封关运作的海南自由贸易港海关监管特殊区域制度。在依法有效监管基础上，建立自由进出、安全便利的货物贸易管理制度，优化服务贸易管理措施，实现贸易自由化便利化。"},{"i":12,"n":"第十二条","txt":"海南自由贸易港应当高标准建设口岸基础设施，加强口岸公共卫生安全、国门生物安全、食品安全、商品质量安全管控。"},{"i":13,"n":"第十三条","txt":"在境外与海南自由贸易港之间，货物、物品可以自由进出，海关依法进行监管，列入海南自由贸易港禁止、限制进出口货物、物品清单的除外。"},{"i":14,"n":"第十四条","txt":"货物由海南自由贸易港进入境内其他地区（以下简称内地），原则上按进口规定办理相关手续。物品由海南自由贸易港进入内地，按规定进行监管。对海南自由贸易港前往内地的运输工具，简化进口管理。"},{"i":15,"n":"第十五条","txt":"各类市场主体在海南自由贸易港内依法自由开展货物贸易以及相关活动，海关实施低干预、高效能的监管。"},{"i":16,"n":"第十六条","txt":"海南自由贸易港实行通关便利化政策，简化货物流转流程和手续。除依法需要检验检疫或者实行许可证件管理的货物外，货物进入海南自由贸易港，海关按照有关规定径予放行，为市场主体提供通关便利服务。"},{"i":17,"n":"第十七条","txt":"海南自由贸易港对跨境服务贸易实行负面清单管理制度，并实施相配套的资金支付和转移制度。对清单之外的跨境服务贸易，按照内外一致的原则管理。"},{"i":18,"n":"第十八条","txt":"海南自由贸易港实行投资自由化便利化政策，全面推行极简审批投资制度，完善投资促进和投资保护制度，强化产权保护，保障公平竞争，营造公开、透明、可预期的投资环境。"},{"i":19,"n":"第十九条","txt":"海南自由贸易港对外商投资实行准入前国民待遇加负面清单管理制度。特别适用于海南自由贸易港的外商投资准入负面清单由国务院有关部门会同海南省制定，报国务院批准后发布。"},{"i":20,"n":"第二十条","txt":"国家放宽海南自由贸易港市场准入。海南自由贸易港放宽市场准入特别清单（特别措施）由国务院有关部门会同海南省制定。"},{"i":21,"n":"第二十一条","txt":"海南自由贸易港按照便利、高效、透明的原则，简化办事程序，提高办事效率，优化政务服务，建立市场主体设立便利、经营便利、注销便利等制度，优化破产程序。具体办法由海南省人民代表大会及其常务委员会制定。"},{"i":22,"n":"第二十二条","txt":"国家依法保护自然人、法人和非法人组织在海南自由贸易港内的投资、收益和其他合法权益，加强对中小投资者的保护。"},{"i":23,"n":"第二十三条","txt":"国家依法保护海南自由贸易港内自然人、法人和非法人组织的知识产权，促进知识产权创造、运用和管理服务能力提升，建立健全知识产权领域信用分类监管、失信惩戒等机制，对知识产权侵权行为，严格依法追究法律责任。"},{"i":24,"n":"第二十四条","txt":"海南自由贸易港建立统一开放、竞争有序的市场体系，强化竞争政策的基础性地位，落实公平竞争审查制度，加强和改进反垄断和反不正当竞争执法，保护市场公平竞争。"},{"i":25,"n":"第二十五条","txt":"在海南自由贸易港开发建设阶段，中央财政根据实际，结合税制变化情况，对海南自由贸易港给予适当财政支持。鼓励海南省在国务院批准的限额内发行地方政府债券支持海南自由贸易港项目建设。海南省设立政府引导、市场化方式运作的海南自由贸易港建设投资基金。"},{"i":26,"n":"第二十六条","txt":"海南自由贸易港可以根据发展需要，自主减征、免征、缓征除具有生态补偿性质外的政府性基金。"},{"i":27,"n":"第二十七条","txt":"按照税种结构简单科学、税制要素充分优化、税负水平明显降低、收入归属清晰、财政收支基本均衡的原则，结合国家税制改革方向，建立符合需要的海南自由贸易港税制体系。"},{"i":28,"n":"第二十八条","txt":"全岛封关运作、简并税制后，海南自由贸易港对进口征税商品实行目录管理，目录之外的货物进入海南自由贸易港，免征进口关税。进口征税商品目录由国务院财政部门会同国务院有关部门和海南省制定。"},{"i":29,"n":"第二十九条","txt":"货物由海南自由贸易港进入内地，原则上按照进口征税；但是，对鼓励类产业企业生产的不含进口料件或者含进口料件在海南自由贸易港加工增值达到一定比例的货物，免征关税。具体办法由国务院有关部门会同海南省制定。"},{"i":30,"n":"第三十条","txt":"对注册在海南自由贸易港符合条件的企业，实行企业所得税优惠；对海南自由贸易港内符合条件的个人，实行个人所得税优惠。"},{"i":31,"n":"第三十一条","txt":"海南自由贸易港建立优化高效统一的税收征管服务体系，提高税收征管服务科学化、信息化、国际化、便民化水平，积极参与国际税收征管合作，提高税收征管服务质量和效率，保护纳税人的合法权益。"},{"i":32,"n":"第三十二条","txt":"海南自由贸易港健全生态环境评价和监测制度，制定生态环境准入清单，防止污染，保护生态环境；健全自然资源资产产权制度和有偿使用制度，促进资源节约高效利用。"},{"i":33,"n":"第三十三条","txt":"海南自由贸易港推进国土空间规划体系建设，实行差别化的自然生态空间用途管制，严守生态保护红线，构建以国家公园为主体的自然保护地体系，推进绿色城镇化、美丽乡村建设。"},{"i":34,"n":"第三十四条","txt":"海南自由贸易港实行严格的进出境环境安全准入管理制度，加强检验检疫能力建设，防范外来物种入侵，禁止境外固体废物输入；提高医疗废物等危险废物处理处置能力，提升突发生态环境事件应急准备与响应能力，加强生态风险防控。"},{"i":35,"n":"第三十五条","txt":"海南自由贸易港推进建立政府主导、企业和社会参与、市场化运作、可持续的生态保护补偿机制，建立生态产品价值实现机制，鼓励利用市场机制推进生态环境保护，实现可持续发展。"},{"i":36,"n":"第三十六条","txt":"海南自由贸易港实行环境保护目标责任制和考核评价制度。县级以上地方人民政府对本级人民政府负有环境监督管理职责的部门及其负责人和下级人民政府及其负责人的年度考核，实行环境保护目标完成情况一票否决制。"},{"i":37,"n":"第三十七条","txt":"海南自由贸易港实行生态环境损害责任终身追究制。对违背科学发展要求、造成生态环境严重破坏的地方人民政府及有关部门主要负责人、直接负责的主管人员和其他直接责任人员，应当严格追究责任。"},{"i":38,"n":"第三十八条","txt":"国家支持海南自由贸易港建设开放型生态型服务型产业体系，积极发展旅游业、现代服务业、高新技术产业以及热带特色高效农业等重点产业。"},{"i":39,"n":"第三十九条","txt":"海南自由贸易港推进国际旅游消费中心建设，推动旅游与文化体育、健康医疗、养老养生等深度融合，培育旅游新业态新模式。"},{"i":40,"n":"第四十条","txt":"海南自由贸易港深化现代服务业对内对外开放，打造国际航运枢纽，推动港口、产业、城市融合发展，完善海洋服务基础设施，构建具有国际竞争力的海洋服务体系。"},{"i":41,"n":"第四十一条","txt":"国家支持海南自由贸易港建设重大科研基础设施和条件平台，建立符合科研规律的科技创新管理制度和国际科技合作机制。"},{"i":42,"n":"第四十二条","txt":"海南自由贸易港依法建立安全有序自由便利的数据流动管理制度，依法保护个人、组织与数据有关的权益，有序扩大通信资源和业务开放，扩大数据领域开放，促进以数据为关键要素的数字经济发展。"},{"i":43,"n":"第四十三条","txt":"海南自由贸易港实施高度自由便利开放的运输政策，建立更加开放的航运制度和船舶管理制度，建设“中国洋浦港”船籍港，实行特殊的船舶登记制度；放宽空域管制和航路限制，优化航权资源配置，提升运输便利化和服务保障水平。"},{"i":44,"n":"第四十四条","txt":"海南自由贸易港深化人才发展体制机制改革，创新人才培养支持机制，建立科学合理的人才引进、认定、使用和待遇保障机制。"},{"i":45,"n":"第四十五条","txt":"海南自由贸易港建立高效便利的出境入境管理制度，逐步实施更大范围适用免签入境政策，延长免签停留时间，优化出境入境检查管理，提供出境入境通关便利。"},{"i":46,"n":"第四十六条","txt":"海南自由贸易港实行更加开放的人才和停居留政策，实行更加宽松的人员临时出境入境政策、便利的工作签证政策，对外国人工作许可实行负面清单管理，进一步完善居留制度。"},{"i":47,"n":"第四十七条","txt":"海南自由贸易港放宽境外人员参加职业资格考试的限制，对符合条件的境外专业资格认定，实行单向认可清单制度。"},{"i":48,"n":"第四十八条","txt":"国务院可以根据海南自由贸易港建设的需要，授权海南省人民政府审批由国务院审批的农用地转为建设用地和土地征收事项；授权海南省人民政府在不突破海南省国土空间规划明确的生态保护红线、永久基本农田面积、耕地和林地保有量、建设用地总规模等重要指标并确保质量不降低的前提下，按照国家规定的条件，对全省耕地、永久基本农田、林地、建设用地布局调整进行审批。"},{"i":49,"n":"第四十九条","txt":"海南自由贸易港建设应当切实保护耕地，加强土地管理，建立集约节约用地制度、评价标准以及存量建设用地盘活处置制度。充分利用闲置土地，以出让方式取得土地使用权进行开发的土地，超过出让合同约定的竣工日期一年未竣工的，应当在竣工前每年征收出让土地现值一定比例的土地闲置费。具体办法由海南省制定。"},{"i":50,"n":"第五十条","txt":"海南自由贸易港坚持金融服务实体经济，推进金融改革创新，率先落实金融业开放政策。"},{"i":51,"n":"第五十一条","txt":"海南自由贸易港建立适应高水平贸易投资自由化便利化需要的跨境资金流动管理制度，分阶段开放资本项目，逐步推进非金融企业外债项下完全可兑换，推动跨境贸易结算便利化，有序推进海南自由贸易港与境外资金自由便利流动。"},{"i":52,"n":"第五十二条","txt":"海南自由贸易港内经批准的金融机构可以通过指定账户或者在特定区域经营离岸金融业务。"},{"i":53,"n":"第五十三条","txt":"海南自由贸易港加强社会信用体系建设和应用，构建守信激励和失信惩戒机制。"},{"i":54,"n":"第五十四条","txt":"国家支持探索与海南自由贸易港相适应的司法体制改革。海南自由贸易港建立多元化商事纠纷解决机制，完善国际商事纠纷案件集中审判机制，支持通过仲裁、调解等多种非诉讼方式解决纠纷。"},{"i":55,"n":"第五十五条","txt":"海南自由贸易港建立风险预警和防控体系，防范和化解重大风险。"},{"i":56,"n":"第五十六条","txt":"对本法规定的事项，在本法施行后，海南自由贸易港全岛封关运作前，国务院及其有关部门和海南省可以根据本法规定的原则，按照职责分工，制定过渡性的具体办法，推动海南自由贸易港建设。"},{"i":57,"n":"第五十七条","txt":"本法自公布之日起施行。"}],"gangkoufa":[{"i":1,"n":"第一条","txt":"为了加强港口管理，维护港口的安全与经营秩序，保护当事人的合法权益，促进港口的建设与发展，制定本法。"},{"i":2,"n":"第二条","txt":"从事港口规划、建设、维护、经营、管理及其相关活动，适用本法。"},{"i":3,"n":"第三条","txt":"本法所称港口，是指具有船舶进出、停泊、靠泊，旅客上下，货物装卸、驳运、储存等功能，具有相应的码头设施，由一定范围的水域和陆域组成的区域。"},{"i":4,"n":"第四条","txt":"国务院和有关县级以上地方人民政府应当在国民经济和社会发展计划中体现港口的发展和规划要求，并依法保护和合理利用港口资源。"},{"i":5,"n":"第五条","txt":"国家鼓励国内外经济组织和个人依法投资建设、经营港口，保护投资者的合法权益。"},{"i":6,"n":"第六条","txt":"国务院交通主管部门主管全国的港口工作。"},{"i":7,"n":"第七条","txt":"港口规划应当根据国民经济和社会发展的要求以及国防建设的需要编制，体现合理利用岸线资源的原则，符合城镇体系规划，并与土地利用总体规划、城市总体规划、江河流域规划、防洪规划、海洋功能区划、水路运输发展规划和其他运输方式发展规划以及法律、行政法规规定的其他有关规划相衔接、协调。"},{"i":8,"n":"第八条","txt":"港口规划包括港口布局规划和港口总体规划。"},{"i":9,"n":"第九条","txt":"全国港口布局规划，由国务院交通主管部门征求国务院有关部门和有关军事机关的意见编制，报国务院批准后公布实施。"},{"i":10,"n":"第十条","txt":"港口总体规划由港口行政管理部门征求有关部门和有关军事机关的意见编制。"},{"i":11,"n":"第十一条","txt":"地理位置重要、吞吐量较大、对经济发展影响较广的主要港口的总体规划，由国务院交通主管部门征求国务院有关部门和有关军事机关的意见后，会同有关省、自治区、直辖市人民政府批准，并公布实施。主要港口名录由国务院交通主管部门征求国务院有关部门意见后确定并公布。"},{"i":12,"n":"第十二条","txt":"港口规划的修改，按照港口规划制定程序办理。"},{"i":13,"n":"第十三条","txt":"在港口总体规划区内建设港口设施，使用港口深水岸线的，由国务院交通主管部门会同国务院经济综合宏观调控部门批准；建设港口设施，使用非深水岸线的，由港口行政管理部门批准。但是，由国务院或者国务院经济综合宏观调控部门批准建设的项目使用港口岸线，不再另行办理使用港口岸线的审批手续。"},{"i":14,"n":"第十四条","txt":"港口建设应当符合港口规划。不得违反港口规划建设任何港口设施。"},{"i":15,"n":"第十五条","txt":"按照国家规定须经有关机关批准的港口建设项目，应当按照国家有关规定办理审批手续，并符合国家有关标准和技术规范。"},{"i":16,"n":"第十六条","txt":"港口建设使用土地和水域，应当依照有关土地管理、海域使用管理、河道管理、航道管理、军事设施保护管理的法律、行政法规以及其他有关法律、行政法规的规定办理。"},{"i":17,"n":"第十七条","txt":"港口的危险货物作业场所、实施卫生除害处理的专用场所，应当符合港口总体规划和国家有关安全生产、消防、检验检疫和环境保护的要求，其与人口密集区和港口客运设施的距离应当符合国务院有关部门的规定；经依法办理有关手续后，方可建设。"},{"i":18,"n":"第十八条","txt":"航标设施以及其他辅助性设施，应当与港口同步建设，并保证按期投入使用。"},{"i":19,"n":"第十九条","txt":"港口设施建设项目竣工后，应当按照国家有关规定经验收合格，方可投入使用。"},{"i":20,"n":"第二十条","txt":"县级以上有关人民政府应当保证必要的资金投入，用于港口公用的航道、防波堤、锚地等基础设施的建设和维护。具体办法由国务院规定。"},{"i":21,"n":"第二十一条","txt":"县级以上有关人民政府应当采取措施，组织建设与港口相配套的航道、铁路、公路、给排水、供电、通信等设施。"},{"i":22,"n":"第二十二条","txt":"从事港口经营，应当向港口行政管理部门书面申请取得港口经营许可，并依法办理工商登记。"},{"i":23,"n":"第二十三条","txt":"取得港口经营许可，应当有固定的经营场所，有与经营业务相适应的设施、设备、专业技术人员和管理人员，并应当具备法律、法规规定的其他条件。"},{"i":24,"n":"第二十四条","txt":"港口行政管理部门应当自收到本法第二十二条第一款规定的书面申请之日起三十日内依法作出许可或者不予许可的决定。予以许可的，颁发港口经营许可证；不予许可的，应当书面通知申请人并告知理由。"},{"i":25,"n":"第二十五条","txt":"国务院交通主管部门应当制定港口理货服务标准和规范。"},{"i":26,"n":"第二十六条","txt":"港口经营人从事经营活动，必须遵守有关法律、法规，遵守国务院交通主管部门有关港口作业规则的规定，依法履行合同约定的义务，为客户提供公平、良好的服务。"},{"i":27,"n":"第二十七条","txt":"港口经营人应当优先安排抢险物资、救灾物资和国防建设急需物资的作业。"},{"i":28,"n":"第二十八条","txt":"港口经营人应当在其经营场所公布经营服务的收费项目和收费标准；未公布的，不得实施。"},{"i":29,"n":"第二十九条","txt":"国家鼓励和保护港口经营活动的公平竞争。"},{"i":30,"n":"第三十条","txt":"港口行政管理部门依照《中华人民共和国统计法》和有关行政法规的规定要求港口经营人提供的统计资料，港口经营人应当如实提供。"},{"i":31,"n":"第三十一条","txt":"港口经营人的合法权益受法律保护。任何单位和个人不得向港口经营人摊派或者违法收取费用，不得违法干预港口经营人的经营自主权。"},{"i":32,"n":"第三十二条","txt":"港口经营人必须依照《中华人民共和国安全生产法》等有关法律、法规和国务院交通主管部门有关港口安全作业规则的规定，加强安全生产管理，建立健全安全生产责任制等规章制度，完善安全生产条件，采取保障安全生产的有效措施，确保安全生产。"},{"i":33,"n":"第三十三条","txt":"港口行政管理部门应当依法制定可能危及社会公共利益的港口危险货物事故应急预案、重大生产安全事故的旅客紧急疏散和救援预案以及预防自然灾害预案，建立健全港口重大生产安全事故的应急救援体系。"},{"i":34,"n":"第三十四条","txt":"船舶进出港口，应当依照有关水上交通安全的法律、行政法规的规定向海事管理机构报告。海事管理机构接到报告后，应当及时通报港口行政管理部门。"},{"i":35,"n":"第三十五条","txt":"在港口内进行危险货物的装卸、过驳作业，应当按照国务院交通主管部门的规定将危险货物的名称、特性、包装和作业的时间、地点报告港口行政管理部门。港口行政管理部门接到报告后，应当在国务院交通主管部门规定的时间内作出是否同意的决定，通知报告人，并通报海事管理机构。"},{"i":36,"n":"第三十六条","txt":"港口行政管理部门应当依法对港口安全生产情况实施监督检查，对旅客上下集中、货物装卸量较大或者有特殊用途的码头进行重点巡查；检查中发现安全隐患的，应当责令被检查人立即排除或者限期排除。"},{"i":37,"n":"第三十七条","txt":"禁止在港口水域内从事养殖、种植活动。"},{"i":38,"n":"第三十八条","txt":"建设桥梁、水底隧道、水电站等可能影响港口水文条件变化的工程项目，负责审批该项目的部门在审批前应当征求港口行政管理部门的意见。"},{"i":39,"n":"第三十九条","txt":"依照有关水上交通安全的法律、行政法规的规定，进出港口须经引航的船舶，应当向引航机构申请引航。引航的具体办法由国务院交通主管部门规定。"},{"i":40,"n":"第四十条","txt":"遇有旅客滞留、货物积压阻塞港口的情况，港口行政管理部门应当及时采取有效措施，进行疏港；港口所在地的市、县人民政府认为必要时，可以直接采取措施，进行疏港。"},{"i":41,"n":"第四十一条","txt":"港口行政管理部门应当组织制定所管理的港口的章程，并向社会公布。"},{"i":42,"n":"第四十二条","txt":"港口行政管理部门依据职责对本法执行情况实施监督检查。"},{"i":43,"n":"第四十三条","txt":"监督检查人员应当将监督检查的时间、地点、内容、发现的问题及处理情况作出书面记录，并由监督检查人员和被检查单位的负责人签字；被检查单位的负责人拒绝签字的，监督检查人员应当将情况记录在案，并向港口行政管理部门报告。"},{"i":44,"n":"第四十四条","txt":"被检查单位和有关人员应当接受港口行政管理部门依法实施的监督检查，如实提供有关情况和资料，不得拒绝检查或者隐匿、谎报有关情况和资料。"},{"i":45,"n":"第四十五条","txt":"港口经营人、港口理货业务经营人有本法规定的违法行为的，依照有关法律、行政法规的规定纳入信用记录，并予以公示。"},{"i":46,"n":"第四十六条","txt":"有下列行为之一的，由县级以上地方人民政府或者港口行政管理部门责令限期改正；逾期不改正的，由作出限期改正决定的机关申请人民法院强制拆除违法建设的设施；可以处五万元以下罚款："},{"i":47,"n":"第四十七条","txt":"在港口建设的危险货物作业场所、实施卫生除害处理的专用场所与人口密集区或者港口客运设施的距离不符合国务院有关部门的规定的，由港口行政管理部门责令停止建设或者使用，限期改正，可以处五万元以下罚款。"},{"i":48,"n":"第四十八条","txt":"码头或者港口装卸设施、客运设施未经验收合格，擅自投入使用的，由港口行政管理部门责令停止使用，限期改正，可以处五万元以下罚款。"},{"i":49,"n":"第四十九条","txt":"未依法取得港口经营许可证从事港口经营，或者港口理货业务经营人兼营货物装卸经营业务、仓储经营业务的，由港口行政管理部门责令停止违法经营，没收违法所得；违法所得十万元以上的，并处违法所得二倍以上五倍以下罚款；违法所得不足十万元的，处五万元以上二十万元以下罚款。"},{"i":50,"n":"第五十条","txt":"港口经营人不优先安排抢险物资、救灾物资、国防建设急需物资的作业的，由港口行政管理部门责令改正；造成严重后果的，吊销港口经营许可证。"},{"i":51,"n":"第五十一条","txt":"港口经营人违反有关法律、行政法规的规定，在经营活动中实施垄断行为或者不正当竞争行为的，依照有关法律、行政法规的规定承担法律责任。"},{"i":52,"n":"第五十二条","txt":"港口经营人违反本法第三十二条关于安全生产的规定的，由港口行政管理部门或者其他依法负有安全生产监督管理职责的部门依法给予处罚；情节严重的，由港口行政管理部门吊销港口经营许可证，并对其主要负责人依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":53,"n":"第五十三条","txt":"船舶进出港口，未依照本法第三十四条的规定向海事管理机构报告的，由海事管理机构依照有关水上交通安全的法律、行政法规的规定处罚。"},{"i":54,"n":"第五十四条","txt":"未依法向港口行政管理部门报告并经其同意，在港口内进行危险货物的装卸、过驳作业的，由港口行政管理部门责令停止作业，处五千元以上五万元以下罚款。"},{"i":55,"n":"第五十五条","txt":"在港口水域内从事养殖、种植活动的，由海事管理机构责令限期改正；逾期不改正的，强制拆除养殖、种植设施，拆除费用由违法行为人承担；可以处一万元以下罚款。"},{"i":56,"n":"第五十六条","txt":"未经依法批准在港口进行可能危及港口安全的采掘、爆破等活动的，向港口水域倾倒泥土、砂石的，由港口行政管理部门责令停止违法行为，限期消除因此造成的安全隐患；逾期不消除的，强制消除，因此发生的费用由违法行为人承担；处五千元以上五万元以下罚款；依照有关水上交通安全的法律、行政法规的规定由海事管理机构处罚的，依照其规定；构成犯罪的，依法追究刑事责任。"},{"i":57,"n":"第五十七条","txt":"交通主管部门、港口行政管理部门、海事管理机构等不依法履行职责，有下列行为之一的，对直接负责的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任："},{"i":58,"n":"第五十八条","txt":"行政机关违法干预港口经营人的经营自主权的，由其上级行政机关或者监察机关责令改正；向港口经营人摊派财物或者违法收取费用的，责令退回；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予行政处分。"},{"i":59,"n":"第五十九条","txt":"对航行国际航线的船舶开放的港口，由有关省、自治区、直辖市人民政府按照国家有关规定商国务院有关部门和有关军事机关同意后，报国务院批准。"},{"i":60,"n":"第六十条","txt":"渔业港口的管理工作由县级以上人民政府渔业行政主管部门负责。具体管理办法由国务院规定。"},{"i":61,"n":"第六十一条","txt":"军事港口的建设和管理办法由国务院、中央军事委员会规定。"},{"i":62,"n":"第六十二条","txt":"本法自2004年1月1日起施行。"}],"yanyeshuifa":[{"i":1,"n":"第一条","txt":"在中华人民共和国境内，依照《中华人民共和国烟草专卖法》的规定收购烟叶的单位为烟叶税的纳税人。纳税人应当依照本法规定缴纳烟叶税。"},{"i":2,"n":"第二条","txt":"本法所称烟叶，是指烤烟叶、晾晒烟叶。"},{"i":3,"n":"第三条","txt":"烟叶税的计税依据为纳税人收购烟叶实际支付的价款总额。"},{"i":4,"n":"第四条","txt":"烟叶税的税率为百分之二十。"},{"i":5,"n":"第五条","txt":"烟叶税的应纳税额按照纳税人收购烟叶实际支付的价款总额乘以税率计算。"},{"i":6,"n":"第六条","txt":"烟叶税由税务机关依照本法和《中华人民共和国税收征收管理法》的有关规定征收管理。"},{"i":7,"n":"第七条","txt":"纳税人应当向烟叶收购地的主管税务机关申报缴纳烟叶税。"},{"i":8,"n":"第八条","txt":"烟叶税的纳税义务发生时间为纳税人收购烟叶的当日。"},{"i":9,"n":"第九条","txt":"烟叶税按月计征，纳税人应当于纳税义务发生月终了之日起十五日内申报并缴纳税款。"},{"i":10,"n":"第十条","txt":"本法自2018年7月1日起施行。2006年4月28日国务院公布的《中华人民共和国烟叶税暂行条例》同时废止。"}],"yancaozhuanmaifa":[{"i":1,"n":"第一条","txt":"为实行烟草专卖管理，有计划地组织烟草专卖品的生产和经营，提高烟草制品质量，维护消费者利益，保证国家财政收入，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称烟草专卖品是指卷烟、雪茄烟、烟丝、复烤烟叶、烟叶、卷烟纸、滤嘴棒、烟用丝束、烟草专用机械。"},{"i":3,"n":"第三条","txt":"国家对烟草专卖品的生产、销售、进出口依法实行专卖管理，并实行烟草专卖许可证制度。"},{"i":4,"n":"第四条","txt":"国务院烟草专卖行政主管部门主管全国烟草专卖工作。省、自治区、直辖市烟草专卖行政主管部门主管本辖区的烟草专卖工作，受国务院烟草专卖行政主管部门和省、自治区、直辖市人民政府的双重领导，以国务院烟草专卖行政主管部门的领导为主。"},{"i":5,"n":"第五条","txt":"国家加强对烟草专卖品的科学研究和技术开发，提高烟草制品的质量，降低焦油和其他有害成份的含量。"},{"i":6,"n":"第六条","txt":"国家在民族自治地方实行烟草专卖管理，应当依照本法和民族区域自治法的有关规定，照顾民族自治地方的利益，对民族自治地方的烟叶种植和烟草制品生产给予照顾。"},{"i":7,"n":"第七条","txt":"本法所称烟叶是指生产烟草制品所需的烤烟和名晾晒烟，名晾晒烟的名录由国务院烟草专卖行政主管部门规定。"},{"i":8,"n":"第八条","txt":"烟草种植应当因地制宜地培育和推广优良品种。优良品种由当地烟草公司组织供应。"},{"i":9,"n":"第九条","txt":"烟叶收购计划由县级以上地方人民政府计划部门根据国务院计划部门下达的计划下达，其他单位和个人不得变更。"},{"i":10,"n":"第十条","txt":"烟叶由烟草公司或者其委托单位按照国家规定的收购标准统一收购，其他单位和个人不得收购。"},{"i":11,"n":"第十一条","txt":"省、自治区、直辖市之间的烟叶、复烤烟叶的调拨计划由国务院计划部门下达，省、自治区、直辖市辖区内的烟叶、复烤烟叶的调拨计划由省、自治区、直辖市计划部门下达，其他单位和个人不得变更。"},{"i":12,"n":"第十二条","txt":"开办烟草制品生产企业，必须经国务院烟草专卖行政主管部门批准，取得烟草专卖生产企业许可证，并经工商行政管理部门核准登记；其分立、合并、撤销，必须经国务院烟草专卖行政主管部门批准，并向工商行政管理部门办理变更、注销登记手续。未取得烟草专卖生产企业许可证的，工商行政管理部门不得核准登记。"},{"i":13,"n":"第十三条","txt":"烟草制品生产企业为扩大生产能力进行基本建设或者技术改造，必须经国务院烟草专卖行政主管部门批准。"},{"i":14,"n":"第十四条","txt":"省、自治区、直辖市的卷烟、雪茄烟年度总产量计划由国务院计划部门下达。烟草制品生产企业的卷烟、雪茄烟年度总产量计划，由省级烟草专卖行政主管部门根据国务院计划部门下达的计划，结合市场销售情况下达，地方人民政府不得向烟草制品生产企业下达超产任务。烟草制品生产企业根据市场销售情况，需要超过年度总产量计划生产卷烟、雪茄烟，必须经国务院烟草专卖行政主管部门批准。"},{"i":15,"n":"第十五条","txt":"经营烟草制品批发业务的企业，必须经国务院烟草专卖行政主管部门或者省级烟草专卖行政主管部门批准，取得烟草专卖批发企业许可证，并经工商行政管理部门核准登记。"},{"i":16,"n":"第十六条","txt":"经营烟草制品零售业务的企业或者个人，由县级人民政府工商行政管理部门根据上一级烟草专卖行政主管部门的委托，审查批准发给烟草专卖零售许可证。已经设立县级烟草专卖行政主管部门的地方，也可以由县级烟草专卖行政主管部门审查批准发给烟草专卖零售许可证。"},{"i":17,"n":"第十七条","txt":"国家制定卷烟、雪茄烟的焦油含量级标准。卷烟、雪茄烟应当在包装上标明焦油含量级和“吸烟有害健康”。"},{"i":18,"n":"第十八条","txt":"禁止在广播电台、电视台、报刊播放、刊登烟草制品广告。"},{"i":19,"n":"第十九条","txt":"卷烟、雪茄烟和有包装的烟丝必须申请商标注册，未经核准注册的，不得生产、销售。"},{"i":20,"n":"第二十条","txt":"烟草制品商标标识必须由省级工商行政管理部门指定的企业印制；非指定的企业不得印制烟草制品商标标识。"},{"i":21,"n":"第二十一条","txt":"托运或者自运烟草专卖品必须持有烟草专卖行政主管部门或者烟草专卖行政主管部门授权的机构签发的准运证；无准运证的，承运人不得承运。"},{"i":22,"n":"第二十二条","txt":"邮寄、异地携带烟叶、烟草制品的，不得超过国务院有关主管部门规定的限量。"},{"i":23,"n":"第二十三条","txt":"个人进入中国境内携带烟草制品的，不得超过国务院有关主管部门规定的限量。"},{"i":24,"n":"第二十四条","txt":"生产卷烟纸、滤嘴棒、烟用丝束、烟草专用机械的企业，必须报国务院烟草专卖行政主管部门批准，取得烟草专卖生产企业许可证。"},{"i":25,"n":"第二十五条","txt":"生产卷烟纸、滤嘴棒、烟用丝束、烟草专用机械的企业，应当按照国务院烟草专卖行政主管部门的计划以及与烟草制品生产企业签订的订货合同组织生产。"},{"i":26,"n":"第二十六条","txt":"生产卷烟纸、滤嘴棒、烟用丝束、烟草专用机械的企业，只可将产品销售给烟草公司和持有烟草专卖生产企业许可证的烟草制品生产企业。"},{"i":27,"n":"第二十七条","txt":"国务院烟草专卖行政主管部门根据国务院规定，管理烟草行业的进出口贸易和对外经济技术合作。"},{"i":28,"n":"第二十八条","txt":"违反本法规定擅自收购烟叶的，由烟草专卖行政主管部门处以罚款，并按照查获地省级烟草专卖行政主管部门出具的上年度烟叶平均收购价格的百分之七十收购违法收购的烟叶；数量巨大的，没收违法收购的烟叶和违法所得。"},{"i":29,"n":"第二十九条","txt":"无准运证或者超过准运证规定的数量托运或者自运烟草专卖品的，由烟草专卖行政主管部门处以罚款，可以按照查获地省级烟草专卖行政主管部门出具的上年度烟叶平均收购价格的百分之七十收购违法运输的烟叶，按照市场批发价格的百分之七十收购违法运输的除烟叶外的其他烟草专卖品；情节严重的，没收违法运输的烟草专卖品和违法所得。"},{"i":30,"n":"第三十条","txt":"无烟草专卖生产企业许可证生产烟草制品的，由烟草专卖行政主管部门责令关闭，没收违法所得，并处罚款。"},{"i":31,"n":"第三十一条","txt":"无烟草专卖批发企业许可证经营烟草制品批发业务的，由烟草专卖行政主管部门责令关闭或者停止经营烟草制品批发业务，没收违法所得，并处罚款。"},{"i":32,"n":"第三十二条","txt":"无烟草专卖零售许可证经营烟草制品零售业务的，由工商行政管理部门责令停止经营烟草制品零售业务，没收违法所得，并处罚款。"},{"i":33,"n":"第三十三条","txt":"生产、销售没有注册商标的卷烟、雪茄烟、有包装的烟丝的，由工商行政管理部门责令停止生产、销售，并处罚款。"},{"i":34,"n":"第三十四条","txt":"违反本法第二十条的规定，非法印制烟草制品商标标识的，由工商行政管理部门销毁印制的商标标识，没收违法所得，并处罚款。"},{"i":35,"n":"第三十五条","txt":"倒卖烟草专卖品，构成犯罪的，依法追究刑事责任；情节轻微，不构成犯罪的，由工商行政管理部门没收倒卖的烟草专卖品和违法所得，可以并处罚款。"},{"i":36,"n":"第三十六条","txt":"伪造、变造、买卖本法规定的烟草专卖生产企业许可证、烟草专卖经营许可证等许可证件和准运证的，依照刑法有关规定追究刑事责任。"},{"i":37,"n":"第三十七条","txt":"走私烟草专卖品，构成走私罪的，依照刑法有关规定追究刑事责任；走私烟草专卖品，数额不大，不构成走私罪的，由海关没收走私货物、物品和违法所得，可以并处罚款。"},{"i":38,"n":"第三十八条","txt":"烟草专卖行政主管部门有权对本法实施情况进行检查。以暴力、威胁方法阻碍烟草专卖检查人员依法执行职务的，依法追究刑事责任；拒绝、阻碍烟草专卖检查人员依法执行职务未使用暴力、威胁方法的，由公安机关依照治安管理处罚法的规定处罚。"},{"i":39,"n":"第三十九条","txt":"人民法院和处理违法案件的有关部门的工作人员私分没收的烟草制品，依照刑法有关规定追究刑事责任。"},{"i":40,"n":"第四十条","txt":"烟草专卖行政主管部门和烟草公司的工作人员滥用职权、徇私舞弊或者玩忽职守的，给予行政处分；情节严重，构成犯罪的，依法追究刑事责任。"},{"i":41,"n":"第四十一条","txt":"当事人对烟草专卖行政主管部门和工商行政管理部门作出的行政处罚决定不服的，可以在接到处罚通知之日起十五日内向作出处罚决定的机关的上一级机关申请复议；当事人也可以在接到处罚通知之日起十五日内直接向人民法院起诉。"},{"i":42,"n":"第四十二条","txt":"国务院根据本法制定实施条例。"},{"i":43,"n":"第四十三条","txt":"本法自1992年1月1日起施行。1983年9月23日国务院发布的《烟草专卖条例》同时废止。"}],"huanjingbaohushuifa":[{"i":1,"n":"第一条","txt":"为了保护和改善环境，减少污染物排放，推进生态文明建设，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域和中华人民共和国管辖的其他海域，直接向环境排放应税污染物的企业事业单位和其他生产经营者为环境保护税的纳税人，应当依照本法规定缴纳环境保护税。"},{"i":3,"n":"第三条","txt":"本法所称应税污染物，是指本法所附《环境保护税税目税额表》、《应税污染物和当量值表》规定的大气污染物、水污染物、固体废物和噪声。"},{"i":4,"n":"第四条","txt":"有下列情形之一的，不属于直接向环境排放污染物，不缴纳相应污染物的环境保护税："},{"i":5,"n":"第五条","txt":"依法设立的城乡污水集中处理、生活垃圾集中处理场所超过国家和地方规定的排放标准向环境排放应税污染物的，应当缴纳环境保护税。"},{"i":6,"n":"第六条","txt":"环境保护税的税目、税额，依照本法所附《环境保护税税目税额表》执行。"},{"i":7,"n":"第七条","txt":"应税污染物的计税依据，按照下列方法确定："},{"i":8,"n":"第八条","txt":"应税大气污染物、水污染物的污染当量数，以该污染物的排放量除以该污染物的污染当量值计算。每种应税大气污染物、水污染物的具体污染当量值，依照本法所附《应税污染物和当量值表》执行。"},{"i":9,"n":"第九条","txt":"每一排放口或者没有排放口的应税大气污染物，按照污染当量数从大到小排序，对前三项污染物征收环境保护税。"},{"i":10,"n":"第十条","txt":"应税大气污染物、水污染物、固体废物的排放量和噪声的分贝数，按照下列方法和顺序计算："},{"i":11,"n":"第十一条","txt":"环境保护税应纳税额按照下列方法计算："},{"i":12,"n":"第十二条","txt":"下列情形，暂予免征环境保护税："},{"i":13,"n":"第十三条","txt":"纳税人排放应税大气污染物或者水污染物的浓度值低于国家和地方规定的污染物排放标准百分之三十的，减按百分之七十五征收环境保护税。纳税人排放应税大气污染物或者水污染物的浓度值低于国家和地方规定的污染物排放标准百分之五十的，减按百分之五十征收环境保护税。"},{"i":14,"n":"第十四条","txt":"环境保护税由税务机关依照《中华人民共和国税收征收管理法》和本法的有关规定征收管理。"},{"i":15,"n":"第十五条","txt":"生态环境主管部门和税务机关应当建立涉税信息共享平台和工作配合机制。"},{"i":16,"n":"第十六条","txt":"纳税义务发生时间为纳税人排放应税污染物的当日。"},{"i":17,"n":"第十七条","txt":"纳税人应当向应税污染物排放地的税务机关申报缴纳环境保护税。"},{"i":18,"n":"第十八条","txt":"环境保护税按月计算，按季申报缴纳。不能按固定期限计算缴纳的，可以按次申报缴纳。"},{"i":19,"n":"第十九条","txt":"纳税人按季申报缴纳的，应当自季度终了之日起十五日内，向税务机关办理纳税申报并缴纳税款。纳税人按次申报缴纳的，应当自纳税义务发生之日起十五日内，向税务机关办理纳税申报并缴纳税款。"},{"i":20,"n":"第二十条","txt":"税务机关应当将纳税人的纳税申报数据资料与生态环境主管部门交送的相关数据资料进行比对。"},{"i":21,"n":"第二十一条","txt":"依照本法第十条第四项的规定核定计算污染物排放量的，由税务机关会同生态环境主管部门核定污染物排放种类、数量和应纳税额。"},{"i":22,"n":"第二十二条","txt":"纳税人从事海洋工程向中华人民共和国管辖海域排放应税大气污染物、水污染物或者固体废物，申报缴纳环境保护税的具体办法，由国务院税务主管部门会同国务院生态环境主管部门规定。"},{"i":23,"n":"第二十三条","txt":"纳税人和税务机关、生态环境主管部门及其工作人员违反本法规定的，依照《中华人民共和国税收征收管理法》、《中华人民共和国环境保护法》和有关法律法规的规定追究法律责任。"},{"i":24,"n":"第二十四条","txt":"各级人民政府应当鼓励纳税人加大环境保护建设投入，对纳税人用于污染物自动监测设备的投资予以资金和政策支持。"},{"i":25,"n":"第二十五条","txt":"本法下列用语的含义："},{"i":26,"n":"第二十六条","txt":"直接向环境排放应税污染物的企业事业单位和其他生产经营者，除依照本法规定缴纳环境保护税外，应当对所造成的损害依法承担责任。"},{"i":27,"n":"第二十七条","txt":"国务院根据国民经济和社会发展以及环境保护需要，对直接向环境排放本法所附《应税污染物和当量值表》规定以外的挥发性有机物的企业事业单位和其他生产经营者开展征收环境保护税试点工作。试点实施办法由国务院制定，报全国人民代表大会常务委员会备案。"},{"i":28,"n":"第二十八条","txt":"自本法施行之日起，依照本法规定征收环境保护税，不再征收排污费。"},{"i":29,"n":"第二十九条","txt":"本法自2018年1月1日起施行。"}],"dianlifa":[{"i":1,"n":"第一条","txt":"为了保障和促进电力事业的发展，维护电力投资者、经营者和使用者的合法权益，保障电力安全运行，制定本法。"},{"i":2,"n":"第二条","txt":"本法适用于中华人民共和国境内的电力建设、生产、供应和使用活动。"},{"i":3,"n":"第三条","txt":"电力事业应当适应国民经济和社会发展的需要，适当超前发展。国家鼓励、引导国内外的经济组织和个人依法投资开发电源，兴办电力生产企业。"},{"i":4,"n":"第四条","txt":"电力设施受国家保护。"},{"i":5,"n":"第五条","txt":"电力建设、生产、供应和使用应当依法保护环境，采用新技术，减少有害物质排放，防治污染和其他公害。"},{"i":6,"n":"第六条","txt":"国务院电力管理部门负责全国电力事业的监督管理。国务院有关部门在各自的职责范围内负责电力事业的监督管理。"},{"i":7,"n":"第七条","txt":"电力建设企业、电力生产企业、电网经营企业依法实行自主经营、自负盈亏，并接受电力管理部门的监督。"},{"i":8,"n":"第八条","txt":"国家帮助和扶持少数民族地区、边远地区和贫困地区发展电力事业。"},{"i":9,"n":"第九条","txt":"国家鼓励在电力建设、生产、供应和使用过程中，采用先进的科学技术和管理方法，对在研究、开发、采用先进的科学技术和管理方法等方面作出显著成绩的单位和个人给予奖励。"},{"i":10,"n":"第十条","txt":"电力发展规划应当根据国民经济和社会发展的需要制定，并纳入国民经济和社会发展计划。"},{"i":11,"n":"第十一条","txt":"城市电网的建设与改造规划，应当纳入城市总体规划。城市人民政府应当按照规划，安排变电设施用地、输电线路走廊和电缆通道。"},{"i":12,"n":"第十二条","txt":"国家通过制定有关政策，支持、促进电力建设。"},{"i":13,"n":"第十三条","txt":"电力投资者对其投资形成的电力，享有法定权益。并网运行的，电力投资者有优先使用权；未并网的自备电厂，电力投资者自行支配使用。"},{"i":14,"n":"第十四条","txt":"电力建设项目应当符合电力发展规划，符合国家电力产业政策。"},{"i":15,"n":"第十五条","txt":"输变电工程、调度通信自动化工程等电网配套工程和环境保护工程，应当与发电工程项目同时设计、同时建设、同时验收、同时投入使用。"},{"i":16,"n":"第十六条","txt":"电力建设项目使用土地，应当依照有关法律、行政法规的规定办理；依法征收土地的，应当依法支付土地补偿费和安置补偿费，做好迁移居民的安置工作。"},{"i":17,"n":"第十七条","txt":"地方人民政府应当支持电力企业为发电工程建设勘探水源和依法取水、用水。电力企业应当节约用水。"},{"i":18,"n":"第十八条","txt":"电力生产与电网运行应当遵循安全、优质、经济的原则。"},{"i":19,"n":"第十九条","txt":"电力企业应当加强安全生产管理，坚持安全第一、预防为主的方针，建立、健全安全生产责任制度。"},{"i":20,"n":"第二十条","txt":"发电燃料供应企业、运输企业和电力生产企业应当依照国务院有关规定或者合同约定供应、运输和接卸燃料。"},{"i":21,"n":"第二十一条","txt":"电网运行实行统一调度、分级管理。任何单位和个人不得非法干预电网调度。"},{"i":22,"n":"第二十二条","txt":"国家提倡电力生产企业与电网、电网与电网并网运行。具有独立法人资格的电力生产企业要求将生产的电力并网运行的，电网经营企业应当接受。"},{"i":23,"n":"第二十三条","txt":"电网调度管理办法，由国务院依照本法的规定制定。"},{"i":24,"n":"第二十四条","txt":"国家对电力供应和使用，实行安全用电、节约用电、计划用电的管理原则。"},{"i":25,"n":"第二十五条","txt":"供电企业在批准的供电营业区内向用户供电。"},{"i":26,"n":"第二十六条","txt":"供电营业区内的供电营业机构，对本营业区内的用户有按照国家规定供电的义务；不得违反国家规定对其营业区内申请用电的单位和个人拒绝供电。"},{"i":27,"n":"第二十七条","txt":"电力供应与使用双方应当根据平等自愿、协商一致的原则，按照国务院制定的电力供应与使用办法签订供用电合同，确定双方的权利和义务。"},{"i":28,"n":"第二十八条","txt":"供电企业应当保证供给用户的供电质量符合国家标准。对公用供电设施引起的供电质量问题，应当及时处理。"},{"i":29,"n":"第二十九条","txt":"供电企业在发电、供电系统正常的情况下，应当连续向用户供电，不得中断。因供电设施检修、依法限电或者用户违法用电等原因，需要中断供电时，供电企业应当按照国家有关规定事先通知用户。"},{"i":30,"n":"第三十条","txt":"因抢险救灾需要紧急供电时，供电企业必须尽速安排供电，所需供电工程费用和应付电费依照国家有关规定执行。"},{"i":31,"n":"第三十一条","txt":"用户应当安装用电计量装置。用户使用的电力电量，以计量检定机构依法认可的用电计量装置的记录为准。"},{"i":32,"n":"第三十二条","txt":"用户用电不得危害供电、用电安全和扰乱供电、用电秩序。"},{"i":33,"n":"第三十三条","txt":"供电企业应当按照国家核准的电价和用电计量装置的记录，向用户计收电费。"},{"i":34,"n":"第三十四条","txt":"供电企业和用户应当遵守国家有关规定，采取有效措施，做好安全用电、节约用电和计划用电工作。"},{"i":35,"n":"第三十五条","txt":"本法所称电价，是指电力生产企业的上网电价、电网间的互供电价、电网销售电价。"},{"i":36,"n":"第三十六条","txt":"制定电价，应当合理补偿成本，合理确定收益，依法计入税金，坚持公平负担，促进电力建设。"},{"i":37,"n":"第三十七条","txt":"上网电价实行同网同质同价。具体办法和实施步骤由国务院规定。"},{"i":38,"n":"第三十八条","txt":"跨省、自治区、直辖市电网和省级电网内的上网电价，由电力生产企业和电网经营企业协商提出方案，报国务院物价行政主管部门核准。"},{"i":39,"n":"第三十九条","txt":"跨省、自治区、直辖市电网和独立电网之间、省级电网和独立电网之间的互供电价，由双方协商提出方案，报国务院物价行政主管部门或者其授权的部门核准。"},{"i":40,"n":"第四十条","txt":"跨省、自治区、直辖市电网和省级电网的销售电价，由电网经营企业提出方案，报国务院物价行政主管部门或者其授权的部门核准。"},{"i":41,"n":"第四十一条","txt":"国家实行分类电价和分时电价。分类标准和分时办法由国务院确定。"},{"i":42,"n":"第四十二条","txt":"用户用电增容收费标准，由国务院物价行政主管部门会同国务院电力管理部门制定。"},{"i":43,"n":"第四十三条","txt":"任何单位不得超越电价管理权限制定电价。供电企业不得擅自变更电价。"},{"i":44,"n":"第四十四条","txt":"禁止任何单位和个人在电费中加收其他费用；但是，法律、行政法规另有规定的，按照规定执行。"},{"i":45,"n":"第四十五条","txt":"电价的管理办法，由国务院依照本法的规定制定。"},{"i":46,"n":"第四十六条","txt":"省、自治区、直辖市人民政府应当制定农村电气化发展规划，并将其纳入当地电力发展规划及国民经济和社会发展计划。"},{"i":47,"n":"第四十七条","txt":"国家对农村电气化实行优惠政策，对少数民族地区、边远地区和贫困地区的农村电力建设给予重点扶持。"},{"i":48,"n":"第四十八条","txt":"国家提倡农村开发水能资源，建设中、小型水电站，促进农村电气化。"},{"i":49,"n":"第四十九条","txt":"县级以上地方人民政府及其经济综合主管部门在安排用电指标时，应当保证农业和农村用电的适当比例，优先保证农村排涝、抗旱和农业季节性生产用电。"},{"i":50,"n":"第五十条","txt":"农业用电价格按照保本、微利的原则确定。"},{"i":51,"n":"第五十一条","txt":"农业和农村用电管理办法，由国务院依照本法的规定制定。"},{"i":52,"n":"第五十二条","txt":"任何单位和个人不得危害发电设施、变电设施和电力线路设施及其有关辅助设施。"},{"i":53,"n":"第五十三条","txt":"电力管理部门应当按照国务院有关电力设施保护的规定，对电力设施保护区设立标志。"},{"i":54,"n":"第五十四条","txt":"任何单位和个人需要在依法划定的电力设施保护区内进行可能危及电力设施安全的作业时，应当经电力管理部门批准并采取安全措施后，方可进行作业。"},{"i":55,"n":"第五十五条","txt":"电力设施与公用工程、绿化工程和其他工程在新建、改建或者扩建中相互妨碍时，有关单位应当按照国家有关规定协商，达成协议后方可施工。"},{"i":56,"n":"第五十六条","txt":"电力管理部门依法对电力企业和用户执行电力法律、行政法规的情况进行监督检查。"},{"i":57,"n":"第五十七条","txt":"电力管理部门根据工作需要，可以配备电力监督检查人员。"},{"i":58,"n":"第五十八条","txt":"电力监督检查人员进行监督检查时，有权向电力企业或者用户了解有关执行电力法律、行政法规的情况，查阅有关资料，并有权进入现场进行检查。"},{"i":59,"n":"第五十九条","txt":"电力企业或者用户违反供用电合同，给对方造成损失的，应当依法承担赔偿责任。"},{"i":60,"n":"第六十条","txt":"因电力运行事故给用户或者第三人造成损害的，电力企业应当依法承担赔偿责任。"},{"i":61,"n":"第六十一条","txt":"违反本法第十一条第二款的规定，非法占用变电设施用地、输电线路走廊或者电缆通道的，由县级以上地方人民政府责令限期改正；逾期不改正的，强制清除障碍。"},{"i":62,"n":"第六十二条","txt":"违反本法第十四条规定，电力建设项目不符合电力发展规划、产业政策的，由电力管理部门责令停止建设。"},{"i":63,"n":"第六十三条","txt":"违反本法第二十五条规定，未经许可，从事供电或者变更供电营业区的，由电力管理部门责令改正，没收违法所得，可以并处违法所得五倍以下的罚款。"},{"i":64,"n":"第六十四条","txt":"违反本法第二十六条、第二十九条规定，拒绝供电或者中断供电的，由电力管理部门责令改正，给予警告；情节严重的，对有关主管人员和直接责任人员给予行政处分。"},{"i":65,"n":"第六十五条","txt":"违反本法第三十二条规定，危害供电、用电安全或者扰乱供电、用电秩序的，由电力管理部门责令改正，给予警告；情节严重或者拒绝改正的，可以中止供电，可以并处五万元以下的罚款。"},{"i":66,"n":"第六十六条","txt":"违反本法第三十三条、第四十三条、第四十四条规定，未按照国家核准的电价和用电计量装置的记录向用户计收电费、超越权限制定电价或者在电费中加收其他费用的，由物价行政主管部门给予警告，责令返还违法收取的费用，可以并处违法收取费用五倍以下的罚款；情节严重的，对有关主管人员和直接责任人员给予行政处分。"},{"i":67,"n":"第六十七条","txt":"违反本法第四十九条第二款规定，减少农业和农村用电指标的，由电力管理部门责令改正；情节严重的，对有关主管人员和直接责任人员给予行政处分；造成损失的，责令赔偿损失。"},{"i":68,"n":"第六十八条","txt":"违反本法第五十二条第二款和第五十四条规定，未经批准或者未采取安全措施在电力设施周围或者在依法划定的电力设施保护区内进行作业，危及电力设施安全的，由电力管理部门责令停止作业、恢复原状并赔偿损失。"},{"i":69,"n":"第六十九条","txt":"违反本法第五十三条规定，在依法划定的电力设施保护区内修建建筑物、构筑物或者种植植物、堆放物品，危及电力设施安全的，由当地人民政府责令强制拆除、砍伐或者清除。"},{"i":70,"n":"第七十条","txt":"有下列行为之一，应当给予治安管理处罚的，由公安机关依照治安管理处罚法的有关规定予以处罚；构成犯罪的，依法追究刑事责任："},{"i":71,"n":"第七十一条","txt":"盗窃电能的，由电力管理部门责令停止违法行为，追缴电费并处应交电费五倍以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任。"},{"i":72,"n":"第七十二条","txt":"盗窃电力设施或者以其他方法破坏电力设施，危害公共安全的，依照刑法有关规定追究刑事责任。"},{"i":73,"n":"第七十三条","txt":"电力管理部门的工作人员滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":74,"n":"第七十四条","txt":"电力企业职工违反规章制度、违章调度或者不服从调度指令，造成重大事故的，依照刑法有关规定追究刑事责任。"},{"i":75,"n":"第七十五条","txt":"本法自1996年4月1日起施行。"}],"dianzishangwufa":[{"i":1,"n":"第一条","txt":"为了保障电子商务各方主体的合法权益，规范电子商务行为，维护市场秩序，促进电子商务持续健康发展，制定本法。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内的电子商务活动，适用本法。"},{"i":3,"n":"第三条","txt":"国家鼓励发展电子商务新业态，创新商业模式，促进电子商务技术研发和推广应用，推进电子商务诚信体系建设，营造有利于电子商务创新发展的市场环境，充分发挥电子商务在推动高质量发展、满足人民日益增长的美好生活需要、构建开放型经济方面的重要作用。"},{"i":4,"n":"第四条","txt":"国家平等对待线上线下商务活动，促进线上线下融合发展，各级人民政府和有关部门不得采取歧视性的政策措施，不得滥用行政权力排除、限制市场竞争。"},{"i":5,"n":"第五条","txt":"电子商务经营者从事经营活动，应当遵循自愿、平等、公平、诚信的原则，遵守法律和商业道德，公平参与市场竞争，履行消费者权益保护、环境保护、知识产权保护、网络安全与个人信息保护等方面的义务，承担产品和服务质量责任，接受政府和社会的监督。"},{"i":6,"n":"第六条","txt":"国务院有关部门按照职责分工负责电子商务发展促进、监督管理等工作。县级以上地方各级人民政府可以根据本行政区域的实际情况，确定本行政区域内电子商务的部门职责划分。"},{"i":7,"n":"第七条","txt":"国家建立符合电子商务特点的协同管理体系，推动形成有关部门、电子商务行业组织、电子商务经营者、消费者等共同参与的电子商务市场治理体系。"},{"i":8,"n":"第八条","txt":"电子商务行业组织按照本组织章程开展行业自律，建立健全行业规范，推动行业诚信建设，监督、引导本行业经营者公平参与市场竞争。"},{"i":9,"n":"第九条","txt":"本法所称电子商务经营者，是指通过互联网等信息网络从事销售商品或者提供服务的经营活动的自然人、法人和非法人组织，包括电子商务平台经营者、平台内经营者以及通过自建网站、其他网络服务销售商品或者提供服务的电子商务经营者。"},{"i":10,"n":"第十条","txt":"电子商务经营者应当依法办理市场主体登记。但是，个人销售自产农副产品、家庭手工业产品，个人利用自己的技能从事依法无须取得许可的便民劳务活动和零星小额交易活动，以及依照法律、行政法规不需要进行登记的除外。"},{"i":11,"n":"第十一条","txt":"电子商务经营者应当依法履行纳税义务，并依法享受税收优惠。"},{"i":12,"n":"第十二条","txt":"电子商务经营者从事经营活动，依法需要取得相关行政许可的，应当依法取得行政许可。"},{"i":13,"n":"第十三条","txt":"电子商务经营者销售的商品或者提供的服务应当符合保障人身、财产安全的要求和环境保护要求，不得销售或者提供法律、行政法规禁止交易的商品或者服务。"},{"i":14,"n":"第十四条","txt":"电子商务经营者销售商品或者提供服务应当依法出具纸质发票或者电子发票等购货凭证或者服务单据。电子发票与纸质发票具有同等法律效力。"},{"i":15,"n":"第十五条","txt":"电子商务经营者应当在其首页显著位置，持续公示营业执照信息、与其经营业务有关的行政许可信息、属于依照本法第十条规定的不需要办理市场主体登记情形等信息，或者上述信息的链接标识。"},{"i":16,"n":"第十六条","txt":"电子商务经营者自行终止从事电子商务的，应当提前三十日在首页显著位置持续公示有关信息。"},{"i":17,"n":"第十七条","txt":"电子商务经营者应当全面、真实、准确、及时地披露商品或者服务信息，保障消费者的知情权和选择权。电子商务经营者不得以虚构交易、编造用户评价等方式进行虚假或者引人误解的商业宣传，欺骗、误导消费者。"},{"i":18,"n":"第十八条","txt":"电子商务经营者根据消费者的兴趣爱好、消费习惯等特征向其提供商品或者服务的搜索结果的，应当同时向该消费者提供不针对其个人特征的选项，尊重和平等保护消费者合法权益。"},{"i":19,"n":"第十九条","txt":"电子商务经营者搭售商品或者服务，应当以显著方式提请消费者注意，不得将搭售商品或者服务作为默认同意的选项。"},{"i":20,"n":"第二十条","txt":"电子商务经营者应当按照承诺或者与消费者约定的方式、时限向消费者交付商品或者服务，并承担商品运输中的风险和责任。但是，消费者另行选择快递物流服务提供者的除外。"},{"i":21,"n":"第二十一条","txt":"电子商务经营者按照约定向消费者收取押金的，应当明示押金退还的方式、程序，不得对押金退还设置不合理条件。消费者申请退还押金，符合押金退还条件的，电子商务经营者应当及时退还。"},{"i":22,"n":"第二十二条","txt":"电子商务经营者因其技术优势、用户数量、对相关行业的控制能力以及其他经营者对该电子商务经营者在交易上的依赖程度等因素而具有市场支配地位的，不得滥用市场支配地位，排除、限制竞争。"},{"i":23,"n":"第二十三条","txt":"电子商务经营者收集、使用其用户的个人信息，应当遵守法律、行政法规有关个人信息保护的规定。"},{"i":24,"n":"第二十四条","txt":"电子商务经营者应当明示用户信息查询、更正、删除以及用户注销的方式、程序，不得对用户信息查询、更正、删除以及用户注销设置不合理条件。"},{"i":25,"n":"第二十五条","txt":"有关主管部门依照法律、行政法规的规定要求电子商务经营者提供有关电子商务数据信息的，电子商务经营者应当提供。有关主管部门应当采取必要措施保护电子商务经营者提供的数据信息的安全，并对其中的个人信息、隐私和商业秘密严格保密，不得泄露、出售或者非法向他人提供。"},{"i":26,"n":"第二十六条","txt":"电子商务经营者从事跨境电子商务，应当遵守进出口监督管理的法律、行政法规和国家有关规定。"},{"i":27,"n":"第二十七条","txt":"电子商务平台经营者应当要求申请进入平台销售商品或者提供服务的经营者提交其身份、地址、联系方式、行政许可等真实信息，进行核验、登记，建立登记档案，并定期核验更新。"},{"i":28,"n":"第二十八条","txt":"电子商务平台经营者应当按照规定向市场监督管理部门报送平台内经营者的身份信息，提示未办理市场主体登记的经营者依法办理登记，并配合市场监督管理部门，针对电子商务的特点，为应当办理市场主体登记的经营者办理登记提供便利。"},{"i":29,"n":"第二十九条","txt":"电子商务平台经营者发现平台内的商品或者服务信息存在违反本法第十二条、第十三条规定情形的，应当依法采取必要的处置措施，并向有关主管部门报告。"},{"i":30,"n":"第三十条","txt":"电子商务平台经营者应当采取技术措施和其他必要措施保证其网络安全、稳定运行，防范网络违法犯罪活动，有效应对网络安全事件，保障电子商务交易安全。"},{"i":31,"n":"第三十一条","txt":"电子商务平台经营者应当记录、保存平台上发布的商品和服务信息、交易信息，并确保信息的完整性、保密性、可用性。商品和服务信息、交易信息保存时间自交易完成之日起不少于三年；法律、行政法规另有规定的，依照其规定。"},{"i":32,"n":"第三十二条","txt":"电子商务平台经营者应当遵循公开、公平、公正的原则，制定平台服务协议和交易规则，明确进入和退出平台、商品和服务质量保障、消费者权益保护、个人信息保护等方面的权利和义务。"},{"i":33,"n":"第三十三条","txt":"电子商务平台经营者应当在其首页显著位置持续公示平台服务协议和交易规则信息或者上述信息的链接标识，并保证经营者和消费者能够便利、完整地阅览和下载。"},{"i":34,"n":"第三十四条","txt":"电子商务平台经营者修改平台服务协议和交易规则，应当在其首页显著位置公开征求意见，采取合理措施确保有关各方能够及时充分表达意见。修改内容应当至少在实施前七日予以公示。"},{"i":35,"n":"第三十五条","txt":"电子商务平台经营者不得利用服务协议、交易规则以及技术等手段，对平台内经营者在平台内的交易、交易价格以及与其他经营者的交易等进行不合理限制或者附加不合理条件，或者向平台内经营者收取不合理费用。"},{"i":36,"n":"第三十六条","txt":"电子商务平台经营者依据平台服务协议和交易规则对平台内经营者违反法律、法规的行为实施警示、暂停或者终止服务等措施的，应当及时公示。"},{"i":37,"n":"第三十七条","txt":"电子商务平台经营者在其平台上开展自营业务的，应当以显著方式区分标记自营业务和平台内经营者开展的业务，不得误导消费者。"},{"i":38,"n":"第三十八条","txt":"电子商务平台经营者知道或者应当知道平台内经营者销售的商品或者提供的服务不符合保障人身、财产安全的要求，或者有其他侵害消费者合法权益行为，未采取必要措施的，依法与该平台内经营者承担连带责任。"},{"i":39,"n":"第三十九条","txt":"电子商务平台经营者应当建立健全信用评价制度，公示信用评价规则，为消费者提供对平台内销售的商品或者提供的服务进行评价的途径。"},{"i":40,"n":"第四十条","txt":"电子商务平台经营者应当根据商品或者服务的价格、销量、信用等以多种方式向消费者显示商品或者服务的搜索结果；对于竞价排名的商品或者服务，应当显著标明“广告”。"},{"i":41,"n":"第四十一条","txt":"电子商务平台经营者应当建立知识产权保护规则，与知识产权权利人加强合作，依法保护知识产权。"},{"i":42,"n":"第四十二条","txt":"知识产权权利人认为其知识产权受到侵害的，有权通知电子商务平台经营者采取删除、屏蔽、断开链接、终止交易和服务等必要措施。通知应当包括构成侵权的初步证据。"},{"i":43,"n":"第四十三条","txt":"平台内经营者接到转送的通知后，可以向电子商务平台经营者提交不存在侵权行为的声明。声明应当包括不存在侵权行为的初步证据。"},{"i":44,"n":"第四十四条","txt":"电子商务平台经营者应当及时公示收到的本法第四十二条、第四十三条规定的通知、声明及处理结果。"},{"i":45,"n":"第四十五条","txt":"电子商务平台经营者知道或者应当知道平台内经营者侵犯知识产权的，应当采取删除、屏蔽、断开链接、终止交易和服务等必要措施；未采取必要措施的，与侵权人承担连带责任。"},{"i":46,"n":"第四十六条","txt":"除本法第九条第二款规定的服务外，电子商务平台经营者可以按照平台服务协议和交易规则，为经营者之间的电子商务提供仓储、物流、支付结算、交收等服务。电子商务平台经营者为经营者之间的电子商务提供服务，应当遵守法律、行政法规和国家有关规定，不得采取集中竞价、做市商等集中交易方式进行交易，不得进行标准化合约交易。"},{"i":47,"n":"第四十七条","txt":"电子商务当事人订立和履行合同，适用本章和《中华人民共和国民法总则》《中华人民共和国合同法》《中华人民共和国电子签名法》等法律的规定。"},{"i":48,"n":"第四十八条","txt":"电子商务当事人使用自动信息系统订立或者履行合同的行为对使用该系统的当事人具有法律效力。"},{"i":49,"n":"第四十九条","txt":"电子商务经营者发布的商品或者服务信息符合要约条件的，用户选择该商品或者服务并提交订单成功，合同成立。当事人另有约定的，从其约定。"},{"i":50,"n":"第五十条","txt":"电子商务经营者应当清晰、全面、明确地告知用户订立合同的步骤、注意事项、下载方法等事项，并保证用户能够便利、完整地阅览和下载。"},{"i":51,"n":"第五十一条","txt":"合同标的为交付商品并采用快递物流方式交付的，收货人签收时间为交付时间。合同标的为提供服务的，生成的电子凭证或者实物凭证中载明的时间为交付时间；前述凭证没有载明时间或者载明时间与实际提供服务时间不一致的，实际提供服务的时间为交付时间。"},{"i":52,"n":"第五十二条","txt":"电子商务当事人可以约定采用快递物流方式交付商品。"},{"i":53,"n":"第五十三条","txt":"电子商务当事人可以约定采用电子支付方式支付价款。"},{"i":54,"n":"第五十四条","txt":"电子支付服务提供者提供电子支付服务不符合国家有关支付安全管理要求，造成用户损失的，应当承担赔偿责任。"},{"i":55,"n":"第五十五条","txt":"用户在发出支付指令前，应当核对支付指令所包含的金额、收款人等完整信息。"},{"i":56,"n":"第五十六条","txt":"电子支付服务提供者完成电子支付后，应当及时准确地向用户提供符合约定方式的确认支付的信息。"},{"i":57,"n":"第五十七条","txt":"用户应当妥善保管交易密码、电子签名数据等安全工具。用户发现安全工具遗失、被盗用或者未经授权的支付的，应当及时通知电子支付服务提供者。"},{"i":58,"n":"第五十八条","txt":"国家鼓励电子商务平台经营者建立有利于电子商务发展和消费者权益保护的商品、服务质量担保机制。"},{"i":59,"n":"第五十九条","txt":"电子商务经营者应当建立便捷、有效的投诉、举报机制，公开投诉、举报方式等信息，及时受理并处理投诉、举报。"},{"i":60,"n":"第六十条","txt":"电子商务争议可以通过协商和解，请求消费者组织、行业协会或者其他依法成立的调解组织调解，向有关部门投诉，提请仲裁，或者提起诉讼等方式解决。"},{"i":61,"n":"第六十一条","txt":"消费者在电子商务平台购买商品或者接受服务，与平台内经营者发生争议时，电子商务平台经营者应当积极协助消费者维护合法权益。"},{"i":62,"n":"第六十二条","txt":"在电子商务争议处理中，电子商务经营者应当提供原始合同和交易记录。因电子商务经营者丢失、伪造、篡改、销毁、隐匿或者拒绝提供前述资料，致使人民法院、仲裁机构或者有关机关无法查明事实的，电子商务经营者应当承担相应的法律责任。"},{"i":63,"n":"第六十三条","txt":"电子商务平台经营者可以建立争议在线解决机制，制定并公示争议解决规则，根据自愿原则，公平、公正地解决当事人的争议。"},{"i":64,"n":"第六十四条","txt":"国务院和省、自治区、直辖市人民政府应当将电子商务发展纳入国民经济和社会发展规划，制定科学合理的产业政策，促进电子商务创新发展。"},{"i":65,"n":"第六十五条","txt":"国务院和县级以上地方人民政府及其有关部门应当采取措施，支持、推动绿色包装、仓储、运输，促进电子商务绿色发展。"},{"i":66,"n":"第六十六条","txt":"国家推动电子商务基础设施和物流网络建设，完善电子商务统计制度，加强电子商务标准体系建设。"},{"i":67,"n":"第六十七条","txt":"国家推动电子商务在国民经济各个领域的应用，支持电子商务与各产业融合发展。"},{"i":68,"n":"第六十八条","txt":"国家促进农业生产、加工、流通等环节的互联网技术应用，鼓励各类社会资源加强合作，促进农村电子商务发展，发挥电子商务在精准扶贫中的作用。"},{"i":69,"n":"第六十九条","txt":"国家维护电子商务交易安全，保护电子商务用户信息，鼓励电子商务数据开发应用，保障电子商务数据依法有序自由流动。"},{"i":70,"n":"第七十条","txt":"国家支持依法设立的信用评价机构开展电子商务信用评价，向社会提供电子商务信用评价服务。"},{"i":71,"n":"第七十一条","txt":"国家促进跨境电子商务发展，建立健全适应跨境电子商务特点的海关、税收、进出境检验检疫、支付结算等管理制度，提高跨境电子商务各环节便利化水平，支持跨境电子商务平台经营者等为跨境电子商务提供仓储物流、报关、报检等服务。"},{"i":72,"n":"第七十二条","txt":"国家进出口管理部门应当推进跨境电子商务海关申报、纳税、检验检疫等环节的综合服务和监管体系建设，优化监管流程，推动实现信息共享、监管互认、执法互助，提高跨境电子商务服务和监管效率。跨境电子商务经营者可以凭电子单证向国家进出口管理部门办理有关手续。"},{"i":73,"n":"第七十三条","txt":"国家推动建立与不同国家、地区之间跨境电子商务的交流合作，参与电子商务国际规则的制定，促进电子签名、电子身份等国际互认。"},{"i":74,"n":"第七十四条","txt":"电子商务经营者销售商品或者提供服务，不履行合同义务或者履行合同义务不符合约定，或者造成他人损害的，依法承担民事责任。"},{"i":75,"n":"第七十五条","txt":"电子商务经营者违反本法第十二条、第十三条规定，未取得相关行政许可从事经营活动，或者销售、提供法律、行政法规禁止交易的商品、服务，或者不履行本法第二十五条规定的信息提供义务，电子商务平台经营者违反本法第四十六条规定，采取集中交易方式进行交易，或者进行标准化合约交易的，依照有关法律、行政法规的规定处罚。"},{"i":76,"n":"第七十六条","txt":"电子商务经营者违反本法规定，有下列行为之一的，由市场监督管理部门责令限期改正，可以处一万元以下的罚款，对其中的电子商务平台经营者，依照本法第八十一条第一款的规定处罚："},{"i":77,"n":"第七十七条","txt":"电子商务经营者违反本法第十八条第一款规定提供搜索结果，或者违反本法第十九条规定搭售商品、服务的，由市场监督管理部门责令限期改正，没收违法所得，可以并处五万元以上二十万元以下的罚款；情节严重的，并处二十万元以上五十万元以下的罚款。"},{"i":78,"n":"第七十八条","txt":"电子商务经营者违反本法第二十一条规定，未向消费者明示押金退还的方式、程序，对押金退还设置不合理条件，或者不及时退还押金的，由有关主管部门责令限期改正，可以处五万元以上二十万元以下的罚款；情节严重的，处二十万元以上五十万元以下的罚款。"},{"i":79,"n":"第七十九条","txt":"电子商务经营者违反法律、行政法规有关个人信息保护的规定，或者不履行本法第三十条和有关法律、行政法规规定的网络安全保障义务的，依照《中华人民共和国网络安全法》等法律、行政法规的规定处罚。"},{"i":80,"n":"第八十条","txt":"电子商务平台经营者有下列行为之一的，由有关主管部门责令限期改正；逾期不改正的，处二万元以上十万元以下的罚款；情节严重的，责令停业整顿，并处十万元以上五十万元以下的罚款："},{"i":81,"n":"第八十一条","txt":"电子商务平台经营者违反本法规定，有下列行为之一的，由市场监督管理部门责令限期改正，可以处二万元以上十万元以下的罚款；情节严重的，处十万元以上五十万元以下的罚款："},{"i":82,"n":"第八十二条","txt":"电子商务平台经营者违反本法第三十五条规定，对平台内经营者在平台内的交易、交易价格或者与其他经营者的交易等进行不合理限制或者附加不合理条件，或者向平台内经营者收取不合理费用的，由市场监督管理部门责令限期改正，可以处五万元以上五十万元以下的罚款；情节严重的，处五十万元以上二百万元以下的罚款。"},{"i":83,"n":"第八十三条","txt":"电子商务平台经营者违反本法第三十八条规定，对平台内经营者侵害消费者合法权益行为未采取必要措施，或者对平台内经营者未尽到资质资格审核义务，或者对消费者未尽到安全保障义务的，由市场监督管理部门责令限期改正，可以处五万元以上五十万元以下的罚款；情节严重的，责令停业整顿，并处五十万元以上二百万元以下的罚款。"},{"i":84,"n":"第八十四条","txt":"电子商务平台经营者违反本法第四十二条、第四十五条规定，对平台内经营者实施侵犯知识产权行为未依法采取必要措施的，由有关知识产权行政部门责令限期改正；逾期不改正的，处五万元以上五十万元以下的罚款；情节严重的，处五十万元以上二百万元以下的罚款。"},{"i":85,"n":"第八十五条","txt":"电子商务经营者违反本法规定，销售的商品或者提供的服务不符合保障人身、财产安全的要求，实施虚假或者引人误解的商业宣传等不正当竞争行为，滥用市场支配地位，或者实施侵犯知识产权、侵害消费者权益等行为的，依照有关法律的规定处罚。"},{"i":86,"n":"第八十六条","txt":"电子商务经营者有本法规定的违法行为的，依照有关法律、行政法规的规定记入信用档案，并予以公示。"},{"i":87,"n":"第八十七条","txt":"依法负有电子商务监督管理职责的部门的工作人员，玩忽职守、滥用职权、徇私舞弊，或者泄露、出售或者非法向他人提供在履行职责中所知悉的个人信息、隐私和商业秘密的，依法追究法律责任。"},{"i":88,"n":"第八十八条","txt":"违反本法规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":89,"n":"第八十九条","txt":"本法自2019年1月1日起施行。"}],"xumufa":[{"i":1,"n":"第一条","txt":"为了规范畜牧业生产经营行为，保障畜禽产品供给和质量安全，保护和合理利用畜禽遗传资源，培育和推广畜禽优良品种，振兴畜禽种业，维护畜牧业生产经营者的合法权益，防范公共卫生风险，促进畜牧业高质量发展，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事畜禽的遗传资源保护利用、繁育、饲养、经营、运输、屠宰等活动，适用本法。"},{"i":3,"n":"第三条","txt":"国家支持畜牧业发展，发挥畜牧业在发展农业、农村经济和增加农民收入中的作用。"},{"i":4,"n":"第四条","txt":"国家采取措施，培养畜牧兽医专业人才，加强畜禽疫病监测、畜禽疫苗研制，健全基层畜牧兽医技术推广体系，发展畜牧兽医科学技术研究和推广事业，完善畜牧业标准，开展畜牧兽医科学技术知识的教育宣传工作和畜牧兽医信息服务，推进畜牧业科技进步和创新。"},{"i":5,"n":"第五条","txt":"国务院农业农村主管部门负责全国畜牧业的监督管理工作。县级以上地方人民政府农业农村主管部门负责本行政区域内的畜牧业监督管理工作。"},{"i":6,"n":"第六条","txt":"国务院农业农村主管部门应当指导畜牧业生产经营者改善畜禽繁育、饲养、运输、屠宰的条件和环境。"},{"i":7,"n":"第七条","txt":"各级人民政府及有关部门应当加强畜牧业相关法律法规的宣传。"},{"i":8,"n":"第八条","txt":"畜牧业生产经营者可以依法自愿成立行业协会，为成员提供信息、技术、营销、培训等服务，加强行业自律，维护成员和行业利益。"},{"i":9,"n":"第九条","txt":"畜牧业生产经营者应当依法履行动物防疫和生态环境保护义务，接受有关主管部门依法实施的监督检查。"},{"i":10,"n":"第十条","txt":"国家建立畜禽遗传资源保护制度，开展资源调查、保护、鉴定、登记、监测和利用等工作。各级人民政府应当采取措施，加强畜禽遗传资源保护，将畜禽遗传资源保护经费列入预算。"},{"i":11,"n":"第十一条","txt":"国务院农业农村主管部门设立由专业人员组成的国家畜禽遗传资源委员会，负责畜禽遗传资源的鉴定、评估和畜禽新品种、配套系的审定，承担畜禽遗传资源保护和利用规划论证及有关畜禽遗传资源保护的咨询工作。"},{"i":12,"n":"第十二条","txt":"国务院农业农村主管部门负责定期组织畜禽遗传资源的调查工作，发布国家畜禽遗传资源状况报告，公布经国务院批准的畜禽遗传资源目录。"},{"i":13,"n":"第十三条","txt":"国务院农业农村主管部门根据畜禽遗传资源分布状况，制定全国畜禽遗传资源保护和利用规划，制定、调整并公布国家级畜禽遗传资源保护名录，对原产我国的珍贵、稀有、濒危的畜禽遗传资源实行重点保护。"},{"i":14,"n":"第十四条","txt":"国务院农业农村主管部门根据全国畜禽遗传资源保护和利用规划及国家级畜禽遗传资源保护名录，省、自治区、直辖市人民政府农业农村主管部门根据省级畜禽遗传资源保护名录，分别建立或者确定畜禽遗传资源保种场、保护区和基因库，承担畜禽遗传资源保护任务。"},{"i":15,"n":"第十五条","txt":"新发现的畜禽遗传资源在国家畜禽遗传资源委员会鉴定前，省、自治区、直辖市人民政府农业农村主管部门应当制定保护方案，采取临时保护措施，并报国务院农业农村主管部门备案。"},{"i":16,"n":"第十六条","txt":"从境外引进畜禽遗传资源的，应当向省、自治区、直辖市人民政府农业农村主管部门提出申请；受理申请的农业农村主管部门经审核，报国务院农业农村主管部门经评估论证后批准；但是国务院对批准机关另有规定的除外。经批准的，依照《中华人民共和国进出境动植物检疫法》的规定办理相关手续并实施检疫。"},{"i":17,"n":"第十七条","txt":"国家对畜禽遗传资源享有主权。向境外输出或者在境内与境外机构、个人合作研究利用列入保护名录的畜禽遗传资源的，应当向省、自治区、直辖市人民政府农业农村主管部门提出申请，同时提出国家共享惠益的方案；受理申请的农业农村主管部门经审核，报国务院农业农村主管部门批准。"},{"i":18,"n":"第十八条","txt":"畜禽遗传资源的进出境和对外合作研究利用的审批办法由国务院规定。"},{"i":19,"n":"第十九条","txt":"国家扶持畜禽品种的选育和优良品种的推广使用，实施全国畜禽遗传改良计划；支持企业、高等学校、科研机构和技术推广单位开展联合育种，建立健全畜禽良种繁育体系。"},{"i":20,"n":"第二十条","txt":"国家鼓励和支持畜禽种业自主创新，加强育种技术攻关，扶持选育生产经营相结合的创新型企业发展。"},{"i":21,"n":"第二十一条","txt":"培育的畜禽新品种、配套系和新发现的畜禽遗传资源在销售、推广前，应当通过国家畜禽遗传资源委员会审定或者鉴定，并由国务院农业农村主管部门公告。畜禽新品种、配套系的审定办法和畜禽遗传资源的鉴定办法，由国务院农业农村主管部门制定。审定或者鉴定所需的试验、检测等费用由申请者承担。"},{"i":22,"n":"第二十二条","txt":"转基因畜禽品种的引进、培育、试验、审定和推广，应当符合国家有关农业转基因生物安全管理的规定。"},{"i":23,"n":"第二十三条","txt":"省级以上畜牧兽医技术推广机构应当组织开展种畜质量监测、优良个体登记，向社会推荐优良种畜。优良种畜登记规则由国务院农业农村主管部门制定。"},{"i":24,"n":"第二十四条","txt":"从事种畜禽生产经营或者生产经营商品代仔畜、雏禽的单位、个人，应当取得种畜禽生产经营许可证。"},{"i":25,"n":"第二十五条","txt":"申请取得生产家畜卵子、精液、胚胎等遗传材料的生产经营许可证，除应当符合本法第二十四条第二款规定的条件外，还应当具备下列条件："},{"i":26,"n":"第二十六条","txt":"申请取得生产家畜卵子、精液、胚胎等遗传材料的生产经营许可证，应当向省、自治区、直辖市人民政府农业农村主管部门提出申请。受理申请的农业农村主管部门应当自收到申请之日起六十个工作日内依法决定是否发放生产经营许可证。"},{"i":27,"n":"第二十七条","txt":"种畜禽生产经营许可证应当注明生产经营者名称、场（厂）址、生产经营范围及许可证有效期的起止日期等。"},{"i":28,"n":"第二十八条","txt":"农户饲养的种畜禽用于自繁自养和有少量剩余仔畜、雏禽出售的，农户饲养种公畜进行互助配种的，不需要办理种畜禽生产经营许可证。"},{"i":29,"n":"第二十九条","txt":"发布种畜禽广告的，广告主应当持有或者提供种畜禽生产经营许可证和营业执照。广告内容应当符合有关法律、行政法规的规定，并注明种畜禽品种、配套系的审定或者鉴定名称，对主要性状的描述应当符合该品种、配套系的标准。"},{"i":30,"n":"第三十条","txt":"销售的种畜禽、家畜配种站（点）使用的种公畜，应当符合种用标准。销售种畜禽时，应当附具种畜禽场出具的种畜禽合格证明、动物卫生监督机构出具的检疫证明，销售的种畜还应当附具种畜禽场出具的家畜系谱。"},{"i":31,"n":"第三十一条","txt":"销售种畜禽，不得有下列行为："},{"i":32,"n":"第三十二条","txt":"申请进口种畜禽的，应当持有种畜禽生产经营许可证。因没有种畜禽而未取得种畜禽生产经营许可证的，应当提供省、自治区、直辖市人民政府农业农村主管部门的说明文件。进口种畜禽的批准文件有效期为六个月。"},{"i":33,"n":"第三十三条","txt":"销售商品代仔畜、雏禽的，应当向购买者提供其销售的商品代仔畜、雏禽的主要生产性能指标、免疫情况、饲养技术要求和有关咨询服务，并附具动物卫生监督机构出具的检疫证明。"},{"i":34,"n":"第三十四条","txt":"县级以上人民政府农业农村主管部门负责种畜禽质量安全的监督管理工作。种畜禽质量安全的监督检验应当委托具有法定资质的种畜禽质量检验机构进行；所需检验费用由同级预算列支，不得向被检验人收取。"},{"i":35,"n":"第三十五条","txt":"蜂种、蚕种的资源保护、新品种选育、生产经营和推广，适用本法有关规定，具体管理办法由国务院农业农村主管部门制定。"},{"i":36,"n":"第三十六条","txt":"国家建立健全现代畜禽养殖体系。县级以上人民政府农业农村主管部门应当根据畜牧业发展规划和市场需求，引导和支持畜牧业结构调整，发展优势畜禽生产，提高畜禽产品市场竞争力。"},{"i":37,"n":"第三十七条","txt":"各级人民政府应当保障畜禽养殖用地合理需求。县级国土空间规划根据本地实际情况，安排畜禽养殖用地。畜禽养殖用地按照农业用地管理。畜禽养殖用地使用期限届满或者不再从事养殖活动，需要恢复为原用途的，由畜禽养殖用地使用人负责恢复。在畜禽养殖用地范围内需要兴建永久性建（构）筑物，涉及农用地转用的，依照《中华人民共和国土地管理法》的规定办理。"},{"i":38,"n":"第三十八条","txt":"国家设立的畜牧兽医技术推广机构，应当提供畜禽养殖、畜禽粪污无害化处理和资源化利用技术培训，以及良种推广、疫病防治等服务。县级以上人民政府应当保障国家设立的畜牧兽医技术推广机构从事公益性技术服务的工作经费。"},{"i":39,"n":"第三十九条","txt":"畜禽养殖场应当具备下列条件："},{"i":40,"n":"第四十条","txt":"畜禽养殖场的选址、建设应当符合国土空间规划，并遵守有关法律法规的规定；不得违反法律法规的规定，在禁养区域建设畜禽养殖场。"},{"i":41,"n":"第四十一条","txt":"畜禽养殖场应当建立养殖档案，载明下列内容："},{"i":42,"n":"第四十二条","txt":"畜禽养殖者应当为其饲养的畜禽提供适当的繁殖条件和生存、生长环境。"},{"i":43,"n":"第四十三条","txt":"从事畜禽养殖，不得有下列行为："},{"i":44,"n":"第四十四条","txt":"从事畜禽养殖，应当依照《中华人民共和国动物防疫法》、《中华人民共和国农产品质量安全法》的规定，做好畜禽疫病防治和质量安全工作。"},{"i":45,"n":"第四十五条","txt":"畜禽养殖者应当按照国家关于畜禽标识管理的规定，在应当加施标识的畜禽的指定部位加施标识。农业农村主管部门提供标识不得收费，所需费用列入省、自治区、直辖市人民政府预算。"},{"i":46,"n":"第四十六条","txt":"畜禽养殖场应当保证畜禽粪污无害化处理和资源化利用设施的正常运转，保证畜禽粪污综合利用或者达标排放，防止污染环境。违法排放或者因管理不当污染环境的，应当排除危害，依法赔偿损失。"},{"i":47,"n":"第四十七条","txt":"国家引导畜禽养殖户按照畜牧业发展规划有序发展，加强对畜禽养殖户的指导帮扶，保护其合法权益，不得随意以行政手段强行清退。"},{"i":48,"n":"第四十八条","txt":"国家支持发展特种畜禽养殖。县级以上人民政府应当采取措施支持建立与特种畜禽养殖业发展相适应的养殖体系。"},{"i":49,"n":"第四十九条","txt":"国家支持发展养蜂业，保护养蜂生产者的合法权益。"},{"i":50,"n":"第五十条","txt":"养蜂生产者在生产过程中，不得使用危害蜂产品质量安全的药品和容器，确保蜂产品质量。养蜂器具应当符合国家标准和国务院有关部门规定的技术要求。"},{"i":51,"n":"第五十一条","txt":"养蜂生产者在转地放蜂时，当地公安、交通运输、农业农村等有关部门应当为其提供必要的便利。"},{"i":52,"n":"第五十二条","txt":"国家支持科学利用草原，协调推进草原保护与草原畜牧业发展，坚持生态优先、生产生态有机结合，发展特色优势产业，促进农牧民增加收入，提高草原可持续发展能力，筑牢生态安全屏障，推进牧区生产生活生态协同发展。"},{"i":53,"n":"第五十三条","txt":"国家支持牧区转变草原畜牧业发展方式，加强草原水利、草原围栏、饲草料生产加工储备、牲畜圈舍、牧道等基础设施建设。"},{"i":54,"n":"第五十四条","txt":"国家支持优良饲草品种的选育、引进和推广使用，因地制宜开展人工草地建设、天然草原改良和饲草料基地建设，优化种植结构，提高饲草料供应保障能力。"},{"i":55,"n":"第五十五条","txt":"国家支持农牧民发展畜牧业专业合作社和现代家庭牧场，推行适度规模养殖，提升标准化生产水平，建设牛羊等重要畜产品生产基地。"},{"i":56,"n":"第五十六条","txt":"牧区各级人民政府农业农村主管部门应当鼓励和指导农牧民改良家畜品种，优化畜群结构，实行科学饲养，合理加快出栏周转，促进草原畜牧业节本、提质、增效。"},{"i":57,"n":"第五十七条","txt":"国家加强草原畜牧业灾害防御保障，将草原畜牧业防灾减灾列入预算，优化设施装备条件，完善牧区牛羊等家畜保险制度，提高抵御自然灾害的能力。"},{"i":58,"n":"第五十八条","txt":"国家完善草原生态保护补助奖励政策，对采取禁牧和草畜平衡措施的农牧民按照国家有关规定给予补助奖励。"},{"i":59,"n":"第五十九条","txt":"有关地方人民政府应当支持草原畜牧业与乡村旅游、文化等产业协同发展，推动一二三产业融合，提升产业化、品牌化、特色化水平，持续增加农牧民收入，促进牧区振兴。"},{"i":60,"n":"第六十条","txt":"草原畜牧业发展涉及草原保护、建设、利用和管理活动的，应当遵守有关草原保护法律法规的规定。"},{"i":61,"n":"第六十一条","txt":"国家加快建立统一开放、竞争有序、安全便捷的畜禽交易市场体系。"},{"i":62,"n":"第六十二条","txt":"县级以上地方人民政府应当根据农产品批发市场发展规划，对在畜禽集散地建立畜禽批发市场给予扶持。"},{"i":63,"n":"第六十三条","txt":"进行交易的畜禽应当符合农产品质量安全标准和国务院有关部门规定的技术要求。"},{"i":64,"n":"第六十四条","txt":"运输畜禽，应当符合法律、行政法规和国务院农业农村主管部门规定的动物防疫条件，采取措施保护畜禽安全，并为运输的畜禽提供必要的空间和饲喂饮水条件。"},{"i":65,"n":"第六十五条","txt":"国家实行生猪定点屠宰制度。对生猪以外的其他畜禽可以实行定点屠宰，具体办法由省、自治区、直辖市制定。农村地区个人自宰自食的除外。"},{"i":66,"n":"第六十六条","txt":"国家鼓励畜禽就地屠宰，引导畜禽屠宰企业向养殖主产区转移，支持畜禽产品加工、储存、运输冷链体系建设。"},{"i":67,"n":"第六十七条","txt":"畜禽屠宰企业应当具备下列条件："},{"i":68,"n":"第六十八条","txt":"畜禽屠宰经营者应当加强畜禽屠宰质量安全管理。畜禽屠宰企业应当建立畜禽屠宰质量安全管理制度。"},{"i":69,"n":"第六十九条","txt":"国务院农业农村主管部门负责组织制定畜禽屠宰质量安全风险监测计划。"},{"i":70,"n":"第七十条","txt":"省级以上人民政府应当在其预算内安排支持畜禽种业创新和畜牧业发展的良种补贴、贴息补助、保费补贴等资金，并鼓励有关金融机构提供金融服务，支持畜禽养殖者购买优良畜禽、繁育良种、防控疫病，支持改善生产设施、畜禽粪污无害化处理和资源化利用设施设备、扩大养殖规模，提高养殖效益。"},{"i":71,"n":"第七十一条","txt":"县级以上人民政府应当组织农业农村主管部门和其他有关部门，依照本法和有关法律、行政法规的规定，加强对畜禽饲养环境、种畜禽质量、畜禽交易与运输、畜禽屠宰以及饲料、饲料添加剂、兽药等投入品的生产、经营、使用的监督管理。"},{"i":72,"n":"第七十二条","txt":"国务院农业农村主管部门应当制定畜禽标识和养殖档案管理办法，采取措施落实畜禽产品质量安全追溯和责任追究制度。"},{"i":73,"n":"第七十三条","txt":"县级以上人民政府农业农村主管部门应当制定畜禽质量安全监督抽查计划，并按照计划开展监督抽查工作。"},{"i":74,"n":"第七十四条","txt":"省级以上人民政府农业农村主管部门应当组织制定畜禽生产规范，指导畜禽的安全生产。"},{"i":75,"n":"第七十五条","txt":"国家建立统一的畜禽生产和畜禽产品市场监测预警制度，逐步完善有关畜禽产品储备调节机制，加强市场调控，促进市场供需平衡和畜牧业健康发展。"},{"i":76,"n":"第七十六条","txt":"国家加强畜禽生产、加工、销售、运输体系建设，提升畜禽产品供应安全保障能力。"},{"i":77,"n":"第七十七条","txt":"违反本法规定，县级以上人民政府农业农村主管部门及其工作人员有下列行为之一的，对直接负责的主管人员和其他直接责任人员依法给予处分："},{"i":78,"n":"第七十八条","txt":"违反本法第十四条第二款规定，擅自处理受保护的畜禽遗传资源，造成畜禽遗传资源损失的，由省级以上人民政府农业农村主管部门处十万元以上一百万元以下罚款。"},{"i":79,"n":"第七十九条","txt":"违反本法规定，有下列行为之一的，由省级以上人民政府农业农村主管部门责令停止违法行为，没收畜禽遗传资源和违法所得，并处五万元以上五十万元以下罚款："},{"i":80,"n":"第八十条","txt":"违反本法规定，未经国务院农业农村主管部门批准，向境外输出畜禽遗传资源的，依照《中华人民共和国海关法》的有关规定追究法律责任。海关应当将扣留的畜禽遗传资源移送省、自治区、直辖市人民政府农业农村主管部门处理。"},{"i":81,"n":"第八十一条","txt":"违反本法规定，销售、推广未经审定或者鉴定的畜禽品种、配套系的，由县级以上地方人民政府农业农村主管部门责令停止违法行为，没收畜禽和违法所得；违法所得在五万元以上的，并处违法所得一倍以上三倍以下罚款；没有违法所得或者违法所得不足五万元的，并处五千元以上五万元以下罚款。"},{"i":82,"n":"第八十二条","txt":"违反本法规定，无种畜禽生产经营许可证或者违反种畜禽生产经营许可证规定生产经营，或者伪造、变造、转让、租借种畜禽生产经营许可证的，由县级以上地方人民政府农业农村主管部门责令停止违法行为，收缴伪造、变造的种畜禽生产经营许可证，没收种畜禽、商品代仔畜、雏禽和违法所得；违法所得在三万元以上的，并处违法所得一倍以上三倍以下罚款；没有违法所得或者违法所得不足三万元的，并处三千元以上三万元以下罚款。违反种畜禽生产经营许可证的规定生产经营或者转让、租借种畜禽生产经营许可证，情节严重的，并处吊销种畜禽生产经营许可证。"},{"i":83,"n":"第八十三条","txt":"违反本法第二十九条规定的，依照《中华人民共和国广告法》的有关规定追究法律责任。"},{"i":84,"n":"第八十四条","txt":"违反本法规定，使用的种畜禽不符合种用标准的，由县级以上地方人民政府农业农村主管部门责令停止违法行为，没收种畜禽和违法所得；违法所得在五千元以上的，并处违法所得一倍以上二倍以下罚款；没有违法所得或者违法所得不足五千元的，并处一千元以上五千元以下罚款。"},{"i":85,"n":"第八十五条","txt":"销售种畜禽有本法第三十一条第一项至第四项违法行为之一的，由县级以上地方人民政府农业农村主管部门和市场监督管理部门按照职责分工责令停止销售，没收违法销售的（种）畜禽和违法所得；违法所得在五万元以上的，并处违法所得一倍以上五倍以下罚款；没有违法所得或者违法所得不足五万元的，并处五千元以上五万元以下罚款；情节严重的，并处吊销种畜禽生产经营许可证或者营业执照。"},{"i":86,"n":"第八十六条","txt":"违反本法规定，兴办畜禽养殖场未备案，畜禽养殖场未建立养殖档案或者未按照规定保存养殖档案的，由县级以上地方人民政府农业农村主管部门责令限期改正，可以处一万元以下罚款。"},{"i":87,"n":"第八十七条","txt":"违反本法第四十三条规定养殖畜禽的，依照有关法律、行政法规的规定处理、处罚。"},{"i":88,"n":"第八十八条","txt":"违反本法规定，销售的种畜禽未附具种畜禽合格证明、家畜系谱，销售、收购国务院农业农村主管部门规定应当加施标识而没有标识的畜禽，或者重复使用畜禽标识的，由县级以上地方人民政府农业农村主管部门和市场监督管理部门按照职责分工责令改正，可以处二千元以下罚款。"},{"i":89,"n":"第八十九条","txt":"违反本法规定，未经定点从事畜禽屠宰活动的，依照有关法律法规的规定处理、处罚。"},{"i":90,"n":"第九十条","txt":"县级以上地方人民政府农业农村主管部门发现畜禽屠宰企业不再具备本法规定条件的，应当责令停业整顿，并限期整改；逾期仍未达到本法规定条件的，责令关闭，对实行定点屠宰管理的，由发证机关依法吊销定点屠宰证书。"},{"i":91,"n":"第九十一条","txt":"违反本法第六十八条规定，畜禽屠宰企业未建立畜禽屠宰质量安全管理制度，或者畜禽屠宰经营者对经检验不合格的畜禽产品未按照国家有关规定处理的，由县级以上地方人民政府农业农村主管部门责令改正，给予警告；拒不改正的，责令停业整顿，并处五千元以上五万元以下罚款，对直接负责的主管人员和其他直接责任人员处二千元以上二万元以下罚款；情节严重的，责令关闭，对实行定点屠宰管理的，由发证机关依法吊销定点屠宰证书。"},{"i":92,"n":"第九十二条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":93,"n":"第九十三条","txt":"本法所称畜禽遗传资源，是指畜禽及其卵子（蛋）、精液、胚胎、基因物质等遗传材料。"},{"i":94,"n":"第九十四条","txt":"本法自2023年3月1日起施行。"}],"shiyoutianranqiguandaobaohufa":[{"i":1,"n":"第一条","txt":"为了保护石油、天然气管道，保障石油、天然气输送安全，维护国家能源安全和公共安全，制定本法。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内输送石油、天然气的管道的保护，适用本法。"},{"i":3,"n":"第三条","txt":"本法所称石油包括原油和成品油，所称天然气包括天然气、煤层气和煤制气。"},{"i":4,"n":"第四条","txt":"国务院能源主管部门依照本法规定主管全国管道保护工作，负责组织编制并实施全国管道发展规划，统筹协调全国管道发展规划与其他专项规划的衔接，协调跨省、自治区、直辖市管道保护的重大问题。国务院其他有关部门依照有关法律、行政法规的规定，在各自职责范围内负责管道保护的相关工作。"},{"i":5,"n":"第五条","txt":"省、自治区、直辖市人民政府能源主管部门和设区的市级、县级人民政府指定的部门，依照本法规定主管本行政区域的管道保护工作，协调处理本行政区域管道保护的重大问题，指导、监督有关单位履行管道保护义务，依法查处危害管道安全的违法行为。县级以上地方人民政府其他有关部门依照有关法律、行政法规的规定，在各自职责范围内负责管道保护的相关工作。"},{"i":6,"n":"第六条","txt":"县级以上地方人民政府应当加强对本行政区域管道保护工作的领导，督促、检查有关部门依法履行管道保护职责，组织排除管道的重大外部安全隐患。"},{"i":7,"n":"第七条","txt":"管道企业应当遵守本法和有关规划、建设、安全生产、质量监督、环境保护等法律、行政法规，执行国家技术规范的强制性要求，建立、健全本企业有关管道保护的规章制度和操作规程并组织实施，宣传管道安全与保护知识，履行管道保护义务，接受人民政府及其有关部门依法实施的监督，保障管道安全运行。"},{"i":8,"n":"第八条","txt":"任何单位和个人不得实施危害管道安全的行为。"},{"i":9,"n":"第九条","txt":"国家鼓励和促进管道保护新技术的研究开发和推广应用。"},{"i":10,"n":"第十条","txt":"管道的规划、建设应当符合管道保护的要求，遵循安全、环保、节约用地和经济合理的原则。"},{"i":11,"n":"第十一条","txt":"国务院能源主管部门根据国民经济和社会发展的需要组织编制全国管道发展规划。组织编制全国管道发展规划应当征求国务院有关部门以及有关省、自治区、直辖市人民政府的意见。"},{"i":12,"n":"第十二条","txt":"管道企业应当根据全国管道发展规划编制管道建设规划，并将管道建设规划确定的管道建设选线方案报送拟建管道所在地县级以上地方人民政府城乡规划主管部门审核；经审核符合城乡规划的，应当依法纳入当地城乡规划。"},{"i":13,"n":"第十三条","txt":"管道建设的选线应当避开地震活动断层和容易发生洪灾、地质灾害的区域，与建筑物、构筑物、铁路、公路、航道、港口、市政设施、军事设施、电缆、光缆等保持本法和有关法律、行政法规以及国家技术规范的强制性要求规定的保护距离。"},{"i":14,"n":"第十四条","txt":"管道建设使用土地，依照《中华人民共和国土地管理法》等法律、行政法规的规定执行。"},{"i":15,"n":"第十五条","txt":"依照法律和国务院的规定，取得行政许可或者已报送备案并符合开工条件的管道项目的建设，任何单位和个人不得阻碍。"},{"i":16,"n":"第十六条","txt":"管道建设应当遵守法律、行政法规有关建设工程质量管理的规定。"},{"i":17,"n":"第十七条","txt":"穿跨越水利工程、防洪设施、河道、航道、铁路、公路、港口、电力设施、通信设施、市政设施的管道的建设，应当遵守本法和有关法律、行政法规，执行国家技术规范的强制性要求。"},{"i":18,"n":"第十八条","txt":"管道企业应当按照国家技术规范的强制性要求在管道沿线设置管道标志。管道标志毁损或者安全警示不清的，管道企业应当及时修复或者更新。"},{"i":19,"n":"第十九条","txt":"管道建成后应当按照国家有关规定进行竣工验收。竣工验收应当审查管道是否符合本法规定的管道保护要求，经验收合格方可正式交付使用。"},{"i":20,"n":"第二十条","txt":"管道企业应当自管道竣工验收合格之日起六十日内，将竣工测量图报管道所在地县级以上地方人民政府主管管道保护工作的部门备案；县级以上地方人民政府主管管道保护工作的部门应当将管道企业报送的管道竣工测量图分送本级人民政府规划、建设、国土资源、铁路、交通、水利、公安、安全生产监督管理等部门和有关军事机关。"},{"i":21,"n":"第二十一条","txt":"地方各级人民政府编制、调整土地利用总体规划和城乡规划，需要管道改建、搬迁或者增加防护设施的，应当与管道企业协商确定补偿方案。"},{"i":22,"n":"第二十二条","txt":"管道企业应当建立、健全管道巡护制度，配备专门人员对管道线路进行日常巡护。管道巡护人员发现危害管道安全的情形或者隐患，应当按照规定及时处理和报告。"},{"i":23,"n":"第二十三条","txt":"管道企业应当定期对管道进行检测、维修，确保其处于良好状态；对管道安全风险较大的区段和场所应当进行重点监测，采取有效措施防止管道事故的发生。"},{"i":24,"n":"第二十四条","txt":"管道企业应当配备管道保护所必需的人员和技术装备，研究开发和使用先进适用的管道保护技术，保证管道保护所必需的经费投入，并对在管道保护中做出突出贡献的单位和个人给予奖励。"},{"i":25,"n":"第二十五条","txt":"管道企业发现管道存在安全隐患，应当及时排除。对管道存在的外部安全隐患，管道企业自身排除确有困难的，应当向县级以上地方人民政府主管管道保护工作的部门报告。接到报告的主管管道保护工作的部门应当及时协调排除或者报请人民政府及时组织排除安全隐患。"},{"i":26,"n":"第二十六条","txt":"管道企业依法取得使用权的土地，任何单位和个人不得侵占。"},{"i":27,"n":"第二十七条","txt":"管道企业对管道进行巡护、检测、维修等作业，管道沿线的有关单位、个人应当给予必要的便利。"},{"i":28,"n":"第二十八条","txt":"禁止下列危害管道安全的行为："},{"i":29,"n":"第二十九条","txt":"禁止在本法第五十八条第一项所列管道附属设施的上方架设电力线路、通信线路或者在储气库构造区域范围内进行工程挖掘、工程钻探、采矿。"},{"i":30,"n":"第三十条","txt":"在管道线路中心线两侧各五米地域范围内，禁止下列危害管道安全的行为："},{"i":31,"n":"第三十一条","txt":"在管道线路中心线两侧和本法第五十八条第一项所列管道附属设施周边修建下列建筑物、构筑物的，建筑物、构筑物与管道线路和管道附属设施的距离应当符合国家技术规范的强制性要求："},{"i":32,"n":"第三十二条","txt":"在穿越河流的管道线路中心线两侧各五百米地域范围内，禁止抛锚、拖锚、挖砂、挖泥、采石、水下爆破。但是，在保障管道安全的条件下，为防洪和航道通畅而进行的养护疏浚作业除外。"},{"i":33,"n":"第三十三条","txt":"在管道专用隧道中心线两侧各一千米地域范围内，除本条第二款规定的情形外，禁止采石、采矿、爆破。"},{"i":34,"n":"第三十四条","txt":"未经管道企业同意，其他单位不得使用管道专用伴行道路、管道水工防护设施、管道专用隧道等管道附属设施。"},{"i":35,"n":"第三十五条","txt":"进行下列施工作业，施工单位应当向管道所在地县级人民政府主管管道保护工作的部门提出申请："},{"i":36,"n":"第三十六条","txt":"申请进行本法第三十三条第二款、第三十五条规定的施工作业，应当符合下列条件："},{"i":37,"n":"第三十七条","txt":"进行本法第三十三条第二款、第三十五条规定的施工作业，应当在开工七日前书面通知管道企业。管道企业应当指派专门人员到现场进行管道保护安全指导。"},{"i":38,"n":"第三十八条","txt":"管道企业在紧急情况下进行管道抢修作业，可以先行使用他人土地或者设施，但应当及时告知土地或者设施的所有权人或者使用权人。给土地或者设施的所有权人或者使用权人造成损失的，管道企业应当依法给予赔偿。"},{"i":39,"n":"第三十九条","txt":"管道企业应当制定本企业管道事故应急预案，并报管道所在地县级人民政府主管管道保护工作的部门备案；配备抢险救援人员和设备，并定期进行管道事故应急救援演练。"},{"i":40,"n":"第四十条","txt":"管道泄漏的石油和因管道抢修排放的石油造成环境污染的，管道企业应当及时治理。因第三人的行为致使管道泄漏造成环境污染的，管道企业有权向第三人追偿治理费用。"},{"i":41,"n":"第四十一条","txt":"管道泄漏的石油和因管道抢修排放的石油，由管道企业回收、处理，任何单位和个人不得侵占、盗窃、哄抢。"},{"i":42,"n":"第四十二条","txt":"管道停止运行、封存、报废的，管道企业应当采取必要的安全防护措施，并报县级以上地方人民政府主管管道保护工作的部门备案。"},{"i":43,"n":"第四十三条","txt":"管道重点保护部位，需要由中国人民武装警察部队负责守卫的，依照《中华人民共和国人民武装警察法》和国务院、中央军事委员会的有关规定执行。"},{"i":44,"n":"第四十四条","txt":"管道建设工程与其他建设工程的相遇关系，依照法律的规定处理；法律没有规定的，由建设工程双方按照下列原则协商处理，并为对方提供必要的便利："},{"i":45,"n":"第四十五条","txt":"经依法批准的管道建设工程，需要通过正在建设的其他建设工程的，其他工程建设单位应当按照管道建设工程的需要，预留管道通道或者预建管道通过设施，管道企业应当承担由此增加的费用。"},{"i":46,"n":"第四十六条","txt":"管道建设工程通过矿产资源开采区域的，管道企业应当与矿产资源开采企业协商确定管道的安全防护方案，需要矿产资源开采企业按照管道安全防护要求预建防护设施或者采取其他防护措施的，管道企业应当承担由此增加的费用。"},{"i":47,"n":"第四十七条","txt":"铁路、公路等建设工程修建防洪、分流等水工防护设施，可能影响管道保护的，应当事先通知管道企业并注意保护下游已建成的管道水工防护设施。"},{"i":48,"n":"第四十八条","txt":"县级以上地方人民政府水行政主管部门制定防洪、泄洪方案应当兼顾管道的保护。"},{"i":49,"n":"第四十九条","txt":"管道与航道相遇，确需在航道中修建管道防护设施的，应当进行通航标准技术论证，并经航道主管部门批准。管道防护设施完工后，应经航道主管部门验收。"},{"i":50,"n":"第五十条","txt":"管道企业有下列行为之一的，由县级以上地方人民政府主管管道保护工作的部门责令限期改正；逾期不改正的，处二万元以上十万元以下的罚款；对直接负责的主管人员和其他直接责任人员给予处分："},{"i":51,"n":"第五十一条","txt":"采用移动、切割、打孔、砸撬、拆卸等手段损坏管道或者盗窃、哄抢管道输送、泄漏、排放的石油、天然气，尚不构成犯罪的，依法给予治安管理处罚。"},{"i":52,"n":"第五十二条","txt":"违反本法第二十九条、第三十条、第三十二条或者第三十三条第一款的规定，实施危害管道安全行为的，由县级以上地方人民政府主管管道保护工作的部门责令停止违法行为；情节较重的，对单位处一万元以上十万元以下的罚款，对个人处二百元以上二千元以下的罚款；对违法修建的建筑物、构筑物或者其他设施限期拆除；逾期未拆除的，由县级以上地方人民政府主管管道保护工作的部门组织拆除，所需费用由违法行为人承担。"},{"i":53,"n":"第五十三条","txt":"未经依法批准，进行本法第三十三条第二款或者第三十五条规定的施工作业的，由县级以上地方人民政府主管管道保护工作的部门责令停止违法行为；情节较重的，处一万元以上五万元以下的罚款；对违法修建的危害管道安全的建筑物、构筑物或者其他设施限期拆除；逾期未拆除的，由县级以上地方人民政府主管管道保护工作的部门组织拆除，所需费用由违法行为人承担。"},{"i":54,"n":"第五十四条","txt":"违反本法规定，有下列行为之一的，由县级以上地方人民政府主管管道保护工作的部门责令改正；情节严重的，处二百元以上一千元以下的罚款："},{"i":55,"n":"第五十五条","txt":"违反本法规定，实施危害管道安全的行为，给管道企业造成损害的，依法承担民事责任。"},{"i":56,"n":"第五十六条","txt":"县级以上地方人民政府及其主管管道保护工作的部门或者其他有关部门，违反本法规定，对应当组织排除的管道外部安全隐患不及时组织排除，发现危害管道安全的行为或者接到对危害管道安全行为的举报后不依法予以查处，或者有其他不依照本法规定履行职责的行为的，由其上级机关责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":57,"n":"第五十七条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":58,"n":"第五十八条","txt":"本法所称管道附属设施包括："},{"i":59,"n":"第五十九条","txt":"本法施行前在管道保护距离内已建成的人口密集场所和易燃易爆物品的生产、经营、存储场所，应当由所在地人民政府根据当地的实际情况，有计划、分步骤地进行搬迁、清理或者采取必要的防护措施。需要已建成的管道改建、搬迁或者采取必要的防护措施的，应当与管道企业协商确定补偿方案。"},{"i":60,"n":"第六十条","txt":"国务院可以根据海上石油、天然气管道的具体情况，制定海上石油、天然气管道保护的特别规定。"},{"i":61,"n":"第六十一条","txt":"本法自2010年10月1日起施行。"}],"zhongzifa":[{"i":1,"n":"第一条","txt":"为了保护和合理利用种质资源，规范品种选育、种子生产经营和管理行为，加强种业科学技术研究，鼓励育种创新，保护植物新品种权，维护种子生产经营者、使用者的合法权益，提高种子质量，发展现代种业，保障国家粮食安全，促进农业和林业的发展，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事品种选育、种子生产经营和管理等活动，适用本法。"},{"i":3,"n":"第三条","txt":"国务院农业农村、林业草原主管部门分别主管全国农作物种子和林木种子工作；县级以上地方人民政府农业农村、林业草原主管部门分别主管本行政区域内农作物种子和林木种子工作。"},{"i":4,"n":"第四条","txt":"国家扶持种质资源保护工作和选育、生产、更新、推广使用良种，鼓励品种选育和种子生产经营相结合，奖励在种质资源保护工作和良种选育、推广等工作中成绩显著的单位和个人。"},{"i":5,"n":"第五条","txt":"省级以上人民政府应当根据科教兴农方针和农业、林业发展的需要制定种业发展规划并组织实施。"},{"i":6,"n":"第六条","txt":"省级以上人民政府建立种子储备制度，主要用于发生灾害时的生产需要及余缺调剂，保障农业和林业生产安全。对储备的种子应当定期检验和更新。种子储备的具体办法由国务院规定。"},{"i":7,"n":"第七条","txt":"转基因植物品种的选育、试验、审定和推广应当进行安全性评价，并采取严格的安全控制措施。国务院农业农村、林业草原主管部门应当加强跟踪监管并及时公告有关转基因植物品种审定和推广的信息。具体办法由国务院规定。"},{"i":8,"n":"第八条","txt":"国家依法保护种质资源，任何单位和个人不得侵占和破坏种质资源。"},{"i":9,"n":"第九条","txt":"国家有计划地普查、收集、整理、鉴定、登记、保存、交流和利用种质资源，重点收集珍稀、濒危、特有资源和特色地方品种，定期公布可供利用的种质资源目录。具体办法由国务院农业农村、林业草原主管部门规定。"},{"i":10,"n":"第十条","txt":"国务院农业农村、林业草原主管部门应当建立种质资源库、种质资源保护区或者种质资源保护地。省、自治区、直辖市人民政府农业农村、林业草原主管部门可以根据需要建立种质资源库、种质资源保护区、种质资源保护地。种质资源库、种质资源保护区、种质资源保护地的种质资源属公共资源，依法开放利用。"},{"i":11,"n":"第十一条","txt":"国家对种质资源享有主权。任何单位和个人向境外提供种质资源，或者与境外机构、个人开展合作研究利用种质资源的，应当报国务院农业农村、林业草原主管部门批准，并同时提交国家共享惠益的方案。国务院农业农村、林业草原主管部门可以委托省、自治区、直辖市人民政府农业农村、林业草原主管部门接收申请材料。国务院农业农村、林业草原主管部门应当将批准情况通报国务院生态环境主管部门。"},{"i":12,"n":"第十二条","txt":"国家支持科研院所及高等院校重点开展育种的基础性、前沿性和应用技术研究以及生物育种技术研究，支持常规作物、主要造林树种育种和无性繁殖材料选育等公益性研究。"},{"i":13,"n":"第十三条","txt":"由财政资金支持形成的育种发明专利权和植物新品种权，除涉及国家安全、国家利益和重大社会公共利益的外，授权项目承担者依法取得。"},{"i":14,"n":"第十四条","txt":"单位和个人因林业草原主管部门为选育林木良种建立测定林、试验林、优树收集区、基因库等而减少经济收入的，批准建立的林业草原主管部门应当按照国家有关规定给予经济补偿。"},{"i":15,"n":"第十五条","txt":"国家对主要农作物和主要林木实行品种审定制度。主要农作物品种和主要林木品种在推广前应当通过国家级或者省级审定。由省、自治区、直辖市人民政府林业草原主管部门确定的主要林木品种实行省级审定。"},{"i":16,"n":"第十六条","txt":"国务院和省、自治区、直辖市人民政府的农业农村、林业草原主管部门分别设立由专业人员组成的农作物品种和林木品种审定委员会。品种审定委员会承担主要农作物品种和主要林木品种的审定工作，建立包括申请文件、品种审定试验数据、种子样品、审定意见和审定结论等内容的审定档案，保证可追溯。在审定通过的品种依法公布的相关信息中应当包括审定意见情况，接受监督。"},{"i":17,"n":"第十七条","txt":"实行选育生产经营相结合，符合国务院农业农村、林业草原主管部门规定条件的种子企业，对其自主研发的主要农作物品种、主要林木品种可以按照审定办法自行完成试验，达到审定标准的，品种审定委员会应当颁发审定证书。种子企业对试验数据的真实性负责，保证可追溯，接受省级以上人民政府农业农村、林业草原主管部门和社会的监督。"},{"i":18,"n":"第十八条","txt":"审定未通过的农作物品种和林木品种，申请人有异议的，可以向原审定委员会或者国家级审定委员会申请复审。"},{"i":19,"n":"第十九条","txt":"通过国家级审定的农作物品种和林木良种由国务院农业农村、林业草原主管部门公告，可以在全国适宜的生态区域推广。通过省级审定的农作物品种和林木良种由省、自治区、直辖市人民政府农业农村、林业草原主管部门公告，可以在本行政区域内适宜的生态区域推广；其他省、自治区、直辖市属于同一适宜生态区的地域引种农作物品种、林木良种的，引种者应当将引种的品种和区域报所在省、自治区、直辖市人民政府农业农村、林业草原主管部门备案。"},{"i":20,"n":"第二十条","txt":"省、自治区、直辖市人民政府农业农村、林业草原主管部门应当完善品种选育、审定工作的区域协作机制，促进优良品种的选育和推广。"},{"i":21,"n":"第二十一条","txt":"审定通过的农作物品种和林木良种出现不可克服的严重缺陷等情形不宜继续推广、销售的，经原审定委员会审核确认后，撤销审定，由原公告部门发布公告，停止推广、销售。"},{"i":22,"n":"第二十二条","txt":"国家对部分非主要农作物实行品种登记制度。列入非主要农作物登记目录的品种在推广前应当登记。"},{"i":23,"n":"第二十三条","txt":"应当审定的农作物品种未经审定的，不得发布广告、推广、销售。"},{"i":24,"n":"第二十四条","txt":"在中国境内没有经常居所或者营业场所的境外机构、个人在境内申请品种审定或者登记的，应当委托具有法人资格的境内种子企业代理。"},{"i":25,"n":"第二十五条","txt":"国家实行植物新品种保护制度。对国家植物品种保护名录内经过人工选育或者发现的野生植物加以改良，具备新颖性、特异性、一致性、稳定性和适当命名的植物品种，由国务院农业农村、林业草原主管部门授予植物新品种权，保护植物新品种权所有人的合法权益。植物新品种权的内容和归属、授予条件、申请和受理、审查与批准，以及期限、终止和无效等依照本法、有关法律和行政法规规定执行。"},{"i":26,"n":"第二十六条","txt":"一个植物新品种只能授予一项植物新品种权。两个以上的申请人分别就同一个品种申请植物新品种权的，植物新品种权授予最先申请的人；同时申请的，植物新品种权授予最先完成该品种育种的人。"},{"i":27,"n":"第二十七条","txt":"授予植物新品种权的植物新品种名称，应当与相同或者相近的植物属或者种中已知品种的名称相区别。该名称经授权后即为该植物新品种的通用名称。"},{"i":28,"n":"第二十八条","txt":"植物新品种权所有人对其授权品种享有排他的独占权。植物新品种权所有人可以将植物新品种权许可他人实施，并按照合同约定收取许可使用费；许可使用费可以采取固定价款、从推广收益中提成等方式收取。"},{"i":29,"n":"第二十九条","txt":"在下列情况下使用授权品种的，可以不经植物新品种权所有人许可，不向其支付使用费，但不得侵犯植物新品种权所有人依照本法、有关法律、行政法规享有的其他权利："},{"i":30,"n":"第三十条","txt":"为了国家利益或者社会公共利益，国务院农业农村、林业草原主管部门可以作出实施植物新品种权强制许可的决定，并予以登记和公告。"},{"i":31,"n":"第三十一条","txt":"从事种子进出口业务的种子生产经营许可证，由国务院农业农村、林业草原主管部门核发。国务院农业农村、林业草原主管部门可以委托省、自治区、直辖市人民政府农业农村、林业草原主管部门接收申请材料。"},{"i":32,"n":"第三十二条","txt":"申请取得种子生产经营许可证的，应当具有与种子生产经营相适应的生产经营设施、设备及专业技术人员，以及法规和国务院农业农村、林业草原主管部门规定的其他条件。"},{"i":33,"n":"第三十三条","txt":"种子生产经营许可证应当载明生产经营者名称、地址、法定代表人、生产种子的品种、地点和种子经营的范围、有效期限、有效区域等事项。"},{"i":34,"n":"第三十四条","txt":"种子生产应当执行种子生产技术规程和种子检验、检疫规程，保证种子符合净度、纯度、发芽率等质量要求和检疫要求。"},{"i":35,"n":"第三十五条","txt":"在林木种子生产基地内采集种子的，由种子生产基地的经营者组织进行，采集种子应当按照国家有关标准进行。"},{"i":36,"n":"第三十六条","txt":"种子生产经营者应当建立和保存包括种子来源、产地、数量、质量、销售去向、销售日期和有关责任人员等内容的生产经营档案，保证可追溯。种子生产经营档案的具体载明事项，种子生产经营档案及种子样品的保存期限由国务院农业农村、林业草原主管部门规定。"},{"i":37,"n":"第三十七条","txt":"农民个人自繁自用的常规种子有剩余的，可以在当地集贸市场上出售、串换，不需要办理种子生产经营许可证。"},{"i":38,"n":"第三十八条","txt":"种子生产经营许可证的有效区域由发证机关在其管辖范围内确定。种子生产经营者在种子生产经营许可证载明的有效区域设立分支机构的，专门经营不再分装的包装种子的，或者受具有种子生产经营许可证的种子生产经营者以书面委托生产、代销其种子的，不需要办理种子生产经营许可证，但应当向当地农业农村、林业草原主管部门备案。"},{"i":39,"n":"第三十九条","txt":"销售的种子应当加工、分级、包装。但是不能加工、包装的除外。"},{"i":40,"n":"第四十条","txt":"销售的种子应当符合国家或者行业标准，附有标签和使用说明。标签和使用说明标注的内容应当与销售的种子相符。种子生产经营者对标注内容的真实性和种子质量负责。"},{"i":41,"n":"第四十一条","txt":"种子广告的内容应当符合本法和有关广告的法律、法规的规定，主要性状描述等应当与审定、登记公告一致。"},{"i":42,"n":"第四十二条","txt":"运输或者邮寄种子应当依照有关法律、行政法规的规定进行检疫。"},{"i":43,"n":"第四十三条","txt":"种子使用者有权按照自己的意愿购买种子，任何单位和个人不得非法干预。"},{"i":44,"n":"第四十四条","txt":"国家对推广使用林木良种造林给予扶持。国家投资或者国家投资为主的造林项目和国有林业单位造林，应当根据林业草原主管部门制定的计划使用林木良种。"},{"i":45,"n":"第四十五条","txt":"种子使用者因种子质量问题或者因种子的标签和使用说明标注的内容不真实，遭受损失的，种子使用者可以向出售种子的经营者要求赔偿，也可以向种子生产者或者其他经营者要求赔偿。赔偿额包括购种价款、可得利益损失和其他损失。属于种子生产者或者其他经营者责任的，出售种子的经营者赔偿后，有权向种子生产者或者其他经营者追偿；属于出售种子的经营者责任的，种子生产者或者其他经营者赔偿后，有权向出售种子的经营者追偿。"},{"i":46,"n":"第四十六条","txt":"农业农村、林业草原主管部门应当加强对种子质量的监督检查。种子质量管理办法、行业标准和检验方法，由国务院农业农村、林业草原主管部门制定。"},{"i":47,"n":"第四十七条","txt":"农业农村、林业草原主管部门可以委托种子质量检验机构对种子质量进行检验。"},{"i":48,"n":"第四十八条","txt":"禁止生产经营假、劣种子。农业农村、林业草原主管部门和有关部门依法打击生产经营假、劣种子的违法行为，保护农民合法权益，维护公平竞争的市场秩序。"},{"i":49,"n":"第四十九条","txt":"农业农村、林业草原主管部门是种子行政执法机关。种子执法人员依法执行公务时应当出示行政执法证件。农业农村、林业草原主管部门依法履行种子监督检查职责时，有权采取下列措施："},{"i":50,"n":"第五十条","txt":"种子生产经营者依法自愿成立种子行业协会，加强行业自律管理，维护成员合法权益，为成员和行业发展提供信息交流、技术培训、信用建设、市场营销和咨询等服务。"},{"i":51,"n":"第五十一条","txt":"种子生产经营者可自愿向具有资质的认证机构申请种子质量认证。经认证合格的，可以在包装上使用认证标识。"},{"i":52,"n":"第五十二条","txt":"由于不可抗力原因，为生产需要必须使用低于国家或者地方规定标准的农作物种子的，应当经用种地县级以上地方人民政府批准。"},{"i":53,"n":"第五十三条","txt":"从事品种选育和种子生产经营以及管理的单位和个人应当遵守有关植物检疫法律、行政法规的规定，防止植物危险性病、虫、杂草及其他有害生物的传播和蔓延。"},{"i":54,"n":"第五十四条","txt":"省级以上人民政府农业农村、林业草原主管部门应当在统一的政府信息发布平台上发布品种审定、品种登记、新品种保护、种子生产经营许可、监督管理等信息。"},{"i":55,"n":"第五十五条","txt":"农业农村、林业草原主管部门及其工作人员，不得参与和从事种子生产经营活动。"},{"i":56,"n":"第五十六条","txt":"进口种子和出口种子必须实施检疫，防止植物危险性病、虫、杂草及其他有害生物传入境内和传出境外，具体检疫工作按照有关植物进出境检疫法律、行政法规的规定执行。"},{"i":57,"n":"第五十七条","txt":"从事种子进出口业务的，应当具备种子生产经营许可证；其中，从事农作物种子进出口业务的，还应当按照国家有关规定取得种子进出口许可。"},{"i":58,"n":"第五十八条","txt":"进口种子的质量，应当达到国家标准或者行业标准。没有国家标准或者行业标准的，可以按照合同约定的标准执行。"},{"i":59,"n":"第五十九条","txt":"为境外制种进口种子的，可以不受本法第五十七条第一款的限制，但应当具有对外制种合同，进口的种子只能用于制种，其产品不得在境内销售。"},{"i":60,"n":"第六十条","txt":"禁止进出口假、劣种子以及属于国家规定不得进出口的种子。"},{"i":61,"n":"第六十一条","txt":"国家建立种业国家安全审查机制。境外机构、个人投资、并购境内种子企业，或者与境内科研院所、种子企业开展技术合作，从事品种研发、种子生产经营的审批管理依照有关法律、行政法规的规定执行。"},{"i":62,"n":"第六十二条","txt":"国家加大对种业发展的支持。对品种选育、生产、示范推广、种质资源保护、种子储备以及制种大县给予扶持。"},{"i":63,"n":"第六十三条","txt":"国家加强种业公益性基础设施建设，保障育种科研设施用地合理需求。"},{"i":64,"n":"第六十四条","txt":"对从事农作物和林木品种选育、生产的种子企业，按照国家有关规定给予扶持。"},{"i":65,"n":"第六十五条","txt":"国家鼓励和引导金融机构为种子生产经营和收储提供信贷支持。"},{"i":66,"n":"第六十六条","txt":"国家支持保险机构开展种子生产保险。省级以上人民政府可以采取保险费补贴等措施，支持发展种业生产保险。"},{"i":67,"n":"第六十七条","txt":"国家鼓励科研院所及高等院校与种子企业开展育种科技人员交流，支持本单位的科技人员到种子企业从事育种成果转化活动；鼓励育种科研人才创新创业。"},{"i":68,"n":"第六十八条","txt":"国务院农业农村、林业草原主管部门和异地繁育种子所在地的省、自治区、直辖市人民政府应当加强对异地繁育种子工作的管理和协调，交通运输部门应当优先保证种子的运输。"},{"i":69,"n":"第六十九条","txt":"农业农村、林业草原主管部门不依法作出行政许可决定，发现违法行为或者接到对违法行为的举报不予查处，或者有其他未依照本法规定履行职责的行为的，由本级人民政府或者上级人民政府有关部门责令改正，对负有责任的主管人员和其他直接责任人员依法给予处分。"},{"i":70,"n":"第七十条","txt":"违反本法第十六条规定，品种审定委员会委员和工作人员不依法履行职责，弄虚作假、徇私舞弊的，依法给予处分；自处分决定作出之日起五年内不得从事品种审定工作。"},{"i":71,"n":"第七十一条","txt":"品种测试、试验和种子质量检验机构伪造测试、试验、检验数据或者出具虚假证明的，由县级以上人民政府农业农村、林业草原主管部门责令改正，对单位处五万元以上十万元以下罚款，对直接负责的主管人员和其他直接责任人员处一万元以上五万元以下罚款；有违法所得的，并处没收违法所得；给种子使用者和其他种子生产经营者造成损失的，与种子生产经营者承担连带责任；情节严重的，由省级以上人民政府有关主管部门取消种子质量检验资格。"},{"i":72,"n":"第七十二条","txt":"违反本法第二十八条规定，有侵犯植物新品种权行为的，由当事人协商解决，不愿协商或者协商不成的，植物新品种权所有人或者利害关系人可以请求县级以上人民政府农业农村、林业草原主管部门进行处理，也可以直接向人民法院提起诉讼。"},{"i":73,"n":"第七十三条","txt":"当事人就植物新品种的申请权和植物新品种权的权属发生争议的，可以向人民法院提起诉讼。"},{"i":74,"n":"第七十四条","txt":"违反本法第四十八条规定，生产经营假种子的，由县级以上人民政府农业农村、林业草原主管部门责令停止生产经营，没收违法所得和种子，吊销种子生产经营许可证；违法生产经营的货值金额不足二万元的，并处二万元以上二十万元以下罚款；货值金额二万元以上的，并处货值金额十倍以上二十倍以下罚款。"},{"i":75,"n":"第七十五条","txt":"违反本法第四十八条规定，生产经营劣种子的，由县级以上人民政府农业农村、林业草原主管部门责令停止生产经营，没收违法所得和种子；违法生产经营的货值金额不足二万元的，并处一万元以上十万元以下罚款；货值金额二万元以上的，并处货值金额五倍以上十倍以下罚款；情节严重的，吊销种子生产经营许可证。"},{"i":76,"n":"第七十六条","txt":"违反本法第三十二条、第三十三条、第三十四条规定，有下列行为之一的，由县级以上人民政府农业农村、林业草原主管部门责令改正，没收违法所得和种子；违法生产经营的货值金额不足一万元的，并处三千元以上三万元以下罚款；货值金额一万元以上的，并处货值金额三倍以上五倍以下罚款；可以吊销种子生产经营许可证："},{"i":77,"n":"第七十七条","txt":"违反本法第二十一条、第二十二条、第二十三条规定，有下列行为之一的，由县级以上人民政府农业农村、林业草原主管部门责令停止违法行为，没收违法所得和种子，并处二万元以上二十万元以下罚款："},{"i":78,"n":"第七十八条","txt":"违反本法第五十七条、第五十九条、第六十条规定，有下列行为之一的，由县级以上人民政府农业农村、林业草原主管部门责令改正，没收违法所得和种子；违法生产经营的货值金额不足一万元的，并处三千元以上三万元以下罚款；货值金额一万元以上的，并处货值金额三倍以上五倍以下罚款；情节严重的，吊销种子生产经营许可证："},{"i":79,"n":"第七十九条","txt":"违反本法第三十六条、第三十八条、第三十九条、第四十条规定，有下列行为之一的，由县级以上人民政府农业农村、林业草原主管部门责令改正，处二千元以上二万元以下罚款："},{"i":80,"n":"第八十条","txt":"违反本法第八条规定，侵占、破坏种质资源，私自采集或者采伐国家重点保护的天然种质资源的，由县级以上人民政府农业农村、林业草原主管部门责令停止违法行为，没收种质资源和违法所得，并处五千元以上五万元以下罚款；造成损失的，依法承担赔偿责任。"},{"i":81,"n":"第八十一条","txt":"违反本法第十一条规定，向境外提供或者从境外引进种质资源，或者与境外机构、个人开展合作研究利用种质资源的，由国务院或者省、自治区、直辖市人民政府的农业农村、林业草原主管部门没收种质资源和违法所得，并处二万元以上二十万元以下罚款。"},{"i":82,"n":"第八十二条","txt":"违反本法第三十五条规定，抢采掠青、损坏母树或者在劣质林内、劣质母树上采种的，由县级以上人民政府林业草原主管部门责令停止采种行为，没收所采种子，并处所采种子货值金额二倍以上五倍以下罚款。"},{"i":83,"n":"第八十三条","txt":"违反本法第十七条规定，种子企业有造假行为的，由省级以上人民政府农业农村、林业草原主管部门处一百万元以上五百万元以下罚款；不得再依照本法第十七条的规定申请品种审定；给种子使用者和其他种子生产经营者造成损失的，依法承担赔偿责任。"},{"i":84,"n":"第八十四条","txt":"违反本法第四十四条规定，未根据林业草原主管部门制定的计划使用林木良种的，由同级人民政府林业草原主管部门责令限期改正；逾期未改正的，处三千元以上三万元以下罚款。"},{"i":85,"n":"第八十五条","txt":"违反本法第五十三条规定，在种子生产基地进行检疫性有害生物接种试验的，由县级以上人民政府农业农村、林业草原主管部门责令停止试验，处五千元以上五万元以下罚款。"},{"i":86,"n":"第八十六条","txt":"违反本法第四十九条规定，拒绝、阻挠农业农村、林业草原主管部门依法实施监督检查的，处二千元以上五万元以下罚款，可以责令停产停业整顿；构成违反治安管理行为的，由公安机关依法给予治安管理处罚。"},{"i":87,"n":"第八十七条","txt":"违反本法第十三条规定，私自交易育种成果，给本单位造成经济损失的，依法承担赔偿责任。"},{"i":88,"n":"第八十八条","txt":"违反本法第四十三条规定，强迫种子使用者违背自己的意愿购买、使用种子，给使用者造成损失的，应当承担赔偿责任。"},{"i":89,"n":"第八十九条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":90,"n":"第九十条","txt":"本法下列用语的含义是："},{"i":91,"n":"第九十一条","txt":"国家加强中药材种质资源保护，支持开展中药材育种科学技术研究。"},{"i":92,"n":"第九十二条","txt":"本法自2016年1月1日起施行。"}],"shuishouzhengshouguanlifa":[{"i":1,"n":"第一条","txt":"为了加强税收征收管理，规范税收征收和缴纳行为，保障国家税收收入，保护纳税人的合法权益，促进经济和社会发展，制定本法。"},{"i":2,"n":"第二条","txt":"凡依法由税务机关征收的各种税收的征收管理，均适用本法。"},{"i":3,"n":"第三条","txt":"税收的开征、停征以及减税、免税、退税、补税，依照法律的规定执行；法律授权国务院规定的，依照国务院制定的行政法规的规定执行。"},{"i":4,"n":"第四条","txt":"法律、行政法规规定负有纳税义务的单位和个人为纳税人。"},{"i":5,"n":"第五条","txt":"国务院税务主管部门主管全国税收征收管理工作。各地国家税务局和地方税务局应当按照国务院规定的税收征收管理范围分别进行征收管理。"},{"i":6,"n":"第六条","txt":"国家有计划地用现代信息技术装备各级税务机关，加强税收征收管理信息系统的现代化建设，建立、健全税务机关与政府其他管理机关的信息共享制度。"},{"i":7,"n":"第七条","txt":"税务机关应当广泛宣传税收法律、行政法规，普及纳税知识，无偿地为纳税人提供纳税咨询服务。"},{"i":8,"n":"第八条","txt":"纳税人、扣缴义务人有权向税务机关了解国家税收法律、行政法规的规定以及与纳税程序有关的情况。"},{"i":9,"n":"第九条","txt":"税务机关应当加强队伍建设，提高税务人员的政治业务素质。"},{"i":10,"n":"第十条","txt":"各级税务机关应当建立、健全内部制约和监督管理制度。"},{"i":11,"n":"第十一条","txt":"税务机关负责征收、管理、稽查、行政复议的人员的职责应当明确，并相互分离、相互制约。"},{"i":12,"n":"第十二条","txt":"税务人员征收税款和查处税收违法案件，与纳税人、扣缴义务人或者税收违法案件有利害关系的，应当回避。"},{"i":13,"n":"第十三条","txt":"任何单位和个人都有权检举违反税收法律、行政法规的行为。收到检举的机关和负责查处的机关应当为检举人保密。税务机关应当按照规定对检举人给予奖励。"},{"i":14,"n":"第十四条","txt":"本法所称税务机关是指各级税务局、税务分局、税务所和按照国务院规定设立的并向社会公告的税务机构。"},{"i":15,"n":"第十五条","txt":"企业，企业在外地设立的分支机构和从事生产、经营的场所，个体工商户和从事生产、经营的事业单位（以下统称从事生产、经营的纳税人）自领取营业执照之日起三十日内，持有关证件，向税务机关申报办理税务登记。税务机关应当于收到申报的当日办理登记并发给税务登记证件。"},{"i":16,"n":"第十六条","txt":"从事生产、经营的纳税人，税务登记内容发生变化的，自工商行政管理机关办理变更登记之日起三十日内或者在向工商行政管理机关申请办理注销登记之前，持有关证件向税务机关申报办理变更或者注销税务登记。"},{"i":17,"n":"第十七条","txt":"从事生产、经营的纳税人应当按照国家有关规定，持税务登记证件，在银行或者其他金融机构开立基本存款帐户和其他存款帐户，并将其全部帐号向税务机关报告。"},{"i":18,"n":"第十八条","txt":"纳税人按照国务院税务主管部门的规定使用税务登记证件。税务登记证件不得转借、涂改、损毁、买卖或者伪造。"},{"i":19,"n":"第十九条","txt":"纳税人、扣缴义务人按照有关法律、行政法规和国务院财政、税务主管部门的规定设置帐簿，根据合法、有效凭证记帐，进行核算。"},{"i":20,"n":"第二十条","txt":"从事生产、经营的纳税人的财务、会计制度或者财务、会计处理办法和会计核算软件，应当报送税务机关备案。"},{"i":21,"n":"第二十一条","txt":"税务机关是发票的主管机关，负责发票印制、领购、开具、取得、保管、缴销的管理和监督。"},{"i":22,"n":"第二十二条","txt":"增值税专用发票由国务院税务主管部门指定的企业印制；其他发票，按照国务院税务主管部门的规定，分别由省、自治区、直辖市国家税务局、地方税务局指定企业印制。"},{"i":23,"n":"第二十三条","txt":"国家根据税收征收管理的需要，积极推广使用税控装置。纳税人应当按照规定安装、使用税控装置，不得损毁或者擅自改动税控装置。"},{"i":24,"n":"第二十四条","txt":"从事生产、经营的纳税人、扣缴义务人必须按照国务院财政、税务主管部门规定的保管期限保管帐簿、记帐凭证、完税凭证及其他有关资料。"},{"i":25,"n":"第二十五条","txt":"纳税人必须依照法律、行政法规规定或者税务机关依照法律、行政法规的规定确定的申报期限、申报内容如实办理纳税申报，报送纳税申报表、财务会计报表以及税务机关根据实际需要要求纳税人报送的其他纳税资料。"},{"i":26,"n":"第二十六条","txt":"纳税人、扣缴义务人可以直接到税务机关办理纳税申报或者报送代扣代缴、代收代缴税款报告表，也可以按照规定采取邮寄、数据电文或者其他方式办理上述申报、报送事项。"},{"i":27,"n":"第二十七条","txt":"纳税人、扣缴义务人不能按期办理纳税申报或者报送代扣代缴、代收代缴税款报告表的，经税务机关核准，可以延期申报。"},{"i":28,"n":"第二十八条","txt":"税务机关依照法律、行政法规的规定征收税款，不得违反法律、行政法规的规定开征、停征、多征、少征、提前征收、延缓征收或者摊派税款。"},{"i":29,"n":"第二十九条","txt":"除税务机关、税务人员以及经税务机关依照法律、行政法规委托的单位和人员外，任何单位和个人不得进行税款征收活动。"},{"i":30,"n":"第三十条","txt":"扣缴义务人依照法律、行政法规的规定履行代扣、代收税款的义务。对法律、行政法规没有规定负有代扣、代收税款义务的单位和个人，税务机关不得要求其履行代扣、代收税款义务。"},{"i":31,"n":"第三十一条","txt":"纳税人、扣缴义务人按照法律、行政法规规定或者税务机关依照法律、行政法规的规定确定的期限，缴纳或者解缴税款。"},{"i":32,"n":"第三十二条","txt":"纳税人未按照规定期限缴纳税款的，扣缴义务人未按照规定期限解缴税款的，税务机关除责令限期缴纳外，从滞纳税款之日起，按日加收滞纳税款万分之五的滞纳金。"},{"i":33,"n":"第三十三条","txt":"纳税人依照法律、行政法规的规定办理减税、免税。"},{"i":34,"n":"第三十四条","txt":"税务机关征收税款时，必须给纳税人开具完税凭证。扣缴义务人代扣、代收税款时，纳税人要求扣缴义务人开具代扣、代收税款凭证的，扣缴义务人应当开具。"},{"i":35,"n":"第三十五条","txt":"纳税人有下列情形之一的，税务机关有权核定其应纳税额："},{"i":36,"n":"第三十六条","txt":"企业或者外国企业在中国境内设立的从事生产、经营的机构、场所与其关联企业之间的业务往来，应当按照独立企业之间的业务往来收取或者支付价款、费用；不按照独立企业之间的业务往来收取或者支付价款、费用，而减少其应纳税的收入或者所得额的，税务机关有权进行合理调整。"},{"i":37,"n":"第三十七条","txt":"对未按照规定办理税务登记的从事生产、经营的纳税人以及临时从事经营的纳税人，由税务机关核定其应纳税额，责令缴纳；不缴纳的，税务机关可以扣押其价值相当于应纳税款的商品、货物。扣押后缴纳应纳税款的，税务机关必须立即解除扣押，并归还所扣押的商品、货物；扣押后仍不缴纳应纳税款的，经县以上税务局（分局）局长批准，依法拍卖或者变卖所扣押的商品、货物，以拍卖或者变卖所得抵缴税款。"},{"i":38,"n":"第三十八条","txt":"税务机关有根据认为从事生产、经营的纳税人有逃避纳税义务行为的，可以在规定的纳税期之前，责令限期缴纳应纳税款；在限期内发现纳税人有明显的转移、隐匿其应纳税的商品、货物以及其他财产或者应纳税的收入的迹象的，税务机关可以责成纳税人提供纳税担保。如果纳税人不能提供纳税担保，经县以上税务局（分局）局长批准，税务机关可以采取下列税收保全措施："},{"i":39,"n":"第三十九条","txt":"纳税人在限期内已缴纳税款，税务机关未立即解除税收保全措施，使纳税人的合法利益遭受损失的，税务机关应当承担赔偿责任。"},{"i":40,"n":"第四十条","txt":"从事生产、经营的纳税人、扣缴义务人未按照规定的期限缴纳或者解缴税款，纳税担保人未按照规定的期限缴纳所担保的税款，由税务机关责令限期缴纳，逾期仍未缴纳的，经县以上税务局（分局）局长批准，税务机关可以采取下列强制执行措施："},{"i":41,"n":"第四十一条","txt":"本法第三十七条、第三十八条、第四十条规定的采取税收保全措施、强制执行措施的权力，不得由法定的税务机关以外的单位和个人行使。"},{"i":42,"n":"第四十二条","txt":"税务机关采取税收保全措施和强制执行措施必须依照法定权限和法定程序，不得查封、扣押纳税人个人及其所扶养家属维持生活必需的住房和用品。"},{"i":43,"n":"第四十三条","txt":"税务机关滥用职权违法采取税收保全措施、强制执行措施，或者采取税收保全措施、强制执行措施不当，使纳税人、扣缴义务人或者纳税担保人的合法权益遭受损失的，应当依法承担赔偿责任。"},{"i":44,"n":"第四十四条","txt":"欠缴税款的纳税人或者他的法定代表人需要出境的，应当在出境前向税务机关结清应纳税款、滞纳金或者提供担保。未结清税款、滞纳金，又不提供担保的，税务机关可以通知出境管理机关阻止其出境。"},{"i":45,"n":"第四十五条","txt":"税务机关征收税款，税收优先于无担保债权，法律另有规定的除外；纳税人欠缴的税款发生在纳税人以其财产设定抵押、质押或者纳税人的财产被留置之前的，税收应当先于抵押权、质权、留置权执行。"},{"i":46,"n":"第四十六条","txt":"纳税人有欠税情形而以其财产设定抵押、质押的，应当向抵押权人、质权人说明其欠税情况。抵押权人、质权人可以请求税务机关提供有关的欠税情况。"},{"i":47,"n":"第四十七条","txt":"税务机关扣押商品、货物或者其他财产时，必须开付收据；查封商品、货物或者其他财产时，必须开付清单。"},{"i":48,"n":"第四十八条","txt":"纳税人有合并、分立情形的，应当向税务机关报告，并依法缴清税款。纳税人合并时未缴清税款的，应当由合并后的纳税人继续履行未履行的纳税义务；纳税人分立时未缴清税款的，分立后的纳税人对未履行的纳税义务应当承担连带责任。"},{"i":49,"n":"第四十九条","txt":"欠缴税款数额较大的纳税人在处分其不动产或者大额资产之前，应当向税务机关报告。"},{"i":50,"n":"第五十条","txt":"欠缴税款的纳税人因怠于行使到期债权，或者放弃到期债权，或者无偿转让财产，或者以明显不合理的低价转让财产而受让人知道该情形，对国家税收造成损害的，税务机关可以依照合同法第七十三条、第七十四条的规定行使代位权、撤销权。"},{"i":51,"n":"第五十一条","txt":"纳税人超过应纳税额缴纳的税款，税务机关发现后应当立即退还；纳税人自结算缴纳税款之日起三年内发现的，可以向税务机关要求退还多缴的税款并加算银行同期存款利息，税务机关及时查实后应当立即退还；涉及从国库中退库的，依照法律、行政法规有关国库管理的规定退还。"},{"i":52,"n":"第五十二条","txt":"因税务机关的责任，致使纳税人、扣缴义务人未缴或者少缴税款的，税务机关在三年内可以要求纳税人、扣缴义务人补缴税款，但是不得加收滞纳金。"},{"i":53,"n":"第五十三条","txt":"国家税务局和地方税务局应当按照国家规定的税收征收管理范围和税款入库预算级次，将征收的税款缴入国库。"},{"i":54,"n":"第五十四条","txt":"税务机关有权进行下列税务检查："},{"i":55,"n":"第五十五条","txt":"税务机关对从事生产、经营的纳税人以前纳税期的纳税情况依法进行税务检查时，发现纳税人有逃避纳税义务行为，并有明显的转移、隐匿其应纳税的商品、货物以及其他财产或者应纳税的收入的迹象的，可以按照本法规定的批准权限采取税收保全措施或者强制执行措施。"},{"i":56,"n":"第五十六条","txt":"纳税人、扣缴义务人必须接受税务机关依法进行的税务检查，如实反映情况，提供有关资料，不得拒绝、隐瞒。"},{"i":57,"n":"第五十七条","txt":"税务机关依法进行税务检查时，有权向有关单位和个人调查纳税人、扣缴义务人和其他当事人与纳税或者代扣代缴、代收代缴税款有关的情况，有关单位和个人有义务向税务机关如实提供有关资料及证明材料。"},{"i":58,"n":"第五十八条","txt":"税务机关调查税务违法案件时，对与案件有关的情况和资料，可以记录、录音、录像、照相和复制。"},{"i":59,"n":"第五十九条","txt":"税务机关派出的人员进行税务检查时，应当出示税务检查证和税务检查通知书，并有责任为被检查人保守秘密；未出示税务检查证和税务检查通知书的，被检查人有权拒绝检查。"},{"i":60,"n":"第六十条","txt":"纳税人有下列行为之一的，由税务机关责令限期改正，可以处二千元以下的罚款；情节严重的，处二千元以上一万元以下的罚款："},{"i":61,"n":"第六十一条","txt":"扣缴义务人未按照规定设置、保管代扣代缴、代收代缴税款帐簿或者保管代扣代缴、代收代缴税款记帐凭证及有关资料的，由税务机关责令限期改正，可以处二千元以下的罚款；情节严重的，处二千元以上五千元以下的罚款。"},{"i":62,"n":"第六十二条","txt":"纳税人未按照规定的期限办理纳税申报和报送纳税资料的，或者扣缴义务人未按照规定的期限向税务机关报送代扣代缴、代收代缴税款报告表和有关资料的，由税务机关责令限期改正，可以处二千元以下的罚款；情节严重的，可以处二千元以上一万元以下的罚款。"},{"i":63,"n":"第六十三条","txt":"纳税人伪造、变造、隐匿、擅自销毁帐簿、记帐凭证，或者在帐簿上多列支出或者不列、少列收入，或者经税务机关通知申报而拒不申报或者进行虚假的纳税申报，不缴或者少缴应纳税款的，是偷税。对纳税人偷税的，由税务机关追缴其不缴或者少缴的税款、滞纳金，并处不缴或者少缴的税款百分之五十以上五倍以下的罚款；构成犯罪的，依法追究刑事责任。"},{"i":64,"n":"第六十四条","txt":"纳税人、扣缴义务人编造虚假计税依据的，由税务机关责令限期改正，并处五万元以下的罚款。"},{"i":65,"n":"第六十五条","txt":"纳税人欠缴应纳税款，采取转移或者隐匿财产的手段，妨碍税务机关追缴欠缴的税款的，由税务机关追缴欠缴的税款、滞纳金，并处欠缴税款百分之五十以上五倍以下的罚款；构成犯罪的，依法追究刑事责任。"},{"i":66,"n":"第六十六条","txt":"以假报出口或者其他欺骗手段，骗取国家出口退税款的，由税务机关追缴其骗取的退税款，并处骗取税款一倍以上五倍以下的罚款；构成犯罪的，依法追究刑事责任。"},{"i":67,"n":"第六十七条","txt":"以暴力、威胁方法拒不缴纳税款的，是抗税，除由税务机关追缴其拒缴的税款、滞纳金外，依法追究刑事责任。情节轻微，未构成犯罪的，由税务机关追缴其拒缴的税款、滞纳金，并处拒缴税款一倍以上五倍以下的罚款。"},{"i":68,"n":"第六十八条","txt":"纳税人、扣缴义务人在规定期限内不缴或者少缴应纳或者应解缴的税款，经税务机关责令限期缴纳，逾期仍未缴纳的，税务机关除依照本法第四十条的规定采取强制执行措施追缴其不缴或者少缴的税款外，可以处不缴或者少缴的税款百分之五十以上五倍以下的罚款。"},{"i":69,"n":"第六十九条","txt":"扣缴义务人应扣未扣、应收而不收税款的，由税务机关向纳税人追缴税款，对扣缴义务人处应扣未扣、应收未收税款百分之五十以上三倍以下的罚款。"},{"i":70,"n":"第七十条","txt":"纳税人、扣缴义务人逃避、拒绝或者以其他方式阻挠税务机关检查的，由税务机关责令改正，可以处一万元以下的罚款；情节严重的，处一万元以上五万元以下的罚款。"},{"i":71,"n":"第七十一条","txt":"违反本法第二十二条规定，非法印制发票的，由税务机关销毁非法印制的发票，没收违法所得和作案工具，并处一万元以上五万元以下的罚款；构成犯罪的，依法追究刑事责任。"},{"i":72,"n":"第七十二条","txt":"从事生产、经营的纳税人、扣缴义务人有本法规定的税收违法行为，拒不接受税务机关处理的，税务机关可以收缴其发票或者停止向其发售发票。"},{"i":73,"n":"第七十三条","txt":"纳税人、扣缴义务人的开户银行或者其他金融机构拒绝接受税务机关依法检查纳税人、扣缴义务人存款帐户，或者拒绝执行税务机关作出的冻结存款或者扣缴税款的决定，或者在接到税务机关的书面通知后帮助纳税人、扣缴义务人转移存款，造成税款流失的，由税务机关处十万元以上五十万元以下的罚款，对直接负责的主管人员和其他直接责任人员处一千元以上一万元以下的罚款。"},{"i":74,"n":"第七十四条","txt":"本法规定的行政处罚，罚款额在二千元以下的，可以由税务所决定。"},{"i":75,"n":"第七十五条","txt":"税务机关和司法机关的涉税罚没收入，应当按照税款入库预算级次上缴国库。"},{"i":76,"n":"第七十六条","txt":"税务机关违反规定擅自改变税收征收管理范围和税款入库预算级次的，责令限期改正，对直接负责的主管人员和其他直接责任人员依法给予降级或者撤职的行政处分。"},{"i":77,"n":"第七十七条","txt":"纳税人、扣缴义务人有本法第六十三条、第六十五条、第六十六条、第六十七条、第七十一条规定的行为涉嫌犯罪的，税务机关应当依法移交司法机关追究刑事责任。"},{"i":78,"n":"第七十八条","txt":"未经税务机关依法委托征收税款的，责令退还收取的财物，依法给予行政处分或者行政处罚；致使他人合法权益受到损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":79,"n":"第七十九条","txt":"税务机关、税务人员查封、扣押纳税人个人及其所扶养家属维持生活必需的住房和用品的，责令退还，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":80,"n":"第八十条","txt":"税务人员与纳税人、扣缴义务人勾结，唆使或者协助纳税人、扣缴义务人有本法第六十三条、第六十五条、第六十六条规定的行为，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":81,"n":"第八十一条","txt":"税务人员利用职务上的便利，收受或者索取纳税人、扣缴义务人财物或者谋取其他不正当利益，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":82,"n":"第八十二条","txt":"税务人员徇私舞弊或者玩忽职守，不征或者少征应征税款，致使国家税收遭受重大损失，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":83,"n":"第八十三条","txt":"违反法律、行政法规的规定提前征收、延缓征收或者摊派税款的，由其上级机关或者行政监察机关责令改正，对直接负责的主管人员和其他直接责任人员依法给予行政处分。"},{"i":84,"n":"第八十四条","txt":"违反法律、行政法规的规定，擅自作出税收的开征、停征或者减税、免税、退税、补税以及其他同税收法律、行政法规相抵触的决定的，除依照本法规定撤销其擅自作出的决定外，补征应征未征税款，退还不应征收而征收的税款，并由上级机关追究直接负责的主管人员和其他直接责任人员的行政责任；构成犯罪的，依法追究刑事责任。"},{"i":85,"n":"第八十五条","txt":"税务人员在征收税款或者查处税收违法案件时，未按照本法规定进行回避的，对直接负责的主管人员和其他直接责任人员，依法给予行政处分。"},{"i":86,"n":"第八十六条","txt":"违反税收法律、行政法规应当给予行政处罚的行为，在五年内未被发现的，不再给予行政处罚。"},{"i":87,"n":"第八十七条","txt":"未按照本法规定为纳税人、扣缴义务人、检举人保密的，对直接负责的主管人员和其他直接责任人员，由所在单位或者有关单位依法给予行政处分。"},{"i":88,"n":"第八十八条","txt":"纳税人、扣缴义务人、纳税担保人同税务机关在纳税上发生争议时，必须先依照税务机关的纳税决定缴纳或者解缴税款及滞纳金或者提供相应的担保，然后可以依法申请行政复议；对行政复议决定不服的，可以依法向人民法院起诉。"},{"i":89,"n":"第八十九条","txt":"纳税人、扣缴义务人可以委托税务代理人代为办理税务事宜。"},{"i":90,"n":"第九十条","txt":"耕地占用税、契税、农业税、牧业税征收管理的具体办法，由国务院另行制定。"},{"i":91,"n":"第九十一条","txt":"中华人民共和国同外国缔结的有关税收的条约、协定同本法有不同规定的，依照条约、协定的规定办理。"},{"i":92,"n":"第九十二条","txt":"本法施行前颁布的税收法律与本法有不同规定的，适用本法规定。"},{"i":93,"n":"第九十三条","txt":"国务院根据本法制定实施细则。"},{"i":94,"n":"第九十四条","txt":"本法自2001年5月1日起施行。"}],"liangshianquanbaozhangfa":[{"i":1,"n":"第一条","txt":"为了保障粮食有效供给，确保国家粮食安全，提高防范和抵御粮食安全风险能力，维护经济社会稳定和国家安全，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"国家粮食安全工作坚持中国共产党的领导，贯彻总体国家安全观，统筹发展和安全，实施以我为主、立足国内、确保产能、适度进口、科技支撑的国家粮食安全战略，坚持藏粮于地、藏粮于技，提高粮食生产、储备、流通、加工能力，确保谷物基本自给、口粮绝对安全。"},{"i":3,"n":"第三条","txt":"国家建立粮食安全责任制，实行粮食安全党政同责。县级以上地方人民政府应当承担保障本行政区域粮食安全的具体责任。"},{"i":4,"n":"第四条","txt":"国家加强粮食宏观调控，优化粮食品种结构和区域布局，统筹利用国内、国际的市场和资源，构建科学合理、安全高效的粮食供给保障体系，提升粮食供给能力和质量安全。"},{"i":5,"n":"第五条","txt":"县级以上人民政府应当将粮食安全保障纳入国民经济和社会发展规划。县级以上人民政府有关部门应当根据粮食安全保障目标、任务等，编制粮食安全保障相关专项规划，按照程序批准后实施。"},{"i":6,"n":"第六条","txt":"国家建立健全粮食安全保障投入机制，采取财政、金融等支持政策加强粮食安全保障，完善粮食生产、收购、储存、运输、加工、销售协同保障机制，建设国家粮食安全产业带，调动粮食生产者和地方人民政府保护耕地、种粮、做好粮食安全保障工作的积极性，全面推进乡村振兴，促进粮食产业高质量发展，增强国家粮食安全保障能力。"},{"i":7,"n":"第七条","txt":"国家加强粮食安全科技创新能力和信息化建设，支持粮食领域基础研究、关键技术研发和标准化工作，完善科技人才培养、评价和激励等机制，促进科技创新成果转化和先进技术、设备的推广使用，提高粮食生产、储备、流通、加工的科技支撑能力和应用水平。"},{"i":8,"n":"第八条","txt":"各级人民政府及有关部门应当采取多种形式加强粮食安全宣传教育，提升全社会粮食安全意识，引导形成爱惜粮食、节约粮食的良好风尚。"},{"i":9,"n":"第九条","txt":"对在国家粮食安全保障工作中做出突出贡献的单位和个人，按照国家有关规定给予表彰和奖励。"},{"i":10,"n":"第十条","txt":"国家实施国土空间规划下的国土空间用途管制，统筹布局农业、生态、城镇等功能空间，划定落实耕地和永久基本农田保护红线、生态保护红线和城镇开发边界，严格保护耕地。"},{"i":11,"n":"第十一条","txt":"国家实行占用耕地补偿制度，严格控制各类占用耕地行为；确需占用耕地的，应当依法落实补充耕地责任，补充与所占用耕地数量相等、质量相当的耕地。"},{"i":12,"n":"第十二条","txt":"国家严格控制耕地转为林地、草地、园地等其他农用地。禁止违规占用耕地绿化造林、挖湖造景等行为。禁止在国家批准的退耕还林还草计划外擅自扩大退耕范围。"},{"i":13,"n":"第十三条","txt":"耕地应当主要用于粮食和棉、油、糖、蔬菜等农产品及饲草饲料生产。县级以上地方人民政府应当根据粮食和重要农产品保供目标任务，加强耕地种植用途管控，落实耕地利用优先序，调整优化种植结构。具体办法由国务院农业农村主管部门制定。"},{"i":14,"n":"第十四条","txt":"国家建立严格的耕地质量保护制度，加强高标准农田建设，按照量质并重、系统推进、永续利用的要求，坚持政府主导与社会参与、统筹规划与分步实施、用养结合与建管并重的原则，健全完善多元投入保障机制，提高建设标准和质量。"},{"i":15,"n":"第十五条","txt":"县级以上人民政府应当建立耕地质量和种植用途监测网络，开展耕地质量调查和监测评价，采取土壤改良、地力培肥、治理修复等措施，提高中低产田产能，治理退化耕地，加强大中型灌区建设与改造，提升耕地质量。"},{"i":16,"n":"第十六条","txt":"县级以上地方人民政府应当因地制宜、分类推进撂荒地治理，采取措施引导复耕。家庭承包的发包方可以依法通过组织代耕代种等形式将撂荒地用于农业生产。"},{"i":17,"n":"第十七条","txt":"国家推动盐碱地综合利用，制定相关规划和支持政策，鼓励和引导社会资本投入，挖掘盐碱地开发利用潜力，分区分类开展盐碱耕地治理改良，加快选育耐盐碱特色品种，推广改良盐碱地有效做法，遏制耕地盐碱化趋势。"},{"i":18,"n":"第十八条","txt":"国家推进种业振兴，维护种业安全，推动种业高质量发展。"},{"i":19,"n":"第十九条","txt":"省级以上人民政府应当建立种子储备制度，主要用于发生灾害时的粮食生产需要及余缺调剂。"},{"i":20,"n":"第二十条","txt":"县级以上人民政府应当统筹做好肥料、农药、农用薄膜等农业生产资料稳定供应工作，引导粮食生产者科学施用化肥、农药，合理使用农用薄膜，增施有机肥料。"},{"i":21,"n":"第二十一条","txt":"国家加强水资源管理和水利基础设施建设，优化水资源配置，保障粮食生产合理用水需求。各级人民政府应当组织做好农田水利建设和运行维护，保护和完善农田灌溉排水体系，因地制宜发展高效节水农业。"},{"i":22,"n":"第二十二条","txt":"国家推进农业机械产业发展，加强农业机械化作业基础条件建设，推广普及粮食生产机械化技术，鼓励使用绿色、智能、高效的农业机械，促进粮食生产全程机械化，提高粮食生产效率。"},{"i":23,"n":"第二十三条","txt":"国家加强农业技术推广体系建设，支持推广应用先进适用的粮食生产技术，因地制宜推广间作套种等种植方法，鼓励创新推广方式，提高粮食生产技术推广服务水平，促进提高粮食单产。"},{"i":24,"n":"第二十四条","txt":"国家加强粮食生产防灾减灾救灾能力建设。县级以上人民政府应当建立健全农业自然灾害和生物灾害监测预警体系、防灾减灾救灾工作机制，加强干旱、洪涝、低温、高温、风雹、台风等灾害防御防控技术研究应用和安全生产管理，落实灾害防治属地责任，加强粮食作物病虫害防治和植物检疫工作。"},{"i":25,"n":"第二十五条","txt":"国家加强粮食生产功能区和重要农产品生产保护区建设，鼓励农业生产者种植优质农作物。县级以上人民政府应当按照规定组织划定粮食生产功能区和重要农产品生产保护区并加强建设和管理，引导农业生产者种植目标作物。"},{"i":26,"n":"第二十六条","txt":"国家采取措施稳定粮食播种面积，合理布局粮食生产，粮食主产区、主销区、产销平衡区都应当保面积、保产量。"},{"i":27,"n":"第二十七条","txt":"国家扶持和培育家庭农场、农民专业合作社等新型农业经营主体从事粮食生产，鼓励其与农户建立利益联结机制，提高粮食生产能力和现代化水平。"},{"i":28,"n":"第二十八条","txt":"国家健全粮食主产区利益补偿机制，完善对粮食主产区和产粮大县的财政转移支付制度，调动粮食生产积极性。"},{"i":29,"n":"第二十九条","txt":"国家建立政府粮食储备体系。政府粮食储备分为中央政府储备和地方政府储备。政府粮食储备用于调节粮食供求、稳定粮食市场、应对突发事件等。"},{"i":30,"n":"第三十条","txt":"承储政府粮食储备的企业或者其他组织应当遵守法律、法规和国家有关规定，实行储备与商业性经营业务分开，建立健全内部管理制度，落实安全生产责任和消防安全责任，对承储粮食数量、质量负责，实施粮食安全风险事项报告制度，确保政府粮食储备安全。"},{"i":31,"n":"第三十一条","txt":"承储政府粮食储备的企业或者其他组织应当保证政府粮食储备账实相符、账账相符，实行专仓储存、专人保管、专账记载，不得虚报、瞒报政府粮食储备数量、质量、品种。"},{"i":32,"n":"第三十二条","txt":"县级以上地方人民政府应当根据本行政区域实际情况，指导规模以上粮食加工企业建立企业社会责任储备，鼓励家庭农场、农民专业合作社、农业产业化龙头企业自主储粮，鼓励有条件的经营主体为农户提供粮食代储服务。"},{"i":33,"n":"第三十三条","txt":"县级以上人民政府应当加强粮食储备基础设施及质量检验能力建设，推进仓储科技创新和推广应用，加强政府粮食储备管理信息化建设。"},{"i":34,"n":"第三十四条","txt":"县级以上人民政府应当将政府粮食储备情况列为年度国有资产报告内容，向本级人民代表大会常务委员会报告。"},{"i":35,"n":"第三十五条","txt":"国家加强对粮食市场的管理，充分发挥市场作用，健全市场规则，维护市场秩序，依法保障粮食经营者公平参与市场竞争，维护粮食经营者合法权益。"},{"i":36,"n":"第三十六条","txt":"县级以上地方人民政府应当加强对粮食仓储、物流等粮食流通基础设施的建设和保护，组织建设与本行政区域粮食收储规模和保障供应要求相匹配，布局合理、功能齐全的粮食流通基础设施，并引导社会资本投入粮食流通基础设施建设。"},{"i":37,"n":"第三十七条","txt":"从事粮食收购、储存、加工、销售的经营者以及饲料、工业用粮企业，应当按照规定建立粮食经营台账，并向所在地的县级人民政府粮食和储备主管部门报送粮食购进、储存、销售等基本数据和有关情况。"},{"i":38,"n":"第三十八条","txt":"为了保障市场供应、保护粮食生产者利益，必要时国务院可以根据粮食安全形势和财政状况，决定对重点粮食品种在粮食主产区实行政策性收储。"},{"i":39,"n":"第三十九条","txt":"从事粮食收购、加工、销售的规模以上经营者，应当按照所在地省、自治区、直辖市人民政府的规定，执行特定情况下的粮食库存量。"},{"i":40,"n":"第四十条","txt":"粮食供求关系和价格显著变化或者有可能显著变化时，县级以上人民政府及其有关部门可以按照权限采取下列措施调控粮食市场："},{"i":41,"n":"第四十一条","txt":"国家建立健全粮食风险基金制度。粮食风险基金主要用于支持粮食储备、稳定粮食市场等。"},{"i":42,"n":"第四十二条","txt":"国家鼓励和引导粮食加工业发展，重点支持在粮食生产功能区和重要农产品生产保护区发展粮食加工业，协调推进粮食初加工、精深加工、综合利用加工，保障粮食加工产品有效供给和质量安全。"},{"i":43,"n":"第四十三条","txt":"国家鼓励和引导粮食加工结构优化，增加优质、营养粮食加工产品供给，优先保障口粮加工，饲料用粮、工业用粮加工应当服从口粮保障。"},{"i":44,"n":"第四十四条","txt":"县级以上地方人民政府应当根据本行政区域人口和经济社会发展水平，科学布局粮食加工业，确保本行政区域的粮食加工能力特别是应急状态下的粮食加工能力。"},{"i":45,"n":"第四十五条","txt":"国家鼓励粮食主产区和主销区以多种形式建立稳定的产销关系，鼓励粮食主销区的企业在粮食主产区建立粮源基地、加工基地和仓储物流设施等，促进区域粮食供求平衡。"},{"i":46,"n":"第四十六条","txt":"国家支持建设粮食加工原料基地、基础设施和物流体系，支持粮食加工新技术、新工艺、新设备的推广应用。"},{"i":47,"n":"第四十七条","txt":"国家建立统一领导、分级负责、属地管理为主的粮食应急管理体制。"},{"i":48,"n":"第四十八条","txt":"国务院发展改革、粮食和储备主管部门会同有关部门制定全国的粮食应急预案，报请国务院批准。省、自治区、直辖市人民政府应当根据本行政区域的实际情况，制定本行政区域的粮食应急预案。"},{"i":49,"n":"第四十九条","txt":"国家建立粮食市场异常波动报告制度。发生突发事件，引起粮食市场供求关系和价格异常波动时，县级以上地方人民政府发展改革、农业农村、粮食和储备、市场监督管理等主管部门应当及时将粮食市场有关情况向本级人民政府和上一级人民政府主管部门报告。"},{"i":50,"n":"第五十条","txt":"县级以上人民政府按照权限确认出现粮食应急状态的，应当及时启动应急响应，可以依法采取下列应急处置措施："},{"i":51,"n":"第五十一条","txt":"粮食应急状态消除后，县级以上人民政府应当及时终止实施应急处置措施，并恢复应对粮食应急状态的能力。"},{"i":52,"n":"第五十二条","txt":"国家厉行节约，反对浪费。县级以上人民政府应当建立健全引导激励与惩戒教育相结合的机制，加强对粮食节约工作的领导和监督管理，推进粮食节约工作。"},{"i":53,"n":"第五十三条","txt":"粮食生产者应当加强粮食作物生长期保护和生产作业管理，减少播种、田间管理、收获等环节的粮食损失和浪费。"},{"i":54,"n":"第五十四条","txt":"国家鼓励粮食经营者运用先进、高效的粮食储存、运输、加工设施设备，减少粮食损失损耗。"},{"i":55,"n":"第五十五条","txt":"国家推广应用粮食适度加工技术，防止过度加工，提高成品粮出品率。"},{"i":56,"n":"第五十六条","txt":"粮食食品生产经营者应当依照有关法律、法规的规定，建立健全生产、储存、运输、加工等管理制度，引导消费者合理消费，防止和减少粮食浪费。"},{"i":57,"n":"第五十七条","txt":"机关、人民团体、社会组织、学校、企业事业单位等应当加强本单位食堂的管理，定期开展节约粮食检查，纠正浪费行为。"},{"i":58,"n":"第五十八条","txt":"县级以上人民政府发展改革、农业农村、粮食和储备、自然资源、水行政、生态环境、市场监督管理、工业和信息化等有关部门应当依照职责对粮食生产、储备、流通、加工等实施监督检查，并建立粮食安全监管协调机制和信息共享机制，加强协作配合。"},{"i":59,"n":"第五十九条","txt":"国务院发展改革、农业农村、粮食和储备主管部门应当会同有关部门建立粮食安全监测预警体系，加强粮食安全风险评估，健全粮食安全信息发布机制。"},{"i":60,"n":"第六十条","txt":"国家完善粮食生产、储存、运输、加工标准体系。粮食生产经营者应当严格遵守有关法律、法规的规定，执行有关标准和技术规范，确保粮食质量安全。"},{"i":61,"n":"第六十一条","txt":"县级以上人民政府有关部门依照职责开展粮食安全监督检查，可以采取下列措施："},{"i":62,"n":"第六十二条","txt":"国务院发展改革、自然资源、农业农村、粮食和储备主管部门应当会同有关部门，按照规定具体实施对省、自治区、直辖市落实耕地保护和粮食安全责任制情况的考核。"},{"i":63,"n":"第六十三条","txt":"外商投资粮食生产经营，影响或者可能影响国家安全的，应当按照国家有关规定进行外商投资安全审查。"},{"i":64,"n":"第六十四条","txt":"县级以上人民政府发展改革、农业农村、粮食和储备等主管部门应当加强粮食安全信用体系建设，建立粮食生产经营者信用记录。"},{"i":65,"n":"第六十五条","txt":"违反本法规定，地方人民政府和县级以上人民政府有关部门不履行粮食安全保障工作职责或者有其他滥用职权、玩忽职守、徇私舞弊行为的，对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":66,"n":"第六十六条","txt":"违反本法规定，种植不符合耕地种植用途管控要求作物的，由县级人民政府农业农村主管部门或者乡镇人民政府给予批评教育；经批评教育仍不改正的，可以不予发放粮食生产相关补贴；对有关农业生产经营组织，可以依法处以罚款。"},{"i":67,"n":"第六十七条","txt":"违反本法规定，承储政府粮食储备的企业或者其他组织有下列行为之一的，依照有关行政法规的规定处罚："},{"i":68,"n":"第六十八条","txt":"违反本法规定，侵占、损毁、擅自拆除或者迁移政府投资建设的粮食流通基础设施，或者擅自改变其用途的，由县级以上地方人民政府有关部门依照职责责令停止违法行为，限期恢复原状或者采取其他补救措施；逾期不恢复原状、不采取其他补救措施的，对单位处五万元以上五十万元以下罚款，对个人处五千元以上五万元以下罚款。"},{"i":69,"n":"第六十九条","txt":"违反本法规定，粮食应急状态发生时，不服从县级以上人民政府的统一指挥和调度，或者不配合采取应急处置措施的，由县级以上人民政府有关部门依照职责责令改正，给予警告；拒不改正的，对单位处二万元以上二十万元以下罚款，对个人处二千元以上二万元以下罚款；情节严重的，对单位处二十万元以上二百万元以下罚款，对个人处二万元以上二十万元以下罚款。"},{"i":70,"n":"第七十条","txt":"违反本法规定，故意毁坏在耕地上种植的粮食作物青苗的，由县级以上地方人民政府农业农村主管部门责令停止违法行为；情节严重的，可以处毁坏粮食作物青苗价值五倍以下罚款。"},{"i":71,"n":"第七十一条","txt":"违反有关土地管理、耕地保护、种子、农产品质量安全、食品安全、反食品浪费、安全生产等法律、行政法规的，依照相关法律、行政法规的规定处理、处罚。"},{"i":72,"n":"第七十二条","txt":"违反本法规定，给他人造成损失的，依法承担赔偿责任；构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":73,"n":"第七十三条","txt":"本法所称粮食，是指小麦、稻谷、玉米、大豆、杂粮及其成品粮。杂粮包括谷子、高粱、大麦、荞麦、燕麦、青稞、绿豆、马铃薯、甘薯等。"},{"i":74,"n":"第七十四条","txt":"本法自2024年6月1日起施行。"}],"tongjifa":[{"i":1,"n":"第一条","txt":"为了科学、有效地组织统计工作，保障统计资料的真实性、准确性、完整性和及时性，加强统计监督，发挥统计在了解国情国力、服务经济社会高质量发展中的重要作用，推动全面建设社会主义现代化国家，制定本法。"},{"i":2,"n":"第二条","txt":"本法适用于各级人民政府、县级以上人民政府统计机构和有关部门组织实施的统计活动。"},{"i":3,"n":"第三条","txt":"统计工作坚持中国共产党的领导。"},{"i":4,"n":"第四条","txt":"国务院和地方各级人民政府、各有关部门应当加强对统计工作的组织领导，为统计工作提供必要的保障。"},{"i":5,"n":"第五条","txt":"国家加强统计科学研究，根据经济社会发展的新情况，健全科学合理的统计标准和统计指标体系，将新经济新领域纳入统计调查范围，并不断改进统计调查方法，提高统计的科学性。"},{"i":6,"n":"第六条","txt":"国家构建系统完整、协同高效、约束有力、权威可靠的统计监督体系。"},{"i":7,"n":"第七条","txt":"统计机构和统计人员依照本法规定独立行使统计调查、统计报告、统计监督的职权，不受侵犯。"},{"i":8,"n":"第八条","txt":"国家机关、企业事业单位和其他组织以及个体工商户和个人等统计调查对象，必须依照本法和国家有关规定，真实、准确、完整、及时地提供统计调查所需的资料，不得提供不真实或者不完整的统计资料，不得迟报、拒报统计资料。"},{"i":9,"n":"第九条","txt":"地方各级人民政府、县级以上人民政府统计机构和有关部门应当根据国家有关规定，将防范和惩治统计造假、弄虚作假纳入依法行政、依法履职责任范围，建立健全相关责任制，加强对领导干部统计工作的考核管理，依法对统计造假、弄虚作假行为追究法律责任。"},{"i":10,"n":"第十条","txt":"统计工作应当接受社会公众的监督。任何单位和个人有权检举统计中弄虚作假等违法行为。对检举有功的单位和个人应当给予表彰和奖励。"},{"i":11,"n":"第十一条","txt":"统计机构和统计人员对在统计工作中知悉的国家秘密、工作秘密、商业秘密、个人隐私和个人信息，应当予以保密，不得泄露或者向他人非法提供。"},{"i":12,"n":"第十二条","txt":"任何单位和个人不得利用虚假统计资料骗取荣誉称号、物质利益或者职务职级等晋升。"},{"i":13,"n":"第十三条","txt":"统计调查项目包括国家统计调查项目、部门统计调查项目和地方统计调查项目。"},{"i":14,"n":"第十四条","txt":"国家统计调查项目由国家统计局制定，或者由国家统计局和国务院有关部门共同制定，报国务院备案；重大的国家统计调查项目报国务院审批。"},{"i":15,"n":"第十五条","txt":"统计调查项目的审批机关应当对调查项目的必要性、可行性、科学性进行审查，对符合法定条件的，作出予以批准的书面决定，并公布；对不符合法定条件的，作出不予批准的书面决定，并说明理由。"},{"i":16,"n":"第十六条","txt":"制定统计调查项目，应当同时制定该项目的统计调查制度，并依照本法第十四条的规定一并报经审批或者备案。"},{"i":17,"n":"第十七条","txt":"统计调查表应当标明表号、制定机关、批准或者备案文号、有效期限等标志。"},{"i":18,"n":"第十八条","txt":"搜集、整理统计资料，应当以周期性普查为基础，以经常性抽样调查为主体，综合运用全面调查、重点调查等方法，并充分利用行政记录、社会大数据等资料。"},{"i":19,"n":"第十九条","txt":"国家制定统一的统计标准，保障统计调查采用的指标涵义、计算方法、分类目录、调查表式和统计编码等的标准化。"},{"i":20,"n":"第二十条","txt":"国家实施统一的国民经济核算制度。"},{"i":21,"n":"第二十一条","txt":"县级以上人民政府统计机构根据统计任务的需要，可以在统计调查对象中推广使用计算机网络报送统计资料。"},{"i":22,"n":"第二十二条","txt":"县级以上人民政府应当将统计工作所需经费列入财政预算。"},{"i":23,"n":"第二十三条","txt":"县级以上人民政府统计机构和有关部门以及乡、镇人民政府，应当按照国家有关规定建立统计资料的保存、管理制度。"},{"i":24,"n":"第二十四条","txt":"国家机关、企业事业单位和其他组织等统计调查对象，应当按照国家有关规定设置原始记录、统计台账，推动统计台账电子化、数字化、标准化，建立健全统计资料的审核、签署、报送、归档等管理制度。"},{"i":25,"n":"第二十五条","txt":"县级以上人民政府有关部门应当及时向本级人民政府统计机构提供统计所需的行政记录资料和国民经济核算所需的财务资料、财政资料及其他资料，并按照统计调查制度的规定及时向本级人民政府统计机构报送其组织实施统计调查取得的有关资料。"},{"i":26,"n":"第二十六条","txt":"县级以上人民政府统计机构按照国家有关规定，定期公布统计资料。"},{"i":27,"n":"第二十七条","txt":"县级以上人民政府有关部门统计调查取得的统计资料，由本部门按照国家有关规定公布。"},{"i":28,"n":"第二十八条","txt":"统计调查中获得的能够识别或者推断单个统计调查对象身份的资料，任何单位和个人不得对外提供、泄露，不得用于统计以外的目的。"},{"i":29,"n":"第二十九条","txt":"县级以上人民政府统计机构和有关部门统计调查取得的统计资料，除依法应当保密的外，应当及时公开，供社会公众查询。"},{"i":30,"n":"第三十条","txt":"国务院设立国家统计局，依法组织领导和协调全国的统计工作。"},{"i":31,"n":"第三十一条","txt":"县级以上人民政府有关部门根据统计任务的需要设立统计机构，或者在有关机构中设置统计人员，并指定统计负责人，依法组织、管理本部门职责范围内的统计工作，实施统计调查，在统计业务上受本级人民政府统计机构的指导。"},{"i":32,"n":"第三十二条","txt":"统计机构、统计人员应当依法履行职责，如实搜集、报送统计资料，不得伪造、篡改统计资料，不得以任何方式要求任何单位和个人提供不真实的统计资料，不得有其他违反本法规定的行为。"},{"i":33,"n":"第三十三条","txt":"统计人员进行统计调查时，有权就与统计有关的问题询问有关人员，要求其如实提供有关情况、资料并改正不真实、不准确的资料。"},{"i":34,"n":"第三十四条","txt":"国家实行统计专业技术职务资格考试、评聘制度，提高统计人员的专业素质，保障统计队伍的稳定性。"},{"i":35,"n":"第三十五条","txt":"县级以上人民政府对下级人民政府、本级人民政府统计机构和有关部门执行本法的情况，实施监督。"},{"i":36,"n":"第三十六条","txt":"国家统计局组织管理全国统计工作的监督检查，查处重大统计违法行为。"},{"i":37,"n":"第三十七条","txt":"县级以上人民政府有关部门应当积极协助本级人民政府统计机构查处统计违法行为，及时向本级人民政府统计机构移送有关统计违法案件材料。"},{"i":38,"n":"第三十八条","txt":"县级以上人民政府统计机构在调查统计违法行为或者核查统计数据时，有权采取下列措施："},{"i":39,"n":"第三十九条","txt":"县级以上人民政府统计机构履行监督检查职责时，有关单位和个人应当如实反映情况，提供相关证明和资料，不得拒绝、阻碍检查，不得转移、隐匿、篡改、毁弃原始记录和凭证、统计台账、统计调查表、会计资料及其他相关证明和资料。"},{"i":40,"n":"第四十条","txt":"地方各级人民政府、县级以上人民政府统计机构或者有关部门、单位的负责人有下列行为之一的，由任免机关、单位或者监察机关依法给予处分，并由县级以上人民政府统计机构予以通报："},{"i":41,"n":"第四十一条","txt":"县级以上人民政府统计机构或者有关部门有下列行为之一的，由本级人民政府、上级人民政府统计机构或者本级人民政府统计机构责令改正，予以通报；对负有责任的领导人员和直接责任人员，由任免机关或者监察机关依法给予处分："},{"i":42,"n":"第四十二条","txt":"县级以上人民政府统计机构或者有关部门有下列行为之一的，对负有责任的领导人员和直接责任人员由任免机关或者监察机关依法给予处分："},{"i":43,"n":"第四十三条","txt":"统计机构、统计人员泄露国家秘密、工作秘密的，依法追究法律责任。"},{"i":44,"n":"第四十四条","txt":"作为统计调查对象的国家机关、企业事业单位或者其他组织有下列行为之一的，由县级以上人民政府统计机构责令改正，给予警告，可以予以通报；其负有责任的领导人员和直接责任人员属于公职人员的，由任免机关、单位或者监察机关依法给予处分："},{"i":45,"n":"第四十五条","txt":"作为统计调查对象的国家机关、企业事业单位或者其他组织迟报统计资料，或者未按照国家有关规定设置原始记录、统计台账的，由县级以上人民政府统计机构责令改正，给予警告，可以予以通报；其负有责任的领导人员和直接责任人员属于公职人员的，由任免机关、单位或者监察机关依法给予处分。"},{"i":46,"n":"第四十六条","txt":"县级以上人民政府统计机构查处统计违法行为时，认为对有关公职人员依法应当给予处分的，应当向该公职人员的任免机关、单位提出给予处分的建议，该公职人员的任免机关、单位应当依法及时作出决定，并将结果书面通知县级以上人民政府统计机构；向监察机关移送的，由监察机关按照有关规定办理。"},{"i":47,"n":"第四十七条","txt":"作为统计调查对象的个人在重大国情国力普查活动中拒绝、阻碍统计调查，或者提供不真实或者不完整的普查资料的，由县级以上人民政府统计机构责令改正，予以批评教育。"},{"i":48,"n":"第四十八条","txt":"违反本法规定，利用虚假统计资料骗取荣誉称号、物质利益或者职务职级等晋升的，除对其编造虚假统计资料或者要求他人编造虚假统计资料的行为依法追究法律责任外，由作出有关决定的单位或者其上级单位、监察机关取消其荣誉称号，追缴获得的物质利益，撤销晋升的职务职级等。"},{"i":49,"n":"第四十九条","txt":"当事人对县级以上人民政府统计机构作出的行政处罚决定不服的，可以依法申请行政复议或者提起行政诉讼。对国家统计局派出的调查机构作出的行政处罚决定不服的，向国家统计局申请行政复议。"},{"i":50,"n":"第五十条","txt":"违反本法规定，造成人身损害、财产损失的，依法承担民事责任；构成犯罪的，依法追究刑事责任。"},{"i":51,"n":"第五十一条","txt":"本法所称县级以上人民政府统计机构，是指国家统计局及其派出的调查机构、县级以上地方人民政府统计机构。"},{"i":52,"n":"第五十二条","txt":"民间统计调查活动的管理办法，由国务院制定。"},{"i":53,"n":"第五十三条","txt":"本法自2010年1月1日起施行。"}],"wangluoanquanfa":[{"i":1,"n":"第一条","txt":"为了保障网络安全，维护网络空间主权和国家安全、社会公共利益，保护公民、法人和其他组织的合法权益，促进经济社会信息化健康发展，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内建设、运营、维护和使用网络，以及网络安全的监督管理，适用本法。"},{"i":3,"n":"第三条","txt":"网络安全工作坚持中国共产党的领导，贯彻总体国家安全观，统筹发展和安全，推进网络强国建设。"},{"i":4,"n":"第四条","txt":"国家坚持网络安全与信息化发展并重，遵循积极利用、科学发展、依法管理、确保安全的方针，推进网络基础设施建设和互联互通，鼓励网络技术创新和应用，支持培养网络安全人才，建立健全网络安全保障体系，提高网络安全保护能力。"},{"i":5,"n":"第五条","txt":"国家制定并不断完善网络安全战略，明确保障网络安全的基本要求和主要目标，提出重点领域的网络安全政策、工作任务和措施。"},{"i":6,"n":"第六条","txt":"国家采取措施，监测、防御、处置来源于中华人民共和国境内外的网络安全风险和威胁，保护关键信息基础设施免受攻击、侵入、干扰和破坏，依法惩治网络违法犯罪活动，维护网络空间安全和秩序。"},{"i":7,"n":"第七条","txt":"国家倡导诚实守信、健康文明的网络行为，推动传播社会主义核心价值观，采取措施提高全社会的网络安全意识和水平，形成全社会共同参与促进网络安全的良好环境。"},{"i":8,"n":"第八条","txt":"国家积极开展网络空间治理、网络技术研发和标准制定、打击网络违法犯罪等方面的国际交流与合作，推动构建和平、安全、开放、合作的网络空间，建立多边、民主、透明的网络治理体系。"},{"i":9,"n":"第九条","txt":"国家网信部门负责统筹协调网络安全工作和相关监督管理工作。国务院电信主管部门、公安部门和其他有关机关依照本法和有关法律、行政法规的规定，在各自职责范围内负责网络安全保护和监督管理工作。"},{"i":10,"n":"第十条","txt":"网络运营者开展经营和服务活动，必须遵守法律、行政法规，尊重社会公德，遵守商业道德，诚实信用，履行网络安全保护义务，接受政府和社会的监督，承担社会责任。"},{"i":11,"n":"第十一条","txt":"建设、运营网络或者通过网络提供服务，应当依照法律、行政法规的规定和国家标准的强制性要求，采取技术措施和其他必要措施，保障网络安全、稳定运行，有效应对网络安全事件，防范网络违法犯罪活动，维护网络数据的完整性、保密性和可用性。"},{"i":12,"n":"第十二条","txt":"网络相关行业组织按照章程，加强行业自律，制定网络安全行为规范，指导会员加强网络安全保护，提高网络安全保护水平，促进行业健康发展。"},{"i":13,"n":"第十三条","txt":"国家保护公民、法人和其他组织依法使用网络的权利，促进网络接入普及，提升网络服务水平，为社会提供安全、便利的网络服务，保障网络信息依法有序自由流动。"},{"i":14,"n":"第十四条","txt":"国家支持研究开发有利于未成年人健康成长的网络产品和服务，依法惩治利用网络从事危害未成年人身心健康的活动，为未成年人提供安全、健康的网络环境。"},{"i":15,"n":"第十五条","txt":"任何个人和组织有权对危害网络安全的行为向网信、电信、公安等部门举报。收到举报的部门应当及时依法作出处理；不属于本部门职责的，应当及时移送有权处理的部门。"},{"i":16,"n":"第十六条","txt":"国家建立和完善网络安全标准体系。国务院标准化行政主管部门和国务院其他有关部门根据各自的职责，组织制定并适时修订有关网络安全管理以及网络产品、服务和运行安全的国家标准、行业标准。"},{"i":17,"n":"第十七条","txt":"国务院和省、自治区、直辖市人民政府应当统筹规划，加大投入，扶持重点网络安全技术产业和项目，支持网络安全技术的研究开发和应用，推广安全可信的网络产品和服务，保护网络技术知识产权，支持企业、研究机构和高等学校等参与国家网络安全技术创新项目。"},{"i":18,"n":"第十八条","txt":"国家推进网络安全社会化服务体系建设，鼓励有关企业、机构开展网络安全认证、检测和风险评估等安全服务。"},{"i":19,"n":"第十九条","txt":"国家鼓励开发网络数据安全保护和利用技术，促进公共数据资源开放，推动技术创新和经济社会发展。"},{"i":20,"n":"第二十条","txt":"国家支持人工智能基础理论研究和算法等关键技术研发，推进训练数据资源、算力等基础设施建设，完善人工智能伦理规范，加强风险监测评估和安全监管，促进人工智能应用和健康发展。"},{"i":21,"n":"第二十一条","txt":"各级人民政府及其有关部门应当组织开展经常性的网络安全宣传教育，并指导、督促有关单位做好网络安全宣传教育工作。"},{"i":22,"n":"第二十二条","txt":"国家支持企业和高等学校、职业学校等教育培训机构开展网络安全相关教育与培训，采取多种方式培养网络安全人才，促进网络安全人才交流。"},{"i":23,"n":"第二十三条","txt":"国家实行网络安全等级保护制度。网络运营者应当按照网络安全等级保护制度的要求，履行下列安全保护义务，保障网络免受干扰、破坏或者未经授权的访问，防止网络数据泄露或者被窃取、篡改："},{"i":24,"n":"第二十四条","txt":"网络产品、服务应当符合相关国家标准的强制性要求。网络产品、服务的提供者不得设置恶意程序；发现其网络产品、服务存在安全缺陷、漏洞等风险时，应当立即采取补救措施，按照规定及时告知用户并向有关主管部门报告。"},{"i":25,"n":"第二十五条","txt":"网络关键设备和网络安全专用产品应当按照相关国家标准的强制性要求，由具备资格的机构安全认证合格或者安全检测符合要求后，方可销售或者提供。国家网信部门会同国务院有关部门制定、公布网络关键设备和网络安全专用产品目录，并推动安全认证和安全检测结果互认，避免重复认证、检测。"},{"i":26,"n":"第二十六条","txt":"网络运营者为用户办理网络接入、域名注册服务，办理固定电话、移动电话等入网手续，或者为用户提供信息发布、即时通讯等服务，在与用户签订协议或者确认提供服务时，应当要求用户提供真实身份信息。用户不提供真实身份信息的，网络运营者不得为其提供相关服务。"},{"i":27,"n":"第二十七条","txt":"网络运营者应当制定网络安全事件应急预案，及时处置系统漏洞、计算机病毒、网络攻击、网络侵入等安全风险；在发生危害网络安全的事件时，立即启动应急预案，采取相应的补救措施，并按照规定向有关主管部门报告。"},{"i":28,"n":"第二十八条","txt":"开展网络安全认证、检测、风险评估等活动，向社会发布系统漏洞、计算机病毒、网络攻击、网络侵入等网络安全信息，应当遵守国家有关规定。"},{"i":29,"n":"第二十九条","txt":"任何个人和组织不得从事非法侵入他人网络、干扰他人网络正常功能、窃取网络数据等危害网络安全的活动；不得提供专门用于从事侵入网络、干扰网络正常功能及防护措施、窃取网络数据等危害网络安全活动的程序、工具；明知他人从事危害网络安全的活动的，不得为其提供技术支持、广告推广、支付结算等帮助。"},{"i":30,"n":"第三十条","txt":"网络运营者应当为公安机关、国家安全机关依法维护国家安全和侦查犯罪的活动提供技术支持和协助。"},{"i":31,"n":"第三十一条","txt":"国家支持网络运营者之间在网络安全信息收集、分析、通报和应急处置等方面进行合作，提高网络运营者的安全保障能力。"},{"i":32,"n":"第三十二条","txt":"网信部门和有关部门在履行网络安全保护职责中获取的信息，只能用于维护网络安全的需要，不得用于其他用途。"},{"i":33,"n":"第三十三条","txt":"国家对公共通信和信息服务、能源、交通、水利、金融、公共服务、电子政务等重要行业和领域，以及其他一旦遭到破坏、丧失功能或者数据泄露，可能严重危害国家安全、国计民生、公共利益的关键信息基础设施，在网络安全等级保护制度的基础上，实行重点保护。关键信息基础设施的具体范围和安全保护办法由国务院制定。"},{"i":34,"n":"第三十四条","txt":"按照国务院规定的职责分工，负责关键信息基础设施安全保护工作的部门分别编制并组织实施本行业、本领域的关键信息基础设施安全规划，指导和监督关键信息基础设施运行安全保护工作。"},{"i":35,"n":"第三十五条","txt":"建设关键信息基础设施应当确保其具有支持业务稳定、持续运行的性能，并保证安全技术措施同步规划、同步建设、同步使用。"},{"i":36,"n":"第三十六条","txt":"除本法第二十三条的规定外，关键信息基础设施的运营者还应当履行下列安全保护义务："},{"i":37,"n":"第三十七条","txt":"关键信息基础设施的运营者采购网络产品和服务，可能影响国家安全的，应当通过国家网信部门会同国务院有关部门组织的国家安全审查。"},{"i":38,"n":"第三十八条","txt":"关键信息基础设施的运营者采购网络产品和服务，应当按照规定与提供者签订安全保密协议，明确安全和保密义务与责任。"},{"i":39,"n":"第三十九条","txt":"关键信息基础设施的运营者在中华人民共和国境内运营中收集和产生的个人信息和重要数据应当在境内存储。因业务需要，确需向境外提供的，应当按照国家网信部门会同国务院有关部门制定的办法进行安全评估；法律、行政法规另有规定的，依照其规定。"},{"i":40,"n":"第四十条","txt":"关键信息基础设施的运营者应当自行或者委托网络安全服务机构对其网络的安全性和可能存在的风险每年至少进行一次检测评估，并将检测评估情况和改进措施报送相关负责关键信息基础设施安全保护工作的部门。"},{"i":41,"n":"第四十一条","txt":"国家网信部门应当统筹协调有关部门对关键信息基础设施的安全保护采取下列措施："},{"i":42,"n":"第四十二条","txt":"网络运营者应当对其收集的用户信息严格保密，并建立健全用户信息保护制度。"},{"i":43,"n":"第四十三条","txt":"网络运营者收集、使用个人信息，应当遵循合法、正当、必要的原则，公开收集、使用规则，明示收集、使用信息的目的、方式和范围，并经被收集者同意。"},{"i":44,"n":"第四十四条","txt":"网络运营者不得泄露、篡改、毁损其收集的个人信息；未经被收集者同意，不得向他人提供个人信息。但是，经过处理无法识别特定个人且不能复原的除外。"},{"i":45,"n":"第四十五条","txt":"个人发现网络运营者违反法律、行政法规的规定或者双方的约定收集、使用其个人信息的，有权要求网络运营者删除其个人信息；发现网络运营者收集、存储的其个人信息有错误的，有权要求网络运营者予以更正。网络运营者应当采取措施予以删除或者更正。"},{"i":46,"n":"第四十六条","txt":"任何个人和组织不得窃取或者以其他非法方式获取个人信息，不得非法出售或者非法向他人提供个人信息。"},{"i":47,"n":"第四十七条","txt":"依法负有网络安全监督管理职责的部门及其工作人员，必须对在履行职责中知悉的个人信息、隐私和商业秘密严格保密，不得泄露、出售或者非法向他人提供。"},{"i":48,"n":"第四十八条","txt":"任何个人和组织应当对其使用网络的行为负责，不得设立用于实施诈骗，传授犯罪方法，制作或者销售违禁物品、管制物品等违法犯罪活动的网站、通讯群组，不得利用网络发布涉及实施诈骗，制作或者销售违禁物品、管制物品以及其他违法犯罪活动的信息。"},{"i":49,"n":"第四十九条","txt":"网络运营者应当加强对其用户发布的信息的管理，发现法律、行政法规禁止发布或者传输的信息的，应当立即停止传输该信息，采取消除等处置措施，防止信息扩散，保存有关记录，并向有关主管部门报告。"},{"i":50,"n":"第五十条","txt":"任何个人和组织发送的电子信息、提供的应用软件，不得设置恶意程序，不得含有法律、行政法规禁止发布或者传输的信息。"},{"i":51,"n":"第五十一条","txt":"网络运营者应当建立网络信息安全投诉、举报制度，公布投诉、举报方式等信息，及时受理并处理有关网络信息安全的投诉和举报。"},{"i":52,"n":"第五十二条","txt":"国家网信部门和有关部门依法履行网络信息安全监督管理职责，发现法律、行政法规禁止发布或者传输的信息的，应当要求网络运营者停止传输，采取消除等处置措施，保存有关记录；对来源于中华人民共和国境外的上述信息，应当通知有关机构采取技术措施和其他必要措施阻断传播。"},{"i":53,"n":"第五十三条","txt":"国家建立网络安全监测预警和信息通报制度。国家网信部门应当统筹协调有关部门加强网络安全信息收集、分析和通报工作，按照规定统一发布网络安全监测预警信息。"},{"i":54,"n":"第五十四条","txt":"负责关键信息基础设施安全保护工作的部门，应当建立健全本行业、本领域的网络安全监测预警和信息通报制度，并按照规定报送网络安全监测预警信息。"},{"i":55,"n":"第五十五条","txt":"国家网信部门协调有关部门建立健全网络安全风险评估和应急工作机制，制定网络安全事件应急预案，并定期组织演练。"},{"i":56,"n":"第五十六条","txt":"网络安全事件发生的风险增大时，省级以上人民政府有关部门应当按照规定的权限和程序，并根据网络安全风险的特点和可能造成的危害，采取下列措施："},{"i":57,"n":"第五十七条","txt":"发生网络安全事件，应当立即启动网络安全事件应急预案，对网络安全事件进行调查和评估，要求网络运营者采取技术措施和其他必要措施，消除安全隐患，防止危害扩大，并及时向社会发布与公众有关的警示信息。"},{"i":58,"n":"第五十八条","txt":"省级以上人民政府有关部门在履行网络安全监督管理职责中，发现网络存在较大安全风险或者发生安全事件的，可以按照规定的权限和程序对该网络的运营者的法定代表人或者主要负责人进行约谈。网络运营者应当按照要求采取措施，进行整改，消除隐患。"},{"i":59,"n":"第五十九条","txt":"因网络安全事件，发生突发事件或者生产安全事故的，应当依照《中华人民共和国突发事件应对法》、《中华人民共和国安全生产法》等有关法律、行政法规的规定处置。"},{"i":60,"n":"第六十条","txt":"因维护国家安全和社会公共秩序，处置重大突发社会安全事件的需要，经国务院决定或者批准，可以在特定区域对网络通信采取限制等临时措施。"},{"i":61,"n":"第六十一条","txt":"网络运营者不履行本法第二十三条、第二十七条规定的网络安全保护义务的，由有关主管部门责令改正，给予警告，可以处一万元以上五万元以下罚款；拒不改正或者导致危害网络安全等后果的，处五万元以上五十万元以下罚款，对直接负责的主管人员和其他直接责任人员处一万元以上十万元以下罚款。"},{"i":62,"n":"第六十二条","txt":"违反本法第二十四条第一款、第二款和第五十条第一款规定，有下列行为之一的，由有关主管部门责令改正，给予警告；拒不改正或者导致危害网络安全等后果的，处五万元以上五十万元以下罚款，对直接负责的主管人员处一万元以上十万元以下罚款："},{"i":63,"n":"第六十三条","txt":"违反本法第二十五条规定，销售或者提供未经安全认证、安全检测或者安全认证不合格、安全检测不符合要求的网络关键设备和网络安全专用产品的，由有关主管部门责令停止销售或者提供，给予警告，没收违法所得；没有违法所得或者违法所得不足十万元的，并处二万元以上十万元以下罚款；违法所得十万元以上的，并处违法所得一倍以上五倍以下罚款；情节严重的，并可以责令暂停相关业务、停业整顿、吊销相关业务许可证或者吊销营业执照。法律、行政法规另有规定的，依照其规定。"},{"i":64,"n":"第六十四条","txt":"网络运营者违反本法第二十六条第一款规定，未要求用户提供真实身份信息，或者对不提供真实身份信息的用户提供相关服务的，由有关主管部门责令改正；拒不改正或者情节严重的，处五万元以上五十万元以下罚款，并可以责令暂停相关业务、停业整顿、关闭网站或者应用程序、吊销相关业务许可证或者吊销营业执照，对直接负责的主管人员和其他直接责任人员处一万元以上十万元以下罚款。"},{"i":65,"n":"第六十五条","txt":"违反本法第二十八条规定，开展网络安全认证、检测、风险评估等活动，或者向社会发布系统漏洞、计算机病毒、网络攻击、网络侵入等网络安全信息的，由有关主管部门责令改正，给予警告，可以处一万元以上十万元以下罚款；拒不改正或者情节严重的，处十万元以上一百万元以下罚款，并可以责令暂停相关业务、停业整顿、关闭网站或者应用程序、吊销相关业务许可证或者吊销营业执照，对直接负责的主管人员和其他直接责任人员处一万元以上十万元以下罚款。"},{"i":66,"n":"第六十六条","txt":"违反本法第二十九条规定，从事危害网络安全的活动，或者提供专门用于从事危害网络安全活动的程序、工具，或者为他人从事危害网络安全的活动提供技术支持、广告推广、支付结算等帮助，尚不构成犯罪的，由公安机关没收违法所得，处五日以下拘留，可以并处五万元以上五十万元以下罚款；情节较重的，处五日以上十五日以下拘留，可以并处十万元以上一百万元以下罚款。"},{"i":67,"n":"第六十七条","txt":"关键信息基础设施的运营者违反本法第三十七条规定，使用未经安全审查或者安全审查未通过的网络产品或者服务的，由有关主管部门责令限期改正、停止使用、消除对国家安全的影响，处采购金额一倍以上十倍以下罚款，对直接负责的主管人员和其他直接责任人员处一万元以上十万元以下罚款。"},{"i":68,"n":"第六十八条","txt":"违反本法第四十八条规定，设立用于实施违法犯罪活动的网站、通讯群组，或者利用网络发布涉及实施违法犯罪活动的信息，尚不构成犯罪的，由公安机关处五日以下拘留，可以并处一万元以上十万元以下罚款；情节较重的，处五日以上十五日以下拘留，可以并处五万元以上五十万元以下罚款。关闭用于实施违法犯罪活动的网站、通讯群组。"},{"i":69,"n":"第六十九条","txt":"网络运营者违反本法第四十九条规定，对法律、行政法规禁止发布或者传输的信息未停止传输、采取消除等处置措施、保存有关记录、向有关主管部门报告，或者违反本法第五十二条规定，不按照有关部门的要求对法律、行政法规禁止发布或者传输的信息停止传输、采取消除等处置措施、保存有关记录的，由有关主管部门责令改正，给予警告、予以通报，可以处五万元以上五十万元以下罚款；拒不改正或者情节严重的，处五十万元以上二百万元以下罚款，并可以责令暂停相关业务、停业整顿、关闭网站或者应用程序、吊销相关业务许可证或者吊销营业执照，对直接负责的主管人员和其他直接责任人员处五万元以上二十万元以下罚款。"},{"i":70,"n":"第七十条","txt":"网络运营者违反本法规定，有下列行为之一的，由有关主管部门责令改正；拒不改正或者情节严重的，处五万元以上五十万元以下罚款，对直接负责的主管人员和其他直接责任人员，处一万元以上十万元以下罚款："},{"i":71,"n":"第七十一条","txt":"有下列行为之一的，依照有关法律、行政法规的规定处理、处罚："},{"i":72,"n":"第七十二条","txt":"有本法规定的违法行为的，依照有关法律、行政法规的规定记入信用档案，并予以公示。"},{"i":73,"n":"第七十三条","txt":"违反本法规定，但具有《中华人民共和国行政处罚法》规定的从轻、减轻或者不予处罚情形的，依照其规定从轻、减轻或者不予处罚。"},{"i":74,"n":"第七十四条","txt":"国家机关政务网络的运营者不履行本法规定的网络安全保护义务的，由其上级机关或者有关机关责令改正；对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":75,"n":"第七十五条","txt":"网信部门和有关部门违反本法第三十二条规定，将在履行网络安全保护职责中获取的信息用于其他用途的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":76,"n":"第七十六条","txt":"违反本法规定，给他人造成损害的，依法承担民事责任。"},{"i":77,"n":"第七十七条","txt":"境外的机构、组织、个人从事危害中华人民共和国网络安全的活动的，依法追究法律责任；造成严重后果的，国务院公安部门和有关部门并可以决定对该机构、组织、个人采取冻结财产或者其他必要的制裁措施。"},{"i":78,"n":"第七十八条","txt":"本法下列用语的含义："},{"i":79,"n":"第七十九条","txt":"存储、处理涉及国家秘密信息的网络的运行安全保护，除应当遵守本法外，还应当遵守保密法律、行政法规的规定。"},{"i":80,"n":"第八十条","txt":"军事网络的安全保护，由中央军事委员会另行规定。"},{"i":81,"n":"第八十一条","txt":"本法自2017年6月1日起施行。"}],"gengdizhanyongshuifa":[{"i":1,"n":"第一条","txt":"为了合理利用土地资源，加强土地管理，保护耕地，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内占用耕地建设建筑物、构筑物或者从事非农业建设的单位和个人，为耕地占用税的纳税人，应当依照本法规定缴纳耕地占用税。"},{"i":3,"n":"第三条","txt":"耕地占用税以纳税人实际占用的耕地面积为计税依据，按照规定的适用税额一次性征收，应纳税额为纳税人实际占用的耕地面积（平方米）乘以适用税额。"},{"i":4,"n":"第四条","txt":"耕地占用税的税额如下："},{"i":5,"n":"第五条","txt":"在人均耕地低于零点五亩的地区，省、自治区、直辖市可以根据当地经济发展情况，适当提高耕地占用税的适用税额，但提高的部分不得超过本法第四条第二款确定的适用税额的百分之五十。具体适用税额按照本法第四条第二款规定的程序确定。"},{"i":6,"n":"第六条","txt":"占用基本农田的，应当按照本法第四条第二款或者第五条确定的当地适用税额，加按百分之一百五十征收。"},{"i":7,"n":"第七条","txt":"军事设施、学校、幼儿园、社会福利机构、医疗机构占用耕地，免征耕地占用税。"},{"i":8,"n":"第八条","txt":"依照本法第七条第一款、第二款规定免征或者减征耕地占用税后，纳税人改变原占地用途，不再属于免征或者减征耕地占用税情形的，应当按照当地适用税额补缴耕地占用税。"},{"i":9,"n":"第九条","txt":"耕地占用税由税务机关负责征收。"},{"i":10,"n":"第十条","txt":"耕地占用税的纳税义务发生时间为纳税人收到自然资源主管部门办理占用耕地手续的书面通知的当日。纳税人应当自纳税义务发生之日起三十日内申报缴纳耕地占用税。"},{"i":11,"n":"第十一条","txt":"纳税人因建设项目施工或者地质勘查临时占用耕地，应当依照本法的规定缴纳耕地占用税。纳税人在批准临时占用耕地期满之日起一年内依法复垦，恢复种植条件的，全额退还已经缴纳的耕地占用税。"},{"i":12,"n":"第十二条","txt":"占用园地、林地、草地、农田水利用地、养殖水面、渔业水域滩涂以及其他农用地建设建筑物、构筑物或者从事非农业建设的，依照本法的规定缴纳耕地占用税。"},{"i":13,"n":"第十三条","txt":"税务机关应当与相关部门建立耕地占用税涉税信息共享机制和工作配合机制。县级以上地方人民政府自然资源、农业农村、水利等相关部门应当定期向税务机关提供农用地转用、临时占地等信息，协助税务机关加强耕地占用税征收管理。"},{"i":14,"n":"第十四条","txt":"耕地占用税的征收管理，依照本法和《中华人民共和国税收征收管理法》的规定执行。"},{"i":15,"n":"第十五条","txt":"纳税人、税务机关及其工作人员违反本法规定的，依照《中华人民共和国税收征收管理法》和有关法律法规的规定追究法律责任。"},{"i":16,"n":"第十六条","txt":"本法自2019年9月1日起施行。2007年12月1日国务院公布的《中华人民共和国耕地占用税暂行条例》同时废止。"}],"hangdaofa":[{"i":1,"n":"第一条","txt":"为了规范和加强航道的规划、建设、养护、保护，保障航道畅通和通航安全，促进水路运输发展，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称航道，是指中华人民共和国领域内的江河、湖泊等内陆水域中可以供船舶通航的通道，以及内海、领海中经建设、养护可以供船舶通航的通道。航道包括通航建筑物、航道整治建筑物和航标等航道设施。"},{"i":3,"n":"第三条","txt":"规划、建设、养护、保护航道，应当根据经济社会发展和国防建设的需要，遵循综合利用和保护水资源、保护生态环境的原则，服从综合交通运输体系建设和防洪总体安排，统筹兼顾供水、灌溉、发电、渔业等需求，发挥水资源的综合效益。"},{"i":4,"n":"第四条","txt":"国务院和有关县级以上地方人民政府应当加强对航道工作的领导，组织、协调、督促有关部门采取措施，保持和改善航道通航条件，保护航道安全，维护航道网络完整和畅通。"},{"i":5,"n":"第五条","txt":"国务院交通运输主管部门主管全国航道管理工作，并按照国务院的规定直接管理跨省、自治区、直辖市的重要干线航道和国际、国境河流航道等重要航道。"},{"i":6,"n":"第六条","txt":"航道规划分为全国航道规划、流域航道规划、区域航道规划和省、自治区、直辖市航道规划。"},{"i":7,"n":"第七条","txt":"航道应当划分技术等级。航道技术等级包括现状技术等级和发展规划技术等级。航道发展规划技术等级根据相关自然条件以及防洪、供水、水资源保护、生态环境保护要求和航运发展需求等因素评定。"},{"i":8,"n":"第八条","txt":"全国航道规划由国务院交通运输主管部门会同国务院发展改革部门、国务院水行政主管部门等部门编制，报国务院批准公布。流域航道规划、区域航道规划由国务院交通运输主管部门编制并公布。"},{"i":9,"n":"第九条","txt":"依法制定并公布的航道规划应当依照执行；航道规划确需修改的，依照规划编制程序办理。"},{"i":10,"n":"第十条","txt":"新建航道以及为改善航道通航条件而进行的航道工程建设，应当遵守法律、行政法规关于建设工程质量管理、安全管理和生态环境保护的规定，符合航道规划，执行有关的国家标准、行业标准和技术规范，依法办理相关手续。"},{"i":11,"n":"第十一条","txt":"航道建设单位应当根据航道建设工程的技术要求，依法通过招标等方式选择具有相应资质的勘察、设计、施工和监理单位进行工程建设，对工程质量和安全进行监督检查，并对工程质量和安全负责。"},{"i":12,"n":"第十二条","txt":"有关县级以上人民政府交通运输主管部门应当加强对航道建设工程质量和安全的监督检查，保障航道建设工程的质量和安全。"},{"i":13,"n":"第十三条","txt":"航道建设工程竣工后，应当按照国家有关规定组织竣工验收，经验收合格方可正式投入使用。"},{"i":14,"n":"第十四条","txt":"进行航道工程建设应当维护河势稳定，符合防洪要求，不得危及依法建设的其他工程或者设施的安全。因航道工程建设损坏依法建设的其他工程或者设施的，航道建设单位应当予以修复或者依法赔偿。"},{"i":15,"n":"第十五条","txt":"国务院交通运输主管部门应当制定航道养护技术规范。"},{"i":16,"n":"第十六条","txt":"负责航道管理的部门应当根据航道现状技术等级或者航道自然条件确定并公布航道维护尺度和内河航道图。"},{"i":17,"n":"第十七条","txt":"负责航道管理的部门应当按照国务院交通运输主管部门的规定对航道进行巡查，发现航道实际尺度达不到航道维护尺度或者有其他不符合保证船舶通航安全要求的情形，应当进行维护，及时发布航道通告并通报海事管理机构。"},{"i":18,"n":"第十八条","txt":"海事管理机构发现航道损毁等危及通航安全的情形，应当及时通报负责航道管理的部门，并采取必要的安全保障措施。"},{"i":19,"n":"第十九条","txt":"负责航道管理的部门应当合理安排航道养护作业，避免限制通航的集中作业和在通航高峰期作业。"},{"i":20,"n":"第二十条","txt":"进行航道养护作业可能造成航道堵塞的，有关负责航道管理的部门应当会同海事管理机构事先通报相关区域负责航道管理的部门和海事管理机构，共同制定船舶疏导方案，并向社会公告。"},{"i":21,"n":"第二十一条","txt":"因自然灾害、事故灾难等突发事件造成航道损坏、阻塞的，负责航道管理的部门应当按照突发事件应急预案尽快修复抢通；必要时由县级以上人民政府组织尽快修复抢通。"},{"i":22,"n":"第二十二条","txt":"航标的设置、养护、保护和管理，依照有关法律、行政法规和国家标准或者行业标准的规定执行。"},{"i":23,"n":"第二十三条","txt":"部队执行任务、战备训练需要使用航道的，负责航道管理的部门应当给予必要的支持和协助。"},{"i":24,"n":"第二十四条","txt":"新建、改建、扩建（以下统称建设）跨越、穿越航道的桥梁、隧道、管道、缆线等建筑物、构筑物，应当符合该航道发展规划技术等级对通航净高、净宽、埋设深度等航道通航条件的要求。"},{"i":25,"n":"第二十五条","txt":"在通航河流上建设永久性拦河闸坝，建设单位应当按照航道发展规划技术等级建设通航建筑物。通航建筑物应当与主体工程同步规划、同步设计、同步建设、同步验收、同步投入使用。"},{"i":26,"n":"第二十六条","txt":"在航道保护范围内建设临河、临湖、临海建筑物或者构筑物，应当符合该航道通航条件的要求。"},{"i":27,"n":"第二十七条","txt":"建设本法第二十四条、第二十五条第一款、第二十六条第一款规定的工程（以下统称与航道有关的工程），除依照法律、行政法规或者国务院规定进行的防洪、供水等特殊工程外，不得因工程建设降低航道通航条件。"},{"i":28,"n":"第二十八条","txt":"建设与航道有关的工程，建设单位应当在工程可行性研究阶段就建设项目对航道通航条件的影响作出评价，并报送有审核权的交通运输主管部门或者航道管理机构审核，但下列工程除外："},{"i":29,"n":"第二十九条","txt":"国务院或者国务院有关部门批准、核准的建设项目，以及与国务院交通运输主管部门直接管理的航道有关的建设项目的航道通航条件影响评价，由国务院交通运输主管部门审核；其他建设项目的航道通航条件影响评价，按照省、自治区、直辖市人民政府的规定由县级以上地方人民政府交通运输主管部门或者航道管理机构审核。"},{"i":30,"n":"第三十条","txt":"航道上相邻拦河闸坝之间的航道通航水位衔接，应当符合国家规定的通航标准和技术要求。位于航道及其上游支流上的水工程，应当在设计、施工和调度运行中统筹考虑下游航道设计最低通航水位所需的下泄流量，但水文条件超出实际标准的除外。"},{"i":31,"n":"第三十一条","txt":"与航道有关的工程施工影响航道正常功能的，负责航道管理的部门、海事管理机构应当根据需要对航标或者航道的位置、走向进行临时调整；影响消除后应当及时恢复。所需费用由建设单位承担，但因防洪抢险工程引起调整的除外。"},{"i":32,"n":"第三十二条","txt":"与航道有关的工程竣工验收前，建设单位应当及时清除影响航道通航条件的临时设施及其残留物。"},{"i":33,"n":"第三十三条","txt":"与航道有关的工程建设活动不得危及航道安全。"},{"i":34,"n":"第三十四条","txt":"在通航水域上建设桥梁等建筑物，建设单位应当按照国家有关规定和技术要求设置航标等设施，并承担相应费用。"},{"i":35,"n":"第三十五条","txt":"禁止下列危害航道通航安全的行为："},{"i":36,"n":"第三十六条","txt":"在河道内采砂，应当依照有关法律、行政法规的规定进行。禁止在河道内依法划定的砂石禁采区采砂、无证采砂、未按批准的范围和作业方式采砂等非法采砂行为。"},{"i":37,"n":"第三十七条","txt":"本法施行前建设的拦河闸坝造成通航河流断航，需要恢复通航且具备建设通航建筑物条件的，由发展改革部门会同水行政主管部门、交通运输主管部门提出恢复通航方案，报本级人民政府决定。"},{"i":38,"n":"第三十八条","txt":"航道建设、勘察、设计、施工、监理单位在航道建设活动中违反本法规定的，由县级以上人民政府交通运输主管部门依照有关招标投标和工程建设管理的法律、行政法规的规定处罚。"},{"i":39,"n":"第三十九条","txt":"建设单位未依法报送航道通航条件影响评价材料而开工建设的，由有审核权的交通运输主管部门或者航道管理机构责令停止建设，限期补办手续，处三万元以下的罚款；逾期不补办手续继续建设的，由有审核权的交通运输主管部门或者航道管理机构责令恢复原状，处二十万元以上五十万元以下的罚款。"},{"i":40,"n":"第四十条","txt":"与航道有关的工程的建设单位违反本法规定，未及时清除影响航道通航条件的临时设施及其残留物的，由负责航道管理的部门责令限期清除，处二万元以下的罚款；逾期仍未清除的，处三万元以上二十万元以下的罚款，并由负责航道管理的部门依法组织清除，所需费用由建设单位承担。"},{"i":41,"n":"第四十一条","txt":"在通航水域上建设桥梁等建筑物，建设单位未按照规定设置航标等设施的，由负责航道管理的部门或者海事管理机构责令改正，处五万元以下罚款。"},{"i":42,"n":"第四十二条","txt":"违反本法规定，有下列行为之一的，由负责航道管理的部门责令改正，对单位处五万元以下罚款，对个人处二千元以下罚款；造成损失的，依法承担赔偿责任："},{"i":43,"n":"第四十三条","txt":"在河道内依法划定的砂石禁采区采砂、无证采砂、未按批准的范围和作业方式采砂等非法采砂的，依照有关法律、行政法规的规定处罚。"},{"i":44,"n":"第四十四条","txt":"违反法律规定，污染环境、破坏生态或者有其他环境违法行为的，依照《中华人民共和国环境保护法》等法律的规定处罚。"},{"i":45,"n":"第四十五条","txt":"交通运输主管部门以及其他有关部门不依法履行本法规定的职责的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":46,"n":"第四十六条","txt":"违反本法规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":47,"n":"第四十七条","txt":"进出军事港口、渔业港口的专用航道不适用本法。专用航道由专用部门管理。"},{"i":48,"n":"第四十八条","txt":"本法自2015年3月1日起施行。"}],"chuanbodunshuifa":[{"i":1,"n":"第一条","txt":"自中华人民共和国境外港口进入境内港口的船舶（以下称应税船舶），应当依照本法缴纳船舶吨税（以下简称吨税）。"},{"i":2,"n":"第二条","txt":"吨税的税目、税率依照本法所附的《吨税税目税率表》执行。"},{"i":3,"n":"第三条","txt":"吨税设置优惠税率和普通税率。"},{"i":4,"n":"第四条","txt":"吨税按照船舶净吨位和吨税执照期限征收。"},{"i":5,"n":"第五条","txt":"吨税的应纳税额按照船舶净吨位乘以适用税率计算。"},{"i":6,"n":"第六条","txt":"吨税由海关负责征收。海关征收吨税应当制发缴款凭证。"},{"i":7,"n":"第七条","txt":"应税船舶在进入港口办理入境手续时，应当向海关申报纳税领取吨税执照，或者交验吨税执照（或者申请核验吨税执照电子信息）。应税船舶在离开港口办理出境手续时，应当交验吨税执照（或者申请核验吨税执照电子信息）。"},{"i":8,"n":"第八条","txt":"吨税纳税义务发生时间为应税船舶进入港口的当日。"},{"i":9,"n":"第九条","txt":"下列船舶免征吨税："},{"i":10,"n":"第十条","txt":"在吨税执照期限内，应税船舶发生下列情形之一的，海关按照实际发生的天数批注延长吨税执照期限："},{"i":11,"n":"第十一条","txt":"符合本法第九条第一款第五项至第九项、第十条规定的船舶，应当提供海事部门、渔业船舶管理部门等部门、机构出具的具有法律效力的证明文件或者使用关系证明文件，申明免税或者延长吨税执照期限的依据和理由。"},{"i":12,"n":"第十二条","txt":"应税船舶负责人应当自海关填发吨税缴款凭证之日起十五日内缴清税款。未按期缴清税款的，自滞纳税款之日起至缴清税款之日止，按日加收滞纳税款万分之五的税款滞纳金。"},{"i":13,"n":"第十三条","txt":"应税船舶到达港口前，经海关核准先行申报并办结出入境手续的，应税船舶负责人应当向海关提供与其依法履行吨税缴纳义务相适应的担保；应税船舶到达港口后，依照本法规定向海关申报纳税。"},{"i":14,"n":"第十四条","txt":"应税船舶在吨税执照期限内，因修理、改造导致净吨位变化的，吨税执照继续有效。应税船舶办理出入境手续时，应当提供船舶经过修理、改造的证明文件。"},{"i":15,"n":"第十五条","txt":"应税船舶在吨税执照期限内，因税目税率调整或者船籍改变而导致适用税率变化的，吨税执照继续有效。"},{"i":16,"n":"第十六条","txt":"吨税执照在期满前毁损或者遗失的，应当向原发照海关书面申请核发吨税执照副本，不再补税。"},{"i":17,"n":"第十七条","txt":"海关发现少征或者漏征税款的，应当自应税船舶应当缴纳税款之日起一年内，补征税款。但因应税船舶违反规定造成少征或者漏征税款的，海关可以自应当缴纳税款之日起三年内追征税款，并自应当缴纳税款之日起按日加征少征或者漏征税款万分之五的税款滞纳金。"},{"i":18,"n":"第十八条","txt":"应税船舶有下列行为之一的，由海关责令限期改正，处二千元以上三万元以下的罚款；不缴或者少缴应纳税款的，处不缴或者少缴税款百分之五十以上五倍以下的罚款，但罚款不得低于二千元："},{"i":19,"n":"第十九条","txt":"吨税税款、税款滞纳金、罚款以人民币计算。"},{"i":20,"n":"第二十条","txt":"吨税的征收，本法未作规定的，依照有关税收征收管理的法律、行政法规的规定执行。"},{"i":21,"n":"第二十一条","txt":"本法及所附《吨税税目税率表》下列用语的含义："},{"i":22,"n":"第二十二条","txt":"本法自2018年7月1日起施行。2011年12月5日国务院公布的《中华人民共和国船舶吨税暂行条例》同时废止。"}],"jiliangfa":[{"i":1,"n":"第一条","txt":"为了加强计量监督管理，保障国家计量单位制的统一和量值的准确可靠，有利于生产、贸易和科学技术的发展，适应社会主义现代化建设的需要，维护国家、人民的利益，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内，建立计量基准器具、计量标准器具，进行计量检定，制造、修理、销售、使用计量器具，必须遵守本法。"},{"i":3,"n":"第三条","txt":"国家实行法定计量单位制度。"},{"i":4,"n":"第四条","txt":"国务院计量行政部门对全国计量工作实施统一监督管理。"},{"i":5,"n":"第五条","txt":"国务院计量行政部门负责建立各种计量基准器具，作为统一全国量值的最高依据。"},{"i":6,"n":"第六条","txt":"县级以上地方人民政府计量行政部门根据本地区的需要，建立社会公用计量标准器具，经上级人民政府计量行政部门主持考核合格后使用。"},{"i":7,"n":"第七条","txt":"国务院有关主管部门和省、自治区、直辖市人民政府有关主管部门，根据本部门的特殊需要，可以建立本部门使用的计量标准器具，其各项最高计量标准器具经同级人民政府计量行政部门主持考核合格后使用。"},{"i":8,"n":"第八条","txt":"企业、事业单位根据需要，可以建立本单位使用的计量标准器具，其各项最高计量标准器具经有关人民政府计量行政部门主持考核合格后使用。"},{"i":9,"n":"第九条","txt":"县级以上人民政府计量行政部门对社会公用计量标准器具，部门和企业、事业单位使用的最高计量标准器具，以及用于贸易结算、安全防护、医疗卫生、环境监测方面的列入强制检定目录的工作计量器具，实行强制检定。未按照规定申请检定或者检定不合格的，不得使用。实行强制检定的工作计量器具的目录和管理办法，由国务院制定。"},{"i":10,"n":"第十条","txt":"计量检定必须按照国家计量检定系统表进行。国家计量检定系统表由国务院计量行政部门制定。"},{"i":11,"n":"第十一条","txt":"计量检定工作应当按照经济合理的原则，就地就近进行。"},{"i":12,"n":"第十二条","txt":"制造、修理计量器具的企业、事业单位，必须具有与所制造、修理的计量器具相适应的设施、人员和检定仪器设备。"},{"i":13,"n":"第十三条","txt":"制造计量器具的企业、事业单位生产本单位未生产过的计量器具新产品，必须经省级以上人民政府计量行政部门对其样品的计量性能考核合格，方可投入生产。"},{"i":14,"n":"第十四条","txt":"任何单位和个人不得违反规定制造、销售和进口非法定计量单位的计量器具。"},{"i":15,"n":"第十五条","txt":"制造、修理计量器具的企业、事业单位必须对制造、修理的计量器具进行检定，保证产品计量性能合格，并对合格产品出具产品合格证。"},{"i":16,"n":"第十六条","txt":"使用计量器具不得破坏其准确度，损害国家和消费者的利益。"},{"i":17,"n":"第十七条","txt":"个体工商户可以制造、修理简易的计量器具。"},{"i":18,"n":"第十八条","txt":"县级以上人民政府计量行政部门应当依法对制造、修理、销售、进口和使用计量器具，以及计量检定等相关计量活动进行监督检查。有关单位和个人不得拒绝、阻挠。"},{"i":19,"n":"第十九条","txt":"县级以上人民政府计量行政部门，根据需要设置计量监督员。计量监督员管理办法，由国务院计量行政部门制定。"},{"i":20,"n":"第二十条","txt":"县级以上人民政府计量行政部门可以根据需要设置计量检定机构，或者授权其他单位的计量检定机构，执行强制检定和其他检定、测试任务。"},{"i":21,"n":"第二十一条","txt":"处理因计量器具准确度所引起的纠纷，以国家计量基准器具或者社会公用计量标准器具检定的数据为准。"},{"i":22,"n":"第二十二条","txt":"为社会提供公证数据的产品质量检验机构，必须经省级以上人民政府计量行政部门对其计量检定、测试的能力和可靠性考核合格。"},{"i":23,"n":"第二十三条","txt":"制造、销售未经考核合格的计量器具新产品的，责令停止制造、销售该种新产品，没收违法所得，可以并处罚款。"},{"i":24,"n":"第二十四条","txt":"制造、修理、销售的计量器具不合格的，没收违法所得，可以并处罚款。"},{"i":25,"n":"第二十五条","txt":"属于强制检定范围的计量器具，未按照规定申请检定或者检定不合格继续使用的，责令停止使用，可以并处罚款。"},{"i":26,"n":"第二十六条","txt":"使用不合格的计量器具或者破坏计量器具准确度，给国家和消费者造成损失的，责令赔偿损失，没收计量器具和违法所得，可以并处罚款。"},{"i":27,"n":"第二十七条","txt":"制造、销售、使用以欺骗消费者为目的的计量器具的，没收计量器具和违法所得，处以罚款；情节严重的，并对个人或者单位直接责任人员依照刑法有关规定追究刑事责任。"},{"i":28,"n":"第二十八条","txt":"违反本法规定，制造、修理、销售的计量器具不合格，造成人身伤亡或者重大财产损失的，依照刑法有关规定，对个人或者单位直接责任人员追究刑事责任。"},{"i":29,"n":"第二十九条","txt":"计量监督人员违法失职，情节严重的，依照刑法有关规定追究刑事责任；情节轻微的，给予行政处分。"},{"i":30,"n":"第三十条","txt":"本法规定的行政处罚，由县级以上地方人民政府计量行政部门决定。"},{"i":31,"n":"第三十一条","txt":"当事人对行政处罚决定不服的，可以在接到处罚通知之日起十五日内向人民法院起诉；对罚款、没收违法所得的行政处罚决定期满不起诉又不履行的，由作出行政处罚决定的机关申请人民法院强制执行。"},{"i":32,"n":"第三十二条","txt":"中国人民解放军和国防科技工业系统计量工作的监督管理办法，由国务院、中央军事委员会依据本法另行制定。"},{"i":33,"n":"第三十三条","txt":"国务院计量行政部门根据本法制定实施细则，报国务院批准施行。"},{"i":34,"n":"第三十四条","txt":"本法自1986年7月1日起施行。"}],"zichanpinggufa":[{"i":1,"n":"第一条","txt":"为了规范资产评估行为，保护资产评估当事人合法权益和公共利益，促进资产评估行业健康发展，维护社会主义市场经济秩序，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称资产评估（以下称评估），是指评估机构及其评估专业人员根据委托对不动产、动产、无形资产、企业价值、资产损失或者其他经济权益进行评定、估算，并出具评估报告的专业服务行为。"},{"i":3,"n":"第三条","txt":"自然人、法人或者其他组织需要确定评估对象价值的，可以自愿委托评估机构评估。"},{"i":4,"n":"第四条","txt":"评估机构及其评估专业人员开展业务应当遵守法律、行政法规和评估准则，遵循独立、客观、公正的原则。"},{"i":5,"n":"第五条","txt":"评估专业人员从事评估业务，应当加入评估机构，并且只能在一个评估机构从事业务。"},{"i":6,"n":"第六条","txt":"评估行业可以按照专业领域依法设立行业协会，实行自律管理，并接受有关评估行政管理部门的监督和社会监督。"},{"i":7,"n":"第七条","txt":"国务院有关评估行政管理部门按照各自职责分工，对评估行业进行监督管理。"},{"i":8,"n":"第八条","txt":"评估专业人员包括评估师和其他具有评估专业知识及实践经验的评估从业人员。"},{"i":9,"n":"第九条","txt":"有关全国性评估行业协会按照国家规定组织实施评估师资格全国统一考试。"},{"i":10,"n":"第十条","txt":"有关全国性评估行业协会应当在其网站上公布评估师名单，并实时更新。"},{"i":11,"n":"第十一条","txt":"因故意犯罪或者在从事评估、财务、会计、审计活动中因过失犯罪而受刑事处罚，自刑罚执行完毕之日起不满五年的人员，不得从事评估业务。"},{"i":12,"n":"第十二条","txt":"评估专业人员享有下列权利："},{"i":13,"n":"第十三条","txt":"评估专业人员应当履行下列义务："},{"i":14,"n":"第十四条","txt":"评估专业人员不得有下列行为："},{"i":15,"n":"第十五条","txt":"评估机构应当依法采用合伙或者公司形式，聘用评估专业人员开展评估业务。"},{"i":16,"n":"第十六条","txt":"设立评估机构，应当向工商行政管理部门申请办理登记。评估机构应当自领取营业执照之日起三十日内向有关评估行政管理部门备案。评估行政管理部门应当及时将评估机构备案情况向社会公告。"},{"i":17,"n":"第十七条","txt":"评估机构应当依法独立、客观、公正开展业务，建立健全质量控制制度，保证评估报告的客观、真实、合理。"},{"i":18,"n":"第十八条","txt":"委托人拒绝提供或者不如实提供执行评估业务所需的权属证明、财务会计信息和其他资料的，评估机构有权依法拒绝其履行合同的要求。"},{"i":19,"n":"第十九条","txt":"委托人要求出具虚假评估报告或者有其他非法干预评估结果情形的，评估机构有权解除合同。"},{"i":20,"n":"第二十条","txt":"评估机构不得有下列行为："},{"i":21,"n":"第二十一条","txt":"评估机构根据业务需要建立职业风险基金，或者自愿办理职业责任保险，完善风险防范机制。"},{"i":22,"n":"第二十二条","txt":"委托人有权自主选择符合本法规定的评估机构，任何组织或者个人不得非法限制或者干预。"},{"i":23,"n":"第二十三条","txt":"委托人应当与评估机构订立委托合同，约定双方的权利和义务。"},{"i":24,"n":"第二十四条","txt":"对受理的评估业务，评估机构应当指定至少两名评估专业人员承办。"},{"i":25,"n":"第二十五条","txt":"评估专业人员应当根据评估业务具体情况，对评估对象进行现场调查，收集权属证明、财务会计信息和其他资料并进行核查验证、分析整理，作为评估的依据。"},{"i":26,"n":"第二十六条","txt":"评估专业人员应当恰当选择评估方法，除依据评估执业准则只能选择一种评估方法的外，应当选择两种以上评估方法，经综合分析，形成评估结论，编制评估报告。"},{"i":27,"n":"第二十七条","txt":"评估报告应当由至少两名承办该项业务的评估专业人员签名并加盖评估机构印章。"},{"i":28,"n":"第二十八条","txt":"评估机构开展法定评估业务，应当指定至少两名相应专业类别的评估师承办，评估报告应当由至少两名承办该项业务的评估师签名并加盖评估机构印章。"},{"i":29,"n":"第二十九条","txt":"评估档案的保存期限不少于十五年，属于法定评估业务的，保存期限不少于三十年。"},{"i":30,"n":"第三十条","txt":"委托人对评估报告有异议的，可以要求评估机构解释。"},{"i":31,"n":"第三十一条","txt":"委托人认为评估机构或者评估专业人员违法开展业务的，可以向有关评估行政管理部门或者行业协会投诉、举报，有关评估行政管理部门或者行业协会应当及时调查处理，并答复委托人。"},{"i":32,"n":"第三十二条","txt":"委托人或者评估报告使用人应当按照法律规定和评估报告载明的使用范围使用评估报告。"},{"i":33,"n":"第三十三条","txt":"评估行业协会是评估机构和评估专业人员的自律性组织，依照法律、行政法规和章程实行自律管理。"},{"i":34,"n":"第三十四条","txt":"评估行业协会的章程由会员代表大会制定，报登记管理机关核准，并报有关评估行政管理部门备案。"},{"i":35,"n":"第三十五条","txt":"评估机构、评估专业人员加入有关评估行业协会，平等享有章程规定的权利，履行章程规定的义务。有关评估行业协会公布加入本协会的评估机构、评估专业人员名单。"},{"i":36,"n":"第三十六条","txt":"评估行业协会履行下列职责："},{"i":37,"n":"第三十七条","txt":"有关评估行业协会应当建立沟通协作和信息共享机制，根据需要制定共同的行为规范，促进评估行业健康有序发展。"},{"i":38,"n":"第三十八条","txt":"评估行业协会收取会员会费的标准，由会员代表大会通过，并向社会公开。不得以会员交纳会费数额作为其在行业协会中担任职务的条件。"},{"i":39,"n":"第三十九条","txt":"国务院有关评估行政管理部门组织制定评估基本准则和评估行业监督管理办法。"},{"i":40,"n":"第四十条","txt":"设区的市级以上人民政府有关评估行政管理部门依据各自职责，负责监督管理评估行业，对评估机构和评估专业人员的违法行为依法实施行政处罚，将处罚情况及时通报有关评估行业协会，并依法向社会公开。"},{"i":41,"n":"第四十一条","txt":"评估行政管理部门对有关评估行业协会实施监督检查，对检查发现的问题和针对协会的投诉、举报，应当及时调查处理。"},{"i":42,"n":"第四十二条","txt":"评估行政管理部门不得违反本法规定，对评估机构依法开展业务进行限制。"},{"i":43,"n":"第四十三条","txt":"评估行政管理部门不得与评估行业协会、评估机构存在人员或者资金关联，不得利用职权为评估机构招揽业务。"},{"i":44,"n":"第四十四条","txt":"评估专业人员违反本法规定，有下列情形之一的，由有关评估行政管理部门予以警告，可以责令停止从业六个月以上一年以下；有违法所得的，没收违法所得；情节严重的，责令停止从业一年以上五年以下；构成犯罪的，依法追究刑事责任："},{"i":45,"n":"第四十五条","txt":"评估专业人员违反本法规定，签署虚假评估报告的，由有关评估行政管理部门责令停止从业两年以上五年以下；有违法所得的，没收违法所得；情节严重的，责令停止从业五年以上十年以下；构成犯罪的，依法追究刑事责任，终身不得从事评估业务。"},{"i":46,"n":"第四十六条","txt":"违反本法规定，未经工商登记以评估机构名义从事评估业务的，由工商行政管理部门责令停止违法活动；有违法所得的，没收违法所得，并处违法所得一倍以上五倍以下罚款。"},{"i":47,"n":"第四十七条","txt":"评估机构违反本法规定，有下列情形之一的，由有关评估行政管理部门予以警告，可以责令停业一个月以上六个月以下；有违法所得的，没收违法所得，并处违法所得一倍以上五倍以下罚款；情节严重的，由工商行政管理部门吊销营业执照；构成犯罪的，依法追究刑事责任："},{"i":48,"n":"第四十八条","txt":"评估机构违反本法规定，出具虚假评估报告的，由有关评估行政管理部门责令停业六个月以上一年以下；有违法所得的，没收违法所得，并处违法所得一倍以上五倍以下罚款；情节严重的，由工商行政管理部门吊销营业执照；构成犯罪的，依法追究刑事责任。"},{"i":49,"n":"第四十九条","txt":"评估机构、评估专业人员在一年内累计三次因违反本法规定受到责令停业、责令停止从业以外处罚的，有关评估行政管理部门可以责令其停业或者停止从业一年以上五年以下。"},{"i":50,"n":"第五十条","txt":"评估专业人员违反本法规定，给委托人或者其他相关当事人造成损失的，由其所在的评估机构依法承担赔偿责任。评估机构履行赔偿责任后，可以向有故意或者重大过失行为的评估专业人员追偿。"},{"i":51,"n":"第五十一条","txt":"违反本法规定，应当委托评估机构进行法定评估而未委托的，由有关部门责令改正；拒不改正的，处十万元以上五十万元以下罚款；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分；造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":52,"n":"第五十二条","txt":"违反本法规定，委托人在法定评估中有下列情形之一的，由有关评估行政管理部门会同有关部门责令改正；拒不改正的，处十万元以上五十万元以下罚款；有违法所得的，没收违法所得；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分；造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任："},{"i":53,"n":"第五十三条","txt":"评估行业协会违反本法规定的，由有关评估行政管理部门给予警告，责令改正；拒不改正的，可以通报登记管理机关，由其依法给予处罚。"},{"i":54,"n":"第五十四条","txt":"有关行政管理部门、评估行业协会工作人员违反本法规定，滥用职权、玩忽职守或者徇私舞弊的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":55,"n":"第五十五条","txt":"本法自2016年12月1日起施行。"}],"ziyuanshuifa":[{"i":1,"n":"第一条","txt":"在中华人民共和国领域和中华人民共和国管辖的其他海域开发应税资源的单位和个人，为资源税的纳税人，应当依照本法规定缴纳资源税。"},{"i":2,"n":"第二条","txt":"资源税的税目、税率，依照《税目税率表》执行。"},{"i":3,"n":"第三条","txt":"资源税按照《税目税率表》实行从价计征或者从量计征。"},{"i":4,"n":"第四条","txt":"纳税人开采或者生产不同税目应税产品的，应当分别核算不同税目应税产品的销售额或者销售数量；未分别核算或者不能准确提供不同税目应税产品的销售额或者销售数量的，从高适用税率。"},{"i":5,"n":"第五条","txt":"纳税人开采或者生产应税产品自用的，应当依照本法规定缴纳资源税；但是，自用于连续生产应税产品的，不缴纳资源税。"},{"i":6,"n":"第六条","txt":"有下列情形之一的，免征资源税："},{"i":7,"n":"第七条","txt":"有下列情形之一的，省、自治区、直辖市可以决定免征或者减征资源税："},{"i":8,"n":"第八条","txt":"纳税人的免税、减税项目，应当单独核算销售额或者销售数量；未单独核算或者不能准确提供销售额或者销售数量的，不予免税或者减税。"},{"i":9,"n":"第九条","txt":"资源税由税务机关依照本法和《中华人民共和国税收征收管理法》的规定征收管理。"},{"i":10,"n":"第十条","txt":"纳税人销售应税产品，纳税义务发生时间为收讫销售款或者取得索取销售款凭据的当日；自用应税产品的，纳税义务发生时间为移送应税产品的当日。"},{"i":11,"n":"第十一条","txt":"纳税人应当向应税产品开采地或者生产地的税务机关申报缴纳资源税。"},{"i":12,"n":"第十二条","txt":"资源税按月或者按季申报缴纳；不能按固定期限计算缴纳的，可以按次申报缴纳。"},{"i":13,"n":"第十三条","txt":"纳税人、税务机关及其工作人员违反本法规定的，依照《中华人民共和国税收征收管理法》和有关法律法规的规定追究法律责任。"},{"i":14,"n":"第十四条","txt":"国务院根据国民经济和社会发展需要，依照本法的原则，对取用地表水或者地下水的单位和个人试点征收水资源税。征收水资源税的，停止征收水资源费。"},{"i":15,"n":"第十五条","txt":"中外合作开采陆上、海上石油资源的企业依法缴纳资源税。"},{"i":16,"n":"第十六条","txt":"本法下列用语的含义是："},{"i":17,"n":"第十七条","txt":"本法自2020年9月1日起施行。1993年12月25日国务院发布的《中华人民共和国资源税暂行条例》同时废止。"}],"chechuanshuifa":[{"i":1,"n":"第一条","txt":"在中华人民共和国境内属于本法所附《车船税税目税额表》规定的车辆、船舶（以下简称车船）的所有人或者管理人，为车船税的纳税人，应当依照本法缴纳车船税。"},{"i":2,"n":"第二条","txt":"车船的适用税额依照本法所附《车船税税目税额表》执行。"},{"i":3,"n":"第三条","txt":"下列车船免征车船税："},{"i":4,"n":"第四条","txt":"对节约能源、使用新能源的车船可以减征或者免征车船税；对受严重自然灾害影响纳税困难以及有其他特殊原因确需减税、免税的，可以减征或者免征车船税。具体办法由国务院规定，并报全国人民代表大会常务委员会备案。"},{"i":5,"n":"第五条","txt":"省、自治区、直辖市人民政府根据当地实际情况，可以对公共交通车船，农村居民拥有并主要在农村地区使用的摩托车、三轮汽车和低速载货汽车定期减征或者免征车船税。"},{"i":6,"n":"第六条","txt":"从事机动车第三者责任强制保险业务的保险机构为机动车车船税的扣缴义务人，应当在收取保险费时依法代收车船税，并出具代收税款凭证。"},{"i":7,"n":"第七条","txt":"车船税的纳税地点为车船的登记地或者车船税扣缴义务人所在地。依法不需要办理登记的车船，车船税的纳税地点为车船的所有人或者管理人所在地。"},{"i":8,"n":"第八条","txt":"车船税纳税义务发生时间为取得车船所有权或者管理权的当月。"},{"i":9,"n":"第九条","txt":"车船税按年申报缴纳。具体申报纳税期限由省、自治区、直辖市人民政府规定。"},{"i":10,"n":"第十条","txt":"公安、交通运输、农业、渔业等车船登记管理部门、船舶检验机构和车船税扣缴义务人的行业主管部门应当在提供车船有关信息等方面，协助税务机关加强车船税的征收管理。"},{"i":11,"n":"第十一条","txt":"车船税的征收管理，依照本法和《中华人民共和国税收征收管理法》的规定执行。"},{"i":12,"n":"第十二条","txt":"国务院根据本法制定实施条例。"},{"i":13,"n":"第十三条","txt":"本法自2012年1月1日起施行。2006年12月29日国务院公布的《中华人民共和国车船税暂行条例》同时废止。"}],"chelianggouzhishuifa":[{"i":1,"n":"第一条","txt":"在中华人民共和国境内购置汽车、有轨电车、汽车挂车、排气量超过一百五十毫升的摩托车（以下统称应税车辆）的单位和个人，为车辆购置税的纳税人，应当依照本法规定缴纳车辆购置税。"},{"i":2,"n":"第二条","txt":"本法所称购置，是指以购买、进口、自产、受赠、获奖或者其他方式取得并自用应税车辆的行为。"},{"i":3,"n":"第三条","txt":"车辆购置税实行一次性征收。购置已征车辆购置税的车辆，不再征收车辆购置税。"},{"i":4,"n":"第四条","txt":"车辆购置税的税率为百分之十。"},{"i":5,"n":"第五条","txt":"车辆购置税的应纳税额按照应税车辆的计税价格乘以税率计算。"},{"i":6,"n":"第六条","txt":"应税车辆的计税价格，按照下列规定确定："},{"i":7,"n":"第七条","txt":"纳税人申报的应税车辆计税价格明显偏低，又无正当理由的，由税务机关依照《中华人民共和国税收征收管理法》的规定核定其应纳税额。"},{"i":8,"n":"第八条","txt":"纳税人以外汇结算应税车辆价款的，按照申报纳税之日的人民币汇率中间价折合成人民币计算缴纳税款。"},{"i":9,"n":"第九条","txt":"下列车辆免征车辆购置税："},{"i":10,"n":"第十条","txt":"车辆购置税由税务机关负责征收。"},{"i":11,"n":"第十一条","txt":"纳税人购置应税车辆，应当向车辆登记地的主管税务机关申报缴纳车辆购置税；购置不需要办理车辆登记的应税车辆的，应当向纳税人所在地的主管税务机关申报缴纳车辆购置税。"},{"i":12,"n":"第十二条","txt":"车辆购置税的纳税义务发生时间为纳税人购置应税车辆的当日。纳税人应当自纳税义务发生之日起六十日内申报缴纳车辆购置税。"},{"i":13,"n":"第十三条","txt":"纳税人应当在向公安机关交通管理部门办理车辆注册登记前，缴纳车辆购置税。"},{"i":14,"n":"第十四条","txt":"免税、减税车辆因转让、改变用途等原因不再属于免税、减税范围的，纳税人应当在办理车辆转移登记或者变更登记前缴纳车辆购置税。计税价格以免税、减税车辆初次办理纳税申报时确定的计税价格为基准，每满一年扣减百分之十。"},{"i":15,"n":"第十五条","txt":"纳税人将已征车辆购置税的车辆退回车辆生产企业或者销售企业的，可以向主管税务机关申请退还车辆购置税。退税额以已缴税款为基准，自缴纳税款之日至申请退税之日，每满一年扣减百分之十。"},{"i":16,"n":"第十六条","txt":"税务机关和公安、商务、海关、工业和信息化等部门应当建立应税车辆信息共享和工作配合机制，及时交换应税车辆和纳税信息资料。"},{"i":17,"n":"第十七条","txt":"车辆购置税的征收管理，依照本法和《中华人民共和国税收征收管理法》的规定执行。"},{"i":18,"n":"第十八条","txt":"纳税人、税务机关及其工作人员违反本法规定的，依照《中华人民共和国税收征收管理法》和有关法律法规的规定追究法律责任。"},{"i":19,"n":"第十九条","txt":"本法自2019年7月1日起施行。2000年10月22日国务院公布的《中华人民共和国车辆购置税暂行条例》同时废止。"}],"jinchukoushangpinjianyanfa":[{"i":1,"n":"第一条","txt":"为了加强进出口商品检验工作，规范进出口商品检验行为，维护社会公共利益和进出口贸易有关各方的合法权益，促进对外经济贸易关系的顺利发展，制定本法。"},{"i":2,"n":"第二条","txt":"国务院设立进出口商品检验部门（以下简称国家商检部门），主管全国进出口商品检验工作。国家商检部门设在各地的进出口商品检验机构（以下简称商检机构）管理所辖地区的进出口商品检验工作。"},{"i":3,"n":"第三条","txt":"商检机构和依法设立的检验机构（以下称其他检验机构），依法对进出口商品实施检验。"},{"i":4,"n":"第四条","txt":"进出口商品检验应当根据保护人类健康和安全、保护动物或者植物的生命和健康、保护环境、防止欺诈行为、维护国家安全的原则，由国家商检部门制定、调整必须实施检验的进出口商品目录（以下简称目录）并公布实施。"},{"i":5,"n":"第五条","txt":"列入目录的进出口商品，由商检机构实施检验。"},{"i":6,"n":"第六条","txt":"必须实施的进出口商品检验，是指确定列入目录的进出口商品是否符合国家技术规范的强制性要求的合格评定活动。"},{"i":7,"n":"第七条","txt":"列入目录的进出口商品，按照国家技术规范的强制性要求进行检验；尚未制定国家技术规范的强制性要求的，应当依法及时制定，未制定之前，可以参照国家商检部门指定的国外有关标准进行检验。"},{"i":8,"n":"第八条","txt":"其他检验机构可以接受对外贸易关系人或者外国检验机构的委托，办理进出口商品检验鉴定业务。"},{"i":9,"n":"第九条","txt":"法律、行政法规规定由其他检验机构实施检验的进出口商品或者检验项目，依照有关法律、行政法规的规定办理。"},{"i":10,"n":"第十条","txt":"国家商检部门和商检机构应当及时收集和向有关方面提供进出口商品检验方面的信息。"},{"i":11,"n":"第十一条","txt":"本法规定必须经商检机构检验的进口商品的收货人或者其代理人，应当向报关地的商检机构报检。"},{"i":12,"n":"第十二条","txt":"本法规定必须经商检机构检验的进口商品的收货人或者其代理人，应当在商检机构规定的地点和期限内，接受商检机构对进口商品的检验。商检机构应当在国家商检部门统一规定的期限内检验完毕，并出具检验证单。"},{"i":13,"n":"第十三条","txt":"本法规定必须经商检机构检验的进口商品以外的进口商品的收货人，发现进口商品质量不合格或者残损短缺，需要由商检机构出证索赔的，应当向商检机构申请检验出证。"},{"i":14,"n":"第十四条","txt":"对重要的进口商品和大型的成套设备，收货人应当依据对外贸易合同约定在出口国装运前进行预检验、监造或者监装，主管部门应当加强监督；商检机构根据需要可以派出检验人员参加。"},{"i":15,"n":"第十五条","txt":"本法规定必须经商检机构检验的出口商品的发货人或者其代理人，应当在商检机构规定的地点和期限内，向商检机构报检。商检机构应当在国家商检部门统一规定的期限内检验完毕，并出具检验证单。"},{"i":16,"n":"第十六条","txt":"经商检机构检验合格发给检验证单的出口商品，应当在商检机构规定的期限内报关出口；超过期限的，应当重新报检。"},{"i":17,"n":"第十七条","txt":"为出口危险货物生产包装容器的企业，必须申请商检机构进行包装容器的性能鉴定。生产出口危险货物的企业，必须申请商检机构进行包装容器的使用鉴定。使用未经鉴定合格的包装容器的危险货物，不准出口。"},{"i":18,"n":"第十八条","txt":"对装运出口易腐烂变质食品的船舱和集装箱，承运人或者装箱单位必须在装货前申请检验。未经检验合格的，不准装运。"},{"i":19,"n":"第十九条","txt":"商检机构对本法规定必须经商检机构检验的进出口商品以外的进出口商品，根据国家规定实施抽查检验。"},{"i":20,"n":"第二十条","txt":"商检机构根据便利对外贸易的需要，可以按照国家规定对列入目录的出口商品进行出厂前的质量监督管理和检验。"},{"i":21,"n":"第二十一条","txt":"为进出口货物的收发货人办理报检手续的代理人办理报检手续时应当向商检机构提交授权委托书。"},{"i":22,"n":"第二十二条","txt":"国家商检部门和商检机构依法对其他检验机构的进出口商品检验鉴定业务活动进行监督，可以对其检验的商品抽查检验。"},{"i":23,"n":"第二十三条","txt":"国务院认证认可监督管理部门根据国家统一的认证制度，对有关的进出口商品实施认证管理。"},{"i":24,"n":"第二十四条","txt":"认证机构可以根据国务院认证认可监督管理部门同外国有关机构签订的协议或者接受外国有关机构的委托进行进出口商品质量认证工作，准许在认证合格的进出口商品上使用质量认证标志。"},{"i":25,"n":"第二十五条","txt":"商检机构依照本法对实施许可制度的进出口商品实行验证管理，查验单证，核对证货是否相符。"},{"i":26,"n":"第二十六条","txt":"商检机构根据需要，对检验合格的进出口商品，可以加施商检标志或者封识。"},{"i":27,"n":"第二十七条","txt":"进出口商品的报检人对商检机构作出的检验结果有异议的，可以向原商检机构或者其上级商检机构以至国家商检部门申请复验，由受理复验的商检机构或者国家商检部门及时作出复验结论。"},{"i":28,"n":"第二十八条","txt":"当事人对商检机构、国家商检部门作出的复验结论不服或者对商检机构作出的处罚决定不服的，可以依法申请行政复议，也可以依法向人民法院提起诉讼。"},{"i":29,"n":"第二十九条","txt":"国家商检部门和商检机构履行职责，必须遵守法律，维护国家利益，依照法定职权和法定程序严格执法，接受监督。"},{"i":30,"n":"第三十条","txt":"国家商检部门和商检机构应当建立健全内部监督制度，对其工作人员的执法活动进行监督检查。"},{"i":31,"n":"第三十一条","txt":"任何单位和个人均有权对国家商检部门、商检机构及其工作人员的违法、违纪行为进行控告、检举。收到控告、检举的机关应当依法按照职责分工及时查处，并为控告人、检举人保密。"},{"i":32,"n":"第三十二条","txt":"违反本法规定，将必须经商检机构检验的进口商品未报经检验而擅自销售或者使用的，或者将必须经商检机构检验的出口商品未报经检验合格而擅自出口的，由商检机构没收违法所得，并处货值金额百分之五以上百分之二十以下的罚款；构成犯罪的，依法追究刑事责任。"},{"i":33,"n":"第三十三条","txt":"进口或者出口属于掺杂掺假、以假充真、以次充好的商品或者以不合格进出口商品冒充合格进出口商品的，由商检机构责令停止进口或者出口，没收违法所得，并处货值金额百分之五十以上三倍以下的罚款；构成犯罪的，依法追究刑事责任。"},{"i":34,"n":"第三十四条","txt":"伪造、变造、买卖或者盗窃商检单证、印章、标志、封识、质量认证标志的，依法追究刑事责任；尚不够刑事处罚的，由商检机构、认证认可监督管理部门依据各自职责责令改正，没收违法所得，并处货值金额等值以下的罚款。"},{"i":35,"n":"第三十五条","txt":"国家商检部门、商检机构的工作人员违反本法规定，泄露所知悉的商业秘密的，依法给予行政处分，有违法所得的，没收违法所得；构成犯罪的，依法追究刑事责任。"},{"i":36,"n":"第三十六条","txt":"国家商检部门、商检机构的工作人员滥用职权，故意刁难的，徇私舞弊，伪造检验结果的，或者玩忽职守，延误检验出证的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":37,"n":"第三十七条","txt":"商检机构和其他检验机构依照本法的规定实施检验和办理检验鉴定业务，依照国家有关规定收取费用。"},{"i":38,"n":"第三十八条","txt":"国务院根据本法制定实施条例。"},{"i":39,"n":"第三十九条","txt":"本法自1989年8月1日起施行。"}],"jinchujingdongzhiwujianyifa":[{"i":1,"n":"第一条","txt":"为防止动物传染病、寄生虫病和植物危险性病、虫、杂草以及其他有害生物（以下简称病虫害）传入、传出国境，保护农、林、牧、渔业生产和人体健康，促进对外经济贸易的发展，制定本法。"},{"i":2,"n":"第二条","txt":"进出境的动植物、动植物产品和其他检疫物，装载动植物、动植物产品和其他检疫物的装载容器、包装物，以及来自动植物疫区的运输工具，依照本法规定实施检疫。"},{"i":3,"n":"第三条","txt":"国务院设立动植物检疫机关（以下简称国家动植物检疫机关），统一管理全国进出境动植物检疫工作。国家动植物检疫机关在对外开放的口岸和进出境动植物检疫业务集中的地点设立的口岸动植物检疫机关，依照本法规定实施进出境动植物检疫。"},{"i":4,"n":"第四条","txt":"口岸动植物检疫机关在实施检疫时可以行使下列职权："},{"i":5,"n":"第五条","txt":"国家禁止下列各物进境："},{"i":6,"n":"第六条","txt":"国外发生重大动植物疫情并可能传入中国时，国务院应当采取紧急预防措施，必要时可以下令禁止来自动植物疫区的运输工具进境或者封锁有关口岸；受动植物疫情威胁地区的地方人民政府和有关口岸动植物检疫机关，应当立即采取紧急措施，同时向上级人民政府和国家动植物检疫机关报告。"},{"i":7,"n":"第七条","txt":"国家动植物检疫机关和口岸动植物检疫机关对进出境动植物、动植物产品的生产、加工、存放过程，实行检疫监督制度。"},{"i":8,"n":"第八条","txt":"口岸动植物检疫机关在港口、机场、车站、邮局执行检疫任务时，海关、交通、民航、铁路、邮电等有关部门应当配合。"},{"i":9,"n":"第九条","txt":"动植物检疫机关检疫人员必须忠于职守，秉公执法。"},{"i":10,"n":"第十条","txt":"输入动物、动物产品、植物种子、种苗及其他繁殖材料的，必须事先提出申请，办理检疫审批手续。"},{"i":11,"n":"第十一条","txt":"通过贸易、科技合作、交换、赠送、援助等方式输入动植物、动植物产品和其他检疫物的，应当在合同或者协议中订明中国法定的检疫要求，并订明必须附有输出国家或者地区政府动植物检疫机关出具的检疫证书。"},{"i":12,"n":"第十二条","txt":"货主或者其代理人应当在动植物、动植物产品和其他检疫物进境前或者进境时持输出国家或者地区的检疫证书、贸易合同等单证，向进境口岸动植物检疫机关报检。"},{"i":13,"n":"第十三条","txt":"装载动物的运输工具抵达口岸时，口岸动植物检疫机关应当采取现场预防措施，对上下运输工具或者接近动物的人员、装载动物的运输工具和被污染的场地作防疫消毒处理。"},{"i":14,"n":"第十四条","txt":"输入动植物、动植物产品和其他检疫物，应当在进境口岸实施检疫。未经口岸动植物检疫机关同意，不得卸离运输工具。"},{"i":15,"n":"第十五条","txt":"输入动植物、动植物产品和其他检疫物，经检疫合格的，准予进境；海关凭口岸动植物检疫机关签发的检疫单证或者在报关单上加盖的印章验放。"},{"i":16,"n":"第十六条","txt":"输入动物，经检疫不合格的，由口岸动植物检疫机关签发《检疫处理通知单》，通知货主或者其代理人作如下处理："},{"i":17,"n":"第十七条","txt":"输入植物、植物产品和其他检疫物，经检疫发现有植物危险性病、虫、杂草的，由口岸动植物检疫机关签发《检疫处理通知单》，通知货主或者其代理人作除害、退回或者销毁处理。经除害处理合格的，准予进境。"},{"i":18,"n":"第十八条","txt":"本法第十六条第一款第一项、第二项所称一类、二类动物传染病、寄生虫病的名录和本法第十七条所称植物危险性病、虫、杂草的名录，由国务院农业行政主管部门制定并公布。"},{"i":19,"n":"第十九条","txt":"输入动植物、动植物产品和其他检疫物，经检疫发现有本法第十八条规定的名录之外，对农、林、牧、渔业有严重危害的其他病虫害的，由口岸动植物检疫机关依照国务院农业行政主管部门的规定，通知货主或者其代理人作除害、退回或者销毁处理。经除害处理合格的，准予进境。"},{"i":20,"n":"第二十条","txt":"货主或者其代理人在动植物、动植物产品和其他检疫物出境前，向口岸动植物检疫机关报检。"},{"i":21,"n":"第二十一条","txt":"输出动植物、动植物产品和其他检疫物，由口岸动植物检疫机关实施检疫，经检疫合格或者经除害处理合格的，准予出境；海关凭口岸动植物检疫机关签发的检疫证书或者在报关单上加盖的印章验放。检疫不合格又无有效方法作除害处理的，不准出境。"},{"i":22,"n":"第二十二条","txt":"经检疫合格的动植物、动植物产品和其他检疫物，有下列情形之一的，货主或者其代理人应当重新报检："},{"i":23,"n":"第二十三条","txt":"要求运输动物过境的，必须事先商得中国国家动植物检疫机关同意，并按照指定的口岸和路线过境。"},{"i":24,"n":"第二十四条","txt":"运输动植物、动植物产品和其他检疫物过境的，由承运人或者押运人持货运单和输出国家或者地区政府动植物检疫机关出具的检疫证书，在进境时向口岸动植物检疫机关报检，出境口岸不再检疫。"},{"i":25,"n":"第二十五条","txt":"过境的动物经检疫合格的，准予过境；发现有本法第十八条规定的名录所列的动物传染病、寄生虫病的，全群动物不准过境。"},{"i":26,"n":"第二十六条","txt":"对过境植物、动植物产品和其他检疫物，口岸动植物检疫机关检查运输工具或者包装，经检疫合格的，准予过境；发现有本法第十八条规定的名录所列的病虫害的，作除害处理或者不准过境。"},{"i":27,"n":"第二十七条","txt":"动植物、动植物产品和其他检疫物过境期间，未经动植物检疫机关批准，不得开拆包装或者卸离运输工具。"},{"i":28,"n":"第二十八条","txt":"携带、邮寄植物种子、种苗及其他繁殖材料进境的，必须事先提出申请，办理检疫审批手续。"},{"i":29,"n":"第二十九条","txt":"禁止携带、邮寄进境的动植物、动植物产品和其他检疫物的名录，由国务院农业行政主管部门制定并公布。"},{"i":30,"n":"第三十条","txt":"携带本法第二十九条规定的名录以外的动植物、动植物产品和其他检疫物进境的，在进境时向海关申报并接受口岸动植物检疫机关检疫。"},{"i":31,"n":"第三十一条","txt":"邮寄本法第二十九条规定的名录以外的动植物、动植物产品和其他检疫物进境的，由口岸动植物检疫机关在国际邮件互换局实施检疫，必要时可以取回口岸动植物检疫机关检疫；未经检疫不得运递。"},{"i":32,"n":"第三十二条","txt":"邮寄进境的动植物、动植物产品和其他检疫物，经检疫或者除害处理合格后放行；经检疫不合格又无有效方法作除害处理的，作退回或者销毁处理，并签发《检疫处理通知单》。"},{"i":33,"n":"第三十三条","txt":"携带、邮寄出境的动植物、动植物产品和其他检疫物，物主有检疫要求的，由口岸动植物检疫机关实施检疫。"},{"i":34,"n":"第三十四条","txt":"来自动植物疫区的船舶、飞机、火车抵达口岸时，由口岸动植物检疫机关实施检疫。发现有本法第十八条规定的名录所列的病虫害的，作不准带离运输工具、除害、封存或者销毁处理。"},{"i":35,"n":"第三十五条","txt":"进境的车辆，由口岸动植物检疫机关作防疫消毒处理。"},{"i":36,"n":"第三十六条","txt":"进出境运输工具上的泔水、动植物性废弃物，依照口岸动植物检疫机关的规定处理，不得擅自抛弃。"},{"i":37,"n":"第三十七条","txt":"装载出境的动植物、动植物产品和其他检疫物的运输工具，应当符合动植物检疫和防疫的规定。"},{"i":38,"n":"第三十八条","txt":"进境供拆船用的废旧船舶，由口岸动植物检疫机关实施检疫，发现有本法第十八条规定的名录所列的病虫害的，作除害处理。"},{"i":39,"n":"第三十九条","txt":"违反本法规定，有下列行为之一的，由口岸动植物检疫机关处以罚款："},{"i":40,"n":"第四十条","txt":"报检的动植物、动植物产品或者其他检疫物与实际不符的，由口岸动植物检疫机关处以罚款；已取得检疫单证的，予以吊销。"},{"i":41,"n":"第四十一条","txt":"违反本法规定，擅自开拆过境动植物、动植物产品或者其他检疫物的包装的，擅自将过境动植物、动植物产品或者其他检疫物卸离运输工具的，擅自抛弃过境动物的尸体、排泄物、铺垫材料或者其他废弃物的，由动植物检疫机关处以罚款。"},{"i":42,"n":"第四十二条","txt":"违反本法规定，引起重大动植物疫情的，依照刑法有关规定追究刑事责任。"},{"i":43,"n":"第四十三条","txt":"伪造、变造检疫单证、印章、标志、封识，依照刑法有关规定追究刑事责任。"},{"i":44,"n":"第四十四条","txt":"当事人对动植物检疫机关的处罚决定不服的，可以在接到处罚通知之日起十五日内向作出处罚决定的机关的上一级机关申请复议；当事人也可以在接到处罚通知之日起十五日内直接向人民法院起诉。"},{"i":45,"n":"第四十五条","txt":"动植物检疫机关检疫人员滥用职权，徇私舞弊，伪造检疫结果，或者玩忽职守，延误检疫出证，构成犯罪的，依法追究刑事责任；不构成犯罪的，给予行政处分。"},{"i":46,"n":"第四十六条","txt":"本法下列用语的含义是："},{"i":47,"n":"第四十七条","txt":"中华人民共和国缔结或者参加的有关动植物检疫的国际条约与本法有不同规定的，适用该国际条约的规定。但是，中华人民共和国声明保留的条款除外。"},{"i":48,"n":"第四十八条","txt":"口岸动植物检疫机关实施检疫依照规定收费。收费办法由国务院农业行政主管部门会同国务院物价等有关主管部门制定。"},{"i":49,"n":"第四十九条","txt":"国务院根据本法制定实施条例。"},{"i":50,"n":"第五十条","txt":"本法自1992年4月1日起施行。1982年6月4日国务院发布的《中华人民共和国进出口动植物检疫条例》同时废止。"}],"youzhengfa":[{"i":1,"n":"第一条","txt":"为了保障邮政普遍服务，加强对邮政市场的监督管理，维护邮政通信与信息安全，保护通信自由和通信秘密，保护用户合法权益，促进邮政业健康发展，适应经济社会发展和人民生活需要，制定本法。"},{"i":2,"n":"第二条","txt":"国家保障中华人民共和国境内的邮政普遍服务。"},{"i":3,"n":"第三条","txt":"公民的通信自由和通信秘密受法律保护。除因国家安全或者追查刑事犯罪的需要，由公安机关、国家安全机关或者检察机关依照法律规定的程序对通信进行检查外，任何组织或者个人不得以任何理由侵犯公民的通信自由和通信秘密。"},{"i":4,"n":"第四条","txt":"国务院邮政管理部门负责对全国的邮政普遍服务和邮政市场实施监督管理。"},{"i":5,"n":"第五条","txt":"国务院规定范围内的信件寄递业务，由邮政企业专营。"},{"i":6,"n":"第六条","txt":"邮政企业应当加强服务质量管理，完善安全保障措施，为用户提供迅速、准确、安全、方便的服务。"},{"i":7,"n":"第七条","txt":"邮政管理部门、公安机关、国家安全机关和海关应当相互配合，建立健全安全保障机制，加强对邮政通信与信息安全的监督管理，确保邮政通信与信息安全。"},{"i":8,"n":"第八条","txt":"邮政设施的布局和建设应当满足保障邮政普遍服务的需要。"},{"i":9,"n":"第九条","txt":"邮政设施应当按照国家规定的标准设置。"},{"i":10,"n":"第十条","txt":"机关、企业事业单位应当设置接收邮件的场所。农村地区应当逐步设置村邮站或者其他接收邮件的场所。"},{"i":11,"n":"第十一条","txt":"邮件处理场所的设计和建设，应当符合国家安全机关和海关依法履行职责的要求。"},{"i":12,"n":"第十二条","txt":"征收邮政营业场所或者邮件处理场所的，城乡规划主管部门应当根据保障邮政普遍服务的要求，对邮政营业场所或者邮件处理场所的重新设置作出妥善安排；未作出妥善安排前，不得征收。"},{"i":13,"n":"第十三条","txt":"邮政企业应当对其设置的邮政设施进行经常性维护，保证邮政设施的正常使用。"},{"i":14,"n":"第十四条","txt":"邮政企业经营下列业务："},{"i":15,"n":"第十五条","txt":"邮政企业应当对信件、单件重量不超过五千克的印刷品、单件重量不超过十千克的包裹的寄递以及邮政汇兑提供邮政普遍服务。"},{"i":16,"n":"第十六条","txt":"国家对邮政企业提供邮政普遍服务、特殊服务给予补贴，并加强对补贴资金使用的监督。"},{"i":17,"n":"第十七条","txt":"国家设立邮政普遍服务基金。邮政普遍服务基金征收、使用和监督管理的具体办法由国务院财政部门会同国务院有关部门制定，报国务院批准后公布施行。"},{"i":18,"n":"第十八条","txt":"邮政企业的邮政普遍服务业务与竞争性业务应当分业经营。"},{"i":19,"n":"第十九条","txt":"邮政企业在城市每周的营业时间应当不少于六天，投递邮件每天至少一次；在乡、镇人民政府所在地每周的营业时间应当不少于五天，投递邮件每周至少五次。"},{"i":20,"n":"第二十条","txt":"邮政企业寄递邮件，应当符合国务院邮政管理部门规定的寄递时限和服务规范。"},{"i":21,"n":"第二十一条","txt":"邮政企业应当在其营业场所公示或者以其他方式公布其服务种类、营业时间、资费标准、邮件和汇款的查询及损失赔偿办法以及用户对其服务质量的投诉办法。"},{"i":22,"n":"第二十二条","txt":"邮政企业采用其提供的格式条款确定与用户的权利义务的，该格式条款适用《中华人民共和国合同法》关于合同格式条款的规定。"},{"i":23,"n":"第二十三条","txt":"用户交寄邮件，应当清楚、准确地填写收件人姓名、地址和邮政编码。邮政企业应当在邮政营业场所免费为用户提供邮政编码查询服务。"},{"i":24,"n":"第二十四条","txt":"邮政企业收寄邮件和用户交寄邮件，应当遵守法律、行政法规以及国务院和国务院有关部门关于禁止寄递或者限制寄递物品的规定。"},{"i":25,"n":"第二十五条","txt":"邮政企业应当依法建立并执行邮件收寄验视制度。"},{"i":26,"n":"第二十六条","txt":"邮政企业发现邮件内夹带禁止寄递或者限制寄递的物品的，应当按照国家有关规定处理。"},{"i":27,"n":"第二十七条","txt":"对提供邮政普遍服务的邮政企业交运的邮件，铁路、公路、水路、航空等运输企业应当优先安排运输，车站、港口、机场应当安排装卸场所和出入通道。"},{"i":28,"n":"第二十八条","txt":"带有邮政专用标志的车船进出港口、通过渡口时，应当优先放行。"},{"i":29,"n":"第二十九条","txt":"邮件通过海上运输时，不参与分摊共同海损。"},{"i":30,"n":"第三十条","txt":"海关依照《中华人民共和国海关法》的规定，对进出境的国际邮袋、邮件集装箱和国际邮递物品实施监管。"},{"i":31,"n":"第三十一条","txt":"进出境邮件的检疫，由进出境检验检疫机构依法实施。"},{"i":32,"n":"第三十二条","txt":"邮政企业采取按址投递、用户领取或者与用户协商的其他方式投递邮件。"},{"i":33,"n":"第三十三条","txt":"邮政企业对无法投递的邮件，应当退回寄件人。"},{"i":34,"n":"第三十四条","txt":"邮政汇款的收款人应当自收到汇款通知之日起六十日内，凭有效身份证件到邮政企业兑领汇款。"},{"i":35,"n":"第三十五条","txt":"任何单位和个人不得私自开拆、隐匿、毁弃他人邮件。"},{"i":36,"n":"第三十六条","txt":"因国家安全或者追查刑事犯罪的需要，公安机关、国家安全机关或者检察机关可以依法检查、扣留有关邮件，并可以要求邮政企业提供相关用户使用邮政服务的信息。邮政企业和有关单位应当配合，并对有关情况予以保密。"},{"i":37,"n":"第三十七条","txt":"任何单位和个人不得利用邮件寄递含有下列内容的物品："},{"i":38,"n":"第三十八条","txt":"任何单位和个人不得有下列行为："},{"i":39,"n":"第三十九条","txt":"实行政府指导价或者政府定价的邮政业务范围，以中央政府定价目录为依据，具体资费标准由国务院价格主管部门会同国务院财政部门、国务院邮政管理部门制定。"},{"i":40,"n":"第四十条","txt":"国务院有关部门制定邮政业务资费标准，应当听取邮政企业、用户和其他有关方面的意见。"},{"i":41,"n":"第四十一条","txt":"邮件资费的交付，以邮资凭证、证明邮资已付的戳记以及有关业务单据等表示。"},{"i":42,"n":"第四十二条","txt":"普通邮票发行数量由邮政企业按照市场需要确定，报国务院邮政管理部门备案；纪念邮票和特种邮票发行计划由邮政企业根据市场需要提出，报国务院邮政管理部门审定。国务院邮政管理部门负责纪念邮票的选题和图案审查。"},{"i":43,"n":"第四十三条","txt":"邮资凭证售出后，邮资凭证持有人不得要求邮政企业兑换现金。"},{"i":44,"n":"第四十四条","txt":"下列邮资凭证不得使用："},{"i":45,"n":"第四十五条","txt":"邮政普遍服务业务范围内的邮件和汇款的损失赔偿，适用本章规定。"},{"i":46,"n":"第四十六条","txt":"邮政企业对平常邮件的损失不承担赔偿责任。但是，邮政企业因故意或者重大过失造成平常邮件损失的除外。"},{"i":47,"n":"第四十七条","txt":"邮政企业对给据邮件的损失依照下列规定赔偿："},{"i":48,"n":"第四十八条","txt":"因下列原因之一造成的给据邮件损失，邮政企业不承担赔偿责任："},{"i":49,"n":"第四十九条","txt":"用户交寄给据邮件后，对国内邮件可以自交寄之日起一年内持收据向邮政企业查询，对国际邮件可以自交寄之日起一百八十日内持收据向邮政企业查询。"},{"i":50,"n":"第五十条","txt":"邮政汇款的汇款人自汇款之日起一年内，可以持收据向邮政企业查询。邮政企业应当自用户查询之日起二十日内将查询结果告知汇款人。查复期满未查到汇款的，邮政企业应当向汇款人退还汇款和汇款费用。"},{"i":51,"n":"第五十一条","txt":"经营快递业务，应当依照本法规定取得快递业务经营许可；未经许可，任何单位和个人不得经营快递业务。"},{"i":52,"n":"第五十二条","txt":"申请快递业务经营许可，应当具备下列条件："},{"i":53,"n":"第五十三条","txt":"申请快递业务经营许可，在省、自治区、直辖市范围内经营的，应当向所在地的省、自治区、直辖市邮政管理机构提出申请，跨省、自治区、直辖市经营或者经营国际快递业务的，应当向国务院邮政管理部门提出申请；申请时应当提交申请书和有关申请材料。"},{"i":54,"n":"第五十四条","txt":"邮政企业以外的经营快递业务的企业（以下称快递企业）设立分支机构或者合并、分立的，应当向邮政管理部门备案。"},{"i":55,"n":"第五十五条","txt":"快递企业不得经营由邮政企业专营的信件寄递业务，不得寄递国家机关公文。"},{"i":56,"n":"第五十六条","txt":"快递企业经营邮政企业专营业务范围以外的信件快递业务，应当在信件封套的显著位置标注信件字样。"},{"i":57,"n":"第五十七条","txt":"经营国际快递业务应当接受邮政管理部门和有关部门依法实施的监管。邮政管理部门和有关部门可以要求经营国际快递业务的企业提供报关数据。"},{"i":58,"n":"第五十八条","txt":"快递企业停止经营快递业务的，应当书面告知邮政管理部门，交回快递业务经营许可证，并对尚未投递的快件按照国务院邮政管理部门的规定妥善处理。"},{"i":59,"n":"第五十九条","txt":"本法第六条、第二十一条、第二十二条、第二十四条、第二十五条、第二十六条第一款、第三十五条第二款、第三十六条关于邮政企业及其从业人员的规定，适用于快递企业及其从业人员；第十一条关于邮件处理场所的规定，适用于快件处理场所；第三条第二款、第二十六条第二款、第三十五条第一款、第三十六条、第三十七条关于邮件的规定，适用于快件；第四十五条第二款关于邮件的损失赔偿的规定，适用于快件的损失赔偿。"},{"i":60,"n":"第六十条","txt":"经营快递业务的企业依法成立的行业协会，依照法律、行政法规及其章程规定，制定快递行业规范，加强行业自律，为企业提供信息、培训等方面的服务，促进快递行业的健康发展。"},{"i":61,"n":"第六十一条","txt":"邮政管理部门依法履行监督管理职责，可以采取下列监督检查措施："},{"i":62,"n":"第六十二条","txt":"邮政管理部门根据履行监督管理职责的需要，可以要求邮政企业和快递企业报告有关经营情况。"},{"i":63,"n":"第六十三条","txt":"邮政管理部门进行监督检查时，监督检查人员不得少于二人，并应当出示执法证件。对邮政管理部门依法进行的监督检查，有关单位和个人应当配合，不得拒绝、阻碍。"},{"i":64,"n":"第六十四条","txt":"邮政管理部门工作人员对监督检查中知悉的商业秘密，负有保密义务。"},{"i":65,"n":"第六十五条","txt":"邮政企业和快递企业应当及时、妥善处理用户对服务质量提出的异议。用户对处理结果不满意的，可以向邮政管理部门申诉，邮政管理部门应当及时依法处理，并自接到申诉之日起三十日内作出答复。"},{"i":66,"n":"第六十六条","txt":"任何单位和个人对违反本法规定的行为，有权向邮政管理部门举报。邮政管理部门接到举报后，应当及时依法处理。"},{"i":67,"n":"第六十七条","txt":"邮政企业提供邮政普遍服务不符合邮政普遍服务标准的，由邮政管理部门责令改正，可以处一万元以下的罚款；情节严重的，处一万元以上五万元以下的罚款；对直接负责的主管人员和其他直接责任人员给予处分。"},{"i":68,"n":"第六十八条","txt":"邮政企业未经邮政管理部门批准，停止办理或者限制办理邮政普遍服务业务和特殊服务业务，或者撤销提供邮政普遍服务的邮政营业场所的，由邮政管理部门责令改正，可以处二万元以下的罚款；情节严重的，处二万元以上十万元以下的罚款；对直接负责的主管人员和其他直接责任人员给予处分。"},{"i":69,"n":"第六十九条","txt":"邮政企业利用带有邮政专用标志的车船从事邮件运递以外的经营性活动，或者以出租等方式允许其他单位或者个人使用带有邮政专用标志的车船的，由邮政管理部门责令改正，没收违法所得，可以并处二万元以下的罚款；情节严重的，并处二万元以上十万元以下的罚款；对直接负责的主管人员和其他直接责任人员给予处分。"},{"i":70,"n":"第七十条","txt":"邮政企业从业人员故意延误投递邮件的，由邮政企业给予处分。"},{"i":71,"n":"第七十一条","txt":"冒领、私自开拆、隐匿、毁弃或者非法检查他人邮件、快件，尚不构成犯罪的，依法给予治安管理处罚。"},{"i":72,"n":"第七十二条","txt":"未取得快递业务经营许可经营快递业务，或者邮政企业以外的单位或者个人经营由邮政企业专营的信件寄递业务或者寄递国家机关公文的，由邮政管理部门或者工商行政管理部门责令改正，没收违法所得，并处五万元以上十万元以下的罚款；情节严重的，并处十万元以上二十万元以下的罚款；对快递企业，还可以责令停业整顿直至吊销其快递业务经营许可证。"},{"i":73,"n":"第七十三条","txt":"快递企业有下列行为之一的，由邮政管理部门责令改正，可以处一万元以下的罚款；情节严重的，处一万元以上五万元以下的罚款，并可以责令停业整顿："},{"i":74,"n":"第七十四条","txt":"邮政企业、快递企业未按照规定向用户明示其业务资费标准，或者有其他价格违法行为的，由政府价格主管部门依照《中华人民共和国价格法》的规定处罚。"},{"i":75,"n":"第七十五条","txt":"邮政企业、快递企业不建立或者不执行收件验视制度，或者违反法律、行政法规以及国务院和国务院有关部门关于禁止寄递或者限制寄递物品的规定收寄邮件、快件的，对邮政企业直接负责的主管人员和其他直接责任人员给予处分；对快递企业，邮政管理部门可以责令停业整顿直至吊销其快递业务经营许可证。"},{"i":76,"n":"第七十六条","txt":"邮政企业、快递企业违法提供用户使用邮政服务或者快递服务的信息，尚不构成犯罪的，由邮政管理部门责令改正，没收违法所得，并处一万元以上五万元以下的罚款；对邮政企业直接负责的主管人员和其他直接责任人员给予处分；对快递企业，邮政管理部门还可以责令停业整顿直至吊销其快递业务经营许可证。"},{"i":77,"n":"第七十七条","txt":"邮政企业、快递企业拒绝、阻碍依法实施的监督检查，尚不构成犯罪的，依法给予治安管理处罚；对快递企业，邮政管理部门还可以责令停业整顿直至吊销其快递业务经营许可证。"},{"i":78,"n":"第七十八条","txt":"邮政企业及其从业人员、快递企业及其从业人员在经营活动中有危害国家安全行为的，依法追究法律责任；对快递企业，并由邮政管理部门吊销其快递业务经营许可证。"},{"i":79,"n":"第七十九条","txt":"冒用邮政企业名义或者邮政专用标志，或者伪造邮政专用品或者倒卖伪造的邮政专用品的，由邮政管理部门责令改正，没收伪造的邮政专用品以及违法所得，并处一万元以上五万元以下的罚款。"},{"i":80,"n":"第八十条","txt":"有下列行为之一，尚不构成犯罪的，依法给予治安管理处罚："},{"i":81,"n":"第八十一条","txt":"违反本法规定被吊销快递业务经营许可证的，自快递业务经营许可证被吊销之日起三年内，不得申请经营快递业务。"},{"i":82,"n":"第八十二条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":83,"n":"第八十三条","txt":"邮政管理部门工作人员在监督管理工作中滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。"},{"i":84,"n":"第八十四条","txt":"本法下列用语的含义："},{"i":85,"n":"第八十五条","txt":"本法公布前按照国家有关规定，经国务院对外贸易主管部门批准或者备案，并向工商行政管理部门依法办理登记后经营国际快递业务的国际货物运输代理企业，凭批准或者备案文件以及营业执照，到国务院邮政管理部门领取快递业务经营许可证。国务院邮政管理部门应当将企业领取快递业务经营许可证的情况向其原办理登记的工商行政管理部门通报。"},{"i":86,"n":"第八十六条","txt":"省、自治区、直辖市应当根据本地区的实际情况，制定支持邮政企业提供邮政普遍服务的具体办法。"},{"i":87,"n":"第八十七条","txt":"本法自2009年10月1日起施行。"}],"tielufa":[{"i":1,"n":"第一条","txt":"为了保障铁路运输和铁路建设的顺利进行，适应社会主义现代化建设和人民生活的需要，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称铁路，包括国家铁路、地方铁路、专用铁路和铁路专用线。"},{"i":3,"n":"第三条","txt":"国务院铁路主管部门主管全国铁路工作，对国家铁路实行高度集中、统一指挥的运输管理体制，对地方铁路、专用铁路和铁路专用线进行指导、协调、监督和帮助。"},{"i":4,"n":"第四条","txt":"国家重点发展国家铁路，大力扶持地方铁路的发展。"},{"i":5,"n":"第五条","txt":"铁路运输企业必须坚持社会主义经营方向和为人民服务的宗旨，改善经营管理，切实改进路风，提高运输服务质量。"},{"i":6,"n":"第六条","txt":"公民有爱护铁路设施的义务。禁止任何人破坏铁路设施，扰乱铁路运输的正常秩序。"},{"i":7,"n":"第七条","txt":"铁路沿线各级地方人民政府应当协助铁路运输企业保证铁路运输安全畅通，车站、列车秩序良好，铁路设施完好和铁路建设顺利进行。"},{"i":8,"n":"第八条","txt":"国家铁路的技术管理规程，由国务院铁路主管部门制定，地方铁路、专用铁路的技术管理办法，参照国家铁路的技术管理规程制定。"},{"i":9,"n":"第九条","txt":"国家鼓励铁路科学技术研究，提高铁路科学技术水平。对在铁路科学技术研究中有显著成绩的单位和个人给予奖励。"},{"i":10,"n":"第十条","txt":"铁路运输企业应当保证旅客和货物运输的安全，做到列车正点到达。"},{"i":11,"n":"第十一条","txt":"铁路运输合同是明确铁路运输企业与旅客、托运人之间权利义务关系的协议。"},{"i":12,"n":"第十二条","txt":"铁路运输企业应当保证旅客按车票载明的日期、车次乘车，并到达目的站。因铁路运输企业的责任造成旅客不能按车票载明的日期、车次乘车的，铁路运输企业应当按照旅客的要求，退还全部票款或者安排改乘到达相同目的站的其他列车。"},{"i":13,"n":"第十三条","txt":"铁路运输企业应当采取有效措施做好旅客运输服务工作，做到文明礼貌、热情周到，保持车站和车厢内的清洁卫生，提供饮用开水，做好列车上的饮食供应工作。"},{"i":14,"n":"第十四条","txt":"旅客乘车应当持有效车票。对无票乘车或者持失效车票乘车的，应当补收票款，并按照规定加收票款；拒不交付的，铁路运输企业可以责令下车。"},{"i":15,"n":"第十五条","txt":"国家铁路和地方铁路根据发展生产、搞活流通的原则，安排货物运输计划。"},{"i":16,"n":"第十六条","txt":"铁路运输企业应当按照合同约定的期限或者国务院铁路主管部门规定的期限，将货物、包裹、行李运到目的站；逾期运到的，铁路运输企业应当支付违约金。"},{"i":17,"n":"第十七条","txt":"铁路运输企业应当对承运的货物、包裹、行李自接受承运时起到交付时止发生的灭失、短少、变质、污染或者损坏，承担赔偿责任："},{"i":18,"n":"第十八条","txt":"由于下列原因造成的货物、包裹、行李损失的，铁路运输企业不承担赔偿责任："},{"i":19,"n":"第十九条","txt":"托运人应当如实填报托运单，铁路运输企业有权对填报的货物和包裹的品名、重量、数量进行检查。经检查，申报与实际不符的，检查费用由托运人承担；申报与实际相符的，检查费用由铁路运输企业承担，因检查对货物和包裹中的物品造成的损坏由铁路运输企业赔偿。"},{"i":20,"n":"第二十条","txt":"托运货物需要包装的，托运人应当按照国家包装标准或者行业包装标准包装；没有国家包装标准或者行业包装标准的，应当妥善包装，使货物在运输途中不因包装原因而受损坏。"},{"i":21,"n":"第二十一条","txt":"货物、包裹、行李到站后，收货人或者旅客应当按照国务院铁路主管部门规定的期限及时领取，并支付托运人未付或者少付的运费和其他费用；逾期领取的，收货人或者旅客应当按照规定交付保管费。"},{"i":22,"n":"第二十二条","txt":"自铁路运输企业发出领取货物通知之日起满三十日仍无人领取的货物，或者收货人书面通知铁路运输企业拒绝领取的货物，铁路运输企业应当通知托运人，托运人自接到通知之日起满三十日未作答复的，由铁路运输企业变卖；所得价款在扣除保管等费用后尚有余款的，应当退还托运人，无法退还、自变卖之日起一百八十日内托运人又未领回的，上缴国库。"},{"i":23,"n":"第二十三条","txt":"因旅客、托运人或者收货人的责任给铁路运输企业造成财产损失的，由旅客、托运人或者收货人承担赔偿责任。"},{"i":24,"n":"第二十四条","txt":"国家鼓励专用铁路兼办公共旅客、货物运输营业；提倡铁路专用线与有关单位按照协议共用。"},{"i":25,"n":"第二十五条","txt":"铁路的旅客票价率和货物、行李的运价率实行政府指导价或者政府定价，竞争性领域实行市场调节价。政府指导价、政府定价的定价权限和具体适用范围以中央政府和地方政府的定价目录为依据。铁路旅客、货物运输杂费的收费项目和收费标准，以及铁路包裹运价率由铁路运输企业自主制定。"},{"i":26,"n":"第二十六条","txt":"铁路的旅客票价，货物、包裹、行李的运价，旅客和货物运输杂费的收费项目和收费标准，必须公告；未公告的不得实施。"},{"i":27,"n":"第二十七条","txt":"国家铁路、地方铁路和专用铁路印制使用的旅客、货物运输票证，禁止伪造和变造。"},{"i":28,"n":"第二十八条","txt":"托运、承运货物、包裹、行李，必须遵守国家关于禁止或者限制运输物品的规定。"},{"i":29,"n":"第二十九条","txt":"铁路运输企业与公路、航空或者水上运输企业相互间实行国内旅客、货物联运，依照国家有关规定办理；国家没有规定的，依照有关各方的协议办理。"},{"i":30,"n":"第三十条","txt":"国家铁路、地方铁路参加国际联运，必须经国务院批准。"},{"i":31,"n":"第三十一条","txt":"铁路军事运输依照国家有关规定办理。"},{"i":32,"n":"第三十二条","txt":"发生铁路运输合同争议的，铁路运输企业和托运人、收货人或者旅客可以通过调解解决；不愿意调解解决或者调解不成的，可以依据合同中的仲裁条款或者事后达成的书面仲裁协议，向国家规定的仲裁机构申请仲裁。"},{"i":33,"n":"第三十三条","txt":"铁路发展规划应当依据国民经济和社会发展以及国防建设的需要制定，并与其他方式的交通运输发展规划相协调。"},{"i":34,"n":"第三十四条","txt":"地方铁路、专用铁路、铁路专用线的建设计划必须符合全国铁路发展规划，并征得国务院铁路主管部门或者国务院铁路主管部门授权的机构的同意。"},{"i":35,"n":"第三十五条","txt":"在城市规划区范围内，铁路的线路、车站、枢纽以及其他有关设施的规划，应当纳入所在城市的总体规划。"},{"i":36,"n":"第三十六条","txt":"铁路建设用地，依照有关法律、行政法规的规定办理。"},{"i":37,"n":"第三十七条","txt":"已经取得使用权的铁路建设用地，应当依照批准的用途使用，不得擅自改作他用；其他单位或者个人不得侵占。"},{"i":38,"n":"第三十八条","txt":"铁路的标准轨距为1435毫米。新建国家铁路必须采用标准轨距。"},{"i":39,"n":"第三十九条","txt":"铁路建成后，必须依照国家基本建设程序的规定，经验收合格，方能交付正式运行。"},{"i":40,"n":"第四十条","txt":"铁路与道路交叉处，应当优先考虑设置立体交叉；未设立体交叉的，可以根据国家有关规定设置平交道口或者人行过道。在城市规划区内设置平交道口或者人行过道，由铁路运输企业或者建有专用铁路、铁路专用线的企业或者其他单位和城市规划主管部门共同决定。"},{"i":41,"n":"第四十一条","txt":"修建跨越河流的铁路桥梁，应当符合国家规定的防洪、通航和水流的要求。"},{"i":42,"n":"第四十二条","txt":"铁路运输企业必须加强对铁路的管理和保护，定期检查、维修铁路运输设施，保证铁路运输设施完好，保障旅客和货物运输安全。"},{"i":43,"n":"第四十三条","txt":"铁路公安机关和地方公安机关分工负责共同维护铁路治安秩序。车站和列车内的治安秩序，由铁路公安机关负责维护；铁路沿线的治安秩序，由地方公安机关和铁路公安机关共同负责维护，以地方公安机关为主。"},{"i":44,"n":"第四十四条","txt":"电力主管部门应当保证铁路牵引用电以及铁路运营用电中重要负荷的电力供应。铁路运营用电中重要负荷的供应范围由国务院铁路主管部门和国务院电力主管部门商定。"},{"i":45,"n":"第四十五条","txt":"铁路线路两侧地界以外的山坡地由当地人民政府作为水土保持的重点进行整治。铁路隧道顶上的山坡地由铁路运输企业协助当地人民政府进行整治。铁路地界以内的山坡地由铁路运输企业进行整治。"},{"i":46,"n":"第四十六条","txt":"在铁路线路和铁路桥梁、涵洞两侧一定距离内，修建山塘、水库、堤坝，开挖河道、干渠，采石挖砂，打井取水，影响铁路路基稳定或者危害铁路桥梁、涵洞安全的，由县级以上地方人民政府责令停止建设或者采挖、打井等活动，限期恢复原状或者责令采取必要的安全防护措施。"},{"i":47,"n":"第四十七条","txt":"禁止擅自在铁路线路上铺设平交道口和人行过道。"},{"i":48,"n":"第四十八条","txt":"运输危险品必须按照国务院铁路主管部门的规定办理，禁止以非危险品品名托运危险品。"},{"i":49,"n":"第四十九条","txt":"对损毁、移动铁路信号装置及其他行车设施或者在铁路线路上放置障碍物的，铁路职工有权制止，可以扭送公安机关处理。"},{"i":50,"n":"第五十条","txt":"禁止偷乘货车、攀附行进中的列车或者击打列车。对偷乘货车、攀附行进中的列车或者击打列车的，铁路职工有权制止。"},{"i":51,"n":"第五十一条","txt":"禁止在铁路线路上行走、坐卧。对在铁路线路上行走、坐卧的，铁路职工有权制止。"},{"i":52,"n":"第五十二条","txt":"禁止在铁路线路两侧二十米以内或者铁路防护林地内放牧。对在铁路线路两侧二十米以内或者铁路防护林地内放牧的，铁路职工有权制止。"},{"i":53,"n":"第五十三条","txt":"对聚众拦截列车或者聚众冲击铁路行车调度机构的，铁路职工有权制止；不听制止的，公安人员现场负责人有权命令解散；拒不解散的，公安人员现场负责人有权依照国家有关规定决定采取必要手段强行驱散，并对拒不服从的人员强行带离现场或者予以拘留。"},{"i":54,"n":"第五十四条","txt":"对哄抢铁路运输物资的，铁路职工有权制止，可以扭送公安机关处理；现场公安人员可以予以拘留。"},{"i":55,"n":"第五十五条","txt":"在列车内，寻衅滋事，扰乱公共秩序，危害旅客人身、财产安全的，铁路职工有权制止，铁路公安人员可以予以拘留。"},{"i":56,"n":"第五十六条","txt":"在车站和旅客列车内，发生法律规定需要检疫的传染病时，由铁路卫生检疫机构进行检疫；根据铁路卫生检疫机构的请求，地方卫生检疫机构应予协助。"},{"i":57,"n":"第五十七条","txt":"发生铁路交通事故，铁路运输企业应当依照国务院和国务院有关主管部门关于事故调查处理的规定办理，并及时恢复正常行车，任何单位和个人不得阻碍铁路线路开通和列车运行。"},{"i":58,"n":"第五十八条","txt":"因铁路行车事故及其他铁路运营事故造成人身伤亡的，铁路运输企业应当承担赔偿责任；如果人身伤亡是因不可抗力或者由于受害人自身的原因造成的，铁路运输企业不承担赔偿责任。"},{"i":59,"n":"第五十九条","txt":"国家铁路的重要桥梁和隧道，由中国人民武装警察部队负责守卫。"},{"i":60,"n":"第六十条","txt":"违反本法规定，携带危险品进站上车或者以非危险品品名托运危险品，导致发生重大事故的，依照刑法有关规定追究刑事责任。企业事业单位、国家机关、社会团体犯本款罪的，处以罚金，对其主管人员和直接责任人员依法追究刑事责任。"},{"i":61,"n":"第六十一条","txt":"故意损毁、移动铁路行车信号装置或者在铁路线路上放置足以使列车倾覆的障碍物的，依照刑法有关规定追究刑事责任。"},{"i":62,"n":"第六十二条","txt":"盗窃铁路线路上行车设施的零件、部件或者铁路线路上的器材，危及行车安全的，依照刑法有关规定追究刑事责任。"},{"i":63,"n":"第六十三条","txt":"聚众拦截列车、冲击铁路行车调度机构不听制止的，对首要分子和骨干分子依照刑法有关规定追究刑事责任。"},{"i":64,"n":"第六十四条","txt":"聚众哄抢铁路运输物资的，对首要分子和骨干分子依照刑法有关规定追究刑事责任。"},{"i":65,"n":"第六十五条","txt":"在列车内，抢劫旅客财物，伤害旅客的，依照刑法有关规定从重处罚。"},{"i":66,"n":"第六十六条","txt":"倒卖旅客车票，构成犯罪的，依照刑法有关规定追究刑事责任。铁路职工倒卖旅客车票或者与其他人员勾结倒卖旅客车票的，依照刑法有关规定追究刑事责任。"},{"i":67,"n":"第六十七条","txt":"违反本法规定，尚不够刑事处罚，应当给予治安管理处罚的，依照治安管理处罚法的规定处罚。"},{"i":68,"n":"第六十八条","txt":"擅自在铁路线路上铺设平交道口、人行过道的，由铁路公安机关或者地方公安机关责令限期拆除，可以并处罚款。"},{"i":69,"n":"第六十九条","txt":"铁路运输企业违反本法规定，多收运费、票款或者旅客、货物运输杂费的，必须将多收的费用退还付款人，无法退还的上缴国库。将多收的费用据为己有或者侵吞私分的，依照刑法有关规定追究刑事责任。"},{"i":70,"n":"第七十条","txt":"铁路职工利用职务之便走私的，或者与其他人员勾结走私的，依照刑法有关规定追究刑事责任。"},{"i":71,"n":"第七十一条","txt":"铁路职工玩忽职守、违反规章制度造成铁路运营事故的，滥用职权、利用办理运输业务之便谋取私利的，给予行政处分；情节严重、构成犯罪的，依照刑法有关规定追究刑事责任。"},{"i":72,"n":"第七十二条","txt":"本法所称国家铁路运输企业是指铁路局和铁路分局。"},{"i":73,"n":"第七十三条","txt":"国务院根据本法制定实施条例。"},{"i":74,"n":"第七十四条","txt":"本法自1991年5月1日起施行。"}],"yinhangyejianduguanlifa":[{"i":1,"n":"第一条","txt":"为了加强对银行业的监督管理，规范监督管理行为，防范和化解银行业风险，保护存款人和其他客户的合法权益，促进银行业健康发展，制定本法。"},{"i":2,"n":"第二条","txt":"国务院银行业监督管理机构负责对全国银行业金融机构及其业务活动监督管理的工作。"},{"i":3,"n":"第三条","txt":"银行业监督管理的目标是促进银行业的合法、稳健运行，维护公众对银行业的信心。"},{"i":4,"n":"第四条","txt":"银行业监督管理机构对银行业实施监督管理，应当遵循依法、公开、公正和效率的原则。"},{"i":5,"n":"第五条","txt":"银行业监督管理机构及其从事监督管理工作的人员依法履行监督管理职责，受法律保护。地方政府、各级政府部门、社会团体和个人不得干涉。"},{"i":6,"n":"第六条","txt":"国务院银行业监督管理机构应当和中国人民银行、国务院其他金融监督管理机构建立监督管理信息共享机制。"},{"i":7,"n":"第七条","txt":"国务院银行业监督管理机构可以和其他国家或者地区的银行业监督管理机构建立监督管理合作机制，实施跨境监督管理。"},{"i":8,"n":"第八条","txt":"国务院银行业监督管理机构根据履行职责的需要设立派出机构。国务院银行业监督管理机构对派出机构实行统一领导和管理。"},{"i":9,"n":"第九条","txt":"银行业监督管理机构从事监督管理工作的人员，应当具备与其任职相适应的专业知识和业务工作经验。"},{"i":10,"n":"第十条","txt":"银行业监督管理机构工作人员，应当忠于职守，依法办事，公正廉洁，不得利用职务便利牟取不正当的利益，不得在金融机构等企业中兼任职务。"},{"i":11,"n":"第十一条","txt":"银行业监督管理机构工作人员，应当依法保守国家秘密，并有责任为其监督管理的银行业金融机构及当事人保守秘密。"},{"i":12,"n":"第十二条","txt":"国务院银行业监督管理机构应当公开监督管理程序，建立监督管理责任制度和内部监督制度。"},{"i":13,"n":"第十三条","txt":"银行业监督管理机构在处置银行业金融机构风险、查处有关金融违法行为等监督管理活动中，地方政府、各级有关部门应当予以配合和协助。"},{"i":14,"n":"第十四条","txt":"国务院审计、监察等机关，应当依照法律规定对国务院银行业监督管理机构的活动进行监督。"},{"i":15,"n":"第十五条","txt":"国务院银行业监督管理机构依照法律、行政法规制定并发布对银行业金融机构及其业务活动监督管理的规章、规则。"},{"i":16,"n":"第十六条","txt":"国务院银行业监督管理机构依照法律、行政法规规定的条件和程序，审查批准银行业金融机构的设立、变更、终止以及业务范围。"},{"i":17,"n":"第十七条","txt":"申请设立银行业金融机构，或者银行业金融机构变更持有资本总额或者股份总额达到规定比例以上的股东的，国务院银行业监督管理机构应当对股东的资金来源、财务状况、资本补充能力和诚信状况进行审查。"},{"i":18,"n":"第十八条","txt":"银行业金融机构业务范围内的业务品种，应当按照规定经国务院银行业监督管理机构审查批准或者备案。需要审查批准或者备案的业务品种，由国务院银行业监督管理机构依照法律、行政法规作出规定并公布。"},{"i":19,"n":"第十九条","txt":"未经国务院银行业监督管理机构批准，任何单位或者个人不得设立银行业金融机构或者从事银行业金融机构的业务活动。"},{"i":20,"n":"第二十条","txt":"国务院银行业监督管理机构对银行业金融机构的董事和高级管理人员实行任职资格管理。具体办法由国务院银行业监督管理机构制定。"},{"i":21,"n":"第二十一条","txt":"银行业金融机构的审慎经营规则，由法律、行政法规规定，也可以由国务院银行业监督管理机构依照法律、行政法规制定。"},{"i":22,"n":"第二十二条","txt":"国务院银行业监督管理机构应当在规定的期限，对下列申请事项作出批准或者不批准的书面决定；决定不批准的，应当说明理由："},{"i":23,"n":"第二十三条","txt":"银行业监督管理机构应当对银行业金融机构的业务活动及其风险状况进行非现场监管，建立银行业金融机构监督管理信息系统，分析、评价银行业金融机构的风险状况。"},{"i":24,"n":"第二十四条","txt":"银行业监督管理机构应当对银行业金融机构的业务活动及其风险状况进行现场检查。"},{"i":25,"n":"第二十五条","txt":"国务院银行业监督管理机构应当对银行业金融机构实行并表监督管理。"},{"i":26,"n":"第二十六条","txt":"国务院银行业监督管理机构对中国人民银行提出的检查银行业金融机构的建议，应当自收到建议之日起三十日内予以回复。"},{"i":27,"n":"第二十七条","txt":"国务院银行业监督管理机构应当建立银行业金融机构监督管理评级体系和风险预警机制，根据银行业金融机构的评级情况和风险状况，确定对其现场检查的频率、范围和需要采取的其他措施。"},{"i":28,"n":"第二十八条","txt":"国务院银行业监督管理机构应当建立银行业突发事件的发现、报告岗位责任制度。"},{"i":29,"n":"第二十九条","txt":"国务院银行业监督管理机构应当会同中国人民银行、国务院财政部门等有关部门建立银行业突发事件处置制度，制定银行业突发事件处置预案，明确处置机构和人员及其职责、处置措施和处置程序，及时、有效地处置银行业突发事件。"},{"i":30,"n":"第三十条","txt":"国务院银行业监督管理机构负责统一编制全国银行业金融机构的统计数据、报表，并按照国家有关规定予以公布。"},{"i":31,"n":"第三十一条","txt":"国务院银行业监督管理机构对银行业自律组织的活动进行指导和监督。"},{"i":32,"n":"第三十二条","txt":"国务院银行业监督管理机构可以开展与银行业监督管理有关的国际交流、合作活动。"},{"i":33,"n":"第三十三条","txt":"银行业监督管理机构根据履行职责的需要，有权要求银行业金融机构按照规定报送资产负债表、利润表和其他财务会计、统计报表、经营管理资料以及注册会计师出具的审计报告。"},{"i":34,"n":"第三十四条","txt":"银行业监督管理机构根据审慎监管的要求，可以采取下列措施进行现场检查："},{"i":35,"n":"第三十五条","txt":"银行业监督管理机构根据履行职责的需要，可以与银行业金融机构董事、高级管理人员进行监督管理谈话，要求银行业金融机构董事、高级管理人员就银行业金融机构的业务活动和风险管理的重大事项作出说明。"},{"i":36,"n":"第三十六条","txt":"银行业监督管理机构应当责令银行业金融机构按照规定，如实向社会公众披露财务会计报告、风险管理状况、董事和高级管理人员变更以及其他重大事项等信息。"},{"i":37,"n":"第三十七条","txt":"银行业金融机构违反审慎经营规则的，国务院银行业监督管理机构或者其省一级派出机构应当责令限期改正；逾期未改正的，或者其行为严重危及该银行业金融机构的稳健运行、损害存款人和其他客户合法权益的，经国务院银行业监督管理机构或者其省一级派出机构负责人批准，可以区别情形，采取下列措施："},{"i":38,"n":"第三十八条","txt":"银行业金融机构已经或者可能发生信用危机，严重影响存款人和其他客户合法权益的，国务院银行业监督管理机构可以依法对该银行业金融机构实行接管或者促成机构重组，接管和机构重组依照有关法律和国务院的规定执行。"},{"i":39,"n":"第三十九条","txt":"银行业金融机构有违法经营、经营管理不善等情形，不予撤销将严重危害金融秩序、损害公众利益的，国务院银行业监督管理机构有权予以撤销。"},{"i":40,"n":"第四十条","txt":"银行业金融机构被接管、重组或者被撤销的，国务院银行业监督管理机构有权要求该银行业金融机构的董事、高级管理人员和其他工作人员，按照国务院银行业监督管理机构的要求履行职责。"},{"i":41,"n":"第四十一条","txt":"经国务院银行业监督管理机构或者其省一级派出机构负责人批准，银行业监督管理机构有权查询涉嫌金融违法的银行业金融机构及其工作人员以及关联行为人的账户；对涉嫌转移或者隐匿违法资金的，经银行业监督管理机构负责人批准，可以申请司法机关予以冻结。"},{"i":42,"n":"第四十二条","txt":"银行业监督管理机构依法对银行业金融机构进行检查时，经设区的市一级以上银行业监督管理机构负责人批准，可以对与涉嫌违法事项有关的单位和个人采取下列措施："},{"i":43,"n":"第四十三条","txt":"银行业监督管理机构从事监督管理工作的人员有下列情形之一的，依法给予行政处分；构成犯罪的，依法追究刑事责任："},{"i":44,"n":"第四十四条","txt":"擅自设立银行业金融机构或者非法从事银行业金融机构的业务活动的，由国务院银行业监督管理机构予以取缔；构成犯罪的，依法追究刑事责任；尚不构成犯罪的，由国务院银行业监督管理机构没收违法所得，违法所得五十万元以上的，并处违法所得一倍以上五倍以下罚款；没有违法所得或者违法所得不足五十万元的，处五十万元以上二百万元以下罚款。"},{"i":45,"n":"第四十五条","txt":"银行业金融机构有下列情形之一，由国务院银行业监督管理机构责令改正，有违法所得的，没收违法所得，违法所得五十万元以上的，并处违法所得一倍以上五倍以下罚款；没有违法所得或者违法所得不足五十万元的，处五十万元以上二百万元以下罚款；情节特别严重或者逾期不改正的，可以责令停业整顿或者吊销其经营许可证；构成犯罪的，依法追究刑事责任："},{"i":46,"n":"第四十六条","txt":"银行业金融机构有下列情形之一，由国务院银行业监督管理机构责令改正，并处二十万元以上五十万元以下罚款；情节特别严重或者逾期不改正的，可以责令停业整顿或者吊销其经营许可证；构成犯罪的，依法追究刑事责任："},{"i":47,"n":"第四十七条","txt":"银行业金融机构不按照规定提供报表、报告等文件、资料的，由银行业监督管理机构责令改正，逾期不改正的，处十万元以上三十万元以下罚款。"},{"i":48,"n":"第四十八条","txt":"银行业金融机构违反法律、行政法规以及国家有关银行业监督管理规定的，银行业监督管理机构除依照本法第四十四条至第四十七条规定处罚外，还可以区别不同情形，采取下列措施："},{"i":49,"n":"第四十九条","txt":"阻碍银行业监督管理机构工作人员依法执行检查、调查职务的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":50,"n":"第五十条","txt":"对在中华人民共和国境内设立的政策性银行、金融资产管理公司的监督管理，法律、行政法规另有规定的，依照其规定。"},{"i":51,"n":"第五十一条","txt":"对在中华人民共和国境内设立的外资银行业金融机构、中外合资银行业金融机构、外国银行业金融机构的分支机构的监督管理，法律、行政法规另有规定的，依照其规定。"},{"i":52,"n":"第五十二条","txt":"本法自2004年2月1日起施行。"}],"fanghongfa":[{"i":1,"n":"第一条","txt":"为了防治洪水，防御、减轻洪涝灾害，维护人民的生命和财产安全，保障社会主义现代化建设顺利进行，制定本法。"},{"i":2,"n":"第二条","txt":"防洪工作实行全面规划、统筹兼顾、预防为主、综合治理、局部利益服从全局利益的原则。"},{"i":3,"n":"第三条","txt":"防洪工程设施建设，应当纳入国民经济和社会发展计划。"},{"i":4,"n":"第四条","txt":"开发利用和保护水资源，应当服从防洪总体安排，实行兴利与除害相结合的原则。"},{"i":5,"n":"第五条","txt":"防洪工作按照流域或者区域实行统一规划、分级实施和流域管理与行政区域管理相结合的制度。"},{"i":6,"n":"第六条","txt":"任何单位和个人都有保护防洪工程设施和依法参加防汛抗洪的义务。"},{"i":7,"n":"第七条","txt":"各级人民政府应当加强对防洪工作的统一领导，组织有关部门、单位，动员社会力量，依靠科技进步，有计划地进行江河、湖泊治理，采取措施加强防洪工程设施建设，巩固、提高防洪能力。"},{"i":8,"n":"第八条","txt":"国务院水行政主管部门在国务院的领导下，负责全国防洪的组织、协调、监督、指导等日常工作。国务院水行政主管部门在国家确定的重要江河、湖泊设立的流域管理机构，在所管辖的范围内行使法律、行政法规规定和国务院水行政主管部门授权的防洪协调和监督管理职责。"},{"i":9,"n":"第九条","txt":"防洪规划是指为防治某一流域、河段或者区域的洪涝灾害而制定的总体部署，包括国家确定的重要江河、湖泊的流域防洪规划，其他江河、河段、湖泊的防洪规划以及区域防洪规划。"},{"i":10,"n":"第十条","txt":"国家确定的重要江河、湖泊的防洪规划，由国务院水行政主管部门依据该江河、湖泊的流域综合规划，会同有关部门和有关省、自治区、直辖市人民政府编制，报国务院批准。"},{"i":11,"n":"第十一条","txt":"编制防洪规划，应当遵循确保重点、兼顾一般，以及防汛和抗旱相结合、工程措施和非工程措施相结合的原则，充分考虑洪涝规律和上下游、左右岸的关系以及国民经济对防洪的要求，并与国土规划和土地利用总体规划相协调。"},{"i":12,"n":"第十二条","txt":"受风暴潮威胁的沿海地区的县级以上地方人民政府，应当把防御风暴潮纳入本地区的防洪规划，加强海堤（海塘）、挡潮闸和沿海防护林等防御风暴潮工程体系建设，监督建筑物、构筑物的设计和施工符合防御风暴潮的需要。"},{"i":13,"n":"第十三条","txt":"山洪可能诱发山体滑坡、崩塌和泥石流的地区以及其他山洪多发地区的县级以上地方人民政府，应当组织负责地质矿产管理工作的部门、水行政主管部门和其他有关部门对山体滑坡、崩塌和泥石流隐患进行全面调查，划定重点防治区，采取防治措施。"},{"i":14,"n":"第十四条","txt":"平原、洼地、水网圩区、山谷、盆地等易涝地区的有关地方人民政府，应当制定除涝治涝规划，组织有关部门、单位采取相应的治理措施，完善排水系统，发展耐涝农作物种类和品种，开展洪涝、干旱、盐碱综合治理。"},{"i":15,"n":"第十五条","txt":"国务院水行政主管部门应当会同有关部门和省、自治区、直辖市人民政府制定长江、黄河、珠江、辽河、淮河、海河入海河口的整治规划。"},{"i":16,"n":"第十六条","txt":"防洪规划确定的河道整治计划用地和规划建设的堤防用地范围内的土地，经土地管理部门和水行政主管部门会同有关地区核定，报经县级以上人民政府按照国务院规定的权限批准后，可以划定为规划保留区；该规划保留区范围内的土地涉及其他项目用地的，有关土地管理部门和水行政主管部门核定时，应当征求有关部门的意见。"},{"i":17,"n":"第十七条","txt":"在江河、湖泊上建设防洪工程和其他水工程、水电站等，应当符合防洪规划的要求；水库应当按照防洪规划的要求留足防洪库容。"},{"i":18,"n":"第十八条","txt":"防治江河洪水，应当蓄泄兼施，充分发挥河道行洪能力和水库、洼淀、湖泊调蓄洪水的功能，加强河道防护，因地制宜地采取定期清淤疏浚等措施，保持行洪畅通。"},{"i":19,"n":"第十九条","txt":"整治河道和修建控制引导河水流向、保护堤岸等工程，应当兼顾上下游、左右岸的关系，按照规划治导线实施，不得任意改变河水流向。"},{"i":20,"n":"第二十条","txt":"整治河道、湖泊，涉及航道的，应当兼顾航运需要，并事先征求交通主管部门的意见。整治航道，应当符合江河、湖泊防洪安全要求，并事先征求水行政主管部门的意见。"},{"i":21,"n":"第二十一条","txt":"河道、湖泊管理实行按水系统一管理和分级管理相结合的原则，加强防护，确保畅通。"},{"i":22,"n":"第二十二条","txt":"河道、湖泊管理范围内的土地和岸线的利用，应当符合行洪、输水的要求。"},{"i":23,"n":"第二十三条","txt":"禁止围湖造地。已经围垦的，应当按照国家规定的防洪标准进行治理，有计划地退地还湖。"},{"i":24,"n":"第二十四条","txt":"对居住在行洪河道内的居民，当地人民政府应当有计划地组织外迁。"},{"i":25,"n":"第二十五条","txt":"护堤护岸的林木，由河道、湖泊管理机构组织营造和管理。护堤护岸林木，不得任意砍伐。采伐护堤护岸林木的，应当依法办理采伐许可手续，并完成规定的更新补种任务。"},{"i":26,"n":"第二十六条","txt":"对壅水、阻水严重的桥梁、引道、码头和其他跨河工程设施，根据防洪标准，有关水行政主管部门可以报请县级以上人民政府按照国务院规定的权限责令建设单位限期改建或者拆除。"},{"i":27,"n":"第二十七条","txt":"建设跨河、穿河、穿堤、临河的桥梁、码头、道路、渡口、管道、缆线、取水、排水等工程设施，应当符合防洪标准、岸线规划、航运要求和其他技术要求，不得危害堤防安全、影响河势稳定、妨碍行洪畅通；其工程建设方案未经有关水行政主管部门根据前述防洪要求审查同意的，建设单位不得开工建设。"},{"i":28,"n":"第二十八条","txt":"对于河道、湖泊管理范围内依照本法规定建设的工程设施，水行政主管部门有权依法检查；水行政主管部门检查时，被检查者应当如实提供有关的情况和资料。"},{"i":29,"n":"第二十九条","txt":"防洪区是指洪水泛滥可能淹及的地区，分为洪泛区、蓄滞洪区和防洪保护区。"},{"i":30,"n":"第三十条","txt":"各级人民政府应当按照防洪规划对防洪区内的土地利用实行分区管理。"},{"i":31,"n":"第三十一条","txt":"地方各级人民政府应当加强对防洪区安全建设工作的领导，组织有关部门、单位对防洪区内的单位和居民进行防洪教育，普及防洪知识，提高水患意识；按照防洪规划和防御洪水方案建立并完善防洪体系和水文、气象、通信、预警以及洪涝灾害监测系统，提高防御洪水能力；组织防洪区内的单位和居民积极参加防洪工作，因地制宜地采取防洪避洪措施。"},{"i":32,"n":"第三十二条","txt":"洪泛区、蓄滞洪区所在地的省、自治区、直辖市人民政府应当组织有关地区和部门，按照防洪规划的要求，制定洪泛区、蓄滞洪区安全建设计划，控制蓄滞洪区人口增长，对居住在经常使用的蓄滞洪区的居民，有计划地组织外迁，并采取其他必要的安全保护措施。"},{"i":33,"n":"第三十三条","txt":"在洪泛区、蓄滞洪区内建设非防洪建设项目，应当就洪水对建设项目可能产生的影响和建设项目对防洪可能产生的影响作出评价，编制洪水影响评价报告，提出防御措施。洪水影响评价报告未经有关水行政主管部门审查批准的，建设单位不得开工建设。"},{"i":34,"n":"第三十四条","txt":"大中城市，重要的铁路、公路干线，大型骨干企业，应当列为防洪重点，确保安全。"},{"i":35,"n":"第三十五条","txt":"属于国家所有的防洪工程设施，应当按照经批准的设计，在竣工验收前由县级以上人民政府按照国家规定，划定管理和保护范围。"},{"i":36,"n":"第三十六条","txt":"各级人民政府应当组织有关部门加强对水库大坝的定期检查和监督管理。对未达到设计洪水标准、抗震设防要求或者有严重质量缺陷的险坝，大坝主管部门应当组织有关单位采取除险加固措施，限期消除危险或者重建，有关人民政府应当优先安排所需资金。对可能出现垮坝的水库，应当事先制定应急抢险和居民临时撤离方案。"},{"i":37,"n":"第三十七条","txt":"任何单位和个人不得破坏、侵占、毁损水库大坝、堤防、水闸、护岸、抽水站、排水渠系等防洪工程和水文、通信设施以及防汛备用的器材、物料等。"},{"i":38,"n":"第三十八条","txt":"防汛抗洪工作实行各级人民政府行政首长负责制，统一指挥、分级分部门负责。"},{"i":39,"n":"第三十九条","txt":"国务院设立国家防汛指挥机构，负责领导、组织全国的防汛抗洪工作，其办事机构设在国务院水行政主管部门。"},{"i":40,"n":"第四十条","txt":"有防汛抗洪任务的县级以上地方人民政府根据流域综合规划、防洪工程实际状况和国家规定的防洪标准，制定防御洪水方案（包括对特大洪水的处置措施）。"},{"i":41,"n":"第四十一条","txt":"省、自治区、直辖市人民政府防汛指挥机构根据当地的洪水规律，规定汛期起止日期。"},{"i":42,"n":"第四十二条","txt":"对河道、湖泊范围内阻碍行洪的障碍物，按照谁设障、谁清除的原则，由防汛指挥机构责令限期清除；逾期不清除的，由防汛指挥机构组织强行清除，所需费用由设障者承担。"},{"i":43,"n":"第四十三条","txt":"在汛期，气象、水文、海洋等有关部门应当按照各自的职责，及时向有关防汛指挥机构提供天气、水文等实时信息和风暴潮预报；电信部门应当优先提供防汛抗洪通信的服务；运输、电力、物资材料供应等有关部门应当优先为防汛抗洪服务。"},{"i":44,"n":"第四十四条","txt":"在汛期，水库、闸坝和其他水工程设施的运用，必须服从有关的防汛指挥机构的调度指挥和监督。"},{"i":45,"n":"第四十五条","txt":"在紧急防汛期，防汛指挥机构根据防汛抗洪的需要，有权在其管辖范围内调用物资、设备、交通运输工具和人力，决定采取取土占地、砍伐林木、清除阻水障碍物和其他必要的紧急措施；必要时，公安、交通等有关部门按照防汛指挥机构的决定，依法实施陆地和水面交通管制。"},{"i":46,"n":"第四十六条","txt":"江河、湖泊水位或者流量达到国家规定的分洪标准，需要启用蓄滞洪区时，国务院，国家防汛指挥机构，流域防汛指挥机构，省、自治区、直辖市人民政府，省、自治区、直辖市防汛指挥机构，按照依法经批准的防御洪水方案中规定的启用条件和批准程序，决定启用蓄滞洪区。依法启用蓄滞洪区，任何单位和个人不得阻拦、拖延；遇到阻拦、拖延时，由有关县级以上地方人民政府强制实施。"},{"i":47,"n":"第四十七条","txt":"发生洪涝灾害后，有关人民政府应当组织有关部门、单位做好灾区的生活供给、卫生防疫、救灾物资供应、治安管理、学校复课、恢复生产和重建家园等救灾工作以及所管辖地区的各项水毁工程设施修复工作。水毁防洪工程设施的修复，应当优先列入有关部门的年度建设计划。"},{"i":48,"n":"第四十八条","txt":"各级人民政府应当采取措施，提高防洪投入的总体水平。"},{"i":49,"n":"第四十九条","txt":"江河、湖泊的治理和防洪工程设施的建设和维护所需投资，按照事权和财权相统一的原则，分级负责，由中央和地方财政承担。城市防洪工程设施的建设和维护所需投资，由城市人民政府承担。"},{"i":50,"n":"第五十条","txt":"中央财政应当安排资金，用于国家确定的重要江河、湖泊的堤坝遭受特大洪涝灾害时的抗洪抢险和水毁防洪工程修复。省、自治区、直辖市人民政府应当在本级财政预算中安排资金，用于本行政区域内遭受特大洪涝灾害地区的抗洪抢险和水毁防洪工程修复。"},{"i":51,"n":"第五十一条","txt":"国家设立水利建设基金，用于防洪工程和水利工程的维护和建设。具体办法由国务院规定。"},{"i":52,"n":"第五十二条","txt":"任何单位和个人不得截留、挪用防洪、救灾资金和物资。"},{"i":53,"n":"第五十三条","txt":"违反本法第十七条规定，未经水行政主管部门签署规划同意书，擅自在江河、湖泊上建设防洪工程和其他水工程、水电站的，责令停止违法行为，补办规划同意书手续；违反规划同意书的要求，严重影响防洪的，责令限期拆除；违反规划同意书的要求，影响防洪但尚可采取补救措施的，责令限期采取补救措施，可以处一万元以上十万元以下的罚款。"},{"i":54,"n":"第五十四条","txt":"违反本法第十九条规定，未按照规划治导线整治河道和修建控制引导河水流向、保护堤岸等工程，影响防洪的，责令停止违法行为，恢复原状或者采取其他补救措施，可以处一万元以上十万元以下的罚款。"},{"i":55,"n":"第五十五条","txt":"违反本法第二十二条第二款、第三款规定，有下列行为之一的，责令停止违法行为，排除阻碍或者采取其他补救措施，可以处五万元以下的罚款："},{"i":56,"n":"第五十六条","txt":"违反本法第十五条第二款、第二十三条规定，围海造地、围湖造地、围垦河道的，责令停止违法行为，恢复原状或者采取其他补救措施，可以处五万元以下的罚款；既不恢复原状也不采取其他补救措施的，代为恢复原状或者采取其他补救措施，所需费用由违法者承担。"},{"i":57,"n":"第五十七条","txt":"违反本法第二十七条规定，未经水行政主管部门对其工程建设方案审查同意或者未按照有关水行政主管部门审查批准的位置、界限，在河道、湖泊管理范围内从事工程设施建设活动的，责令停止违法行为，补办审查同意或者审查批准手续；工程设施建设严重影响防洪的，责令限期拆除，逾期不拆除的，强行拆除，所需费用由建设单位承担；影响行洪但尚可采取补救措施的，责令限期采取补救措施，可以处一万元以上十万元以下的罚款。"},{"i":58,"n":"第五十八条","txt":"违反本法第三十三条第一款规定，在洪泛区、蓄滞洪区内建设非防洪建设项目，未编制洪水影响评价报告或者洪水影响评价报告未经审查批准开工建设的，责令限期改正；逾期不改正的，处五万元以下的罚款。"},{"i":59,"n":"第五十九条","txt":"违反本法第三十四条规定，因城市建设擅自填堵原有河道沟叉、贮水湖塘洼淀和废除原有防洪围堤的，城市人民政府应当责令停止违法行为，限期恢复原状或者采取其他补救措施。"},{"i":60,"n":"第六十条","txt":"违反本法规定，破坏、侵占、毁损堤防、水闸、护岸、抽水站、排水渠系等防洪工程和水文、通信设施以及防汛备用的器材、物料的，责令停止违法行为，采取补救措施，可以处五万元以下的罚款；造成损坏的，依法承担民事责任；应当给予治安管理处罚的，依照治安管理处罚法的规定处罚；构成犯罪的，依法追究刑事责任。"},{"i":61,"n":"第六十一条","txt":"阻碍、威胁防汛指挥机构、水行政主管部门或者流域管理机构的工作人员依法执行职务，构成犯罪的，依法追究刑事责任；尚不构成犯罪，应当给予治安管理处罚的，依照治安管理处罚法的规定处罚。"},{"i":62,"n":"第六十二条","txt":"截留、挪用防洪、救灾资金和物资，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，给予行政处分。"},{"i":63,"n":"第六十三条","txt":"除本法第五十九条的规定外，本章规定的行政处罚和行政措施，由县级以上人民政府水行政主管部门决定，或者由流域管理机构按照国务院水行政主管部门规定的权限决定。但是，本法第六十条、第六十一条规定的治安管理处罚的决定机关，按照治安管理处罚法的规定执行。"},{"i":64,"n":"第六十四条","txt":"国家工作人员，有下列行为之一，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，给予行政处分："},{"i":65,"n":"第六十五条","txt":"本法自1998年1月1日起施行。"}],"yusuanfa":[{"i":1,"n":"第一条","txt":"为了规范政府收支行为，强化预算约束，加强对预算的管理和监督，建立健全全面规范、公开透明的预算制度，保障经济社会的健康发展，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"预算、决算的编制、审查、批准、监督，以及预算的执行和调整，依照本法规定执行。"},{"i":3,"n":"第三条","txt":"国家实行一级政府一级预算，设立中央，省、自治区、直辖市，设区的市、自治州，县、自治县、不设区的市、市辖区，乡、民族乡、镇五级预算。"},{"i":4,"n":"第四条","txt":"预算由预算收入和预算支出组成。"},{"i":5,"n":"第五条","txt":"预算包括一般公共预算、政府性基金预算、国有资本经营预算、社会保险基金预算。"},{"i":6,"n":"第六条","txt":"一般公共预算是对以税收为主体的财政收入，安排用于保障和改善民生、推动经济社会发展、维护国家安全、维持国家机构正常运转等方面的收支预算。"},{"i":7,"n":"第七条","txt":"地方各级一般公共预算包括本级各部门（含直属单位，下同）的预算和税收返还、转移支付预算。"},{"i":8,"n":"第八条","txt":"各部门预算由本部门及其所属各单位预算组成。"},{"i":9,"n":"第九条","txt":"政府性基金预算是对依照法律、行政法规的规定在一定期限内向特定对象征收、收取或者以其他方式筹集的资金，专项用于特定公共事业发展的收支预算。"},{"i":10,"n":"第十条","txt":"国有资本经营预算是对国有资本收益作出支出安排的收支预算。"},{"i":11,"n":"第十一条","txt":"社会保险基金预算是对社会保险缴款、一般公共预算安排和其他方式筹集的资金，专项用于社会保险的收支预算。"},{"i":12,"n":"第十二条","txt":"各级预算应当遵循统筹兼顾、勤俭节约、量力而行、讲求绩效和收支平衡的原则。"},{"i":13,"n":"第十三条","txt":"经人民代表大会批准的预算，非经法定程序，不得调整。各级政府、各部门、各单位的支出必须以经批准的预算为依据，未列入预算的不得支出。"},{"i":14,"n":"第十四条","txt":"经本级人民代表大会或者本级人民代表大会常务委员会批准的预算、预算调整、决算、预算执行情况的报告及报表，应当在批准后二十日内由本级政府财政部门向社会公开，并对本级政府财政转移支付安排、执行的情况以及举借债务的情况等重要事项作出说明。"},{"i":15,"n":"第十五条","txt":"国家实行中央和地方分税制。"},{"i":16,"n":"第十六条","txt":"国家实行财政转移支付制度。财政转移支付应当规范、公平、公开，以推进地区间基本公共服务均等化为主要目标。"},{"i":17,"n":"第十七条","txt":"各级预算的编制、执行应当建立健全相互制约、相互协调的机制。"},{"i":18,"n":"第十八条","txt":"预算年度自公历一月一日起，至十二月三十一日止。"},{"i":19,"n":"第十九条","txt":"预算收入和预算支出以人民币元为计算单位。"},{"i":20,"n":"第二十条","txt":"全国人民代表大会审查中央和地方预算草案及中央和地方预算执行情况的报告；批准中央预算和中央预算执行情况的报告；改变或者撤销全国人民代表大会常务委员会关于预算、决算的不适当的决议。"},{"i":21,"n":"第二十一条","txt":"县级以上地方各级人民代表大会审查本级总预算草案及本级总预算执行情况的报告；批准本级预算和本级预算执行情况的报告；改变或者撤销本级人民代表大会常务委员会关于预算、决算的不适当的决议；撤销本级政府关于预算、决算的不适当的决定和命令。"},{"i":22,"n":"第二十二条","txt":"全国人民代表大会财政经济委员会对中央预算草案初步方案及上一年预算执行情况、中央预算调整初步方案和中央决算草案进行初步审查，提出初步审查意见。"},{"i":23,"n":"第二十三条","txt":"国务院编制中央预算、决算草案；向全国人民代表大会作关于中央和地方预算草案的报告；将省、自治区、直辖市政府报送备案的预算汇总后报全国人民代表大会常务委员会备案；组织中央和地方预算的执行；决定中央预算预备费的动用；编制中央预算调整方案；监督中央各部门和地方政府的预算执行；改变或者撤销中央各部门和地方政府关于预算、决算的不适当的决定、命令；向全国人民代表大会、全国人民代表大会常务委员会报告中央和地方预算的执行情况。"},{"i":24,"n":"第二十四条","txt":"县级以上地方各级政府编制本级预算、决算草案；向本级人民代表大会作关于本级总预算草案的报告；将下一级政府报送备案的预算汇总后报本级人民代表大会常务委员会备案；组织本级总预算的执行；决定本级预算预备费的动用；编制本级预算的调整方案；监督本级各部门和下级政府的预算执行；改变或者撤销本级各部门和下级政府关于预算、决算的不适当的决定、命令；向本级人民代表大会、本级人民代表大会常务委员会报告本级总预算的执行情况。"},{"i":25,"n":"第二十五条","txt":"国务院财政部门具体编制中央预算、决算草案；具体组织中央和地方预算的执行；提出中央预算预备费动用方案；具体编制中央预算的调整方案；定期向国务院报告中央和地方预算的执行情况。"},{"i":26,"n":"第二十六条","txt":"各部门编制本部门预算、决算草案；组织和监督本部门预算的执行；定期向本级政府财政部门报告预算的执行情况。"},{"i":27,"n":"第二十七条","txt":"一般公共预算收入包括各项税收收入、行政事业性收费收入、国有资源（资产）有偿使用收入、转移性收入和其他收入。"},{"i":28,"n":"第二十八条","txt":"政府性基金预算、国有资本经营预算和社会保险基金预算的收支范围，按照法律、行政法规和国务院的规定执行。"},{"i":29,"n":"第二十九条","txt":"中央预算与地方预算有关收入和支出项目的划分、地方向中央上解收入、中央对地方税收返还或者转移支付的具体办法，由国务院规定，报全国人民代表大会常务委员会备案。"},{"i":30,"n":"第三十条","txt":"上级政府不得在预算之外调用下级政府预算的资金。下级政府不得挤占或者截留属于上级政府预算的资金。"},{"i":31,"n":"第三十一条","txt":"国务院应当及时下达关于编制下一年预算草案的通知。编制预算草案的具体事项由国务院财政部门部署。"},{"i":32,"n":"第三十二条","txt":"各级预算应当根据年度经济社会发展目标、国家宏观调控总体要求和跨年度预算平衡的需要，参考上一年预算执行情况、有关支出绩效评价结果和本年度收支预测，按照规定程序征求各方面意见后，进行编制。"},{"i":33,"n":"第三十三条","txt":"省、自治区、直辖市政府应当按照国务院规定的时间，将本级总预算草案报国务院审核汇总。"},{"i":34,"n":"第三十四条","txt":"中央一般公共预算中必需的部分资金，可以通过举借国内和国外债务等方式筹措，举借债务应当控制适当的规模，保持合理的结构。"},{"i":35,"n":"第三十五条","txt":"地方各级预算按照量入为出、收支平衡的原则编制，除本法另有规定外，不列赤字。"},{"i":36,"n":"第三十六条","txt":"各级预算收入的编制，应当与经济社会发展水平相适应，与财政政策相衔接。"},{"i":37,"n":"第三十七条","txt":"各级预算支出应当依照本法规定，按其功能和经济性质分类编制。"},{"i":38,"n":"第三十八条","txt":"一般性转移支付应当按照国务院规定的基本标准和计算方法编制。专项转移支付应当分地区、分项目编制。"},{"i":39,"n":"第三十九条","txt":"中央预算和有关地方预算中应当安排必要的资金，用于扶助革命老区、民族地区、边疆地区、贫困地区发展经济社会建设事业。"},{"i":40,"n":"第四十条","txt":"各级一般公共预算应当按照本级一般公共预算支出额的百分之一至百分之三设置预备费，用于当年预算执行中的自然灾害等突发事件处理增加的支出及其他难以预见的开支。"},{"i":41,"n":"第四十一条","txt":"各级一般公共预算按照国务院的规定可以设置预算周转金，用于本级政府调剂预算年度内季节性收支差额。"},{"i":42,"n":"第四十二条","txt":"各级政府上一年预算的结转资金，应当在下一年用于结转项目的支出；连续两年未用完的结转资金，应当作为结余资金管理。"},{"i":43,"n":"第四十三条","txt":"中央预算由全国人民代表大会审查和批准。"},{"i":44,"n":"第四十四条","txt":"国务院财政部门应当在每年全国人民代表大会会议举行的四十五日前，将中央预算草案的初步方案提交全国人民代表大会财政经济委员会进行初步审查。"},{"i":45,"n":"第四十五条","txt":"县、自治县、不设区的市、市辖区、乡、民族乡、镇的人民代表大会举行会议审查预算草案前，应当采用多种形式，组织本级人民代表大会代表，听取选民和社会各界的意见。"},{"i":46,"n":"第四十六条","txt":"报送各级人民代表大会审查和批准的预算草案应当细化。本级一般公共预算支出，按其功能分类应当编列到项；按其经济性质分类，基本支出应当编列到款。本级政府性基金预算、国有资本经营预算、社会保险基金预算支出，按其功能分类应当编列到项。"},{"i":47,"n":"第四十七条","txt":"国务院在全国人民代表大会举行会议时，向大会作关于中央和地方预算草案以及中央和地方预算执行情况的报告。"},{"i":48,"n":"第四十八条","txt":"全国人民代表大会和地方各级人民代表大会对预算草案及其报告、预算执行情况的报告重点审查下列内容："},{"i":49,"n":"第四十九条","txt":"全国人民代表大会财政经济委员会向全国人民代表大会主席团提出关于中央和地方预算草案及中央和地方预算执行情况的审查结果报告。"},{"i":50,"n":"第五十条","txt":"乡、民族乡、镇政府应当及时将经本级人民代表大会批准的本级预算报上一级政府备案。县级以上地方各级政府应当及时将经本级人民代表大会批准的本级预算及下一级政府报送备案的预算汇总，报上一级政府备案。"},{"i":51,"n":"第五十一条","txt":"国务院和县级以上地方各级政府对下一级政府依照本法第五十条规定报送备案的预算，认为有同法律、行政法规相抵触或者有其他不适当之处，需要撤销批准预算的决议的，应当提请本级人民代表大会常务委员会审议决定。"},{"i":52,"n":"第五十二条","txt":"各级预算经本级人民代表大会批准后，本级政府财政部门应当在二十日内向本级各部门批复预算。各部门应当在接到本级政府财政部门批复的本部门预算后十五日内向所属各单位批复预算。"},{"i":53,"n":"第五十三条","txt":"各级预算由本级政府组织执行，具体工作由本级政府财政部门负责。"},{"i":54,"n":"第五十四条","txt":"预算年度开始后，各级预算草案在本级人民代表大会批准前，可以安排下列支出："},{"i":55,"n":"第五十五条","txt":"预算收入征收部门和单位，必须依照法律、行政法规的规定，及时、足额征收应征的预算收入。不得违反法律、行政法规规定，多征、提前征收或者减征、免征、缓征应征的预算收入，不得截留、占用或者挪用预算收入。"},{"i":56,"n":"第五十六条","txt":"政府的全部收入应当上缴国家金库（以下简称国库），任何部门、单位和个人不得截留、占用、挪用或者拖欠。"},{"i":57,"n":"第五十七条","txt":"各级政府财政部门必须依照法律、行政法规和国务院财政部门的规定，及时、足额地拨付预算支出资金，加强对预算支出的管理和监督。"},{"i":58,"n":"第五十八条","txt":"各级预算的收入和支出实行收付实现制。"},{"i":59,"n":"第五十九条","txt":"县级以上各级预算必须设立国库；具备条件的乡、民族乡、镇也应当设立国库。"},{"i":60,"n":"第六十条","txt":"已经缴入国库的资金，依照法律、行政法规的规定或者国务院的决定需要退付的，各级政府财政部门或者其授权的机构应当及时办理退付。按照规定应当由财政支出安排的事项，不得用退库处理。"},{"i":61,"n":"第六十一条","txt":"国家实行国库集中收缴和集中支付制度，对政府全部收入和支出实行国库集中收付管理。"},{"i":62,"n":"第六十二条","txt":"各级政府应当加强对预算执行的领导，支持政府财政、税务、海关等预算收入的征收部门依法组织预算收入，支持政府财政部门严格管理预算支出。"},{"i":63,"n":"第六十三条","txt":"各部门、各单位应当加强对预算收入和支出的管理，不得截留或者动用应当上缴的预算收入，不得擅自改变预算支出的用途。"},{"i":64,"n":"第六十四条","txt":"各级预算预备费的动用方案，由本级政府财政部门提出，报本级政府决定。"},{"i":65,"n":"第六十五条","txt":"各级预算周转金由本级政府财政部门管理，不得挪作他用。"},{"i":66,"n":"第六十六条","txt":"各级一般公共预算年度执行中有超收收入的，只能用于冲减赤字或者补充预算稳定调节基金。"},{"i":67,"n":"第六十七条","txt":"经全国人民代表大会批准的中央预算和经地方各级人民代表大会批准的地方各级预算，在执行中出现下列情况之一的，应当进行预算调整："},{"i":68,"n":"第六十八条","txt":"在预算执行中，各级政府一般不制定新的增加财政收入或者支出的政策和措施，也不制定减少财政收入的政策和措施；必须作出并需要进行预算调整的，应当在预算调整方案中作出安排。"},{"i":69,"n":"第六十九条","txt":"在预算执行中，各级政府对于必须进行的预算调整，应当编制预算调整方案。预算调整方案应当说明预算调整的理由、项目和数额。"},{"i":70,"n":"第七十条","txt":"经批准的预算调整方案，各级政府应当严格执行。未经本法第六十九条规定的程序，各级政府不得作出预算调整的决定。"},{"i":71,"n":"第七十一条","txt":"在预算执行中，地方各级政府因上级政府增加不需要本级政府提供配套资金的专项转移支付而引起的预算支出变化，不属于预算调整。"},{"i":72,"n":"第七十二条","txt":"各部门、各单位的预算支出应当按照预算科目执行。严格控制不同预算科目、预算级次或者项目间的预算资金的调剂，确需调剂使用的，按照国务院财政部门的规定办理。"},{"i":73,"n":"第七十三条","txt":"地方各级预算的调整方案经批准后，由本级政府报上一级政府备案。"},{"i":74,"n":"第七十四条","txt":"决算草案由各级政府、各部门、各单位，在每一预算年度终了后按照国务院规定的时间编制。"},{"i":75,"n":"第七十五条","txt":"编制决算草案，必须符合法律、行政法规，做到收支真实、数额准确、内容完整、报送及时。"},{"i":76,"n":"第七十六条","txt":"各部门对所属各单位的决算草案，应当审核并汇总编制本部门的决算草案，在规定的期限内报本级政府财政部门审核。"},{"i":77,"n":"第七十七条","txt":"国务院财政部门编制中央决算草案，经国务院审计部门审计后，报国务院审定，由国务院提请全国人民代表大会常务委员会审查和批准。"},{"i":78,"n":"第七十八条","txt":"国务院财政部门应当在全国人民代表大会常务委员会举行会议审查和批准中央决算草案的三十日前，将上一年度中央决算草案提交全国人民代表大会财政经济委员会进行初步审查。"},{"i":79,"n":"第七十九条","txt":"县级以上各级人民代表大会常务委员会和乡、民族乡、镇人民代表大会对本级决算草案，重点审查下列内容："},{"i":80,"n":"第八十条","txt":"各级决算经批准后，财政部门应当在二十日内向本级各部门批复决算。各部门应当在接到本级政府财政部门批复的本部门决算后十五日内向所属单位批复决算。"},{"i":81,"n":"第八十一条","txt":"地方各级政府应当将经批准的决算及下一级政府上报备案的决算汇总，报上一级政府备案。"},{"i":82,"n":"第八十二条","txt":"国务院和县级以上地方各级政府对下一级政府依照本法第八十一条规定报送备案的决算，认为有同法律、行政法规相抵触或者有其他不适当之处，需要撤销批准该项决算的决议的，应当提请本级人民代表大会常务委员会审议决定；经审议决定撤销的，该下级人民代表大会常务委员会应当责成本级政府依照本法规定重新编制决算草案，提请本级人民代表大会常务委员会审查和批准。"},{"i":83,"n":"第八十三条","txt":"全国人民代表大会及其常务委员会对中央和地方预算、决算进行监督。"},{"i":84,"n":"第八十四条","txt":"各级人民代表大会和县级以上各级人民代表大会常务委员会有权就预算、决算中的重大事项或者特定问题组织调查，有关的政府、部门、单位和个人应当如实反映情况和提供必要的材料。"},{"i":85,"n":"第八十五条","txt":"各级人民代表大会和县级以上各级人民代表大会常务委员会举行会议时，人民代表大会代表或者常务委员会组成人员，依照法律规定程序就预算、决算中的有关问题提出询问或者质询，受询问或者受质询的有关的政府或者财政部门必须及时给予答复。"},{"i":86,"n":"第八十六条","txt":"国务院和县级以上地方各级政府应当在每年六月至九月期间向本级人民代表大会常务委员会报告预算执行情况。"},{"i":87,"n":"第八十七条","txt":"各级政府监督下级政府的预算执行；下级政府应当定期向上一级政府报告预算执行情况。"},{"i":88,"n":"第八十八条","txt":"各级政府财政部门负责监督本级各部门及其所属各单位预算管理有关工作，并向本级政府和上一级政府财政部门报告预算执行情况。"},{"i":89,"n":"第八十九条","txt":"县级以上政府审计部门依法对预算执行、决算实行审计监督。"},{"i":90,"n":"第九十条","txt":"政府各部门负责监督检查所属各单位的预算执行，及时向本级政府财政部门反映本部门预算执行情况，依法纠正违反预算的行为。"},{"i":91,"n":"第九十一条","txt":"公民、法人或者其他组织发现有违反本法的行为，可以依法向有关国家机关进行检举、控告。"},{"i":92,"n":"第九十二条","txt":"各级政府及有关部门有下列行为之一的，责令改正，对负有直接责任的主管人员和其他直接责任人员追究行政责任："},{"i":93,"n":"第九十三条","txt":"各级政府及有关部门、单位有下列行为之一的，责令改正，对负有直接责任的主管人员和其他直接责任人员依法给予降级、撤职、开除的处分："},{"i":94,"n":"第九十四条","txt":"各级政府、各部门、各单位违反本法规定举借债务或者为他人债务提供担保，或者挪用重点支出资金，或者在预算之外及超预算标准建设楼堂馆所的，责令改正，对负有直接责任的主管人员和其他直接责任人员给予撤职、开除的处分。"},{"i":95,"n":"第九十五条","txt":"各级政府有关部门、单位及其工作人员有下列行为之一的，责令改正，追回骗取、使用的资金，有违法所得的没收违法所得，对单位给予警告或者通报批评；对负有直接责任的主管人员和其他直接责任人员依法给予处分："},{"i":96,"n":"第九十六条","txt":"本法第九十二条、第九十三条、第九十四条、第九十五条所列违法行为，其他法律对其处理、处罚另有规定的，依照其规定。"},{"i":97,"n":"第九十七条","txt":"各级政府财政部门应当按年度编制以权责发生制为基础的政府综合财务报告，报告政府整体财务状况、运行情况和财政中长期可持续性，报本级人民代表大会常务委员会备案。"},{"i":98,"n":"第九十八条","txt":"国务院根据本法制定实施条例。"},{"i":99,"n":"第九十九条","txt":"民族自治地方的预算管理，依照民族区域自治法的有关规定执行；民族区域自治法没有规定的，依照本法和国务院的有关规定执行。"},{"i":100,"n":"第一百条","txt":"省、自治区、直辖市人民代表大会或者其常务委员会根据本法，可以制定有关预算审查监督的决定或者地方性法规。"},{"i":101,"n":"第一百零一条","txt":"本法自1995年1月1日起施行。1991年10月21日国务院发布的《国家预算管理条例》同时废止。"}],"diwujiequanguorenmindaibiaodahuichangwuweiyuanhuig8c3904":[{"i":1,"n":"第一条","txt":"为发展对外经济合作和技术交流，促进社会主义现代化建设，在广东省深圳、珠海、汕头三市分别划出一定区域，设置经济特区（以下简称特区）。特区鼓励外国公民、华侨、港澳同胞及其公司、企业（以下简称客商），投资设厂或者与我方合资设厂，兴办企业和其他事业，并依法保护其资产、应得利润和其他合法权益。"},{"i":2,"n":"第二条","txt":"特区内的企业和个人，必须遵守中华人民共和国的法律、法令和有关规定。本条例有特别规定的，按照本条例的规定执行。"},{"i":3,"n":"第三条","txt":"设立广东省经济特区管理委员会，代表广东省人民政府对各特区实行统一管理。"},{"i":4,"n":"第四条","txt":"特区为客商提供广阔的经营范围，创造良好的经营条件，保证稳定的经营场所。一切在国际经济合作和技术交流中具有积极意义的工业、农业、畜牧业、养殖业、旅游业、住宅和建筑业、高级技术研究制造业，以及客商与我方共同感兴趣的其他行业，都可以投资兴办或者与我方合资兴办。"},{"i":5,"n":"第五条","txt":"特区的土地平整工程和供水、排水、供电、道路、码头、通讯、仓储等各项公共设施，由广东省经济特区管理委员会负责兴建，必要时也可以吸收外资参与兴建。"},{"i":6,"n":"第六条","txt":"各特区分别聘请国内外专家和热心我国现代化建设的有关人士组成顾问委员会，作为该特区的咨询机构。"},{"i":7,"n":"第七条","txt":"客商在特区投资设厂，兴办各项经济事业，应向广东省经济特区管理委员会提出申请，经审核、批准后，发给注册证书和土地使用证书。"},{"i":8,"n":"第八条","txt":"客商可在特区内设立的中国银行或者其他经我方批准设立的银行开户，并办理有关外汇事宜。"},{"i":9,"n":"第九条","txt":"特区企业的产品供国际市场销售；其产品如向我国内地销售，须经广东省经济特区管理委员会核准，并办理海关补税手续。"},{"i":10,"n":"第十条","txt":"客商在特区内可以独立经营自己的企业，雇用外籍人员担任技术和管理工作。"},{"i":11,"n":"第十一条","txt":"客商在特区所办的企业中途停业，应向广东省经济特区管理委员会申报理由，办理停业手续，清理债权债务；停业后，其资产可转让，资金可汇出。"},{"i":12,"n":"第十二条","txt":"特区的土地为中华人民共和国所有。客商用地，按实际需要提供，其使用年限、使用费数额和缴纳办法，根据不同行业和用途，给予优惠，具体办法另行规定。"},{"i":13,"n":"第十三条","txt":"特区企业进口生产所必需的机器设备、零配件、原材料、运输工具和其他生产资料，免征进口税；对必需的生活用品、可以根据具体情况、分别征税或者减免进口税。上述物品进口和特区产品出口时，均应向海关办理申报手续。"},{"i":14,"n":"第十四条","txt":"特区企业所得税税率为百分之十五。对在本条例公布后两年内投资兴办的企业，或者投资额达五百万美元以上的企业，或者技术性较高、资金周转期较长的企业，给予特别优惠待遇。"},{"i":15,"n":"第十五条","txt":"客商在缴纳企业所得税后所得的合法利润，特区企业的外籍职工、华侨职工、港澳职工在缴纳个人所得税后的工资和其他正当收入，可以按照特区外汇管理办法的规定，通过特区内的中国银行或者其他银行汇出。"},{"i":16,"n":"第十六条","txt":"客商将所得利润用于在特区内进行再投资为期五年以上者，可申请减免用于再投资部分的所得税。"},{"i":17,"n":"第十七条","txt":"鼓励特区企业采用我国生产的机器设备、原材料和其他物资，其价格可按我国当时同类商品的出口价格给予优惠，以外汇结算。这些产品和物资，可凭售货单位的销售凭证直接运往特区。"},{"i":18,"n":"第十八条","txt":"凡来往特区的外籍人员、华侨和港澳同胞，出入境均简化手续，给予方便。"},{"i":19,"n":"第十九条","txt":"各特区设立劳动服务公司。特区企业雇用中国职员和工人，或者由当地劳动服务公司介绍，或者经广东省经济特区管理委员会同意由客商自行招聘，都由企业考核录用，同职工签订劳动合同。"},{"i":20,"n":"第二十条","txt":"特区企业雇用的职工，由该企业按其经营的要求进行管理，必要时可以解雇，其手续按照劳动合同的规定办理。"},{"i":21,"n":"第二十一条","txt":"特区企业中的中国职工工资水平、工资形式、奖励办法，以及劳动保险、国家对职工的各项补贴，按照广东省经济特区管理委员会的规定，由企业同职工签订合同。"},{"i":22,"n":"第二十二条","txt":"特区企业应有必要的劳动保护措施，保证职工在安全、卫生的条件下进行工作。"},{"i":23,"n":"第二十三条","txt":"广东省经济特区管理委员会行使以下职权："},{"i":24,"n":"第二十四条","txt":"深圳特区由广东省经济特区管理委员会直接经营管理；珠海、汕头特区设立必要的办事机构。"},{"i":25,"n":"第二十五条","txt":"为适应特区经济活动的开展，设立广东省经济特区发展公司。公司业务范围：承办资金筹集和信托投资业务；经营或者与客商合资经营特区的有关企业；代理特区客商与内地贸易往来的购销事宜，并提供洽商服务。"},{"i":26,"n":"第二十六条","txt":"本条例由广东省人民代表大会通过，并报中华人民共和国全国人民代表大会常务委员会批准后施行。"}]};
